@dataclass(frozen=True)
class Bar:
    timestamp: datetime
    open: float
    high: float
    low: float
    close: float
    volume: float


@dataclass(frozen=True)
class SourceSignal:
    ticker: str
    source: SourceName
    action: Action
    reason: str
    decision_price: float = 0.0
    previous_close: float = 0.0
    lookback_price: float = 0.0
    price_vs_previous_close_pct: float = 0.0
    intraday_trend_pct: float = 0.0
    drop_vs_previous_close_pct: float = 0.0
    buy_multiplier: float = 0.0
    # Mirrors ReconciledDecision.ladder_multiplier -- see that field's own
    # docstring. Carried on the per-source signal so reconcile_signals()
    # can copy it, from whichever signal wins, onto the merged decision.
    ladder_multiplier: float = 0.0
    suggested_amount_usd: float = 0.0
    # Prior regular-session low and the first-allocation base scale selected from
    # it (see StrategyConfig.base_buy_amount_below_close_usd and
    # select_first_allocation_base_usd). base_selection_reason records which branch
    # was taken. suggested_amount_usd == selected_base_amount_usd * buy_multiplier.
    previous_low: float = 0.0
    selected_base_amount_usd: float = 0.0
    base_selection_reason: str = ""
    decision_bar_timestamp: Optional[datetime] = None
    previous_close_timestamp: Optional[datetime] = None
    lookback_bar_timestamp: Optional[datetime] = None
    # Signal-time quote is the intended target price for execution. It defaults to
    # the completed decision-bar close but a provider may supply a distinct
    # last-trade/quote captured at signal time via get_quote(). decision_bar_close
    # is always the completed regular-session bar close, retained separately.
    quote_price: float = 0.0
    quote_time: Optional[datetime] = None
    decision_bar_close: float = 0.0
    # True when this signal stands in for a provider exception rather than a
    # genuine "no data" answer. Reconciliation must never auto-buy past it.
    provider_error: bool = False


@dataclass(frozen=True)
class ReconciledDecision:
    ticker: str
    action: Action
    reason: str
    finance_signal: Optional[SourceSignal]
    robinhood_signal: Optional[SourceSignal]
    buy_multiplier: float = 0.0
    # The graded ladder's OWN tier match -- before the ML sizing nudge, the
    # 5x cap, or the kill-switch cap that buy_multiplier already reflects.
    # Exists specifically so the high_multiplier_threshold selloff-breadth
    # count (how many tickers are showing a genuinely deep, ladder-severity
    # dip this run -- see select_budget_tier's own docstring) is judged on
    # the ladder's real classification, not on a per-ticker ML nudge. Without
    # this distinction, an ML factor moving several tickers' FINAL
    # multipliers across the threshold (e.g. six 2.5x ladder matches each
    # nudged to 3.0x by a 1.2 factor) would escalate the day's budget caps
    # purely from independent per-ticker forecasts, not from an actual
    # broad market selloff -- and a factor below 1.0 could just as easily
    # suppress a genuine broad-selloff signal from being counted at all
    # (Codex review: "Preserve the raw ladder tier for selloff-breadth
    # counting"). Defaults to 0.0 (matching buy_multiplier's own default)
    # for every decision that never goes through raw_ladder_multiplier() --
    # a synthetic (inverse-Martingale fire / credit-flush) candidate's
    # buy_multiplier is likewise always 0.0 or explicitly set, so the two
    # fields never legitimately diverge outside the one real ladder-signal
    # construction site.
    ladder_multiplier: float = 0.0
    suggested_amount_usd: float = 0.0
    # The first-allocation base ($1 or $2) behind suggested_amount_usd (see
    # select_first_allocation_base_usd). Persisted so a later same-day top-up
    # guard call can reuse THIS run's base instead of recomputing one from its
    # own (possibly lower) price -- see evaluate_top_up_guard.
    selected_base_amount_usd: float = 0.0
    # Execution target derived from the source that drives the buy. target_price is
    # the signal-time quote by default; decision_bar_close is retained separately.
    target_price: float = 0.0
    target_price_source: str = ""
    target_quote_time: Optional[datetime] = None
    decision_bar_close: float = 0.0
    # "" for every ordinary signal-derived decision. Set to
    # "inverse_martingale" only for a synthetic fire candidate injected by the
    # opt-in accumulator (see dca_inverse_martingale.py and _run_once_impl's
    # injection site) so _process_buy_candidate's ref_id construction can
    # namespace it distinctly from a normal ladder buy.
    synthetic_source: str = ""


# 2:30 PM ET boundary. Morning/manual (market-open recovery and future morning
# session) runs happen before this time; the scheduled afternoon run happens after
# it. Orders from before this boundary may be read ONLY as prior-allocation context
# for the same-day top-up guard -- never as scheduled afternoon execution evidence,
# slippage, watchdog confirmation, scheduled cost basis, or scheduled fill counts.
MORNING_MANUAL_BOUNDARY_ET = time(14, 30)

# Sentinel used when a prior run has no parseable generated_at timestamp. It sorts
# before every real timestamp so that, among untimestamped runs, later scan/merge
# order (paths are scanned in ascending sorted order) still wins the reference.
_TS_FLOOR = datetime.min.replace(tzinfo=timezone.utc)

# top_up_guard_result values recorded per candidate on the scheduled afternoon run.
TOP_UP_NO_PRIOR_RUN = "no_prior_run"  # normal allocation; nothing bought earlier today
TOP_UP_INCREMENTAL = "incremental_top_up"  # buy only the incremental dollar difference
# Legacy morning/midday-guard-only codes (scripts.run_classification.incremental_top_up_amount
# and morning_dca.py's own guard still emit these for their own sessions). The scheduled
# afternoon guard (evaluate_top_up_guard below) uses the unified canonical code instead --
# see TOP_UP_NOT_LOWER_OR_NO_DELTA.
TOP_UP_PRICE_NOT_BELOW = (
    "price_not_below_prior_run"  # afternoon price >= prior ref -> $0
)
TOP_UP_NO_INCREMENTAL = (
    "no_incremental_difference"  # afternoon desired <= prior amount -> $0
)
# Canonical rule item 12 (config/scheduled_tasks.json canonical_first_buy_and_topup_rule):
# the scheduled afternoon guard (evaluate_top_up_guard) emits this single unified code
# whenever a same-day top-up is skipped because the price is not strictly lower than the
# ticker's same-day reference, OR the recomputed corrected_delta_usd is 0 -- replacing the
# two legacy codes above for that guard specifically.
TOP_UP_NOT_LOWER_OR_NO_DELTA = (
    "same_day_topup_not_lower_or_no_delta"  # afternoon price not lower or delta 0 -> $0
)
TOP_UP_MISSING_PRIOR_PRICE = (
    "missing_prior_price"  # prior amount known but no ref price -> $0 (manual review)
)
TOP_UP_MISSING_PRIOR_BASE = "missing_prior_base"  # prior amount known but no resolved base -> $0 (manual review)


@dataclass(frozen=True)
class PriorSameDayAllocation:
    """Allocation already bought for a ticker by an earlier same-day (morning/manual) run.

    Read as prior-allocation context ONLY by the scheduled afternoon top-up guard;
    these runs are never counted as scheduled evidence/metrics. ``reference_price`` is
    the earlier run's decision/fill/target price for the ticker (None when the earlier
    artifact recorded an amount but no usable price).
    """

    ticker: str
    amount_usd: float = 0.0
    reference_price: Optional[float] = None
    run_id: Optional[str] = None
    source: Optional[str] = None
    # The contributing run's generated_at, parsed, for the run that established
    # reference_price -- so merging allocations from different roots/streams can
    # pick the ticker's MOST RECENT valid same-day reference (canonical rule item
    # 9) rather than the lowest. None when unresolved/unavailable.
    reference_ts: Optional[datetime] = None
    # The first same-day allocation's selected_base_amount_usd ($1 or $2), when the
    # contributing artifact recorded one. None for older artifacts that predate this
    # field, or when it could not be resolved -- never treat that as $0. A caller with
    # a known prior amount_usd but this still None must fail closed (bounded reload,
    # then manual review) rather than silently recompute the base from the current
    # run's own price (Codex review: "Fail closed when the first allocation base is
    # unknown"); see run_dca._tickers_with_unresolved_same_day_context and
    # near_close_dca.evaluate_top_up_guard / morning_dca._evaluate_top_up.
    selected_base_amount_usd: Optional[float] = None
    # The contributing run's generated_at (ISO string) that established
    # selected_base_amount_usd, so merging allocations from different roots/streams
    # (e.g. run_dca.py's afternoon-root + cross-stream-root merge) can pick the
    # chronologically FIRST allocation's base rather than whichever root happened
    # to be merged first. None when unresolved/unavailable.
    selected_base_amount_usd_at: Optional[str] = None
    # Count of genuine prior-run buy ATTEMPTS this allocation was built from,
    # including zero-capital ones (a candidate that obtained an order_id but
    # was later confirmed rejected/canceled, or a placement that raised) --
    # NOT derived from amount_usd being positive. config/budgets.json's
    # max_orders_per_day circuit breaker is defined as a count of attempts
    # shared across all seven roster slots, and "a cancelled or rejected buy
    # still consumes one -- the conservative direction"; collapsing multiple
    # attempts into one dollar total (amount_usd) must not also collapse them
    # into one attempt when this is used to reconstruct state after a process
    # restart (Codex review: "Count every prior buy attempt toward the daily
    # limit"). Defaults to 1 so any other/older construction site still
    # represents "at least one contributing attempt" rather than zero.
    attempt_count: int = 1
    # True when amount_usd is (wholly or partly) the fail-closed
    # UNRECONSTRUCTABLE-SUBMISSION SENTINEL estimate, not a reconstructed
    # real figure -- set only at the sites in load_prior_same_day_
    # allocations() that also append to unreconstructable_sink. Distinct
    # from reference_price being None: an ordinary "submitted"/
    # "unconfirmed" allocation with a genuine, fully-reconstructed dollar
    # amount but simply no fill price yet ALSO has reference_price=None,
    # and conflating the two made a caller's "is this ticker still
    # uncertain" check (run_dca.py's bounded-reload merge) treat a cleanly
    # resolved allocation as if it still carried the sentinel estimate,
    # forcing the shared weekly cap closed over uncertainty that no longer
    # exists (Codex review: "Track unknown notionals separately from
    # missing prices"). dataclasses.replace() preserves this field
    # unless a caller explicitly overrides it, so every existing
    # ``_dc.replace(existing, reference_price=None, ...)`` poisoning call
    # that poisons the REFERENCE for an unrelated reason (an incomplete
    # reload, a swapped/conflicting corroboration) correctly leaves it
    # untouched.
    notional_uncertain: bool = False
    # Every run_id that contributed dollars to amount_usd within a SINGLE
    # root's scan (load_prior_same_day_allocations), not just the latest one
    # (unlike run_id above, which is overwritten to whichever run was
    # scanned last for auditability). Lets load_prior_same_day_allocations_
    # multi() recognize when a later root's contribution for this ticker is
    # a COMPLETE duplicate of evidence an earlier root already counted --
    # e.g. a manual override backfilled under both midday_dca/manual_reruns
    # and ce16ba6b/manual_runs -- and skip re-summing it, rather than
    # recording twice the real spend (Codex review: "Deduplicate mirrored
    # artifacts before pooling spend"). Empty by default for any
    # older/direct construction site, which correctly disables dedup for
    # allocations with no known contributing run_id rather than falsely
    # treating them as a match.
    contributing_run_ids: frozenset = field(default_factory=frozenset)
    # Every order_id (or whole_share_order_ids entry) actually REPRESENTED by
    # a row that contributed dollars to amount_usd -- finer-grained than
    # contributing_run_ids, which only records the ARTIFACT/run a
    # contribution came from. A single mutable run_state.json can expose
    # multiple distinct same-ticker orders under one run_id across two scans
    # (see load_prior_same_day_allocations' own attempt-counting comment on
    # aggregate rows), so an equal contributing_run_ids set between two
    # passes does not prove the SAME order was reconstructed both times --
    # only order-level identity does (Codex review: "Match order-level
    # provenance before clearing uncertainty"). Empty by default for any
    # older/direct construction site or a row with no known order_id,
    # correctly disabling order-level matching rather than falsely treating
    # an unknown identity as a match.
    contributing_order_ids: frozenset = field(default_factory=frozenset)
    # Synthetic (non-broker) identity for every id-LESS contribution --
    # e.g. an unreconstructable_submitted_tickers sentinel, or a candidate
    # row with no order_id/whole_share_order_ids at all (empty
    # `_represented` in load_prior_same_day_allocations). Those
    # contributions never enter contributing_order_ids (there is no real
    # order_id to record), so a subset/equality check on contributing_
    # order_ids ALONE cannot tell "the same anonymous contributor was
    # re-observed" apart from "a different, unrelated contributor happened
    # to make the known-order sets line up" -- e.g. a first scan combining
    # one known order with one id-less uncertain candidate, followed by a
    # cleaner reload that swaps in a DIFFERENT known order while never
    # re-observing the uncertain one: the known-order subset still holds,
    # but the original uncertain contributor's dollars were never actually
    # re-verified (Codex review, PR badMade/all-stock-dca#1168 discussion
    # r3900047294: "Track identity for id-less uncertain contributors, not
    # just a known-ID subset check"). run_dca.py's bounded-reload merge must
    # additionally prove THIS set is covered before trusting a reload's
    # notional_uncertain=False -- mirroring the exact provenance requirement
    # contributing_order_ids already enforces for known orders.
    #
    # Populated ONLY while a row carries no order_id at all (mirroring
    # contributing_order_ids' own gating in the opposite direction), even
    # though that means it stays empty across the confirmed-dollar path
    # too whenever the row DOES have one. An earlier revision of this field
    # populated it UNCONDITIONALLY (every row, id-full included) so a row
    # that starts id-less and later gains a real order_id could still
    # prove the same contributor was re-observed -- but that let an
    # already order_id-proven row's legitimate decision-field correction
    # (e.g. target_price fixed on a clean reload, order_id unchanged) also
    # poison the SAME check, since the synthetic digest changes even though
    # contributing_order_ids alone already proves it is the same order
    # (Codex review, PR badMade/all-stock-dca#1171 discussion: "Skip
    # synthetic provenance for already identified orders" -- a P1 caught in
    # review). The accepted tradeoff: a row that starts id-less and later
    # gains its FIRST order_id no longer auto-resolves either (its
    # first-pass key never reappears once the row moves off the id-less
    # path) -- the same fail-closed limitation an unreconstructable_
    # submitted_tickers sentinel already has when it resolves into a normal
    # candidate row, not a new regression. Empty by default for any
    # older/direct construction site, matching contributing_order_ids' same
    # fail-closed default.
    uncertain_contributor_ids: frozenset = field(default_factory=frozenset)
    # Every run_id that contributed an ATTEMPT (attempt_count), including a
    # zero-dollar rejected/canceled/failed one -- a strict superset of
    # contributing_run_ids, which only tracks DOLLAR contributors. Needed
    # because the same mirrored zero-notional attempt (e.g. a rejected order
    # backfilled under both midday_dca/manual_reruns and ce16ba6b/manual_runs)
    # never enters contributing_run_ids at all (it contributed no dollars), so
    # the dollar-dedup check in load_prior_same_day_allocations_multi never
    # recognizes it as a duplicate and double-counts the same broker attempt
    # against max_orders_per_day (Codex review: "Deduplicate mirrored
    # zero-notional attempts"). Empty by default for any older/direct
    # construction site, matching contributing_run_ids' same-reasoning default.
    attempt_run_ids: frozenset = field(default_factory=frozenset)


@dataclass(frozen=True)
class TopUpGuardOutcome:
    """Per-ticker result of the same-day prior-run offset/top-up guard."""

    ticker: str
    afternoon_desired_amount: float
    afternoon_decision_price: Optional[float]
    prior_same_day_amount: float
    prior_same_day_reference_price: Optional[float]
    prior_same_day_run_id: Optional[str]
    prior_same_day_source: Optional[str]
    incremental_order_amount: float
    top_up_guard_result: str
    skipped: bool
    manual_review: bool = False
    # The base ($1 or $2) that actually produced afternoon_desired_amount -- the
    # preserved first-allocation base when reused (see
    # resolve_top_up_desired_amount_usd), otherwise this run's own freshly
    # selected base. A candidate-row artifact should record THIS, not the
    # current run's own selected_base_amount_usd, so it stays consistent with
    # the amount actually calculated (Codex review: "Persist the preserved
    # base on top-up candidates").
    effective_base_amount_usd: float = 0.0
    # Set only when the cumulative sub-dollar credit path (dca_cumulative)
    # determined incremental_order_amount, to the raw same-day price decline
    # that was fed into it (NOT the resulting order amount). None whenever an
    # ordinary ladder/price-step increment won instead. The caller settles the
    # durable CumulativeCreditLedger with this value ONLY after the resulting
    # order is actually confirmed submitted (Codex review: "Defer ledger
    # updates until the submitted amount is known") -- this field alone never
    # writes to the ledger.
    cumulative_credit_decline_usd: Optional[float] = None
    # Set ONLY by the sub-dollar ladder-combination branch (the one branch
    # _select_final_session_credit_flush_tickers's combination gate can ever
    # route a deferred ticker into) when combining the existing pending
    # broker-minimum remainder with THIS call's own qualifying decline still
    # lands under the final-session discard threshold. apply_cumulative_
    # credit's own final_session semantics already decided that combined
    # total is forgotten for the day; this field lets the caller
    # (_process_buy_candidate) durably discard it, since evaluate_top_up_guard
    # itself performs no ledger I/O. Left None on the two flush-only branches
    # (no prior context, or price recovered) on purpose: those can only
    # reflect the EXISTING balance alone with no new decline to combine, so
    # deferring them here was never possible in the first place (see
    # _final_session_credit_could_combine_with_this_runs_decline) and their
    # own pre-existing behavior of leaving the ledger untouched is
    # unchanged (Codex review discussion on commit 0af4768: "Clear combined
    # credits that remain below fifty cents").
    discarded_pending_credit_usd: Optional[float] = None


@dataclass(frozen=True)
class BudgetTier:
    """A budget tier with its absolute daily and weekly notional ceilings."""

    name: str
    daily_cap_usd: float
    weekly_cap_usd: float
    uses_rollover_reserve: bool = False


# Ordered low-to-high. The live $2-allocation policy selects the tier by the
# count of 3x-or-greater signals ALONE. These tier values are NOT loaded from
# config at runtime; they must be kept in sync with config/budgets.json, which
# documents the same policy.
BUDGET_TIERS: tuple[BudgetTier, ...] = (
    BudgetTier("normal", 180.0, 900.0),
    BudgetTier("elevated", 240.0, 1200.0),
    BudgetTier("high_volatility", 300.0, 1500.0),
    BudgetTier("stress", 360.0, 1800.0, uses_rollover_reserve=True),
)

NORMAL_WEEKLY_CAP_USD = BUDGET_TIERS[0].weekly_cap_usd

# Escalation thresholds, named rather than inlined as bare numbers in the
# branches below. Each entry is the value a run must EXCEED to reach the tier at
# the same index + 1, so the tuple is read low-to-high alongside BUDGET_TIERS
# and the "> threshold" boundary is stated once instead of per branch.
#
# The signal count is the "how broad is the selloff" trigger — 6, 11, and 18+
# tickers at 3x-or-greater — and is the SOLE input to tier selection: it is
# fixed by Gate 7's candidate list before sizing runs, so tier selection never
# depends on a value the sizing decision itself produces. Mirrored in
# config/budgets.json -> budget_tiers[].select_when and pinned against it by
# test_config_invariants.py.
#
# TIER_SPEND_THRESHOLDS_USD is kept only as a documentation/monitoring
# reference (see config/budgets.json's escalate_above_planned_spend_usd) --
# planned spend is NOT an input to select_budget_tier() below.
TIER_SPEND_THRESHOLDS_USD: tuple[float, ...] = (129.0, 213.0, 272.0)
TIER_HIGH_MULTIPLIER_SIGNAL_THRESHOLDS: tuple[int, ...] = (5, 10, 17)


def _escalation_index(value: float, thresholds: Sequence[float]) -> int:
    """Number of ``thresholds`` strictly exceeded by ``value`` — i.e. the tier index."""
    return sum(1 for threshold in thresholds if value > threshold)


def select_budget_tier(
    planned_spend_usd: float, high_multiplier_signal_count: int
) -> BudgetTier:
    """Select the budget tier for a run from the count of 3x+ signals ALONE.

    Tier selection depends solely on ``high_multiplier_signal_count`` -- a
    value fixed by Gate 7's candidate list before sizing runs, not an output
    of the sizing decision:

        signals: <=5 -> 0, 6-10 -> 1, 11-17 -> 2, >17 -> 3

    ``planned_spend_usd`` is accepted for call-site/signature compatibility
    (and is still recorded in config/budgets.json's
    ``escalate_above_planned_spend_usd`` as a documentation/monitoring
    reference) but does NOT affect tier selection.

    See TIER_HIGH_MULTIPLIER_SIGNAL_THRESHOLDS for where the boundaries come
    from.
    """
    del planned_spend_usd
    signal_idx = _escalation_index(
        high_multiplier_signal_count, TIER_HIGH_MULTIPLIER_SIGNAL_THRESHOLDS
    )
    return BUDGET_TIERS[signal_idx]


@dataclass(frozen=True)
class StrategyConfig:
    tickers: Sequence[str] = tuple(ACTIVE_TICKERS)
    excluded_tickers: frozenset[str] = frozenset(EXCLUDED_TICKERS)
    # See WHOLE_SHARE_TICKERS' own module-level comment and
    # docs/whole_share_accumulation.md. UNLIKE `tickers`/`excluded_tickers`,
    # this deliberately does NOT default to `frozenset(WHOLE_SHARE_TICKERS)`:
    # `excluded_tickers` only ever NARROWS whatever `tickers` a caller
    # passes, so a test/caller overriding `tickers=(...)` to a small ad hoc
    # set is unaffected by whatever excluded_tickers still defaults to. This
    # field WIDENS the evaluated universe instead (see _run_once_impl's
    # tradable_tickers/whole_share_evaluated_tickers split) -- defaulting it
    # to a non-empty set would silently evaluate BYDDY (with a live
    # DryRunBroker/fake-data instance a caller never provisioned for it)
    # against ANY bare `StrategyConfig(tickers=(...))` construction,
    # including the hundreds of existing tests that build one. Real live
    # runs still get WHOLE_SHARE_TICKERS' real membership from
    # config/tickers.json's "whole_share" array via
    # dca_config.load_tickers/load_strategy_config, exactly like `tickers`/
    # `excluded_tickers` are overlaid from "active"/"excluded" -- this is an
    # empty CLASS default only, not a statement that no ticker is enrolled.
    whole_share_tickers: frozenset[str] = frozenset()
    approved_test_dates: frozenset[date] = frozenset(APPROVED_TEST_DATES)
    decision_time_et: time = time(
        15, 30
    )  # matches the 3:30 PM ET canonical live schedule
    trend_lookback_minutes: int = 60
    # First-allocation base amount selected before the ladder multiplier. When the
    # decision price is below the prior regular-session close AND the prior
    # regular-session low, the full ``base_buy_amount_usd`` ($2) scale is used;
    # when it is below the prior close only (not below the prior low), the reduced
    # ``base_buy_amount_below_close_usd`` ($1) scale is used. Not below the prior
    # close is no buy. The 0x-to-5x ladder multiplier is applied after this
    # selection, so the per-order ceiling stays 5x * $2 = $10.
    base_buy_amount_usd: float = 2.0
    base_buy_amount_below_close_usd: float = 1.0
    minimum_order_usd: float = 1.0
    max_per_order_usd: float = 10.0
    # A whole-share ticker (WHOLE_SHARE_TICKERS) cannot be bought in any
    # smaller unit than ONE SHARE, so max_per_order_usd's $10 -- sized for
    # fractional dollar orders, where any amount is expressible -- reads as
    # "never buy this ticker at all" for any symbol trading above it. That is
    # not a theoretical edge: it is what blocked RVII (~$23/share) outright
    # when it moved into the whole-share category, and BYDDY (~$10/share)
    # clears the $10 cap only by a cent or two. This is the ceiling the
    # whole-share path uses INSTEAD, and ONLY to authorize a single share
    # that the ordinary ceiling cannot fit -- never to enlarge a multi-share
    # fire, which max_per_order_usd still governs. See
    # _whole_share_risk_gates and docs/whole_share_accumulation.md.
    whole_share_max_per_order_usd: float = 50.0
    weekly_rollover_reserve_cap_usd: float = 900.0
    high_multiplier_threshold: float = 3.0
    minimum_drop_vs_previous_close: float = 0.001
    max_buys_per_ticker_per_day: int = 1
    one_order_per_ticker_per_day: bool = False
    max_bid_ask_spread_pct: float = 1.0
    # Circuit breaker: max BUY ATTEMPTS placeable in one trading day, shared
    # across all seven roster slots and manual buying (config/budgets.json
    # circuit_breakers.max_orders_per_day). None (the default for a directly
    # constructed StrategyConfig, e.g. in tests or demo mode) means uncapped;
    # dca_config.load_strategy_config overlays the configured integer from
    # budgets.json for every real config load.
    max_orders_per_day: Optional[int] = None
    # circuit_breakers.max_consecutive_placement_failures -- the same knob
    # dca_runner.execute_plan, MorningConfig, and every executor prompt's
    # Gate 7 use, so the live paths cannot disagree about when a batch stops.
    # One ticker's rejection is isolated and costs only that ticker; an
    # unbroken RUN of failures means the broker leg itself is unhealthy and
    # every further placement is a doomed live call. None (the default for a
    # directly-constructed StrategyConfig) means no streak breaker, matching
    # max_orders_per_day's own optional contract; live runs get the real value
    # overlaid from config/budgets.json by dca_config.load_strategy_config.
    max_consecutive_placement_failures: Optional[int] = None
    target_account_number: str = ROBINHOOD_AGENTIC_ACCOUNT_NUMBER
    broker: BrokerName = BrokerName.ROBINHOOD
    dry_run: bool = True

    # Bars from many market-data APIs are start-stamped. At a 3:30 PM decision,
    # the latest completed 15-minute start-stamped bar is 3:05 PM.
    assume_bar_timestamps_are_start_times: bool = True
    finance_interval_minutes: int = 15
    robinhood_interval_minutes: int = 5

    # Graded sizing ladder mapping the drop from prior close to a buy multiplier.
    # Thresholds are fractions of the previous close (0.001 == 0.1%). The largest
    # threshold less than or equal to the actual drop wins; a drop below the first
    # threshold yields no buy (0x). There is no upper cutoff: any drop >= 8.0% is 5x.
    #     drop < 0.1%             -> 0x  (no buy)
    #     0.1% <= drop < 2.0%     -> 1x
    #     2.0% <= drop < 4.0%     -> 1.5x
    #     4.0% <= drop < 5.0%     -> 2x
    #     5.0% <= drop < 6.0%     -> 2.5x
    #     6.0% <= drop < 6.5%     -> 3x
    #     6.5% <= drop < 7.0%     -> 3.5x
    #     7.0% <= drop < 7.5%     -> 4x
    #     7.5% <= drop < 8.0%     -> 4.5x
    #     drop >= 8.0%            -> 5x
    #
    # Rescaled 2026-08-02 (user-directed). The prior curve stepped uniformly every
    # 1% from 0.1% to 8%. This one is flatter on shallow dips (1x now runs to 2%,
    # 1.5x to 4%) and back-loads the scaling into deep drops, slicing 6-8% every
    # half percent. Same endpoints -- 0x below 0.1%, 5x at 8%+ -- so the $10
    # per-order ceiling (5x * $2) is unchanged. Note the knock-on effect on budget
    # tiering: high_multiplier_threshold counts 3x-or-greater signals, which now
    # require a 6% drop rather than 4%, so tier escalation is correspondingly
    # less frequent for the same market conditions.
    sizing_tiers: tuple[tuple[float, float], ...] = (
        (0.001, 1.0),  # down 0.1% to <2.0%
        (0.020, 1.5),  # down 2.0% to <4.0%
        (0.040, 2.0),  # down 4.0% to <5.0%
        (0.050, 2.5),  # down 5.0% to <6.0%
        (0.060, 3.0),  # down 6.0% to <6.5%
        (0.065, 3.5),  # down 6.5% to <7.0%
        (0.070, 4.0),  # down 7.0% to <7.5%
        (0.075, 4.5),  # down 7.5% to <8.0%
        (0.080, 5.0),  # down 8.0% or more (no upper cutoff)
    )
    # Optional symbol-specific historical calibration loaded from
    # config/per_ticker_sizing.json. Each value supplies ``tiers`` as
    # (drop-fraction, multiplier), plus full/reduced base amounts. Symbols
    # absent from this mapping keep the conservative shared ladder.
    per_ticker_sizing: Mapping[str, Mapping[str, Any]] = field(default_factory=dict)
    # Opt-in deferred-accumulation ("inverse Martingale") sizing mode, loaded
    # from config/inverse_martingale.json via dca_config.load_inverse_martingale_config.
    # Off by default (empty mapping) -- see dca_inverse_martingale.py and
    # docs/inverse_martingale.md. Untouched by any path that builds a bare
    # StrategyConfig() without loading config, so behavior there is unaffected.
    inverse_martingale_enabled_default: bool = False
    inverse_martingale_unit_usd: float = 1.0
    inverse_martingale_max_cycle_days: int = 30
    inverse_martingale_max_fire_attempts: int = 5
    inverse_martingale: Mapping[str, Mapping[str, Any]] = field(default_factory=dict)
    # Published, bounded per-ticker multiplier nudge from the ml-forecaster/
    # sibling tool (config/ml_sizing_adjustment.json via
    # dca_config.load_ml_sizing_adjustment). Empty by default -> every
    # ticker's lookup returns the implicit 1.0 no-op in graded_buy_multiplier.
    ml_sizing_adjustment: Mapping[str, float] = field(default_factory=dict)
    # Same-day price-step top-ups use the last executed buy's reference price.
    # A $0.50 cumulative decline rounds up to the first $1 order. Above that
    # floor, order notionals retain cent precision (for example $1.01/$2.99).
    cumulative_top_up_min_drop_usd: float = 0.50
    cumulative_top_up_min_order_usd: float = 1.00

    # --- Dynamic risk guard (rolling deployment kill-switch) -----------------
    # The monthly cash allocation the strategy is funded with, and the fraction
    # of it that, once deployed within any rolling 7-day window, engages the
    # kill-switch. When engaged, the graded ladder is capped at 1x so the
    # strategy keeps participating in dips at the base amount but stops scaling
    # up. deployed_last_7d_usd is a *runtime* field injected per run from the
    # deployment history (see dca_risk.apply_risk_guard); it is never read from
    # config JSON, so loading config can never by itself change sizing.
    monthly_cash_allocation_usd: float = 3600.0
    kill_switch_7d_deploy_fraction: float = 0.40
    deployed_last_7d_usd: float = 0.0

    # When True the 60-minute intraday trend filter is skipped for the buy
    # decision: a ticker below its prior close with multiplier > 0 is bought
    # regardless of whether the 60-minute trend is up or flat. All other guards
    # (minimum drop, spread, budget, data confidence, hard circuit breakers) still
    # apply. Set to True for the final scheduled live buy of the day (3:30 PM ET)
    # per the final_buy_behavior policy in config/scheduled_tasks.json.
    ignore_trend_filter: bool = False


@dataclass
class ArtifactRunContext:
    """Execution parameters for :func:`build_run_artifacts` and :func:`build_usage_proxy`.

    Groups the 11 keyword arguments that control what is stamped into run
    artifacts (error counts, notification counters, top-up guard outcomes,
    manual/scheduled flag, etc.) into a single cohesive object instead of a
    long keyword-argument list.
    """

    order_reviews_attempted: Optional[int] = None
    finance_calls_attempted: Optional[int] = None
    robinhood_calls_attempted: Optional[int] = None
    errors_count: int = 0
    notifications_sent: Optional[int] = None
    cost_control_notes: Optional[Sequence[str]] = None
    top_up_outcomes: Optional[Dict[str, "TopUpGuardOutcome"]] = None
    manual: bool = False
    raw_persistence_state: Optional[Dict[str, object]] = None
    classification_overrides: Optional[Dict[str, Any]] = None
    correlation_id: Optional[str] = None
    # Used ONLY to stamp a non-reversible account_number fingerprint onto the
    # artifact (see build_run_artifacts), never the raw account number: a
    # generated run_state.json is consumed, copied, and scanned by
    # operational tooling, so persisting the real account identifier there
    # exposes it to a support bundle, backup, or accidental check-in --
    # AGENTS.md's secrets policy forbids that (Codex review, PR #911 round
    # 3: "Persist a non-sensitive account fingerprint instead"). Both None
    # (the caller has no broker/key_dir to offer) leave the field null,
    # exactly like an artifact written before this fingerprinting existed.
    broker: Optional["BrokerAdapter"] = None
    account_fingerprint_key_dir: Optional[str | Path] = None


def _canonicalized_integral_numeral(_digits_str: str) -> str:
    """A POSITIVE integral digit string (no sign, leading zeros already
    stripped by the caller), canonicalized the SAME way the scientific-
    notation branch of :func:`_normalized_order_id` bounds and
    canonicalizes ITS OWN oversized values: at or beyond the identical
    ``adjusted() >= 1000`` magnitude bound (equivalently, 1001+
    significant digits), returned as compact normalized scientific
    notation instead of the fully expanded fixed-point digit string.

    Every plain-integer/plain-decimal branch of ``_normalized_order_id``
    used to return its full expansion unconditionally, with no magnitude
    bound at all -- so a 1051-digit plain-integer id ("1" followed by
    1050 zeros) canonicalized to its own 1051-digit expansion, while the
    numerically IDENTICAL value spelled in scientific notation
    ("1e1050") canonicalized to the compact "1e+1050" the sibling branch
    already bounds itself to. The two spellings of the same broker order
    then registered as two DIFFERENT ids, and a later reconciliation
    would restore a second attempt for one of them (Codex review, PR
    #1168: "Canonicalize bounded and expanded numeric IDs consistently").
    Below the bound, every existing plain-integer/decimal id -- however
    large, up to Python's own integer-string conversion digit limit --
    canonicalizes exactly as before, unchanged.
    """
    _digits_str = _digits_str.lstrip("0") or "0"
    if _digits_str == "0" or len(_digits_str) - 1 < 1000:
        return _digits_str
    _canonical_exponent = len(_digits_str) - 1
    _mantissa = _digits_str.rstrip("0") or "0"
    if len(_mantissa) == 1:
        return f"{_mantissa}e+{_canonical_exponent}"
    return f"{_mantissa[0]}.{_mantissa[1:]}e+{_canonical_exponent}"


def _normalized_order_id(order_id: Optional[object]) -> Optional[str]:
    """``str(...).strip()`` an order_id, or ``None`` through unchanged.

    Every OTHER order-id comparison in this module normalizes this way
    before comparing (e.g. the duplicate-order dedup at
    ``_dup_order_id_normalized``, the sidecar-conflict checks) -- but
    ``StrategyState``'s own ``recorded_attempt_order_ids``/
    ``own_recovered_order_ids`` membership used the raw, un-normalized
    value a caller happened to pass. A broker id returned with incidental
    surrounding whitespace (``" ORD "``) then registered under a DIFFERENT
    set member than the same physical order's later, ``.strip()``-
    normalized reference (``"ORD"``, as reconciliation's own history-id
    lookups already produce) -- read as two distinct orders, subtracting
    the untrimmed one as an unrelated buy and restoring a second attempt
    for what is actually the same order (Codex review, PR #1164/#1165:
    "Normalize order IDs before persisting attempt provenance").

    An INTEGRAL numeric order id -- a bare ``int``/``float``, or a
    numeric-looking string -- is further canonicalized to the same
    bare-integer spelling regardless of which representation produced
    it: the adapter's own explicitly supported finite positive float-ID
    shape persists a placement's ``123.0`` here as ``"123.0"``, while a
    LATER broker/history response can encode the identical identifier as
    ``123`` or ``"123"`` (which this function already normalized to
    ``"123"``). Reconciliation then treated the two spellings as
    DISTINCT orders and could restore the same attempt a second time
    (Codex review, PR #1168: "Canonicalize integral numeric order IDs
    consistently"). ``bool`` is excluded even though it is technically an
    ``int`` subclass: ``True``/``False`` are never a numeric order id.

    Never routes a numeral through ``float()`` to detect or canonicalize
    it: IEEE-754 doubles only represent integers EXACTLY up to 2**53, so
    ``float("9007199254740993")`` silently rounds to
    ``9007199254740992.0`` -- two broker ids that differ by 1 above that
    range collapsed to the identical normalized string, and reconciliation
    mistook a genuinely different order for one already recorded,
    understating ``day_order_count()`` (Codex review, PR #1168: "Preserve
    exact numeric order IDs"). A real Python ``int`` is already an exact
    integer and is stringified directly; a numeric STRING is canonicalized
    via plain ``int()`` parsing (also exact, arbitrary precision) with a
    regex fallback for the explicitly-supported ``"123.0"``-style decimal
    spelling, never ``float()``.
    """
    if order_id is None:
        return None
    if isinstance(order_id, bool):
        # A bool is technically an int subclass -- excluded from numeric
        # canonicalization below (True/False must never collide with a
        # real numeric order id like "1"). Discarded entirely, not
        # stringified to "True"/"False": `dca_live_adapters.py` already
        # rejects a boolean order_id outright as never a real broker
        # identifier, but this function used to persist it anyway as the
        # apparently-valid string "True". If an ambiguous attempt is
        # charged against that placeholder and the real id is later
        # discovered, reconciliation reads "True" as a DIFFERENT known
        # order and restores the same attempt a second time, inflating the
        # daily attempt count (Codex review, PR #1168: "Discard boolean
        # order-ID sentinels before recording provenance").
        return None
    if isinstance(order_id, int):
        # Already an exact integer -- stringified directly, no float()
        # detour that could round a value outside its exact 53-bit range.
        # A non-positive value (`0`, a negative int) discarded entirely,
        # not stringified into the apparently-valid durable id "-1"/"0":
        # `_is_usable_reconciled_order_id` already rejects a non-positive
        # numeric id outright (`value > 0`) as never a real broker
        # identifier -- no legitimate broker assigns order id 0 or a
        # negative number -- but this function persisted it anyway. If an
        # ambiguous attempt is charged against that placeholder and the
        # real id is later discovered, reconciliation reads "-1" as a
        # DIFFERENT known order and restores the same attempt a second
        # time, inflating the daily attempt count (Codex review, PR
        # #1168: "Discard non-positive numeric order IDs before
        # persisting").
        if order_id <= 0:
            return None
        # Bounded the same way the string-literal branches below already
        # are: `str()` on an integer longer than Python 3.11's default
        # integer-string conversion digit limit raises `ValueError` --
        # unguarded here, a native (not string-encoded) astronomically
        # large positive int passed every check above and reached this
        # bare `str(order_id)`, even though `_is_usable_order_id_scalar`
        # accepts the identical value and can hand it to whole-share
        # recovery paths that then bookkeep an order already known to the
        # broker. Because successful live-placement paths call
        # `record_buy(..., order_id=...)` with this function's return
        # value, an unguarded raise here could abort bookkeeping AFTER
        # the broker already accepted the order (Codex review, PR #1169:
        # "Reject oversized native integer order IDs before
        # stringifying").
        try:
            return str(order_id)
        except ValueError:
            return None
    if isinstance(order_id, float):
        if not math.isfinite(order_id):
            # A bare NaN or +/-infinity discarded entirely, not
            # stringified into the apparently-valid durable id "nan"/
            # "inf": `_is_usable_reconciled_order_id` already rejects a
            # non-finite numeric id outright as never a real broker
            # identifier, but this function persisted it anyway. If an
            # ambiguous attempt is charged against that placeholder and
            # the real id is later discovered, reconciliation reads
            # "nan"/"inf" as a DIFFERENT known order and restores the
            # same attempt a second time, inflating the daily attempt
            # count (Codex review, PR #1168: "Discard non-finite order
            # IDs instead of persisting them"; PR #1169: "Discard
            # non-finite IDs from the durable attempt ledger").
            return None
        # A non-positive float value (`-1.0`, `0.0`) is discarded too,
        # for the identical reason as the int branch above -- a genuinely
        # fractional non-positive value (`-1.5`) is equally never a real
        # order id.
        if order_id <= 0:
            return None
        if order_id.is_integer():
            # Routed back through THIS function via `repr(order_id)`, not
            # a bare `str(int(order_id))`: the binary float's exact value
            # can differ from its shortest decimal repr once the
            # magnitude exceeds float's ~15-17 significant-digit precision
            # -- `int(1.2345678901234568e20)` is the EXACT binary integer
            # 123456789012345683968, while the equivalent numeric STRING
            # id ("1.2345678901234568e+20") canonicalizes through the
            # scientific-notation string branch below to
            # 123456789012345680000 (`repr()`'s own shortest round-
            # tripping decimal spelling). A native integral-float order id
            # and the identical value's string spelling diverged into two
            # different canonical forms, and reconciliation read them as
            # two DISTINCT orders (Codex review, PR #1169: "Route integral
            # floats through their round-trip representation"). Mirrors
            # the fractional branch's own identical `repr()` routing just
            # below, for the identical round-tripping reason.
            return _normalized_order_id(repr(order_id))
        # Routed back through THIS function via `repr(order_id)`, not a
        # bare `str(order_id).strip()`: Python's own float repr switches
        # to exponent notation for small magnitudes (`repr(1e-5) ==
        # "1e-05"`), while the equivalent numeric STRING id ("1e-5")
        # canonicalizes through the scientific/fractional-decimal string
        # branches below to "0.00001" -- so a native float order id and
        # the identical value's string spelling diverged into two
        # different canonical forms, and reconciliation read them as two
        # DISTINCT orders (Codex review, PR #1168: "Canonicalize
        # scientific native-float order IDs consistently"). `repr()`, not
        # `str()`: `repr()` is guaranteed to round-trip exactly back to
        # the identical float, so re-parsing it through the string
        # branches below via `Decimal` loses no precision.
        return _normalized_order_id(repr(order_id))
    if not isinstance(order_id, str):
        # Every scalar shape a real order id can legitimately arrive as --
        # None, bool, int, float, str -- is handled by name above or below;
        # anything else (a list, a dict/mapping, any other non-scalar) is a
        # malformed connector row, not a real identifier. `str(order_id)`
        # would otherwise stringify it into an apparently-valid id like
        # "['BAD']" or "{'id': 1}" -- `dca_live_adapters.py` already
        # requires `isinstance(order_id, (str, int, float))` before
        # trusting one, but this function persisted the fabricated string
        # anyway. If history later reveals the real id for that same
        # ambiguous attempt, reconciliation treats the fabricated string as
        # a DIFFERENT known order and restores the same attempt a second
        # time, inflating the daily attempt count (Codex review, PR #1168:
        # "Reject non-scalar order IDs before persisting them").
        return None
    _normalized = order_id.strip()
    if not _normalized:
        return None
    # A numeric string that IS already an exact integer literal (optional
    # sign, digits only) is canonicalized via `int()`, never `float()`:
    # Python's `int` has arbitrary precision, but `float` cannot represent
    # every integer exactly once it exceeds 2**53, so two distinct broker
    # ids beyond that range -- e.g. "9007199254740992" and
    # "9007199254740993" -- both round-tripped through `float()` to the
    # SAME canonicalized string. Reconciliation then treated the second
    # order as already recorded, crediting its notional while never
    # counting its attempt, understating submitted_order_count_by_day and
    # permitting another live order beyond the configured daily limit
    # (Codex review, PR #1169: "Keep numeric string order IDs lossless").
    # `int()` raises ValueError on anything that isn't a plain integer
    # literal (a decimal string like "123.0", scientific notation, etc.),
    # so those fall through to the float-based path below exactly as
    # before. Gated on a strict ASCII `[+-]?[0-9]+` regex FIRST, not
    # passed straight to `int()`: Python's `int()` is far more permissive
    # than a "digits-only literal" -- it accepts an underscore digit
    # separator ("1_0") and Unicode decimal digits from other scripts,
    # silently normalizing either to the same value as the equivalent
    # plain ASCII spelling ("10"). A rejected pagination row using one
    # spelling and a queued row using the other -- both distinct as RAW
    # broker strings -- canonicalized to the identical id here, so a
    # dedup/history scan keyed on this function's output collapsed them
    # into one and could report a live order absent, authorizing a
    # duplicate purchase (Codex review, PR #1168: "Restrict numeric ID
    # normalization to ASCII literals").
    if re.fullmatch(r"[+-]?[0-9]+", _normalized):
        try:
            _int_value = int(_normalized)
        except ValueError:
            # A digit count beyond Python 3.11's default integer-string
            # conversion digit limit (e.g. a 4,301-digit literal) raises
            # here rather than converting -- falling through to `pass`
            # sent this ALL-DIGITS string past every other branch (none
            # of which match a plain digit string with no ``.``/``e``)
            # all the way to the final non-finite check, where
            # `float(_normalized)` overflows a value this large to
            # `inf` and the "non-finite" rejection discarded it as
            # `None` -- even though the value is a genuine, exact,
            # finite positive integer, just one `int()`/`float()` alone
            # cannot represent. The live placement validators accept an
            # oversized numeric string via `Decimal`, so an accepted
            # order could reach `record_buy()` and then lose its durable
            # provenance here, forcing later reconciliation to treat it
            # as anonymous (Codex review, PR #1169: "Preserve oversized
            # numeric-string IDs").
            #
            # Canonicalized manually here -- sign and leading zeros
            # stripped directly from the matched digit string -- rather
            # than returned unchanged (an earlier version of this fix
            # did): the ordinary `int()` path just below strips a leading
            # `+`/leading zeros and rejects zero/negative before
            # stringifying, but returning `_normalized` raw skipped all of
            # that for an oversized literal. The SAME broker order
            # reported once as a 5,000-digit id with a leading zero
            # ("0" + 5000 digits) and later as the identical value with no
            # leading zero then canonicalized to two DIFFERENT strings
            # here, and `book_reconciled_attempt_notional()` read them as
            # two distinct orders, restoring the same attempt again and
            # prematurely consuming the daily order cap (Codex review, PR
            # #1168: "Canonicalize oversized integer IDs without
            # returning raw"). Never routed through `int()`/`float()` --
            # both would raise or lose precision on a literal this long;
            # stripping leading zeros from the raw digit string is exact
            # at any length, the same reasoning the scientific/fractional
            # branches' own manual `Decimal` tuple-stripping already
            # applies.
            #
            # A negative sign is rejected outright, not preserved: the
            # ordinary `int()` path just below (the `else` branch) already
            # rejects a negative/zero numeric string via `_int_value <=
            # 0: return None`, but this overflow branch returned the
            # manually-normalized NEGATIVE value unchanged, skipping that
            # check entirely for a literal too large for `int()`. A
            # malformed persisted provenance entry -- an oversized
            # negative id -- then survived as an apparently-valid durable
            # order id, and a later reconciliation could subtract it as
            # an unrelated known attempt and restore the real order
            # again, inflating the daily attempt count (Codex review, PR
            # #1168: "Reject oversized negative decimal IDs" -- reported
            # for the sibling decimal branch below, applies identically
            # here).
            if _normalized.startswith("-"):
                return None
            _oversized_digits = _normalized.lstrip("+").lstrip("0") or "0"
            if _oversized_digits == "0":
                return None
            return _canonicalized_integral_numeral(_oversized_digits)
        else:
            # A negative or zero numeric STRING ("-1", "0") bypassed the
            # non-positive rejection the int/float branches above already
            # apply -- `_is_usable_reconciled_order_id` and the
            # live-adapter validators already treat a non-positive
            # numeric id as unusable regardless of whether it arrives as
            # a native number or a string spelling of one, but this
            # string path returned it verbatim. If an ambiguous attempt
            # is charged against that placeholder and the real id is
            # later discovered, reconciliation reads "-1" as a DIFFERENT
            # known order and restores the same attempt a second time
            # (Codex review, PR #1168/#1169: "Discard stringified
            # non-positive order IDs" / "Reject negative numeric-string
            # order IDs" -- two independently-authored fixes for the
            # identical gap).
            if _int_value <= 0:
                return None
            return _canonicalized_integral_numeral(str(_int_value))
    # Not a clean integer literal, but could still be the adapter's own
    # explicitly-supported integral DECIMAL spelling ("123.0") -- the
    # integer portion is captured via regex, never float(), to stay exact
    # at any magnitude. The captured digits are still passed through
    # int() before stringifying, not returned as raw captured text: a
    # LEADING-ZERO decimal spelling ("001.0") otherwise kept its zeros
    # ("001") while the equivalent plain-integer spelling ("001") above
    # already canonicalizes through int() to "1" -- the same broker order
    # encoded through the two paths registered as two different ids, and
    # a later reconciliation restored a second attempt for it, overstating
    # the daily order count (Codex review, PR #1169: "Canonicalize leading
    # zeros in decimal order IDs"). The optional leading `+` mirrors the
    # scientific-notation regex below: an integral plain-decimal spelling
    # like "+001.0" fell through this regex unchanged (only `-` was
    # accepted), while the equivalent "+001"/"1.0"/numeric 1.0 all
    # canonicalize to "1" -- the same broker order registering as two
    # distinct ids (Codex review, PR #1169: "Canonicalize leading-plus
    # decimal order IDs").
    #
    # Matched with `re.ASCII`, not the bare Unicode-aware `\d` every
    # other numeric-string regex here still used: Python's `\d` matches
    # any Unicode decimal digit, not just ASCII 0-9, so a broker string
    # spelling the same value with Arabic-Indic digits ("١٠.0") matched
    # this regex identically to the plain-ASCII spelling ("10.0") and
    # canonicalized to the SAME id -- the exact class of collision the
    # plain-integer-literal branch above was already fixed for (Codex
    # review, PR #1168: "Restrict numeric ID normalization to ASCII
    # literals"), but this sibling regex, and the fractional/scientific
    # ones below, were not.
    _decimal_match = re.fullmatch(r"([+-]?\d+)\.0+", _normalized, re.ASCII)
    if _decimal_match:
        # Bounded the same way the plain-integer branch above already is:
        # `int()` on a digit string longer than Python 3.11's default
        # integer-conversion digit limit raises `ValueError` -- an
        # integral decimal spelling with an extreme digit count (e.g.
        # 5,000 digits before ".0") hit that limit unguarded here, even
        # though the plain-integer branch a few lines up already wraps the
        # identical conversion in a try/except for exactly this reason.
        # Because successful live-placement paths call `record_buy(...,
        # order_id=...)` with this function's return value, an unguarded
        # raise here could abort bookkeeping AFTER the broker already
        # accepted the order, leaving it without a durable attempt charge
        # (Codex review, PR #1168: "Bound plain-decimal order-ID
        # conversion").
        try:
            _decimal_int_value = int(_decimal_match.group(1))
        except ValueError:
            # A digit count beyond Python 3.11's default integer-string
            # conversion digit limit (e.g. a 5,001-digit coefficient
            # before ".0") raises here too, the same overflow the plain-
            # integer-literal branch above already guards. Canonicalized
            # manually -- sign and leading zeros stripped directly from
            # the matched coefficient -- rather than returned unchanged:
            # the SAME oversized broker id delivered once as this
            # integral-decimal spelling ("...0001.0") and later as the
            # equivalent plain-integer spelling ("...1", already
            # canonicalized by the sibling overflow branch above) would
            # otherwise register as two DIFFERENT ids, and
            # `book_reconciled_attempt_notional()` would restore a second
            # attempt for it, prematurely consuming the daily order cap
            # (Codex review, PR #1168: "Canonicalize oversized decimal
            # IDs without returning raw"). Never routed through
            # `int()`/`float()` -- both would raise or lose precision on
            # a coefficient this long; stripping leading zeros from the
            # raw digit string is exact at any length, the same reasoning
            # the sibling oversized plain-integer branch's own identical
            # fix already applies.
            #
            # A negative sign is rejected outright, not preserved: the
            # ordinary `int()` path just below already rejects a
            # negative/zero decimal string via `_decimal_int_value <= 0:
            # return None`, but this overflow branch returned the
            # manually-normalized NEGATIVE value unchanged, skipping that
            # check for a coefficient too large for `int()`. A malformed
            # persisted provenance entry -- an oversized negative decimal
            # id -- then survived as an apparently-valid durable order
            # id, and a later reconciliation could subtract it as an
            # unrelated known attempt and restore the real order again,
            # inflating the daily attempt count (Codex review, PR #1168:
            # "Reject oversized negative decimal IDs").
            if _decimal_match.group(1).startswith("-"):
                return None
            _oversized_decimal_digits = _decimal_match.group(1).lstrip("+").lstrip("0") or "0"
            if _oversized_decimal_digits == "0":
                return None
            return _canonicalized_integral_numeral(_oversized_decimal_digits)
        # Same non-positive rejection as the plain-integer-literal branch
        # above, for the identical decimal-spelling reason (Codex review,
        # PR #1169: "Reject negative numeric-string order IDs").
        if _decimal_int_value <= 0:
            return None
        return _canonicalized_integral_numeral(str(_decimal_int_value))
    # A GENUINELY FRACTIONAL decimal string ("1.50") is likewise a valid
    # numeric spelling this function otherwise left unchanged, while the
    # SAME broker id delivered later as an actual `float` (1.5) hits the
    # `isinstance(order_id, float)` branch above and canonicalizes to
    # "1.5" -- the adapter explicitly accepts a finite positive float id,
    # so placement and reconciliation can represent the identical order
    # under these two spellings, registering it as two distinct ids and
    # letting `book_reconciled_attempt_notional()` restore a second
    # attempt (Codex review, PR #1169: "Canonicalize fractional numeric
    # order IDs"). The mantissa alternation (`\d+\.\d*|\.\d+`) mirrors the
    # scientific-notation regex below: a valid spelling with an OMITTED
    # leading or trailing digit (".5", "1.") previously did not match the
    # stricter `\d+\.\d+` this used to require (digits on BOTH sides), so
    # it fell through unchanged, while the equivalent native floats
    # normalize to "0.5"/"1" -- the same broker order registering as two
    # different ids (Codex review, PR #1168: "Canonicalize decimal IDs
    # with an omitted digit"; PR #1169: "Canonicalize leading- and
    # trailing-dot decimal IDs" -- two independently-authored fixes for
    # the identical gap). Parsed via `Decimal`, not `float()`, and
    # canonicalized the SAME way the scientific-notation branch below
    # does -- exact trailing-zero stripping on the digit tuple, never a
    # lossy float conversion, for the identical reason that branch's own
    # fix exists. Matched with `re.ASCII` for the identical reason the
    # decimal_match regex above now is -- `\d` alone accepts Unicode
    # decimal digits from other scripts, and `Decimal()` parses them
    # too, so a broker string spelling the same value with, e.g.,
    # Arabic-Indic digits collided with the plain-ASCII spelling under
    # this function's canonicalized output (Codex review, PR #1168/
    # #1169: "Restrict numeric ID normalization to ASCII literals").
    if re.fullmatch(r"[+-]?(\d+\.\d*|\.\d+)", _normalized, re.ASCII):
        try:
            _decimal_value = decimal.Decimal(_normalized)
        except decimal.InvalidOperation:
            return _normalized
        if _decimal_value <= 0:
            return None
        if _decimal_value == _decimal_value.to_integral_value():
            try:
                return _canonicalized_integral_numeral(str(int(_decimal_value)))
            except ValueError:
                # A digit count beyond Python 3.11's default integer-string
                # conversion digit limit (e.g. a 5,000-digit value with an
                # OMITTED fractional digit, "<digits>.") raises here too --
                # this integral-decimal shape has its own conversion path
                # (`int(_decimal_value)`, not `int()` on a matched regex
                # group like the sibling ".0"-suffixed branch above), so
                # that branch's own overflow fix didn't cover it.
                # Canonicalized via the SAME manual digit-tuple stripping
                # the non-integral branch just below already uses, not
                # returned as `_normalized` raw (which would keep the
                # trailing "."): the SAME oversized broker id delivered
                # once as this trailing-dot spelling and later as the
                # equivalent plain-integer spelling (already canonicalized
                # by the sibling oversized branch above) would otherwise
                # register as two DIFFERENT ids, and reconciliation would
                # restore a second attempt for it (Codex review, PR #1168:
                # "Canonicalize oversized trailing-dot IDs"). Leading zeros
                # are already stripped by `Decimal`'s own parsing, so only
                # trailing fractional zeros (a negative exponent) need
                # stripping here -- exact at any length, never routed
                # through `int()`/`float()`.
                _sign, _digits, _exponent = _decimal_value.as_tuple()
                _digits = list(_digits)
                while _exponent < 0 and _digits and _digits[-1] == 0:
                    _digits.pop()
                    _exponent += 1
                _mantissa = "".join(str(_d) for _d in _digits) or "0"
                if _exponent > 0:
                    _mantissa += "0" * _exponent
                return _canonicalized_integral_numeral(_mantissa)
        _sign, _digits, _exponent = _decimal_value.as_tuple()
        _digits = list(_digits)
        while len(_digits) > 1 and _exponent < 0 and _digits[-1] == 0:
            _digits.pop()
            _exponent += 1
        _stripped = decimal.Decimal((_sign, tuple(_digits), _exponent))
        return format(_stripped, "f")
    # A SCIENTIFIC-notation spelling ("1e3") is likewise a valid numeric
    # string `int()` above cannot parse and the plain-decimal regex above
    # does not match either, so it fell through returned unchanged -- while
    # the SAME broker id delivered later as an actual float (1000.0) hits
    # the isinstance(order_id, float) branch further up and canonicalizes
    # to "1000". The two spellings of the identical order registered as
    # two different ids, and a later reconciliation restored a second
    # attempt for it, overstating the daily order count (Codex review, PR
    # #1169: "Canonicalize scientific-notation order IDs"). Parsed via
    # Decimal, not float(): Decimal("9.007199254740993e15") is exact at
    # any magnitude the same way int() is for a plain digit string, so
    # this stays consistent with why the earlier huge-integer fix avoided
    # float() entirely.
    #
    # The mantissa alternation (`\d+(\.\d*)?|\.\d+`) and the leading
    # `[+-]?` sign accept the FULL scientific-notation grammar `Decimal`
    # itself supports, not just the bare `-?\d+(\.\d*)?` shape: a valid
    # spelling like "+1e3" (explicit leading plus) or ".5e3" (no digits
    # before the decimal point) previously fell through this regex
    # unchanged, while the equivalent numeric id "1000"/"500" delivered
    # through another path canonicalized normally -- the same broker order
    # registered as two different ids and a later reconciliation restored
    # a second attempt for it, overstating the daily order count (Codex
    # review, PR #1169: "Normalize leading-plus scientific order IDs").
    #
    # Matched with `re.ASCII` for the identical reason the plain-decimal
    # regexes above now are -- `\d` alone accepts Unicode decimal digits,
    # and `Decimal()` parses them too, so a broker string spelling the
    # same value with, e.g., Arabic-Indic digits collided with the
    # plain-ASCII spelling under this function's canonicalized output
    # (Codex review, PR #1168/#1169: "Restrict numeric ID normalization
    # to ASCII literals").
    if re.fullmatch(r"[+-]?(\d+(\.\d*)?|\.\d+)[eE][+-]?\d+", _normalized, re.ASCII):
        try:
            _decimal_value = decimal.Decimal(_normalized)
        except decimal.InvalidOperation:
            return _normalized
        # A large POSITIVE exponent ("1e4300") expands into a
        # thousands-of-digits integer -- `Decimal.adjusted()` gives that
        # expansion's order of magnitude WITHOUT ever materializing the
        # integer itself, so this bound is checked BEFORE the expensive
        # `int()`/`str()`/`float()` conversion below runs at all, not
        # after. No real broker order id is ever anywhere close to this
        # many digits, so a spelling this large is itself proof the id is
        # malformed, not a genuine numeric id this function failed to
        # canonicalize. Left as its own unchanged string rather than
        # expanded: on Python 3.11+, converting an integer this large to
        # a string can outright raise `ValueError` (the interpreter's own
        # default integer-string conversion digit limit), and even below
        # that limit the expansion itself is needless CPU/memory work for
        # a value that was never a usable id to begin with. Because
        # successful live-placement paths call `record_buy(...,
        # order_id=...)` with this function's return value, an unguarded
        # raise here could abort bookkeeping AFTER the broker already
        # accepted the order, leaving it without a durable attempt charge
        # (Codex review, PR #1168/#1169: "Bound scientific order-ID
        # expansion" / "Bound scientific order-ID canonicalization" -- two
        # independently-authored fixes for the identical gap; this one
        # wins since it also avoids the needless CPU/memory cost of
        # materializing a huge integer that was never going to be a
        # usable id). Applied BEFORE the non-positive/fractional checks
        # below, not just inside the integral branch, so it bounds every
        # scientific spelling this regex can match, fractional included.
        # Bounded SYMMETRICALLY -- an extreme NEGATIVE exponent (e.g.
        # "1e-1" followed by eight more zeros) passes this positive-only
        # check (`adjusted()` is negative there), but the fixed-point
        # formatting the
        # fractional branch below performs allocates a string with
        # roughly that many leading zeros, risking the same memory/CPU
        # exhaustion (or an abort after the broker already accepted the
        # order) the positive-exponent bound above exists to prevent
        # (Codex review, PR #1168: "Bound negative scientific exponents
        # before fixed formatting").
        # Same non-positive rejection as the other numeric-string
        # branches above, for the identical scientific-notation spelling
        # reason (Codex review, PR #1169: "Reject negative numeric-string
        # order IDs"). Checked BEFORE the integral/fractional branch
        # below (not only inside the integral one), so a negative
        # FRACTIONAL spelling ("-1e-1") is rejected too -- it previously
        # bypassed this check entirely by never reaching the integral
        # branch it lived inside, falling through unchanged and returning
        # the apparently-valid negative id "-1e-1" (Codex review, PR
        # #1168: "Canonicalize fractional scientific order IDs"). Also
        # checked BEFORE the magnitude bound below, not after: a `Decimal`
        # comparison against zero is cheap regardless of magnitude (unlike
        # the `int()`/`str()` expansion the magnitude bound itself guards
        # against), so an extreme-exponent NEGATIVE or ZERO spelling
        # ("-1e1000", "0e10000") used to hit the magnitude bound first and
        # return unchanged as an apparently-valid id, instead of being
        # rejected here like every smaller-exponent non-positive spelling
        # already is (Codex review, PR #1169: "Reject bounded non-positive
        # scientific order IDs").
        if _decimal_value <= 0:
            return None
        if _decimal_value.adjusted() >= 1000 or _decimal_value.adjusted() <= -1000:
            # Canonicalized in place -- trailing zeros stripped from the
            # exact (sign, digits, exponent) tuple and re-assembled as
            # normalized scientific notation, never returned as the raw
            # `_normalized` spelling: two numerically-EQUIVALENT
            # over-bound spellings of the identical value ("1e1000" and
            # "10e999", both 1*10**1000) canonicalized to two DIFFERENT
            # strings when returned unchanged, and the adapter's own
            # `Decimal`-based placement validation accepts both as usable
            # finite positive string ids -- so placement and later
            # history reporting the same broker order under these two
            # spellings let `book_reconciled_attempt_notional()` subtract
            # the first as an unrelated known order and restore another
            # attempt under the second, inflating the daily attempt count
            # (Codex review, PR #1168: "Canonicalize equivalent
            # scientific IDs beyond the bound"). Trailing-zero stripping
            # only touches the digit COUNT, never expands the value into
            # a fixed-point string -- exact and bounded in output size by
            # the number of significant digits (never the magnitude),
            # the same reasoning the magnitude bound above exists to
            # enforce.
            _sign, _digits, _exponent = _decimal_value.as_tuple()
            _digits = list(_digits)
            while len(_digits) > 1 and _digits[-1] == 0:
                _digits.pop()
                _exponent += 1
            _mantissa = "".join(str(_d) for _d in _digits)
            _canonical_exponent = _exponent + len(_digits) - 1
            _sign_str = "-" if _sign else ""
            if len(_mantissa) == 1:
                return f"{_sign_str}{_mantissa}e{_canonical_exponent:+d}"
            return f"{_sign_str}{_mantissa[0]}.{_mantissa[1:]}e{_canonical_exponent:+d}"
        if _decimal_value == _decimal_value.to_integral_value():
            return str(int(_decimal_value))
        # A FRACTIONAL scientific spelling ("1.5e0") previously fell
        # through this whole branch unchanged (only an INTEGRAL value
        # canonicalized). Routing it through `float()` (an earlier version
        # of this fix did) is itself LOSSY: distinct accepted spellings
        # like "1e-400" and "2e-400" both underflow to the same float
        # 0.0, and "1.0000000000000001e0" (17 significant digits, exact
        # in Decimal) rounds to the float 1.0 -- collapsing genuinely
        # different broker ids into the identical canonicalized string,
        # or a rounding string like "1.0" a later exact match for that
        # id's next appearance under a Decimal path would never agree
        # with. Canonicalized via manual trailing-zero stripping on the
        # exact (sign, digits, exponent) tuple, formatted with the 'f'
        # (fixed-point) spec -- exact at any magnitude the same way
        # `int()` is for the plain-integer branch, never rounding through
        # a lossy float, whether that loss shows up as a collision (a
        # large-magnitude value like "9007199254740993.5e0" rounding to
        # the SAME string a DIFFERENT id "9007199254740994.5e0" spells)
        # or an underflow to zero (a tiny value like "1e-5000" becoming
        # "0.0", which the non-positive check above would then discard as
        # if it were never a real id) (Codex review, PR #1168: "Avoid
        # lossy float conversion of scientific order IDs"; PR #1169:
        # "Preserve exact fractional scientific order IDs" -- two
        # independently-authored fixes for the identical gap). NOT
        # `Decimal.normalize()` (an earlier version of this fix used it):
        # that convenience method is itself an ARITHMETIC operation that
        # applies the thread-local decimal context's precision (28
        # significant digits by default), silently rounding a value with
        # MORE digits than that -- two distinct ids differing only past
        # the 28th digit (e.g. "...901e0" vs "...902e0") both normalized
        # to the identical rounded string, letting the provenance ledger
        # treat two real orders as one and omit an attempt from the daily
        # cap. Manually stripping trailing zeros from the digit tuple
        # (only while the exponent is still negative, i.e. only the
        # fractional part) performs no arithmetic and is therefore exact
        # at ANY digit count `decimal.Decimal(_normalized)`'s own
        # (equally exact, construction-time-only) parsing already
        # preserved (Codex review, PR #1168: "Preserve all digits when
        # normalizing scientific IDs").
        _sign, _digits, _exponent = _decimal_value.as_tuple()
        _digits = list(_digits)
        while len(_digits) > 1 and _exponent < 0 and _digits[-1] == 0:
            _digits.pop()
            _exponent += 1
        _stripped = decimal.Decimal((_sign, tuple(_digits), _exponent))
        return format(_stripped, "f")
    # A connector can serialize a non-finite sentinel as a STRING spelling
    # ("NaN", "Infinity", "-inf") that matches none of the numeric regexes
    # above, so it reached here unchanged and was returned as an
    # apparently-valid durable id. Checked before falling through -- if
    # history later exposes the real scalar id for that same ambiguous
    # attempt, `book_reconciled_attempt_notional()` would otherwise treat
    # the sentinel as an unrelated recorded order and restore the same
    # attempt again, inflating the daily attempt count (Codex review, PR
    # #1168: "Discard serialized non-finite order IDs").
    #
    # Checked via `decimal.Decimal(...).is_finite()`, not `float(...)`:
    # `float()` only recognizes the ordinary "nan"/"inf"/"infinity"
    # spellings (case-insensitively) and raises `ValueError` on a
    # SIGNALING or PAYLOAD NaN -- "sNaN" or "NaN123" -- so those sentinels
    # fell through the `except ValueError: pass` below unrejected and were
    # returned as apparently-valid durable ids. `Decimal` parses both
    # extended spellings and reports `is_finite() is False` for either,
    # closing that gap the same way the numeric-string branches above
    # already lean on `Decimal` rather than `float()` for exactness (Codex
    # review, PR #1168: "Reject signaling and payload NaN order IDs").
    try:
        _non_numeric_decimal = decimal.Decimal(_normalized)
    except decimal.InvalidOperation:
        return _normalized
    if not _non_numeric_decimal.is_finite():
        return None
    return _normalized


@dataclass
class StrategyState:
    buys_by_ticker_by_day: Dict[str, Dict[date, int]] = field(default_factory=dict)
    submitted_notional_by_day: Dict[date, float] = field(default_factory=dict)
    submitted_notional_by_week: Dict[tuple[int, int], float] = field(
        default_factory=dict
    )
    # Buy ATTEMPTS booked for the day, shared across all seven roster slots
    # (config/budgets.json circuit_breakers.max_orders_per_day). Bumped by
    # record_buy alongside the dollar counters above, so it is reconstructed
    # by the same same-day seeding path that rebuilds submitted_notional_by_day
    # across separate slot invocations -- see _seed_prior_allocations.
    submitted_order_count_by_day: Dict[date, int] = field(default_factory=dict)
    # How much EARLIER-weekday cross-stream notional (run_dca._compute_
    # earlier_week_cross_stream_notional's total, re-derived from on-disk
    # artifacts on every invocation) has already been folded into
    # submitted_notional_by_week for a given ISO week via
    # reconcile_earlier_week_cross_stream_notional. This persistent
    # StrategyState survives across invocations (state_transaction()
    # reloads it fresh each time), and record_buy() calls made on an
    # EARLIER day already updated submitted_notional_by_week for that day's
    # own ISO week -- so a later invocation re-scanning that same earlier
    # day's artifacts and blindly ADDING its total again would double-count
    # spend the persisted ledger already knows about, worse on every
    # subsequent same-week invocation (Codex review: "Reconcile earlier-week
    # spend instead of adding it"). Tracking the total already folded in
    # lets each call add only the INCREMENTAL delta, the same idiom
    # morning_dca.py's own _cap_seeded_amounts uses for its (ephemeral,
    # in-memory) cross-stream cap seeding.
    earlier_week_cross_stream_seeded_usd: Dict[tuple[int, int], float] = field(
        default_factory=dict
    )
    # How much of submitted_notional_by_week's current total for a given ISO
    # week is SYNTHETIC ceiling-topping injected by
    # force_week_notional_to_worst_case_ceiling's fail-closed path (as
    # opposed to real spend or a real reconciled cross-stream total).
    # reconcile_earlier_week_cross_stream_notional subtracts this back out
    # before reconciling, so a transient earlier-week scan failure doesn't
    # leave the weekly bucket permanently pinned at the ceiling once a later
    # invocation's scan succeeds (mirrors morning_dca.py's own
    # _cap_seed_poison_week fix for the identical failure mode).
    earlier_week_cross_stream_poison_usd: Dict[tuple[int, int], float] = field(
        default_factory=dict
    )
    weekly_rollover_reserve_usd: float = 0.0
    selected_tier: Optional[BudgetTier] = None
    finalized_budget_days: Set[date] = field(default_factory=set)
    # ISO-week key the current ``weekly_rollover_reserve_usd`` was computed for.
    # Guards the roll-forward so it runs exactly once per week, independent of the
    # order in which days are finalized vs. queried (a quiet week with no BUY
    # candidates must still roll the reserve before that day is finalized).
    reserve_week_key: Optional[tuple[int, int]] = None
    # (ticker, trading_day) pairs THIS state instance has booked its own order
    # for -- via a fresh placement or a same-stream duplicate-preserved retry.
    # Deliberately separate from buys_by_ticker_by_day: _seed_prior_allocations
    # also calls record_buy (to seed CROSS-stream morning/midday context into
    # this ticker's day/week spend), which bumps buys_today to a nonzero value
    # with no order of THIS stream's own ever booked. A same-stream duplicate
    # check keyed off buys_today alone would then wrongly treat a freshly
    # restarted process's never-recorded afternoon order as already booked
    # (Codex review, PR #231: "Record the recovered buy separately from seeded
    # prior context").
    own_orders_recorded: Set[Tuple[Any, ...]] = field(default_factory=set)
    # Companion to own_orders_recorded: the broker order_id a fractional-
    # placement recovery booked for (ticker, trading_day), keyed the SAME
    # bare way ordinary bookings use -- so a later same-run duplicate-order
    # lookup can tell "this broker row IS the recovered order" (safe to
    # suppress a second record_buy) apart from "a genuinely DIFFERENT order
    # for the same ticker/day" (e.g. a distinct top-up, or an afternoon
    # order after reconciling a morning claim), which must still be booked.
    # Membership in own_orders_recorded alone could not draw that
    # distinction: it only ever recorded ticker+day, so any later same-
    # ticker/day broker order -- recovered or not -- looked identical to
    # the one already accounted for (Codex review, PR #911 round 18:
    # "Compare order IDs before suppressing duplicate booking"). Deliberately
    # NOT persisted, for the identical reason own_orders_recorded is not:
    # it exists only to guard in-process retries reusing the same
    # StrategyState instance, never a full process restart.
    #
    # A SET per ticker/day, not a single scalar id: two distinct unresolved
    # reference groups for the SAME ticker/day (a plain placement and a
    # later "-topup-" retry, or a morning claim reconciled alongside an
    # afternoon one) are two separate broker orders, and a single call
    # OVERWRITES whatever a prior call this same run already recorded here.
    # A scalar id let the SECOND recovery's id silently replace the
    # FIRST's, so when the duplicate-order lookup below later found the
    # first (now-orphaned) order, its id no longer matched anything this
    # dict remembered -- read as "a genuinely different order", it was
    # booked a second time, doubling its notional/attempt count (Codex
    # review, PR #911 round 25: "Track every recovered order ID per
    # ticker and day").
    own_recovered_order_ids: Dict[Tuple[str, date], Set[str]] = field(default_factory=dict)
    # The run_id of every SOURCE ARTIFACT whose ambiguous placement THIS
    # process's own reconciliation has restored an attempt for, per
    # (ticker, trading_day). A same-stream retry's prior-allocation scan
    # (_seed_prior_allocations, fed by load_prior_same_day_allocations)
    # can independently discover the SAME crashed run's own unresolved
    # candidate as cross-stream context and re-seed its attempt a second
    # time -- book_reconciled_attempt_notional's own synthetic
    # own_orders_recorded key (deliberately NOT the bare (ticker,
    # trading_day) shape -- see that field's own docstring) does not
    # satisfy _seed_prior_allocations' bare-tuple exclusion check, so
    # nothing there recognized this attempt as already counted (Codex
    # review, PR #911 round 30: "Avoid reseeding a recovered earlier-slot
    # attempt"). Matched against PriorSameDayAllocation.attempt_run_ids --
    # the exact same run-identity signal load_prior_same_day_allocations_
    # multi already tracks for its own mirrored-artifact dedup -- so only
    # an allocation ENTIRELY explained by already-recovered run_ids is
    # skipped; a ticker with genuinely separate evidence from another
    # slot is still folded in normally, preserving the reason
    # own_orders_recorded was kept synthetic rather than bare in the
    # first place. Deliberately NOT persisted, for the identical reason
    # own_recovered_order_ids is not.
    own_recovered_attempt_run_ids: Dict[Tuple[str, date], Set[str]] = field(default_factory=dict)
    # Every broker order_id whose attempt (a `record_buy` call of any kind --
    # a fresh placement, a duplicate-order booking, or a
    # `book_reconciled_attempt_notional` restore/no-op) has been durably
    # counted toward `buys_by_ticker_by_day`/`submitted_order_count_by_day`
    # for that (ticker, trading_day), keyed the same bare way
    # `own_recovered_order_ids` is. Unlike `own_recovered_order_ids` and
    # `own_recovered_attempt_run_ids`, this DOES survive
    # save_strategy_state()/load_strategy_state() -- it is the durable,
    # per-order answer `book_reconciled_attempt_notional`'s own docstring
    # says this codebase was missing: whether a POSITIVE `buys_today()` for
    # a ticker/day is explained by THIS EXACT order_id (already counted;
    # restoring again would double-book it) or by a genuinely different
    # order for the same ticker/day (never counted; must still be
    # restored). A run-scoped, in-memory set like `own_recovered_order_ids`
    # cannot answer that across a process restart -- reloaded fresh every
    # invocation, it is empty on the very first reconciliation pass for an
    # order no matter how many UNRELATED buys already sit in
    # `buys_today()` for that ticker/day (Codex review on PR #1164/#1165:
    # "Restore recovered attempts after unrelated same-ticker buys").
    # Populated only when `order_id` is actually known -- an id-less call
    # (e.g. the immediate zero-dollar charge an ambiguous placement makes
    # before any order_id is ever discovered, see
    # `book_reconciled_attempt_notional`'s own docstring) has nothing to
    # register here and keeps relying on the older aggregate heuristic,
    # since there is no per-order key available to disambiguate it either.
    recorded_attempt_order_ids: Dict[Tuple[str, date], Set[str]] = field(default_factory=dict)
    # How much prior-context has already been folded in via
    # reconcile_prior_allocation, per (ticker, trading_day) -- so a LATER
    # invocation's fresh scan discovering MORE evidence for a ticker already
    # seeded (e.g. a manual fill written between the original run and its
    # retry) tops up only the newly-discovered delta, instead of the old
    # buys_today()==0 gate treating any prior count as proof the aggregate
    # was already complete and skipping the ticker forever (Codex review:
    # "Reconcile increases to already-seeded ticker allocations"). Mirrors
    # buys_by_ticker_by_day's own nested ticker -> {day: value} shape so it
    # round-trips through the same date-dedup/normalization machinery.
    seeded_prior_context_amount_by_ticker_day: Dict[str, Dict[date, float]] = field(
        default_factory=dict
    )
    seeded_prior_context_attempts_by_ticker_day: Dict[str, Dict[date, int]] = field(
        default_factory=dict
    )
    # How many order_ids THIS aggregate (seed_prior_allocation/
    # reconcile_prior_allocation for one ticker/day) has itself registered
    # into recorded_attempt_order_ids so far -- distinct from that set's
    # own size, which is GLOBAL across every source (real record_buy()
    # calls included) for the ticker/day. Mirrors seeded_prior_context_
    # attempts_by_ticker_day's own nested ticker -> {day: value} shape.
    seeded_prior_context_registered_id_count_by_ticker_day: Dict[str, Dict[date, int]] = field(
        default_factory=dict
    )
    # The cumulative SUM of every attempt_delta reconcile_prior_allocation
    # has itself proven for this ticker/day -- i.e. attempts THIS aggregate
    # has actually ADDED to buys_by_ticker_by_day across all its calls.
    # Deliberately NOT the same as seeded_prior_context_attempts_by_ticker_
    # day (already_attempts), which on this ticker/day's first-ever call
    # ABSORBS whatever buys_today() already held -- possibly attempts from
    # a genuinely UNRELATED real order -- as a conservative baseline for
    # attempt-COUNT reconciliation. Using that absorbed total for ID-
    # backfill room let a first call for order Y (no new attempt_count)
    # attach Y's id to an unrelated order's own anonymous attempt: fresh
    # evidence is `record_buy(..., order_id=None)` (an unrelated attempt
    # with no id) followed by `reconcile_prior_allocation(..., attempt_
    # count=1, order_ids=["Y"])`, where the absorbed baseline made room
    # look nonzero even though THIS aggregate had proven zero attempts of
    # its own so far (Codex review, PR #1168: "Restrict ID backfills to
    # seeded anonymous attempts"). This field only ever grows by an actual
    # `attempt_delta`, never by absorption, so it can never be inflated by
    # attempts this aggregate did not itself prove.
    seeded_prior_context_proven_attempts_by_ticker_day: Dict[str, Dict[date, int]] = field(
        default_factory=dict
    )
    # Callbacks a caller queues to defer work (e.g. writing its own "this is
    # durably booked" artifact marker) that must never run before the
    # record_buy()/etc. mutation it is vouching for has actually reached
    # disk. dca_runner.state_transaction() runs every queued callback --
    # ALL of them, even after one raises -- immediately after its own
    # save_strategy_state() call returns without raising, then clears this
    # list; a callback queued here and never run because the save itself
    # raised is correct, not a bug, since the state it describes was never
    # durably committed either (Codex review: "Mark recovery only after
    # committing StrategyState"). Not persisted (``repr=False,
    # compare=False``) -- these are in-process closures with no meaningful
    # on-disk representation, exactly like own_orders_recorded and its
    # neighbors above.
    pending_durable_commit_callbacks: List[Callable[[], None]] = field(
        default_factory=list, repr=False, compare=False
    )

    def buys_today(self, ticker: str, trading_day: date) -> int:
        return self.buys_by_ticker_by_day.get(ticker, {}).get(trading_day, 0)

    def record_buy(
        self,
        ticker: str,
        trading_day: date,
        notional_usd: float,
        order_id: Optional[str] = None,
    ) -> None:
        # Normalized on entry -- see _normalized_order_id's own docstring --
        # so every downstream use (recorded_attempt_order_ids membership)
        # compares against the same string shape every other order-id
        # comparison in this module uses.
        order_id = _normalized_order_id(order_id)
        self.buys_by_ticker_by_day.setdefault(ticker, {})
        self.buys_by_ticker_by_day[ticker][trading_day] = (
            self.buys_today(ticker, trading_day) + 1
        )
        self.submitted_notional_by_day[trading_day] = (
            self.day_notional(trading_day) + notional_usd
        )
        self.submitted_notional_by_week[iso_week_key(trading_day)] = (
            self.week_notional(trading_day) + notional_usd
        )
        self.submitted_order_count_by_day[trading_day] = (
            self.day_order_count(trading_day) + 1
        )
        # See recorded_attempt_order_ids' own docstring: an id-less call
        # (the common case -- most call sites have no order_id handy, or
        # genuinely none exists yet) simply registers nothing, exactly as
        # before this parameter existed.
        if order_id:
            self.recorded_attempt_order_ids.setdefault((ticker, trading_day), set()).add(order_id)

    def backfill_known_order_id(self, ticker: str, trading_day: date, order_id: Optional[str]) -> None:
        """Register a KNOWN order id against an attempt already durably
        recorded through some OTHER path -- never bumps
        ``buys_today()``/``day_notional()``, only attaches provenance to an
        attempt count that already exists.

        For a caller that skips its own ``record_buy()`` call because the
        order is already durably recorded elsewhere (e.g.
        ``_book_recovered_lease_durably`` finding the recovery already on
        disk in another stream's artifact) but still KNOWS the order's id.
        Leaving it anonymous lets a later, genuinely different same-ticker
        ambiguous order mistake this attempt's own count for its own
        already-durable charge and decline to restore its own attempt
        (Codex review, PR #1168: "Backfill IDs when a recovered lease is
        already on disk").

        Bounded by the SAME "never exceed ``buys_today()``'s own room"
        invariant every other id-registration path in this class enforces
        (see ``seed_prior_allocation``'s own docstring): registering a
        known id here for an attempt this call did NOT itself just prove
        landed would let ``len(recorded_attempt_order_ids[...])`` exceed
        ``buys_by_ticker_by_day[...]``, the exact invariant
        ``dca_runner._state_from_json`` enforces on reload.
        """
        order_id = _normalized_order_id(order_id)
        if not order_id:
            return
        _already_recorded = self.recorded_attempt_order_ids.get((ticker, trading_day), set())
        if order_id in _already_recorded:
            return
        if len(_already_recorded) < self.buys_today(ticker, trading_day):
            self.recorded_attempt_order_ids.setdefault((ticker, trading_day), set()).add(order_id)

    def book_reconciled_attempt_notional(
        self,
        ticker: str,
        trading_day: date,
        notional_usd: float,
        order_id: Optional[str] = None,
        source_run_id: Optional[str] = None,
    ) -> None:
        """Book spend for an attempt whose zero-dollar charge SHOULD already exist.

        An ambiguous placement is charged as an attempt (``record_buy(..., 0.0)``)
        before its run exits. If a LATER invocation proves that order was
        accepted, only its dollars are usually missing -- but the run that
        raised may have written its failure ARTIFACT and then died before
        ``state_transaction()``'s own final save durably persisted that
        zero-dollar charge. This fresh ``StrategyState`` would then carry no
        attempt for the ticker at all: adding only notional here left
        ``buys_today()``/``day_order_count()`` short by one, letting the
        shared ``max_orders_per_day`` breaker authorize one extra unrelated
        live order (Codex review, PR #911: "Restore the attempt count when
        durable state missed the failure"). Restoring it here, gated on
        whether it is already present, keeps both outcomes correct: a
        persisted charge gets notional added on top of it; a lost one gets
        the full ``record_buy`` treatment, attempt included.

        Gated on ``buys_today() <= len(already-recovered order ids for this
        ticker/day)`` PLUS an identity check, not a bare ``buys_today() <=
        0``: two DISTINCT unresolved references for the same ticker/day (a
        plain placement and a later "-topup-" retry, say) can BOTH need
        their attempt restored when neither's zero-dollar charge survived
        the crash, and a ticker-level "any buy already exists" check cannot
        tell that apart from "the first recovery's own record_buy call is
        what pushed buys_today above zero". With a bare ``<= 0`` gate, the
        first recovery restores its attempt and every LATER one for the
        same ticker/day then sees ``buys_today() > 0`` and silently skips
        its own restoration -- so ``day_order_count()`` stays short by
        however many recoveries were skipped, and the shared
        ``max_orders_per_day`` breaker can authorize that many orders past
        its own cap (Codex review, PR #911 round 27: "Restore each missing
        reconciliation attempt independently"). ``own_recovered_order_ids``
        already tracks one entry per DISTINCT order_id this run has
        recovered for this ticker/day (added at the end of this same call,
        when ``order_id`` is known) -- its size before this call is exactly
        how many attempts THIS function has already restored, so comparing
        ``buys_today()`` against it (rather than against zero) lets each new
        order_id still claim its own restoration once the count catches up.
        The identity check (is THIS order_id already IN that set) handles
        the mirror case the count alone cannot: a call repeating an
        order_id ALREADY recovered (e.g. a duplicate reconciliation pass)
        must still skip restoration even though the count-based comparison
        alone might otherwise permit it. An order_id-less legacy call never
        grows that set and never matches the identity check, so it keeps
        comparing against zero exactly as before -- there is nothing here
        to disambiguate a second such call from the first.

        Marked under a RECOVERY-SPECIFIC ``own_orders_recorded`` key, never
        the bare ``(ticker, trading_day)`` shape ordinary bookings use.
        ``_seed_prior_allocations`` reads that exact shape as "this stream
        already placed a real order for this ticker today, so its
        cross-stream aggregate is already accounted for" and skips folding
        in anything else discovered for it later this run -- which is wrong
        here: this order died before its OWN artifact could ever be scanned
        into that aggregate, so any OTHER slot's spend for this ticker
        still needs to be reconciled (Codex review, PR #911: "Preserve
        newly discovered cross-stream allocation context"). Mirrors
        ``_book_recovered_lease_durably``'s identical ``#imart-recovery``
        namespace, kept for the identical reason.
        """
        # Normalized on entry -- see _normalized_order_id's own docstring --
        # so every membership/equality check below compares against the
        # same string shape record_buy() and every other order-id
        # comparison in this module uses.
        order_id = _normalized_order_id(order_id)
        _recovered_ids_this_ticker_day = self.own_recovered_order_ids.get((ticker, trading_day), set())
        # Every order_id this (ticker, trading_day) has EVER durably
        # recorded an attempt for -- see recorded_attempt_order_ids' own
        # docstring. Unlike `_recovered_ids_this_ticker_day` above, this
        # survives a process restart.
        _durably_recorded_ids = self.recorded_attempt_order_ids.get((ticker, trading_day), set())
        # THIS exact order_id already claimed its own restoration on an
        # earlier call -- this run (own_recovered_order_ids) OR a prior one
        # (recorded_attempt_order_ids) -- never a second, independent
        # "missing attempt" no matter what the count-based check below
        # would otherwise allow.
        _already_restored_this_order = order_id is not None and (
            order_id in _recovered_ids_this_ticker_day or order_id in _durably_recorded_ids
        )
        # A Codex review on PR #1164 ("Restore recovered attempts after
        # unrelated same-ticker buys") pointed out that the original
        # count-based gate (`buys_today() <= len(_recovered_ids_this_ticker
        # _day)`, with no adjustment below) can skip restoration it SHOULD
        # have performed: if `ticker` already has an unrelated,
        # already-persisted buy today (a genuinely separate order this
        # function was never asked to reconcile) and THIS call is the
        # first reconciliation this run for a DIFFERENT unproven group on
        # the same ticker/day, `buys_today() > 0` while
        # `_recovered_ids_this_ticker_day` is still empty -- the exact same
        # shape the gate reads as "already durably recorded, do not
        # restore" in the far more common case the gate exists for.
        #
        # That far more common case is real and cannot be dropped: an
        # ambiguous placement's own immediate, synchronous `record_buy(...,
        # 0.0)` call (a separate code path from this whole reconciliation
        # function) routinely DOES persist normally, with no crash at all
        # -- the run just writes its failure artifact and exits, leaving
        # `placement_outcome_unproven=True` for a LATER, unrelated
        # reconciliation pass to pick up. `buys_today()` already reflects
        # that attempt in this ordinary case, and restoring it here would
        # double-book it. Critically, that immediate charge has NO
        # order_id available to it at call time (the placement call itself
        # raised before any id was known -- see UnresolvedPlacementError's
        # own docstring), so it can never register itself in
        # `recorded_attempt_order_ids` either: a POSITIVE `buys_today()`
        # excess left AFTER subtracting every OTHER order_id this ticker/
        # day durably knows about is still ambiguous between (a) this exact
        # order's own already-durable, id-less charge (must NOT restore)
        # and (b) a genuinely different, also-id-less attempt for the same
        # ticker (MUST restore) -- both look identical, and neither
        # `own_recovered_order_ids` nor `recorded_attempt_order_ids` nor
        # anything else this class or the persisted artifact tracks can
        # ever record an id that was never assigned. That residual
        # ambiguity is inherent, not a gap left to close (Codex review on
        # PR #1164/#1165: confirmed no safe fix exists using only
        # currently-persisted data for the id-less case) -- resolving it
        # would need a durable pre-order-id correlation token this
        # codebase does not generate today. What `recorded_attempt_order_ids`
        # DOES resolve is the narrower, common case above: a genuinely
        # different order for the same ticker/day that DOES carry a known,
        # durably-recorded id (e.g. an ordinary successful placement, or an
        # earlier reconciliation) is no longer mistaken for THIS order's
        # own charge, because its id is excluded from the comparison below
        # by name rather than folded anonymously into the aggregate count.
        #
        # Also excludes every id already in `_recovered_ids_this_ticker_day`
        # (Codex review on this PR: "Exclude same-run recoveries from the ID
        # adjustment"). Those ids are ALREADY counted on the other side of
        # the comparison below, via `len(_recovered_ids_this_ticker_day)` --
        # subtracting them here too double-credits them. Concretely: two
        # same-ticker orders A and B both already have their own persisted
        # zero-dollar attempt (buys_today() == 2), and this run reconciles
        # both. Processing A first correctly does NOT restore it (A's own
        # charge already landed) but still registers A's id in both
        # `own_recovered_order_ids` and `recorded_attempt_order_ids`
        # unconditionally (Codex review, PR #911 round 25: every id this
        # function ever resolves must be tracked, whether restored or not).
        # Without this exclusion, processing B next would subtract A's now-
        # known id from `buys_today()` (2 - 1 = 1) while ALSO counting A via
        # `len(_recovered_ids_this_ticker_day)` (= 1) on the right-hand side
        # -- `1 <= 1` wrongly restores B's already-persisted attempt too,
        # overstating the daily order count by one and risking a premature
        # `max_orders_per_day` trip. Restricting `_other_known_ids` to ids
        # this exact function has NOT already folded into
        # `_recovered_ids_this_ticker_day` this run keeps each known id
        # counted on exactly one side of the comparison.
        # The per-ID subtraction below is applied ONLY when THIS call
        # supplies a usable `order_id` of its own -- an ID-LESS legacy
        # call has no identity evidence that its own attempt is a
        # DIFFERENT order than whatever `_durably_recorded_ids` already
        # knows about, so subtracting them anyway wrongly manufactures a
        # positive `_adjusted_buys_today` excess this call's own count
        # never actually proved: after `record_buy(..., order_id="X")`,
        # an id-less `book_reconciled_attempt_notional()` call for the
        # SAME ticker/day used to change the comparison from "already
        # recorded, do not restore" to "restore", double-charging an
        # attempt that already landed and prematurely exhausting
        # `max_orders_per_day` (Codex review, PR #1168: "Keep ID-less
        # reconciliations on the aggregate gate"). An id-less call keeps
        # comparing against the RAW `buys_today()` aggregate, exactly as
        # the original count-based gate did before per-ID subtraction
        # existed.
        _other_known_ids = (
            (_durably_recorded_ids - _recovered_ids_this_ticker_day - {order_id}) if order_id else set()
        )
        _adjusted_buys_today = self.buys_today(ticker, trading_day) - len(_other_known_ids)
        if not _already_restored_this_order and _adjusted_buys_today <= len(_recovered_ids_this_ticker_day):
            self.record_buy(ticker, trading_day, notional_usd, order_id=order_id)
        else:
            self.submitted_notional_by_day[trading_day] = (
                self.day_notional(trading_day) + notional_usd
            )
            self.submitted_notional_by_week[iso_week_key(trading_day)] = (
                self.week_notional(trading_day) + notional_usd
            )
        # roll_weekly_reserve() memoizes weekly_rollover_reserve_usd per
        # reserve_week_key, computed from submitted_notional_by_week[the
        # most recent EARLIER week] -- and this call can just have raised
        # exactly that figure for a PRIOR week (this is the recovery path
        # that routinely books evidence for an earlier trading day/week,
        # unlike an ordinary same-day record_buy). If the reserve for the
        # CURRENT week was already computed before this booking landed,
        # it keeps granting rollover capacity based on a now-stale, too-
        # generous "unused last week" estimate until the reserve happens
        # to be recomputed for some unrelated reason (Codex review, PR
        # #911 round 21: "Invalidate rollover reserve after prior-week
        # recovery"). Invalidated only when this booking could plausibly
        # be the basis the cached reserve used -- a week strictly BEFORE
        # the cached reserve_week_key -- and only when real dollars moved;
        # a $0 rejection changes nothing roll_weekly_reserve would read
        # differently.
        if notional_usd:
            _notional_week_key = iso_week_key(trading_day)
            if self.reserve_week_key is not None and _notional_week_key < self.reserve_week_key:
                self.reserve_week_key = None
            # `roll_weekly_reserve` only ever considers a week a candidate
            # "prior week" when at least one of its days is IN
            # `finalized_budget_days` -- and the run that would ordinarily
            # have added `trading_day` there is exactly the run that
            # crashed before reaching `finalize_daily_budget`, which is
            # why this recovery exists at all. Invalidating
            # `reserve_week_key` alone is not enough: it forces the NEXT
            # `roll_weekly_reserve` call to recompute, but that recompute
            # still filters `finalized_budget_days` for a week strictly
            # before the CURRENT week, and without `trading_day` in that
            # set, this exact week -- now the most recent one with real
            # activity -- is invisible to it, so an older, unrelated
            # finalized week gets used instead (a stale, too-generous
            # reserve if that older week happened to be quieter, or a
            # too-strict one if noisier) -- either way, the ceiling
            # `effective_weekly_cap()` grants is wrong for the reason this
            # recovery exists (Codex review, PR #1164: "Include recovered
            # weeks when recomputing rollover reserve"). Added
            # unconditionally, not gated on whether the day was already
            # finalized -- `finalize_daily_budget` itself is a no-op on a
            # day already present, and a day that WAS already finalized
            # normally (the ordinary case) is already exactly the day this
            # call would try to add again.
            self.finalized_budget_days.add(trading_day)
        self.own_orders_recorded.add((f"{ticker}#fractional-recovery", trading_day))
        # See own_recovered_order_ids's own docstring: recorded under the
        # BARE (ticker, trading_day) key so the duplicate-order check below
        # can look it up with the same key it already computes, and only
        # when an id is actually known -- a rejection this same call
        # notionally books at $0 may still name a real (declined) order,
        # and an older/legacy call site with no id to offer must not
        # overwrite a real one recorded by an earlier call this run. Added
        # to the set for this ticker/day, never assigned over it -- a
        # SECOND distinct recovery for the same ticker/day (two separate
        # broker orders) must not erase the FIRST's id (Codex review, PR
        # #911 round 25: "Track every recovered order ID per ticker and
        # day").
        if order_id:
            self.own_recovered_order_ids.setdefault((ticker, trading_day), set()).add(order_id)
            # See recorded_attempt_order_ids' own docstring -- durable
            # counterpart to own_recovered_order_ids above, added
            # unconditionally (not only on the restore branch) so a later
            # reconciliation, in THIS run or a future one, can tell this
            # exact order_id apart from a genuinely different order for the
            # same ticker/day even when this call took the "already
            # recorded elsewhere" branch. record_buy() already adds it on
            # the restore branch; harmless (sets are idempotent) to add it
            # again here.
            self.recorded_attempt_order_ids.setdefault((ticker, trading_day), set()).add(order_id)
        # See own_recovered_attempt_run_ids's own docstring: recorded so
        # _seed_prior_allocations can recognize when a same-stream retry's
        # prior-allocation scan rediscovers THIS exact crashed run as
        # cross-stream context and skip re-seeding an attempt this call
        # already restored.
        if source_run_id:
            self.own_recovered_attempt_run_ids.setdefault((ticker, trading_day), set()).add(source_run_id)

    def seed_prior_allocation(
        self,
        ticker: str,
        trading_day: date,
        notional_usd: float,
        attempt_count: int,
        order_ids: Optional[Iterable[str]] = None,
    ) -> None:
        """Restore CROSS-run/cross-slot allocation context reconstructed from
        prior artifacts -- not a placement by this process. Unlike
        ``record_buy`` (always exactly +1 attempt, for a single real
        placement this process just made), this seeds the RECONSTRUCTED
        attempt count: an earlier slot may have made several attempts for
        the same ticker (including rejected/canceled ones that moved no
        capital), and each one still consumed one of the shared
        ``max_orders_per_day`` slots (config/budgets.json:
        "Counted as buy ATTEMPTS ... a cancelled or rejected buy still
        consumes one -- the conservative direction"). Collapsing several
        attempts into ``notional_usd`` (already pre-summed by the caller)
        while only bumping the attempt counters by 1 would let
        ``day_order_count()`` undercount and permit more real orders than
        the shared cap allows (Codex review: "Count every prior buy attempt
        toward the daily limit").

        ``order_ids`` -- when the caller can name any of the KNOWN broker
        order_ids this seeded aggregate is composed of (e.g.
        ``PriorSameDayAllocation.contributing_order_ids``) -- registers each
        into ``recorded_attempt_order_ids``, the same durable per-order
        ledger ``record_buy()`` populates. Without this, a seeded aggregate
        inflates ``buys_today()`` with NO known order_id backing it, so
        ``book_reconciled_attempt_notional``'s adjusted-count gate cannot
        tell that excess apart from "this exact ambiguous order's own
        already-durable charge" and wrongly declines to restore a genuinely
        different order's attempt (Codex review, PR #1164/#1165: "Preserve
        attempts hidden by seeded prior allocations"). Safe to register
        every KNOWN id here even when ``attempt_count`` also includes
        unidentified attempts this call has no id for -- each id in
        ``order_ids`` represents a real, dollar-contributing row this
        allocation is already counting, so it can never exceed the
        attempts being added. ``dca_runner._state_from_json`` independently
        enforces the same "recorded ids never exceed the buy ledger" bound
        on reload, so a future violation of this assumption fails closed
        rather than silently misbehaving.
        """
        # Each id normalized on entry -- see _normalized_order_id's own
        # docstring -- for the same reason record_buy()/
        # book_reconciled_attempt_notional() normalize their own order_id.
        order_ids = [_normalized_order_id(oid) for oid in (order_ids or ())]
        self.buys_by_ticker_by_day.setdefault(ticker, {})
        self.buys_by_ticker_by_day[ticker][trading_day] = (
            self.buys_today(ticker, trading_day) + attempt_count
        )
        self.submitted_notional_by_day[trading_day] = (
            self.day_notional(trading_day) + notional_usd
        )
        self.submitted_notional_by_week[iso_week_key(trading_day)] = (
            self.week_notional(trading_day) + notional_usd
        )
        self.submitted_order_count_by_day[trading_day] = (
            self.day_order_count(trading_day) + attempt_count
        )
        # Capped at `attempt_count` for the identical reason
        # `reconcile_prior_allocation`'s own registration is capped at
        # `attempt_delta` -- THIS call only ever proves `attempt_count`
        # NEW attempts landed, so registering more distinct ids than that
        # would let `len(recorded_attempt_order_ids[...])` exceed
        # `buys_by_ticker_by_day[...]`, the exact invariant
        # `dca_runner._state_from_json` enforces on reload (Codex review,
        # PR #1164/#1165: "Avoid attaching scanned IDs to an unrelated
        # attempt baseline").
        # Compared against ids not already recorded, not the whole
        # `order_ids` set -- the identical reasoning `reconcile_prior_
        # allocation`'s own registration uses (see its own comment): a
        # caller passing a CUMULATIVE id set across repeat calls must not
        # have an already-registered id (from an earlier call) count
        # against THIS call's own new-attempt room.
        _already_recorded_ids = self.recorded_attempt_order_ids.get((ticker, trading_day), set())
        # Deduplicated via `dict.fromkeys` (order-preserving), not a plain
        # list comprehension: a caller passing repeated ids, or spellings
        # that normalize identically, for the SAME physical order --
        # `order_ids=["A", "A"]` -- otherwise counted that one id TWICE
        # against `attempt_count`, so a single genuinely proven attempt
        # failed `len(...) <= attempt_count` and registered NO provenance
        # at all even though the id was perfectly usable. A later
        # reconciliation for a different order then mistook the resulting
        # anonymous seeded attempt for its own prior charge (Codex review,
        # PR #1169: "Deduplicate order IDs before seed registration").
        _new_order_ids = list(dict.fromkeys(
            oid for oid in (order_ids or ()) if oid and oid not in _already_recorded_ids
        ))
        if _new_order_ids and len(_new_order_ids) <= attempt_count:
            for _order_id in _new_order_ids:
                self.recorded_attempt_order_ids.setdefault((ticker, trading_day), set()).add(_order_id)

    def reconcile_prior_allocation(
        self,
        ticker: str,
        trading_day: date,
        amount_usd: float,
        attempt_count: int,
        order_ids: Optional[Iterable[str]] = None,
    ) -> None:
        """Idempotently top up a ticker's seeded prior-context to match a
        freshly re-scanned aggregate, adding only the newly-discovered delta.

        ``order_ids`` -- see ``seed_prior_allocation``'s own docstring --
        describes the CUMULATIVE known-id aggregate on every call, not just
        this call's own delta portion. Only the ids not already registered
        for this (ticker, trading_day) are candidates for registration, and
        only when there are no more of them than this call's own
        ``attempt_delta`` proves landed: a caller passing the same growing
        aggregate across repeat calls (first call finds order A, a later
        call finds A+B) must not have the already-known A count against the
        room the second call's own delta (covering only B) proves (Codex
        review, PR #1164/#1165: "Register newly discovered IDs from
        cumulative scans"). A zero-delta call registers nothing new, even
        though every id in ``order_ids`` may already be durably reflected
        in ``buys_today()`` from an earlier pass -- there is nothing new to
        prove in that case, and nothing lost either, since those ids were
        already registered when the delta that covered them landed.

        ``_seed_prior_allocations`` used to gate seeding on
        ``buys_today(ticker, trading_day) == 0``, treating ANY prior count as
        proof the ticker's aggregate was already fully accounted for. But a
        RETRY re-scans artifacts fresh each time, and can discover MORE
        evidence for a ticker already seeded on an earlier pass -- e.g. a
        manual fill for this ticker written between the original 15:30 run
        and its retry raises the aggregate from $2/1 attempt to $4/2
        attempts. The old gate skipped the ticker entirely once ANY prior
        count existed, so neither the extra $2 nor the extra attempt were
        ever folded in, letting the retry exceed the dollar or
        ``max_orders_per_day`` cap (Codex review: "Reconcile increases to
        already-seeded ticker allocations").

        Tracks how much has already been seeded via THIS mechanism, per
        (ticker, trading_day), in ``seeded_prior_context_amount_by_ticker_day``
        /``..._attempts_by_ticker_day`` -- separate from ``buys_today()``,
        which also reflects this stream's OWN real orders (via
        ``record_buy``). Conflating the two would double-count: the caller
        must gate this call on ``(ticker, trading_day) not in
        own_orders_recorded`` so a ticker this stream has already bought for
        real today is never topped up here (its own record_buy call already
        accounts for it).

        ``own_orders_recorded`` is deliberately NOT persisted across a full
        process restart (it exists only to guard in-process retries reusing
        the same ``StrategyState``), so a fresh reload of a state that
        already has ``buys_today(ticker, trading_day) > 0`` -- from THIS
        stream's own real order recorded before a crash, or from a
        pre-this-fix ``seed_prior_allocation`` call -- looks identical to a
        brand-new ticker to the caller's gate. When THIS specific
        (ticker, trading_day) has never been tracked here before AND
        ``buys_today()`` is already positive, that ambiguity is resolved
        conservatively: the exact, ticker-specific ``buys_today()`` count
        becomes the attempt baseline (so attempts are still counted
        precisely), but the dollar baseline defaults to THIS call's own
        ``amount_usd`` rather than 0 -- ``submitted_notional_by_day`` is a
        DAY-level aggregate, not ticker-keyed, so there is no reliable way to
        recover exactly how many of those dollars belong to this ticker
        already; assuming none of the freshly-scanned total is new avoids
        ever re-adding dollars that may already be recorded, at the cost of
        not crediting a genuinely new cross-stream dollar contribution
        discovered in that same ambiguous call -- the same conservative
        trade-off ``buys_today() == 0`` already made for this exact
        combination before this fix existed.
        """
        # Each id normalized on entry -- see _normalized_order_id's own
        # docstring.
        order_ids = [_normalized_order_id(oid) for oid in (order_ids or ())]
        tracked_attempts = self.seeded_prior_context_attempts_by_ticker_day.get(
            ticker, {}
        ).get(trading_day)
        if tracked_attempts is None:
            already_attempts = self.buys_today(ticker, trading_day)
            # The ambiguous-absorption baseline treats the WHOLE scanned
            # `amount_usd` as already covered by `already_attempts`'s
            # existing dollars -- correct when it is genuinely unknown
            # whether the scan is redescribing those same existing
            # attempts (id-aliasing across data sources is a real, known
            # hazard here, so ATTEMPT COUNTING stays conservative and
            # never trusts id disjointness alone -- see the sibling
            # "Avoid attaching scanned IDs to an unrelated attempt
            # baseline" fix a few hundred lines below for why). But
            # `order_ids` (fully identified orders this scan already
            # named) DOES prove the scanned DOLLARS are not already
            # covered whenever EVERY one of the existing attempts is
            # ALSO a known, recorded id (`len(_already_recorded_ids) ==
            # already_attempts` -- nothing anonymous is hiding among
            # them) and NONE of those recorded ids appears among the ids
            # THIS aggregate just supplied: a scan naming known orders A
            # and B for a ticker whose only prior attempt is a fully-
            # identified, provably-different order X must not treat A+B's
            # own dollars as already-recorded just because X exists --
            # that dollar amount belongs to A/B, which are proven
            # unrelated to X (Codex review, PR #1168: "Use disjoint order
            # IDs before absorbing the baseline"). Falls back to the
            # original absorption whenever any existing attempt is
            # anonymous (no id to compare) or genuinely overlaps.
            _already_recorded_ids = self.recorded_attempt_order_ids.get((ticker, trading_day), set())
            # `order_ids` proves the whole scanned amount_usd disjoint only
            # when it identifies EVERY attempt THIS scan itself counted, not
            # merely "at least one usable id, disjoint from what's already
            # known". A two-attempt/$7 scan naming only ONE new id (A) --
            # its other row being the SAME already-known order X, just
            # supplied with no usable id this time -- has `order_ids={A}`
            # disjoint from `_already_recorded_ids={X}` under the old
            # bare-non-empty check, wrongly reading the ENTIRE $7 as new
            # and adding it to X's existing $5 for a $12 baseline that
            # should have stayed $7 (the second attempt IS X, already
            # counted, just anonymous in this particular scan). Only a
            # scan whose distinct usable ids cover `attempt_count` exactly
            # -- nothing anonymous hiding among ITS OWN rows either -- can
            # safely treat the whole amount as unrelated to the existing
            # baseline (Codex review, PR #1168: "Verify every scanned
            # attempt before treating IDs as disjoint").
            _usable_scanned_ids = {oid for oid in order_ids if oid}
            if (
                already_attempts > 0
                and order_ids
                and len(_already_recorded_ids) == already_attempts
                and len(_usable_scanned_ids) == attempt_count
                and not (_usable_scanned_ids & _already_recorded_ids)
            ):
                already_amount = 0.0
            else:
                # Bounded by the day's ACTUAL dollar ledger, not assumed to
                # equal the whole scanned `amount_usd`: absorbing the full
                # amount when the durable day ledger holds less left
                # `amount_delta` at 0, so the uncovered difference was never
                # credited via `seed_prior_allocation` below and the day
                # ledger (`submitted_notional_by_day`) never grew to match
                # the baseline this call is about to persist. A later
                # `save_strategy_state()` then rejected the state outright
                # because a single ticker's seeded amount exceeded the
                # day's total notional -- an invariant this bound now
                # preserves by crediting the gap instead of pretending it
                # is already covered (Codex review, PR #1169: "Keep
                # absorbed allocation baselines within the dollar
                # ledger").
                already_amount = min(amount_usd, self.day_notional(trading_day)) if already_attempts > 0 else 0.0
        else:
            already_attempts = tracked_attempts
            already_amount = self.seeded_prior_context_amount_by_ticker_day.get(
                ticker, {}
            ).get(trading_day, 0.0)
        # Reconciled INDEPENDENTLY, not gated on each other: a previously
        # seeded order's executed notional can grow (e.g. a partial fill
        # confirms more shares) across two scans with NO new attempt at all
        # -- attempt_delta stays 0 while amount_delta is genuinely positive.
        # Returning early whenever attempt_delta <= 0 (as a prior version of
        # this method did) skipped that dollar delta entirely, leaving the
        # daily/weekly ledgers understated even though the fresh allocation
        # proves the extra exposure (Codex review: "Reconcile notional when
        # the attempt count is unchanged").
        attempt_delta = max(0, attempt_count - already_attempts)
        amount_delta = max(0.0, amount_usd - already_amount)
        if attempt_delta > 0 or amount_delta > 0:
            self.seed_prior_allocation(ticker, trading_day, amount_delta, attempt_delta)
        # Grows ONLY by this call's own proven attempt_delta, never by the
        # ambiguous-branch absorption above -- see seeded_prior_context_
        # proven_attempts_by_ticker_day's own docstring for why that
        # distinction is exactly what keeps the ID-backfill room below
        # from claiming an unrelated order's own anonymous attempt.
        _prior_aggregate_proven_attempts = self.seeded_prior_context_proven_attempts_by_ticker_day.get(
            ticker, {}
        ).get(trading_day, 0)
        _aggregate_proven_attempts = _prior_aggregate_proven_attempts + attempt_delta
        # Persisted UNCONDITIONALLY, even when this call's own attempt_delta
        # is 0 -- an ordinary, common no-op reconciliation whenever a fresh
        # scan already matches the tracked baseline -- the same
        # "record the observed baseline regardless of whether anything
        # changed" convention seeded_prior_context_attempts_by_ticker_day/
        # ..._amount_by_ticker_day already follow a few lines below.
        # `dca_runner._state_from_json` loads this field through
        # `_nonneg_int`, not `_positive_int`, specifically because a genuine
        # `0` is a legitimate persisted value here (Codex review, PR #1169:
        # "Allow zero proven-attempt baselines to round-trip").
        self.seeded_prior_context_proven_attempts_by_ticker_day.setdefault(ticker, {})[
            trading_day
        ] = _aggregate_proven_attempts
        # Registering `order_ids` here is gated on `len(...) <= attempt_delta`
        # -- NOT on attempt_delta being merely positive, and NOT unconditionally
        # -- because `order_ids` describes every KNOWN id in the WHOLE
        # aggregate, not just this call's own delta portion. On a fresh
        # process where `buys_today()` already has an attempt from a
        # genuinely UNRELATED order X (e.g. this stream's own real
        # placement) and this call's aggregate describes a DIFFERENT order
        # Y with the same total attempt_count, the ambiguous baseline above
        # makes attempt_delta 0 -- registering Y's id anyway would leave
        # `recorded_attempt_order_ids` naming 2 distinct orders (X, Y) for
        # only 1 actual buy, an invariant `dca_runner._state_from_json`
        # itself enforces (recorded ids can never exceed the buy ledger),
        # so the very next save/reload would reject this state as corrupt
        # (Codex review, PR #1164/#1165: "Avoid attaching scanned IDs to an
        # unrelated attempt baseline"). The same risk exists even when
        # attempt_delta IS positive but smaller than `len(order_ids)`: not
        # every known id is provably part of the NEW delta. Only when every
        # NEWLY-SEEN known id can fit within the room this call's own delta
        # just proved is registering it safe; otherwise this call falls
        # back to the id-less heuristic for this ticker/day, exactly as it
        # did before `order_ids` existed.
        #
        # Compared against ids not already recorded, not against the whole
        # `order_ids` set: `order_ids` describes the CUMULATIVE aggregate on
        # every call, so a scan that grows incrementally (first call finds
        # order A, a later call finds A+B) has `attempt_delta == 1` for the
        # second call (only B is new) but `len(order_ids) == 2` -- comparing
        # the full cumulative count against the delta wrongly refused to
        # register even the one id (B) the delta DOES prove, leaving B
        # anonymous and able to mask a genuinely different order's own
        # restoration the same way this whole mechanism exists to prevent
        # (Codex review, PR #1164/#1165: "Register newly discovered IDs
        # from cumulative scans").
        #
        # Capped at THIS AGGREGATE's own anonymous-attempt room -- its own
        # tracked attempt total minus how many ids IT has itself already
        # registered -- not at `attempt_delta` alone, and NOT at the
        # ticker/day's GLOBAL anonymous-attempt count either. An id-less
        # attempt can be seeded first (e.g. `order_ids=[]`,
        # `attempt_count=1`) and only IDENTIFIED by a later scan that
        # observes no NEW attempt at all (`order_ids=["A"]`,
        # `attempt_count` unchanged), so `attempt_delta` is 0 even though
        # this call has just proven which already-counted attempt "A"
        # belongs to. Gating strictly on `attempt_delta` left "A" anonymous
        # forever, able to mask a genuinely different order's own
        # restoration the identical way an unregistered id always does
        # (Codex review, PR #1168: "Backfill IDs discovered without a new
        # attempt delta"). But bounding that room by the ticker/day's
        # GLOBAL `buys_today() - len(all recorded ids)` (a first version of
        # this fix did) let it claim an anonymous slot that belongs to a
        # genuinely UNRELATED real order instead: `record_buy(...,
        # order_id=None)` followed by this aggregate's own first-ever call
        # for a DIFFERENT known order Y (no new attempt_count) attached Y's
        # id to that unrelated order's own anonymous attempt, so a LATER
        # reconciliation for the real Y order saw Y's id as already durable
        # and declined to restore its own attempt (Codex review, PR #1168:
        # "Restrict ID backfills to seeded anonymous attempts"). Scoped
        # instead to `seeded_prior_context_registered_id_count_by_ticker_
        # day` (how many ids THIS aggregate has itself contributed) against
        # `seeded_prior_context_proven_attempts_by_ticker_day` (the
        # cumulative SUM of every attempt_delta this aggregate has itself
        # proven -- see that field's own docstring for why it, not
        # `already_attempts + attempt_delta`, is the safe bound: the latter
        # can include attempts this aggregate never proved at all, silently
        # absorbed as a conservative baseline on this ticker/day's first-
        # ever call).
        _already_recorded_ids = self.recorded_attempt_order_ids.get((ticker, trading_day), set())
        # Deduplicated via dict.fromkeys (order-preserving) BEFORE anything
        # below counts or registers these ids: a caller can supply the same
        # id twice, or two distinct spellings that normalize to the same
        # string (see _normalized_order_id), and `recorded_attempt_order_ids`
        # is a SET -- adding a duplicate grows it by zero. Counting the raw
        # (un-deduplicated) list's length for the registered-id-counter
        # increment below credited one MORE registered id than the set
        # actually gained, so a later `save_strategy_state` rejected the
        # resulting state once `seeded_prior_context_registered_id_count_
        # by_ticker_day` exceeded the real number of recorded ids (Codex
        # review, PR #1169: "Deduplicate normalized IDs before counting
        # backfill room").
        _order_ids_supplied = list(dict.fromkeys(oid for oid in (order_ids or ()) if oid))
        _new_order_ids = [oid for oid in _order_ids_supplied if oid not in _already_recorded_ids]
        # "Already consumed" room is the MAX of two independent counts, not
        # just the persisted counter -- an id THIS aggregate itself knows
        # about (it is in `order_ids`) can enter the GLOBAL ledger through
        # a completely different path (book_reconciled_attempt_notional's
        # own record_buy() call, not this method's own registration
        # branch), which never touches seeded_prior_context_registered_id_
        # count_by_ticker_day at all. `{unrelated attempt A already
        # recorded, then this aggregate reports attempts C+D}`: the first
        # scan proves 1 new attempt and registers neither id (both still
        # unknown); if C then gets recorded via that OTHER path, a repeat
        # scan with `order_ids=[C, D]` sees only D as genuinely new (C is
        # already globally recorded) but the persisted counter is still 0
        # -- so this condition still credits the full room to D alone,
        # registering it on top of C's ALREADY-consumed slot and leaving
        # 3 recorded ids for only 2 ledger attempts (Codex review, PR
        # #1168: "Count recorded aggregate IDs against the backfill
        # room"). Counting how many of THIS call's own supplied ids are
        # already globally recorded -- regardless of which path recorded
        # them -- closes that gap.
        # The cross-path term (`len(supplied) - len(new)`) is itself
        # bounded by the room that existed BEFORE this call's own
        # attempt_delta was added -- `_prior_aggregate_proven_attempts`
        # minus the persisted registered-id counter -- not left
        # unbounded. An id already recorded via ANOTHER path is only
        # correctly attributable to THIS aggregate's own proven capacity
        # when that capacity existed before this call ran (a cross-path
        # registration cannot have consumed room this call is only now
        # proving for the first time). Without this bound, an id that was
        # ALREADY recorded from before this aggregate mechanism ever
        # engaged at all -- e.g. its very first call already found the id
        # globally recorded, with zero proven attempts of its own at that
        # point -- permanently consumed one unit of "proven room" it never
        # actually needed. A LATER call proving a genuinely NEW id then
        # found that phantom consumption still counted against it, leaving
        # zero room for an id this exact call just proved
        # (`_aggregate_proven_attempts` rose by `attempt_delta`, but
        # `_aggregate_registered_so_far` rose by the SAME amount from the
        # stale already-recorded id, netting zero) (Codex review, PR
        # #1168: "Preserve backfill room for newly proven IDs").
        _cross_path_recorded_count = len(_order_ids_supplied) - len(_new_order_ids)
        _persisted_registered_count = self.seeded_prior_context_registered_id_count_by_ticker_day.get(
            ticker, {}
        ).get(trading_day, 0)
        _cross_path_recorded_count = min(
            _cross_path_recorded_count,
            max(0, _prior_aggregate_proven_attempts - _persisted_registered_count),
        )
        _aggregate_registered_so_far = max(_persisted_registered_count, _cross_path_recorded_count)
        _aggregate_room = max(0, _aggregate_proven_attempts - _aggregate_registered_so_far)
        # Also capped by the ticker/day's GLOBAL remaining ledger room --
        # buys_today() minus every id ALREADY recorded, from any path, not
        # just this aggregate's own contributions. The aggregate-scoped
        # room alone does not see ids another mechanism registered against
        # this same ticker/day: `backfill_known_order_id` can independently
        # consume the ticker/day's last anonymous attempt for an UNRELATED
        # id B, and a later call to reconcile THIS aggregate (now proving
        # a genuinely new id A) still computed room solely from its own
        # provenance counters, registering A anyway and leaving THREE
        # recorded ids for only two actual buys -- the exact invariant
        # `dca_runner._state_from_json` enforces on reload (Codex review,
        # PR #1169: "Cap aggregate ID backfills by the global ledger
        # room"). Taking the MIN of the two rooms, not replacing the
        # aggregate-scoped one with the global one, is what keeps this
        # safe: an earlier fix ("Restrict ID backfills to seeded anonymous
        # attempts") already rejected bounding by the GLOBAL room ALONE,
        # because that let this aggregate claim an anonymous slot
        # belonging to a genuinely unrelated real order. The global bound
        # here only ever makes registration MORE conservative on top of
        # the existing aggregate-scoped bound, never looser.
        _global_room = max(0, self.buys_today(ticker, trading_day) - len(_already_recorded_ids))
        _effective_room = min(_aggregate_room, _global_room)
        if _new_order_ids and len(_new_order_ids) <= _effective_room:
            for _order_id in _new_order_ids:
                self.recorded_attempt_order_ids.setdefault((ticker, trading_day), set()).add(_order_id)
            self.seeded_prior_context_registered_id_count_by_ticker_day.setdefault(ticker, {})[
                trading_day
            ] = _aggregate_registered_so_far + len(_new_order_ids)
        # Persisted UNCONDITIONALLY, even when both deltas are zero this
        # call: when tracked_attempts was None above (the ambiguous-branch
        # case, e.g. this ticker's first-ever reconcile call this process),
        # a scan that happens to exactly match the existing buys_today()
        # baseline computed BOTH deltas as zero and used to return before
        # ever reaching these two lines. That left the tracked dicts empty,
        # so the NEXT call re-entered the same ambiguous branch and
        # recomputed already_amount from THAT call's own (now-larger)
        # amount_usd -- silently assuming the entire new total was already
        # accounted for and crediting only the attempt delta, permanently
        # losing the dollar delta between the two scans (Codex review:
        # "Record no-op prior-allocation baselines"). Recording the observed
        # baseline here regardless of whether anything changed ensures the
        # next call takes the tracked (non-ambiguous) branch instead.
        #
        # max()'d against the prior tracked value, not a blind overwrite: a
        # transient rescan that happens to observe fewer dollars/attempts
        # than a PREVIOUS call already recorded (e.g. an artifact briefly
        # unreadable) must not lower this baseline -- doing so would let a
        # later scan that recovers to the true (higher) total look like a
        # fresh delta on top of the already-credited amount, double-counting
        # it against the daily/weekly caps.
        self.seeded_prior_context_amount_by_ticker_day.setdefault(ticker, {})[
            trading_day
        ] = max(already_amount, amount_usd)
        self.seeded_prior_context_attempts_by_ticker_day.setdefault(ticker, {})[
            trading_day
        ] = max(already_attempts, attempt_count)

    def note_prior_allocation_baseline_is_disjoint(
        self, ticker: str, trading_day: date
    ) -> None:
        """Declare that nothing in ``ticker``'s prior-allocation aggregate for
        ``trading_day`` has been folded into this state yet, so the NEXT
        :meth:`reconcile_prior_allocation` credits that aggregate in full.

        For the one caller that books a real order this state has no other
        record of: crash-lease recovery. A recovered order died before its
        artifacts were written, so it is absent from the artifact scan the
        aggregate is built from -- the two are provably disjoint, and the
        aggregate's dollars and attempts belong to some OTHER order entirely
        (a cross-stream or manual buy for the same ticker made after the
        crash).

        Without this, ``reconcile_prior_allocation``'s ambiguous branch would
        see the ``buys_today()`` the recovery booking just raised, take it as
        the baseline, assume the whole freshly-scanned aggregate was already
        accounted for, and credit neither the other order's dollars nor its
        attempt (Codex review: "Reconcile separate prior allocations after
        booking a recovery"). That conservative default is right when the
        overlap is genuinely unknown; here it is known to be zero.

        Recorded via ``setdefault``, never an overwrite: a baseline already
        tracked for this (ticker, day) came from a real earlier reconcile whose
        dollars ARE credited, and resetting it to zero would re-credit them.
        """
        self.seeded_prior_context_amount_by_ticker_day.setdefault(ticker, {}).setdefault(
            trading_day, 0.0
        )
        self.seeded_prior_context_attempts_by_ticker_day.setdefault(
            ticker, {}
        ).setdefault(trading_day, 0)

    def bump_week_notional_only(self, trading_day: date, amount_usd: float) -> None:
        """Add ``amount_usd`` to the shared weekly dollar bucket ONLY --
        touches no per-ticker, per-day, or attempt-count bucket at all.

        For reconstructing EARLIER-weekday cross-stream spend (a completed
        prior day in the same ISO week), which must count against the
        shared weekly cap but must NOT be attributed to any specific
        ticker's same-day top-up reference price -- that reference is only
        ever compared against TODAY's own price, and conflating an earlier
        day's amount into a ticker's PriorSameDayAllocation would make the
        same-day top-up guard require today's price to beat an unrelated
        day's price instead of evaluating a fresh, independent DCA occasion
        (Codex review: "Include prior-week sibling spend in the afternoon
        ledger"). Mirrors morning_dca.py's own earlier-weekday ledger scan,
        which bumps ``planned_by_week`` directly for exactly the same
        reason.
        """
        self.submitted_notional_by_week[iso_week_key(trading_day)] = (
            self.week_notional(trading_day) + amount_usd
        )

    def force_week_notional_to_worst_case_ceiling(self, trading_day: date) -> None:
        """Fail closed: force the shared weekly bucket to the highest tier's
        ceiling, so remaining weekly headroom is zero regardless of which
        tier this run ultimately selects.

        Used when an earlier-weekday cross-stream scan could not verify
        every artifact it found (a transient read/parse race) -- real
        week-to-date spend may be understated, and placing against an
        unproven, possibly-too-low figure is the unsafe direction. Matches
        morning_dca.py's own fail-closed policy for the same failure mode.
        Injects only the INCREMENTAL delta needed to reach the ceiling (not
        a flat overwrite) and records exactly how much was injected in
        ``earlier_week_cross_stream_poison_usd``, so
        ``reconcile_earlier_week_cross_stream_notional`` can subtract it
        back out once a later invocation's scan succeeds -- otherwise this
        persistent StrategyState (reloaded across invocations) would stay
        pinned at the ceiling for the rest of the week even after the
        transient failure clears (mirrors morning_dca.py's own
        ``_cap_seed_poison_week`` fix for the identical failure mode). Net
        effect on ``week_notional`` is unchanged from a flat ``max()``:
        calling this repeatedly still never inflates past the ceiling, and
        it never lowers an already-larger real total.
        """
        week_key = iso_week_key(trading_day)
        worst_case_cap = max(tier.weekly_cap_usd for tier in BUDGET_TIERS)
        poison_delta = max(0.0, worst_case_cap - self.week_notional(trading_day))
        if poison_delta > 0:
            self.submitted_notional_by_week[week_key] = (
                self.week_notional(trading_day) + poison_delta
            )
            self.earlier_week_cross_stream_poison_usd[week_key] = (
                self.earlier_week_cross_stream_poison_usd.get(week_key, 0.0) + poison_delta
            )

    def reconcile_earlier_week_cross_stream_notional(
        self,
        trading_day: date,
        total_usd: float,
        *,
        pre_same_day_seed_week_notional: Optional[float] = None,
    ) -> None:
        """Fold a freshly re-derived earlier-weekday cross-stream total into
        the shared weekly bucket, adding only what isn't ALREADY reflected.

        ``total_usd`` (run_dca._compute_earlier_week_cross_stream_notional's
        result) is re-derived from on-disk artifacts on EVERY invocation --
        it does not shrink as the week progresses, and it includes THIS
        stream's own earlier-day spend too (that function's ``all_roots``
        includes the afternoon root alongside the cross-stream siblings).
        This StrategyState is persistent (reloaded fresh by
        ``state_transaction()`` on every invocation, not just within one
        process), so an earlier day's own ``record_buy()`` calls already
        updated ``submitted_notional_by_week`` for that week when they
        happened. Unconditionally adding ``total_usd`` again -- as a bare
        ``bump_week_notional_only`` call did -- double-counts that already-
        persisted spend, and does so AGAIN on every later invocation this
        same week (Codex review: "Reconcile earlier-week spend instead of
        adding it").

        Tracks how much of ``total_usd`` has already been folded in (keyed
        by ISO week, in ``earlier_week_cross_stream_seeded_usd``) and adds
        only the incremental delta -- the same idempotent-seeding idiom
        morning_dca.py's own ``_cap_seeded_amounts`` uses. Also clears any
        prior fail-closed poisoning from
        ``force_week_notional_to_worst_case_ceiling`` before reconciling, so
        a scan that previously failed and is now succeeding doesn't just
        pile the real total on top of a still-poisoned ceiling value.

        ``pre_same_day_seed_week_notional`` is the caller's own
        ``week_notional(trading_day)`` snapshot taken BEFORE it called
        ``_seed_prior_allocations`` for today's own same-day cross-stream
        context. The FIRST reconciliation this ISO week needs this snapshot
        as its baseline, not the CURRENT ``week_notional`` -- by the time
        this method runs, ``_seed_prior_allocations`` has already folded
        today's own same-day allocations into the very same weekly bucket,
        and mistaking that for "already-accounted earlier-week spend" (the
        bug before this parameter existed) silently drops the real
        earlier-week delta whenever today also has same-day context to seed
        (Codex review: "Exclude today's allocations from the prior-week
        baseline"). Optional and defaults to the current ``week_notional``
        only for a caller with no same-day seeding step of its own to
        snapshot before.
        """
        week_key = iso_week_key(trading_day)
        poisoned = self.earlier_week_cross_stream_poison_usd.pop(week_key, 0.0)
        if poisoned > 0:
            self.submitted_notional_by_week[week_key] = max(
                0.0, self.week_notional(trading_day) - poisoned
            )
        if week_key in self.earlier_week_cross_stream_seeded_usd:
            already_seeded = self.earlier_week_cross_stream_seeded_usd[week_key]
        else:
            # First reconciliation this ISO week: the correct baseline is
            # whatever this stream's own earlier-day history already
            # contributed BEFORE today's own same-day seeding ran -- total_usd's
            # fresh rescan re-derives that same earlier-day history too, since
            # its all_roots includes the afternoon root alongside the
            # cross-stream siblings.
            already_seeded = (
                pre_same_day_seed_week_notional
                if pre_same_day_seed_week_notional is not None
                else self.week_notional(trading_day)
            )
            # The caller's `pre_same_day_seed_week_notional` snapshot was
            # taken BEFORE this call -- and therefore before the poison
            # removal a few lines above ran -- so it can still include a
            # fail-closed ceiling `force_week_notional_to_worst_case_
            # ceiling` injected in an EARLIER invocation this same ISO
            # week. Using it as-is inflates the baseline by exactly that
            # poison: a $100 real spend plus $1,700 poison snapshots as
            # $1,800, and after this recovered scan reports $150 the
            # bucket is correctly reduced to $100 above but `incremental`
            # computes as `150 - 1800` (clamped to 0), so the missing $50
            # is never added AND the persisted seeded baseline becomes
            # $1,800 against a $100 ledger -- understating weekly spend
            # and failing the serializer's own seeded-versus-ledger
            # invariant on the next save (Codex review, PR #1169: "Remove
            # poison from the pre-seed weekly baseline"). The `self.week_
            # notional(trading_day)` fallback just above needs no such
            # adjustment: it is read AFTER the poison removal already ran.
            #
            # Gated on `pre_same_day_seed_week_notional is not None`, not
            # merely `poisoned > 0`: the fallback branch's own baseline is
            # ALREADY poison-free (per the comment just above), so
            # subtracting `poisoned` from it a second time drove the
            # baseline below the real already-recorded spend. A $100 real
            # spend plus $1,700 poison this method itself just cleared,
            # followed by a successful $150 scan with no caller-supplied
            # snapshot, left `already_seeded` at `max(0.0, 100 - 1700) ==
            # 0` instead of the correct `100`, so `incremental` computed
            # as the full `150` instead of the genuine `50` delta,
            # inflating the weekly bucket to $250 and overstating
            # deployment enough to suppress a valid buy (Codex review, PR
            # #1169: "Do not subtract poison twice from the fallback
            # baseline").
            if poisoned > 0 and pre_same_day_seed_week_notional is not None:
                already_seeded = max(0.0, already_seeded - poisoned)
        incremental = total_usd - already_seeded
        if incremental > 0:
            self.submitted_notional_by_week[week_key] = (
                self.week_notional(trading_day) + incremental
            )
        # Recorded UNCONDITIONALLY, even when incremental is zero (an exact
        # match against the just-computed baseline): a prior version of this
        # method only recorded earlier_week_cross_stream_seeded_usd inside
        # the `incremental > 0` branch, so a first-ever reconciliation this
        # ISO week that happened to exactly equal already_seeded left the key
        # unset. The NEXT call then fell back to the "first reconciliation
        # this week" branch again, re-baselining against a snapshot that may
        # have since grown from today's own same-day spend and silently
        # under-crediting the real earlier-week delta discovered by a later
        # rescan (Codex review: "Persist an unchanged earlier-week
        # reconciliation baseline"). Recording it here regardless of sign
        # ensures the next call takes the already-seeded (non-rebaselining)
        # branch instead.
        #
        # max()'d against the (possibly just-computed) already_seeded, not a
        # blind overwrite: a transient rescan reporting a SMALLER total than
        # a previous call already recorded must not lower this baseline --
        # doing so would let a later scan that recovers to the true (higher)
        # total look like a fresh delta on top of spend already added to the
        # weekly bucket, double-counting it against the shared cap.
        self.earlier_week_cross_stream_seeded_usd[week_key] = max(
            already_seeded, total_usd
        )

    def day_notional(self, trading_day: date) -> float:
        return self.submitted_notional_by_day.get(trading_day, 0.0)

    def week_notional(self, trading_day: date) -> float:
        return self.submitted_notional_by_week.get(iso_week_key(trading_day), 0.0)

    def day_order_count(self, trading_day: date) -> int:
        return self.submitted_order_count_by_day.get(trading_day, 0)

    def current_tier(self) -> BudgetTier:
        """Return the tier selected for the current run, defaulting to Normal."""
        return self.selected_tier or BUDGET_TIERS[0]

    def select_daily_budget(
        self,
        planned_spend_usd: float,
        high_multiplier_signal_count: int,
        config: StrategyConfig,
    ) -> BudgetTier:
        """Choose and store the budget tier for the run from the day's plan."""
        tier = select_budget_tier(planned_spend_usd, high_multiplier_signal_count)
        self.selected_tier = tier
        return tier

    def roll_weekly_reserve(self, trading_day: date, config: StrategyConfig) -> None:
        """Roll the weekly rollover reserve forward for ``trading_day``'s week.

        The reserve reflects the *prior* week's unused Normal-cap capacity (itself
        capped by ``weekly_rollover_reserve_cap_usd``) and stays constant for the
        whole week. It is computed exactly once per week, keyed by
        ``reserve_week_key``, so the result does not depend on whether the day has
        already been finalized or how many times this is called -- a quiet week
        with no BUY candidates still rolls the reserve before the day is finalized.
        """
        week_key = iso_week_key(trading_day)
        if self.reserve_week_key == week_key:
            return
        # Base the reserve on the most recent *earlier* week that saw activity.
        prior_weeks = [
            iso_week_key(day)
            for day in self.finalized_budget_days
            if iso_week_key(day) < week_key
        ]
        if prior_weeks:
            last_week_key = max(prior_weeks)
            unused_prev = max(
                0.0,
                NORMAL_WEEKLY_CAP_USD
                - self.submitted_notional_by_week.get(last_week_key, 0.0),
            )
            self.weekly_rollover_reserve_usd = min(
                config.weekly_rollover_reserve_cap_usd, unused_prev
            )
        else:
            self.weekly_rollover_reserve_usd = 0.0
        self.reserve_week_key = week_key

    def effective_weekly_cap(self) -> float:
        """Return the weekly notional ceiling the selected tier will actually allow.

        For the stress tier this is the Normal weekly cap plus the current rollover
        reserve (bounded by the tier's nominal weekly cap); with only a partial
        reserve it is below the nominal $1,800 tier cap. All other tiers allow
        their nominal weekly cap.
        """
        tier = self.current_tier()
        if tier.uses_rollover_reserve:
            return min(
                tier.weekly_cap_usd,
                NORMAL_WEEKLY_CAP_USD + self.weekly_rollover_reserve_usd,
            )
        return tier.weekly_cap_usd

    def allowed_spend_today(self, trading_day: date, config: StrategyConfig) -> float:
        """Return the max strategy spend allowed today under the selected tier caps.

        The weekly ceiling is the selected tier's weekly cap. Stress tier capacity
        above the Normal weekly cap is available only to the extent of the prior
        unused weekly rollover reserve (itself capped by
        ``weekly_rollover_reserve_cap_usd``).
        """
        self.roll_weekly_reserve(trading_day, config)
        effective_weekly = self.effective_weekly_cap()
        remaining_weekly = max(0.0, effective_weekly - self.week_notional(trading_day))
        return max(0.0, min(self.current_tier().daily_cap_usd, remaining_weekly))

    def remaining_spend_today(self, trading_day: date, config: StrategyConfig) -> float:
        """Return remaining strategy spend after same-day submitted notional."""
        return max(
            0.0,
            self.allowed_spend_today(trading_day, config)
            - self.day_notional(trading_day),
        )

    def finalize_daily_budget(self, trading_day: date, config: StrategyConfig) -> None:
        """Mark the current trading day as finalized.

        The weekly rollover reserve is rolled forward at the start of a new week in
        ``allowed_spend_today``, so it stays constant during the week and correctly
        reflects the *prior* week's unused Normal-cap capacity. This method only
        records that the day's budget has been finalized.
        """
        if trading_day in self.finalized_budget_days:
            return
        self.finalized_budget_days.add(trading_day)


class MarketDataProvider(Protocol):
    source: SourceName

    def get_previous_close_bar(self, ticker: str, as_of: datetime) -> Optional[Bar]:
        """Return the prior completed regular-session close bar before as_of."""
        ...

    def get_intraday_bars(
        self,
        ticker: str,
        start: datetime,
        end: datetime,
        interval_minutes: int,
    ) -> List[Bar]:
        """Return regular-session intraday bars for the given interval."""
        ...


@dataclass(frozen=True)
class OrderFill:
    """Broker-reported fill details used to compute execution slippage."""

    avg_fill_price: float
    quantity_filled: float
    order_submitted_at: Optional[datetime] = None
    order_filled_at: Optional[datetime] = None


class OrderConfirmationRequiredError(Exception):
    """Raised by a BrokerAdapter when review passed but submission needs confirmation.

    Some brokers require additional post-review user confirmation (e.g. a
    step-up/2FA gate) before a reviewed order will actually submit. This is a
    normal, expected broker response, not a placement failure: no order was
    attempted and nothing needs retrying by this run. Per
    schemas/run_state.schema.json, a run that hits this is still valid
    scheduled-run evidence that the task executed and passed review; it must be
    recorded distinctly (``not_submitted_confirmation_required``) rather than
    counted as an error.
    """


class UnresolvedPlacementError(RuntimeError):
    """Stop a batch when reconciliation cannot prove a placement's outcome.

    The broker may have accepted the order even though the placement call
    raised.  Until history proves acceptance or proves that no order exists,
    later placements cannot safely use the batch's deployment and cap totals.

    ``concurrent_writer_detected`` marks the specific case where this halt was
    raised NOT because a placement outcome is itself unprovable, but because a
    run_state.json compare-and-swap found that a DIFFERENT, overlapping retry
    sharing this same trading_day/stream/slot identity has already published
    its own evidence since this invocation's last known view of the file
    (Codex review: "Preserve the concurrent writer after rejecting stale
    state"). That other retry already owns this identity slot and has
    already -- or will -- satisfy the scheduled contract for it, so the
    exception-handling artifact writer must not merge or overwrite
    run_state.json (or its companions) on this path the way it does for
    every other halt reason; see its ``concurrent_writer_detected`` handling.
    """

    def __init__(self, *args: object, concurrent_writer_detected: bool = False) -> None:
        super().__init__(*args)
        self.concurrent_writer_detected = concurrent_writer_detected


class AmbiguousPlacementResponseError(RuntimeError):
    """A terminal placement response that does NOT prove the order is dead.

    The shape is a terminal ``state`` carrying an order id AND positive or
    unreadable fill evidence: not self-consistent, so the outcome stays
    unresolved and the caller reconciles it against order history. What makes
    this its own type rather than a plain ``RuntimeError`` is the id -- when
    the just-created order is not yet visible in eventually consistent history,
    reconciliation returns no match and the failure artifact recorded
    ``order_id=null``, leaving an operator to investigate a possible partial
    fill with no broker identifier at all (Codex review, PR #859: "Retain IDs
    from ambiguous terminal responses"). The VERDICT is unchanged -- this is
    still unproven and still halts the batch; only the reconciliation key
    survives.

    ``response_notional_usd`` carries the SAME response's own recovered
    execution notional (``_recovered_broker_notional`` applied to the
    order that triggered this raise), not just its id. Without it, a
    terminal response reporting real execution -- ``executed_notional:
    100`` -- had that evidence discarded the moment this exception was
    raised: if the immediately-queried history then matches a STALE
    working row for the same id at the approved requested size
    (``state=queued, dollar_amount=2``), reconciliation reads that row as
    an ordinary accepted order, books only the requested $2, and the
    batch continues -- silently losing the response's own $100 fill
    (Codex review, PR #859 round 39: "Retain response fill evidence
    through reconciliation"). Carrying it here lets reconciliation refuse
    to accept a working match whose own notional does not corroborate it.

    ``structurally_ambiguous`` marks a response that itself names TWO OR
    MORE disagreeing identities -- ``{"id": "A", "order_id": "B"}``, or a
    collection carrying several distinct candidate rows -- rather than one
    order whose terminal fate merely is not yet certain. ``order_id`` above
    can only ever carry ONE of the disputed identities (the raise site
    always prefers "id"), so a history lookup that happens to match THAT
    ONE id proves only that it is real; it says nothing about the OTHER,
    discarded identity the SAME response also named, which could just as
    easily be a second, live order this run never accounts for. Without
    this flag, a coincidental match on the carried id let the caller treat
    the whole response as accepted and continue, silently dropping the
    other identity from reconciliation and cap accounting for good (Codex
    review, PR #859/#911 round 42: "Keep structurally ambiguous responses
    unresolved").
    """

    def __init__(
        self,
        message: str,
        order_id: object = None,
        response_notional_usd: Optional[float] = None,
        response_may_have_executed: bool = False,
        structurally_ambiguous: bool = False,
    ) -> None:
        super().__init__(message)
        self.order_id = order_id
        self.response_notional_usd = response_notional_usd
        self.response_may_have_executed = response_may_have_executed
        self.structurally_ambiguous = structurally_ambiguous


class FractionalPlacementRejectedError(RuntimeError):
    """A broker response proves that a fractional order was rejected.

    Unlike a transport exception, this is safe to treat as a ticker-local
    placement failure: the adapter received an explicit refusal response, so
    there is no possibly-live order whose notional is missing from the batch.

    ``order_id`` carries the refusal's OWN broker id when the response named
    one -- a terminal ``{"id": "ORD", "state": "cancelled",
    "cumulative_quantity": "0"}`` proves no order is live and still identifies
    the order it is talking about. The caller skips history reconciliation on
    this exception, so dropping the id left ``broker_outcomes`` and the
    candidate artifact with no durable link to the broker record at all, while
    ``_reconcile_ambiguous_fractional_placement`` deliberately preserves that
    same id on its own no-order verdict (Codex review, PR #859: "Preserve the
    terminal order ID from proven rejections"). The VERDICT, not the presence
    of an id, is what decides whether a submission gets booked.
    """

    def __init__(self, message: str, order_id: object = None) -> None:
        super().__init__(message)
        self.order_id = order_id


# Backwards-compatible public name used by the morning strategy and adapter
# consumers. Fractional rejections retain the same ticker-local semantics.
OrderPlacementRejectedError = FractionalPlacementRejectedError


class WholeSharePlacementTerminalError(RuntimeError):
    """Raised by a BrokerAdapter's ``place_whole_share_buy`` when the broker's
    OWN immediate placement response already reports a terminal (non-live,
    non-"filled") order state.

    Carries the raw ``order`` payload the broker returned, so the caller can
    settle/restore using its ALREADY-KNOWN ``cumulative_quantity``/
    ``average_price``/``state`` directly, instead of relying exclusively on a
    SEPARATE, later order-history lookup that can itself be eventually
    consistent and report a clean "no match" for an order the placement
    response already proved landed (Codex review: "Reconcile terminal fills
    from the placement response") -- discarding this payload before raising
    a bare exception left the caller with strictly less information than the
    broker had already given it in the very same response.
    """

    def __init__(self, message: str, order: Dict[str, Any]) -> None:
        super().__init__(message)
        self.order = order


class BrokerAdapter(Protocol):
    def account_number(self) -> str:
        """Return the account number that will be used for orders."""
        ...

    def available_buying_power(self) -> float:
        """Return available buying power for the target account."""
        ...

    def same_day_strategy_order_exists(self, ticker: str, trading_day: date) -> bool:
        """Return True if this strategy already submitted an order for ticker today."""
        ...

    def same_day_strategy_order_exists_with_ref_id_prefix(
        self, ticker: str, trading_day: date, ref_id_prefixes: Tuple[str, ...]
    ) -> Optional[Dict[str, Any]]:
        """Return the live same-day order whose ref id matches one of ``ref_id_prefixes``.

        Used to narrow the broad same-day-order check to only this stream's own
        idempotency ids, so a guarded top-up candidate (whose broad check is
        intentionally bypassed to allow topping up a cross-stream allocation)
        can still detect a retry of ITS OWN earlier same-day order.
        """
        ...

    def same_day_order_with_ref_id_prefix_any_state(
        self, ticker: str, trading_day: date, ref_id_prefixes: Tuple[str, ...]
    ) -> Optional[Dict[str, Any]]:
        """Same exact-ref-id match as
        :meth:`same_day_strategy_order_exists_with_ref_id_prefix`, but also
        returns a genuinely TERMINAL (cancelled/rejected/expired) order --
        not just a live one.

        Whole-share reconciliation of an ambiguous placement needs this: a
        partial fill followed by a cancellation is real, already-executed
        capital that the live-only method would report as a clean "no
        match," indistinguishable from an order that never reached the
        broker at all (Codex review: "Reconcile partial fills before
        releasing canceled claims").
        """
        ...

    def strategy_order_with_ref_id(
        self, ticker: str, trading_day: date, ref_id: str
    ) -> Optional[Dict[str, Any]]:
        """Return a matching order from history, including terminal orders."""
        ...

    def same_day_ticker_notional_usd(self, ticker: str, trading_day: date) -> float:
        """Return the total dollar notional of every live same-day order for ticker.

        Unlike the two methods above (existence checks scoped to this
        strategy's own ref-id conventions), this sums EVERY live-state broker
        order for the ticker/day regardless of ref id or which stream/executor
        placed it -- the real, ground-truth figure a guarded top-up's
        incremental delta must never under-count relative to (see
        ``evaluate_top_up_guard``'s KNOWN GAP note).
        """
        ...

    def is_tradable_for_fractional_buy(self, ticker: str) -> bool:
        """Return True only if the instrument can receive this notional buy."""
        ...

    def is_tradable_for_whole_share_buy(self, ticker: str) -> bool:
        """Return True only if the instrument can receive a QUANTITY-based buy.

        Unlike :meth:`is_tradable_for_fractional_buy`, this must NOT require
        fractional tradability -- a whole-share ticker (see
        ``near_close_dca.WHOLE_SHARE_TICKERS`` and
        ``docs/whole_share_accumulation.md``) is in that category PRECISELY
        because it fails ``is_tradable_for_fractional_buy``'s fractional
        requirement. Checked unconditionally (both scheduled and manual
        runs) before placement, mirroring how ``is_tradable_for_fractional_buy``
        gates the normal buy path regardless of ``ctx.scheduled`` -- distinct
        from :meth:`review_whole_share_buy`, which (like
        :meth:`review_market_buy`) is only attempted on a MANUAL run.
        """
        ...

    def review_market_buy(self, ticker: str, notional_usd: float) -> tuple[bool, str]:
        """Return (approved, reason) from broker-side order review."""
        ...

    def place_market_buy(self, ticker: str, notional_usd: float, ref_id: str) -> str:
        """Place a notional regular-hours market buy and return an order id.

        May raise ``OrderConfirmationRequiredError`` when review passed but the
        broker requires additional confirmation before it will submit.
        """
        ...

    def review_whole_share_buy(self, ticker: str, quantity: int) -> tuple[bool, str]:
        """Quantity-based counterpart to :meth:`review_market_buy`.

        For a ticker not tradable for fractional/notional buys (see
        ``near_close_dca.WHOLE_SHARE_TICKERS`` and
        ``docs/whole_share_accumulation.md``), a dollar-amount review is
        reviewing the wrong kind of order entirely.
        """
        ...

    def place_whole_share_buy(self, ticker: str, quantity: int, ref_id: str) -> str:
        """Place a whole-share (quantity-based, non-fractional) market buy and
        return an order id. Quantity-based counterpart to :meth:`place_market_buy`.
        """
        ...

    def get_order_fill(self, order_id: str) -> Optional[OrderFill]:
        """Return fill details for a placed order, or None if not yet filled."""
        ...

    @property
    def supports_concurrent_fill_lookup(self) -> bool:
        """Whether get_order_fill may be called from multiple threads at once.

        Defaults to False. get_order_fill is commonly a thin wrapper around a
        scheduler-owned MCP callable that is not guaranteed thread-safe; only
        override to True once a broker's wiring is verified safe for concurrent
        calls (see docs/live_wiring.md).
        """
        return False

    def get_raw_placement_responses(self) -> List[Dict[str, Any]]:
        """Return raw broker response dicts for every order placed this run.

        Used to persist ``raw/orders_after_place.json`` for durable fill
        data so the slippage report is replayable without a live broker
        re-query. Brokers that do not support this may return ``[]``.
        """
        return []


class DryRunBroker:
    def __init__(
        self,
        cash: float = 300.0,
        account: str = ROBINHOOD_AGENTIC_ACCOUNT_NUMBER,
        reference_prices: Optional[Dict[str, float]] = None,
        simulated_slippage_pct: float = 0.0,
    ) -> None:
        self._cash = cash
        self._account = account
        # When reference prices are supplied the dry-run broker simulates fills so the
        # slippage/coverage pipeline can be exercised end-to-end without a live broker.
        self._reference_prices = dict(reference_prices or {})
        self._simulated_slippage_pct = simulated_slippage_pct
        self._fills: Dict[str, OrderFill] = {}
        self.supports_concurrent_fill_lookup: bool = False
        # Keyed by ref_id (the SAME deterministic idempotency-slot ref_id
        # every real placement call uses) so
        # same_day_strategy_order_exists_with_ref_id_prefix/
        # same_day_order_with_ref_id_prefix_any_state can answer a
        # post-placement state-verification lookup the same way a real
        # broker would -- without this, place_whole_share_buy's own
        # simulated order was undiscoverable by those lookups, and the
        # ordinary success path's own nonterminal-state guard (see
        # _process_whole_share_candidate) would leave every dry-run-broker
        # placement's claim reserved as "not yet visible" instead of
        # settling it, contrary to this broker's whole design intent of
        # simulating an immediately-accepted (and, with a reference price,
        # immediately-filled) order.
        self._placed_whole_share_orders: Dict[str, Dict[str, Any]] = {}

    def account_number(self) -> str:
        return self._account

    def available_buying_power(self) -> float:
        return self._cash

    def same_day_strategy_order_exists(self, ticker: str, trading_day: date) -> bool:
        return False

    def same_day_strategy_order_exists_with_ref_id_prefix(
        self, ticker: str, trading_day: date, ref_id_prefixes: Tuple[str, ...]
    ) -> Optional[Dict[str, Any]]:
        for ref_id in ref_id_prefixes:
            order = self._placed_whole_share_orders.get(ref_id)
            if order is not None:
                return order
        return None

    def same_day_order_with_ref_id_prefix_any_state(
        self, ticker: str, trading_day: date, ref_id_prefixes: Tuple[str, ...]
    ) -> Optional[Dict[str, Any]]:
        return self.same_day_strategy_order_exists_with_ref_id_prefix(ticker, trading_day, ref_id_prefixes)

    def strategy_order_with_ref_id(
        self, ticker: str, trading_day: date, ref_id: str
    ) -> Optional[Dict[str, Any]]:
        return None

    def same_day_ticker_notional_usd(self, ticker: str, trading_day: date) -> float:
        return 0.0

    def is_tradable_for_fractional_buy(self, ticker: str) -> bool:
        return True

    def is_tradable_for_whole_share_buy(self, ticker: str) -> bool:
        return True

    def review_market_buy(self, ticker: str, notional_usd: float) -> tuple[bool, str]:
        return True, "dry-run review approved"

    def place_market_buy(self, ticker: str, notional_usd: float, ref_id: str) -> str:
        order_id = f"DRY-RUN-{ticker}-{notional_usd:.2f}-{ref_id}"
        reference = self._reference_prices.get(ticker)
        if reference:
            submitted_at = datetime.now(tz=EASTERN)
            fill_price = reference * (1.0 + self._simulated_slippage_pct / 100.0)
            self._fills[order_id] = OrderFill(
                avg_fill_price=fill_price,
                quantity_filled=notional_usd / fill_price if fill_price else 0.0,
                order_submitted_at=submitted_at,
                order_filled_at=submitted_at + timedelta(seconds=1),
            )
        return order_id

    def review_whole_share_buy(self, ticker: str, quantity: int) -> tuple[bool, str]:
        return True, "dry-run review approved"

    def place_whole_share_buy(self, ticker: str, quantity: int, ref_id: str) -> str:
        order_id = f"DRY-RUN-WHOLESHARE-{ticker}-{quantity}-{ref_id}"
        reference = self._reference_prices.get(ticker)
        if reference:
            submitted_at = datetime.now(tz=EASTERN)
            fill_price = reference * (1.0 + self._simulated_slippage_pct / 100.0)
            self._fills[order_id] = OrderFill(
                avg_fill_price=fill_price,
                quantity_filled=float(quantity),
                order_submitted_at=submitted_at,
                order_filled_at=submitted_at + timedelta(seconds=1),
            )
            self._placed_whole_share_orders[ref_id] = {
                "id": order_id,
                "order_id": order_id,
                "state": "filled",
                "cumulative_quantity": str(quantity),
                "quantity": str(quantity),
                "average_price": str(fill_price),
            }
        else:
            # No reference price supplied -- this broker never simulates a
            # fill for this order (see __init__'s own comment), so it is
            # genuinely still working/unconfirmed, not filled.
            self._placed_whole_share_orders[ref_id] = {
                "id": order_id,
                "order_id": order_id,
                "state": "new",
                "cumulative_quantity": "0",
                "quantity": str(quantity),
            }
        return order_id

    def get_order_fill(self, order_id: str) -> Optional[OrderFill]:
        return self._fills.get(order_id)

    def get_raw_placement_responses(self) -> List[Dict[str, Any]]:
        return []


def format_notional(amount_usd: float) -> str:
    """Format a dollar amount as the string Alpaca expects for notional orders."""
    return f"{amount_usd:.2f}"


@dataclass(frozen=True)
class AlpacaConfig:
    """Alpaca backend settings.

    ``is_paper_api`` selects paper vs. live at the connector; paper is safest for
    connection testing. ``enable_live_orders`` is the hard gate on real placement:
    while False (default), the adapter builds the order payload but never submits it.
    """

    is_paper_api: bool = True
    enable_live_orders: bool = False
    time_in_force: str = "day"
    extended_hours: bool = False
    # Dry-run buying power used when no live account-info callable is wired in.
    simulated_buying_power_usd: float = 300.0


def build_alpaca_account_info_payload(is_paper_api: bool) -> Dict[str, Any]:
    return {
        "source_id": ALPACA_SOURCE_ID,
        "tool": ALPACA_ACCOUNT_INFO_TOOL,
        "input": {"isPaperAPI": is_paper_api},
    }


def build_alpaca_get_order_payload(order_id: str, is_paper_api: bool) -> Dict[str, Any]:
    """Build a payload for the Pipedream ``alpaca-get-order`` action.

    ``order_id`` is sent under the connector's camel-cased ``orderId`` input key
    (consistent with its other inputs, e.g. ``isPaperAPI``) -- not ``order_id`` --
    or the action has no ID to look up and the request fails. ``is_paper_api``
    selects paper vs. live trading, same as the other Alpaca payload builders.
    """
    return {
        "source_id": ALPACA_SOURCE_ID,
        "tool": ALPACA_GET_ORDER_TOOL,
        "input": {"orderId": order_id, "isPaperAPI": is_paper_api},
    }


# Terminal Alpaca order statuses that can carry a real, durable fill under
# their own order id (no further fills will ever land on this id). 'filled'
# is the ordinary case; 'canceled'/'expired' can still report a positive
# filled_qty for shares that executed before the remainder was canceled or
# expired. That execution is real and must not be discarded, or such orders
# become permanent missing-fill gaps (Codex review: "Record executions from
# terminally canceled Alpaca orders"). 'partially_filled' is deliberately
# excluded even though it also carries a positive filled_qty: it is NOT
# terminal, so treating it as a complete fill here would make
# build_execution_record() persist status='filled' and
# _refresh_fills_from_broker() would then never re-query the order again
# even though more shares may still execute.
#
# 'replaced' is handled separately (see _resolve_alpaca_order_fill): unlike
# the statuses above, a replaced order's remaining quantity continues under
# a *new* order id in its 'replaced_by' field, so it is not in this set.
#
# 'done_for_day' and 'calculated' are ALSO handled separately, not included
# here. Per Alpaca's own docs, 'calculated' means "the order has been
# completed for the day (either filled OR done for day), with settlement
# calculations still pending" -- it is not a synonym for 'filled', it can
# equally represent the done_for_day case. Both are durable terminal
# signals ONLY for a 'day' time-in-force order (it expires with the trading
# day, so no same-day-or-later execution can still land on it); Alpaca can
# resume working any other TIF on a later trading day, so whether either
# status is terminal depends on AlpacaConfig.time_in_force, which this
# module-level constant can't see (Codex review: "Accept done_for_day
# Alpaca fills" / "Gate calculated status on the order's TIF").
_ALPACA_TERMINAL_FILL_STATUSES = frozenset({"filled", "canceled", "expired"})

# Bounds how many 'replaced_by' hops _resolve_alpaca_order_fill will follow
# for a single lookup, so a cyclic or pathologically long replacement chain
# in a malformed response can never loop forever.
_ALPACA_MAX_REPLACEMENT_HOPS = 10


def _unwrap_alpaca_connector_response(payload: Any) -> Any:
    """Unwrap nested ``{"data": ...}`` connector envelopes.

    Same convention as ``dca_live_adapters._unwrap()`` and
    ``dca_reporting._unwrap_payload()``: an MCP/Pipedream tool response can
    arrive wrapped in one or more ``data`` layers (e.g.
    ``{"data": {"order": {...}}}``) rather than the bare order envelope.
    Keeps unwrapping until the payload stops being an unwrappable dict, with
    a cycle guard for a malformed self-referential payload.
    """
    seen_ids: set = set()
    while isinstance(payload, dict) and "data" in payload:
        if id(payload) in seen_ids:
            break
        seen_ids.add(id(payload))
        payload = payload["data"]
    return payload


def _extract_alpaca_order(data: Any, order_id: str) -> Optional[Dict[str, Any]]:
    """Find the order dict matching ``order_id`` in an Alpaca get-order response.

    Accepts a ``{"data": ...}``-wrapped envelope, list mode
    (``{"orders": [...]}``), a single-order envelope (``{"order": {...}}``),
    or a bare top-level order object.
    """
    data = _unwrap_alpaca_connector_response(data)
    if not isinstance(data, dict):
        return None
    single = data.get("order") if isinstance(data.get("order"), dict) else None
    if single is None and (data.get("id") or data.get("order_id")):
        single = data
    raw_orders = data.get("orders")
    orders: List[Any] = raw_orders if isinstance(raw_orders, list) else ([single] if single else [])
    for order in orders:
        if not isinstance(order, dict):
            continue
        oid = _first_usable_order_id_alias(order)
        if oid == order_id:
            return order
    return None


def _alpaca_float_or_nan(value: Any) -> float:
    """Best-effort float conversion; NaN for a missing, null, or non-numeric value.

    ``order.get(key, 0.0)`` only substitutes the default when the key is
    absent -- an explicit JSON ``null`` (e.g. a canceled order's unfilled
    ``filled_avg_price``) comes through as Python ``None`` and would raise
    from a bare ``float(None)``. Normalizing every unusable shape to NaN
    lets callers use a single ``math.isfinite`` check regardless of why the
    value is unusable.
    """
    if value is None:
        return float("nan")
    try:
        return float(value)
    except (TypeError, ValueError, OverflowError):
        # OverflowError joins the pair: float(10**1000) raises it rather than
        # returning inf, and a JSON-decoded integer is unbounded in Python, so
        # a broker payload can reach here with one. This function's whole
        # contract is to normalize every unusable shape to NaN rather than
        # raise (Codex review, PR #786: "Treat oversized numeric order IDs as
        # unusable" -- same defect class, swept to every best-effort numeric
        # parse a JSON payload can reach).
        return float("nan")


def _parse_alpaca_order_fill(order: Dict[str, Any]) -> Optional[Tuple[float, float]]:
    """Extract ``(filled_qty, filled_avg_price)`` for a hop with a genuine, usable fill.

    Returns ``None`` for a missing, null, zero, negative, or non-finite
    quantity or price -- covers both "genuinely nothing executed at this
    hop" (legitimate, e.g. a canceled order with a null price that never
    filled) and "a positive quantity but an unusable price" (ambiguous; see
    ``_alpaca_has_unpriced_fill``, which the caller checks separately since
    that case must not be silently treated the same as "nothing executed").
    Submission/fill timestamps are handled separately by the caller: they
    are meaningful even on a hop with no positive fill (e.g. an order
    replaced before executing anything still has a real ``submitted_at``).
    """
    filled_qty = _alpaca_float_or_nan(order.get("filled_qty"))
    if not math.isfinite(filled_qty) or filled_qty <= 0:
        return None
    filled_avg_price = _alpaca_float_or_nan(order.get("filled_avg_price"))
    if not math.isfinite(filled_avg_price) or filled_avg_price <= 0:
        return None
    return filled_qty, filled_avg_price


def _alpaca_has_unpriced_fill(order: Dict[str, Any]) -> bool:
    """True when ``filled_qty`` is genuinely positive but ``filled_avg_price`` is unusable.

    A positive quantity means a real execution happened at this hop --
    unlike a missing/zero/null quantity (nothing executed, which is
    legitimate), an unusable price here means the execution is real but its
    notional can't be computed. ``_parse_alpaca_order_fill`` alone would
    silently drop such a hop's contribution from the running total; the
    caller instead treats this as an unresolved chain, since silently
    dropping it would under-report a fill known to have happened (Codex
    review: "Retry replacements with invalid partial-fill numerics").
    """
    filled_qty = _alpaca_float_or_nan(order.get("filled_qty"))
    if not math.isfinite(filled_qty) or filled_qty <= 0:
        return False
    filled_avg_price = _alpaca_float_or_nan(order.get("filled_avg_price"))
    return not math.isfinite(filled_avg_price) or filled_avg_price <= 0


def _alpaca_qty_is_explicit_zero(order: Dict[str, Any]) -> bool:
    """True when ``filled_qty`` is present and parses to exactly ``0``.

    Distinguishes Alpaca's genuine "nothing executed" signal (an explicit,
    finite zero) from a missing, non-numeric, non-finite, or negative
    value on a terminal ``'canceled'``/``'expired'`` hop. Those other shapes
    are ambiguous or malformed, not proof nothing executed, so the caller
    must not silently treat them the same as a resolved zero fill (Codex
    review: "Retry canceled replacements with invalid quantities").
    """
    raw = order.get("filled_qty")
    if raw is None:
        return False
    try:
        qty = float(raw)
    except (TypeError, ValueError):
        return False
    return math.isfinite(qty) and qty == 0


def _parse_alpaca_timestamp(value: Optional[str]) -> Optional[datetime]:
    """Parse an RFC3339 Alpaca timestamp, requiring timezone awareness.

    Returns ``None`` for a missing value or one that parses to a naive
    datetime (no offset). A naive result can't be safely compared against
    another hop's timezone-aware timestamp -- build_execution_record()
    subtracts submitted_at from filled_at to compute latency, and mixing a
    naive and an aware datetime raises TypeError there, outside this
    method's exception boundary. Treating it as unusable rather than
    guessing a timezone keeps that subtraction safe.
    """
    if not value:
        return None
    try:
        parsed = datetime.fromisoformat(value.replace('Z', '+00:00'))
    except ValueError:
        return None
    if parsed.tzinfo is None:
        return None
    return parsed


def build_alpaca_list_orders_payload(
    is_paper_api: bool,
    symbols: Sequence[str],
    side: str = "buy",
    status: str = "all",
    after: Optional[str] = None,
    until: Optional[str] = None,
    nested: str = "",
) -> Dict[str, Any]:
    order_input: Dict[str, Any] = {
        "isPaperAPI": is_paper_api,
        "symbols": list(symbols),
        "side": side,
        "status": status,
        "nested": nested,
    }
    if after is not None:
        order_input["after"] = after
    if until is not None:
        order_input["until"] = until
    return {
        "source_id": ALPACA_SOURCE_ID,
        "tool": ALPACA_LIST_ORDERS_TOOL,
        "input": order_input,
    }


def build_alpaca_list_positions_payload(is_paper_api: bool) -> Dict[str, Any]:
    return {
        "source_id": ALPACA_SOURCE_ID,
        "tool": ALPACA_LIST_POSITIONS_TOOL,
        "input": {"isPaperAPI": is_paper_api},
    }


def build_alpaca_market_buy_payload(
    symbol: str,
    notional_usd: float,
    is_paper_api: bool = True,
    time_in_force: str = "day",
    extended_hours: bool = False,
) -> Dict[str, Any]:
    """Build a regular-hours market buy payload using notional as a string."""
    return {
        "source_id": ALPACA_SOURCE_ID,
        "tool": ALPACA_PLACE_ORDER_TOOL,
        "input": {
            "symbol": symbol,
            "side": "buy",
            "type": "market",
            "timeInForce": time_in_force,
            "notional": format_notional(notional_usd),
            "extendedHours": extended_hours,
            "isPaperAPI": is_paper_api,
        },
    }


class AlpacaBroker:
    """BrokerAdapter for Alpaca via the ``alpaca__pipedream`` connector.

    The adapter is a skeleton: it builds connector-ready payloads and only submits
    a real order when ``AlpacaConfig.enable_live_orders`` is True and a ``place_order_fn``
    is wired in. With the defaults it is entirely dry-run and never calls the network.
    Inject callables to connect it to the live connector without changing the strategy.
    """

    supports_concurrent_fill_lookup: bool = False

    def __init__(
        self,
        config: Optional[AlpacaConfig] = None,
        account: str = ROBINHOOD_AGENTIC_ACCOUNT_NUMBER,
        place_order_fn: Optional[Callable[[Dict[str, Any]], str]] = None,
        account_info_fn: Optional[Callable[[Dict[str, Any]], Dict[str, Any]]] = None,
        list_orders_fn: Optional[
            Callable[[Dict[str, Any]], List[Dict[str, Any]]]
        ] = None,
        order_fill_fn: Optional[
            Callable[[Dict[str, Any]], Optional[Dict[str, Any]]]
        ] = None,
    ) -> None:
        self.config = config or AlpacaConfig()
        self._account = account
        self._place_order_fn = place_order_fn
        self._account_info_fn = account_info_fn
        self._list_orders_fn = list_orders_fn
        self._order_fill_fn = order_fill_fn

    def account_number(self) -> str:
        return self._account

    def available_buying_power(self) -> float:
        if self._account_info_fn is not None:
            info = self._account_info_fn(
                build_alpaca_account_info_payload(self.config.is_paper_api)
            )
            bp = info.get("buying_power") if info.get("buying_power") is not None else info.get("cash", 0.0)
            return float(bp or 0.0)
        return self.config.simulated_buying_power_usd

    def same_day_strategy_order_exists(self, ticker: str, trading_day: date) -> bool:
        if self._list_orders_fn is None:
            return False
        day_iso = trading_day.isoformat()
        payload = build_alpaca_list_orders_payload(
            is_paper_api=self.config.is_paper_api,
            symbols=[ticker],
            side="buy",
            status="all",
            after=f"{day_iso}T00:00:00Z",
            until=f"{day_iso}T23:59:59Z",
        )
        return bool(self._list_orders_fn(payload))

    def same_day_strategy_order_exists_with_ref_id_prefix(
        self, ticker: str, trading_day: date, ref_id_prefixes: Tuple[str, ...]
    ) -> Optional[Dict[str, Any]]:
        # build_alpaca_market_buy_payload carries no client-order-id field, so
        # place_market_buy below never sends this strategy's ref_id to the
        # live connector -- no listed Alpaca order could ever be matched by
        # ref_id here even with list_orders_fn wired. Returning None ("no
        # known duplicate") would silently disable retry protection for a
        # guarded top-up: an explicitly enabled live AlpacaBroker could then
        # place a second real order on every retry. Fail closed instead --
        # this raises, which _same_stream_order_exists's caller already
        # converts into a blocked candidate (Codex review, PR #231: "Fail
        # closed for Alpaca until client IDs are wired") -- the same posture
        # as an adapter that doesn't implement this method at all. Real
        # conflict protection for this adapter requires plumbing a
        # client-order-id through the connector payload and inspecting
        # listed orders here -- out of scope while ALPACA is not a selected
        # backend in any config.
        raise RuntimeError(
            "AlpacaBroker cannot verify same-stream order duplicates: "
            "place_market_buy does not send a client order id the live "
            "connector could match against"
        )

    def same_day_order_with_ref_id_prefix_any_state(
        self, ticker: str, trading_day: date, ref_id_prefixes: Tuple[str, ...]
    ) -> Optional[Dict[str, Any]]:
        # Same posture as same_day_strategy_order_exists_with_ref_id_prefix
        # above -- AlpacaBroker has no client-order-id wired through
        # place_market_buy, so no listed order could ever be matched by
        # ref_id here regardless of state. Fail closed.
        raise RuntimeError(
            "AlpacaBroker cannot verify same-stream order duplicates: "
            "place_market_buy does not send a client order id the live "
            "connector could match against"
        )

    def strategy_order_with_ref_id(
        self, ticker: str, trading_day: date, ref_id: str
    ) -> Optional[Dict[str, Any]]:
        raise RuntimeError(
            "AlpacaBroker cannot reconcile order history by client id: "
            "place_market_buy does not send a client order id"
        )

    def same_day_ticker_notional_usd(self, ticker: str, trading_day: date) -> float:
        # Same posture as same_day_strategy_order_exists_with_ref_id_prefix
        # above: real order-history verification for this adapter is out of
        # scope while ALPACA is not a selected backend in any config. Fail
        # closed rather than silently returning 0.0 and letting a guarded
        # top-up trust an artifact-only figure this adapter cannot verify.
        raise RuntimeError(
            "AlpacaBroker cannot verify same-day order notional: "
            "list_orders_fn wiring for this adapter is not implemented"
        )

    def is_tradable_for_fractional_buy(self, ticker: str) -> bool:
        return True

    def is_tradable_for_whole_share_buy(self, ticker: str) -> bool:
        # Whole-share tickers are Robinhood-only by design (see
        # review_whole_share_buy/place_whole_share_buy below) -- this
        # adapter is never actually selected for them. Fail closed rather
        # than a permissive stub that would misleadingly suggest support.
        return False

    def review_market_buy(self, ticker: str, notional_usd: float) -> tuple[bool, str]:
        return True, "alpaca dry-run review approved"

    def build_market_buy_payload(
        self, ticker: str, notional_usd: float
    ) -> Dict[str, Any]:
        return build_alpaca_market_buy_payload(
            symbol=ticker,
            notional_usd=notional_usd,
            is_paper_api=self.config.is_paper_api,
            time_in_force=self.config.time_in_force,
            extended_hours=self.config.extended_hours,
        )

    def place_market_buy(self, ticker: str, notional_usd: float, ref_id: str) -> str:
        payload = self.build_market_buy_payload(ticker, notional_usd)
        if self.config.enable_live_orders and self._place_order_fn is not None:
            return self._place_order_fn(payload)
        mode = "PAPER" if self.config.is_paper_api else "LIVE"
        return f"ALPACA-DRYRUN-{mode}-{ticker}-{payload['input']['notional']}-{ref_id}"

    def review_whole_share_buy(self, ticker: str, quantity: int) -> tuple[bool, str]:
        # Whole-share tickers (near_close_dca.WHOLE_SHARE_TICKERS) are
        # Robinhood-only by design (docs/whole_share_accumulation.md); this
        # adapter is never actually selected for them. Fail closed rather
        # than a permissive dry-run stub that would misleadingly suggest
        # Alpaca support.
        return False, "AlpacaBroker does not support whole-share buys; Robinhood-only execution"

    def place_whole_share_buy(self, ticker: str, quantity: int, ref_id: str) -> str:
        raise RuntimeError("AlpacaBroker does not support whole-share buys; Robinhood-only execution")

    def get_order_fill(self, order_id: str) -> Optional[OrderFill]:
        if not order_id or "DRYRUN" in order_id:
            return None
        if self._order_fill_fn is None:
            if self.config.enable_live_orders:
                logger.warning(
                    "AlpacaBroker.get_order_fill has no order_fill_fn wired while "
                    "enable_live_orders is True; order %s will be reported as "
                    "unfilled",
                    order_id,
                )
            return None
        try:
            return self._resolve_alpaca_order_fill(order_id)
        except Exception:  # noqa: BLE001 - a fill-lookup outage or malformed response must not abort the run
            logger.exception("order-fill lookup failed for %s; recording as unfilled", order_id)
            return None

    def _resolve_alpaca_order_fill(self, order_id: str) -> Optional[OrderFill]:
        """Resolve ``order_id`` to a fill, following any ``replaced_by`` chain.

        An Alpaca order that is replaced (status ``'replaced'``) stops
        accumulating fills under its own id; any remaining quantity continues
        under a new order id in its ``'replaced_by'`` field. Follow that
        chain, summing the filled quantity and computing the notional-
        weighted average price across every hop, until reaching a status
        that is genuinely terminal (``filled``/``canceled``/``expired``,
        or ``done_for_day``/``calculated`` for a ``'day'`` time-in-force
        order -- see ``_ALPACA_TERMINAL_FILL_STATUSES``) with no further
        replacement -- or a non-terminal status (``partially_filled``,
        ``new``, ...), which means the order isn't resolved yet and stays
        eligible for a later refresh.

        Every ambiguous or unresolved shape reports no fill rather than
        freezing whatever was accumulated so far, so a later refresh gets a
        chance to retry: an unresolvable ``replaced_by`` hop, a missing
        ``replaced_by``/cyclic chain (per Alpaca's documented semantics a
        genuinely replaced order always carries its replacement's id, so a
        missing one signals an incomplete response, not a permanent
        characteristic), a chain longer than the hop cap, a terminal
        ``'filled'`` hop whose own numerics don't parse (a truly filled
        order always has positive fill data), and ANY hop (intermediate or
        terminal) with a genuinely positive quantity but an unusable price
        (a real execution whose notional can't be computed). The one case
        that IS trusted as final despite a hop's own numerics not parsing is
        a terminal ``'canceled'``/``'expired'``/``'done_for_day'``/
        ``'calculated'`` hop with a genuinely non-positive (explicit, finite
        zero) quantity: those can legitimately report a zero fill (nothing
        executed before the terminal state), which is a real answer, not
        malformed data.
        """
        if self._order_fill_fn is None:
            return None

        seen_ids = {order_id}
        current_id = order_id
        total_qty = 0.0
        total_notional = 0.0
        earliest_submitted_at: Optional[str] = None
        latest_filled_at: Optional[str] = None

        for hop_index in range(_ALPACA_MAX_REPLACEMENT_HOPS):
            payload = build_alpaca_get_order_payload(current_id, self.config.is_paper_api)
            data = self._order_fill_fn(payload)
            order = _extract_alpaca_order(data, current_id)
            if order is None:
                return None

            status = order.get("status")

            # Only the ORIGINAL order's own submitted_at counts as the
            # chain's earliest submission time -- every replacement is
            # created strictly later, so substituting a later hop's
            # submitted_at when the original omits one would understate
            # elapsed time rather than leaving it honestly unknown (Codex
            # review: "Keep incomplete replacement-chain timestamps
            # unknown").
            if hop_index == 0:
                submitted_at_str = order.get("submitted_at")
                if submitted_at_str:
                    earliest_submitted_at = submitted_at_str

            if _alpaca_has_unpriced_fill(order):
                return None

            parsed = _parse_alpaca_order_fill(order)
            if parsed is not None:
                filled_qty, filled_avg_price = parsed
                total_qty += filled_qty
                total_notional += filled_qty * filled_avg_price
                # The LAST quantity-contributing hop's filled_at is the true
                # completion time; if that hop omits it, the aggregate
                # completion time is genuinely unknown -- don't keep an
                # earlier, now-superseded hop's timestamp instead.
                latest_filled_at = order.get("filled_at")

            replaced_by = order.get("replaced_by")
            if status == "replaced":
                if replaced_by and replaced_by not in seen_ids:
                    seen_ids.add(replaced_by)
                    current_id = replaced_by
                    continue
                # No replaced_by to follow, or a cyclic chain (Codex review:
                # "Retry replacement chains without a usable next hop").
                return None

            # 'done_for_day' means Alpaca won't execute the order any
            # further today; 'calculated' per Alpaca's own docs means
            # "completed for the day (either filled OR done for day),
            # settlement pending" -- NOT a synonym for 'filled', it can
            # equally BE the done_for_day case. Either way, that's only a
            # durable terminal signal for a 'day' time-in-force order: it
            # expires with the trading day, so no same-day-or-later
            # execution can still land on it. For any other TIF (e.g.
            # 'gtc'), Alpaca can resume working the order on a later
            # trading day, so both stay non-terminal here (Codex review:
            # "Accept done_for_day Alpaca fills" / "Gate calculated status
            # on the order's TIF").
            is_day_only_status_terminal = (
                status in ("done_for_day", "calculated")
                and self.config.time_in_force == "day"
            )
            if status not in _ALPACA_TERMINAL_FILL_STATUSES and not is_day_only_status_terminal:
                # Genuinely non-terminal (e.g. partially_filled, new): not yet
                # resolved, so report no fill and let a later refresh retry.
                return None

            if parsed is None and not (
                status in ("canceled", "expired", "done_for_day", "calculated")
                and _alpaca_qty_is_explicit_zero(order)
            ):
                # A 'filled' order always has positive fill numerics, so
                # parsed being None there always means this response is
                # malformed or incomplete (Codex review: "Retry chains
                # whose terminal fill details are invalid"). A terminal
                # 'canceled'/'expired'/'done_for_day'/'calculated' hop is
                # trusted as a genuine zero fill ONLY when filled_qty is an
                # explicit, finite zero -- a missing, non-numeric,
                # non-finite, or negative value there is not proof nothing
                # executed either (Codex review: "Retry canceled
                # replacements with invalid quantities"). Either way,
                # treating an earlier hop's partial as final here would
                # freeze a possibly-stale number.
                return None
            break
        else:
            logger.warning(
                "order-fill replacement chain for %s exceeded %d hops "
                "without resolving; reporting no fill so a later refresh retries",
                order_id,
                _ALPACA_MAX_REPLACEMENT_HOPS,
            )
            return None

        if total_qty <= 0:
            return None

        # A response omitting a timestamp -- or one that parses to a naive
        # datetime, unsafe to compare against another hop's timezone-aware
        # one -- leaves it unknown rather than fabricating a value: stamping
        # with now() would persist a spurious near-zero latency as broker
        # evidence, and a naive/aware mismatch would raise downstream in
        # build_execution_record()'s latency subtraction (Codex review:
        # "Reject mixed-awareness fill timestamps").
        submitted_at = _parse_alpaca_timestamp(earliest_submitted_at)
        filled_at = _parse_alpaca_timestamp(latest_filled_at)

        return OrderFill(
            avg_fill_price=total_notional / total_qty,
            quantity_filled=total_qty,
            order_submitted_at=submitted_at,
            order_filled_at=filled_at,
        )

    def get_raw_placement_responses(self) -> List[Dict[str, Any]]:
        return []


def account_pinning_failure(
    target_account_number: Optional[str],
    broker: "BrokerName | str | None" = None,
) -> Optional[str]:
    """Return why ``target_account_number`` cannot pin a live run, or ``None`` if it can.

    A live run must know, explicitly, which brokerage account it is allowed to trade.
    Three values fail that test:

      * falsy (``None``/``""``) — nothing was configured, so a
        ``configured != actual`` comparison short-circuits and silently permits
        ANY account the adapter happens to be wired to;
      * :data:`_UNSET_ACCOUNT_SENTINEL` — ``ROBINHOOD_AGENTIC_ACCOUNT_NUMBER`` was
        not set in the environment, so the module-level default is a placeholder,
        not an account;
      * for Robinhood only, anything that is not 6-12 digits.

    The digit shape is Robinhood's, not every broker's. Applying it unconditionally
    made ``build_broker`` reject a perfectly normal Alpaca identifier (a ``PA...``
    paper account) before execution ever reached the ALPACA branch, so the
    documented broker-agnostic live adapter could not be constructed at all
    (Codex review, PR #219). ``broker`` defaults to Robinhood because every
    caller that omits it -- the morning and midday streams -- is a Robinhood
    stream, and the artifact schema requires the digit shape for those runs.
    The nonempty/placeholder checks above are broker-agnostic and always apply:
    no backend may trade an account nobody named.

    Shared by both live execution paths on purpose. ``build_broker`` refuses to
    construct a live adapter, and ``morning_dca``'s class-based executor refuses to
    place, on exactly the same condition — previously the executor guarded with
    ``if expected_account and ...``, so an empty configured value disabled its
    account check entirely rather than blocking the run.
    """
    if not target_account_number:
        return (
            "config.target_account_number is unset "
            f"({target_account_number!r}), so the live account cannot be pinned"
        )
    if target_account_number == _UNSET_ACCOUNT_SENTINEL:
        return (
            "config.target_account_number is the unset placeholder "
            f"({target_account_number!r}); the ROBINHOOD_AGENTIC_ACCOUNT_NUMBER "
            "environment variable is not set"
        )
    if broker is None or BrokerName(broker) == BrokerName.ROBINHOOD:
        if not _ACCOUNT_NUMBER_SHAPE.fullmatch(target_account_number):
            return (
                f"config.target_account_number is a {len(target_account_number)}-character "
                "value that is not a valid Robinhood account number (expected 6-12 "
                "digits); the value is withheld because a malformed one is often a "
                "secret pasted into the wrong variable"
            )
    return None


def build_broker(
    config: StrategyConfig,
    alpaca_config: Optional[AlpacaConfig] = None,
    **adapter_kwargs: Any,
) -> BrokerAdapter:
    """Return the BrokerAdapter for ``config.broker`` without changing strategy logic.

    For ``BrokerName.ROBINHOOD`` a live :class:`RobinhoodBroker` is returned when any
    Robinhood MCP callable is supplied via ``adapter_kwargs`` (e.g. ``review_fn=...``,
    ``place_fn=...``); otherwise a :class:`DryRunBroker` is used so unwired callers keep
    the safe simulator. For ``BrokerName.ALPACA`` an :class:`AlpacaBroker` is returned.
    Live placement stays gated behind ``config.dry_run`` and the adapter's own
    ``enable_live_orders`` flag regardless of which backend is selected.

    Security: for a live run (``config.dry_run`` is False) ``config.target_account_number``
    must be a real, explicitly-configured value. ``run_once`` guards against trading the
    wrong account with ``broker.account_number() != config.target_account_number``, but every
    branch below constructs the broker with ``account=config.target_account_number``, so that
    check is trivially satisfied by construction and can never catch a missing account number.
    Refuse to build a live broker (the ALPACA branch, and the ROBINHOOD branch when adapter
    callables are wired) here instead, before any live adapter is constructed.
    """
    if not config.dry_run:
        pinning_failure = account_pinning_failure(
            config.target_account_number, config.broker
        )
        if pinning_failure:
            raise RuntimeError(
                f"build_broker: config.dry_run is False but {pinning_failure}. Set the "
                "ROBINHOOD_AGENTIC_ACCOUNT_NUMBER environment variable (or otherwise "
                "configure a real account number) before running live, or set dry_run=True."
            )
    if config.broker == BrokerName.ALPACA:
        return AlpacaBroker(
            config=alpaca_config or AlpacaConfig(),
            account=config.target_account_number,
            **adapter_kwargs,
        )
    if config.broker == BrokerName.ROBINHOOD and adapter_kwargs:
        # Imported lazily so the core strategy module has no hard dependency on the
        # live-adapter layer (keeps import graph and tests light when unused).
        from dca_live_adapters import RobinhoodBroker

        return RobinhoodBroker(account=config.target_account_number, **adapter_kwargs)
    if not config.dry_run:
        # A live run (dry_run=False) must never fall through to the DryRunBroker: run_once's
        # live branch would call its place_market_buy, record the buy, and mark it submitted
        # with a DRY-RUN id though no order was sent. Refuse the unwired build instead.
        raise RuntimeError(
            "build_broker: config.dry_run is False but no live broker could be constructed "
            f"for {config.broker.value} (no adapter callables supplied). Wire the broker "
            "callables or set dry_run=True."
        )
    return DryRunBroker(account=config.target_account_number)


def iso_week_key(day: date) -> tuple[int, int]:
    iso = day.isocalendar()
    return iso.year, iso.week


def completed_bar_anchor(
    decision_dt: datetime, interval_minutes: int, config: StrategyConfig
) -> datetime:
    if config.assume_bar_timestamps_are_start_times:
        return decision_dt - timedelta(minutes=interval_minutes)
    return decision_dt


def latest_bar_at_or_before(bars: Iterable[Bar], target: datetime) -> Optional[Bar]:
    # ⚡ Bolt Optimization: single-pass loop avoids per-candidate key=lambda calls and generator-expression overhead in this hot path.
    best = None
    for bar in bars:
        if bar.timestamp <= target:
            if best is None or bar.timestamp > best.timestamp:
                best = bar
    return best


def kill_switch_engaged(config: StrategyConfig) -> bool:
    """Return True when the rolling-deployment kill-switch should cap sizing.

    Engaged when capital deployed in the trailing 7 days
    (``config.deployed_last_7d_usd``, injected at runtime from the deployment
    history) exceeds ``kill_switch_7d_deploy_fraction`` of the configured monthly
    cash allocation. A non-positive allocation disables the guard so a
    mis-/unconfigured allocation can never wedge the ladder to 1x.
    """
    allocation = config.monthly_cash_allocation_usd
    if allocation <= 0:
        return False
    fraction = config.kill_switch_7d_deploy_fraction
    if not 0 <= fraction <= 1:
        return False
    threshold = fraction * allocation
    return config.deployed_last_7d_usd > threshold


def _ticker_sizing(ticker: Optional[str], config: StrategyConfig) -> Mapping[str, Any]:
    """Return validated symbol calibration, or an empty mapping for global fallback."""
    if not ticker:
        return {}
    candidate = config.per_ticker_sizing.get(ticker.upper(), {})
    return candidate if isinstance(candidate, Mapping) else {}


def _inverse_martingale_config(ticker: Optional[str], config: StrategyConfig) -> Mapping[str, Any]:
    """Return this ticker's validated inverse-Martingale calibration, or ``{}``.

    ``{}`` means the mode is fully off for this ticker -- either it has no
    entry in ``config.inverse_martingale`` (see
    ``dca_config.load_inverse_martingale_config``, which already drops any
    ``enabled: false`` entry at load time) or ``ticker`` is falsy.
    """
    if not ticker:
        return {}
    candidate = config.inverse_martingale.get(ticker.upper(), {})
    return candidate if isinstance(candidate, Mapping) else {}


def minimum_drop_for_ticker(config: StrategyConfig, ticker: Optional[str] = None) -> float:
    """Return the first positive calibrated threshold for a symbol."""
    calibration = _ticker_sizing(ticker, config)
    tiers = calibration.get("tiers", config.sizing_tiers)
    return min(float(threshold) for threshold, _ in tiers)


def raw_ladder_multiplier(
    drop_vs_previous_close: float, config: StrategyConfig, ticker: Optional[str] = None
) -> float:
    """The graded ladder's own tier match -- BEFORE the ML nudge, the 5x cap, or
    the kill-switch cap -- for a drop from prior close.

    ``drop_vs_previous_close`` is a fraction (0.02 == 2.0% down). The largest tier
    threshold less than or equal to the drop determines the multiplier; a drop
    below the first threshold returns 0.0 (no buy). See StrategyConfig.sizing_tiers.

    Factored out of :func:`graded_buy_multiplier` so a caller that needs the
    ladder's OWN severity classification -- e.g. the high_multiplier_threshold
    selloff-breadth count that escalates the day's budget tier -- can read it
    without the ML sizing nudge or kill-switch cap distorting it (see
    ReconciledDecision.ladder_multiplier's own docstring for why that distinction
    matters).
    """
    if _inverse_martingale_config(ticker, config):
        # Mirrors graded_buy_multiplier's own identical suppression -- see
        # that function's docstring for the full rationale. An enrolled
        # ticker's ladder is fully suppressed, so its raw tier match is
        # always 0 too, not just its final (ML/cap-adjusted) multiplier.
        return 0.0
    calibration = _ticker_sizing(ticker, config)
    tiers = calibration.get("tiers", config.sizing_tiers)
    multiplier = 0.0
    for threshold, tier_multiplier in sorted(tiers):
        if drop_vs_previous_close >= threshold:
            multiplier = tier_multiplier
    return multiplier


def graded_buy_multiplier(
    drop_vs_previous_close: float, config: StrategyConfig, ticker: Optional[str] = None
) -> float:
    """Map a drop from prior close to a buy multiplier via the graded ladder.

    ``drop_vs_previous_close`` is a fraction (0.02 == 2.0% down). The largest tier
    threshold less than or equal to the drop determines the multiplier; a drop below
    the first threshold returns 0.0 (no buy). See StrategyConfig.sizing_tiers.

    When the dynamic risk kill-switch is engaged (see ``kill_switch_engaged``) any
    positive multiplier is capped to 1x: the strategy still participates in a dip
    at the base amount but stops scaling up. A 0x (no-buy) stays 0x.
    """
    multiplier = raw_ladder_multiplier(drop_vs_previous_close, config, ticker)
    if multiplier > 0:
        # ml-forecaster's published, bounded (see config/ml_sizing_adjustment.json
        # "bounds") per-ticker nudge. Absent/stale/malformed publishes are
        # already normalized to an empty mapping by
        # dca_config.load_ml_sizing_adjustment, so .get(..., 1.0) is a
        # provable no-op with no ML output configured. Applied only to a
        # positive tier match -- a 0x (no-buy) drop must stay 0x regardless of
        # the ML factor. Applied BEFORE the kill-switch cap below so the
        # kill-switch remains the final word on scaling.
        ml_factor = config.ml_sizing_adjustment.get((ticker or "").upper(), 1.0)
        multiplier = multiplier * ml_factor
    multiplier = min(multiplier, 5.0)
    if kill_switch_engaged(config):
        multiplier = min(multiplier, 1.0)
    return multiplier


# base_selection_reason values recorded per signal for the first-allocation base.
BASE_BELOW_CLOSE_AND_LOW = "below_prior_close_and_low"  # $2 scale
BASE_BELOW_CLOSE_ONLY = "below_prior_close_only"  # $1 scale
BASE_NOT_BELOW_CLOSE = "not_below_prior_close_no_buy"  # $0, no buy


def select_first_allocation_base_usd(
    decision_price: float,
    previous_close: float,
    previous_low: Optional[float],
    config: StrategyConfig,
    ticker: Optional[str] = None,
) -> tuple[float, str]:
    """Select the first-allocation base dollar amount before the ladder multiplier.

    Policy (applied per ticker before ``graded_buy_multiplier``):

      * decision price not below the prior regular-session close -> $0 (no buy).
      * below the prior close but not below the prior regular-session low ->
        the reduced ``base_buy_amount_below_close_usd`` ($1) scale.
      * below both the prior close and the prior low -> the full
        ``base_buy_amount_usd`` ($2) scale.

    A missing/unknown ``previous_low`` is treated conservatively as "not below the
    low" so an unavailable low can never upgrade the base to the larger $2 scale.
    """
    if not (decision_price < previous_close):
        return 0.0, BASE_NOT_BELOW_CLOSE
    calibration = _ticker_sizing(ticker, config)
    # A model must never produce a sub-dollar notional. The $1 floor applies
    # before the multiplier, so every positive tier produces at least $1.
    full_base = max(1.0, float(calibration.get("base_amount_usd", config.base_buy_amount_usd)))
    reduced_base = max(
        1.0,
        float(calibration.get("base_amount_below_close_usd", config.base_buy_amount_below_close_usd)),
    )
    if (
        previous_low is not None
        and math.isfinite(previous_low)
        and 0 < previous_low <= previous_close
        and decision_price < previous_low
    ):
        return full_base, BASE_BELOW_CLOSE_AND_LOW
    return reduced_base, BASE_BELOW_CLOSE_ONLY


# Substrings (checked case-insensitively) that indicate a provider raised because the
# ticker itself is unresolved/unlisted on that source (e.g. GFUZ on the finance
# connector) rather than a transient failure. This distinction matters: reconcile_signals
# treats provider_error=True as unsafe-to-auto-buy, but a permanently-unresolved ticker
# on one source should still allow the documented Robinhood-only BUY path, not permanently
# force MANUAL_REVIEW every run. See docs data_source_notes in config/tickers.json.
_TICKER_NOT_FOUND_MARKERS = (
    "not found",
    "no data found",
    "invalid symbol",
    "unknown symbol",
    "unresolved symbol",
    "404",
)


def _is_ticker_not_found_error(exc: Exception) -> bool:
    message = str(exc).lower()
    return any(marker in message for marker in _TICKER_NOT_FOUND_MARKERS)


def _compute_signal_timestamps(
    now: datetime, config: StrategyConfig, interval_minutes: int
) -> tuple[date, datetime, datetime, datetime]:
    now_et = now.astimezone(EASTERN)
    trading_day = now_et.date()
    decision_dt = datetime.combine(trading_day, config.decision_time_et, tzinfo=EASTERN)
    decision_anchor = completed_bar_anchor(decision_dt, interval_minutes, config)
    lookback_anchor = decision_anchor - timedelta(minutes=config.trend_lookback_minutes)
    return trading_day, decision_dt, decision_anchor, lookback_anchor


def evaluate_source_signal(
    ticker: str,
    now: datetime,
    config: StrategyConfig,
    data: MarketDataProvider,
    interval_minutes: int,
) -> SourceSignal:
    trading_day, decision_dt, decision_anchor, lookback_anchor = (
        _compute_signal_timestamps(now, config, interval_minutes)
    )

    bars = data.get_intraday_bars(
        ticker=ticker,
        start=datetime.combine(trading_day, time(9, 30), tzinfo=EASTERN),
        end=decision_dt,
        interval_minutes=interval_minutes,
    )
    decision_bar = latest_bar_at_or_before(bars, decision_anchor)
    lookback_bar = latest_bar_at_or_before(bars, lookback_anchor)
    previous_close_bar = data.get_previous_close_bar(ticker, decision_dt)

    if decision_bar is None or lookback_bar is None or previous_close_bar is None:
        return SourceSignal(
            ticker=ticker,
            source=data.source,
            action=Action.NO_DATA,
            reason="missing completed bar or previous close",
        )

    decision_price = decision_bar.close
    previous_close = previous_close_bar.close
    previous_low = previous_close_bar.low
    lookback_price = lookback_bar.close

    # Signal-time quote is the intended execution target. Prefer a live quote from
    # the provider (get_quote) captured at signal time; otherwise fall back to the
    # completed decision-bar close. decision_bar_close is always retained separately.
    decision_bar_close = decision_bar.close
    quote_price = decision_bar_close
    quote_time = decision_bar.timestamp
    get_quote = getattr(data, "get_quote", None)
    if callable(get_quote):
        quote = get_quote(ticker, decision_dt)
        if quote is not None and isinstance(quote, (tuple, list)) and len(quote) >= 2:
            quote_price = float(quote[0])
            quote_time = quote[1]
    price_vs_previous_close_pct = (decision_price / previous_close - 1.0) * 100.0
    intraday_trend_pct = (decision_price / lookback_price - 1.0) * 100.0
    drop_vs_previous_close = (previous_close - decision_price) / previous_close
    drop_vs_previous_close_pct = drop_vs_previous_close * 100.0
    buy_multiplier = graded_buy_multiplier(drop_vs_previous_close, config, ticker)
    # See ReconciledDecision.ladder_multiplier's own docstring: the raw
    # ladder tier match, before the ML nudge/caps buy_multiplier already
    # reflects, kept separately for the high_multiplier_threshold selloff-
    # breadth count.
    ladder_multiplier = raw_ladder_multiplier(drop_vs_previous_close, config, ticker)
    selected_base_amount_usd, base_selection_reason = select_first_allocation_base_usd(
        decision_price, previous_close, previous_low, config, ticker
    )
    if buy_multiplier <= 0:
        # Canonical rule item 6: "not lower than close, OR multiplier is 0" ->
        # no-buy. select_first_allocation_base_usd only looks at price vs.
        # close/low, so a price below the close with a drop too shallow to
        # clear the first ladder tier (multiplier 0) would otherwise still
        # carry a below_prior_close_only/and_low reason despite being a no-buy.
        base_selection_reason = BASE_NOT_BELOW_CLOSE
    suggested_amount_usd = selected_base_amount_usd * buy_multiplier
    if buy_multiplier > 0:
        # ml-forecaster's per-ticker nudge (already folded into buy_multiplier
        # by graded_buy_multiplier) can push an otherwise-valid tier match's
        # effective multiplier below 1.0 -- its published bounds allow
        # factors down to 0.5 -- which combined with the $1-floored base can
        # still land a genuine buy below the broker's $1 minimum notional
        # (e.g. a 1x tier * 0.5 factor = $0.50). Re-floor the FINAL dollar
        # amount here, not the multiplier itself (which would distort tier
        # semantics like high_multiplier_threshold comparisons elsewhere),
        # and only when this is a genuine buy -- a 0x (no-buy) must stay $0
        # (Codex review: "Keep ML-adjusted buys above the broker minimum").
        suggested_amount_usd = max(1.0, suggested_amount_usd)

    below_previous_close = decision_price < previous_close
    # A calibrated symbol's own first tier is the authoritative minimum drop
    # (Codex review: "Let calibrated first tiers override the global
    # floor") -- config/per_ticker_sizing.json is a deliberate, reviewed
    # per-symbol model (e.g. AAAU's 0.01% first tier), not a misconfiguration
    # to clamp up to the global default. Flooring it at
    # config.minimum_drop_vs_previous_close would silently disable part of
    # that checked-in model by vetoing a buy the calibrated ladder already
    # approved (buy_multiplier > 0). Only an UNCALIBRATED (fallback) symbol
    # is floored at the global minimum.
    effective_minimum_drop = (
        minimum_drop_for_ticker(config, ticker)
        if _ticker_sizing(ticker, config)
        else config.minimum_drop_vs_previous_close
    )
    minimum_drop_met = drop_vs_previous_close >= effective_minimum_drop
    intraday_trend_down = decision_price < lookback_price
    above_previous_close = decision_price > previous_close
    intraday_trend_up = decision_price > lookback_price

    trend_required = not getattr(config, "ignore_trend_filter", False)
    if (
        below_previous_close
        and minimum_drop_met
        and buy_multiplier > 0
        and (intraday_trend_down or not trend_required)
    ):
        action = Action.BUY
        if trend_required:
            reason = "below prior close, minimum drop met, 60-minute trend down"
        else:
            reason = (
                "below prior close, minimum drop met, trend filter bypassed (final-buy)"
            )
    elif above_previous_close and intraday_trend_up:
        action = Action.SKIP
        reason = "above prior close and 60-minute trend up"
    elif below_previous_close and not minimum_drop_met:
        action = Action.NO_ACTION
        reason = "below prior close but below 0.1% minimum drop"
    elif below_previous_close and not intraday_trend_down and trend_required:
        action = Action.NO_ACTION
        reason = "below prior close but 60-minute trend not down"
    else:
        action = Action.NO_ACTION
        reason = "mixed or flat conditions"

    return SourceSignal(
        ticker=ticker,
        source=data.source,
        action=action,
        reason=reason,
        decision_price=decision_price,
        previous_close=previous_close,
        lookback_price=lookback_price,
        price_vs_previous_close_pct=price_vs_previous_close_pct,
        intraday_trend_pct=intraday_trend_pct,
        drop_vs_previous_close_pct=drop_vs_previous_close_pct,
        buy_multiplier=buy_multiplier if action == Action.BUY else 0.0,
        ladder_multiplier=ladder_multiplier if action == Action.BUY else 0.0,
        suggested_amount_usd=suggested_amount_usd if action == Action.BUY else 0.0,
        previous_low=previous_low,
        selected_base_amount_usd=(
            selected_base_amount_usd if action == Action.BUY else 0.0
        ),
        base_selection_reason=base_selection_reason,
        decision_bar_timestamp=decision_bar.timestamp,
        previous_close_timestamp=previous_close_bar.timestamp,
        lookback_bar_timestamp=lookback_bar.timestamp,
        quote_price=quote_price,
        quote_time=quote_time,
        decision_bar_close=decision_bar_close,
    )


def _target_fields(signal: SourceSignal) -> Dict[str, Any]:
    """Derive execution-target fields from the source signal that drives the buy.

    target_price defaults to the signal-time quote (SourceSignal.quote_price), while
    decision_bar_close keeps the completed regular-session bar close for comparison.
    """
    return {
        "target_price": signal.quote_price,
        "target_price_source": f"{signal.source.value}:signal_quote",
        "target_quote_time": signal.quote_time,
        "decision_bar_close": signal.decision_bar_close,
    }


def reconcile_signals(
    ticker: str,
    finance_signal: Optional[SourceSignal],
    robinhood_signal: Optional[SourceSignal],
) -> ReconciledDecision:
    finance_action = finance_signal.action if finance_signal else Action.NO_DATA
    robinhood_action = robinhood_signal.action if robinhood_signal else Action.NO_DATA

    if Action.BUY in {finance_action, robinhood_action}:
        errored = [
            name
            for name, signal in (
                ("finance", finance_signal),
                ("robinhood", robinhood_signal),
            )
            if signal is not None and signal.provider_error
        ]
        if errored:
            return ReconciledDecision(
                ticker=ticker,
                action=Action.MANUAL_REVIEW,
                reason=f"provider error on {', '.join(errored)}; do not auto-buy",
                finance_signal=finance_signal,
                robinhood_signal=robinhood_signal,
            )

    if finance_action == Action.BUY and robinhood_action == Action.BUY:
        # Keep amount, base, AND multiplier all from the SAME winning signal --
        # whichever produced the smaller suggested_amount_usd -- so the
        # reconciled decision's own base * multiplier always equals its amount
        # (Codex review: "Keep the winning amount's multiplier paired with its
        # base", following "Preserve the base that produced the reconciled
        # amount"). Independently taking min(base1, base2) and
        # min(mult1, mult2) can each come from a DIFFERENT, non-winning signal
        # -- e.g. finance $2*2.5x=$5 vs. Robinhood $1*3.5x=$3.50: amount is
        # Robinhood's $3.50, so both its base ($1) and multiplier (3.5x) must
        # be used together, not finance's mismatched 2.5x.
        if finance_signal is not None and robinhood_signal is not None:
            winning_signal = (
                finance_signal
                if finance_signal.suggested_amount_usd
                <= robinhood_signal.suggested_amount_usd
                else robinhood_signal
            )
            return ReconciledDecision(
                ticker=ticker,
                action=Action.BUY,
                reason="finance and Robinhood agree on BUY",
                finance_signal=finance_signal,
                robinhood_signal=robinhood_signal,
                buy_multiplier=winning_signal.buy_multiplier,
                ladder_multiplier=winning_signal.ladder_multiplier,
                suggested_amount_usd=winning_signal.suggested_amount_usd,
                selected_base_amount_usd=winning_signal.selected_base_amount_usd,
                **cast(Any, _target_fields(winning_signal)),
            )

    if finance_action == Action.BUY and robinhood_action != Action.BUY:
        return ReconciledDecision(
            ticker=ticker,
            action=Action.MANUAL_REVIEW,
            reason=f"finance BUY but Robinhood is {robinhood_action.value}; do not auto-buy",
            finance_signal=finance_signal,
            robinhood_signal=robinhood_signal,
        )

    if robinhood_action == Action.BUY and finance_action == Action.NO_DATA:
        if robinhood_signal is not None:
            return ReconciledDecision(
                ticker=ticker,
                action=Action.BUY,
                reason="Robinhood-only BUY because finance source is unavailable",
                finance_signal=finance_signal,
                robinhood_signal=robinhood_signal,
                buy_multiplier=robinhood_signal.buy_multiplier,
                ladder_multiplier=robinhood_signal.ladder_multiplier,
                suggested_amount_usd=robinhood_signal.suggested_amount_usd,
                selected_base_amount_usd=robinhood_signal.selected_base_amount_usd,
                **cast(Any, _target_fields(robinhood_signal)),
            )

    if robinhood_action == Action.BUY and finance_action != Action.BUY:
        return ReconciledDecision(
            ticker=ticker,
            action=Action.MANUAL_REVIEW,
            reason=f"Robinhood BUY but finance is {finance_action.value}; do not auto-buy",
            finance_signal=finance_signal,
            robinhood_signal=robinhood_signal,
        )

    return ReconciledDecision(
        ticker=ticker,
        action=(
            Action.NO_ACTION
            if Action.NO_DATA not in {finance_action, robinhood_action}
            else Action.NO_DATA
        ),
        reason=f"no reconciled BUY; finance={finance_action.value}, robinhood={robinhood_action.value}",
        finance_signal=finance_signal,
        robinhood_signal=robinhood_signal,
    )


def within_caps(
    amount: float, state: StrategyState, trading_day: date, config: StrategyConfig
) -> bool:
    """True if ``amount`` (the amount actually about to be ordered) fits the remaining cap.

    Takes the amount explicitly rather than reading it off a decision so a
    caller that reduced a candidate's amount (e.g. the kill-switch's mid-batch
    cap in ``run_once``) checks caps against what will really be submitted,
    not the pre-cap ladder amount.

    Also enforces ``config.max_orders_per_day`` (the roster-wide daily
    order-count circuit breaker, config/budgets.json
    circuit_breakers.max_orders_per_day) against ``state``'s running count of
    buy attempts booked for ``trading_day`` -- this is the one gate every
    scheduled slot (run_dca.run_slot/run_pipeline -> near_close_dca) and
    manual run actually places orders through, unlike dca_runner.plan_orders(),
    which only the disabled 12:30 assess() path calls (Codex review: "Apply
    the order-count cap to every live placement path"). ``None`` means
    uncapped, matching a directly constructed StrategyConfig's default.
    """
    if amount <= 0:
        return False
    if amount > state.remaining_spend_today(trading_day, config):
        return False
    if (
        config.max_orders_per_day is not None
        and state.day_order_count(trading_day) + 1 > config.max_orders_per_day
    ):
        return False
    return True


def _quote_bid_ask(
    data: Optional[MarketDataProvider], ticker: str, as_of: datetime
) -> Optional[tuple[float, float]]:
    """Return a live bid/ask quote when the provider exposes one.

    The scheduled live path uses this as a final pre-placement spread circuit
    breaker. Providers that cannot expose bid/ask return ``None``; a concrete
    bid/ask with an excessive spread blocks the order before the broker path.
    """
    get_bid_ask = getattr(data, "get_bid_ask", None)
    if not callable(get_bid_ask):
        return None
    quote = get_bid_ask(ticker, as_of)
    if quote is None or not isinstance(quote, (tuple, list)) or len(quote) < 2:
        return None
    try:
        bid = float(quote[0])
        ask = float(quote[1])
    except (TypeError, ValueError):
        return None
    if not math.isfinite(bid) or not math.isfinite(ask):
        return None
    if bid <= 0 or ask <= 0 or ask < bid:
        return None
    return bid, ask


def quote_spread_pct(
    data: Optional[MarketDataProvider], ticker: str, as_of: datetime
) -> Optional[float]:
    """Return bid/ask spread as a percent of quote midpoint, if available."""
    bid_ask = _quote_bid_ask(data, ticker, as_of)
    if bid_ask is None:
        return None
    bid, ask = bid_ask
    midpoint = (bid + ask) / 2.0
    if midpoint <= 0:
        return None
    return (ask - bid) / midpoint * 100.0


def allocation_sort_key(decision: ReconciledDecision) -> Tuple[float, float, str]:
    """Deterministic allocation priority for buy candidates.

    Orders by higher multiplier first, then larger percent drop, then ticker
    alphabetical (A->Z) as the final tie-break so a capped run always fills the
    same names the strategy state promises. Numeric keys are negated (rather than
    sorting with ``reverse=True``) so ticker still sorts ascending.
    """
    drop = max(
        (
            decision.finance_signal.drop_vs_previous_close_pct
            if decision.finance_signal
            else 0.0
        ),
        (
            decision.robinhood_signal.drop_vs_previous_close_pct
            if decision.robinhood_signal
            else 0.0
        ),
    )
    return (-decision.buy_multiplier, -drop, decision.ticker)


def _signal_target_price(decision: ReconciledDecision) -> Optional[float]:
    """Return the decision-bar close used as the buy target price at signal time.

    Prefer the finance decision price, falling back to Robinhood. Returns None when
    neither source carried a usable decision price so downstream slippage math can
    flag ``target_price_missing`` instead of computing against a fabricated value.
    """
    for signal in (decision.finance_signal, decision.robinhood_signal):
        if signal is not None and signal.decision_price > 0:
            return signal.decision_price
    return None


def _signal_previous_close(decision: ReconciledDecision) -> Optional[float]:
    """Return the prior regular-session close used as the drop basis.

    Mirrors :func:`_signal_target_price`'s finance-preferred, Robinhood-fallback
    order. Returns ``None`` when neither source carried a usable value.
    """
    for signal in (decision.finance_signal, decision.robinhood_signal):
        if signal is not None and signal.previous_close > 0:
            return signal.previous_close
    return None


# Same-source-price-agreement tolerance used only by the inverse-Martingale
# accumulator's cross-source safety check (see
# _inverse_martingale_reconciled_price) -- not related to the broker spread
# gate's max_bid_ask_spread_pct, which bounds a single source's own bid/ask.
_INVERSE_MARTINGALE_SOURCE_AGREEMENT_TOLERANCE = 0.02


def _inverse_martingale_reconciled_price(decision: ReconciledDecision) -> Optional[Tuple[float, float]]:
    """Cross-source-verified ``(decision_price, previous_close)``, or ``None``.

    The accumulator bypasses ``evaluate_source_signal``'s normal action-based
    BUY gate: an enrolled ticker's ladder multiplier is forced to ``0.0`` by
    ``graded_buy_multiplier``, so ``decision.action`` is never ``BUY`` and
    ``reconcile_signals``'s own finance/Robinhood-disagreement handling never
    gets a chance to run for it (Codex review: "Reconcile provider prices
    before firing the accumulator" -- without this, a single source alone
    reporting a recovery, while the other stays at the low or errors, could
    fire a real order despite the two providers actively disagreeing).

    This applies the same safety bar directly to the two raw signals instead:
    both sources must be present, neither may carry a ``provider_error``, and
    their decision prices AND prior closes must agree within
    ``_INVERSE_MARTINGALE_SOURCE_AGREEMENT_TOLERANCE``. Deliberately more
    conservative than ``reconcile_signals`` (which allows a Robinhood-only
    BUY when finance is merely unavailable, not erroring): a disagreement or
    single-source gap here only delays this ticker's fire to a later run
    (deferred, not lost), so there is no reason to accept single-source
    trust for a decision that risks a synthetic, non-ladder-gated order.
    """
    finance = decision.finance_signal
    robinhood = decision.robinhood_signal
    if finance is None or robinhood is None:
        return None
    if finance.provider_error or robinhood.provider_error:
        return None
    # A NaN/inf price from either source must be caught explicitly, not
    # inferred from the positivity/tolerance checks below: EVERY comparison
    # against NaN is false (so "nan <= 0" never rejects it), and "inf > x"
    # is true while "inf > inf" is false -- an infinite finance.decision_price
    # would sail past the tolerance check below (since it computes
    # tolerance * inf = inf too, and inf is never > inf), then win
    # _signal_target_price's own "> 0" preference check (inf > 0 is true),
    # handing an infinite decision_price to the accumulator. Fed into
    # evaluate_inverse_martingale_step, an infinite decision_price makes
    # drop_metric go to -inf (a "price" infinitely above the prior close),
    # which makes ANY active cycle's recovery check
    # ((lowest_drop_seen - drop_metric) >= recovery_offset) trivially true --
    # firing a real synthetic order regardless of the actual accumulated
    # balance's true price history (Codex review: "Reject non-finite
    # reconciled prices").
    if not (
        math.isfinite(finance.decision_price)
        and math.isfinite(robinhood.decision_price)
        and math.isfinite(finance.previous_close)
        and math.isfinite(robinhood.previous_close)
    ):
        return None
    if finance.decision_price <= 0 or robinhood.decision_price <= 0:
        return None
    if finance.previous_close <= 0 or robinhood.previous_close <= 0:
        return None
    tolerance = _INVERSE_MARTINGALE_SOURCE_AGREEMENT_TOLERANCE
    if abs(finance.decision_price - robinhood.decision_price) > tolerance * finance.decision_price:
        return None
    if abs(finance.previous_close - robinhood.previous_close) > tolerance * finance.previous_close:
        return None
    decision_price = _signal_target_price(decision)
    previous_close = _signal_previous_close(decision)
    if decision_price is None or previous_close is None:
        return None
    return decision_price, previous_close


def _whole_share_redispatch_reconciled_price(decision: ReconciledDecision) -> Optional[float]:
    """Cross-source-verified current quote price for a whole-share fire, or
    ``None`` if the sources disagree or either is unusable.

    Originally written for _run_once_impl's preserved-fire redispatch (see
    that function's own comment on "Re-dispatch preserved fires without
    requiring a new BUY") -- that path bypasses ``reconcile_signals``'s
    action-based BUY gate exactly like the inverse-Martingale accumulator
    does, since ``decision.action`` is ``NO_ACTION``, not ``BUY``, so
    ``reconcile_signals``'s own finance/Robinhood-disagreement handling
    never ran for that decision. Selecting one source's ``quote_price``
    unconditionally (finance preferred, as the original redispatch code did)
    without a cross-source agreement check would let a REAL price
    disagreement between the two sources (e.g. finance $9.50 vs. Robinhood
    $20) size and approve an order against the more favorable source's price
    while the other actively disagrees -- bypassing the
    ``max_per_order_usd`` ceiling, which is computed against whichever price
    this function returns (Codex review: "Reconcile prices before
    redispatching preserved fires").

    ALSO called by ``_process_whole_share_candidate`` for an ordinary,
    fresh ``Action.BUY`` decision when both sources are present:
    ``reconcile_signals``'s own "finance and Robinhood agree on BUY" branch
    selects ONE winning signal's ``quote_price`` purely by whichever
    produced the smaller ``suggested_amount_usd`` -- it never checks that
    price against the OTHER source's own quote either, so the exact same
    disagreement hazard applies to a fresh BUY as to a redispatch (Codex
    review: "Reconcile fresh whole-share BUY prices before sizing").

    Mirrors :func:`_inverse_martingale_reconciled_price`'s exact same safety
    bar, applied to ``quote_price`` (the live execution-time quote) rather
    than ``decision_price`` (the signal-time comparison price used for the
    drop-vs-previous-close trigger) since a whole-share fire always executes
    at the CURRENT price, not a historical bar.
    """
    finance = decision.finance_signal
    robinhood = decision.robinhood_signal
    if finance is None or robinhood is None:
        return None
    if finance.provider_error or robinhood.provider_error:
        return None
    finance_price = finance.quote_price or finance.decision_bar_close
    robinhood_price = robinhood.quote_price or robinhood.decision_bar_close
    if not (math.isfinite(finance_price) and math.isfinite(robinhood_price)):
        return None
    if finance_price <= 0 or robinhood_price <= 0:
        return None
    tolerance = _INVERSE_MARTINGALE_SOURCE_AGREEMENT_TOLERANCE
    if abs(finance_price - robinhood_price) > tolerance * finance_price:
        return None
    # The HIGHER of the two in-tolerance quotes, not unconditionally
    # finance's -- actual execution happens on Robinhood
    # (place_whole_share_buy is Robinhood-only; see RobinhoodBroker's own
    # class docstring), so sizing/threshold/ceiling math against a LOWER
    # quote than what the broker will actually fill at can authorize
    # spending beyond what a caller believes it approved. With the
    # documented Finance=$9.90/Robinhood=$10.09 tolerance-boundary case, a
    # $10 pending balance and the default $10 per-order ceiling both looked
    # sufficient/compliant against the $9.90 finance price alone, even
    # though the broker was already quoting above both figures (Codex
    # review: "Size whole-share orders using the higher reconciled quote").
    # Still requires agreement WITHIN tolerance first (the check above) --
    # this only decides which of the two agreeing quotes to use, never
    # widens what counts as agreement.
    return max(finance_price, robinhood_price)


def _inverse_martingale_advance_age_for_missing_data(
    ledger: InverseMartingaleLedger, ticker: str, trading_day: date
) -> None:
    """Keep an active cycle's age clock ticking through a session where this
    ticker's decision data is unusable (missing signal, provider error, or a
    cross-source disagreement _inverse_martingale_reconciled_price refuses).

    The injection site `continue`s past both of those cases BEFORE the
    ledger is ever read for a real evaluation -- so an active cycle simply
    never advanced trading_days_active/last_evaluated_trading_day for that
    session, no matter how many sessions in a row this happened. A ticker
    with unavailable data for well over max_cycle_days could then return
    months later and still fire its stale accumulated balance (evaluated
    against today's price but accumulated against a cycle-start reference
    close from a completely different market regime), and the same thing
    happens if a ticker leaves and later rejoins the active universe (Codex
    review: "Age cycles across missing-data sessions"). This performs the
    SAME age-only bookkeeping evaluate_inverse_martingale_step's own
    trading_days_active counter does, without running a real evaluation (no
    price data to evaluate against) and without touching anything else
    about the cycle.

    Best-effort, via the ledger's own compare-and-swap: if a concurrent
    process's REAL evaluation for this ticker has already moved the state
    (e.g. a different stream that DOES have data for this ticker this same
    session), that write already leaves the age current for real reasons,
    and this one is simply skipped rather than retried or forced.

    A `settlement_pending` cycle is left COMPLETELY untouched, never even
    having its age fields bumped -- a partial fire's owning process is
    still between its own claim and its own deferred settlement, and this
    helper's `dict(tracker_state)` copy would otherwise carry
    `settlement_pending` forward into a NEW on-disk state that still
    matches `expected_prior_state` for a compare-and-swap here, but no
    longer matches the EXACT state the owning process's settlement step
    expects: that settlement's own compare-and-swap would then fail,
    silently discarding whatever it placed if it succeeded, or leaving
    `settlement_pending` stuck forever (no other process would ever clear
    it) if it didn't (Codex review: "Preserve pending settlement leases
    during age-only updates"). Mirrors
    evaluate_inverse_martingale_step()'s own refusal to advance a pending
    lease at all -- the pending lease always wins, here too.

    Stamps `last_evaluated_is_real=False` alongside the date, NOT
    `last_evaluated_stream` -- that field is deliberately left at whatever
    a REAL evaluation last set it to (or absent, on a genuinely fresh
    tracker). `last_evaluated_trading_day` still has to move to today, or a
    genuine same-day evaluation later would increment `trading_days_active`
    a second time for one calendar day -- but that means a STATUS_FIRING
    tracker last really evaluated on an EARLIER day by, say, "afternoon"
    would otherwise carry that stale stream name forward into today's date
    stamp. If "afternoon" also happens to be the first stream with usable
    data TODAY, evaluate_inverse_martingale_step's STATUS_FIRING same-day
    guard (`last_evaluated_trading_day == today and last_evaluated_stream
    in (None, stream)`) would misread that as a retry of a stream that
    never actually touched this ticker today, and silently swallow the
    real continuation instead of placing it -- indefinitely, if only that
    one stream ever has usable data (Codex review: "Separate age updates
    from the retry stream identity"). `last_evaluated_is_real=False` is the
    third signal that guard now also checks, specifically to distinguish
    "the date moved because of a fabricated age-only bump" from "the date
    moved because THIS stream genuinely evaluated the ticker today" --
    every real evaluation path in dca_inverse_martingale.py restamps it
    back to True the moment it actually runs.
    """
    try:
        tracker_state = ledger.read(ticker)
    except CorruptedLedgerStateError as exc:
        # Same "skip only this ticker, leave the file for manual recovery"
        # contract as the real-evaluation branch's identical handling.
        logger.error("inverse-Martingale ledger unreadable for %s: %s", ticker, exc)
        return
    if not tracker_state or tracker_state.get("status", STATUS_NONE) == STATUS_NONE:
        return  # no active cycle to age
    if tracker_state.get("settlement_pending"):
        return  # a pending settlement lease is never touched by an age-only update
    trading_day_iso = trading_day.isoformat()
    if tracker_state.get("last_evaluated_trading_day") == trading_day_iso:
        return  # already advanced (or genuinely evaluated) today
    status = tracker_state.get("status", STATUS_NONE)
    accumulated = float(tracker_state.get("accumulated_usd", 0.0))
    new_state = dict(tracker_state)
    new_state["trading_days_active"] = int(tracker_state.get("trading_days_active", 0)) + 1
    new_state["last_evaluated_trading_day"] = trading_day_iso
    new_state["last_evaluated_is_real"] = False
    ledger.claim_fire(
        ticker,
        expected_prior_state=tracker_state,
        new_state=new_state,
        step=InverseMartingaleStep(
            status_before=status,
            status_after=status,
            accumulated_usd_before=accumulated,
            accumulated_usd_after=accumulated,
            newly_crossed_tiers=(),
            fired=False,
            fire_amount_usd=0.0,
            reason="data_unavailable_age_advanced",
        ),
    )


def _inverse_martingale_reset_if_disabled_mid_cycle(
    ledger: InverseMartingaleLedger, ticker: str, trading_day: date, stream: str
) -> None:
    """Abandon an active cycle when its ticker is no longer enrolled.

    The injection site skips a ticker entirely -- never even reading its
    ledger -- as soon as `_inverse_martingale_config` returns `{}` (the
    ticker has no entry in config.inverse_martingale, or its `enabled` flag
    was flipped to false). Left alone, that ticker's tracker.json sits
    completely frozen: not aged, not abandoned, not reset. Meanwhile
    `graded_buy_multiplier` no longer sees this ticker as enrolled either,
    so the NORMAL ladder resumes buying its dips immediately -- and if an
    operator later re-enrolls the ticker under the SAME tier/basis/unit_usd
    configuration (an identical fingerprint), the frozen cycle wakes back
    up and can fire the balance it accumulated before AND during the
    disabled interval as a real order, on top of whatever the ladder
    already bought in the meantime for the same descent (Codex review:
    "Reset active cycles when enrollment is disabled"). Disabling
    enrollment must abandon any active cycle outright, the same as any
    other "this cycle's assumptions no longer hold" reset
    (cycle_reset_basis_changed, cycle_reset_tier_config_changed) --
    a future re-enrollment then starts genuinely fresh.

    Best-effort via the ledger's own compare-and-swap, matching
    _inverse_martingale_advance_age_for_missing_data's philosophy: a lost
    CAS means a concurrent process already moved this ticker's state (real
    enrollment, a real fire, etc.), and this reset is simply skipped rather
    than forced over it. A `settlement_pending` cycle is left untouched for
    the same reason that helper leaves one untouched too: overwriting it
    here (even with a clean resolved_marker) would still move the on-disk
    state out from under the owning process's own settlement compare-and-
    swap, silently discarding whatever it placed.

    A resolved (``STATUS_NONE``) tracker is not necessarily inert either: a
    completed fire now leaves behind a durable ``rearm_reference_close``
    latch (see :func:`resolved_marker`) that keeps suppressing new cycles
    until price exits the old dip. Disabling enrollment while that latch is
    still armed and later re-enrolling the ticker must not inherit it --
    the ticker should start genuinely fresh, not remain silently blocked by
    a dip that happened entirely during the disabled interval (Codex
    review: "Clear resolved latches when enrollment is disabled"). Only a
    tracker actually carrying the latch is rewritten; a plain, latch-free
    ``STATUS_NONE`` marker (or an entirely absent one) has nothing to clear
    and is left alone, same as before.
    """
    try:
        tracker_state = ledger.read(ticker)
    except CorruptedLedgerStateError as exc:
        logger.error("inverse-Martingale ledger unreadable for %s: %s", ticker, exc)
        return
    status = tracker_state.get("status", STATUS_NONE) if tracker_state else STATUS_NONE
    if not tracker_state:
        return  # nothing to reset -- never started
    if status == STATUS_NONE and tracker_state.get("rearm_reference_close") is None:
        return  # already none, and no durable rearm latch to clear either
    if tracker_state.get("settlement_pending"):
        return  # a pending settlement lease is never touched by this reset either
    ledger.claim_fire(
        ticker,
        expected_prior_state=tracker_state,
        new_state=resolved_marker(trading_day, stream),
        step=InverseMartingaleStep(
            status_before=status,
            status_after=STATUS_NONE,
            accumulated_usd_before=float(tracker_state.get("accumulated_usd", 0.0)),
            accumulated_usd_after=0.0,
            newly_crossed_tiers=(),
            fired=False,
            fire_amount_usd=0.0,
            reason="cycle_reset_enrollment_disabled",
        ),
    )


#: Broker order states that mean "this order moved no capital and never will".
#: Mirrors scripts/broker_reconciliation._TERMINAL_ORDER_STATES, the repo's
#: canonical terminal set. Robinhood reports both "cancelled" and "canceled"
#: (and "voided"), so crash reconciliation must recognize every spelling:
#: reading a zero-fill "canceled" order as non-terminal made it substitute the
#: order's REQUESTED dollar_amount for the executed amount, which then matched
#: the claim exactly and permanently discarded an accumulator balance no shares
#: were ever bought with (Codex review: "Recognize every terminal spelling
#: before settling the claim").
#:
#: A SUPERSET of the states dca_live_adapters.RobinhoodBroker.place_market_buy
#: refuses on submission, and deliberately so: "expired" cannot come back from a
#: placement call, but order HISTORY reports it, and omitting it here left an
#: expired order looking indeterminate -- so its lease was preserved forever even
#: though the order can no longer execute (Codex review: "Treat expired broker
#: orders as settled").
_TERMINAL_BROKER_ORDER_STATES = frozenset(
    {"cancelled", "canceled", "rejected", "failed", "voided", "expired"}
)

#: Order states whose executed amount is FINAL and will not change again --
#: the failure states above, plus a completed fill. Every other state
#: (``new``/``queued``/``confirmed``/``unconfirmed``/``partially_filled``) is a
#: working order that can still execute more, so its executed amount so far is
#: not something a settlement decision may be based on. See
#: :func:`_recovered_broker_notional`.
_SETTLED_BROKER_ORDER_STATES = _TERMINAL_BROKER_ORDER_STATES | {"filled"}


@dataclass(frozen=True)
class InverseMartingaleLeaseRecovery:
    """One resolved crash lease, returned by :func:`_inverse_martingale_recover_pending_leases`.

    ``recovered_amount_usd`` is the capital the broker actually accepted for the
    claimed fire (its filled notional, or its submitted notional for an order
    still live). It is 0.0 when the lease expired with no order at all. The
    caller books that amount into ``StrategyState``/the trailing-7-day
    deployment figure and publishes a candidate outcome for it -- reconciling
    the ledger alone would leave the restarted run computing its daily, weekly
    and 7-day headroom as if the money had never been spent.
    """

    ticker: str
    claim_trading_day: date
    recovered_amount_usd: float
    recovered_state: Dict[str, Any]
    order_id: Optional[str]
    #: The deterministic ref the claim submitted under. Kept alongside
    #: ``order_id`` so deployment-history matching can recognize this order by
    #: either identifier -- see _same_day_order_deployment_already_recorded.
    claim_ref: Optional[str] = None
    #: The roster stream that made the claim, from the lease's
    #: ``settlement_stream``. ``None`` for a legacy lease written before the
    #: field existed, which callers must treat as "provenance unknown" rather
    #: than assuming this run's own stream -- deployment is accounted per
    #: stream and a lease is routinely recovered by a LATER one.
    claim_stream: Optional[str] = None
    #: Best-effort fill price/quantity read from the SAME broker history
    #: lookup that established recovered_amount_usd, independent of whether a
    #: later get_order_fill() call succeeds. ``None`` when the matched order
    #: carried no positive, parseable quantity/price (e.g. a terminal
    #: zero-fill). See _run_once_impl's recovered-fire execution-record call.
    fill_price: Optional[float] = None
    fill_quantity: Optional[float] = None


def _is_blank_broker_field(value: Any) -> bool:
    """True for ``None`` or a string that is empty/whitespace-only.

    A broker payload can represent "this field is absent" as ``None``, ``""``,
    or whitespace like ``" "`` -- all three must be treated as "genuinely
    absent" by the cumulative_quantity-vs-quantity fallback checks in
    ``_recovered_broker_notional``, ``_inverse_martingale_recover_pending_
    lease``, and ``RobinhoodBroker.get_order_fill()``. A plain ``is not None``
    or ``not in (None, "")`` check let a whitespace-only value select
    cumulative_quantity as the field to read, which then parsed to ``None``
    and preserved an otherwise-terminal lease indefinitely instead of valuing
    the fill (Codex review: "Treat whitespace-only cumulative quantities as
    absent"). Non-string values (numbers) are never blank.
    """
    if value is None:
        return True
    return isinstance(value, str) and not value.strip()


def _is_usable_order_id_scalar(candidate: Any) -> bool:
    """True when ``candidate`` is a genuinely usable order-id SCALAR.

    Shared by every caller that needs to sanity-check a raw broker/
    recovery-artifact value BEFORE treating it as a real order id -- not
    just ``_first_usable_order_id_alias``'s own primary/secondary alias
    selection, but any other site reinjecting a previously-recorded
    ``order_id`` scalar. Rejects: blank (``None``/``""``/whitespace),
    falsey (``0``/``False``), a non-scalar (list/dict), a boolean
    (excluded from the scalar allowlist even though ``bool`` subclasses
    ``int`` in Python), a non-positive number (native or a STRING
    spelling of one, e.g. ``"-1"``/``"0"``), and a non-finite float
    (native or a STRING spelling, e.g. ``"nan"``/``"inf"``) -- the same
    set of sentinels ``_normalized_order_id`` itself discards, so a value
    this predicate accepts is guaranteed to round-trip through that
    normalizer unchanged.
    """
    if _is_blank_broker_field(candidate) or not candidate:
        return False
    if not isinstance(candidate, (str, int, float)) or isinstance(candidate, bool):
        return False
    if isinstance(candidate, (int, float)) and candidate <= 0:
        return False
    if isinstance(candidate, float) and not math.isfinite(candidate):
        return False
    if isinstance(candidate, int):
        # A native int beyond Python's integer-to-string conversion digit
        # limit (e.g. a recovery artifact's raw `order_id=10**5000`) is
        # positive and finite by every check above, so this predicate
        # returned `True` for it -- but its own docstring promises every
        # accepted value "round-trips through `_normalized_order_id`
        # unchanged", and that normalizer's `str(order_id)` call raises
        # `ValueError` for a literal this large. `_first_usable_order_id_
        # alias` then selected this oversized primary over a valid
        # secondary, and downstream recovery code calling a bare
        # `str(order_id)` of its own (e.g. building `last_recovery`) raised
        # before a known broker fill/lease could be durably reconciled
        # (Codex review, PR #1169: "Reject unrepresentable native IDs
        # during recovery alias selection"). `math.isfinite` on an int this
        # large raises `OverflowError` when converting to `float` --
        # exactly the same magnitude bound `_is_representable_numeric_
        # order_id` (dca_live_adapters.py) already enforces for the
        # identical reason.
        try:
            math.isfinite(candidate)
        except OverflowError:
            return False
    if isinstance(candidate, str):
        # Parsed via `Decimal`, not `float()`: binary floating point
        # underflows a tiny but genuinely POSITIVE scientific spelling
        # (``"1e-5000"``) to ``0.0``, which this check then misclassified
        # as non-positive and rejected -- `_first_usable_order_id_alias`
        # fell through to a secondary alias (or `None`) even though
        # `_normalized_order_id` explicitly preserves that exact value,
        # so whole-share recovery booked or published the recovered
        # broker attempt without its durable identity, letting a later
        # reconciliation consume the wrong anonymous charge (Codex
        # review, PR #1169: "Preserve tiny positive IDs during recovery
        # alias selection"). `Decimal` stays exact at any magnitude the
        # same way `_normalized_order_id`'s own scientific-notation branch
        # already requires.
        try:
            _decimal_value = decimal.Decimal(candidate)
        except decimal.InvalidOperation:
            return True
        return _decimal_value.is_finite() and _decimal_value > 0
    return True


def _first_usable_order_id_alias(container: Dict[str, Any]) -> Any:
    """The first of ``"id"``/``"order_id"`` on ``container`` that is not blank.

    A raw ``container.get("id") or container.get("order_id")`` picks
    whichever is merely non-empty-string-truthy FIRST, so a blank
    placeholder on ``"id"`` (``""``, whitespace, or ``None``) alongside a
    real, usable ``"order_id"`` -- ``{"id": "   ", "order_id": "REAL-1"}``
    -- selected the blank placeholder over the real id, and callers that
    then normalized the result with ``str(... or "") or None`` recorded the
    attempt as anonymous even though a usable identifier was right there
    under the other alias, letting a later reconciliation for a different
    same-ticker order mistake this attempt for its own prior charge (Codex
    review, PR #1168: "Fall back past blank primary order IDs"). Diverges
    from ``dca_live_adapters._first_usable_order_id_alias`` in one respect
    -- that twin deliberately returns a non-string, non-blank primary
    (e.g. a boolean sentinel) as-is, leaving its own numeric/type
    validation to reject it downstream. This copy has no such downstream
    gate: it feeds durable id-backfill bookkeeping and live-order recovery
    directly, so a FALSEY primary sentinel -- ``{"id": 0, "order_id":
    "ORD"}`` -- must also fall through to the real secondary id, exactly
    as the plain ``id or order_id`` expression this function replaced
    already did. Treating only genuinely BLANK values as unusable (the
    original fix's scope) regressed that: `0` is not blank per
    ``_is_blank_broker_field``, so it was selected and returned verbatim,
    losing the real ``order_id`` to a placeholder no legitimate broker id
    is ever actually `0` (Codex review, PR #1169: "Fall back past falsey
    primary order-ID sentinels"). Also requires the primary to be a SCALAR
    (``str``/``int``/``float``/``bool``): a truthy NON-SCALAR primary
    (``{"id": ["BAD"], "order_id": "REAL"}``) is neither blank nor falsey,
    so it was returned verbatim and a caller stringifying the result
    directly (rather than routing it back through this module's own
    ``_normalized_order_id``) recorded the apparently-valid garbage id
    ``"['BAD']"``, burying the real ``order_id`` and letting a later
    reconciliation treat the same broker order as a distinct one (Codex
    review, PR #1169: "Validate recovered order IDs before stringifying
    them"). Now applies the SAME validity rules this module's own
    `_normalized_order_id` enforces -- reject a boolean sentinel, a
    non-positive number, and a non-finite float -- rather than accepting
    any scalar: a caller at a terminal whole-share recovery site
    stringifies the selected value directly, BEFORE `record_buy()` ever
    gets a chance to reject it via `_normalized_order_id`, so `{"id":
    True, "order_id": "REAL"}` was durably recorded as the apparently-
    valid id "True" instead of falling through to "REAL" (Codex review,
    PR #1169: "Fall through unusable scalar order aliases").

    The non-positive/non-finite rejection also applies when the sentinel
    is a STRING spelling of one (``id="-1"``, ``id="0"``), not just a
    native ``int``/``float``: the numeric-typed check alone missed this,
    so ``{"id": "-1", "order_id": "REAL"}`` and ``{"id": "0", "order_id":
    "REAL", "state": "queued"}`` still selected the string sentinel and
    hid "REAL" behind it. Several whole-share recovery call sites
    stringify this function's return value immediately (or pass it
    straight to `_normalized_order_id`, which discards it outright), so
    the recovered attempt was recorded/published under the unusable
    sentinel -- or left anonymous -- instead of reaching the real
    secondary id (Codex review, PR #1168/#1169: "Fall through stringified
    non-positive primary IDs" / "Fall through stringified sentinel order
    aliases" -- two independently-authored fixes for the identical gap).

    The SAME usability validation now applies to the fallback "order_id"
    alias too, not just the primary: a blank primary with a malformed
    secondary (``{"id": "", "order_id": ["BAD"]}``) still returned the
    list unchanged, and a caller stringifying it directly (before
    `_normalized_order_id` ever gets a chance to reject it) recorded the
    apparently-valid durable id ``"['BAD']"``. A later reconciliation
    under the real scalar id would then restore the same attempt again,
    prematurely consuming the daily order cap (Codex review, PR #1168:
    "Validate the secondary order-ID alias").
    """
    primary = container.get("id")
    if _is_usable_order_id_scalar(primary):
        return primary
    secondary = container.get("order_id")
    if _is_usable_order_id_scalar(secondary):
        return secondary
    return None


def _normalize_broker_lifecycle_alias(value: Any) -> Optional[str]:
    """Normalize a single ``state``/``status`` value, or ``None`` if blank.

    Two normalizations, shared by every caller that reads a broker row's
    lifecycle to decide whether its ``state`` and ``status`` aliases agree
    or to select the settled value between them:

    * BLANK (``None``, ``""``, whitespace) reads as absent, matching
      ``_is_blank_broker_field`` everywhere else in this module -- a row
      supplying one real alias and leaving the other an empty string
      (``state="queued", status=""``) is the ordinary single-alias case,
      not a conflict between two values.
    * A "cancelled" spelling collapses to "canceled": Robinhood reports
      both for the identical terminal state (see
      ``_TERMINAL_BROKER_ORDER_STATES``, which deliberately carries both
      spellings), so ``state="cancelled", status="canceled"`` is one
      broker answering itself in two dialects, not two disagreeing
      answers.

    Without both normalizations, a caller comparing raw ``state``/
    ``status`` values read either case as a conflict and reported the
    order UNKNOWN, or read only ``state`` and missed a row that carried
    its terminal fill exclusively through ``status`` (Codex review, PR
    #911 round 32: "Normalize lifecycle aliases before declaring
    conflicts", "Read recovered fill state from the status alias").
    """
    if _is_blank_broker_field(value):
        return None
    normalized = str(value).strip().lower()
    return "canceled" if normalized == "cancelled" else normalized


def _finite_nonnegative_float(value: Any) -> Optional[float]:
    """Parse ``value`` as a real, finite, non-negative float, or ``None``.

    ``None`` covers every unusable shape a broker field can take -- absent,
    non-numeric, ``NaN``/``Infinity`` (both of which ``float()`` accepts without
    raising), or negative -- so callers can treat "cannot be valued" as one
    case rather than letting a non-finite value flow into money arithmetic.

    A Robinhood money value is either a scalar or a ``{"amount": ...}`` mapping;
    both are accepted, matching ``scripts/broker_reconciliation._money``.
    Rejecting the mapping form made a perfectly valuable fill read as unreadable
    and preserved its lease indefinitely (Codex review: "Parse mapping-shaped
    executed notionals").
    """
    if isinstance(value, Mapping):
        value = value.get("amount")
    if value is None or isinstance(value, bool):
        return None
    try:
        parsed = float(value)
    except (TypeError, ValueError, OverflowError):
        # OverflowError alongside the usual conversion errors: json.loads()
        # parses an arbitrarily large JSON integer into an unbounded Python
        # int, and float() on one too large to represent RAISES rather than
        # returning inf. Uncaught, that escaped this function (and
        # _recovered_broker_notional's own try/except below it) entirely,
        # aborting the whole scheduled run over one malformed broker-history
        # response instead of treating that ticker's settlement as
        # indeterminate and preserving its lease (Codex review: "Catch
        # integer overflow while parsing broker amounts").
        return None
    if not math.isfinite(parsed) or parsed < 0:
        return None
    return parsed


#: Candidate-row fields fixed at DECISION time -- computed once when the
#: row is first produced and never mutated afterward, unlike the row's
#: volatile submission-lifecycle fields (``planned_amount_usd``,
#: ``incremental_order_amount``, ``status``, ``order_id``,
#: ``whole_share_order_ids``) which legitimately change as an order
#: resolves from decision through submission to a confirmed fill. Used by
#: _synthetic_uncertain_contributor_key to build a per-row identity that
#: survives that resolution instead of breaking on it (Codex review, PR
#: badMade/all-stock-dca#1171 discussion: "Preserve the anonymous key when
#: an order ID appears").
#:
#: Deliberately excludes ``target_price``/``decision_bar_close`` as bare
#: dict keys: not every writer uses those names for the same concept --
#: morning_dca.py's own in-flight/recovery candidate-row constructor logs
#: the decided price under ``decision_price`` instead, which a literal
#: ``target_price`` lookup here would silently read as absent, collapsing
#: every one of that constructor's rows down to whatever the OTHER fields
#: (``reason``, ``buy_multiplier``, ``previous_close``) alone distinguish
#: -- two genuinely different id-less morning contributions for the same
#: ticker could then land on the identical key, a false MATCH the whole
#: identity scheme exists to prevent (Codex review, PR
#: badMade/all-stock-dca#1171 discussion: "Hash the fields emitted by
#: morning candidates" -- a P1 caught in review). The decided price is
#: folded in separately below via ``_candidate_logged_reference_price``,
#: this module's own existing alias-priority resolver for exactly this
#: field-naming inconsistency (target_price, then decision_price, then
#: decision_bar_close -- see that function's docstring).
_UNCERTAIN_CONTRIBUTOR_IDENTITY_FIELDS = (
    "reason",
    "buy_multiplier",
    "target_price_missing",
    "previous_close",
)


def _synthetic_uncertain_contributor_key(
    ticker: str,
    run_id: Optional[str],
    run_state_path: Path,
    candidate: Mapping[str, Any],
) -> str:
    """Stable synthetic identity for a candidate-row contribution to ``uncertain_contributor_ids``.

    A contribution with no broker ``order_id`` can never be recorded in
    ``contributing_order_ids``. Without SOME per-contribution identity, two
    scans that each fail to re-observe the same anonymous contributor look
    identical to "the contributor was re-verified," which is exactly the
    coincidental-match gap ``contributing_order_ids`` already closes for
    known orders (see that field's docstring).

    Keyed on ``run_id`` (falling back to the artifact path when absent,
    matching every other dedupe key in this loader) plus a hash of the
    row's own DECISION-time fields (``_UNCERTAIN_CONTRIBUTOR_IDENTITY_
    FIELDS`` above) -- deliberately neither the row's full content nor its
    POSITION within the artifact's ``buy_candidates`` list. A full-content
    hash looked appealing (it distinguishes a genuinely different row from
    the same one re-read) but broke the one transition this identity most
    needs to survive: a row's own transient
    corruption (e.g. a ``NaN`` ``planned_amount_usd``) getting fixed between
    the first scan and a clean reload. That row is precisely why this
    field exists -- an id-less row IS this function's caller -- yet fixing
    its own amount changes the row's content and therefore its hash,
    producing a mismatch and permanently locking the ticker uncertain even
    though the exact same contributor was cleanly re-observed, resolved
    (Codex review, PR badMade/all-stock-dca#1171 discussion: "Retain
    identity after resolving an anonymous row" -- a P1 regression in an
    earlier version of this function). Position-within-the-list looked
    like the fix, but is unsound the OTHER direction: if a mutable
    ``run_state.json`` ever rebuilds its candidate list, a completely
    DIFFERENT contribution for the same ticker landing at the same index
    would generate the identical key, letting the merge wrongly treat an
    unrelated new contributor as proof the original one was re-observed --
    exactly the false-match risk this whole identity scheme exists to
    prevent (Codex review, PR badMade/all-stock-dca#1171 discussion:
    "Avoid treating a row position as contributor identity" -- a second P1
    caught on the position-keyed version of this function). Decision-time
    fields split this difference: they are fixed once (so they survive the
    row's own later resolution, unlike a full-content hash) yet specific
    to what was actually decided for THIS ticker at THIS moment (so a
    genuinely different, unrelated contribution is very unlikely to
    reproduce them, unlike a bare row index).

    Called ONLY for a row with no order_id at all -- every caller gates on
    ``not _represented`` before calling this (see
    ``uncertain_contributor_ids``' own docstring for why an id-FULL row
    must never touch that field: a stable ``order_id`` already proves
    identity through ``contributing_order_ids`` on its own, and layering
    THIS additional, weaker proof on top would make an already-proven
    match depend on decision-time fields a clean reload is legitimately
    allowed to correct -- a third P1 caught in review, "Skip synthetic
    provenance for already identified orders"). A row that starts id-less
    and later gains its first ``order_id`` is therefore an accepted
    exception this identity does NOT survive -- see
    ``uncertain_contributor_ids``' own docstring for why that tradeoff was
    chosen over the alternative.
    """
    identity_payload = {
        field_name: candidate.get(field_name)
        for field_name in _UNCERTAIN_CONTRIBUTOR_IDENTITY_FIELDS
    }
    # Folded in via the shared alias-priority resolver rather than a bare
    # `candidate.get("target_price")` -- see
    # _UNCERTAIN_CONTRIBUTOR_IDENTITY_FIELDS' own comment for why a literal
    # key lookup misses morning_dca.py's `decision_price`-named rows.
    identity_payload["decision_price"] = _candidate_logged_reference_price(candidate)
    digest = hashlib.sha256(
        json.dumps(identity_payload, sort_keys=True, default=str).encode("utf-8")
    ).hexdigest()[:16]
    root = run_id if run_id is not None else str(run_state_path)
    return f"uncertain:{ticker}:{root}:{digest}"


#: Filename of the local secret that keys lease account fingerprints. Lives
#: BESIDE the accumulator ledger tree (``<cron root>/.lease_fingerprint_key``),
#: never inside a tracker payload -- see :func:`_broker_account_fingerprint`.
_LEASE_FINGERPRINT_KEY_FILENAME = ".lease_fingerprint_key"

#: The exact shape ``secrets.token_hex(32)`` produces: 64 lowercase hex
#: characters, i.e. 256 bits. A partially restored or truncated key file can
#: contain valid UTF-8 that is still NOT this -- a one-character or
#: truncated hex string -- which the plain "is there text" check in
#: ``_published()`` accepted as the HMAC key. That silently keyed new
#: fingerprints with far fewer than the promised 256 bits of material (a
#: brute-forceable key that could expose the environment-only account
#: number via the tracker) while making every existing lease's fingerprint
#: permanently unmatchable against the real key once it is eventually
#: regenerated correctly (Codex review: "Validate persisted fingerprint key
#: material before use").
_LEASE_FINGERPRINT_KEY_PATTERN = re.compile(r"^[0-9a-f]{64}$")


def _fsync_directory(path: Path) -> None:
    """Best-effort fsync of a directory's own metadata (its entries), not its files.

    ``os.link``/``os.replace`` are atomic, but the directory entry they create
    can still be lost on power loss before the PARENT directory's own metadata
    reaches stable storage -- an ordinary ext4/xfs behavior, not a bug in
    either call. Called only after :func:`_lease_fingerprint_key` actually
    publishes the key, so a host that loses power in that window cannot come
    back up with the tracker write durable but the key gone, generating
    different key material next time and permanently unmatchable against the
    pending lease's ``settlement_account`` (Codex review: "Fsync the key
    directory after publishing"). Failure here is deliberately swallowed: a
    filesystem/platform that cannot open a directory for fsync (some
    read-only or exotic mounts) must not turn a successful key publish into a
    fatal error over a durability guarantee it cannot offer anyway.
    """
    try:
        fd = os.open(path, os.O_RDONLY)
    except OSError:
        return
    try:
        os.fsync(fd)
    except OSError:
        pass
    finally:
        os.close(fd)


def _lease_fingerprint_key(key_dir: Path) -> Optional[bytes]:
    """Return the local HMAC key for lease account fingerprints, creating it once.

    A fresh 256-bit random value, stored 0600 and published atomically so two
    concurrent streams cannot race two different keys into existence -- by hard
    link where the filesystem supports it, otherwise by a lock-serialized
    rename. Returns ``None`` when the key can neither be read nor created,
    which callers treat as "record no account identity" rather than falling
    back to something weaker.
    """
    path = Path(key_dir) / _LEASE_FINGERPRINT_KEY_FILENAME

    def _published() -> Optional[bytes]:
        try:
            existing = path.read_text(encoding="utf-8").strip()
        except (OSError, UnicodeDecodeError):
            # A partially restored or corrupted key file can contain
            # non-UTF-8 bytes, which read_text() raises on rather than
            # returning as an OSError. Uncaught, that propagated out of
            # _broker_account_fingerprint() during both live claim creation
            # and pending-lease recovery, aborting the entire scheduled run
            # instead of recording an unknown account identity (or
            # preserving the affected lease) fail-closed like every other
            # unusable-key case here (Codex review: "Treat an undecodable
            # fingerprint key as unavailable").
            return None
        if not existing:
            return None
        if not _LEASE_FINGERPRINT_KEY_PATTERN.match(existing):
            # Valid UTF-8 text that is not the exact 64-lowercase-hex shape
            # publication always writes -- a truncated or hand-edited file,
            # say. Trusting it as-is would key new fingerprints with
            # whatever (possibly far weaker) material it contains, and
            # accepting it as "the" key blocks this call from ever
            # regenerating a correct one, since the create-if-absent path
            # below only runs when nothing is already published.
            return None
        # The create path below always writes this file 0600, but an
        # ALREADY-published key can reach this path with a wider mode --
        # a backup restore or manual copy that did not preserve
        # permissions, say. A world/group-readable key file lets any other
        # local reader who also obtains a persisted account fingerprint
        # (e.g. from a lease/state artifact) recover the HMAC key and
        # enumerate this repo's small 6-12 digit account-number space,
        # defeating the entire reason this scheme uses a keyed digest
        # instead of an unkeyed one (Codex review: "Reject fingerprint
        # keys with unsafe file permissions"). Repaired in place rather
        # than refused: returning None here would be read as "no key
        # published yet" by the caller below, which would mint a NEW
        # random key and permanently strand every fingerprint already
        # computed against this one -- far worse than tightening the mode
        # on the correct, still-usable material already on disk. Only
        # when the repair itself fails (a mount that does not support
        # chmod, a permission error) does this fall back to the same
        # fail-closed "unusable" verdict every other unreadable-key case
        # here returns.
        try:
            if os.stat(path).st_mode & 0o077:
                os.chmod(path, 0o600)
        except OSError:
            return None
        return existing.encode("utf-8")

    already = _published()
    if already is not None:
        return already
    # Write the material to a private temp file FIRST and publish it with a
    # single atomic link. Creating the real path with O_EXCL and writing into it
    # afterwards left a window where a concurrent first-time process saw the
    # file exist, read it EMPTY, and gave up -- persisting a live claim as
    # settlement_account="unknown", which recovery then refuses to release
    # forever (Codex review: "Wait for the fingerprint key to be initialized").
    # os.link fails with FileExistsError if another process published first,
    # which is the whole point: exactly one key is ever published, and every
    # process reads that same one back rather than trusting its own material.
    material = secrets.token_hex(32)
    # A RANDOM temp suffix, not the pid: two threads in one process share a pid,
    # so a pid-named temp made every racer but the first fail its own O_EXCL
    # create and give up with None -- the very outcome this atomic publish
    # exists to prevent.
    tmp = path.parent / f"{_LEASE_FINGERPRINT_KEY_FILENAME}.{secrets.token_hex(8)}.tmp"
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        handle = os.open(tmp, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
        with os.fdopen(handle, "w", encoding="utf-8") as fh:
            fh.write(material)
            fh.flush()
            os.fsync(fh.fileno())
        # BOTH publication paths run under the SAME lock. os.link is itself
        # no-clobber, but os.replace is not, and only the replace path used to
        # take the lock -- so a process whose link failed could check
        # _published(), see nothing, and then have its replace() overwrite a key
        # a LINK-path process published in between. Any claim already
        # fingerprinted under the overwritten key could never match the
        # surviving one again, and recovery refuses to release a lease whose
        # account it cannot confirm: the accumulator freezes permanently, which
        # is the exact outcome every other guard here exists to prevent (Codex
        # review: "Avoid overwriting a concurrently published fingerprint key").
        #
        # The tempting cheaper fix -- retry os.link inside the lock and keep the
        # bare `if _published() is None: os.replace(...)` behind it -- rests on
        # link failure being a filesystem CAPABILITY, identical for every
        # process on the host, so that no unlocked fast-path caller could be
        # succeeding at the very call this one just proved broken. That premise
        # does not hold: a transient EIO/ENOSPC, an LSM denial that applies to
        # one process, or two mounts of the same tree with different link
        # support each put one racer on each path. The check-then-replace pair
        # is then still non-atomic against a link-path publisher holding no
        # lock, and the clobber survives -- see
        # test_lease_fingerprint_key_survives_a_mixed_link_and_replace_race,
        # which forces that interleaving and fails against exactly that variant.
        # Only a lock BOTH paths take closes it.
        #
        # Cheap despite wrapping the common path, because this is only reached
        # when no key exists yet -- the _published() fast path above returns on
        # every subsequent call, so the lock is taken about once per artifact
        # tree, ever. A waiter that cannot acquire within the timeout raises
        # TimeoutError -- itself an OSError -- and falls through to the outer
        # handler's _published(), the same fail-closed "record no account
        # identity" outcome as before.
        from scripts.file_lock import cross_process_lock

        with cross_process_lock(path.with_name(f"{path.name}.lock")):
            if _published() is None:
                try:
                    os.link(tmp, path)
                except FileExistsError:
                    pass  # another process published first; its key is the real one
                except OSError:
                    # The filesystem under $DCA_CRON_TRACKING_ROOT does not
                    # support or does not permit hard links (a bind-mounted
                    # share, some container overlays, exFAT/FAT). Without a
                    # fallback the outer handler returned None and EVERY live
                    # claim was persisted with settlement_account="unknown",
                    # which recovery then refuses to release -- freezing the
                    # accumulator permanently on those hosts (Codex review:
                    # "Provide a fallback when hard-link publication is
                    # unavailable"). os.replace() is atomic on every filesystem
                    # that can host this tree at all, and holding the lock makes
                    # the check-then-publish above atomic against every racer,
                    # so exactly one key is still ever published.
                    os.replace(tmp, path)
        # Durability, not correctness: os.link/os.replace are already atomic,
        # so the key is never observed half-written, but the directory ENTRY
        # they create can still vanish on power loss before the parent
        # directory's own metadata reaches stable storage. Unconditional --
        # harmless (and cheap) to run again when another process published
        # first, since it fsyncs the directory's current state either way.
        _fsync_directory(path.parent)
    except OSError:
        return _published()
    finally:
        try:
            tmp.unlink()
        except OSError:
            pass
    return _published()


def _broker_exposes_account_identity(broker: "BrokerAdapter") -> Optional[bool]:
    """Whether ``broker`` claims a real account identity at all.

    Split out of :func:`_broker_account_fingerprint` so a caller that needs
    to know WHY a fingerprint came back ``None`` -- "nothing to fingerprint"
    (a dry-run/simulated broker) versus "an identity exists but the keyed
    HMAC could not be computed" -- can ask without duplicating the accessor
    probe. Used by the unresolved-placement failure writer to fail closed
    on the second case rather than persisting evidence with a null account
    binding it never should have had (Codex review, PR #911 round 10:
    "Fail closed when evidence fingerprinting fails").

    Three-valued, not a plain bool: ``True`` (a real identity), ``False``
    (no ``account_number`` method, or one that cleanly returns blank -- both
    CONFIRM no identity), and ``None`` for a probe that raised. A broker
    that answered fine at the execution gate earlier this same run and only
    starts raising here (a transient connector hiccup) is not "confirmed to
    have no identity" -- collapsing that into ``False`` let the caller read
    it as "nothing to fingerprint" and persist a bare ``None`` account
    binding, the exact silent-skip this whole fail-closed path exists to
    prevent (Codex review, PR #911 round 13: "Treat account-probe errors as
    fingerprint failures"). ``None`` here means "unknown, not confirmed
    absent" and the caller treats it the same as a real identity: fail
    closed with the sentinel, never silently ``None``.
    """
    accessor = getattr(broker, "account_number", None)
    if not callable(accessor):
        return False
    try:
        account = accessor()
    except Exception:  # noqa: BLE001 - an identity probe must never break a run
        return None
    return isinstance(account, str) and bool(account.strip())


def _broker_account_fingerprint(broker: "BrokerAdapter", key_dir: Path) -> Optional[str]:
    """Return a stable, non-reversible identity for the account ``broker`` trades in.

    A **keyed** HMAC-SHA256, not a plain hash. The value is persisted into
    `tracker.json`, and the brokerage account number is a hard secret here (it
    lives only in ``$ROBINHOOD_AGENTIC_ACCOUNT_NUMBER``, and
    ``test_config_invariants.py`` greps source/config/docs/tests for
    account-shaped literals). A plain ``sha256(account)`` would NOT keep it
    secret: a Robinhood account is 6-12 decimal digits, so anyone holding the
    digest can enumerate the whole space -- a million candidates at the short
    end -- and recover the number exactly (Codex review: "Replace the reversible
    account-number fingerprint"). Keying it with a local secret the tracker
    never contains removes that offline-enumeration path.

    The key lives beside the ledger tree rather than inside it (see
    :func:`_lease_fingerprint_key`), so a tracker file shared, copied, or
    accidentally committed on its own carries nothing enumerable. It is a local
    secret, not a managed one: whoever copies the ENTIRE artifact root copies
    the key with it, and this function protects the tracker payload, not that
    root.

    Returns ``None`` when the adapter exposes no account identity (the
    dry-run/simulated brokers) or the key is unavailable, which callers treat as
    "no constraint recorded" rather than falling back to an unkeyed digest.
    """
    accessor = getattr(broker, "account_number", None)
    if not callable(accessor):
        return None
    try:
        account = accessor()
    except Exception:  # noqa: BLE001 - an identity probe must never break a run
        return None
    if not isinstance(account, str) or not account.strip():
        return None
    key = _lease_fingerprint_key(key_dir)
    if key is None:
        return None
    digest = hmac.new(key, account.strip().encode("utf-8"), hashlib.sha256).hexdigest()
    return digest[:_LEASE_ACCOUNT_FINGERPRINT_LENGTH]


# Not a valid hex digest of any real fingerprint (an actual one is exactly
# _LEASE_ACCOUNT_FINGERPRINT_LENGTH lowercase hex characters), so this can
# never accidentally match a later run's own computed fingerprint.
_ACCOUNT_FINGERPRINT_UNAVAILABLE_SENTINEL = "account-fingerprint-unavailable"


def _account_number_for_unresolved_evidence(
    broker: Optional["BrokerAdapter"], key_dir: Path
) -> Optional[str]:
    """The ``account_number`` to stamp on a failure artifact that may carry
    unresolved fractional-placement evidence.

    A plain ``_broker_account_fingerprint(...)`` call collapses two very
    different situations into the same ``None``: the broker genuinely has no
    account identity to fingerprint (dry-run/simulated -- fine, "no
    constraint recorded" is the correct reading), and the broker DOES have
    an identity but the keyed HMAC could not be computed (the local key file
    could not be read or created). `_reconcile_prior_unproven_fractional_
    placements` treats a null persisted fingerprint as the first case and
    skips its account check entirely -- so silently persisting ``None`` for
    the second case would let a later invocation, under a MISWIRED broker
    for a different account, trust this evidence's history lookup against
    the wrong account (Codex review, PR #911 round 10: "Fail closed when
    evidence fingerprinting fails").

    Returns the sentinel :data:`_ACCOUNT_FINGERPRINT_UNAVAILABLE_SENTINEL`
    for the second case instead of ``None``: a non-empty string that can
    never equal a real fingerprint, so the reconciler's own comparison
    permanently refuses to trust this artifact's evidence (raising
    "recorded for a different account") until a human resolves it -- fail
    closed on the READ side, rather than losing the evidence entirely by
    raising here and aborting the write.
    """
    if broker is None:
        return None
    fingerprint = _broker_account_fingerprint(broker, key_dir)
    if fingerprint is not None:
        return fingerprint
    # `is not False`, not truthiness: _broker_exposes_account_identity
    # returns None for a probe that raised -- unknown, not CONFIRMED
    # absent -- and that must fail closed exactly like a real identity
    # does. Only a confirmed False (no accessor at all, or one that
    # cleanly returned blank) means genuinely nothing to fingerprint.
    if _broker_exposes_account_identity(broker) is not False:
        return _ACCOUNT_FINGERPRINT_UNAVAILABLE_SENTINEL
    return None


def _recovered_broker_notional(order: Dict[str, Any]) -> Optional[float]:
    """Return the FINAL dollars ``order`` moved, or ``None`` when that is not yet
    knowable.

    Only a SETTLED order -- filled, or in one of the terminal failure states --
    has a final executed amount: its ground truth is ``cumulative_quantity *
    average_price``, and a terminal order with no fill moved nothing and
    reports 0.0 so its claimed balance is restored rather than written off.

    ``None`` -- "indeterminate, do not act" -- is returned for everything else,
    and callers must preserve the lease rather than treat it as a zero:

    * **A still-live order** (``new``/``queued``/``confirmed``/``unconfirmed``/
      ``partially_filled``). Substituting a live partial fill's executed amount
      here rebuilt an UNLEASED continuation for the currently-unfilled
      remainder -- while the original broker order was still working and could
      fill that very remainder itself. A later scheduled stream was then free
      to fire the remainder a second time, since inverse-Martingale candidates
      bypass the ordinary duplicate-order guard (Codex review: "Keep live
      partial fills leased until the order is terminal"). The lease stays until
      the order stops moving.
    * **An unusable amount** -- a non-numeric execution field, or a non-finite
      or negative result. Reading that as 0.0 made a genuinely live or filled
      order look like an unplaced claim, releasing the whole balance for a
      duplicate purchase on a later day, while an ``Infinity`` would instead be
      booked into strategy state as real spend (Codex review: "Preserve the
      lease when broker notional is unparseable").

    Falls back to ``status`` too, the SAME alias every other lifecycle
    reader in this module and ``dca_live_adapters.py`` already fall back
    to: a matched history row reporting its terminal state only through
    ``status`` (e.g. ``{"status": "cancelled", "executed_notional":
    "3.00"}`` with no ``state`` field at all) read as an empty, unsettled
    state here and returned ``None`` even though the surrounding
    reconciliation already recognized the row as terminal through the
    SAME alias -- stranding an otherwise settled partial fill as
    unresolved on every retry (Codex review, PR #911 round 33: "Read
    terminal lifecycle state from the status alias").

    Both aliases are read through ``_normalize_broker_lifecycle_alias``,
    not a bare ``or``/``.lower()`` -- a whitespace-only ``state`` (e.g.
    ``{"state": "   ", "status": "cancelled", ...}``) is truthy, so the
    raw ``or`` picked it over the real ``status`` value and produced an
    empty, unsettled string even though the surrounding reconciler --
    which already normalizes both aliases -- recognized the same row as
    terminal, stranding an already-settled order unresolved on every
    retry (Codex review, PR #911 round 36: "Normalize state before
    falling back to status").
    """
    normalized_state = _normalize_broker_lifecycle_alias(order.get("state"))
    normalized_status = _normalize_broker_lifecycle_alias(order.get("status"))
    # A row cannot simultaneously be settled and working. Do not let the
    # preferred ``state`` alias silently hide a contradictory ``status``.
    if normalized_state and normalized_status and normalized_state != normalized_status:
        return None
    state = normalized_state or normalized_status or ""
    if state not in _SETTLED_BROKER_ORDER_STATES:
        return None
    # executed_notional FIRST, matching scripts/broker_reconciliation._executed_
    # dollars: it is the broker's own cent-precise settled figure, while
    # quantity*price is a reconstruction from two separately-rounded fields that
    # lands a fraction of a cent off even for a genuine whole-cent fill. Ignoring
    # it entirely meant a perfectly valid supported row -- executed_notional
    # present, quantity or price absent -- reconstructed as $0.00, which
    # recovery then read as a confirmed zero-fill and released the whole claim
    # for a second purchase (Codex review: "Honor authoritative executed notional
    # during recovery").
    #
    # executed_dollar_amount and filled_notional are checked the SAME way,
    # in the SAME tier, right after: both are already recognized as
    # authoritative executed-notional evidence elsewhere in this
    # reconciliation code (see _FILL_EVIDENCE_ALIASES/_reconciled_order_
    # may_have_executed), but this function itself read only
    # executed_notional before falling to the quantity*price
    # reconstruction below. A matched `filled` row reporting its actual
    # spend only through one of these two aliases, with no
    # executed_notional and no quantity/price either, returned None here
    # even though the reconciliation decision already accepted the row --
    # the execution-log write then fell back to the larger approved
    # REQUEST amount instead of the actual, smaller fill (Codex review, PR
    # #911 round 33: "Read every supported notional alias for recovered
    # fills"). A value present but unusable (unparseable, non-positive) on
    # ANY of the three is tracked the same way a bad executed_notional
    # already was -- indeterminate, not a confirmed zero -- via
    # `_notional_present_but_unusable` below.
    _notional_present_but_unusable = False
    # Aggregated across ALL three aliases, not returned on the FIRST positive
    # one found: a terminal row reporting disagreeing values through two
    # different authoritative aliases -- {"executed_dollar_amount": "5",
    # "filled_notional": "100"} -- used to return the first-checked alias's
    # $5 outright, without ever inspecting whether "filled_notional" agreed.
    # `_inverse_martingale_recover_pending_lease` consumes this value
    # directly to decide the claim is fully settled and clear its lease, so
    # a genuinely $100 fill was booked and released as though it were only
    # $5 (Codex review, PR #911 round 41: "Reject conflicting recovered
    # notional aliases"). Two aliases reporting the SAME value (the ordinary
    # case, e.g. a connector that echoes one figure under two field names)
    # is agreement, not a conflict.
    #
    # An explicit, readable ZERO on one alias is tracked too, not silently
    # skipped: {"executed_notional": "0", "filled_notional": "5"} used to
    # leave the $0 out of the comparison entirely (only strictly-positive
    # values were ever compared), so `_agreeing_notional` settled on $5
    # alone -- one authoritative alias proving no execution at all, the
    # other proving a real fill, and neither ever compared against the
    # other (Codex review, PR #911 round 42: "Reject zero-versus-positive
    # notional aliases"). A positive value alongside an explicit zero is
    # exactly as contradictory as two disagreeing positive values.
    _agreeing_notional: Optional[float] = None
    _explicit_zero_seen = False
    for _notional_alias in ("executed_notional", "executed_dollar_amount", "filled_notional"):
        _alias_value = _finite_nonnegative_float(order.get(_notional_alias))
        if _alias_value is not None and _alias_value > 0:
            if _agreeing_notional is None:
                _agreeing_notional = _alias_value
            elif abs(_agreeing_notional - _alias_value) > 0.001:
                return None  # conflicting authoritative aliases -- indeterminate
            continue
        if _alias_value == 0.0:
            _explicit_zero_seen = True
            continue
        if _alias_value is None and order.get(_notional_alias) is not None:
            _notional_present_but_unusable = True
    if _notional_present_but_unusable:
        return None
    if _agreeing_notional is not None:
        if _explicit_zero_seen:
            return None  # one alias proves execution, another proves none
        # A direct notional does not make the row's independently reported
        # quantity/price evidence disappear.  Brokers can return both, and a
        # material disagreement means neither figure is safe to book.  In
        # particular, accepting a small direct value while ignoring a much
        # larger reconstruction can leave real exposure outside every cap and
        # kill-switch total.  Preserve the normal sub-cent tolerance for fields
        # that were rounded independently.
        _reported_price = _finite_nonnegative_float(order.get("average_price"))
        _quantity_aliases = (
            "cumulative_quantity",
            "executed_quantity",
            "filled_quantity",
            "quantity_filled",
        )
        if state == "filled":
            _quantity_aliases += ("quantity",)
        for _quantity_field in _quantity_aliases:
            _reported_quantity = _finite_nonnegative_float(order.get(_quantity_field))
            if _reported_quantity is None:
                continue
            if _reported_quantity == 0:
                # An EXPLICIT zero quantity is exactly as contradictory
                # here as an explicit zero notional alias already is a
                # few lines above (`_explicit_zero_seen`): `executed_
                # notional=5, cumulative_quantity=0` has the broker's own
                # direct dollar figure saying $5 moved while the SAME row's
                # quantity alias says zero shares executed -- internally
                # contradictory evidence, not a reading this function may
                # pick one side of. This check does NOT depend on
                # `average_price` being present or usable: gating it behind
                # a positive reported price let a row with no average_price
                # at all (`filled_notional=5, cumulative_quantity=0`, no
                # `average_price`) skip quantity inspection entirely and
                # settle on the positive direct notional alone, exactly the
                # contradictory-evidence bug this check exists to catch
                # (Codex review, PR #1164 round 13: "Check zero quantity
                # before requiring an average price"). Skipping the zero
                # (the old `<= 0` guard, and later the price-gated version)
                # let the positive direct notional alone settle the row as
                # a clean, agreeing fill, so fractional/inverse-Martingale
                # recovery booked or released a claim the broker's own
                # quantity alias disputed in the same breath (Codex review,
                # PR #1164: "Reject zero quantity that contradicts executed
                # notional").
                return None
            if _reported_price is not None and _reported_price > 0:
                _reconstructed_notional = _reported_quantity * _reported_price
                if not math.isfinite(_reconstructed_notional):
                    return None
                if abs(_agreeing_notional - _reconstructed_notional) > 0.001:
                    return None
        return _agreeing_notional
    # cumulative_quantity is the EXECUTED quantity. When it is genuinely absent
    # a FILLED row's plain ``quantity`` is the executed amount too -- the same
    # fallback scripts/broker_reconciliation._normalize_orders applies, and
    # without it a real fill valued as $0.00 and released the whole claim for a
    # duplicate purchase (Codex review: "Fall back to quantity when valuing
    # filled orders"). Scoped to "filled" on purpose: on a CANCELLED order
    # ``quantity`` is what was REQUESTED, not what executed, so using it there
    # would write off a balance no shares were bought with.
    quantity_field = "cumulative_quantity"
    if _is_blank_broker_field(order.get("cumulative_quantity")) and state == "filled":
        quantity_field = "quantity"
    quantity = _finite_nonnegative_float(order.get(quantity_field))
    price = _finite_nonnegative_float(order.get("average_price"))
    if quantity is not None and price is not None and quantity > 0 and price > 0:
        reconstructed = quantity * price
        # quantity and price are each individually finite -- _finite_
        # nonnegative_float guarantees that -- but their PRODUCT can still
        # overflow to inf (e.g. two ~1e308 broker fields). Recovery would
        # otherwise treat that infinity as real executed capital, clear the
        # lease, and pass it into ledger events and StrategyState.record_buy(),
        # corrupting budget totals (Codex review: "Reject overflowed
        # reconstructed notionals"). Indeterminate, not zero -- the lease
        # must be preserved rather than released or booked.
        if not math.isfinite(reconstructed):
            return None
        return reconstructed
    # No usable valuation. Distinguish "this order genuinely moved nothing" from
    # "this order reports a fill we could not value" -- only the first is a
    # confirmed zero. An unvalued fill is indeterminate and must keep the lease
    # (the same distinction broker_reconciliation tracks as has_unvalued_fill).
    # Covers all three notional aliases now, not just executed_notional.
    if quantity is None and order.get(quantity_field) is not None:
        return None  # present but unusable
    if quantity is not None and quantity > 0:
        return None  # a real fill whose price we could not read
    # A FILLED order that reached here has no positive valuation from any field
    # -- and unlike a terminal failure state, the broker is telling us it
    # executed. Returning 0.0 made recovery read it as a confirmed zero-fill,
    # restore the entire accumulator balance and allow it to be submitted again,
    # duplicating a purchase the broker says already happened (Codex review:
    # "Treat filled orders without positive notional as indeterminate"). Zero is
    # only ever a defensible answer for a CANCELLED/REJECTED/EXPIRED row, where
    # "nothing executed" is exactly what the state means.
    if state == "filled":
        return None
    return 0.0


def _lease_outage_trading_days(claim_trading_day: date, trading_day: date) -> int:
    """A conservative count of trading sessions a resolving lease was blind to.

    `_inverse_martingale_advance_age_for_missing_data` deliberately never
    touches a `settlement_pending` cycle's age fields -- see that function's
    own docstring on why racing the owning process's settlement write is
    unsafe. So while broker history stays unreachable and a lease sits
    pending, `trading_days_active`/`last_evaluated_trading_day` are frozen
    exactly as they were at claim time, no matter how many real sessions
    pass. Restoring the pre-claim state UNCHANGED once the lease finally
    resolves -- as every branch of `_inverse_martingale_recover_pending_
    lease` used to -- left the very next real evaluation crediting only a
    single `trading_days_active += 1` for the whole gap, so a cycle already
    close to `max_cycle_days` at claim time could resume and fire a stale
    balance well past its real age (Codex review: "Account for lease
    outage days before restoring the cycle").

    Calendar days, not trading days: this repo counts trading-day age by
    real EVALUATION calls, not calendar math (see evaluate_inverse_
    martingale_step's own comment on why `(trading_day - cycle_start).days`
    over-abandons by ~30%) -- but no trading-calendar utility exists here to
    count actual sessions in a date range, and the two failure directions are
    not symmetric: undercounting resumes a genuinely stale cycle with real
    money at risk, while overcounting only abandons a few sessions early,
    an opportunity-cost-only mistake. Calendar days is a safe UPPER bound on
    trading days elapsed, so it errs the cheap direction.

    Never negative -- a same-day resolution contributes nothing extra,
    since the claim day's own advance was already counted when the fire
    was originally claimed.
    """
    return max(0, (trading_day - claim_trading_day).days)


def _inverse_martingale_recover_pending_lease(
    ledger: InverseMartingaleLedger,
    ticker: str,
    tracker_state: Dict[str, Any],
    *,
    broker: "BrokerAdapter",
    dry_run: bool,
    trading_day: date,
    stream: str,
) -> Optional[InverseMartingaleLeaseRecovery]:
    """Resolve one ``settlement_pending`` crash lease, or preserve it untouched.

    A fire claim deliberately keeps the PRE-fire balance on disk and records the
    deterministic broker ref it is about to submit under, so a worker that dies
    between claim and placement loses no accumulated dollars. This is the other
    half of that contract: reconcile the ref against broker order history and
    either apply the claimed target state (the order really landed), rebuild a
    continuation for the unfilled remainder (a partial landed), or release the
    lease intact (nothing was ever placed and the claiming day has ended).

    Returns ``None`` -- leaving the lease exactly as found -- whenever the
    answer cannot be established: during the claiming trading day with no
    matching order (the original worker may still be between claim and submit),
    when the broker lookup fails, or when this invocation cannot see broker
    history at all. Preserving a lease costs one more session of a frozen
    balance; releasing one wrongly duplicates a real purchase.
    """
    claim_ref = tracker_state.get("settlement_ref_id")
    claim_day = tracker_state.get("settlement_trading_day")
    target = tracker_state.get("settlement_target_state")
    claimed_amount = float(tracker_state.get("settlement_claimed_usd", 0.0))
    # settlement_live records whether the CLAIMING invocation was allowed to
    # place real orders. A lease written before that field existed is assumed
    # live -- the fail-closed direction.
    lease_was_live = bool(tracker_state.get("settlement_live", True))
    try:
        claim_trading_day = date.fromisoformat(claim_day) if isinstance(claim_day, str) else None
    except ValueError:
        claim_trading_day = None
    if not isinstance(claim_ref, str) or claim_trading_day is None or not isinstance(target, dict):
        # A lease with unusable metadata cannot be reconciled OR safely
        # released; leave it for manual recovery rather than guessing.
        logger.warning("inverse-Martingale claim cannot be reconciled for %s", ticker)
        return None
    matched_order: Optional[Dict[str, Any]] = None
    # Whether this run can prove it is looking in the SAME account the claim
    # submitted into. Only the release branch depends on it: a positive match is
    # always trustworthy (finding the order proves it exists), but an absence is
    # meaningless unless the account is confirmed.
    account_confirmed = True
    if dry_run:
        # A LIVE lease can never be resolved from a dry-run invocation: the
        # dry-run broker has no order history, so an absent order proves
        # nothing. Gating the lookup on the CURRENT run's mode alone used to
        # release the whole pre-fire balance as "unplaced" once the claim day
        # passed -- even though the live order existed -- and a later live run
        # could then buy that balance a second time (Codex review: "Reconcile
        # live leases even when the recovery run is dry-run"). A lease claimed
        # by a dry-run invocation, by contrast, never reached a broker at all,
        # so it needs no lookup and expires on the ordinary schedule below.
        if lease_was_live:
            logger.warning(
                "inverse-Martingale claim for %s originated live; preserving it during a dry run",
                ticker,
            )
            return None
    elif not lease_was_live:
        # settlement_live=False proves this claim never reached a broker, so no
        # order history anywhere can contain it and there is nothing to look up.
        # Requiring the lookup anyway froze such a lease forever behind an
        # adapter that cannot query client ids at all -- AlpacaBroker refuses
        # outright (Codex review: "Skip broker lookup for dry-run-origin
        # leases"). It simply expires on the ordinary claim-day rule below.
        pass
    else:
        checker = getattr(broker, "strategy_order_with_ref_id", None)
        if checker is None:
            logger.warning("inverse-Martingale claim cannot be reconciled for %s", ticker)
            return None
        # Broker history is scoped to ONE account. If this invocation is wired
        # to a different account than the claim was, the claimed order can never
        # appear in the results, so an empty answer says nothing about whether
        # it was submitted -- and releasing on that silence frees a balance
        # whose real order is sitting in the original account. Only a lease that
        # recorded no account identity at all (a pre-existing lease, or an
        # adapter that exposes none) is exempt, since there is nothing to
        # contradict.
        #
        # Scoped to LIVE leases. A dry-run claim never reached a broker at all
        # -- settlement_live proves it -- so no account anywhere holds an order
        # for it and account identity is irrelevant. Comparing anyway froze such
        # a lease forever the moment the account value changed, which is exactly
        # what happens when a dry run fingerprints the unset placeholder and a
        # later live run supplies the real environment value (Codex review: "Let
        # live runs release leases created by dry runs").
        # A live lease whose account cannot be CONFIRMED to match this run's is
        # not reconcilable AT ALL -- neither a positive match nor an absence
        # means anything. An earlier version withheld only the release branch,
        # on the reasoning that finding the order proves it exists. That was
        # wrong: the claim ref is built from stream + trading day + ticker and
        # carries NO account, so two accounts running this strategy mint the
        # identical ref. A match in the wrong account is then some other
        # account's order, and settling on it would clear the original lease and
        # book a fill that never happened here (Codex review: "Refuse positive
        # matches from a different broker account"). Covers a genuine mismatch,
        # an identity this run cannot compute, and the "unknown" sentinel a live
        # claim records when it could not compute one either.
        claim_account = tracker_state.get("settlement_account") if lease_was_live else None
        if claim_account is None:
            account_confirmed = True  # dry-run lease, or a legacy one: nothing to contradict
        elif claim_account == _LEASE_ACCOUNT_UNKNOWN:
            account_confirmed = False
        else:
            account_confirmed = claim_account == _broker_account_fingerprint(
                broker, ledger.root.parent
            )
        if not account_confirmed:
            logger.warning(
                "inverse-Martingale claim for %s cannot be matched to the account it was made "
                "against; preserving the lease without reconciling it",
                ticker,
            )
            return None
        try:
            candidate = checker(ticker, claim_trading_day, claim_ref)
            matched_order = candidate if isinstance(candidate, dict) and candidate else None
        except Exception as exc:  # noqa: BLE001 - preserve the lease fail-closed
            logger.warning("inverse-Martingale claim reconciliation failed for %s: %s", ticker, exc)
            return None
    recovered_amount = _recovered_broker_notional(matched_order) if matched_order else 0.0
    # Captured from the SAME history lookup that established the notional
    # above, independently of whether a later, separate get_order_fill() call
    # succeeds. The execution-record logger for a recovered fire used to rely
    # solely on that second call and fell back to no price/quantity at all
    # when it returned None (order_fill_fn unwired, or a transient follow-up
    # failure) -- undercounting filled_order_count/total_filled_notional for
    # a fill history had already established (Codex review: "Preserve known
    # fill details during recovery logging"). Best-effort and independent of
    # recovered_amount's own valuation path (executed_notional vs
    # quantity*price): a filled order with a positive, parseable
    # quantity/price is a fill worth reporting even if the two disagree
    # slightly with the notional used for booking.
    recovered_fill_price: Optional[float] = None
    recovered_fill_quantity: Optional[float] = None
    if matched_order is not None:
        _price = _finite_nonnegative_float(matched_order.get("average_price"))
        # The plain "quantity" fallback is scoped to state == "filled", exactly
        # like _recovered_broker_notional's own quantity_field selection just
        # below: on a CANCELLED/REJECTED/EXPIRED order "quantity" is what was
        # REQUESTED, not what executed. Falling back to it unconditionally
        # combined a terminal zero-fill's requested share count with
        # average_price into a fabricated fill, marking a $0 recovery
        # (correctly booked by _recovered_broker_notional) as "filled" with
        # the entire requested notional in the execution record (Codex
        # review: "Avoid treating requested quantity as a recovered fill").
        _order_state = str(matched_order.get("state", "")).strip().lower()
        if not _is_blank_broker_field(matched_order.get("cumulative_quantity")):
            _qty_field = "cumulative_quantity"
        elif _order_state == "filled":
            _qty_field = "quantity"
        else:
            _qty_field = None
        _qty = _finite_nonnegative_float(matched_order.get(_qty_field)) if _qty_field else None
        if _price is not None and _price > 0 and _qty is not None and _qty > 0:
            recovered_fill_price = _price
            recovered_fill_quantity = _qty
    if matched_order is not None and recovered_amount is None:
        # The order exists but has no FINAL executed amount yet -- it is still
        # working, or its execution fields are unusable. Either way this
        # reconciliation is indeterminate, and an indeterminate answer must
        # never release or rewrite a claim on real money.
        logger.warning(
            "inverse-Martingale claim for %s matched a non-terminal or unreadable order; preserving the lease",
            ticker,
        )
        return None
    if matched_order is not None and recovered_amount is not None and recovered_amount > 0:
        if abs(recovered_amount - claimed_amount) < 0.005:
            # The claimed fire landed in full: the target state the claim
            # reserved is exactly right, minus its own lease flag.
            recovered_state = {k: v for k, v in target.items() if k != "settlement_pending"}
            if recovered_state.get("status") == STATUS_FIRING:
                # target is itself a STATUS_FIRING continuation (a capped
                # fire, exactly matched by this settlement) computed by
                # evaluate_inverse_martingale_step() AT CLAIM TIME -- its
                # trading_days_active is correct as of the claim day, but
                # broker reconciliation can be delayed for many sessions
                # (the same outage window the other resolving branches
                # already fold in), and target does not stamp last_
                # evaluated_trading_day to today either, so the next real
                # evaluation's own +1 would otherwise be the only credit for
                # however long that outage lasted -- letting a remainder
                # already close to max_cycle_days resume and place another
                # stale chunk (Codex review: "Age a fully reconciled capped
                # continuation").
                recovered_state["trading_days_active"] = int(
                    target.get("trading_days_active", 0)
                ) + _lease_outage_trading_days(claim_trading_day, trading_day)
        else:
            # A partial landed (most likely a kill-switch-capped order). Rebuild
            # a STATUS_FIRING continuation for the remainder with the SAME retry
            # bookkeeping ordinary deferred partial settlement stamps -- without
            # last_evaluated_trading_day/last_evaluated_stream/fire_attempts,
            # the evaluation that runs right after this would not recognize a
            # retry of the same scheduled stream and could synthesize a SECOND
            # fire in this very invocation, reusing the same deterministic ref
            # id (Codex review: "Preserve retry metadata when recovering a
            # partial order").
            remainder = round(
                float(tracker_state.get("accumulated_usd", 0.0)) - recovered_amount, 2
            )
            if remainder <= 0:
                # The partial exhausted the balance. Writing STATUS_FIRING with
                # accumulated_usd=0 here would be self-inflicted corruption: the
                # validator rejects an active cycle with a nonpositive balance,
                # so the very next read would raise and skip this ticker
                # permanently. Reachable with the supported sub-dollar config,
                # where a $0.30 balance is claimed at the $1 broker minimum and
                # a $0.50 terminal partial differs from the claim while
                # exhausting the real balance. Mirror ordinary deferred
                # settlement and write a resolved marker instead (Codex review:
                # "Resolve partial fills that exhaust the accumulator").
                recovered_state = resolved_marker(
                    trading_day,
                    stream,
                    fired_floor_drop_metric=tracker_state.get("lowest_drop_seen"),
                    # The floor PRICE as well as the metric, exactly like every
                    # ordinary fire-resolution path. With only the metric, the
                    # same-day re-arm guard falls back to comparing it in
                    # whatever reference frame the later stream happens to have
                    # -- so once the durable rearm latch clears, a price still
                    # above the already-paid floor can read as a fresh deeper
                    # descent and re-credit tiers that were already bought
                    # (Codex review: "Preserve the paid floor price on
                    # recovered resolution"). Computed with the ledger's own
                    # inversion rather than a local reimplementation: the two
                    # must agree exactly, and a private-name import is a
                    # smaller risk than a second copy of the basis math
                    # drifting from it.
                    fired_floor_price=_drop_metric_to_price(
                        float(tracker_state.get("cycle_reference_close") or 0.0),
                        float(tracker_state.get("lowest_drop_seen") or 0.0),
                        str(tracker_state.get("basis") or BASIS_PCT),
                        tracker_state.get("stddev_reference"),
                    ),
                    rearm_reference_close=tracker_state.get("cycle_reference_close"),
                    # Carry forward the claim's own rearm_last_seen_day rather
                    # than leaving it unset. Without it, the next evaluation's
                    # split-rebase lookup (near_close_dca's isinstance(...,
                    # str) gate on rearm_last_seen_day) never runs, so a real
                    # corporate action between this claim and next-day
                    # recovery can never be detected: the reference stays
                    # pinned at its pre-split value while decision_price is
                    # already post-split, and the latch can stay armed far
                    # longer than the genuine recovery it is meant to detect
                    # (Codex review: "Preserve the pre-split close in
                    # recovered resolution"). ``target`` already carries the
                    # correct value -- it was computed by this same
                    # resolved_marker()/evaluate_inverse_martingale_step()
                    # machinery at claim time from this exact tracker_state.
                    rearm_last_seen_day=target.get("rearm_last_seen_day"),
                )
            else:
                recovered_state = {
                    k: v
                    for k, v in tracker_state.items()
                    if k != "settlement_pending" and not k.startswith("settlement_")
                }
                recovered_state["status"] = STATUS_FIRING
                recovered_state["accumulated_usd"] = remainder
                recovered_state["fire_attempts"] = (
                    1
                    if tracker_state.get("status") != STATUS_FIRING
                    else int(tracker_state.get("fire_attempts", 0)) + 1
                )
                recovered_state["last_evaluated_trading_day"] = trading_day.isoformat()
                recovered_state["last_evaluated_stream"] = stream
                recovered_state["last_evaluated_is_real"] = True
                # See _lease_outage_trading_days's own docstring: stamping
                # last_evaluated_trading_day to today above means the ordinary
                # per-ticker evaluation loop's own +1 age advance will NOT run
                # for this ticker today (its date already matches), so this
                # recovery step must fold the outage in itself.
                recovered_state["trading_days_active"] = int(
                    tracker_state.get("trading_days_active", 0)
                ) + _lease_outage_trading_days(claim_trading_day, trading_day)
        recovered_reason = "fire_reconciled_from_broker_ref"
    elif matched_order is not None:
        # A REAL order was submitted and came back terminal with nothing filled.
        # That is a failed placement, not an abandoned reservation, and treating
        # the two identically let the balance be submitted again with no attempt
        # recorded -- so a repeating crash-then-terminal-failure cycle never
        # reached max_fire_attempts (Codex review: "Count reconciled zero-fill
        # orders as fire attempts"). Shaped exactly like deferred settlement's
        # own failed-placement rollback: the full balance survives as a
        # STATUS_FIRING continuation with the attempt counted and this stream
        # stamped, so the retry guard also stops a second attempt inside this
        # same run.
        #
        # Resolved on ANY day, including the claiming one. The next-day wait
        # below exists because an ABSENT order might still be in flight -- but a
        # matched terminal row proves submission happened and can never fill, so
        # making a morning/midday crash wait until tomorrow only blocked later
        # same-day streams from retrying the retained balance and deferred the
        # attempt bookkeeping for no gain (Codex review: "Resolve matched
        # terminal zero-fill orders on the claim day").
        recovered_state = {
            k: v for k, v in tracker_state.items() if not k.startswith("settlement_")
        }
        recovered_amount = 0.0
        recovered_state["status"] = STATUS_FIRING
        recovered_state["fire_attempts"] = (
            1
            if tracker_state.get("status") != STATUS_FIRING
            else int(tracker_state.get("fire_attempts", 0)) + 1
        )
        recovered_state["last_evaluated_trading_day"] = trading_day.isoformat()
        recovered_state["last_evaluated_stream"] = stream
        recovered_state["last_evaluated_is_real"] = True
        # See _lease_outage_trading_days's own docstring: last_evaluated_
        # trading_day is stamped to today above, so no later real evaluation
        # this run will supply its own +1 age advance for this ticker.
        recovered_state["trading_days_active"] = int(
            tracker_state.get("trading_days_active", 0)
        ) + _lease_outage_trading_days(claim_trading_day, trading_day)
        recovered_reason = "fire_reconciled_terminal_zero_fill"
    elif claim_trading_day < trading_day:
        # NO order exists under this ref and the claiming day has ended, so no
        # same-day market order from it can still land: the pre-fire balance is
        # safely claimable again. Reaching here at all means the account was
        # confirmed above -- otherwise the silence could just mean we looked
        # somewhere the order never was.
        recovered_state = {
            k: v for k, v in tracker_state.items() if not k.startswith("settlement_")
        }
        recovered_amount = 0.0
        # Unlike the two branches above, this one does NOT stamp
        # last_evaluated_trading_day to today -- it leaves the pre-claim
        # value untouched, so the ordinary per-ticker evaluation loop may
        # still supply its own natural +1 age advance later. Folding the
        # outage in here anyway, on top of that eventual +1, is a harmless
        # over-count of at most one session -- cheap next to the alternative
        # of leaving a genuinely stale cycle able to resume and fire (Codex
        # review: "Account for lease outage days before restoring the
        # cycle").
        recovered_state["trading_days_active"] = int(
            tracker_state.get("trading_days_active", 0)
        ) + _lease_outage_trading_days(claim_trading_day, trading_day)
        recovered_reason = "expired_unplaced_fire_lease_released"
    else:
        return None  # still the claiming day -- the owning worker may yet submit
    order_id = None
    if matched_order is not None:
        # Fall back to the deterministic claim ref: it is the identifier this
        # order was submitted under, and an outcome row with no id at all is
        # not counted as a placed order by build_usage_proxy.
        order_id = _first_usable_order_id_alias(matched_order) or claim_ref
    last_recovery = None
    if recovered_amount is not None and recovered_amount > 0:
        # A durable attribution record. Written to TWO places, not one:
        #
        # 1. The TRACKER's own top-level state (below), so the most recent
        #    recovery is visible on a plain read without scanning history --
        #    but this is overwritten wholesale by resolved_marker() the next
        #    time this cycle fires, is abandoned, or is reset, since that
        #    function carries no such field forward (Codex review: "Persist
        #    recovery attribution in the audit event").
        # 2. recovery_step.recovery_metadata below, which
        #    InverseMartingaleLedger._write_locked() folds into this
        #    transition's own APPEND-ONLY event-log entry -- surviving every
        #    later transition, unlike the top-level copy.
        #
        # Both exist because InverseMartingaleLedger._write_locked() itself
        # serializes only statuses, amounts, crossed tiers, fired, and reason
        # for every event by default, with no date, stream, order id, or
        # claim ref at all -- so a caller that skips publishing this recovery
        # into a run artifact (a cross-day or cross-stream claim; see the
        # publication loop in _run_once_impl) had NO durable way to attribute
        # the purchase back to its original claim (Codex review: "Persist
        # claim metadata before suppressing cross-stream recovery rows").
        # This is especially lossy for a partial reconciliation, which
        # already strips every settlement_* field and stamps the recovered
        # state with the RECONCILING run's own day/stream, not the claim's.
        last_recovery = {
            "claim_trading_day": claim_trading_day.isoformat(),
            "claim_stream": tracker_state.get("settlement_stream"),
            "claim_ref": claim_ref,
            "order_id": str(order_id) if order_id else None,
            "recovered_amount_usd": recovered_amount,
            "reconciled_trading_day": trading_day.isoformat(),
            "reconciled_stream": stream,
        }
        # A plain dict under a new key, not one of the validated
        # settlement_*/rearm_* fields, so it survives _validate_tracker_
        # payload without any schema change and is overwritten wholesale by
        # the next recovery rather than accumulating.
        recovered_state = dict(recovered_state)
        recovered_state["last_recovery"] = last_recovery
    recovery_step = InverseMartingaleStep(
        status_before=str(tracker_state.get("status", STATUS_NONE)),
        status_after=str(recovered_state.get("status", STATUS_NONE)),
        accumulated_usd_before=float(tracker_state.get("accumulated_usd", 0.0)),
        accumulated_usd_after=float(recovered_state.get("accumulated_usd", 0.0)),
        newly_crossed_tiers=(),
        fired=recovered_amount is not None and recovered_amount > 0,
        fire_amount_usd=recovered_amount or 0.0,
        reason=recovered_reason,
        recovery_metadata=last_recovery,
    )
    if not ledger.claim_fire(
        ticker,
        expected_prior_state=tracker_state,
        new_state=recovered_state,
        step=recovery_step,
    ):
        # A concurrent process resolved this lease first; its write wins.
        return None
    return InverseMartingaleLeaseRecovery(
        ticker=ticker,
        claim_trading_day=claim_trading_day,
        recovered_amount_usd=recovered_amount or 0.0,
        recovered_state=recovered_state,
        order_id=str(order_id) if order_id else None,
        claim_ref=claim_ref,
        claim_stream=(
            claim_stream if isinstance(claim_stream := tracker_state.get("settlement_stream"), str) else None
        ),
        fill_price=recovered_fill_price,
        fill_quantity=recovered_fill_quantity,
    )


def _inverse_martingale_recover_pending_leases(
    ledger: InverseMartingaleLedger,
    *,
    broker: "BrokerAdapter",
    dry_run: bool,
    trading_day: date,
    stream: str,
) -> Dict[str, InverseMartingaleLeaseRecovery]:
    """Reconcile every ``settlement_pending`` lease in the on-disk ledger tree.

    Scoped to the LEDGER, not to ``tradable_tickers`` or to
    ``config.inverse_martingale``, and run BEFORE any enrollment/market-data
    gate. A crashed lease is a claim on real money that only broker-ref
    reconciliation can settle -- it needs no current price and no active
    enrollment. Reaching it only through the per-ticker evaluation loop meant
    an operator who disabled inverse-Martingale after the crash (the cleanup
    helper deliberately leaves ``settlement_pending`` untouched, and the
    evaluation loop skips unenrolled tickers), or a ticker whose price data
    simply went missing (the age helper also refuses pending leases), locked
    the claimed balance indefinitely with no path back (Codex review:
    "Reconcile leases before enrollment and market-data gates").
    """
    recoveries: Dict[str, InverseMartingaleLeaseRecovery] = {}
    if not ledger.root.is_dir():
        return recoveries
    for ticker_dir in sorted(ledger.root.iterdir()):
        if not ticker_dir.is_dir():
            continue
        ticker = ticker_dir.name
        try:
            tracker_state = ledger.read(ticker)
        except CorruptedLedgerStateError as exc:
            # Same "skip only this ticker, leave the file for manual recovery"
            # contract every other ledger read site here follows.
            logger.error("inverse-Martingale ledger unreadable for %s: %s", ticker, exc)
            continue
        if not tracker_state or not tracker_state.get("settlement_pending"):
            continue
        recovery = _inverse_martingale_recover_pending_lease(
            ledger,
            ticker,
            tracker_state,
            broker=broker,
            dry_run=dry_run,
            trading_day=trading_day,
            stream=stream,
        )
        if recovery is not None:
            recoveries[ticker] = recovery
    return recoveries


def _afternoon_decision_price(decision: ReconciledDecision) -> Optional[float]:
    """Return the current afternoon decision price used to compare against a prior run.

    Prefer the reconciled execution target (the signal-time quote), falling back to the
    decision-bar close derived from the source signals. Returns None when neither is
    available so the top-up guard can behave conservatively rather than guess.
    """
    if decision.target_price and decision.target_price > 0:
        return decision.target_price
    return _signal_target_price(decision)


def resolve_top_up_desired_amount_usd(
    prior: Optional[PriorSameDayAllocation],
    current_multiplier: float,
    current_suggested_amount_usd: float,
    current_base_amount_usd: float,
) -> tuple[float, float]:
    """Return the same-day full-day target used by a top-up guard, base-preserved.

    The first same-day allocation for a ticker fixes that day's first-allocation
    base scale ($1 or $2, see select_first_allocation_base_usd); a later same-day
    top-up must keep using THAT base and only re-apply its own run's ladder
    multiplier (which legitimately varies with price), never recompute the base
    from its own price. Otherwise a later, lower price that newly crosses the
    prior regular-session low would silently upgrade the whole day's target from
    the $1 to the $2 scale and over-order the incremental difference.

    Falls back to ``current_suggested_amount_usd``/``current_base_amount_usd``
    (the pre-existing behavior) when there is no prior allocation. When a prior
    allocation exists but predates this field / could not be resolved, this
    still returns that same fallback -- never treat an unknown preserved base
    as $0 here -- but callers with a known prior amount (``prior.amount_usd >
    0``) must not trust this fallback value directly: they fail closed
    (manual review, $0) instead of using it, since silently recomputing the
    base from the current run's own price is exactly the bug this function
    exists to prevent (Codex review: "Fail closed when the first allocation
    base is unknown"; see evaluate_top_up_guard's own check).

    Returns ``(desired_amount_usd, effective_base_amount_usd)`` -- the latter is
    whichever base actually produced ``desired_amount_usd``, so a caller
    building a candidate-row artifact can persist the base that was ACTUALLY
    used (Codex review: "Persist the preserved base on top-up candidates")
    instead of always the current run's own freshly recomputed base.
    """
    if (
        prior is not None
        and prior.selected_base_amount_usd
        and prior.selected_base_amount_usd > 0
    ):
        return (
            round(prior.selected_base_amount_usd * current_multiplier, 2),
            prior.selected_base_amount_usd,
        )
    return round(current_suggested_amount_usd, 2), current_base_amount_usd


def cumulative_price_step_amount_usd(
    prior_reference_price: float, current_price: float, config: StrategyConfig
) -> float:
    """Return a cent-precise cumulative same-day top-up, floored at $1."""
    decline = prior_reference_price - current_price
    if decline < config.cumulative_top_up_min_drop_usd:
        return 0.0
    return round(max(config.cumulative_top_up_min_order_usd, decline), 2)


def evaluate_top_up_guard(
    decision: ReconciledDecision,
    prior: Optional[PriorSameDayAllocation],
    config: StrategyConfig,
    *,
    existing_pending_credit_usd: float = 0.0,
) -> TopUpGuardOutcome:
    """Compute the same-day prior-run offset/top-up for one afternoon buy candidate.

    A morning/manual run must never block the scheduled afternoon run; instead the
    afternoon run only tops up, and only when it is buying into a lower price:

      * No earlier same-day allocation for the ticker -> normal allocation (buy the
        full afternoon desired amount).
      * Earlier allocation exists and the afternoon decision price is *below* the
        earlier run's reference price -> buy only the incremental dollar difference
        (afternoon desired minus the amount already bought), and $0 (reason
        ``TOP_UP_NOT_LOWER_OR_NO_DELTA``, canonical rule item 12) if that is <= 0.
      * Earlier allocation exists but the afternoon price is not below the reference
        price -> buy $0 (reason ``TOP_UP_NOT_LOWER_OR_NO_DELTA``).
      * Earlier amount is known but its reference price (or the current afternoon
        price) is missing -> conservative $0 with ``manual_review`` flagged, rather
        than topping up blind.

    The full-day target (``desired``) reuses the first allocation's selected base
    when known (see :func:`resolve_top_up_desired_amount_usd`) so a later, lower
    price cannot silently upgrade the whole day's target to the $2 scale.

    KNOWN GAP (config/scheduled_tasks.json canonical_first_buy_and_topup_rule ->
    effective_prior_usd_gap_2026_07_24, module docstring's JUL 23 2026 EFFECTIVE
    PRIOR ALLOCATION PATCH note): ``prior.amount_usd`` is the artifact-derived
    prior allocation only. This does not yet compute the canonical rule's
    ``effective_prior_usd`` (deduped same-day artifacts PLUS Robinhood same-day
    broker order history) or read ``prior_usd_rh``, so a same-day buy confirmed
    at the broker but missing/incomplete in the artifact trail is not yet folded
    into ``corrected_delta_usd`` here.

    ``existing_pending_credit_usd`` is a same-day sub-dollar credit balance
    the caller already durably persisted (via
    ``CumulativeCreditLedger.pending_usd``) from an earlier session's decline
    that never itself cleared the broker's $1 minimum. Passed in as plain
    data -- this function stays a pure computation, performing no ledger I/O
    itself (see ``_process_buy_candidate``, the only caller that reads it).
    Defaults to 0.0 for the pure planned-spend tier-selection estimate (Codex
    review: "Accumulate credits instead of resetting pending state" -- the
    final 3:30 PM session's own contract is to close ANY positive pending
    balance, even when THIS call's own decision price shows no further
    decline).
    """
    desired, effective_base = resolve_top_up_desired_amount_usd(
        prior,
        decision.buy_multiplier,
        decision.suggested_amount_usd,
        decision.selected_base_amount_usd,
    )
    afternoon_price = _afternoon_decision_price(decision)

    def _outcome(
        incremental: float,
        result: str,
        *,
        skipped: bool,
        manual_review: bool = False,
        cumulative_credit_decline_usd: Optional[float] = None,
        discarded_pending_credit_usd: Optional[float] = None,
    ) -> TopUpGuardOutcome:
        return build_top_up_outcome(
            outcome_cls=TopUpGuardOutcome,
            ticker=decision.ticker,
            desired_amount=desired,
            decision_price=afternoon_price,
            prior=prior,
            incremental=incremental,
            result=result,
            skipped=skipped,
            effective_base=effective_base,
            manual_review=manual_review,
            cumulative_credit_decline_usd=cumulative_credit_decline_usd,
            discarded_pending_credit_usd=discarded_pending_credit_usd,
        )

    def _flush_or_discard_existing_credit(
        fallback_incremental: float, fallback_result: str
    ) -> Optional[TopUpGuardOutcome]:
        """Shared final-session resolution for ``existing_pending_credit_usd``
        at a point where THIS call's own decision contributes no further
        incremental amount (no prior context, a recovered/flat price, or a
        ladder target the prior allocation already exceeds).

        Returns an outcome (order or discard) when there is a positive
        existing balance to resolve, or ``None`` when the caller should fall
        through to its own default ``fallback_incremental``/
        ``fallback_result`` outcome untouched (``existing_pending_credit_usd``
        is zero, so there is nothing here for the final session to resolve
        either way).

        Every zero-order return path in this function must end here rather
        than a bare ``_outcome(...)`` once ``existing_pending_credit_usd`` is
        positive: leaving it neither ordered nor marked
        ``discarded_pending_credit_usd`` strands it in the ledger forever,
        since this is always the final same-day session and
        evaluate_top_up_guard performs no ledger I/O of its own (Codex
        review discussion on commit 55e175d: "Recheck survivor balances
        that shrink below the threshold" and "Flush qualifying credits
        despite a negative ladder delta" -- a concurrent settlement can
        shrink a deferred balance below $0.50 by the time this call reads
        it fresh, and a prior/manual allocation already at or above today's
        ladder target skipped straight past every other flush check
        without ever looking at the remainder).
        """
        if existing_pending_credit_usd <= 0:
            return None
        flushed = apply_cumulative_credit(
            existing_pending_credit_usd, 0.0, final_session=True
        ).order_amount_usd
        if flushed > 0:
            return _outcome(
                flushed,
                TOP_UP_INCREMENTAL,
                skipped=False,
                cumulative_credit_decline_usd=0.0,
            )
        return _outcome(
            fallback_incremental,
            fallback_result,
            skipped=True,
            discarded_pending_credit_usd=existing_pending_credit_usd,
        )

    # A malformed order-bearing fallback proves same-day activity but not its
    # dollars. Never reinterpret its zero placeholder as "no prior run".
    if prior is not None and prior.notional_uncertain:
        return _outcome(
            0.0, TOP_UP_MISSING_PRIOR_BASE, skipped=True, manual_review=True
        )
    # No earlier same-day allocation: behave exactly like a normal scheduled run.
    if prior is None or prior.amount_usd <= 0:
        # A ticker whose only earlier same-day activity was a sub-dollar
        # decline that never itself crossed the broker's $1 minimum has NO
        # prior_same_day_allocations entry at all (that dict tracks actual
        # ORDERS, not pending credits) -- prior is None here for exactly
        # that ticker, same as for a ticker with no same-day activity
        # whatsoever. When this run's own decision is not BUY (desired <=
        # 0), falling straight through to the plain "no prior" outcome
        # below silently strands that pending credit forever: there is no
        # prior.reference_price to gate a top-up against, so the flush
        # branch further down (guarded by afternoon_price >=
        # prior.reference_price) is never reached either (Codex review:
        # "Flush pending credits even without prior context"). The final
        # session's own contract is to close ANY positive pending balance
        # regardless of today's decision price, so flush it here using the
        # same final-session rounding as that later branch.
        if desired <= 0:
            flush_outcome = _flush_or_discard_existing_credit(desired, TOP_UP_NO_PRIOR_RUN)
            if flush_outcome is not None:
                return flush_outcome
        return _outcome(desired, TOP_UP_NO_PRIOR_RUN, skipped=desired <= 0)

    # Prior amount is known but its first-allocation base ($1 or $2) could not
    # be resolved (legacy artifact predating the field, or an unresolved bare
    # manual CSV entry) -- resolve_top_up_desired_amount_usd's fallback above
    # silently recomputed `desired` from THIS run's own freshly selected base,
    # which is exactly the base-upgrade/downgrade bug the preserved-base rule
    # exists to prevent. Fail closed like a missing reference price instead of
    # trusting that silently-recomputed target (Codex review: "Fail closed
    # when the first allocation base is unknown").
    if prior.selected_base_amount_usd is None or prior.selected_base_amount_usd <= 0:
        return _outcome(
            0.0, TOP_UP_MISSING_PRIOR_BASE, skipped=True, manual_review=True
        )

    # Prior amount is known but we cannot establish a comparable price on either side.
    # Prefer the conservative no-top-up path and flag the ticker for manual review.
    if prior.reference_price is None or afternoon_price is None:
        return _outcome(
            0.0, TOP_UP_MISSING_PRIOR_PRICE, skipped=True, manual_review=True
        )

    # Only top up when buying into a lower price than the earlier same-day run.
    # Canonical rule item 12: not-strictly-lower and zero-delta both use the
    # single unified TOP_UP_NOT_LOWER_OR_NO_DELTA code. A recovered price
    # still owes the final session's own flush of any pre-existing pending
    # credit, though -- that balance was earned by an earlier decline this
    # run's own (recovered) price no longer reflects, so it must not be
    # silently stranded just because THIS call finds no further decline
    # (Codex review: "Accumulate credits instead of resetting pending state").
    if afternoon_price >= prior.reference_price:
        flush_outcome = _flush_or_discard_existing_credit(0.0, TOP_UP_NOT_LOWER_OR_NO_DELTA)
        if flush_outcome is not None:
            return flush_outcome
        return _outcome(0.0, TOP_UP_NOT_LOWER_OR_NO_DELTA, skipped=True)

    price_step_incremental = cumulative_price_step_amount_usd(
        prior.reference_price, afternoon_price, config
    )
    ladder_incremental = desired - round(prior.amount_usd, 2)
    # If prior already exceeds the computed desired amount, don't buy more even
    # with a further price decline — that would overshoot the day's target.
    # existing_pending_credit_usd is unrelated money owed from an earlier
    # broker-minimum block, though, not more of THIS ticker's own ladder
    # target -- a qualifying (>= $0.50) remainder must still be flushed here
    # even though the ladder itself has nothing further to contribute (Codex
    # review discussion on commit 55e175d: "Flush qualifying credits despite
    # a negative ladder delta").
    if ladder_incremental < 0:
        flush_outcome = _flush_or_discard_existing_credit(0.0, TOP_UP_NOT_LOWER_OR_NO_DELTA)
        if flush_outcome is not None:
            return flush_outcome
        return _outcome(0.0, TOP_UP_NOT_LOWER_OR_NO_DELTA, skipped=True)
    # For sub-dollar ladder increments (< $1), the ladder and price-step
    # floors above can both land at zero even though the price is genuinely
    # lower (e.g. a $0.30 decline is below cumulative_top_up_min_drop_usd).
    # near_close_dca is always the scheduled 3:30 PM final session, which
    # dca_cumulative documents as closing any positive same-day credit by
    # rounding it up to a whole-dollar order rather than dropping it (Codex
    # review: "wire CumulativeCreditLedger into a real execution path" --
    # dca_cumulative.apply_cumulative_credit/CumulativeCreditLedger were
    # previously exercised only by their own unit tests). This computation is
    # deliberately PURE (no ledger I/O): the caller (_process_buy_candidate)
    # only durably settles the ledger once this candidate's order is actually
    # confirmed submitted, using cumulative_credit_decline_usd below (Codex
    # review: "Defer ledger updates until the submitted amount is known" --
    # writing here, before cap/spread/buying-power/placement checks run,
    # could flush and clear a credit for an order that ends up blocked,
    # clamped, or never placed at all).
    cumulative_credit_decline_usd: Optional[float] = None
    discarded_pending_credit_usd: Optional[float] = None
    if ladder_incremental < 1.0:
        # The final-session credit decision must consider the LADDER
        # increment itself, not just the rounded raw price decline: a
        # preserved $1 base advancing from 1x to 1.5x makes ladder_incremental
        # $0.50 even when the price moved by only a few tenths of a cent
        # (decline_usd rounds to $0.00). Feeding decline_usd alone into
        # apply_cumulative_credit would then skip it entirely and fall back to
        # returning that raw $0.50 ladder amount as the order -- below the
        # broker's $1 minimum every positive order here must meet (Codex
        # review: "Route the ladder increment through the final-session
        # minimum").
        decline_usd = round(max(0.0, prior.reference_price - afternoon_price), 2)
        credit_amount_usd = round(max(ladder_incremental, price_step_incremental, decline_usd), 2)
        cumulative_credit = (
            apply_cumulative_credit(
                existing_pending_credit_usd, credit_amount_usd, final_session=True
            ).order_amount_usd
            if credit_amount_usd > 0 or existing_pending_credit_usd > 0
            else 0.0
        )
        if cumulative_credit > 0:
            cumulative_credit_decline_usd = credit_amount_usd
        elif existing_pending_credit_usd > 0:
            # Even combined with this call's own qualifying decline, the
            # total stayed below the final-session discard threshold --
            # apply_cumulative_credit's own final_session semantics already
            # decided this money is forgotten for the day. Only this ladder
            # branch (never the two flush-only branches above, which have no
            # new decline to combine at all) can reach this state, and only
            # for a ticker _final_session_credit_could_combine_with_this_
            # runs_decline judged worth deferring in the first place -- so
            # this is exactly, and only, the gap that deferral could open
            # (Codex review discussion on commit 0af4768: "Clear combined
            # credits that remain below fifty cents").
            discarded_pending_credit_usd = existing_pending_credit_usd
        incremental = cumulative_credit
    else:
        incremental = ladder_incremental
        if existing_pending_credit_usd > 0:
            # This candidate already qualifies for an ordinary >= $1 ladder
            # order on its own, independent of any pending broker-minimum
            # remainder. Without this, existing_pending_credit_usd is simply
            # never looked at in this branch, so a ticker that also happens
            # to carry a pending remainder gets its ladder order placed while
            # the remainder is left completely untouched -- neither combined
            # into this order nor flushed/discarded, silently stranded for
            # the rest of the day (Codex review discussion on commit
            # 58a536a: "Resolve pending credit on existing buy candidates" --
            # e.g. a $0.75 minimum-order remainder alongside a $2 ladder
            # increment). Fold it into this order: since a real order is
            # happening for this ticker anyway this final session, there is
            # no reason to leave the remainder for a later evaluation that
            # will never come. cumulative_credit_decline_usd=0.0 (not the
            # folded amount) matches the flush-only branches above -- it
            # marks "this call settles existing_pending_credit_usd from the
            # ledger" without misrepresenting it as a fresh decline that was
            # needed to justify the order.
            #
            # But the manifest's own $0.50 discard threshold still applies
            # to the remainder ITSELF first: "less than $0.50, forget it for
            # that trading day" is unconditional, not just for a standalone
            # remainder-only order. Folding every remainder into whatever
            # ladder order happens to be running this session -- regardless
            # of size -- would fold in amounts the policy explicitly says to
            # forget (Codex review discussion on commit e385a54: "Discard
            # sub-threshold credit before folding ladder orders"). Apply the
            # same final-session threshold to the remainder ALONE before
            # deciding whether to fold it in at all.
            if apply_cumulative_credit(
                existing_pending_credit_usd, 0.0, final_session=True
            ).order_amount_usd > 0:
                incremental = round(incremental + existing_pending_credit_usd, 2)
                cumulative_credit_decline_usd = 0.0
            else:
                discarded_pending_credit_usd = existing_pending_credit_usd
    if incremental <= 0:
        return _outcome(
            0.0,
            TOP_UP_NOT_LOWER_OR_NO_DELTA,
            skipped=True,
            discarded_pending_credit_usd=discarded_pending_credit_usd,
        )
    return _outcome(
        incremental,
        TOP_UP_INCREMENTAL,
        skipped=False,
        cumulative_credit_decline_usd=cumulative_credit_decline_usd,
        discarded_pending_credit_usd=discarded_pending_credit_usd,
    )


# The SourceSignal fields _signal_row passes to _iso_or_none, which calls
# .isoformat() on anything that is not None. Kept beside the validator that
# guards them, and cross-checked against _signal_row's own source by
# test_serializable_signal_guards_every_field_the_writer_dereferences.
_SIGNAL_ROW_TIMESTAMP_FIELDS = (
    "decision_bar_timestamp",
    "previous_close_timestamp",
    "lookback_bar_timestamp",
    # Found by that cross-check, not by reading: the first hand-written
    # version of this tuple listed the three *_timestamp names and missed
    # quote_time, which _signal_row passes through the same helper.
    "quote_time",
)


def _serializable_signal(signal: object) -> Optional["SourceSignal"]:
    """``signal`` if the artifact writers can safely serialize it, else None.

    Guards EVERY field ``_signal_row`` dereferences without checking, so a
    structurally valid ``SourceSignal`` carrying a malformed one is dropped
    rather than carried onto a decision that later takes the whole run down
    while artifacts are being written.

    That is two kinds of field: ``action``, read as ``signal.action.value``,
    and the timestamp fields, each passed to ``_iso_or_none`` which calls
    ``.isoformat()`` on anything not None. The first version of this helper
    checked only ``action`` -- deliberately, and too narrowly: a signal with a
    good action and ``decision_bar_timestamp="bad"`` passed it and then raised
    ``'str' object has no attribute 'isoformat'`` from the artifact writer,
    which is the same crash one layer along (Codex review, PR #786: "Validate
    every signal field used by artifact serialization").

    Those per-field checks are not the whole guard, and an earlier version of
    this docstring claimed they were: "every other field is written through
    unexamined, so a wrong-typed float reaches the CSV as-is rather than
    raising". True of the CSV, which ``str()``s every cell and cannot raise --
    and false of run_state.json, which goes through ``json.dumps``. A signal
    carrying ``reason=object()`` passed every check above and then took the
    run down with ``TypeError: Object of type object is not JSON
    serializable`` from the artifact writer -- the same crash one layer along
    again (Codex review, PR #786: "Validate JSON serializability of retained
    signals"). So the row is built and round-tripped through ``json.dumps``
    here, which is the writer's own test rather than a restatement of it: a
    field added to ``_signal_row`` is covered the day it is added, whatever
    its type.

    Still not schema validation -- a wrong-typed but serializable float
    (``"3.5"`` for a number) is carried through exactly as before. The rule is
    narrower than "is this signal correct" and wider than any field list: can
    the artifact writers serialize it without raising. Dropping to None is
    safe because ``_signal_row`` already has a complete no-signal row for
    exactly that case.

    Verified against ``_signal_row`` by a test that walks its source for
    ``.value``/``_iso_or_none`` dereferences, so a field added there without a
    guard here fails the build rather than a live run.
    """
    if not isinstance(signal, SourceSignal):
        return None
    if not isinstance(getattr(signal, "action", None), Action):
        return None
    for timestamp_field in _SIGNAL_ROW_TIMESTAMP_FIELDS:
        value = getattr(signal, timestamp_field, None)
        if value is not None and not isinstance(value, datetime):
            return None
    try:
        # Placeholder ticker/source: ``_signal_row``'s own two are supplied by
        # the CALLER (``decision.ticker`` and a ``SourceName`` value, both
        # already strings), never read off the signal, so they can contribute
        # nothing this probe needs to test. Every other cell comes from the
        # signal and is exercised for real.
        #
        # Plain ``json.dumps``, matching the writer rather than tightening it:
        # the artifact path uses the same defaults, so a value it would accept
        # (a NaN float, say) must not be rejected here.
        json.dumps(_signal_row("", "", signal))
    except (TypeError, ValueError, AttributeError, RecursionError):
        # AttributeError and RecursionError are not what json.dumps raises for
        # an unserializable value, but a hostile or malformed field can reach
        # them through a custom __repr__/__eq__ or a self-referential
        # container. This helper exists so the artifact writer never raises;
        # narrowing to TypeError would leave those two escaping from the very
        # call added to prevent them.
        return None
    return signal


def _signal_row(
    ticker: str, source: str, signal: Optional[SourceSignal]
) -> Dict[str, Any]:
    if signal is None:
        return {
            "ticker": ticker,
            "source": source,
            "action": Action.NO_DATA.value,
            "reason": "no signal produced",
            "auto_buy_signal": False,
            "provider_error": None,
            "decision_bar_close": None,
            "previous_close": None,
            "previous_low": None,
            "lookback_price": None,
            "price_vs_previous_close_pct": None,
            "intraday_trend_pct": None,
            "drop_vs_previous_close_pct": None,
            "buy_multiplier": None,
            "selected_base_amount_usd": None,
            "base_selection_reason": None,
            "decision_bar_timestamp": None,
            "previous_close_timestamp": None,
            "lookback_bar_timestamp": None,
            # Signal-time quote, appended 2026-08-04. SourceSignal has carried
            # these since the target-price work; they were simply never
            # serialized, so the archived 15:30 observation could not say
            # whether the decision price was a live quote or a bar close.
            "quote_price": None,
            "quote_time": None,
        }
    return {
        "ticker": ticker,
        "source": source,
        "action": signal.action.value,
        "reason": signal.reason,
        "auto_buy_signal": signal.action == Action.BUY,
        "provider_error": signal.provider_error,
        "decision_bar_close": signal.decision_price,
        "previous_close": signal.previous_close,
        "previous_low": signal.previous_low,
        "lookback_price": signal.lookback_price,
        "price_vs_previous_close_pct": signal.price_vs_previous_close_pct,
        "intraday_trend_pct": signal.intraday_trend_pct,
        "drop_vs_previous_close_pct": signal.drop_vs_previous_close_pct,
        "buy_multiplier": signal.buy_multiplier,
        "selected_base_amount_usd": signal.selected_base_amount_usd,
        "base_selection_reason": signal.base_selection_reason,
        "suggested_amount_usd": signal.suggested_amount_usd,
        "decision_bar_timestamp": _iso_or_none(signal.decision_bar_timestamp),
        "previous_close_timestamp": _iso_or_none(signal.previous_close_timestamp),
        "lookback_bar_timestamp": _iso_or_none(signal.lookback_bar_timestamp),
        "quote_price": signal.quote_price or None,
        "quote_time": _iso_or_none(signal.quote_time),
    }


def _iso_or_none(value: Optional[datetime]) -> Optional[str]:
    return value.isoformat() if value is not None else None


def build_usage_proxy(
    *,
    decisions: Sequence[ReconciledDecision],
    signal_rows: Sequence[Dict[str, Any]],
    buy_candidates: Sequence[Dict[str, Any]],
    candidate_outcomes: Dict[str, Dict[str, Any]],
    order_reviews_attempted: Optional[int] = None,
    finance_calls_attempted: Optional[int] = None,
    robinhood_calls_attempted: Optional[int] = None,
    errors_count: int = 0,
    notifications_sent: Optional[int] = None,
    cost_control_notes: Optional[Sequence[str]] = None,
) -> Dict[str, Any]:
    """Assemble the lightweight usage-proxy block for a run's run_state.

    Every value is an activity proxy (counts of calls/rows/orders/bytes), never an
    exact credit or dollar figure. ``*_calls_attempted`` default to the number of
    scanned tickers because the daily path evaluates one finance and one Robinhood
    signal per ticker; pass explicit values when the provider count is known. The
    byte/count-of-file fields are left ``None`` here and filled by
    ``write_run_artifacts`` once the files exist on disk.
    """
    tickers_scanned = len(decisions)
    manual_review_count = sum(1 for d in decisions if d.action == Action.MANUAL_REVIEW)
    top_up_manual_review_count = sum(
        1 for c in buy_candidates if c.get("top_up_manual_review")
    )
    orders_placed_count = sum(
        # Orders, not rows: the same aggregation reason as
        # _apply_no_order_classification's own submitted counter above.
        _submitted_orders_in_row(outcome)
        for outcome in candidate_outcomes.values()
        if outcome.get("order_id") and outcome.get("status") in {"submitted", "dry_run"}
    )
    return {
        "tickers_scanned": tickers_scanned,
        "finance_calls_attempted": (
            finance_calls_attempted
            if finance_calls_attempted is not None
            else tickers_scanned
        ),
        "robinhood_calls_attempted": (
            robinhood_calls_attempted
            if robinhood_calls_attempted is not None
            else tickers_scanned
        ),
        "signal_rows_written": len(signal_rows),
        "buy_candidates_written": len(buy_candidates),
        "order_reviews_attempted": (
            order_reviews_attempted
            if order_reviews_attempted is not None
            else len(buy_candidates)
        ),
        "orders_placed_count": orders_placed_count,
        # Filled in write_run_artifacts once files are written (approximate proxy).
        "state_file_bytes": None,
        "csv_artifact_count": None,
        "total_artifact_bytes": None,
        "notifications_sent": notifications_sent,
        "errors_count": errors_count,
        "manual_recovery_required": manual_review_count > 0
        or top_up_manual_review_count > 0
        or errors_count > 0,
        "cost_control_notes": (
            list(cost_control_notes)
            if cost_control_notes is not None
            else list(DAILY_COST_CONTROL_NOTES)
        ),
    }


def _derive_order_submit_status(
    config: "StrategyConfig",
    buy_candidates: Sequence[Dict[str, Any]],
    errors_count: int,
) -> str:
    """Classify the run's overall order-submission outcome for run_classification/reporting.

    Precedence (most concrete evidence first): a dry run is always reported as
    such regardless of individual candidate outcomes; any real submitted order
    makes the whole run "submitted" evidence even if other candidates were
    blocked; an empty candidate list (no BUY signals at all that cycle) is its
    own explicit state rather than being confused with a blocked/error run; a
    broker confirmation-required response is surfaced distinctly so
    reporting/the watchdog know the task ran and passed review but placed
    nothing; unexpected provider/placement errors are reported as such; any
    other block (budget cap, buying power, tradability) falls back to
    budget_exhausted, the closest existing category.

    A placement that RAISED outranks the confirmation hold: in a zero-submission
    batch where one order awaits confirmation and another ticker's placement
    failed, reporting must not read the run as an ordinary confirmation block.
    ``is_confirmation_blocked()`` would otherwise return true for a run
    ``_apply_no_order_classification`` correctly records as a placement failure
    (Codex review).
    """
    try:
        from scripts.run_classification import (
            ORDER_SUBMIT_STATUS_BUDGET_EXHAUSTED,
            ORDER_SUBMIT_STATUS_CONFIRMATION_REQUIRED,
            ORDER_SUBMIT_STATUS_DRY_RUN,
            ORDER_SUBMIT_STATUS_ERROR,
            ORDER_SUBMIT_STATUS_NO_CANDIDATES,
            ORDER_SUBMIT_STATUS_SUBMITTED,
        )
    except ImportError:
        from run_classification import (  # type: ignore
            ORDER_SUBMIT_STATUS_BUDGET_EXHAUSTED,
            ORDER_SUBMIT_STATUS_CONFIRMATION_REQUIRED,
            ORDER_SUBMIT_STATUS_DRY_RUN,
            ORDER_SUBMIT_STATUS_ERROR,
            ORDER_SUBMIT_STATUS_NO_CANDIDATES,
            ORDER_SUBMIT_STATUS_SUBMITTED,
        )

    if config.dry_run:
        return ORDER_SUBMIT_STATUS_DRY_RUN
    # A recovery row (`"reason"` in `_RECOVERY_ROW_REASONS`) reports what an
    # EARLIER, already-resolved broker call settled to -- e.g. a same-day
    # reconciled fractional placement that turned out to be a proven
    # rejection (or acceptance) for a ticker THIS invocation's own ladder
    # never even evaluated -- not evidence about whether this run's own
    # candidate evaluation produced anything. Computed BEFORE the
    # submitted check, not only before the emptiness check below: a
    # startup recovery that reconciled to `status="submitted"` alongside
    # an otherwise-empty ladder used to satisfy the RAW, unfiltered
    # submitted check first and return ORDER_SUBMIT_STATUS_SUBMITTED,
    # never even reaching the emptiness check that already excludes
    # recovery rows -- the same completion_reason="no_ladder_candidates"
    # contradiction round 37's fix closed for the emptiness/budget-
    # exhausted path, reopened one check earlier (Codex review, PR #911
    # round 38: "Filter recoveries before checking for submissions").
    _own_candidates = [c for c in buy_candidates if c.get("reason") not in _RECOVERY_ROW_REASONS]
    if any(c.get("status") == "submitted" for c in _own_candidates):
        return ORDER_SUBMIT_STATUS_SUBMITTED
    # Deciding emptiness from the raw, unfiltered `buy_candidates` let a
    # batch whose ladder produced NO candidates at all, with only a
    # historical recovery row added by startup reconciliation, skip the
    # `not buy_candidates` branch below and fall all the way through to
    # ORDER_SUBMIT_STATUS_BUDGET_EXHAUSTED -- while the completion-reason
    # classifier elsewhere derives `completion_reason="no_ladder_
    # candidates"` from this same invocation's OWN candidates, producing
    # two artifacts of the same run that flatly contradict each other
    # (Codex review, PR #911 round 37: "Ignore recovery rows when
    # deciding candidate emptiness").
    if not _own_candidates:
        return ORDER_SUBMIT_STATUS_NO_CANDIDATES
    # Checked BEFORE the confirmation hold so a genuine broker failure is never
    # reported as a routine confirmation block (Codex review). Mirrors
    # morning_dca._concrete_order_submit_status, which returns None (leaving the
    # classifier's failure status in place) as soon as any row failed.
    #
    # Counting a recovery row's own failure here reported a run that placed
    # nothing of its own (and would otherwise have been a routine
    # no_candidates/budget_exhausted cycle) as ORDER_SUBMIT_STATUS_ERROR
    # purely because an unrelated historical claim happened to resolve as
    # a rejection during this same invocation (Codex review, PR #911
    # round 16: "Exclude recovered rejections from this run's failure
    # status").
    if any(
        c.get("status") == "failed" and c.get("reason") not in _RECOVERY_ROW_REASONS
        for c in buy_candidates
    ):
        return ORDER_SUBMIT_STATUS_ERROR
    if any(
        c.get("status") == "not_submitted_confirmation_required" for c in buy_candidates
    ):
        return ORDER_SUBMIT_STATUS_CONFIRMATION_REQUIRED
    if errors_count > 0:
        return ORDER_SUBMIT_STATUS_ERROR
    return ORDER_SUBMIT_STATUS_BUDGET_EXHAUSTED


def _build_buy_candidates(
    decisions: Sequence[ReconciledDecision],
    candidate_outcomes: Dict[str, Dict[str, Any]],
    top_up_outcomes: Optional[Dict[str, "TopUpGuardOutcome"]],
) -> List[Dict[str, Any]]:
    buy_candidates: List[Dict[str, Any]] = []
    for decision in decisions:
        outcome = candidate_outcomes.get(decision.ticker, {})
        # A ticker appended to the final session's buy_candidates solely
        # because it carries a positive pending same-day credit (see
        # _run_once_impl's flush-only injection, and _process_buy_candidate's
        # matching order_amount fallback) has a non-BUY decision.action even
        # when _process_buy_candidate went on to submit a real rounded
        # flush order for it. Excluding every non-BUY decision here would
        # drop that real order from buy_candidates.csv/counts entirely and
        # could leave order_submit_status reporting no_candidates despite a
        # submitted order, corrupting the run audit and downstream reporting
        # (Codex review: "Include pending-credit flush orders in
        # artifacts"). Only a non-BUY decision that never reached submission
        # is skipped, matching the pre-existing behavior for every ordinary
        # skipped/manual-review non-BUY ticker.
        if outcome.get("recovered_inverse_martingale_lease"):
            # A reconciled crash lease is not this run's placement at all, so it
            # must not borrow this decision's reason/signal fields. Left here it
            # matched the pending-credit-flush shape below (a non-BUY decision
            # with a "submitted" outcome) and was published as a credit flush
            # that never happened, with the wrong reason and amount (Codex
            # review: "Mark covered recovery rows as recoveries"). The recovery
            # pass at the end of this function emits its own row for it --
            # whether or not a decision covers the ticker.
            continue
        is_pending_credit_flush = decision.action != Action.BUY and outcome.get("status") in (
            "submitted",
            "dry_run",
        )
        # A whole-share ticker re-dispatched from a NO_ACTION decision purely
        # because its ledger balance alone already covered a share (see
        # _run_once_impl's preserved-fire re-dispatch) is likewise a non-BUY
        # decision that can still produce a real outcome -- fired, or
        # blocked by a safety gate on the way there, or blocked earlier still
        # (an initial duplicate-order check, a claim-verification failure, a
        # restoration-error outcome) by a branch that carries no
        # "whole_share_"-prefixed field at all. Scanning outcome keys for
        # SOME "whole_share_" marker was fragile: every new
        # _process_whole_share_candidate exit had to remember to add one, and
        # several genuinely didn't (Codex review: "Retain every whole-share
        # redispatch outcome") -- an omission there silently dropped that
        # exit from buy_candidates.csv/run_state.json and could misclassify
        # the run as no_candidates. Identify a redispatch from the DECISION
        # itself instead: _run_once_impl's redispatch loop stamps
        # synthetic_source="whole_share_redispatch" on every priced_decision
        # copy it splices in (see that loop's own comment), a field ALWAYS
        # present on the decision regardless of which outcome branch fires,
        # so this check can never miss a future exit the way the
        # outcome-key scan could.
        is_whole_share_redispatch = (
            decision.action != Action.BUY and decision.synthetic_source == "whole_share_redispatch"
        )
        if decision.action != Action.BUY and not (is_pending_credit_flush or is_whole_share_redispatch):
            continue
        target_price = _signal_target_price(decision)
        # planned_amount_usd: when the top-up guard is active for this ticker use
        # the incremental amount; otherwise use submitted_amount_usd (which
        # reflects any mid-batch kill-switch cap) or fall back to suggested_amount.
        guard = top_up_outcomes.get(decision.ticker) if top_up_outcomes else None
        submitted_amount = outcome.get("submitted_amount_usd")
        if guard is not None and outcome.get("duplicate_preserved"):
            # A same-stream duplicate-preserved retry (near_close_dca.py's
            # _process_buy_candidate) carries the REAL broker order's amount
            # from an earlier attempt this run, not a fresh placement -- this
            # retry's own freshly recomputed guard.incremental_order_amount
            # can differ (e.g. new prior-allocation context shrinks it) and
            # must not clamp away the real submitted amount here (Codex
            # review, PR #231: "Keep the broker notional when rebuilding
            # duplicate artifacts").
            planned_amount_usd = (
                submitted_amount
                if submitted_amount is not None
                else guard.incremental_order_amount
            )
        elif guard is not None:
            # When the kill-switch capped order_amount before the guard ran,
            # submitted_amount_usd already reflects the actual capped spend.
            # Use that when available so planned_amount_usd is never higher than
            # what was really submitted (guard.incremental_order_amount was itself
            # already capped in run_once, but submitted_amount_usd is the ground truth).
            planned_amount_usd = (
                min(guard.incremental_order_amount, submitted_amount)
                if submitted_amount is not None
                else guard.incremental_order_amount
            )
        elif (
            submitted_amount is None
            and (
                "whole_share_planned_notional_usd" in outcome
                or "whole_share_pending_usd" in outcome
                or "whole_share_quantity" in outcome
            )
        ):
            # A whole-share candidate's decision.suggested_amount_usd is only
            # TODAY's raw contribution -- never what the run actually
            # planned to spend. A block AFTER a real fire (ceiling/cap/
            # spread/review) carries the accumulated order_notional_usd it
            # was about to attempt via whole_share_planned_notional_usd; an
            # accumulating-only skip (still below the share threshold) never
            # set that field because nothing was ever planned to spend this
            # run, so it correctly falls back to $0 (Codex review: "Persist
            # the actual whole-share planned notional").
            planned_amount_usd = outcome.get("whole_share_planned_notional_usd", 0.0)
        else:
            planned_amount_usd = (
                submitted_amount
                if submitted_amount is not None
                else decision.suggested_amount_usd
            )
        candidate_row = {
            "ticker": decision.ticker,
            "reason": decision.reason,
            "buy_multiplier": decision.buy_multiplier,
            # See ReconciledDecision.ladder_multiplier's own docstring --
            # the high_multiplier_threshold selloff-breadth count just below
            # reads THIS field, not buy_multiplier, so an ML sizing nudge
            # can't move a ticker across the threshold on its own.
            "ladder_multiplier": decision.ladder_multiplier,
            "is_pending_credit_flush": is_pending_credit_flush,
            # Recorded so a later same-day top-up guard reading this run back as
            # prior-allocation context can reuse this run's base if it was the
            # day's first allocation (see resolve_top_up_desired_amount_usd).
            # When the guard is active, this must be the base that ACTUALLY
            # produced planned_amount_usd (guard.effective_base_amount_usd --
            # the preserved first-allocation base when reused), not this run's
            # own freshly recomputed decision.selected_base_amount_usd (Codex
            # review: "Persist the preserved base on top-up candidates").
            "selected_base_amount_usd": (
                guard.effective_base_amount_usd
                if guard is not None
                else decision.selected_base_amount_usd
            ),
            "planned_amount_usd": round(planned_amount_usd, 2),
            "target_price": target_price,
            "target_price_missing": target_price is None,
            "decision_bar_close": decision.decision_bar_close,
            "previous_close": (
                decision.finance_signal.previous_close
                if decision.finance_signal is not None
                else (
                    decision.robinhood_signal.previous_close
                    if decision.robinhood_signal
                    else None
                )
            ),
            "order_id": outcome.get("order_id"),
            "status": outcome.get("status", "not_submitted"),
            "skip_reason": outcome.get("skip_reason"),
            # Set only by _process_buy_candidates_batch's last-resort net
            # (an unhandled raise while processing this ticker). This
            # function rebuilds each row from an explicit field list, so
            # without copying it here the marker never reaches
            # run_state.json/buy_candidates.csv at all -- and in the
            # accepted-order case the persisted row is an ordinary
            # "submitted" with a null skip_reason, leaving no ticker-level
            # evidence that post-placement processing failed (Codex review,
            # PR #786: "Persist the candidate processing error marker").
            # ALWAYS present (defaulted, not conditionally added) for the
            # same reason the aggregate audit fields below are: _write_csv
            # derives buy_candidates.csv's header from row 0 alone and
            # raises if a LATER row carries a key row 0 lacks.
            "candidate_processing_error": outcome.get("candidate_processing_error"),
            # The placement breaker's own markers, ALWAYS present for the same
            # header reason stated just above. A candidate the breaker leaves
            # unattempted usually gets a purpose-built "skipped" row carrying
            # these inline -- but one PRE-SEEDED by the cross-day whole-share
            # recovery keeps the recovery's row and is annotated in place
            # instead, so without copying them here that row reaches
            # run_state.json/buy_candidates.csv showing only the older
            # recovered submission, with no evidence today's order was never
            # attempted (Codex review, PR #786: "Serialize breaker annotations
            # on recovered rows"). Same explicit-field-list trap
            # candidate_processing_error hit.
            "placement_breaker_halted": outcome.get("placement_breaker_halted"),
            "placement_breaker_tripped_here": outcome.get("placement_breaker_tripped_here"),
            "merged_placement_failed": outcome.get("merged_placement_failed"),
            "merged_placement_blocked": outcome.get("merged_placement_blocked"),
            "merged_confirmation_required": outcome.get("merged_confirmation_required"),
            "merged_failure_reason": outcome.get("merged_failure_reason"),
            "today_order_not_attempted": outcome.get("today_order_not_attempted"),
            "breaker_halt_reason": outcome.get("breaker_halt_reason"),
            # The unresolved-placement halt's counterpart to the breaker
            # markers above, kept on a key of its OWN: the batch stopped
            # because one placement's outcome could not be proven, which is a
            # different event from a consecutive-failure streak and must not
            # borrow its name. Same always-present rule, same header reason.
            "unresolved_placement_halted": outcome.get("unresolved_placement_halted"),
            "reviewed_order": outcome.get("reviewed_order"),
            # Row-level spread verdict, so a reader can separate "never reached the
            # gate" from "failed closed there" without parsing skip-reason prose.
            "spread_ok": outcome.get("spread_ok"),
            "spread_pct": outcome.get("spread_pct"),
            "spread_status": outcome.get("spread_status", SPREAD_STATUS_NOT_EVALUATED),
            # config/scheduled_tasks.json's minimum_order_aggregate_topup_1530
            # requires these on the SERIALIZED artifact row, not just the
            # intermediate candidate_outcome dict -- this function rebuilds
            # each row from an explicit field list, so anything not copied
            # here never reaches run_state.json/buy_candidates.csv (Codex
            # review discussion on commit 58a536a: "Copy aggregate audit
            # fields into artifact rows"). ALWAYS present (defaulted, not
            # conditionally added) even though only the one ticker the
            # aggregate rule actually applied to carries non-default values:
            # _write_csv derives buy_candidates.csv's header from row 0 alone
            # and raises if a LATER row carries a key row 0 lacks, and this
            # aggregate-topup ticker is typically not row 0 among several
            # ordinary candidates in the same guarded run.
            "aggregate_minimum_topup_applied": outcome.get(
                "aggregate_minimum_topup_applied", False
            ),
            "aggregate_minimum_topup_remainder_usd": outcome.get(
                "aggregate_minimum_topup_remainder_usd"
            ),
            "aggregate_minimum_topup_order_usd": outcome.get("aggregate_minimum_topup_order_usd"),
            "aggregate_minimum_topup_reason": outcome.get("aggregate_minimum_topup_reason"),
            # ALWAYS present (defaulted False), same reasoning as the
            # aggregate-topup fields above: _write_csv derives
            # buy_candidates.csv's header from row 0 alone. True only for
            # the duplicate-recovery path's fail-closed ceiling estimate
            # (Codex review: "Poison durable deployment instead of only
            # the current week") -- dca_risk.py's evidence gate reads this
            # to keep treating such a row as unusable evidence for as long
            # as the persisted artifact itself exists, not just for the
            # run that wrote it.
            "deployed_notional_uncertain": outcome.get("deployed_notional_uncertain", False),
        }
        if guard is not None:  # noqa: SIM102 - kept flat to match the block below
            candidate_row.update(
                {
                    "afternoon_desired_amount_usd": round(
                        decision.suggested_amount_usd, 2
                    ),
                    "afternoon_desired_amount": round(
                        guard.afternoon_desired_amount, 2
                    ),
                    "afternoon_decision_price": guard.afternoon_decision_price,
                    "prior_same_day_amount": round(guard.prior_same_day_amount, 2),
                    "prior_same_day_reference_price": guard.prior_same_day_reference_price,
                    "prior_same_day_run_id": guard.prior_same_day_run_id,
                    "prior_same_day_source": guard.prior_same_day_source,
                    # outcome.get(..., default) only falls back on a MISSING key --
                    # an outcome that explicitly carries None (a skip path that
                    # doesn't set incremental_order_amount) would otherwise pass
                    # None straight to float() and raise TypeError (Antigravity
                    # review: "Defensive None check for dictionary lookup").
                    "incremental_order_amount": round(
                        float(
                            outcome["incremental_order_amount"]
                            if outcome.get("incremental_order_amount") is not None
                            else guard.incremental_order_amount
                        ),
                        2,
                    ),
                    "top_up_guard_result": guard.top_up_guard_result,
                    "top_up_skipped": guard.skipped,
                    "top_up_manual_review": guard.manual_review,
                }
            )
        # Carry a whole-share candidate's accumulator detail
        # (_process_whole_share_candidate's own outcome dict, see
        # docs/whole_share_accumulation.md) into the persisted row -- without
        # this, run_state.json/the candidate CSV could report a whole-share
        # ticker as "skipped"/"submitted" with no way to see the accumulated
        # pending balance or how many shares were actually bought, even
        # though the candidate-time outcome computed those values
        # specifically for operational evidence (Codex review: "Persist
        # whole-share details in candidate artifacts"). Set unconditionally
        # (defaulting to None), exactly like reviewed_order/spread_pct above
        # -- buy_candidates.csv's writer (_write_csv) derives its header from
        # the FIRST row's keys, so a key present on only SOME rows (whichever
        # ticker happens to be whole-share) would raise on any other row,
        # normal-ticker or whole-share alike, depending on row order.
        candidate_row["whole_share_pending_usd"] = outcome.get("whole_share_pending_usd")
        candidate_row["whole_share_contribution_usd"] = outcome.get("whole_share_contribution_usd")
        candidate_row["whole_share_quantity"] = outcome.get("whole_share_quantity")
        # A settle() failure after a per-order-ceiling clamp leaves a real,
        # unfilled shortfall stranded in the ledger with no automatic path
        # back to pending_usd (see _process_whole_share_candidate's own
        # comment on this) -- surfaced here, unconditionally like the fields
        # above, so an operator can find and reconcile it from the run
        # artifacts rather than a log line alone (Codex review: "Preserve
        # clamped shortfalls when settlement fails").
        candidate_row["whole_share_settlement_reconciliation_needed"] = outcome.get(
            "whole_share_settlement_reconciliation_needed"
        )
        candidate_row["whole_share_settlement_shortfall_usd"] = outcome.get("whole_share_settlement_shortfall_usd")
        # Distinct broker order ids this row aggregates (see
        # _merge_whole_share_submission_outcomes) and the per-claim
        # trading-day/amount breakdown dca_risk.deployed_usd_by_claim_date()
        # reads to attribute a reconciled recovery to its TRUE execution
        # date instead of this artifact's own trading_day (Codex review:
        # "Preserve each broker order ID when aggregating outcomes",
        # "Attribute reconciled deployment to the claim date"). Kept as a
        # native list (not JSON-encoded) -- this SAME row list is written
        # both to run_state.json (json.dumps handles a native list/dict
        # value automatically) and to buy_candidates.csv (csv.DictWriter
        # renders a non-string value via Python's own str(), acceptable for
        # a rarely-populated audit field); pre-encoding here would leave
        # run_state.json's own "buy_candidates" carrying a JSON STRING
        # instead of a real array, breaking dca_risk.py's own
        # isinstance(..., list) read. Set unconditionally like every other
        # whole_share_ field above, for the SAME CSV-header-consistency
        # reason.
        candidate_row["whole_share_order_ids"] = outcome.get("whole_share_order_ids")
        candidate_row["whole_share_claim_breakdown"] = outcome.get("whole_share_claim_breakdown")
        # Marks a settlement-adjustment row (see _book_reconciled_whole_
        # share_order's own comment) so load_prior_same_day_allocations can
        # unconditionally exclude it from attempt_count regardless of
        # whether its claim date happens to equal this artifact's own
        # trading_day (Codex review: "Exclude same-day settlement deltas
        # from attempt counts") -- set unconditionally like every other
        # whole_share_ field above, for the same CSV-header-consistency
        # reason.
        candidate_row["whole_share_settlement_adjustment"] = outcome.get(
            "whole_share_settlement_adjustment", False
        )
        # The per-day attempt buckets an AGGREGATE row carries, and the total
        # they sum to. load_prior_same_day_allocations() reads these back off
        # the PERSISTED row to charge today's max_orders_per_day exactly once
        # per real broker attempt made today; recorded only on the in-memory
        # outcome, they never survived into run_state.json, so two same-day
        # zero-fill recoveries merged as 2 attempts reloaded as 1 and left room
        # for an extra live order beyond the cap (Codex review, PR #786:
        # "Persist merged attempt buckets into candidate artifacts"). Same
        # explicit-field-list trap the breaker annotations and the claim
        # breakdown each hit before, and set unconditionally for the same
        # _write_csv header reason. Absent on an unmerged row, where both
        # readers fall back to exactly 1 as they always did.
        candidate_row["merged_attempt_days"] = outcome.get("merged_attempt_days")
        candidate_row["merged_attempt_count"] = outcome.get("merged_attempt_count")
        buy_candidates.append(candidate_row)

    # A crash lease reconciled to a real broker order is booked and published
    # through candidate_outcomes -- but this loop is keyed by DECISIONS, and the
    # ledger-wide recovery pass deliberately reaches tickers that have none: its
    # whole purpose is to settle a claim whose ticker was un-enrolled, removed
    # from config.tickers, or excluded after the crash, none of which produce a
    # decision this run. Those outcomes would therefore be silently dropped from
    # buy_candidates.csv and orders_placed_count in exactly the scenario the
    # recovery pass exists for (Codex review: "Emit recovered orders even when
    # the ticker has no decision"). Synthesize an auditable row for them
    # instead, from the outcome alone.
    #
    # Runs for EVERY recovery outcome, not only the uncovered ones. A ticker
    # that is still enrolled does have a decision, and routing its recovery
    # through the loop above published it as a pending-credit flush -- the
    # decision's reason and signal fields attached to an order this run never
    # placed. The loop now skips recovery outcomes outright and they all land
    # here, so a recovery row means the same thing either way.
    #
    # The signal-derived fields a real candidate carries (multipliers, target
    # price, previous close) are deliberately absent rather than fabricated:
    # this row records a purchase reconstructed from broker history, not a
    # decision this run made, and inventing plausible-looking signal values
    # would corrupt the audit these artifacts exist to be. The row is marked by
    # its "reason" rather than a new column, so buy_candidates.csv keeps its
    # existing schema.
    for outcome_key, outcome in candidate_outcomes.items():
        # A reconciled fractional placement (see
        # _reconcile_prior_unproven_fractional_placements) is a DIFFERENT
        # recovery event -- a startup-time settlement of an ambiguous prior
        # placement, not a crash-lease fire -- but needs identical treatment
        # here: it is stored under an equally synthetic key, has no covering
        # decision, and would otherwise vanish from this run's own fresh
        # buy_candidates the moment it is built (Codex review, PR #911:
        # "Publish recovered submissions into the fresh run artifacts").
        # Sharing this ONE row template (rather than a second near-duplicate
        # block) is what keeps buy_candidates.csv's schema consistent when
        # both recovery kinds land in the same run -- _write_csv derives its
        # header from row 0 alone and raises if a later row carries a key
        # row 0 lacks.
        is_imart_recovery = outcome.get("recovered_inverse_martingale_lease")
        is_fractional_recovery = outcome.get("reconciled_fractional_placement")
        if not (is_imart_recovery or is_fractional_recovery):
            continue
        buy_candidates.append(
            {
                # From the outcome, not the dict key -- a recovery is stored
                # under a synthetic key so it cannot collide with this run's own
                # outcome for the same ticker.
                "ticker": outcome.get("ticker", outcome_key),
                "reason": (
                    "recovered_inverse_martingale_lease"
                    if is_imart_recovery
                    else "reconciled_fractional_placement"
                ),
                "buy_multiplier": 0.0,
                "ladder_multiplier": 0.0,
                "is_pending_credit_flush": False,
                "selected_base_amount_usd": None,
                "planned_amount_usd": round(float(outcome.get("submitted_amount_usd") or 0.0), 2),
                "target_price": None,
                "target_price_missing": True,
                "decision_bar_close": None,
                "previous_close": None,
                "order_id": outcome.get("order_id"),
                "status": outcome.get("status", "not_submitted"),
                "skip_reason": outcome.get("skip_reason"),
                "reviewed_order": outcome.get("reviewed_order"),
                "spread_ok": outcome.get("spread_ok"),
                "spread_pct": outcome.get("spread_pct"),
                "spread_status": outcome.get("spread_status", SPREAD_STATUS_NOT_EVALUATED),
                # Same uniform-column reasoning as the main loop above -- a
                # recovery row never carries the aggregate rule, but the
                # column must still exist so a preceding aggregate-topup row
                # doesn't crash _write_csv's fixed-from-row-0 fieldnames.
                "aggregate_minimum_topup_applied": outcome.get(
                    "aggregate_minimum_topup_applied", False
                ),
                "aggregate_minimum_topup_remainder_usd": outcome.get(
                    "aggregate_minimum_topup_remainder_usd"
                ),
                "aggregate_minimum_topup_order_usd": outcome.get(
                    "aggregate_minimum_topup_order_usd"
                ),
                "aggregate_minimum_topup_reason": outcome.get("aggregate_minimum_topup_reason"),
                # Carries the SAME whole_share_* keys the recovered-whole-
                # share fallback row below adds -- both are "recovery-only"
                # rows appended to the SAME buy_candidates list with no
                # covering decision, and _write_csv derives its header from
                # row 0 alone with the default extrasaction="raise": if an
                # inverse-Martingale recovery (this row) is appended FIRST
                # in a run that also recovers an orphaned whole-share claim,
                # the whole-share row's extra keys would raise ValueError
                # when writing buy_candidates.csv (Codex review: "Keep
                # recovery-only CSV rows on one schema"). None/False here --
                # an inverse-Martingale recovery genuinely has no whole-share
                # detail to report.
                "whole_share_pending_usd": None,
                "whole_share_contribution_usd": None,
                "whole_share_quantity": None,
                "whole_share_settlement_reconciliation_needed": None,
                "whole_share_settlement_shortfall_usd": None,
                "whole_share_order_ids": None,
                "whole_share_claim_breakdown": None,
                "whole_share_settlement_adjustment": False,
                # See _build_buy_candidates's own note on these two: absent
                # here (this row stands for no merge at all), present for the
                # CSV header's sake.
                "merged_attempt_days": None,
                "merged_attempt_count": None,
            }
        )

    # A whole-share ticker's recovered claim can ALSO be reconciled with no
    # decision at all -- the orphaned-ledger discovery pass (see
    # WholeShareAccumulationLedger.discover_symbols(), Codex review:
    # "Reconcile claims for tickers removed from configuration")
    # deliberately reconciles a ticker no longer in
    # config.whole_share_tickers, which therefore never gets evaluated
    # into `decisions` at all. Such an outcome is invisible to BOTH the
    # main decision-keyed loop above (nothing in `decisions` to key off)
    # AND the inverse-martingale recovery loop just above (a different
    # marker). Without emitting a row here, the reconciled fill never
    # reaches run_state.json/buy_candidates.csv at all -- and because the
    # ledger claim is now resolved, no LATER run can rediscover the spend
    # either, so persisted cap/kill-switch history permanently undercounts
    # a real broker order this run's in-memory running_deployed_7d only
    # protected for its own lifetime (Codex review: "Persist recovered
    # outcomes for orphaned whole-share tickers").
    decision_tickers = {d.ticker for d in decisions}
    for outcome_key, outcome in candidate_outcomes.items():
        # Both recovery kinds are already given their own row by the loop
        # above; this loop is for a whole-share-specific claim recovered
        # with no covering decision at all (matched below by its own
        # whole_share_* fields), never for either recovery kind.
        if outcome.get("recovered_inverse_martingale_lease") or outcome.get(
            "reconciled_fractional_placement"
        ):
            continue
        ticker = outcome.get("ticker", outcome_key)
        if ticker in decision_tickers:
            continue
        # A confirmed zero-fill recovery (see
        # _book_reconciled_whole_share_order's own zero_fill_attempt
        # branch) publishes "status": "failed" with a whole_share_
        # zero_fill_attempt marker instead of "submitted" -- nothing was
        # purchased, but it is still a REAL broker attempt, already
        # counted via ctx.state.record_buy(..., 0.0) above. Rejecting it
        # here (an earlier version of this fix did, checking only
        # "submitted" and the three submission-shaped fields below) left
        # an ORPHANED ticker's (removed from config.whole_share_tickers)
        # zero-fill attempt with no persisted trace at all: the claim was
        # already released in the ledger, so no LATER run's own ledger
        # scan can rediscover it either, permanently undercounting
        # max_orders_per_day (Codex review: "Persist orphaned zero-fill
        # recoveries").
        if outcome.get("status") != "submitted" and not outcome.get("whole_share_zero_fill_attempt"):
            continue
        if not (
            "whole_share_quantity" in outcome
            or "whole_share_claim_breakdown" in outcome
            or "whole_share_pending_usd" in outcome
            or outcome.get("whole_share_zero_fill_attempt")
        ):
            continue
        buy_candidates.append(
            {
                "ticker": ticker,
                "reason": "recovered_whole_share_claim",
                "buy_multiplier": 0.0,
                "ladder_multiplier": 0.0,
                "is_pending_credit_flush": False,
                "selected_base_amount_usd": None,
                "planned_amount_usd": round(float(outcome.get("submitted_amount_usd") or 0.0), 2),
                "target_price": None,
                "target_price_missing": True,
                "decision_bar_close": None,
                "previous_close": None,
                "order_id": outcome.get("order_id"),
                "status": outcome.get("status", "not_submitted"),
                "skip_reason": outcome.get("skip_reason"),
                "reviewed_order": outcome.get("reviewed_order"),
                "spread_ok": outcome.get("spread_ok"),
                "spread_pct": outcome.get("spread_pct"),
                "spread_status": outcome.get("spread_status", SPREAD_STATUS_NOT_EVALUATED),
                "aggregate_minimum_topup_applied": outcome.get(
                    "aggregate_minimum_topup_applied", False
                ),
                "aggregate_minimum_topup_remainder_usd": outcome.get(
                    "aggregate_minimum_topup_remainder_usd"
                ),
                "aggregate_minimum_topup_order_usd": outcome.get(
                    "aggregate_minimum_topup_order_usd"
                ),
                "aggregate_minimum_topup_reason": outcome.get("aggregate_minimum_topup_reason"),
                "whole_share_pending_usd": outcome.get("whole_share_pending_usd"),
                "whole_share_contribution_usd": outcome.get("whole_share_contribution_usd"),
                "whole_share_quantity": outcome.get("whole_share_quantity"),
                "whole_share_settlement_reconciliation_needed": outcome.get(
                    "whole_share_settlement_reconciliation_needed"
                ),
                "whole_share_settlement_shortfall_usd": outcome.get(
                    "whole_share_settlement_shortfall_usd"
                ),
                "whole_share_order_ids": outcome.get("whole_share_order_ids"),
                "whole_share_claim_breakdown": outcome.get("whole_share_claim_breakdown"),
                "whole_share_settlement_adjustment": outcome.get(
                    "whole_share_settlement_adjustment", False
                ),
                # See _build_buy_candidates's own note on these two -- an
                # orphaned-ledger recovery can itself be an aggregate.
                "merged_attempt_days": outcome.get("merged_attempt_days"),
                "merged_attempt_count": outcome.get("merged_attempt_count"),
            }
        )
    return buy_candidates


# The "reason" a no-decision recovery row in _build_buy_candidates carries --
# never a real ladder decision, and never THIS run's own reconciled amount
# for its ticker. Shared with _backfill_reconciled_signal_amounts, which must
# exclude these rows from its by-ticker mapping for the identical reason.
_RECOVERY_ROW_REASONS = frozenset(
    {
        "recovered_inverse_martingale_lease",
        "reconciled_fractional_placement",
        "recovered_whole_share_claim",
    }
)


def _backfill_reconciled_signal_amounts(
    signal_rows: List[Dict[str, Any]],
    candidate_rows: Sequence[Dict[str, Any]],
) -> None:
    """Overwrite per-provider suggested amounts with the RECONCILED amount.

    When both providers return BUY at different tiers, each signal row carries
    its own ``suggested_amount_usd`` while the reconciled candidate row captures
    what was actually planned. The drift detector reads ``suggested_amount_usd``
    via DESIRED_COLUMNS and deduplicates provider rows by keeping the largest
    positive amount, so leaving the raw per-provider figures makes a report
    claim more money went missing than was ever approved or attempted.

    Extracted alongside :func:`_build_signal_rows` so the afternoon FAILURE
    writer applies it too: that path builds its own rows and skipped the
    backfill, which is exactly the case where the figure is read as "missing"
    (Codex review, PR #859: "Backfill reconciled amounts in failure signal
    rows"). Mutates ``signal_rows`` in place.

    A no-decision RECOVERY row (``"reason"`` one of ``_RECOVERY_ROW_REASONS``
    -- an inverse-Martingale lease, a reconciled fractional placement, or an
    orphaned whole-share claim) is excluded from ``reconciled_by_ticker``: it
    reports what an EARLIER, unrelated order settled for, not what THIS
    run's current decision requested. When the recovered ticker also has an
    ordinary decision row in the same batch, the recovery row can sort after
    it, and this dict comprehension's last-row-wins-by-ticker behavior would
    silently overwrite the current decision's own reconciled amount with the
    stale recovered figure (Codex review, PR #911 round 3: "Exclude recovery
    rows from current-signal backfilling").
    """
    reconciled_by_ticker: Dict[str, float] = {
        row["ticker"]: row["planned_amount_usd"]
        for row in candidate_rows
        if isinstance(row.get("ticker"), str)
        and row["ticker"].strip()
        and row.get("planned_amount_usd") is not None
        and row.get("reason") not in _RECOVERY_ROW_REASONS
    }
    for signal_row in signal_rows:
        ticker = signal_row.get("ticker")
        if ticker in reconciled_by_ticker and signal_row.get("auto_buy_signal"):
            signal_row["suggested_amount_usd"] = reconciled_by_ticker[ticker]


def _build_signal_rows(
    decisions: Sequence[ReconciledDecision],
    candidate_outcomes: Dict[str, Dict[str, Any]],
) -> List[Dict[str, Any]]:
    """The two per-source signal rows for every decision, drift flags settled.

    Extracted from :func:`_build_run_artifacts` so the afternoon FAILURE writer
    can build the same rows: a run that stopped at the broker boundary really
    did evaluate every one of these symbols, and an artifact claiming otherwise
    misreports the run to every reporting and recovery consumer (Codex review,
    PR #859: "Preserve completed evaluation data in halt artifacts"). One
    implementation rather than two, so a rule added to either reaches both.
    """
    signal_rows: List[Dict[str, Any]] = []
    for decision in decisions:
        is_reconciled_buy = decision.action == Action.BUY
        finance_row = _signal_row(
            decision.ticker, SourceName.FINANCE.value, decision.finance_signal
        )
        robinhood_row = _signal_row(
            decision.ticker, SourceName.ROBINHOOD.value, decision.robinhood_signal
        )
        # Override auto_buy_signal with the RECONCILED decision. When providers
        # disagree (one BUY, one SKIP/NO_ACTION) reconcile_signals() produces
        # MANUAL_REVIEW and no order is placed; using the per-provider action would
        # mark that ticker as expected and trigger a false drift alert.
        finance_row["auto_buy_signal"] = is_reconciled_buy
        robinhood_row["auto_buy_signal"] = is_reconciled_buy
        signal_rows.append(finance_row)
        signal_rows.append(robinhood_row)

    # Reconcile auto_buy_signal against final placement outcomes. A BUY decision
    # may still be deliberately skipped by the top-up guard, same-day duplicate
    # guard, budget cap, safety breakers (spread, ceiling, tradability, buying
    # power). Clear the flag for those so the drift detector ignores them.
    # Keep it True for genuine errors (spread-quote error, placement failure) so
    # those do trigger alerts.
    _deliberate_skips = {
        t
        for t, oc in (candidate_outcomes or {}).items()
        if isinstance(oc, dict)
        and (
            oc.get("status") == "skipped"
            or (oc.get("status") == "blocked" and oc.get("deliberate_skip"))
        )
    }
    if _deliberate_skips:
        for _row in signal_rows:
            if (
                _row.get("auto_buy_signal")
                and _row.get("ticker") in _deliberate_skips
            ):
                _row["auto_buy_signal"] = False
    return signal_rows


def _build_budget_block(
    config: StrategyConfig,
    state: StrategyState,
    tier: BudgetTier,
    planned_spend: float,
    high_multiplier_signals: int,
    trading_day: date,
) -> Dict[str, Any]:
    return {
        "base_amount_usd": config.base_buy_amount_usd,
        "base_buy_amount_usd": config.base_buy_amount_usd,
        "budget_tier": tier.name,
        "planned_spend_usd": round(planned_spend, 2),
        "high_multiplier_signal_count": high_multiplier_signals,
        "daily_cap_usd": tier.daily_cap_usd,
        "weekly_cap_usd": round(state.effective_weekly_cap(), 2),
        "weekly_rollover_reserve_usd": round(state.weekly_rollover_reserve_usd, 2),
        "weekly_rollover_reserve_cap_usd": config.weekly_rollover_reserve_cap_usd,
        "allowed_spend_today_usd": round(
            state.allowed_spend_today(trading_day, config), 2
        ),
        "remaining_spend_today_usd": round(
            state.remaining_spend_today(trading_day, config), 2
        ),
        "day_notional_usd": round(state.day_notional(trading_day), 2),
        "week_notional_usd": round(state.week_notional(trading_day), 2),
    }


def _build_risk_guard_block(config: StrategyConfig) -> Dict[str, Any]:
    return {
        "monthly_cash_allocation_usd": config.monthly_cash_allocation_usd,
        "kill_switch_7d_deploy_fraction": config.kill_switch_7d_deploy_fraction,
        "kill_switch_7d_threshold_usd": round(
            config.kill_switch_7d_deploy_fraction * config.monthly_cash_allocation_usd,
            2,
        ),
        "deployed_last_7d_usd": round(config.deployed_last_7d_usd, 2),
        "kill_switch_engaged": kill_switch_engaged(config),
    }


def build_run_artifacts(
    now: datetime,
    config: StrategyConfig,
    state: StrategyState,
    decisions: Sequence[ReconciledDecision],
    candidate_outcomes: Dict[str, Dict[str, Any]],
    *,
    run_context: Optional[ArtifactRunContext] = None,
) -> Dict[str, Any]:
    """Build the structured run-state dict written by the daily live-run path.

    The artifact captures everything downstream reporting needs: per-source signal
    rows, buy candidates with the target price at signal time and the per-symbol
    planned dollar amount, order ids, skip/block reasons, and budget/reserve fields.
    When ``run_context.top_up_outcomes`` is supplied (the scheduled afternoon run applied the
    same-day prior-run offset/top-up guard), each candidate also records the guard's
    prior-allocation context and the resulting incremental order amount.

    Also stamps a ``run_classification`` block (via ``scripts/run_classification``)
    so downstream consumers -- ``dca_reporting``'s manual-order exclusion and
    ``dca_risk``'s scheduled-stream deployment accounting -- can tell a scheduled
    live run from a manual one from the artifact content alone. ``run_context.manual``
    selects which block is stamped: False (default) is the scheduled 3:30 PM ET
    live task, True is a manual/ad hoc invocation. ``run_context.classification_overrides``
    lets a non-afternoon scheduled caller (the roster's ``run_slot`` for 1030ET/
    1230ET) stamp its OWN stream/cron_id/scheduled_for_et/run_id instead of the
    afternoon defaults (Codex review, discussion_r3679391261: "Stamp each slot
    with its own scheduled classification") -- ignored when ``run_context.manual`` is True.

    ``run_context.correlation_id``, when given, is stamped onto the top-level artifact (next
    to ``run_id``) so the deterministic (day, stream, window) id a scheduler used
    to fire this run is recoverable from the durable run_state.json itself, not
    only from an in-process return value that is lost if the process exits or
    crashes before the caller reads it (Codex review, discussion_r3679633768:
    "Persist the slot correlation ID in run artifacts").
    """
    run_context = run_context or ArtifactRunContext()

    now_et = now.astimezone(EASTERN)
    trading_day = now_et.date()
    run_id = f"{trading_day.isoformat()}-{now_et.strftime('%H%M%S')}"
    triggered_at_utc = now.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    try:
        from scripts.run_classification import (
            build_manual_classification,
            build_scheduled_classification,
        )
    except ImportError:
        from run_classification import (  # type: ignore
            build_manual_classification,
            build_scheduled_classification,
        )
    run_classification = (
        build_manual_classification(triggered_at_utc=triggered_at_utc)
        if run_context.manual
        else build_scheduled_classification(
            trading_day.isoformat(),
            triggered_at_utc=triggered_at_utc,
            **(run_context.classification_overrides or {}),
        )
    )
    if not run_context.manual:
        # The scheduled afternoon (3:30 PM ET) artifact contract requires the
        # run_classification to additionally carry trading_day, same_day_required,
        # and valid_scheduled_evidence (see
        # scripts.scheduled_artifacts.build_afternoon_live_run_classification and
        # the identical morning-path stamping in morning_dca.py). trading_day and
        # same_day_required are known now; valid_scheduled_evidence is finalized
        # from the completed state just before this function returns.
        run_classification.setdefault("trading_day", trading_day.isoformat())
        run_classification.setdefault("same_day_required", True)

    signal_rows = _build_signal_rows(decisions, candidate_outcomes)

    buy_candidates = _build_buy_candidates(decisions, candidate_outcomes, run_context.top_up_outcomes)

    manual_review_tickers = [
        d.ticker for d in decisions if d.action == Action.MANUAL_REVIEW
    ]
    for candidate in buy_candidates:
        if (
            candidate.get("top_up_manual_review")
            and candidate["ticker"] not in manual_review_tickers
        ):
            manual_review_tickers.append(candidate["ticker"])

    # Backfill signal rows with the reconciled planned_amount_usd from buy candidates
    # so the drift detector uses the actual order amount rather than a per-provider
    # suggested amount. When both providers return BUY at different tiers, each
    # signal row carries its own suggested_amount_usd but the reconciled candidate
    # row captures what was actually placed. The drift detector reads suggested_amount_usd
    # via DESIRED_COLUMNS; overwriting it here ensures accurate missing-order reporting.
    _backfill_reconciled_signal_amounts(signal_rows, buy_candidates)

    # ⚡ Bolt Optimization: Consolidate multiple generator passes into a single loop
    # to eliminate redundant O(N) scans and generator overhead in this hot aggregation.
    planned_spend = 0.0
    high_multiplier_signals = 0
    submitted_count = 0
    skipped_count = 0
    for c in buy_candidates:
        planned_spend += c["planned_amount_usd"]
        # ladder_multiplier, not buy_multiplier: this count feeds a market-
        # BREADTH signal (select_budget_tier), and buy_multiplier already
        # has the ML sizing nudge folded in -- see ReconciledDecision.
        # ladder_multiplier's own docstring for why that distinction matters
        # here specifically.
        if (c.get("ladder_multiplier") or 0.0) >= config.high_multiplier_threshold:
            high_multiplier_signals += 1
        if c.get("status") == "submitted":
            submitted_count += 1
        else:
            skipped_count += 1

    manual_review_count = 0
    for d in decisions:
        if d.action == Action.MANUAL_REVIEW:
            manual_review_count += 1

    if state.selected_tier is None:
        state.selected_tier = select_budget_tier(planned_spend, high_multiplier_signals)
    tier = state.selected_tier
    # Ensure the rollover reserve reflects this trading day's week before the
    # effective weekly cap is reported.
    state.roll_weekly_reserve(trading_day, config)

    artifacts = {
        "run_id": run_id,
        "run_classification": run_classification,
        **({"correlation_id": run_context.correlation_id} if run_context.correlation_id is not None else {}),
        "order_submit_status": _derive_order_submit_status(config, buy_candidates, run_context.errors_count),
        "generated_at": now_et.isoformat(),
        "trading_day": trading_day.isoformat(),
        "iso_week": list(iso_week_key(trading_day)),
        "broker": config.broker.value,
        "dry_run": config.dry_run,
        # A non-reversible, KEYED fingerprint of the account -- never the raw
        # account number (Codex review, PR #911 round 3: "Persist a
        # non-sensitive account fingerprint instead"; see
        # _broker_account_fingerprint's own docstring for why a keyed HMAC,
        # not a plain hash, is required for a 6-12-digit account number). A
        # persisted ambiguous-placement row is later matched against broker
        # history by ticker/stream/date alone, with no account identity of
        # its own, so _reconcile_prior_unproven_fractional_placements binds
        # that lookup to whichever account wrote this artifact by comparing
        # against this field (Codex review, PR #911: "Bind persisted
        # reconciliation evidence to the broker account"). Null when the
        # caller has no broker/key_dir to offer (most callers/tests, and any
        # artifact written before this fingerprinting existed) -- treated as
        # "unverifiable" by the reconciler, not as a mismatch.
        "account_number": (
            _broker_account_fingerprint(run_context.broker, run_context.account_fingerprint_key_dir)
            if run_context is not None
            and run_context.broker is not None
            and run_context.account_fingerprint_key_dir is not None
            else None
        ),
        "budget": _build_budget_block(
            config, state, tier, planned_spend, high_multiplier_signals, trading_day
        ),
        "risk_guard": _build_risk_guard_block(config),
        "counts": {
            "evaluated": len(decisions),
            "buy_candidates": len(buy_candidates),
            "submitted": submitted_count,
            "skipped": skipped_count,
            "manual_review": manual_review_count,
        },
        "signal_rows": signal_rows,
        "buy_candidates": buy_candidates,
        "manual_review_tickers": manual_review_tickers,
        "usage_proxy": build_usage_proxy(
            decisions=decisions,
            signal_rows=signal_rows,
            buy_candidates=buy_candidates,
            candidate_outcomes=candidate_outcomes,
            order_reviews_attempted=run_context.order_reviews_attempted,
            finance_calls_attempted=run_context.finance_calls_attempted,
            robinhood_calls_attempted=run_context.robinhood_calls_attempted,
            errors_count=run_context.errors_count,
            notifications_sent=run_context.notifications_sent,
            cost_control_notes=run_context.cost_control_notes,
        ),
    }
    _apply_no_order_classification(artifacts, candidate_outcomes, scheduled=not run_context.manual)
    if run_context.raw_persistence_state is not None:
        artifacts.update(cast(Any, run_context.raw_persistence_state))
    if not run_context.manual:
        # Derive valid_scheduled_evidence from the completed state rather than
        # asserting it: a scheduled (non-manual) run is same-day scheduled
        # evidence, a manual run never is. Mirrors morning_dca.py's finalization.
        try:
            from scripts.same_day_pointer import derive_valid_scheduled_evidence
        except ImportError:
            from same_day_pointer import derive_valid_scheduled_evidence  # type: ignore
        run_classification["valid_scheduled_evidence"] = (
            derive_valid_scheduled_evidence(cast(Any, artifacts))
        )
    return artifacts


def _apply_no_order_classification(
    artifacts: Dict[str, Any],
    candidate_outcomes: Dict[str, Dict[str, Any]],
    *,
    scheduled: bool = True,
) -> None:
    """Record how a run that submitted zero orders is classified.

    Separates no-order logic from failures per
    config/scheduled_tasks.json:spread_gate_outcome_contract_2026_07_27. The counts
    the classifier needs -- candidates evaluated, candidates that actually reached
    the spread gate, and those failed closed there for want of a proven spread --
    come from the per-row verdicts stamped by :func:`_process_buy_candidate`, so a
    run where nothing qualified on the ladder records
    ``completion_reason='no_ladder_candidates'`` with a NULL ``error_class``
    instead of blaming the spread, while candidates stopped by a budget/cap check
    BEFORE the spread lookup record ``blocked_before_spread_gate``.

    A run whose placements all RAISED is a genuine failure, not a healthy
    no-order run: any candidate left at ``status='failed'`` marks the run
    ``failed_after_connector_native_recovery_attempt`` with
    ``is_trading_failure=true`` (Codex review).

    A run that submitted an order is not a no-order run; it keeps the
    ``order_submit_status`` the placement path derived.
    """
    outcomes = [
        oc for oc in (candidate_outcomes or {}).values() if isinstance(oc, dict)
    ]

    def _is_historical_recovery_row(oc: Dict[str, Any]) -> bool:
        """Whether ``oc`` reports what an EARLIER, already-resolved broker
        call settled to, not this run's own candidate evaluation.

        Shared by every aggregate below that means to count only THIS run's
        own candidates: a same-day reconciled fractional placement, a
        cross-day whole-share zero-fill reconciliation, or an
        inverse-Martingale lease recovery all report on evidence this run
        did not itself evaluate on the ladder.

        Checks BOTH shapes this can be called with: an OUTCOME dict (from
        ``candidate_outcomes``, carrying the boolean markers directly) and a
        synthesized ``buy_candidates`` ROW (which ``_build_buy_candidates``
        marks only via ``"reason"``, one of ``_RECOVERY_ROW_REASONS`` --
        never the boolean fields themselves, see that function's own
        recovery-row template). Checking only the boolean markers left every
        row-shaped call silently unmatched (Codex review, PR #911 round 25:
        "Exclude recovery rows from candidate evaluation counts").
        """
        return bool(
            oc.get("reconciled_fractional_placement")
            or oc.get("recovered_inverse_martingale_lease")
            or oc.get("whole_share_zero_fill_attempt")
            or oc.get("reason") in _RECOVERY_ROW_REASONS
        )

    def _is_historical_recovery_row(oc: Dict[str, Any]) -> bool:
        """Whether ``oc`` reports what an EARLIER, already-resolved broker
        call settled to, not this run's own candidate evaluation.

        Shared by every aggregate below that means to count only THIS run's
        own candidates: a same-day reconciled fractional placement, a
        cross-day whole-share zero-fill reconciliation, or an
        inverse-Martingale lease recovery all report on evidence this run
        did not itself evaluate on the ladder.

        Checks BOTH shapes this can be called with: an OUTCOME dict (from
        ``candidate_outcomes``, carrying the boolean markers directly) and a
        synthesized ``buy_candidates`` ROW (which ``_build_buy_candidates``
        marks only via ``"reason"``, one of ``_RECOVERY_ROW_REASONS`` --
        never the boolean fields themselves, see that function's own
        recovery-row template). Checking only the boolean markers left every
        row-shaped call silently unmatched (Codex review, PR #911 round 25:
        "Exclude recovery rows from candidate evaluation counts").
        """
        return bool(
            oc.get("reconciled_fractional_placement")
            or oc.get("recovered_inverse_martingale_lease")
            or oc.get("whole_share_zero_fill_attempt")
            or oc.get("reason") in _RECOVERY_ROW_REASONS
        )

    submitted = 0
    failed = 0
    connector_errors = 0
    placement_halted = False
    for oc in outcomes:
        status = oc.get("status")
        # "filled", not just "submitted": a reinjected recovery outcome can
        # already carry a proven fill (see run_daily_compact's own
        # reinjection loop, which folds a persisted "filled" outcome into
        # orders_submitted_count/counts.submitted via this SAME
        # _submitted_orders_in_row helper). Recognizing only "submitted"
        # here left this loop blind to that row: it fell through both
        # branches, submitted stayed 0, and this function went on to stamp
        # completed_no_orders/reset orders_submitted_count to zero over a
        # state that genuinely contains a filled order -- reporting no
        # order submitted right beside a nonzero submitted count the
        # merge just computed (Codex review: "Count filled reinjections
        # before reclassifying the run").
        if status in ("submitted", "filled"):
            # Orders, not rows -- a merged recovery row can stand for several
            # real broker submissions (see _merge_whole_share_submission_
            # outcomes' merged_submission_count).
            submitted += _submitted_orders_in_row(oc)
        elif status == "failed":
            # A HISTORICAL recovery row -- a same-day reconciled fractional
            # placement that turned out to be a proven rejection, or a
            # cross-day whole-share zero-fill reconciliation -- reports what
            # an EARLIER, already-resolved broker call settled to, not a
            # failure of THIS run's own candidate evaluation. The attempt it
            # represents is already booked into ctx.state via its own
            # dedicated call (book_reconciled_attempt_notional / record_buy
            # at the reconciliation site itself); counting it here as well
            # made a run that placed every one of its OWN candidates cleanly
            # get classified failed_after_submission/is_trading_failure=True
            # purely because an unrelated historical claim resolved as a
            # rejection during this same invocation (Codex review, PR #911
            # round 16: "Exclude recovered rejections from this run's
            # failure status"). `recovered_inverse_martingale_lease` never
            # actually reaches "failed" today (that recovery is always
            # published "submitted", fill or not) but is excluded here too
            # for the same reason and to guard against it ever doing so.
            if not _is_historical_recovery_row(oc):
                failed += 1
        elif status == "blocked" and not oc.get("deliberate_skip"):
            connector_errors += 1
        # A tripped placement breaker is a trading failure whatever the row
        # statuses say, and its own rows say nothing: the unattempted tail is
        # "skipped" with deliberate_skip=True, and the failures that TRIPPED it
        # can be OrderConfirmationRequiredError, which is neither "failed" nor
        # a non-deliberate "blocked". This is the SAME gap the morning
        # executor's own copy of this function had -- fixed there first,
        # because these two aggregates are independent implementations of one
        # contract and a fix to either does not reach the other (Codex review,
        # PR #786: "Classify afternoon breaker halts as trading failures").
        # INDEPENDENT of the merged-marker checks below, not the head of an
        # elif chain with them. A row can carry both -- today's failed
        # placement merged with an older recovery IS what tripped the
        # breaker -- and chaining meant the breaker branch consumed the row
        # and `failed` never incremented: with a threshold of 1 the run
        # reported orders_failed_count=0, and at the default threshold it
        # undercounted the streak by one (Codex review, PR #786: "Count
        # merged failures even when the breaker trips").
        if oc.get("placement_breaker_halted"):
            placement_halted = True
        # A row whose status was forced to "submitted" by a merged recovery
        # can still hide a fresh placement failure from today (see
        # _merge_whole_share_submission_outcomes). Counted as a failure here
        # so the run is classified on what actually happened rather than on
        # the aggregate status.
        if oc.get("merged_placement_failed") and oc.get("status") == "submitted":
            failed += 1
        # The same masking, for the other kind of hidden event: a merged
        # recovery can equally bury a non-deliberate BLOCK, which this
        # aggregate counts as a connector error rather than a failed order.
        # Also independent of the failed marker above: a three-way merge can
        # carry both a failed and a blocked side, and each is its own event.
        if oc.get("merged_placement_blocked") and oc.get("status") == "submitted":
            connector_errors += 1

    # A pre-placement broker check that RAISED is recorded as a non-deliberate
    # block, not as 'failed'. We count these as connector errors here too so a batch
    # that placed one order but lost another ticker to a connector failure is not
    # recorded as an ordinary success with no error class (Codex review).
    # Same rule as the morning runner.
    artifacts["orders_submitted_count"] = submitted
    if submitted:
        if failed or connector_errors or placement_halted:
            # A partially submitted batch: some orders landed and another ticker
            # was lost -- its placement raised, a pre-placement broker check
            # did, or the placement breaker halted the batch and left the tail
            # unattempted. Returning as an ordinary success would leave the run
            # with no is_trading_failure and no failure outcome even though an
            # intended order never happened (Codex review).
            artifacts["run_classification_outcome"] = (
                RUN_CLASSIFICATION_FAILED_AFTER_SUBMISSION
            )
            artifacts["is_trading_failure"] = True
            artifacts["orders_failed_count"] = failed
            artifacts.setdefault(
                "error_class",
                (
                    # A tripped breaker is a PLACEMENT failure, not degraded
                    # market data: the batch stopped because the broker leg
                    # was unhealthy.
                    ERROR_CLASS_PARTIAL_PLACEMENT_FAILURE
                    if failed or placement_halted
                    else ERROR_CLASS_DEGRADED_MARKET_DATA
                ),
            )
        return
    at_gate = [oc for oc in outcomes if oc.get("spread_status")]
    reaching_gate = sum(
        1 for oc in at_gate if oc.get("spread_status") != SPREAD_STATUS_NOT_EVALUATED
    )
    # Only rows the SPREAD GATE itself stopped, recorded explicitly rather than
    # inferred from spread_status: a manual run does not fail closed on an
    # unproven spread, so a row can carry spread_status='spread_unavailable' and
    # still be stopped later by review or confirmation (Codex review).
    blocked_missing_spread = sum(
        1 for oc in outcomes if oc.get("blocked_by") == BLOCKED_BY_SPREAD_GATE
    )
    # Excludes the SAME historical recovery rows the `failed` aggregate
    # above already does, not the raw `len(buy_candidates)`: that list can
    # carry a synthesized row for a prior, unrelated ambiguous placement
    # this invocation merely reconciled, alongside whatever THIS run's own
    # ladder actually produced (possibly nothing). Counting the recovery
    # row here classified a genuinely empty ladder as
    # `blocked_before_spread_gate` (candidates qualified but were stopped
    # before the spread lookup) instead of `no_ladder_candidates` (nothing
    # qualified at all), even though no CURRENT candidate was evaluated or
    # blocked by anything (Codex review, PR #911 round 25: "Exclude
    # recovery rows from candidate evaluation counts"). Filtered from the
    # SAME `buy_candidates` list `candidates_evaluated` always counted,
    # not switched to the broader `candidate_outcomes`/`outcomes`, which
    # covers every ticker this run considered (skipped and manual-review
    # ones included) rather than only those that reached the ladder.
    candidates_evaluated = sum(
        1
        for row in (artifacts.get("buy_candidates") or [])
        if isinstance(row, dict) and not _is_historical_recovery_row(row)
    )
    outcome = classify_no_order_run(
        candidates_reaching_spread_gate=reaching_gate,
        candidates_blocked_missing_spread=blocked_missing_spread,
        candidates_evaluated=candidates_evaluated,
        # A tripped breaker counts here too, for the same reason it does in
        # the submitted branch above: its own rows contribute nothing to the
        # "failed" count, so a breaker that fired before ANY order landed
        # recorded `completed_no_orders` with no is_trading_failure at all.
        # `placement_attempted_and_failed` is the exact fit -- placement ran on
        # qualifying candidates and could not place them (Codex review,
        # PR #786: "Classify afternoon breaker halts as trading failures", the
        # zero-submission half of the same gap).
        # Reads the counters the loop above ALREADY computed rather than
        # re-deriving from raw statuses, which is what this line used to do
        # and why it went wrong: a merged row's status is forced to
        # "submitted", so `any(status == "failed")` cannot see a failure the
        # merge markers recorded. With a settlement adjustment on the other
        # side the aggregate also counts ZERO submissions -- adjustments
        # correct an already-counted order -- so the run reaches this
        # zero-submission branch carrying `failed = 1` and was classified
        # `completed_no_orders` with no is_trading_failure and no
        # orders_failed_count at all (Codex review, PR #786: "Include merged
        # failures in zero-order classification").
        #
        # `connector_errors` joins them for the same reason the SUBMITTED
        # branch above already treats the three together: a pre-placement or
        # reconciliation call that raised is a placement that was attempted
        # and did not place, whether or not anything else submitted.
        placement_attempted_and_failed=bool(failed or connector_errors or placement_halted),
        # Providers that raised degrade tickers to NO_DATA/manual review rather
        # than genuinely evaluating them, so the zero-order result is not a clean
        # ladder no-op and must not be recorded with a null error_class.
        data_errors=int((artifacts.get("usage_proxy") or {}).get("errors_count") or 0),
        # A manual run never runs the scheduled connector-native recovery policy,
        # so its broker failures must not be recorded under that outcome.
        scheduled=scheduled,
    )
    fields = outcome.as_run_state_fields()
    # Only the submitted branch above recorded this, so a zero-submission run
    # that really did fail a placement reported the outcome without the count
    # an operator reads to know how many orders to chase.
    if failed:
        artifacts.setdefault("orders_failed_count", failed)
    # A concrete status the placement path derived -- dry_run,
    # not_submitted_confirmation_required (review passed, submission awaiting
    # confirmation), not_submitted_error -- is more specific than "no orders" and
    # stays, or downstream consumers such as is_confirmation_blocked would lose
    # it. Two are replaced:
    #   * not_submitted_budget_exhausted is the fallback
    #     _derive_order_submit_status reaches when nothing else matched, so it is
    #     only trustworthy when a candidate really was blocked on a budget, cap,
    #     or buying-power check; and
    #   * not_submitted_no_candidates describes exactly the no-ladder-candidate
    #     case the contract assigns 'no_orders_submitted'. Keeping it would make
    #     the afternoon aggregate disagree with both the contract and the morning
    #     stream for the same situation (Codex review). Its specificity is not
    #     lost: completion_reason='no_ladder_candidates' carries it, which is the
    #     field designed for exactly that.
    current = artifacts.get("order_submit_status")
    budget_blocked = any(oc.get("budget_blocked") for oc in outcomes)
    replaceable = current in (
        ORDER_SUBMIT_STATUS_BUDGET_EXHAUSTED,
        ORDER_SUBMIT_STATUS_NO_CANDIDATES,
    )
    if not replaceable or (
        current == ORDER_SUBMIT_STATUS_BUDGET_EXHAUSTED and budget_blocked
    ):
        fields.pop("order_submit_status", None)
    artifacts.update(fields)


# CSV artifacts a run may leave beside run_state.json, and the status recorded in
# the minimal run_state stub written when the date gate blocks execution.
_RUN_CSV_NAMES = ("signals.csv", "buy_candidates.csv", "orders.csv")
RUN_STATUS_BLOCKED = "blocked"


def _existing_csv_artifacts(out: Path) -> List[Path]:
    return [out / name for name in _RUN_CSV_NAMES if (out / name).exists()]


def _serialize_run_state(run_state: Dict[str, Any]) -> str:
    return json.dumps(run_state, indent=2, sort_keys=True)


def _settle_usage_bytes(
    run_state: Dict[str, Any], usage: Dict[str, Any], csv_bytes: int
) -> str:
    """Set state_file_bytes/total_artifact_bytes to match the payload written to disk.

    The serialized size only shifts when a counter changes digit count, so this
    settles in a pass or two; the values are documented usage *proxies*, so a
    pathological digit-boundary case exiting one byte off is tolerable.
    """
    serialized = _serialize_run_state(run_state)
    for _ in range(4):
        state_bytes = len(serialized.encode("utf-8"))
        if (
            usage.get("state_file_bytes") == state_bytes
            and usage.get("total_artifact_bytes") == state_bytes + csv_bytes
        ):
            break
        usage["state_file_bytes"] = state_bytes
        usage["total_artifact_bytes"] = state_bytes + csv_bytes
        serialized = _serialize_run_state(run_state)
    return serialized


def write_run_artifacts(
    artifacts: Dict[str, Any], output_dir: str | Path
) -> Dict[str, Any]:
    """Write the run-state JSON plus signal and candidate CSVs; return their paths.

    The returned dict's ``"run_state"``/``"signals"``/``"buy_candidates"`` values
    are path strings, as before. It also carries ``"_run_state_written_bytes"``:
    the EXACT bytes this call just wrote to run_state.json (not a path). A
    caller that needs to later confirm no other run has since replaced that
    file should compare against this value rather than reading run_state.json
    back from disk -- a re-read after this function's lock is released
    reopens exactly the race this value exists to close (Codex review: "Bind
    the snapshot to this invocation's state").
    """
    out = Path(output_dir)
    out.mkdir(parents=True, exist_ok=True)

    signals_path = out / "signals.csv"
    _write_csv(signals_path, artifacts["signal_rows"])

    candidates_path = out / "buy_candidates.csv"
    _write_csv(candidates_path, artifacts["buy_candidates"])

    # Count only the CSVs this run just wrote. orders.csv (written afterwards on
    # the compact path) is folded in by _backfill_orders_csv_usage; a stale
    # orders.csv left in a reused directory must not be attributed to this run.
    csv_paths = [signals_path, candidates_path]
    csv_bytes = sum(path.stat().st_size for path in csv_paths)

    usage = artifacts.get("usage_proxy")
    if isinstance(usage, dict):
        usage["csv_artifact_count"] = len(csv_paths)
        serialized = _settle_usage_bytes(artifacts, usage, csv_bytes)
    else:
        serialized = _serialize_run_state(artifacts)

    run_state_path = out / "run_state.json"
    with cross_process_lock(run_state_path.with_name(f"{run_state_path.name}.lock")):
        atomic_write_text(run_state_path, serialized)

    paths: Dict[str, Any] = {
        "run_state": str(run_state_path),
        "signals": str(signals_path),
        "buy_candidates": str(candidates_path),
        "_run_state_written_bytes": serialized.encode("utf-8"),
    }
    return paths


def _select_reconciled_signal_rows(
    signal_rows: Sequence[Dict[str, Any]], decisions: Sequence[ReconciledDecision]
) -> List[Dict[str, Any]]:
    """Reduce two rows per ticker (finance, then Robinhood) to the ONE row
    that actually produced each ticker's reconciled decision.

    The scheduled natural key ``append_observations`` merges on is
    ``(trading_day, stream, slot, ticker)`` -- source is deliberately not
    part of it -- so archiving both providers' rows unfiltered would collapse
    to whichever row happens to sort last, discarding the other provider's
    row even when IT is the one the reconciled decision actually used
    (Codex review: "Archive one reconciled near-close observation per
    ticker"). A BUY decision's ``target_price_source`` names the winning
    provider directly; a non-BUY decision has no "winning" provider, so this
    prefers Finance (this system's primary data source, per the
    Finance-primary-with-Robinhood-fallback policy) when it produced a real
    signal, falling back to Robinhood only when Finance has none.
    """
    preferred_source: Dict[str, str] = {}
    for decision in decisions:
        if decision.target_price_source:
            preferred_source[decision.ticker] = decision.target_price_source.split(":", 1)[0]
        elif decision.finance_signal is not None and decision.finance_signal.action != Action.NO_DATA:
            preferred_source[decision.ticker] = SourceName.FINANCE.value
        elif decision.robinhood_signal is not None:
            preferred_source[decision.ticker] = SourceName.ROBINHOOD.value
        else:
            preferred_source[decision.ticker] = SourceName.FINANCE.value

    decision_by_ticker = {d.ticker: d for d in decisions}
    selected: Dict[str, Dict[str, Any]] = {}
    for row in signal_rows:
        ticker = row.get("ticker")
        if ticker is None:
            continue
        wanted = preferred_source.get(ticker)
        if ticker in selected or (wanted is not None and row.get("source") != wanted):
            continue
        # Copied, never mutated in place: this same row object is also what
        # write_run_artifacts() writes to signals.csv, and archiving must not
        # leak fabricated columns into that unrelated artifact.
        row = dict(row)
        decision = decision_by_ticker.get(ticker)
        if decision is not None and decision.target_price_source:
            # signal_rows never serializes quote_price/quote_time (see
            # _signal_row), so observations_from_signal_rows always fell
            # back to decision_bar_close for "price" -- even when the
            # reconciled decision actually sized and targeted the order from
            # a live quote that differs from the completed bar. Overlaying
            # the decision's own resolved target here (not the raw
            # per-provider signal's quote_price, since decision.target_price
            # is the authoritative execution target after reconciliation)
            # onto the fields observations_from_signal_rows already reads
            # keeps the shared archive's price consistent with what
            # placement actually used (Codex review: "Archive the near-close
            # target quote").
            row["current_price"] = decision.target_price
            row["price_source"] = decision.target_price_source
            if decision.target_quote_time is not None:
                row["price_as_of"] = decision.target_quote_time
        selected[ticker] = row
    return list(selected.values())


def _archive_intraday_observations(
    artifacts: Dict[str, Any],
    out: Path,
    decisions: Sequence[ReconciledDecision] = (),
    run_state_path: Optional[Path] = None,
    run_result: Optional[RunResult] = None,
) -> Optional[str]:
    """Record the 15:30 poll's prices/timestamps in the shared intraday archive.

    The near-close signal rows are the only ones in this repo that already
    carried their own timestamps (``decision_bar_timestamp``,
    ``previous_close_timestamp``) -- they just had nowhere durable to accumulate.
    This lands them in the same per-ticker archive the morning-family streams
    write to, so all eight scheduled polls read back as one time series
    (see dca_intraday_archive).

    ``decisions`` reduces the two-rows-per-ticker (Finance, then Robinhood)
    ``signal_rows`` down to one reconciled row per ticker before archiving --
    see :func:`_select_reconciled_signal_rows`.

    Best-effort and never raised: this run has already placed real orders and
    written its full artifact set by the time it is called -- callers invoke
    this ONLY after the scheduled contract's required run_summary.json and
    submitted_orders.csv are already on disk (or, for a manual run with no
    contract to finalize, right after write_run_artifacts), never before,
    since a per-ticker archive lock can block for several seconds and must
    never delay those required files past the just-fired-run grace period a
    monitor uses to distinguish a genuinely incomplete run from one still
    finishing (Codex review: "Finalize scheduled artifacts before waiting on
    archive locks"). ``usage_proxy`` counters are deliberately NOT re-derived
    to include observations.csv -- they were already settled against the two
    CSVs write_run_artifacts wrote, and re-opening that accounting for an
    observability file would change a figure other tooling reconciles
    against.

    Unlike the morning-family path (``MorningDCAExecutor._archive_observations``),
    a failed archive write here previously left no trace once process logs
    were gone: a summary with ``ok: false`` was only logged, not persisted.
    When ``run_state_path`` is given (the on-disk path
    :func:`write_run_artifacts` already wrote for this run), the archive
    summary is now annotated and run_state.json is re-persisted with it,
    mirroring the morning-family contract so post-run artifact consumers can
    detect an unavailable shared archive after the fact (Codex review:
    "Persist near-close archive failures in run state"). Two things this
    annotation must NOT do, both from a later Codex pass on the first fix:

    * Serialize the in-memory ``artifacts`` dict verbatim over the file.
      ``_write_and_validate_scheduled_contract`` (called by every scheduled
      caller before this) amends the ON-DISK run_state.json in place with
      ``status='blocked'``/``artifact_contract_failure`` on a contract
      breach without touching this function's ``artifacts`` argument;
      overwriting the file with that now-stale in-memory copy would erase
      the rejection every consumer downstream relies on (Codex review:
      "Preserve contract-failure markers when annotating run state"). The
      CURRENT on-disk state is therefore read fresh and used as the base,
      falling back to ``artifacts`` only if the file is missing or
      unreadable.
    * Leave ``usage_proxy.state_file_bytes``/``total_artifact_bytes`` stale.
      Those were already settled by :func:`write_run_artifacts` against the
      serialized size BEFORE this annotation grew the file; re-running the
      same settlement pass here keeps them accurate (Codex review:
      "Recalculate usage bytes after expanding run state").

    Re-persisting is itself best-effort: a failure to annotate must never
    invalidate the already-valid run_state on disk.
    """
    try:
        signal_rows = artifacts.get("signal_rows") or []
        if decisions:
            signal_rows = _select_reconciled_signal_rows(signal_rows, decisions)
        observations = observations_from_signal_rows(
            signal_rows,
            run_classification=artifacts.get("run_classification") or {},
            generated_at=artifacts.get("generated_at") or artifacts.get("as_of"),
            data_source=str(artifacts.get("data_source") or ""),
            trading_day=artifacts.get("trading_day"),
        )
    except Exception as exc:  # noqa: BLE001 - observability must not fail a run
        logger.warning("could not build intraday observations: %s", exc)
        return None
    snapshot_path = write_run_snapshot(out, observations)
    summary = archive_observations_safely(observations)
    summary["observations"] = len(observations)
    summary["run_snapshot"] = snapshot_path
    artifacts["intraday_archive"] = summary
    if not summary.get("ok"):
        logger.warning(
            "intraday observation archive write failed for %s: %s",
            artifacts.get("run_id"),
            summary.get("error"),
        )
    if run_state_path is not None:
        try:
            # Use the same sidecar as the primary run-state publisher so the
            # read, comparison basis, and replacement form one cross-process
            # critical section. Atomic rename alone prevents torn bytes but
            # cannot prevent a stale read-modify-write from winning.
            with cross_process_lock(
                run_state_path.with_name(f"{run_state_path.name}.lock")
            ):
                try:
                    _on_disk_raw_bytes = run_state_path.read_bytes()
                    on_disk = json.loads(_on_disk_raw_bytes)
                except (OSError, json.JSONDecodeError, UnicodeDecodeError):
                    _on_disk_raw_bytes = None
                    on_disk = None
                # Reject a same-identity PEER's state before annotating over
                # it: the comment this replaced claimed the lock alone
                # "confirms no other writer has touched the file", but the
                # lock only serializes writers against EACH OTHER -- it says
                # nothing about whether the bytes now on disk are still
                # THIS invocation's own. When run_result carries a
                # reference (this invocation's own last-known-published
                # bytes), a mismatch means a peer replaced run_state.json in
                # the gap since that publish; annotating over it would
                # overwrite the peer's genuinely valid state, and advancing
                # the snapshot to the resulting peer-derived bytes would
                # make run_daily_compact's later concurrent-writer check
                # read this invocation's OWN intraday-archive write as
                # having come from itself when it actually clobbered a peer
                # (Codex review: "Reject peer state before advancing the
                # publication snapshot"). No reference to compare against
                # (run_result absent, or this is the first write it has
                # ever recorded) falls back to the prior best-effort
                # behavior -- there is nothing to detect a mismatch against.
                if (
                    run_result is not None
                    and run_result.published_run_state_bytes is not None
                    and _on_disk_raw_bytes != run_result.published_run_state_bytes
                ):
                    logger.warning(
                        "run_state at %s changed since this invocation's own last "
                        "publish; skipping intraday archive annotation rather than "
                        "overwriting what is now a different run's state",
                        run_state_path,
                    )
                    # This invocation's own contract_ok was already decided
                    # by _write_and_validate_scheduled_contract before this
                    # call ran, from bytes this path no longer holds -- flag
                    # it so the caller does not publish latest_scheduled_run.json
                    # from a stale in-memory belief about a path a peer now
                    # owns.
                    run_result.archive_ownership_rejected = True
                    return snapshot_path
                if not isinstance(on_disk, dict):
                    # A missing, unreadable, or non-object run_state.json is not
                    # a blank slate to fill in from the in-memory `artifacts` --
                    # it means contract validation (or an earlier writer) could
                    # not attach whatever failure marker it needed to, and this
                    # function has no way to tell an innocent "file not written
                    # yet" apart from a genuinely rejected/unusable state.
                    # Silently substituting the pre-validation in-memory copy
                    # here would materialize a run_state.json that LOOKS like
                    # valid scheduled evidence even though contract validation
                    # never actually approved it -- the opposite of fail-closed
                    # (Codex review: "Never synthesize run_state from in-memory
                    # artifacts when the on-disk file is unusable"). Leave the
                    # on-disk file exactly as it is; only the in-memory
                    # `artifacts` dict (already annotated with
                    # ``intraday_archive`` above) reflects this summary.
                    logger.warning(
                        "run_state at %s is missing or unreadable; skipping intraday "
                        "archive annotation rather than overwriting it",
                        run_state_path,
                    )
                    return snapshot_path
                target = on_disk
                target["intraday_archive"] = summary
                usage = target.get("usage_proxy")
                if isinstance(usage, dict):
                    csv_paths = _existing_csv_artifacts(run_state_path.parent)
                    usage["csv_artifact_count"] = len(csv_paths)
                    csv_bytes = sum(path.stat().st_size for path in csv_paths)
                    serialized = _settle_usage_bytes(target, usage, csv_bytes)
                else:
                    serialized = _serialize_run_state(target)
                atomic_write_text(run_state_path, serialized)
                # Same reasoning as the contract-failure stamp in
                # _write_and_validate_scheduled_contract: this is THIS
                # invocation's own further legitimate write to
                # run_state.json, made under this SAME lock right after
                # confirming no other writer has touched the file (the
                # on_disk read above), so the RunResult snapshot must move
                # forward to match it -- otherwise run_daily_compact's later
                # concurrent-writer check would read this invocation's own
                # intraday-archive annotation as a foreign peer's write
                # (Codex review: "Capture this invocation's state at
                # publication time").
                if run_result is not None:
                    run_result.published_run_state_bytes = serialized.encode("utf-8")
        except (OSError, TypeError, ValueError) as exc:  # noqa: BLE001
            logger.warning(
                "could not annotate run_state with intraday archive summary: %s", exc
            )
    return snapshot_path


def _backfill_orders_csv_usage(run_state_path: Path) -> None:
    """Re-derive the CSV usage-proxy counters from disk after orders.csv is written.

    ``orders.csv`` lands after ``write_run_artifacts`` has already finalized
    ``run_state.json``, so without this pass the daily compact path would
    undercount ``csv_artifact_count``/``total_artifact_bytes``.
    """
    if not run_state_path.exists():
        return
    # Same sidecar the archive writer above and the primary run-state
    # publisher use: this is a read-modify-write of run_state.json, and an
    # unlocked read here can race an overlapping retry's own annotation,
    # silently reverting its recovered submission evidence or usage update
    # back to this call's stale copy (Codex review: "Put every run-state
    # writer behind the sidecar lock" / "Lock the compact usage backfill
    # with the same sidecar").
    try:
        with cross_process_lock(run_state_path.with_name(f"{run_state_path.name}.lock")):
            _backfill_orders_csv_usage_locked(run_state_path)
    except TimeoutError:
        # This backfill pass is best-effort observability (see docstring);
        # a stale or crashed lock holder must not raise out and abort the
        # rest of the run.
        return


def _backfill_orders_csv_usage_locked(run_state_path: Path) -> None:
    """The same backfill as :func:`_backfill_orders_csv_usage`, for a caller
    that ALREADY holds ``run_state.json.lock``.

    ``flock`` is associated with the open file description, not the holding
    process -- a second, nested ``cross_process_lock()`` acquisition on the
    same path from inside an already-held one does not reenter, it contends
    against itself and simply times out. ``run_daily_compact``'s own unified
    ownership-verify-and-publish critical section (Codex review: "Require
    verified ownership before merging executions") holds this lock across
    its own reinjection/orders.csv/usage-backfill writes precisely so an
    overlapping retry cannot claim the directory in the gap between them,
    so it calls this locked variant directly instead of the lock-acquiring
    wrapper above.
    """
    if not run_state_path.exists():
        return
    run_state = json.loads(run_state_path.read_bytes())
    usage = run_state.get("usage_proxy")
    if not isinstance(usage, dict):
        return
    csv_paths = _existing_csv_artifacts(run_state_path.parent)
    usage["csv_artifact_count"] = len(csv_paths)
    csv_bytes = sum(path.stat().st_size for path in csv_paths)
    atomic_write_text(run_state_path, _settle_usage_bytes(run_state, usage, csv_bytes))


# Stable header for a zero-row signals.csv / buy_candidates.csv. An empty
# universe (no active tickers, or every configured ticker excluded) previously
# wrote a zero-byte file, which the artifact contract rejects for lacking a
# header, failing the run and blocking the latest-pointer update (Codex review).
_EMPTY_CSV_FIELDS = ("ticker",)


def _write_csv(
    path: Path,
    rows: Sequence[Dict[str, Any]],
    *,
    empty_fieldnames: Sequence[str] = _EMPTY_CSV_FIELDS,
    fieldnames: Optional[Sequence[str]] = None,
) -> None:
    """Write ``rows`` as CSV, deriving the header from row 0 unless ``fieldnames``
    is given explicitly.

    Row-0-derived headers are safe only when every row comes from the SAME
    builder, as the ordinary success path guarantees. A caller merging rows
    from different eras/builders (e.g. a failure artifact preserved across a
    retry) can have rows with different key sets, and DictWriter's default
    ``extrasaction="raise"`` then crashes the moment a later row carries a key
    row 0 lacks. Pass an explicit, unioned ``fieldnames`` in that case.
    """
    if not rows:
        with atomic_open_w(path, newline="") as handle:
            csv.DictWriter(handle, fieldnames=list(empty_fieldnames)).writeheader()
        return
    resolved_fieldnames = list(fieldnames) if fieldnames is not None else list(rows[0].keys())
    with atomic_open_w(path, newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=resolved_fieldnames)
        writer.writeheader()
        writer.writerows(rows)


# Buy-candidate statuses that mean an order was actually placed (and therefore
# count as prior same-day allocation for the top-up guard).
# "dry_run" is deliberately excluded: its own skip_reason ("dry_run: order not
# placed") means no real capital moved, so a manual dry-run test earlier the
# same day must never reduce the scheduled run's real buy.
#
# "pending"/"unconfirmed" join "submitted"/"filled" for the same reason
# morning_dca._ORDER_BEARING_CANDIDATE_STATUSES already includes them: a
# broker refresh can leave a row still live at the venue (not yet a terminal
# fill) or awaiting the broker's own confirmation echo, and that capital is
# just as committed as a "submitted" row's. This constant is documented
# (there, and in several comments throughout this module) as mirroring that
# one, but had drifted -- a correctly preserved "pending"/"unconfirmed"
# candidate was still skipped here entirely (no attempt count, no deployed
# amount) whenever this loader ran via an explicit prior_allocation_state_root
# or a direct cap-seeding call, letting another ticker spend the apparent
# headroom (Codex review: "Admit in-flight statuses in prior-allocation
# loading").
#
# "potentially_submitted" joins the set for the same reason: an unresolved
# potentially-submitted order is conservatively reserved at its planned
# amount until reconciliation proves whether capital moved (PR #538).
_PRIOR_ALLOCATION_STATUSES = frozenset(
    {"submitted", "filled", "pending", "unconfirmed", "potentially_submitted"}
)
# Broader than _PRIOR_ALLOCATION_STATUSES above: also admits "failed" rows
# (near_close_dca's own placement-exception path, e.g. a broker API error --
# _process_buy_candidate's "except Exception" branch) into the aggregation
# loop for ATTEMPT-COUNTING only. config/budgets.json's max_orders_per_day is
# defined as a count of buy ATTEMPTS, not successful placements -- "a
# cancelled or rejected buy still consumes one" -- so a genuine broker-facing
# attempt that failed must still be reconstructed as one attempt when
# rebuilding state from prior artifacts (Codex review: "Count every prior buy
# attempt toward the daily limit"). "skipped" is deliberately still excluded:
# it means the candidate was blocked BEFORE any broker submission (budget cap,
# duplicate guard, whitelist, etc.), so no attempt was ever made.
_PRIOR_ALLOCATION_ATTEMPT_STATUSES = _PRIOR_ALLOCATION_STATUSES | {"failed"}


def _candidate_logged_reference_price(candidate: Dict[str, Any]) -> Optional[float]:
    """Resolve a prior candidate's logged reference price by policy preference.

    Same-day top-up guard policy resolves a prior run's reference price in this
    order: the run's logged ``target_price``, then ``decision_price`` (also
    recorded as ``decision_bar_close``). Callers must only use this logged
    reference for candidates whose capital movement is confirmed (for example a
    filled candidate or a candidate with a confirmed fill row). Unconfirmed
    submitted candidates keep an unknown reference even when target/decision
    prices were logged, routing later top-ups to the conservative manual-review
    path. Returns the first strictly-positive value, else ``None``.
    """
    for key in ("target_price", "decision_price", "decision_bar_close"):
        raw = candidate.get(key)
        if raw is None:
            continue
        try:
            value = float(raw)
        except (TypeError, ValueError, OverflowError):
            # OverflowError alongside the usual conversion errors: json.loads()
            # parses an arbitrarily large JSON integer into an unbounded Python
            # int, and float() on one too large to represent RAISES rather than
            # returning inf (see _finite_nonnegative_float's own identical
            # catch). Newly reachable from EVERY id-less candidate row via
            # _synthetic_uncertain_contributor_key (Codex review, PR
            # badMade/all-stock-dca#1171 discussion: "Catch overflow in
            # synthetic identity price parsing") -- uncaught here, one
            # malformed artifact aborted the entire prior-allocation scan
            # instead of reaching the existing fail-closed uncertain-notional
            # handling.
            continue
        if value > 0:
            return value
    return None


# Streams whose runs are scheduled evidence for THEIR OWN slot but still count
# as prior same-day allocation context for a later run. intraday* is matched by
# prefix in _prior_run_is_scheduled since that stream carries a per-slot suffix.
# The afternoon stream is deliberately absent.
_PRIOR_CONTEXT_ELIGIBLE_STREAMS = (
    "morning",
    "midday",
    "market_open",
)

# Recovery-context counterparts of the eligible streams above. Handled on a
# separate branch because, unlike the streams above, being named is NOT
# sufficient: the artifact must also satisfy the scheduled-recovery contract
# before its fills may reduce a later buy. No afternoon entry -- an afternoon
# recovery is the afternoon run's own repair, not prior context for it.
_RECOVERY_PRIOR_CONTEXT_STREAMS = (
    "market_open_recovery",
    "morning_recovery",
    "midday_recovery",
    # The intraday task fires at 11:30/13:30/14:30, so its recovery stream is
    # slot-qualified (e.g. intraday_1430_recovery, the Jul 27 2:32 PM pass).
    "intraday_recovery",
    "intraday_1130_recovery",
    "intraday_1330_recovery",
    "intraday_1430_recovery",
)


def _recovery_root_for(run_dir: Path) -> Path:
    """Delegate to run_classification's canonical recovery-root resolver.

    Imported lazily and by both module paths, matching
    :func:`_is_scheduled_recovery_context`. On ImportError we fall back to
    ``run_dir`` -- the narrower boundary, and moot in practice: the same module
    must already have imported successfully for the recovery branch that calls
    this to have been entered at all.
    """
    try:
        from scripts.run_classification import recovery_root_for
    except ImportError:  # pragma: no cover - exercised via the scripts/ path
        try:
            from run_classification import recovery_root_for  # type: ignore
        except ImportError:
            return run_dir
    return recovery_root_for(run_dir)


def _path_within(path: Path, root: Path) -> bool:
    """True when ``path`` resolves inside ``root`` (or is ``root`` itself).

    Resolved on both sides, so a symlink or ``..`` segment cannot escape.
    """
    try:
        resolved = path.resolve()
        root_key = root.resolve()
    except OSError:
        return False
    return resolved == root_key or root_key in resolved.parents


def _is_scheduled_recovery_context(
    run_state: Dict[str, Any], trading_day: Optional[str] = None
) -> bool:
    """True only for a classification satisfying the scheduled-recovery contract.

    Delegates to ``scripts.run_classification.validate_recovery_classification``,
    the single source of truth, rather than re-deriving the rules here. An
    earlier local copy checked only the origin and boolean flags, so a
    recursively discovered ``midday_recovery`` state could omit or fake
    ``run_type``, ``run_id``, ``state_schema_version``, and the classification
    ``trading_day`` and still have its fills reduce or block the 3:30
    allocation (Codex review: "Enforce the full recovery contract before
    loading fills"). This module already imports from ``scripts/`` on
    neighbouring guard paths (see ``derive_valid_scheduled_evidence`` below),
    so there is no reason to keep a second, drifting implementation.

    Takes the whole RUN_STATE, not just its classification. The state-level
    entry point derives the expected day from the state's own top-level
    ``trading_day`` -- so a state dated for today whose recovery classification
    names a stale or bogus day is rejected rather than loaded (Codex review:
    "Pass the state day into recovery validation") -- and fails closed on a
    top-level ``artifact_contract_failure`` marker, which a classification-only
    check would have accepted as usable prior context (Codex review: "Reject
    artifact-contract failures as recovery context").

    Fails CLOSED on an import error: an artifact that cannot be validated is
    not trusted as prior context.

    See schemas/recovery_run_classification.schema.json for the full contract.
    """
    if not isinstance(run_state, dict):
        return False
    try:
        from scripts.run_classification import is_valid_recovery_context_state
    except ImportError:
        logger.exception(
            "could not import the recovery-contract validator; treating the "
            "recovery artifact as untrusted (it will NOT offset a later buy)"
        )
        return False
    return is_valid_recovery_context_state(run_state, trading_day)


def _prior_run_is_scheduled(run_state: Dict[str, Any]) -> bool:
    """True when a run_state is classified as the scheduled *afternoon* run.

    The scheduled afternoon run is never read as prior allocation context. A
    morning-, midday-, or market-open-stream run (``run_classification.stream``
    in ``{'morning', 'midday', 'market_open'}``), however, IS eligible prior
    context even when its own ``run_origin`` is ``'scheduled'``: the 9:35 AM
    market-open live task, the 10:30 AM morning live task, and the 12:30 PM
    midday live task are scheduled within their own streams but must still
    offset the afternoon top-up (Codex review: "Feed market-open fills into
    later top-up guards"). An ad hoc intraday scheduled-recovery stream
    (``stream`` starting with ``'intraday'`` -- e.g. the Jul 24 2026
    ``intraday_1430`` recovery, see config/scheduled_tasks.json
    canonical_first_buy_and_topup_rule -> intraday_dca_scheduled_recovery_2026_07_24,
    and the recurring 11:30/13:30/14:30 intraday live task 7be82b97) is
    eligible for the same reason: it is scheduled evidence for ITS OWN stream
    but must still offset a later same-day run (Codex review: "Include the
    intraday recovery in later top-up context"). Only afternoon scheduled runs
    are excluded here.

    A recovery stream for one of those earlier slots (``morning_recovery``,
    ``midday_recovery``, ``market_open_recovery`` -- e.g. the Jul 27 2026 12:30
    recovery pass, see config/scheduled_tasks.json ->
    midday_dca_scheduled_recovery_2026_07_27) is eligible for the same reason:
    it moved real capital that day and must offset a later run, while never
    being scheduled evidence for the slot it recovered. It is matched
    explicitly rather than left to the ``run_origin`` fallthrough below -- a
    recovery artifact carries ``run_origin='scheduled_recovery'``, which merely
    happens not to equal ``'scheduled'``, so today it lands on eligible by
    accident. Naming it means a future recovery classification that DOES use
    ``run_origin='scheduled'`` cannot silently flip to ineligible (Codex
    review: "Add the recovery root to watchdog classification"). An
    *afternoon* recovery is deliberately NOT listed: like any afternoon
    scheduled run it must stay invisible to the afternoon guard's own pass.
    """
    classification = run_state.get("run_classification")
    if isinstance(classification, dict):
        stream = classification.get("stream")
        # Dispatch on the ORIGIN first, then the stream. Keying the recovery
        # branch off the stream name alone left every malformed-stream shape
        # unvalidated: a state with run_origin='scheduled_recovery' but a
        # missing or non-string stream fell through to the generic arms, and
        # one naming e.g. 'intraday_bogus' was even accepted as eligible by the
        # startswith('intraday') arm below -- so a corrupted artifact under a
        # recursively scanned root had its fills loaded without ever reaching
        # the canonical recovery validator (Codex review: "Gate every
        # scheduled-recovery origin before loading fills").
        if classification.get("run_origin") == "scheduled_recovery" or (
            isinstance(stream, str) and stream.endswith("_recovery")
        ):
            # A recovery stream is eligible prior context ONLY when it is one of
            # the earlier-slot recovery streams AND the artifact satisfies the
            # scheduled-recovery contract. Naming the stream is not enough: the
            # recovery dirs are dated siblings under the recursively scanned
            # midday/morning roots, and _prior_run_is_valid_manual_recovery_artifact
            # only guards paths containing "manual_recovery", so a corrupted or
            # misclassified file that merely sets stream='midday_recovery' would
            # otherwise be read as prior context and could wrongly reduce or
            # block the 3:30 allocation (Codex review: "Gate recovery streams
            # before loading their fills").
            #
            # Returning True means "treated as a scheduled run", i.e. NOT prior
            # context -- the safe direction, since the artifact is then ignored
            # rather than trusted. An afternoon recovery lands here too: it is
            # absent from the eligible set, so it stays invisible to the
            # afternoon guard's own pass.
            if stream not in _RECOVERY_PRIOR_CONTEXT_STREAMS:
                return True
            # The top-level state day is what load_prior_same_day_allocations
            # already accepted this artifact on, so require the classification
            # to name the SAME day rather than merely a non-blank one.
            return not _is_scheduled_recovery_context(run_state)
        if stream in _PRIOR_CONTEXT_ELIGIBLE_STREAMS:
            # Explicitly named streams are unchanged. A MANUAL artifact under
            # morning/midday/market_open is legitimate prior context and is
            # validated by _prior_run_is_valid_manual_recovery_artifact, so the
            # origin check below must not reach it.
            return False
        if isinstance(stream, str) and stream.startswith("intraday"):
            # Naming the stream is NOT enough, for the same reason it is not
            # enough on the recovery branch above. 'intraday_1430_rerun' starts
            # with 'intraday' but carries run_origin='manual_live_recovery_rerun'
            # -- the shape every manifest in this PR records as rejected by
            # is_top_up_context_state() -- and it ends in '_rerun', so it misses
            # the '_recovery' branch and was admitted here unvalidated. A rerun
            # carrying a submitted-but-never-filled candidate would then load as
            # unresolved prior context and suppress the legitimate final buy
            # (Codex review: "Validate ordinary intraday origins before loading
            # context").
            #
            # Only the ORDINARY scheduled identity is admitted here. Returning
            # True for anything else means "treated as a scheduled run", i.e.
            # ignored -- the safe direction, and it leaves manual and
            # scheduled-recovery artifacts to the validators that own them.
            origin = classification.get("run_origin")
            if classification.get("manual_run") is True:
                return True
            if origin not in (None, "scheduled"):
                return True
            return False
        if classification.get("run_origin") == "scheduled":
            return True
        if (
            classification.get("manual_run") is False
            and classification.get("run_origin") is None
        ):
            return True
    return False


def _prior_run_is_valid_manual_recovery_artifact(
    run_state: Dict[str, Any], run_state_path: Path
) -> bool:
    """True unless a manual_recovery/ artifact fails its required classification.

    ``manual_missed_run_recovery`` (config/morning_dca.json) makes a manual
    missed-run recovery artifact valid prior-allocation / same-day top-up
    context ONLY when it carries ``run_origin='manual'``, ``manual_run=true``,
    ``same_day_top_up_context_only=true``, and ``valid_scheduled_evidence=false``.
    A malformed or misclassified file placed under a ``manual_recovery/``
    directory must not be able to reduce or block a later buy, so such a file
    is excluded here rather than trusted at face value. Artifacts outside a
    ``manual_recovery/`` directory (e.g. manual override reruns, which use a
    distinct classification contract) are unaffected by this check.
    """
    if "manual_recovery" not in run_state_path.parts:
        return True
    classification = run_state.get("run_classification")
    if not isinstance(classification, dict):
        return False
    return (
        classification.get("run_origin") == "manual"
        and classification.get("manual_run") is True
        and classification.get("same_day_top_up_context_only") is True
        and classification.get("valid_scheduled_evidence") is False
    )


def _prior_run_before_boundary(run_state: Dict[str, Any], boundary_et: time) -> bool:
    """True when the run's generated_at (ET) is before the morning/manual boundary.

    Runs with no parseable timestamp are treated as eligible prior context: the guard
    is conservative (more prior context only ever reduces the afternoon buy), so an
    unknown time should not silently disable the offset.
    """
    raw = run_state.get("generated_at")
    if not isinstance(raw, str):
        return True
    try:
        parsed = datetime.fromisoformat(raw)
    except ValueError:
        return True
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=EASTERN)
    return parsed.astimezone(EASTERN).timetz().replace(tzinfo=None) < boundary_et


def _prior_run_timestamp(raw: Optional[str]) -> Optional[datetime]:
    """Parse a run_state ``generated_at`` string into an ET-aware datetime for recency ordering.

    Mirrors :func:`_prior_run_before_boundary`'s parsing (a naive timestamp is
    assumed ET). Returns ``None`` when ``raw`` is missing/unparseable; callers fall
    back to :data:`_TS_FLOOR` (reference-price recency) or to scan/merge order
    (first-allocation base recency, see :func:`_earlier_selected_base`) so an
    untimestamped run loses ties to any timestamped run but still wins later
    scan/merge order against other untimestamped runs.
    """
    if not isinstance(raw, str):
        return None
    try:
        parsed = datetime.fromisoformat(raw)
    except ValueError:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=EASTERN)
    return parsed.astimezone(EASTERN)


def _earlier_selected_base(
    existing_base: Optional[float],
    existing_at: Optional[str],
    alloc_base: Optional[float],
    alloc_at: Optional[str],
) -> tuple[Optional[float], Optional[str]]:
    """Pick the base belonging to the chronologically FIRST of two allocations.

    Used wherever two :class:`PriorSameDayAllocation` values for the same ticker
    (typically from different roots/streams) are merged, so the day's base
    always reflects the true first same-day allocation rather than whichever
    side happened to be merged first (Codex review: "Select the base from the
    chronologically first allocation" -- a later manual override loaded from the
    afternoon root must not out-rank an earlier morning/midday allocation just
    because the afternoon root is scanned first). Falls back to preferring
    ``existing`` when either timestamp is missing/unparseable, matching the
    default used before chronological comparison was possible.
    """
    existing_dt = _prior_run_timestamp(existing_at)
    alloc_dt = _prior_run_timestamp(alloc_at)
    if existing_dt is not None and alloc_dt is not None:
        return (
            (alloc_base, alloc_at)
            if alloc_dt < existing_dt
            else (existing_base, existing_at)
        )
    return (
        (existing_base, existing_at)
        if existing_base is not None
        else (alloc_base, alloc_at)
    )


# Confirmed-fill column aliases. The codebase-standard writers (_CSV_FIELDS,
# the scheduled artifact writers) emit avg_fill_price/quantity_filled, but a
# recovery-context artifact persists the broker's own field names,
# average_fill_price/quantity -- the shape recorded for the Jul 27 2026 12:30
# recovery pass (config/scheduled_tasks.json ->
# midday_dca_scheduled_recovery_2026_07_27.fills). Without these aliases such a
# filled_orders.csv parses to no usable price or quantity, so the ticker either
# drops out of the same-day context entirely or lands in the guard's
# conservative missing_prior_price / $0 manual_review path -- silently
# re-allocating capital already spent that day (Codex review: "Teach the
# final-run loader the recovery fill shape"). scripts/run_classification.py's
# _PRICE_COLS/_QUANTITY_COLS already accept both spellings; these mirror it for
# the core loader. Canonical name first: an artifact carrying both wins on the
# codebase-standard column.
# Broker outcomes in the recovery shape's `state` column that mean the order
# will NEVER fill. Used by _orders_csv_submitted_notionals to drop a row whose
# status still says 'submitted'; a pending/queued/unrecognized state is
# deliberately NOT here, because an order that may yet fill must keep counting
# as prior allocation.
def _load_terminal_order_states() -> frozenset:
    """The canonical broker terminal-state set, from broker_reconciliation.

    Sourced rather than re-declared. This set had been hand-copied here and
    into scripts/run_classification, and both copies silently omitted `voided`
    and `expired` -- so a zero-execution order that could no longer fill was
    still carried as live unknown context, forcing its ticker onto the $0
    manual-review path and suppressing a legitimate top-up (Codex review:
    "Treat voided and expired broker orders as terminal"). Any state the broker
    normalizer learns about now reaches both readers automatically.

    The literal is a fallback for the import failing, not a second source of
    truth; it is kept identical to the canonical set.
    """
    try:
        from scripts.broker_reconciliation import _TERMINAL_ORDER_STATES
    except ImportError:  # pragma: no cover - exercised via the scripts/ path
        try:
            from broker_reconciliation import _TERMINAL_ORDER_STATES  # type: ignore
        except ImportError:
            return frozenset(
                {"cancelled", "canceled", "rejected", "failed", "voided", "expired"}
            )
    return frozenset(_TERMINAL_ORDER_STATES)


_TERMINAL_NON_FILL_STATES = _load_terminal_order_states()

# Every placed/in-flight (non-terminal, non-fill) STATUS a canonical
# submitted_orders.csv row can carry, per scripts.scheduled_artifacts.
# ORDER_ATTEMPT_STATUSES, minus "filled" (owned by _orders_csv_fills) and
# minus "not_submitted_confirmation_required" (means the order never reached
# the broker at all -- scripts/drift_detection.py's
# _NOT_ACTUALLY_SUBMITTED_STATUSES). A market-open/intraday canonical CSV can
# legitimately record status="pending"/"unconfirmed", not just "submitted";
# _orders_csv_submitted_notionals previously required status == "submitted"
# exactly (falling back to the statusless-live path only when the status
# column was entirely EMPTY), so a row with an explicit "pending"/
# "unconfirmed" status was silently dropped, reconstructing that attempt as
# $0 exposure and letting the same ticker be bought again while the real
# order was still outstanding (Codex review: "Reserve pending orders loaded
# from the canonical CSV").
# "potentially_submitted" joins the set for the same reason
# _PRIOR_ALLOCATION_STATUSES above does: an unresolved potentially-submitted
# order is conservatively reserved at its planned amount until reconciliation
# proves whether capital moved (PR #538).
_UNRESOLVED_ORDER_ATTEMPT_STATUSES = frozenset(
    {"submitted", "pending", "unconfirmed", "potentially_submitted"}
)

# Submitted-amount aliases, canonical first. `amount_usd` is the broker-native
# recovery spelling; _orders_csv_fills already reads it. `submitted_amount_usd`
# is scripts.scheduled_artifacts.SUBMITTED_ORDERS_FIELDS's canonical column --
# the market-open/intraday streams' submitted_orders.csv (their only
# same-day evidence; they have no in-repo executor writing buy_candidates)
# uses this name, and without it here a valid submitted row from that file
# contributed $0 (Codex review: "Read canonical CSVs during same-day cap
# seeding").
_SUBMITTED_NOTIONAL_COLS = ("notional_usd", "amount_usd", "submitted_amount_usd")
_FILL_PRICE_COLS = ("avg_fill_price", "average_fill_price")
# EXECUTED-quantity columns, in precedence order. `quantity` is deliberately
# absent: in the broker-native shape it is the REQUESTED size and
# `cumulative_quantity` is what actually filled -- exactly the distinction
# scripts/broker_reconciliation.py._normalize_order() already draws, including
# its warning that an `x or y` fallthrough misreads a 0-filled order as fully
# executed. Treating `quantity` as executed meant a canceled zero-fill row
# (`quantity=1`, `cumulative_quantity=0`) reported executed capital and its full
# request was retained as prior allocation, suppressing a legitimate later
# top-up; partially filled rows were overstated the same way (Codex review:
# "Prefer cumulative quantity over requested quantity").
_EXECUTED_QUANTITY_COLS = ("quantity_filled", "cumulative_quantity")
# `quantity` remains a LAST-RESORT alias, used only when neither executed column
# is present at all. That is the recovery artifact shape recorded in
# config/scheduled_tasks.json -> recovery_context_run_outcomes, whose `quantity`
# IS the filled amount because it carries no cumulative_quantity column.
_FILL_QUANTITY_COLS = (*_EXECUTED_QUANTITY_COLS, "quantity")


def _first_present(row: Mapping[str, Any], cols: Sequence[str]) -> Any:
    """First non-blank value among ``cols``, else None.

    Blank ("", "-") and missing columns are skipped rather than returned, so a
    CSV that carries BOTH spellings with the canonical one left empty still
    resolves via the alias instead of yielding a blank that the caller would
    read as "no value".
    """
    for col in cols:
        value = row.get(col)
        if value not in (None, "", "-"):
            return value
    return None


def _has_executed_quantity(row: Mapping[str, object]) -> bool:
    """True when an orders-CSV row records a positive executed quantity.

    The test that decides whether a non-``filled`` row still represents deployed
    capital. A ``partially_filled`` row, or a ``canceled`` one that executed some
    quantity before it ended, carries real shares; only a row with no executed
    quantity can be discarded. math.isfinite rejects a corrupted 'inf'/'nan' cell
    so it cannot pass as executed size.

    An EXPLICIT ZERO in an executed column is authoritative and stops the search
    -- it says the order filled nothing, which is the whole answer. Falling
    through to the requested ``quantity`` on a 0 would report a canceled
    zero-fill row as executed capital, the exact trap
    ``broker_reconciliation._normalize_order()`` documents.
    """
    for col in _EXECUTED_QUANTITY_COLS:
        value = row.get(col)
        if value in (None, "", "-"):
            continue
        try:
            executed = float(cast(Any, value))
        except (TypeError, ValueError):
            return False
        return math.isfinite(executed) and executed > 0
    raw = _first_present(row, _FILL_QUANTITY_COLS)
    if raw in (None, "", "-"):
        return False
    try:
        qty = float(cast(Any, raw))
    except (TypeError, ValueError):
        return False
    return math.isfinite(qty) and qty > 0


def _executed_quantity_is_explicit_zero(row: Mapping[str, object]) -> bool:
    """True only when an executed column states a definitive numeric ZERO.

    Stricter than ``not _has_executed_quantity(row)``, which also returns true
    for an absent, blank, non-finite, or unparsable value. Those say "unknown",
    not "nothing filled" -- and a caller that REMOVES prior allocation must not
    read the first as the second: `cumulative_quantity='oops'` on a canceled row
    does not establish that the order failed to execute, so treating it as a
    zero fill drops a candidate that may really have partially filled and lets
    the later run buy the full amount again (Codex review: "Require an explicit
    zero before excluding terminal candidates").
    """
    for col in _EXECUTED_QUANTITY_COLS:
        value = row.get(col)
        if value in (None, "", "-"):
            continue
        try:
            executed = float(cast(Any, value))
        except (TypeError, ValueError):
            return False
        return math.isfinite(executed) and executed == 0
    raw = _first_present(row, _FILL_QUANTITY_COLS)
    if raw in (None, "", "-"):
        # No quantity column at all. The row says nothing about execution, so it
        # is unresolved rather than a zero fill.
        return False
    try:
        qty = float(raw)
    except (TypeError, ValueError):
        return False
    return math.isfinite(qty) and qty == 0


def _orders_csv_fills(
    run_dir: Path,
    *,
    orders_csv_file: Optional[Path] = None,
    skip_sink: Optional[List[Path]] = None,
    preserve_order_rows: bool = False,
) -> Dict[str, Dict[str, Any]]:
    """Return {order_id, avg_fill_price, quantity_filled} for filled CSV rows only.

    Used to reconcile a prior run's ``buy_candidates`` (whose status is fixed at
    order-submission time) against what the broker actually confirmed: a candidate
    recorded ``status='submitted'`` in run_state.json only means an order_id was
    obtained, not that it filled. A submission that never filled (execution gap,
    reject, cancel) must not count as prior-allocation capital.

    Pass ``orders_csv_file`` to read a specific CSV (e.g. the path recorded in
    ``run_state.artifacts.orders_csv_path``) instead of looking for a sibling
    ``orders.csv``; ``run_and_report`` writes files with custom names like
    ``dca_<label>_<day>_<stamp>_orders.csv`` that ``run_dir / "orders.csv"`` won't find.

    Pass ``skip_sink`` when ``orders_csv_file`` names a CSV a caller already
    knows exists (e.g. just confirmed via ``.exists()``) so a read/parse
    failure caught mid-rewrite still gets recorded -- otherwise it is
    indistinguishable from a genuinely empty (zero-fills) day (Codex review:
    "Include referenced CSV failures in scan completeness").

    ``preserve_order_rows`` is for order-level reporting consumers.  The
    default ticker-keyed result intentionally aggregates the same-day guard's
    view to one fill per ticker, but a historical ledger must retain distinct
    retry orders for the same ticker.  In that mode each result receives an
    internal unique key and carries its original ticker in ``_ticker``.

    When no explicit file is given the sibling ``orders.csv`` is used, falling back
    to ``filled_orders.csv`` -- the confirmed-fill record manual override reruns
    write under ``.../manual_reruns/`` -- so a manual override fill still counts as
    prior-allocation context for the same-day top-up guard. Manual fill files may
    use the documented ``amount_usd``/``avg_fill_price`` shape without orders.csv
    fields like ``status`` or ``quantity_filled``.
    """
    fills: Dict[str, Dict[str, Any]] = {}
    if orders_csv_file is not None:
        orders_csv = orders_csv_file
    else:
        # Prefer filled_orders.csv (confirmed-fill record with actual fill
        # price/quantity) over orders.csv (submitted stub with blank fill
        # fields), so a partial fill or cancellation is seen correctly by the
        # afternoon top-up guard. Fall back to orders.csv when no confirmed
        # fill record exists.
        filled_csv = run_dir / "filled_orders.csv"
        orders_csv = filled_csv if filled_csv.exists() else run_dir / "orders.csv"
    if not orders_csv.exists():
        return fills
    rows = []
    fieldnames = None
    had_csv_error = False
    try:
        with orders_csv.open(newline="", encoding="utf-8") as handle:
            reader = csv.DictReader(handle)
            fieldnames = reader.fieldnames  # reads the header row
            if fieldnames is not None:
                try:
                    for row in reader:
                        rows.append(row)
                except csv.Error:
                    had_csv_error = True
                    logger.exception(
                        "failed to parse %s for same-day fill context; prior allocations from "
                        "this file may be undercounted -- reconcile against broker orders",
                        orders_csv,
                    )
                    if skip_sink is not None:
                        skip_sink.append(orders_csv)
    except (OSError, UnicodeDecodeError):
        logger.exception(
            "failed to parse %s for same-day fill context; prior allocations from "
            "this file may be undercounted -- reconcile against broker orders",
            orders_csv,
        )
        if skip_sink is not None:
            skip_sink.append(orders_csv)
        return fills
    except Exception:
        if skip_sink is not None:
            skip_sink.append(orders_csv)
        return fills
    if fieldnames is None:
        # write_execution_csv() unconditionally calls writer.writeheader(),
        # so a COMPLETE write always has a header row even on a genuine
        # zero-orders day (rows == [] with a real header is a legitimate
        # terminal state, not an error). fieldnames is None only when the
        # file has no header line at all -- observed in the instant right
        # after its truncating open(path, "w") but before even the header
        # was flushed, which `if rows` alone can't distinguish from that
        # legitimate empty day (Codex review: "Treat empty CSV snapshots as
        # incomplete").
        if skip_sink is not None:
            skip_sink.append(orders_csv)
        return fills
    if not had_csv_error and rows and any(value is None for value in rows[-1].values()):
        # The final row has FEWER fields than the header -- csv.DictReader
        # fills any missing trailing columns with None (its `restval`)
        # rather than raising, so a file observed mid-write with its last
        # record only partially flushed (e.g. "AAPL,filled" with the
        # price/quantity/order_id columns not yet written) never reaches the
        # except-clause skip_sink signal above (Codex review: "Detect
        # silently truncated CSV reads"). Drop the untrustworthy tail row
        # but keep whatever was already fully flushed before it.
        if skip_sink is not None:
            skip_sink.append(orders_csv)
        rows = rows[:-1]
    for row_number, row in enumerate(rows):
        ticker = row.get("ticker")
        if not ticker:
            continue
        status = (row.get("status") or "").lower()
        # The broker-native recovery shape records the outcome in `state`, not
        # `status`. Without this, a recovery filled_orders.csv row with
        # state='rejected'/'canceled' hit the statusless is_manual_filled_orders
        # heuristic below and was counted as deployed capital -- amount and
        # reference price included -- which reduces or entirely suppresses that
        # ticker's 3:30 allocation for an order that never filled (Codex review:
        # "Honor the recovery row state before counting fills"). When the column
        # is present it is authoritative: anything other than 'filled',
        # including a blank cell, is not a confirmed fill.
        # EXECUTED QUANTITY decides, not the state name. Requiring state=='filled'
        # discarded a 'partially_filled' row, and a 'canceled' row that executed
        # some quantity before it ended -- both of which are real deployed
        # capital. Dropping them made the loader report no prior buy and let the
        # later run purchase the full amount again, the expensive direction and
        # exactly what this guard exists to prevent.
        # scripts/broker_reconciliation.py already treats partially_filled as
        # live exposure and a terminal order with executed dollars as prior
        # exposure, for the same reason (Codex review: "Preserve executed partial
        # fills in recovery CSVs").
        row_state = (row.get("state") or "").strip().lower() if "state" in row else None
        # `state` is the BROKER's answer; `status` is what we asked for. When the
        # broker says filled, that settles it -- a row carrying
        # status='submitted' with state='filled' was being dropped here by the
        # status gate below, then kept by _orders_csv_submitted_notionals as an
        # unknown-price notional, forcing the ticker onto the conservative $0
        # manual-review path despite having a real fill price and quantity
        # (Codex review: "Let the broker state confirm filled recovery rows").
        state_confirms_fill = row_state == "filled"
        partial_execution = False
        if row_state is not None and not state_confirms_fill:
            if not _has_executed_quantity(row):
                continue
            partial_execution = True
        is_manual_filled_orders = (
            orders_csv.name == "filled_orders.csv" or "amount_usd" in row
        ) and not status
        # partial_execution passes too. Last round taught this gate about
        # state='filled' but not about a row still carrying status='submitted'
        # while the broker reports partially_filled (or canceled after executing
        # some quantity). Such a row was dropped here while
        # _orders_csv_submitted_notionals kept its FULL requested notional, so a
        # $10 request with $2 executed counted as $10 deployed and suppressed
        # the remaining $8 top-up. Letting it through means the executed
        # price * quantity recompute below wins instead (Codex review: "Let
        # submitted partial executions reach the fill reader").
        if (
            status != "filled"
            and not state_confirms_fill
            and not partial_execution
            and not is_manual_filled_orders
        ):
            continue
        raw_price = _first_present(row, _FILL_PRICE_COLS)
        try:
            price = float(raw_price) if raw_price not in (None, "", "-") else None
        except (TypeError, ValueError):
            price = None
        # `> 0` alone excludes NaN (NaN > 0 is False) but NOT Infinity
        # (float('inf') > 0 is True) -- math.isfinite() also rejects a
        # corrupted/malformed CSV value of "inf"/"Infinity" so it can
        # never poison the same-day top-up guard with an unbounded
        # reference price or prior allocation (Gemini review on PR #31).
        price_valid = price is not None and math.isfinite(price) and price > 0
        raw_qty = _first_present(row, _FILL_QUANTITY_COLS)
        try:
            qty = float(raw_qty) if raw_qty not in (None, "", "-") else None
        except (TypeError, ValueError):
            qty = None
        qty_valid = qty is not None and math.isfinite(qty) and qty > 0
        # Canonical alias list, not a bare "amount_usd" lookup: a filled row
        # in the market-open/intraday streams' submitted_orders.csv records
        # the dollar amount as submitted_amount_usd, not amount_usd, and a
        # hardcoded lookup here silently read it as unknown (Codex review:
        # "Read canonical CSVs during same-day cap seeding").
        raw_amount = _first_present(row, _SUBMITTED_NOTIONAL_COLS)
        try:
            amount = float(raw_amount) if raw_amount not in (None, "", "-") else None
        except (TypeError, ValueError):
            amount = None
        amount_valid = amount is not None and math.isfinite(amount) and amount > 0
        if partial_execution and price is not None and qty is not None and price_valid and qty_valid:
            # For a row that did NOT reach state='filled', amount_usd is the
            # amount that was REQUESTED; only price * executed-quantity is the
            # cash that actually moved. Using the recorded amount would overstate
            # prior allocation and suppress a legitimate top-up. When the two
            # agree (amount_usd already being executed cash) this changes
            # nothing.
            amount = price * qty
            amount_valid = math.isfinite(amount) and amount > 0
        if not price_valid and not amount_valid:
            # No usable price AND no usable amount_usd -- genuinely no
            # capital-movement information to preserve for this row.
            continue
        fill_key = f"{ticker}#{row_number}" if preserve_order_rows else ticker
        fills[fill_key] = {
            **({"_ticker": ticker} if preserve_order_rows else {}),
            "order_id": row.get("order_id"),
            # A PARTIAL execution's notional is real and must count, but its
            # price is not a settled reference: the unexecuted remainder may
            # still reprice or be cancelled. Callers that resolve a reference
            # price check this flag; _read_csv_rows draws the same line with
            # _partial_execution, and the two readers disagreed until now
            # (Codex review: "Keep partial executions from confirming a
            # reference price").
            "_partial_execution": partial_execution,
            # Preserve amount-only rows (amount_usd present, price missing/
            # invalid) as an unknown-price allocation instead of dropping
            # them outright -- the confirmed CSV amount must not be
            # silently discarded in favor of a stale planned amount.
            "avg_fill_price": price if price_valid else None,
            "quantity_filled": qty if qty_valid else None,
            "amount_usd": amount if amount_valid else None,
        }
    return fills


def _fill_rank(fill: Mapping[str, Any]) -> int:
    """How authoritative a fill entry is about an order's outcome. Higher wins.

    Mirrors ``scripts.run_classification._dedupe_rank``: a CONFIRMED full fill
    outranks a partial execution. Used when the same ticker appears in more than
    one of a recovery's CSVs -- a stale ``partially_filled`` snapshot beside
    run_state.json versus the explicitly recorded CSV's final ``filled`` state.
    Keeping whichever was read first preserved the partial's notional and its
    unresolved reference price, forcing an unnecessary manual-review stop for an
    order that had since completed (Codex review: "Reconcile overlapping ticker
    fills instead of keeping the first").
    """
    return 0 if fill.get("_partial_execution") else 1


def _fill_order_id(fill: Mapping[str, Any]) -> str:
    """The fill's order_id, normalized; empty string when it carries none."""
    oid = fill.get("order_id")
    oid = oid.strip() if isinstance(oid, str) else ""
    return "" if oid == "-" else oid


def _combined_fill(a: Dict[str, Any], b: Dict[str, Any]) -> Dict[str, Any]:
    """Aggregate two DISTINCT orders for one ticker into a single entry.

    Amounts and quantities add, because both orders really moved capital. The
    reference price becomes the quantity-weighted average of the two fills --
    the cost basis a later top-up should be measured against. When either side
    lacks a usable price or quantity the aggregate price is unknowable, so it
    is left None and the guard routes to its conservative manual-review path
    rather than comparing against a price that was never paid.
    """

    def _num(value):
        try:
            out = float(cast(Any, value))
        except (TypeError, ValueError):
            return None
        return out if math.isfinite(out) else None

    amounts = [_num(a.get("amount_usd")), _num(b.get("amount_usd"))]
    qtys = [_num(a.get("quantity_filled")), _num(b.get("quantity_filled"))]
    prices = [_num(a.get("avg_fill_price")), _num(b.get("avg_fill_price"))]

    amount = sum(x for x in amounts if x) or None
    quantity = sum(x for x in qtys if x) or None
    price = None
    p0, p1 = prices[0], prices[1]
    q0, q1 = qtys[0], qtys[1]
    if (
        p0 is not None
        and p0 > 0
        and p1 is not None
        and p1 > 0
        and q0 is not None
        and q0 > 0
        and q1 is not None
        and q1 > 0
    ):
        price = (p0 * q0 + p1 * q1) / (q0 + q1)
    return {
        # No single order_id describes the pair; the aggregate is what matters
        # downstream, and a wrong single ID would be worse than none.
        "order_id": None,
        # Unresolved if EITHER leg is, since the combined remainder is live.
        "_partial_execution": bool(
            a.get("_partial_execution") or b.get("_partial_execution")
        ),
        "avg_fill_price": price,
        "quantity_filled": quantity,
        "amount_usd": amount,
    }


def _merge_fill(
    fills: Dict[str, Dict[str, Any]], ticker: str, fill: Dict[str, Any]
) -> None:
    """Reconcile a fill into ``fills``, keyed by ORDER, not merely by ticker.

    Three cases, and conflating them is what went wrong before:

    * **Same order** seen again in another sibling CSV -- replace when the new
      snapshot is strictly more authoritative (a completed fill over a stale
      partial), otherwise keep the incumbent. Never sums: the same order in two
      files is one order, and adding would double-count the capital this guard
      exists to count once.
    * **A distinct order** for a ticker already present -- ADD it. Keeping only
      the first understated deployed capital and let the candidate loop apply
      one order's fill to every candidate for that ticker, permitting an
      excessive top-up (Codex review: "Merge recovery fills by order ID before
      aggregating tickers").
    * **Unidentifiable** -- either side missing an order_id. Fall back to
      rank-replacement rather than adding, since two rows that cannot be told
      apart may well be the same order, and double-counting is the direction
      that spends real money twice.
    """
    existing = fills.get(ticker)
    if existing is None:
        fills[ticker] = fill
        return
    new_oid, old_oid = _fill_order_id(fill), _fill_order_id(existing)
    if new_oid and old_oid and new_oid != old_oid:
        fills[ticker] = _combined_fill(existing, fill)
        return
    if _fill_rank(fill) > _fill_rank(existing):
        fills[ticker] = fill


def _orders_csv_terminal_non_fills(
    orders_csv: Path,
) -> tuple[set, set]:
    """(order_ids, tickers) the CSV reports as TERMINALLY not filled.

    A row whose ``state`` is rejected/canceled/failed AND that executed no
    quantity is authoritative evidence that no capital moved for that order.
    Rows that executed something before ending are excluded -- a
    cancelled-after-partial-fill is real deployed capital.

    The tickers set is a fallback for rows carrying no usable ``order_id``; a
    caller must only apply it when nothing else claims the ticker, since a
    ticker can have both a rejected order and a separate real fill.
    """
    order_ids: set = set()
    tickers: set = set()
    if not orders_csv.exists():
        return order_ids, tickers
    try:
        with open(orders_csv, newline="", encoding="utf-8") as handle:
            for row in csv.DictReader(handle):
                # csv.DictReader fills omitted TRAILING cells with None rather
                # than raising, so a row observed mid-write can look like a
                # zero-execution terminal outcome purely because its
                # cumulative_quantity has not been flushed yet -- and this
                # helper would then delete a candidate whose order really did
                # partially fill, letting the later run buy its full amount.
                # _orders_csv_fills drops such a tail row; here ANY row with a
                # missing field is refused, not just the last one, because this
                # collector only ever REMOVES prior allocation and so must be
                # strictly more conservative (Codex review: "Reject truncated
                # terminal rows before excluding candidates").
                if any(value is None for value in row.values()):
                    continue
                state = (row.get("state") or "").strip().lower()
                if state not in _TERMINAL_NON_FILL_STATES:
                    continue
                # An EXPLICIT numeric zero is required, not merely the absence
                # of a positive quantity. A malformed or missing cell means the
                # artifact does not establish whether the order executed, and
                # this collector only ever REMOVES prior allocation -- so an
                # unresolved row must stay unresolved rather than be read as a
                # definitive zero fill.
                if not _executed_quantity_is_explicit_zero(row):
                    continue
                oid = (row.get("order_id") or "").strip()
                if oid and oid != "-":
                    order_ids.add(oid)
                else:
                    ticker = (row.get("ticker") or "").strip().upper()
                    if ticker:
                        tickers.add(ticker)
    except (OSError, csv.Error, UnicodeDecodeError):
        # Unreadable means "no terminal evidence", never "everything is
        # terminal": this set only ever REMOVES prior allocation, so failing to
        # read it must not be able to drop a real prior buy.
        return set(), set()
    return order_ids, tickers


def _orders_csv_submitted_notionals(
    orders_csv: Path, *, skip_sink: Optional[List[Path]] = None
) -> Dict[str, float]:
    """Map ticker -> notional_usd for submitted-but-not-filled rows in an orders CSV.

    Used in the full-report fallback to count submitted-but-unconfirmed orders as
    prior allocation with an unknown reference price (the conservative path), matching
    what the buy_candidates path does for status='submitted' candidates with no fill.

    Pass ``skip_sink`` when ``orders_csv`` is a file the caller already knows
    exists, so a read/parse failure caught mid-rewrite is recorded rather
    than silently indistinguishable from a genuinely empty CSV (Codex
    review: "Include referenced CSV failures in scan completeness").
    """
    notionals: Dict[str, float] = {}
    if not orders_csv.exists():
        return notionals
    rows = []
    fieldnames = None
    had_csv_error = False
    try:
        with orders_csv.open(newline="", encoding="utf-8") as handle:
            reader = csv.DictReader(handle)
            fieldnames = reader.fieldnames  # reads the header row
            if fieldnames is not None:
                try:
                    for row in reader:
                        rows.append(row)
                except csv.Error:
                    had_csv_error = True
                    logger.exception(
                        "failed to parse %s for submitted-order context; prior allocations "
                        "from this file may be undercounted -- reconcile against broker orders",
                        orders_csv,
                    )
                    if skip_sink is not None:
                        skip_sink.append(orders_csv)
    except (OSError, UnicodeDecodeError):
        logger.exception(
            "failed to parse %s for submitted-order context; prior allocations "
            "from this file may be undercounted -- reconcile against broker orders",
            orders_csv,
        )
        if skip_sink is not None:
            skip_sink.append(orders_csv)
        return notionals
    except Exception:
        if skip_sink is not None:
            skip_sink.append(orders_csv)
        return notionals
    if fieldnames is None:
        # See the matching check in _orders_csv_fills: a file with no
        # header line at all was observed before even the header was
        # flushed, distinct from a header-only file (a legitimate
        # zero-orders day) that `if rows` alone can't tell apart (Codex
        # review: "Treat empty CSV snapshots as incomplete").
        if skip_sink is not None:
            skip_sink.append(orders_csv)
        return notionals
    if not had_csv_error and rows and any(value is None for value in rows[-1].values()):
        # See the matching check in _orders_csv_fills: a truncated final row
        # (fewer fields than the header) never raises, so this is the only
        # way to catch a file observed mid-write (Codex review: "Detect
        # silently truncated CSV reads").
        if skip_sink is not None:
            skip_sink.append(orders_csv)
        rows = rows[:-1]
    for row in rows:
        ticker = row.get("ticker")
        if not ticker:
            continue
        row_status = (row.get("status") or "").strip().lower()
        row_state_raw = (
            (row.get("state") or "").strip().lower() if "state" in row else None
        )
        # A broker-native recovery CSV may omit `status` entirely and report the
        # outcome only in `state` -- a shape _orders_csv_fills already treats as
        # authoritative. Requiring status=='submitted' dropped such a row even
        # when its state was still LIVE ('pending', 'queued'), so a candidate-
        # less recovery contributed no prior allocation at all and a later run
        # could submit the full amount while that order was outstanding (Codex
        # review: "Retain statusless nonterminal recovery rows").
        #
        # 'filled' is excluded because _orders_csv_fills owns that row and
        # reports a real price; this reader only carries UNRESOLVED context.
        statusless_live = (
            not row_status
            and row_state_raw is not None
            and row_state_raw != "filled"
            and row_state_raw not in _TERMINAL_NON_FILL_STATES
        )
        if row_status not in _UNRESOLVED_ORDER_ATTEMPT_STATUSES and not statusless_live:
            continue
        # The recovery shape's authoritative `state` column, applied with the
        # opposite polarity to _orders_csv_fills. A row can carry BOTH
        # status='submitted' (what we asked the broker for) and a broker outcome
        # in `state`; the broker's outcome outranks our request. Without this a
        # state='rejected' row still contributed its notional as unknown-price
        # prior allocation, pushing that ticker onto the conservative $0
        # manual-review path for an order known not to have filled (Codex
        # review: "Apply the recovery state gate to submitted notionals").
        #
        # Only TERMINAL NON-FILL states are dropped -- deliberately not
        # `state != 'filled'`. This function's whole job is to count a submitted
        # order whose outcome is not yet known, so discarding a pending/queued
        # row would UNDERCOUNT prior allocation and risk re-buying a ticker
        # whose order is still live. Fail-closed here means keeping the
        # unknown, not dropping it.
        #
        # And a terminal row that EXECUTED some quantity before ending is kept
        # too: cancelled-after-partial-fill is real deployed capital, which
        # scripts/broker_reconciliation.py already counts as prior exposure for
        # exactly this reason (Codex review: "Preserve executed partial fills in
        # recovery CSVs").
        # An EXPLICIT numeric zero is required to drop the row. `not
        # _has_executed_quantity(row)` also matches a missing column and an
        # unparsable cell, and those say UNKNOWN, not "nothing filled" --
        # dropping an unresolved terminal row removes its notional entirely, so
        # a later run sees no prior allocation and can buy the full amount again
        # (Codex review: "Require explicit zero before dropping submitted
        # notionals"). My earlier note claiming this reader RETAINED such a row
        # was wrong: this gate drops it.
        if (
            row.get("state") or ""
        ).strip().lower() in _TERMINAL_NON_FILL_STATES and _executed_quantity_is_explicit_zero(
            row
        ):
            continue
        # The broker-native recovery shape records the amount as `amount_usd`,
        # which _orders_csv_fills already accepts. Reading only `notional_usd`
        # meant a statusless live recovery row passed the gate above and then
        # contributed NOTHING, so its ticker carried no prior allocation and a
        # later run could submit the full amount while that order was still
        # outstanding (Codex review: "Read amount_usd for unresolved recovery
        # submissions"). Canonical column first, so an artifact carrying both
        # wins on the codebase-standard name.
        raw = _first_present(row, _SUBMITTED_NOTIONAL_COLS)
        try:
            notional = float(raw) if raw not in (None, "", "-") else None
        except (TypeError, ValueError):
            notional = None
        if notional and notional > 0:
            notionals[ticker] = notionals.get(ticker, 0.0) + notional
    return notionals


def _orders_csv_attempt_counts(
    orders_csv: Path,
    *,
    skip_sink: Optional[List[Path]] = None,
) -> Dict[str, int]:
    """Map ticker -> count of qualifying broker-facing attempt rows in an orders CSV.

    Used by the no-embedded-candidates CSV-only reconstruction path in
    ``load_prior_same_day_allocations`` to count ONE attempt per CSV ROW,
    not one per ticker after ``_orders_csv_fills``/
    ``_orders_csv_submitted_notionals`` collapse multiple distinct orders
    for the same ticker into a single aggregated fill/notional record (and
    ``_orders_csv_fills`` itself already sums same-ticker distinct orders'
    dollar amounts together -- see ``_merge_fill``). Counting attempts
    AFTER that collapse under-counted whenever a ticker had more than one
    real order this run, and a terminal rejected/canceled-only row (which
    never enters either reader's returned dict at all, since neither
    reader's job is to surface zero-capital rows) was never counted as an
    attempt either (Codex review: "Count each CSV order attempt before
    aggregating by ticker").

    Counts every row with a ticker present, except:
    - a dry-run order_id (no real capital/attempt at risk), and
    - ``not_submitted_confirmation_required`` (status or state) -- this
      status means the order was blocked pending a separate
      pre-authorization step and never reached the broker at all (see
      ``scripts/drift_detection.py``'s ``_NOT_ACTUALLY_SUBMITTED_STATUSES``),
      the same exclusion ``ORDER_ATTEMPT_STATUSES``-based counting applies
      elsewhere in this module.

    A missing file returns an empty mapping (0 attempts for every ticker)
    rather than raising. A headerless file or a truncated final row (short
    on trailing columns -- csv.DictReader fills those with ``None`` via its
    ``restval`` instead of raising) is recorded in ``skip_sink`` and the
    untrustworthy tail row is dropped, mirroring ``_orders_csv_fills``'s
    truncated-read detection so a mid-write CSV observed here doesn't
    silently under-count attempts the same way it must not silently
    under-count dollars (Codex review: "Detect silently truncated CSV
    reads").
    """
    counts: Dict[str, int] = {}
    if not orders_csv.exists():
        return counts
    rows: List[Dict[str, Any]] = []
    fieldnames = None
    had_csv_error = False
    try:
        with orders_csv.open(newline="", encoding="utf-8") as handle:
            reader = csv.DictReader(handle)
            fieldnames = reader.fieldnames
            if fieldnames is not None:
                try:
                    for row in reader:
                        rows.append(row)
                except csv.Error:
                    had_csv_error = True
                    if skip_sink is not None:
                        skip_sink.append(orders_csv)
    except (OSError, UnicodeDecodeError):
        if skip_sink is not None:
            skip_sink.append(orders_csv)
        return counts
    except Exception:
        if skip_sink is not None:
            skip_sink.append(orders_csv)
        return counts
    if fieldnames is None:
        if skip_sink is not None:
            skip_sink.append(orders_csv)
        return counts
    if not had_csv_error and rows and any(value is None for value in rows[-1].values()):
        if skip_sink is not None:
            skip_sink.append(orders_csv)
        rows = rows[:-1]
    for row in rows:
        ticker = row.get("ticker")
        if not ticker:
            continue
        order_id = (row.get("order_id") or "").strip()
        if order_id.startswith("DRY-RUN"):
            continue
        status = (row.get("status") or "").strip().lower()
        row_state = (
            (row.get("state") or "").strip().lower() if "state" in row else ""
        )
        if (
            status == "not_submitted_confirmation_required"
            or row_state == "not_submitted_confirmation_required"
        ):
            continue
        counts[ticker] = counts.get(ticker, 0) + 1
    return counts


def _mtime_matches_trading_day(path: Path, trading_day: date) -> bool:
    """True if ``path``'s last-modified time falls ON OR AFTER ``trading_day`` (Eastern).

    Used to scope ``skip_sink`` to PLAUSIBLY relevant artifacts: a
    ``run_state*.json`` candidate that fails to read/parse can't have its own
    ``trading_day`` field inspected (that's exactly what failed), so a
    permanently corrupted historical artifact from months or years ago --
    accumulated anywhere under a recursively (``rglob``) scanned root -- would
    otherwise poison every future scan's skip_sink forever, permanently
    disabling the bounded-reload recovery this signal exists to enable (Codex
    review: "Exclude historical parse failures from reload completeness").
    mtime is an imperfect but universal, cheap proxy: a same-day artifact still
    being flushed necessarily has a same-day mtime, while old corrupted files
    do not.

    NOT a strict equality check: an earlier-weekday artifact (``trading_day``
    Monday) being backfilled or repaired on a LATER day (mtime Tuesday, when
    ``run_dca._compute_earlier_week_cross_stream_notional`` scans Monday from
    a Tuesday run) is exactly as unverifiable as a same-day race, but its
    mtime can never equal Monday -- an exact-equality check silently dropped
    that failure from skip_sink, understating real earlier-week spend against
    the shared weekly cap (Codex review: "Fail closed on later-modified
    prior-day artifacts"). A file can never legitimately be modified BEFORE
    the trading day it claims to represent, so "on or after" still excludes
    genuinely stale historical garbage (whose mtime predates trading_day)
    while also covering a later-day rewrite of an earlier day's artifact. If
    the path can't even be stat'd, err toward still treating it as a possible
    failure rather than silently dropping the signal.
    """
    try:
        mtime = path.stat().st_mtime
    except OSError:
        return True
    return datetime.fromtimestamp(mtime, tz=EASTERN).date() >= trading_day


def _resolve_recorded_orders_csv(
    run_state: Dict[str, Any],
    run_state_path: Path,
    *,
    skip_sink: Optional[List[Path]] = None,
) -> Optional[Path]:
    """Resolve ``run_state.artifacts.orders_csv_path`` to a concrete path, or None.

    Shared by both readers of the recorded CSV so they cannot disagree about
    which file a recovery artifact points at. ``run_and_report`` writes custom
    names like ``dca_<label>_<day>_<stamp>_orders.csv``, which neither
    ``run_dir / "orders.csv"`` nor ``filled_orders.csv`` will find.

    A RECOVERY artifact's recorded path must resolve inside its own run root.
    A copied one can carry a stale ABSOLUTE path still naming the run it was
    copied from -- following it verbatim would load an unrelated CSV's fills as
    this pass's recovery fills and reduce or block the 3:30 buy (Codex review:
    "Constrain recovery fill paths to their run root"). Mirrors the containment
    ``scripts.run_classification._referenced_orders_csvs_within`` already
    applies for the watchdog collector.

    Contained against the enclosing RECOVERY ROOT, not the run_state's own
    directory: a recovery run may write ``artifacts/run_state.json`` beside a
    root-level ``filled_orders.csv`` and record it as ``../filled_orders.csv``,
    which is in-root and legitimate (Codex review: "Resolve recovery CSVs
    against the artifact root").

    Containment is scoped to recovery states: a manual full-report run
    legitimately records a custom-named CSV that ``run_and_report`` may have
    written elsewhere, and that path has always been followed.
    """
    artifacts_block = run_state.get("artifacts")
    if not isinstance(artifacts_block, dict):
        return None
    orders_csv_path = artifacts_block.get("orders_csv_path")
    if orders_csv_path is None:
        return None
    # The recovery classification schema does not constrain the nested
    # artifacts block, so this value can be any JSON shape. Path([]) raises
    # TypeError, and that exception escaped load_prior_same_day_allocations()
    # and aborted the WHOLE same-day context scan -- taking the afternoon run
    # with it -- rather than treating one artifact as unreadable (Codex review:
    # "Validate recorded CSV path types before constructing Path"). A malformed
    # value is a broken artifact, not an absent one, so it goes to skip_sink:
    # the run's fills are exactly as unverifiable as an unparseable
    # run_state.json, and the scan must not report itself complete.
    if not isinstance(orders_csv_path, (str, os.PathLike)):
        logger.warning(
            "run_state %s records a non-path orders_csv_path (%r); treating the "
            "artifact as unreadable",
            run_state_path,
            orders_csv_path,
        )
        if skip_sink is not None:
            skip_sink.append(run_state_path)
        return None
    if isinstance(orders_csv_path, str) and not orders_csv_path.strip():
        # Absent rather than malformed: nothing was recorded to follow.
        return None
    orders_csv_file = Path(orders_csv_path)
    if not orders_csv_file.is_absolute():
        orders_csv_file = run_state_path.parent / orders_csv_file
    if _is_scheduled_recovery_context(run_state) and not _path_within(
        orders_csv_file, _recovery_root_for(run_state_path.parent)
    ):
        # Fall back to the SAME basename inside the run's own directory rather
        # than giving up. Rejecting the external path outright turned a wrong
        # allocation into NO allocation, which has the same money outcome: a
        # copied recovery state with a stale absolute path plus a valid local
        # filled_orders.csv contributed nothing from either loader, so the
        # ticker got bought again (Codex review: "Fall back to the recovery
        # run's local CSV"). Mirrors the basename fallback
        # scripts.run_classification._referenced_orders_csvs already applies.
        logger.warning(
            "recovery orders_csv_path %s is outside its run directory %s; "
            "falling back to the local file of the same name",
            orders_csv_file,
            run_state_path.parent,
        )
        orders_csv_file = run_state_path.parent / orders_csv_file.name
    return orders_csv_file


# Bounded, deliberately conservative sentinel for a same-day submission whose
# dollar amount could not be reconstructed (morning_dca's blocked-retry
# synthesis path records the ticker in "unreconstructable_submitted_tickers"
# rather than a normal candidate row -- see that field's own comment for why
# no row is carried). It exists only to keep the aggregated amount positive,
# so evaluate_top_up_guard's `prior.amount_usd <= 0` no-prior-run check does
# not mistake a confirmed-but-unsized submission for no submission at all;
# the reference price is poisoned to permanently unknown alongside it (see
# "reference_price_unknown" below), which is what actually routes the guard
# to its conservative TOP_UP_MISSING_PRIOR_PRICE / manual_review path rather
# than this dollar figure. It is not entirely inert, though:
# run_dca._compute_earlier_week_cross_stream_notional sums amount_usd across
# tickers for the shared weekly cap regardless of reference_price, so an
# unbounded sentinel (e.g. float("inf")) would be unsafe for the same reason
# noted at _process_buy_candidate's own order_amount bound -- it could get
# durably recorded as a same-day/weekly spend figure. Mirrors
# StrategyConfig.max_per_order_usd's absolute per-order ceiling
# (config/budgets.json's max_per_order_note): a deliberate overestimate, so
# an unknown submission's spend errs toward overcounting against the weekly
# cap (fail closed) rather than undercounting it.
#
# This is only a FALLBACK default: callers that hold the run's actual
# configured ceiling (StrategyConfig.max_per_order_usd / MorningConfig's
# equivalent) pass it explicitly via ``max_per_order_usd`` below.
# config/budgets.json's max_per_order_note documents $10 as the ceiling
# "across all live streams", but the schema permits any positive value, and a
# deployment that ever configures a higher one would otherwise have this
# fallback UNDERSTATE the true ceiling -- letting an unknown submission
# contribute less than it could really be worth to the shared weekly-cap
# seed and leaving unrelated candidates headroom that was already consumed
# (Codex review: "Derive the unknown-submission bound from its actual
# ceiling").
_UNRECONSTRUCTABLE_SUBMISSION_AMOUNT_USD = 10.0


def load_prior_same_day_allocations(
    state_root: str | Path,
    trading_day: date,
    *,
    boundary_et: time = MORNING_MANUAL_BOUNDARY_ET,
    additional_state_roots: Sequence[str | Path] = (),
    include_scheduled_afternoon: bool = False,
    skip_sink: Optional[List[Path]] = None,
    unreconstructable_submission_amount_usd: Optional[float] = None,
    unreconstructable_sink: Optional[List[str]] = None,
) -> Dict[str, PriorSameDayAllocation]:
    """Aggregate earlier same-day allocation context for the scheduled afternoon guard.

    Scans ``state_root`` (and any ``additional_state_roots``) recursively for
    ``run_state*.json`` artifacts written earlier the same ``trading_day`` by
    morning/midday/manual runs (including manual market-open recovery, manual
    override reruns under ``.../manual_reruns/``, and the morning live stream),
    and returns a per-ticker :class:`PriorSameDayAllocation`. These artifacts
    are read as prior-allocation context ONLY -- they are deliberately never
    surfaced as scheduled evidence, slippage, watchdog confirmation, scheduled
    cost basis, or scheduled fill counts.

    ``unreconstructable_submission_amount_usd`` overrides the conservative
    sentinel used for a ticker whose only evidence is an
    ``unreconstructable_submitted_tickers`` entry (see that field's own
    comment below). Defaults to :data:`_UNRECONSTRUCTABLE_SUBMISSION_AMOUNT_USD`
    (a flat $10) when not given. A fixed $10 undercounts against the weekly
    cross-stream cap whenever a run's actual ``max_per_order_usd`` ceiling is
    configured higher -- ``schemas/budgets.schema.json`` does not bound it at
    $10 -- so a caller that knows this run's real ceiling (e.g.
    ``run_dca._compute_earlier_week_cross_stream_notional``, which has
    ``StrategyConfig.max_per_order_usd`` in hand) should pass it here rather
    than accept the flat default (Codex review: "Derive the unknown-submission
    bound from its actual ceiling").

    Eligibility mirrors the 2:30 PM ET boundary: only runs generated before
    ``boundary_et`` on ``trading_day`` are read, scheduled *afternoon* runs are
    ignored (morning/midday-stream runs stay eligible despite running on a
    schedule; see ``_prior_run_is_scheduled``), and only buy candidates whose
    status shows an order was placed contribute. Each contributing candidate's
    reference price is resolved only after capital movement is confirmed, by policy
    preference -- logged ``target_price``, then ``decision_price``, then the confirmed
    ``average_fill_price`` (from ``orders.csv`` or a manual override's
    ``filled_orders.csv``). An unconfirmed submitted candidate is retained as prior
    allocation context with an unknown reference even if it logged target/decision
    prices. When multiple earlier runs touched a ticker the dollar
    amounts are summed and the ticker's *most recent* valid same-day reference price
    wins (by ``generated_at``; ties and untimestamped runs fall back to later scan
    order), so the afternoon run must beat that ticker's latest earlier entry price
    before it tops up. If any contributing reference is unknown the aggregate
    reference is unknown, routing the guard to its conservative missing-price /
    manual_review $0 path.

    ``include_scheduled_afternoon`` defaults to False, matching the normal
    scheduled afternoon run's own guard invocation (which must never see another
    afternoon-scheduled run as prior context). Set it True only for a distinct,
    later same-day invocation -- e.g. a final manual buy override -- that needs
    to see the day's already-completed scheduled run so it doesn't double-buy;
    pass a ``boundary_et`` later than that run's timestamp to include it.

    ``skip_sink``, when given, has the path of every ``run_state*.json``
    candidate that could not be read or parsed appended to it (a file still
    being flushed by a sibling stream's writer, or a transient read race).
    Such a file contributes NO ticker to the returned mapping, so a caller
    that only inspects the mapping for tickers with a known amount but an
    unresolved reference price can miss this case entirely -- a skipped
    file may be the ONLY same-day artifact for some ticker, leaving that
    ticker absent rather than merely unresolved (Codex review: "Detect
    artifacts skipped during the initial context scan"). Callers that need
    to distinguish "no prior run" from "prior run present but its artifact
    could not be scanned this pass" (e.g. run_dca's bounded same-day
    context reload) should pass a list here and treat any entries in it as
    reason enough to reload, independent of what the returned mapping shows.

    ``unreconstructable_submission_amount_usd`` overrides the conservative
    sentinel used for a ticker whose only evidence is an
    ``unreconstructable_submitted_tickers`` entry (see that field's own
    comment below). Defaults to :data:`_UNRECONSTRUCTABLE_SUBMISSION_AMOUNT_USD`
    (a flat $10) when not given. A fixed $10 undercounts against the weekly
    cross-stream cap whenever a run's actual ``max_per_order_usd`` ceiling is
    configured higher -- ``schemas/budgets.schema.json`` does not bound it at
    $10 -- so a caller that knows this run's real ceiling (e.g.
    ``run_dca._compute_earlier_week_cross_stream_notional``, which has
    ``StrategyConfig.max_per_order_usd`` in hand) should pass it here rather
    than accept the flat default (Codex review: "Derive the unknown-submission
    bound from its actual ceiling").

    ``unreconstructable_sink``, when given, has each ticker whose amount was
    ever set from this conservative sentinel appended to it. No fixed bound
    passed here -- not this run's own ceiling, not any other value -- can be
    proven to dominate the ORIGINATING run's actual ceiling: that run's
    config may have allowed a larger ``max_per_order_usd`` than this one's,
    at a time this call has no visibility into (Codex review: "Preserve the
    originating ceiling for historical unknown orders"). A caller that needs
    a genuinely safe total rather than an estimate (e.g.
    ``run_dca._compute_earlier_week_cross_stream_notional``, which sums
    amounts toward a shared weekly cap) should treat any entry here as
    proof the total is not trustworthy and fail closed the same way it
    already does for ``skip_sink`` -- rather than trust this sentinel's
    dollar figure.
    """
    _unreconstructable_amount = (
        unreconstructable_submission_amount_usd
        if unreconstructable_submission_amount_usd is not None
        else _UNRECONSTRUCTABLE_SUBMISSION_AMOUNT_USD
    )
    # Deduplicate roots by resolved path so an additional_state_root that matches
    # state_root (or another additional root) doesn't cause double-counting.
    _seen_roots: set = set()
    all_roots = []
    for _r in [Path(state_root), *[Path(r) for r in additional_state_roots]]:
        _key = _r.resolve()
        if _key not in _seen_roots:
            _seen_roots.add(_key)
            all_roots.append(_r)

    aggregated: Dict[str, Dict[str, Any]] = {}
    trading_day_iso = trading_day.isoformat()
    # Encode ONCE, outside the per-file loop (Copilot review: "precompute the
    # UTF-8 bytes once before iterating"): the substring fast-path below runs
    # for every candidate artifact in a recursively scanned historical corpus,
    # and re-encoding an invariant date string per file would hand back part of
    # the allocation saving that reading bytes instead of text just bought.
    trading_day_iso_bytes = trading_day_iso.encode("utf-8")
    all_run_state_paths = sorted(
        set(
            p
            for root in all_roots
            if root.exists()
            for p in root.rglob("run_state*.json")
        )
    )

    # Parse every candidate artifact once, then process them in CHRONOLOGICAL
    # (parsed generated_at) order rather than lexical path order (Codex review:
    # "Sort first-allocation records by timestamp"): differently-named subtrees
    # do not sort chronologically by path alone -- e.g. "manual_recovery/1100"
    # sorts before "manual_runs/0900" even though 09:00 happened first -- which
    # would lock the day's first-allocation base from the wrong run. A
    # timestamp-less artifact falls back to (stable) path-scan order and sorts
    # after every timestamped one, since its true position can't be established.
    _parsed_runs: List[Tuple[Tuple[int, Any], Path, Dict[str, Any]]] = []
    for _order, run_state_path in enumerate(all_run_state_paths):
        try:
            raw_bytes = run_state_path.read_bytes()
        except OSError:
            # Transient read failure (e.g. the file is still being flushed by
            # a sibling stream's writer) -- surfaced via skip_sink rather than
            # silently dropped, since a caller may need to know this scan was
            # incomplete even though no ticker in the returned mapping reflects it.
            # Scoped to plausibly same-day artifacts (by mtime) so a permanently
            # corrupted HISTORICAL file elsewhere in the recursively scanned
            # root doesn't poison every future scan's completeness signal forever.
            if skip_sink is not None and _mtime_matches_trading_day(
                run_state_path, trading_day
            ):
                skip_sink.append(run_state_path)
            continue

        # Fast path (restored -- see .jules/bolt.md 2025-01-20: rglob +
        # json.loads over a large historical artifact corpus is expensive,
        # so a raw substring check before parsing is worth keeping): skip
        # the parse ONLY for files whose mtime is NOT on trading_day. Such a
        # file cannot count toward skip_sink either way (it's scoped to
        # plausibly same-day artifacts, same as the two skip_sink call
        # sites below), so skipping its parse produces the exact same
        # observable outcome as parsing it and then discarding a would-be
        # failure. A file modified TODAY always gets a full parse regardless
        # of the substring match -- a "looks like a complete JSON object"
        # heuristic (e.g. ends with "}") isn't a reliable enough proxy for
        # real completeness to gate this on for same-day files (a sorted-key
        # writer can truncate mid-flush at a NESTED object's closing brace
        # while the outer object -- and "trading_day" -- is never written),
        # so same-day files skip the substring shortcut entirely and always
        # reach the parse-failure handler below that records skip_sink
        # (Codex review: "Parse JSON before declaring a brace-terminated
        # prefix complete"; Copilot review: restore the fast path safely).
        # Only trust the substring match when the file contains no JSON
        # unicode escape sequences -- a spec-valid encoder may spell an
        # ASCII character such as one of the date's hyphens as a unicode
        # escape, which would not literal-match trading_day_iso even though
        # the parsed value is identical.
        same_day_mtime = _mtime_matches_trading_day(run_state_path, trading_day)
        if (
            not same_day_mtime
            and trading_day_iso_bytes not in raw_bytes
            and b"\\u" not in raw_bytes
        ):
            continue

        try:
            run_state = json.loads(raw_bytes)
        except ValueError:
            # Partial JSON mid-flush is the other half of the parse-race this
            # loader must not silently absorb -- same skip_sink signal (and
            # same same-day scoping) as the read failure above.
            if skip_sink is not None and same_day_mtime:
                skip_sink.append(run_state_path)
            continue

        if not isinstance(run_state, dict):
            continue
        if run_state.get("trading_day") != trading_day_iso:
            continue

        run_ts = _prior_run_timestamp(run_state.get("generated_at"))
        sort_key = (0, run_ts) if run_ts is not None else (1, _order)
        _parsed_runs.append((sort_key, run_state_path, run_state))

    _parsed_runs.sort(key=lambda item: item[0])

    for _, run_state_path, run_state in _parsed_runs:
        if _prior_run_is_scheduled(run_state) and not include_scheduled_afternoon:
            continue
        if not _prior_run_before_boundary(run_state, boundary_et):
            continue
        if not _prior_run_is_valid_manual_recovery_artifact(run_state, run_state_path):
            continue

        classification = run_state.get("run_classification")
        run_id = None
        source = None
        if isinstance(classification, dict):
            run_id = classification.get("run_id")
            source = classification.get("run_origin")
        run_id = run_id or run_state.get("run_id")
        # A malformed run_id (a JSON list/object surviving corrupt input) is
        # unhashable, and the unreconstructable-submission handling below
        # uses run_id as a set key/membership test (contributing_run_ids/
        # attempt_run_ids) -- an unhashable value there raised TypeError out
        # of this whole scan with no per-artifact boundary around it,
        # aborting load_prior_same_day_allocations() over one corrupt
        # artifact (Codex review: "Validate run IDs before indexing
        # unreconstructable orders"). Normalized to a usable scalar (or
        # None, treated as absent) here, once, rather than at each of the
        # several places below that read run_id.
        #
        # Restricted to str only, not "any hashable scalar" -- a legitimate
        # run_id is always a formatted string (e.g.
        # "scheduled_20260728_1030ET"), never a bare bool/int/float, and
        # int/float/bool ARE hashable so the malformed-run-id check above
        # let them through unchanged. Two DISTINCT eligible artifacts both
        # corrupted to the same run_id: true (or the same numeric value)
        # then produced an IDENTICAL dedupe key in the unreconstructable-
        # submission handling below, collapsing two genuinely separate
        # confirmed submissions into one counted sentinel/attempt --
        # exactly the same undercounting bug the path-fallback dedupe key
        # exists to prevent for a genuinely ABSENT run_id (Codex review:
        # "Treat non-string run IDs as absent").
        if not isinstance(run_id, str):
            run_id = None
        source = source or "manual"
        # Recency key for most-recent reference resolution. Untimestamped runs use
        # the floor so any timestamped run outranks them; equal keys defer to later
        # scan order (all_run_state_paths is sorted ascending).
        run_ts = _prior_run_timestamp(run_state.get("generated_at")) or _TS_FLOOR

        fills = _orders_csv_fills(run_state_path.parent)
        # A full-report run_state written by run_and_report()/write_run_state()
        # stores artifact paths under "artifacts" and "summary_metrics" rather
        # than a top-level "buy_candidates" array.  When buy_candidates is absent
        # but an orders_csv_path is recorded, reconstruct prior allocations from
        # that CSV directly (filled rows only).
        # Full-report dry-run artifacts must never contribute: run_and_report
        # dry runs write filled DryRunBroker rows with no real capital deployed.
        if run_state.get("dry_run"):
            continue
        buy_candidates_raw = run_state.get("buy_candidates")
        # Persisted JSON can hold any shape here. A scalar such as 1 raised
        # TypeError out of the whole final-run context scan at the iteration
        # below, and a truthy non-list (a populated dict) was silently treated
        # as "this run's candidates were read" -- skipping the orders-CSV
        # fallback, so the run's real fills went unseen and its ticker could be
        # bought again at 3:30. Normalizing to [] routes both cases into the CSV
        # fallback, which is the fail-closed direction (Codex review: "Reject
        # malformed candidate collections in recovery states").
        if not isinstance(buy_candidates_raw, list):
            buy_candidates_raw = []
        # A ticker in "unreconstructable_submitted_tickers" had a confirmed
        # broker-side submission this run could not recover a dollar amount
        # for -- morning_dca's blocked-retry synthesis deliberately carries
        # NO buy_candidates row for it (a $0 row would read as no_prior_run
        # below just the same; see that field's own comment), so without this
        # block the ticker is invisible to this scan and
        # evaluate_top_up_guard treats it as no_prior_run, issuing a full
        # fresh buy on top of a submission whose real size is unknown
        # (Codex review: "Fail closed on unreconstructable carried
        # submissions"). Poison it the same way an unresolved reference price
        # already poisons a normally-processed candidate further down (see
        # "reference_price_unknown"): once poisoned, later processing in this
        # scan (any run, any order) never clears it, matching that existing
        # sticky "any unknown poisons the whole" convention.
        _unreconstructable_tickers = run_state.get("unreconstructable_submitted_tickers")
        if isinstance(_unreconstructable_tickers, list):
            for _unrec_ticker in _unreconstructable_tickers:
                if not isinstance(_unrec_ticker, str) or not _unrec_ticker:
                    continue
                _unrec_entry = aggregated.setdefault(
                    _unrec_ticker,
                    {
                        "amount": 0.0,
                        "reference_price": None,
                        "reference_ts": None,
                        "run_id": run_id,
                        "source": source,
                        "selected_base_amount_usd": None,
                        "selected_base_amount_usd_at": None,
                        "selected_base_amount_usd_seen": False,
                        "attempt_count": 0,
                        "contributing_run_ids": set(),
                        "attempt_run_ids": set(),
                        "contributing_dedupe_keys": set(),
                    },
                )
                # Gated on RUN, not on the ticker ever having a nonzero
                # amount: two separate eligible artifacts (e.g. a morning run
                # and a later midday/top-up run) can each independently
                # report the SAME ticker as unreconstructable -- two distinct
                # confirmed broker submissions, not one. The old `amount <= 0`
                # gate credited only the FIRST one ever seen and silently
                # dropped every later run's own sentinel amount and attempt,
                # understating shared daily/weekly notional and
                # max_orders_per_day even though the unknown reference
                # already blocks a fresh buy of the ticker itself (Codex
                # review: "Count each unreconstructable submission
                # separately").
                #
                # Deduped by run_id when one is usable, but by the artifact's
                # own PATH when it is not: a malformed/absent run_id used to
                # fall back to `amount <= 0`, which collapsed every later
                # run_id-less artifact for the same ticker into the FIRST one
                # ever seen -- two distinct eligible run_state.json files each
                # reporting the same ticker unreconstructable are two separate
                # confirmed submissions, not a repeat scan of one (Codex
                # review: "Count unknown submissions when run IDs are
                # absent"). The path IS still a stable, repeat-scan-safe key
                # for the one case this must keep collapsing: the SAME
                # artifact read again on a later pass.
                #
                # setdefault() on the ENTRY, not a bare index: aggregated's
                # own setdefault() above only supplies contributing_dedupe_keys
                # on a FRESH entry -- when an earlier artifact already created
                # this ticker's aggregate through the normal candidate or CSV
                # path (a different dict literal, without this field), a bare
                # entry["contributing_dedupe_keys"] raised KeyError and
                # aborted the whole scan (Codex review: "Initialize dedupe
                # keys on existing allocation entries").
                _unrec_dedupe_keys = _unrec_entry.setdefault("contributing_dedupe_keys", set())
                _unrec_dedupe_key = run_id if run_id is not None else str(run_state_path)
                _already_counted_this_run = _unrec_dedupe_key in _unrec_dedupe_keys
                if not _already_counted_this_run:
                    _unrec_entry["amount"] += _unreconstructable_amount
                    if unreconstructable_sink is not None:
                        unreconstructable_sink.append(_unrec_ticker)
                    # A confirmed submission consumed one of the shared
                    # max_orders_per_day slots even though its size is
                    # unknown -- counted here since (unlike a normal
                    # candidate row) no other code path ever sees this
                    # ticker for this run.
                    _unrec_entry["attempt_count"] += 1
                _unrec_dedupe_keys.add(_unrec_dedupe_key)
                _unrec_entry["reference_price"] = None
                _unrec_entry["reference_ts"] = None
                _unrec_entry["reference_price_unknown"] = True
                _unrec_entry["notional_uncertain"] = True
                # This ticker-level sentinel never carries an order_id, so
                # contributing_order_ids can never record it -- give it a
                # synthetic identity instead, keyed on the SAME dedupe key
                # this block already uses to recognize a repeat scan of the
                # same artifact (see uncertain_contributor_ids' own
                # docstring on PriorSameDayAllocation).
                _unrec_entry.setdefault("uncertain_contributor_ids", set()).add(
                    f"uncertain:{_unrec_ticker}:unrec:{_unrec_dedupe_key}"
                )
                if run_id is not None:
                    _unrec_entry["contributing_run_ids"].add(run_id)
                    _unrec_entry["attempt_run_ids"].add(run_id)
                _unrec_entry["run_id"] = run_id
                _unrec_entry["source"] = source
        # A recovery run may write artifacts/run_state.json beside a ROOT-level
        # filled_orders.csv, so the fills lookup beside the state found nothing.
        # Such a state can ALSO carry non-empty buy_candidates, in which case
        # the recorded orders_csv_path branch below is skipped and the fallback
        # loader treats the run as already covered -- an authoritative partial
        # fill was therefore replaced by the candidate's full planned amount at
        # an unknown price, suppressing the remaining top-up (Codex review:
        # "Read recovery fill CSVs even when candidates are embedded").
        #
        # Scoped to CANDIDATE-BACKED states because that is the only shape that
        # falls through: with no candidates the branch below already reads the
        # recorded path, and ``fills`` is never consulted there since the
        # candidate loop iterates nothing. Gated on ``not fills`` so it can only
        # ADD fills where the state's own directory had none, never
        # double-count.
        #
        # The recorded path is tried FIRST and the fixed-name scan second:
        # _orders_csv_fills() without an explicit file knows only
        # filled_orders.csv and orders.csv, so a recovery recording an in-root
        # CUSTOM name (artifacts.orders_csv_path='../executions.csv') was still
        # missed by the root retry alone -- the same suppressed top-up, one
        # filename away (Codex review: "Follow the recorded CSV for
        # candidate-backed recoveries").
        terminal_order_ids: set = set()
        terminal_tickers: set = set()
        if buy_candidates_raw and _is_scheduled_recovery_context(run_state):
            recorded_csv = _resolve_recorded_orders_csv(
                run_state, run_state_path, skip_sink=skip_sink
            )
            # MERGED per ticker, not gated on `fills` being empty. A single
            # fill beside run_state.json made the whole recorded CSV invisible,
            # so any OTHER ticker it confirmed fell back to its candidate's full
            # planned amount -- a $3 partial of a $10 candidate counted as $10,
            # suppressing the remaining top-up (Codex review: "Merge recorded
            # recovery fills even when sibling fills exist"). setdefault means a
            # later source can only ADD tickers, never overwrite what the
            # state's own directory already answered, so the path that already
            # worked is untouched.
            if recorded_csv is not None and recorded_csv.exists():
                for _t, _f in _orders_csv_fills(
                    recorded_csv.parent,
                    orders_csv_file=recorded_csv,
                    skip_sink=skip_sink,
                ).items():
                    _merge_fill(fills, _t, _f)
            recovery_root = _recovery_root_for(run_state_path.parent)
            if recovery_root != run_state_path.parent:
                for _t, _f in _orders_csv_fills(recovery_root).items():
                    _merge_fill(fills, _t, _f)
            # The same CSV also carries TERMINAL non-fill outcomes, and dropping
            # them left the candidate loop below holding the full planned amount
            # with an unknown reference price -- routing a ticker whose order is
            # KNOWN rejected to the $0 manual-review guard and suppressing a
            # legitimate top-up. The no-candidate path already honors this via
            # _orders_csv_submitted_notionals (Codex review: "Honor terminal
            # rejections for candidate-backed recoveries").
            for _csv in (
                recorded_csv if recorded_csv is not None else None,
                recovery_root / "filled_orders.csv",
                recovery_root / "orders.csv",
                run_state_path.parent / "filled_orders.csv",
                run_state_path.parent / "orders.csv",
            ):
                if _csv is None:
                    continue
                _oids, _tks = _orders_csv_terminal_non_fills(_csv)
                terminal_order_ids |= _oids
                terminal_tickers |= _tks
        if not buy_candidates_raw:
            orders_csv_file = _resolve_recorded_orders_csv(
                run_state, run_state_path, skip_sink=skip_sink
            )
            if orders_csv_file is None:
                # Nothing recorded in artifacts.orders_csv_path -- the shape
                # every in-repo executor (morning/midday/afternoon) writes.
                # The market-open/intraday streams have no in-repo Python
                # entry point at all (their Claude-executor prompts write
                # only run_state.json and a bare sibling submitted_orders.csv,
                # never buy_candidates or an artifacts block), so a valid
                # same-day run whose only evidence is that canonical file was
                # previously invisible here entirely (Codex review: "Read
                # canonical CSVs during same-day cap seeding"). Check for it
                # as a last-resort sibling, exactly like filled_orders.csv/
                # orders.csv are checked by name elsewhere in this module.
                _bare_submitted_orders = run_state_path.parent / "submitted_orders.csv"
                if _bare_submitted_orders.exists():
                    orders_csv_file = _bare_submitted_orders
            if orders_csv_file is not None:
                if orders_csv_file.exists():
                    # Pass the exact recorded file rather than run_dir/"orders.csv"
                    # because run_and_report writes custom-named CSVs.
                    report_fills = _orders_csv_fills(
                        orders_csv_file.parent,
                        orders_csv_file=orders_csv_file,
                        skip_sink=skip_sink,
                    )
                    submitted_notionals = _orders_csv_submitted_notionals(
                        orders_csv_file, skip_sink=skip_sink
                    )
                    # Merge filled rows (known price) then submitted rows (unknown price).
                    # Filled rows for a ticker win over submitted rows for the same ticker.
                    _csv_tickers: Dict[str, tuple] = {}  # ticker -> (amount, ref_price)
                    for _ticker, _fill in report_fills.items():
                        # None keeps the reference UNRESOLVED for a partial, the
                        # same rule the candidate loop applies: the executed
                        # notional counts, but the price does not settle until
                        # the order fully fills or is terminally reconciled.
                        _ref = (
                            None
                            if _fill.get("_partial_execution")
                            else _fill["avg_fill_price"]
                        )
                        if _fill.get("amount_usd"):
                            _csv_tickers[_ticker] = (_fill["amount_usd"], _ref)
                        elif _fill["quantity_filled"]:
                            _csv_tickers[_ticker] = (
                                _fill["avg_fill_price"] * _fill["quantity_filled"],
                                _ref,
                            )
                    for _ticker, _notional in submitted_notionals.items():
                        if _ticker not in _csv_tickers:
                            _csv_tickers[_ticker] = (_notional, None)
                    # Attempt counts are read PER CSV ROW, independent of
                    # _csv_tickers -- report_fills/submitted_notionals both
                    # collapse multiple distinct orders for the same ticker
                    # into a single aggregated record (report_fills sums
                    # them via _merge_fill), so counting "one attempt per
                    # _csv_tickers entry" undercounted whenever a ticker had
                    # more than one real order this run. It also omits a
                    # terminal rejected/canceled-only ticker entirely (never
                    # enters _csv_tickers, since neither reader surfaces
                    # zero-capital rows), which must still count as an
                    # attempt (Codex review: "Count each CSV order attempt
                    # before aggregating by ticker").
                    _attempt_counts = _orders_csv_attempt_counts(
                        orders_csv_file, skip_sink=skip_sink
                    )
                    for _ticker in set(_csv_tickers) | set(_attempt_counts):
                        _entry = aggregated.setdefault(
                            _ticker,
                            {
                                "amount": 0.0,
                                "reference_price": None,
                                "reference_ts": None,
                                "run_id": run_id,
                                "source": source,
                                "selected_base_amount_usd": None,
                                "selected_base_amount_usd_at": None,
                                "selected_base_amount_usd_seen": False,
                                "attempt_count": 0,
                                "contributing_run_ids": set(),
                                "attempt_run_ids": set(),
                            },
                        )
                        # Without an explicit "attempt_count" key in the
                        # setdefault dict above, aggregated.setdefault()
                        # would silently return a PRE-EXISTING entry from an
                        # earlier-scanned run's embedded-candidate branch
                        # missing this key entirely, and that branch's own
                        # entry["attempt_count"] += 1 on a later-scanned run
                        # for the same ticker would then raise KeyError and
                        # abort reconstruction outright (Codex review:
                        # "Initialize attempt counts for CSV-reconstructed
                        # orders").
                        _entry["attempt_count"] += _attempt_counts.get(_ticker, 1)
                        if run_id is not None:
                            _entry["attempt_run_ids"].add(run_id)
                        _amount, _ref = _csv_tickers.get(_ticker, (0.0, None))
                        if _amount <= 0:
                            continue
                        _entry["amount"] += _amount
                        if run_id is not None:
                            _entry["contributing_run_ids"].add(run_id)
                        if _entry.get("reference_price_unknown"):
                            pass
                        elif _ref is None:
                            _entry["reference_price"] = None
                            _entry["reference_ts"] = None
                            _entry["reference_price_unknown"] = True
                        else:
                            if (
                                _entry["reference_price"] is None
                                or run_ts >= _entry["reference_ts"]
                            ):
                                _entry["reference_price"] = _ref
                                _entry["reference_ts"] = run_ts
                        # This CSV-reconstructed shape carries no base info -- if
                        # this is the ticker's first contributing entry, lock the
                        # base permanently unknown (Codex review: "Do not infer a
                        # first-allocation base from a later run") rather than
                        # leaving it open for a later run's own base to fill in.
                        if not _entry["selected_base_amount_usd_seen"]:
                            _entry["selected_base_amount_usd_at"] = run_state.get(
                                "generated_at"
                            )
                            _entry["selected_base_amount_usd_seen"] = True
                        _entry["run_id"] = run_id
                        _entry["source"] = source
                elif skip_sink is not None:
                    # This full-report run_state RECORDED orders_csv_path
                    # as its fill source, but the file isn't there at
                    # that exact path -- deleted, relocated, or still
                    # being written by run_and_report. Its referenced
                    # fills are exactly as unverifiable as a
                    # run_state.json that itself failed to read/parse,
                    # so this scan must not report itself complete while
                    # a ticker's only fill evidence is silently invisible
                    # (Codex review: "Include referenced CSV failures in
                    # scan completeness"). BUT when a supported sibling
                    # sits right beside this run_state (e.g. the recorded
                    # path is a STALE absolute path from a relocated
                    # deployment, while the real CSV -- under its
                    # recorded basename, OR a differently-named file like
                    # submitted_orders.csv/filled_orders.csv -- still
                    # lives in this run's own directory),
                    # scripts.run_classification.load_same_day_top_up_context's
                    # own basename/glob fallback (_referenced_orders_csvs,
                    # which matches its recorded basename AND any sibling
                    # matching "*orders.csv") already recovers this run's
                    # fills unconditionally, within the SAME
                    # _compute_auto_derived_prior_allocations call that
                    # merges its result in right after this loop.
                    # Flagging a failure here anyway would be a permanent
                    # false positive -- a stale absolute path never
                    # becomes valid, so scan_had_failures would never
                    # clear, poisoning an already-correctly-recovered,
                    # resolved allocation on every future scan (Codex
                    # review: "Do not flag stale CSV paths after fallback
                    # recovery"; "Recognize every supported sibling
                    # fallback before flagging failure" -- the exact-
                    # basename-only check missed the glob fallback).
                    # Only flag the failure when NEITHER supported
                    # fallback has anything to find.
                    _has_basename_sibling = (
                        run_state_path.parent / orders_csv_file.name
                    ).exists()
                    _has_glob_sibling = any(run_state_path.parent.glob("*orders.csv"))
                    if not _has_basename_sibling and not _has_glob_sibling:
                        skip_sink.append(run_state_path)
        for candidate in buy_candidates_raw or []:
            if not isinstance(candidate, dict):
                continue
            raw_status = candidate.get("status")
            if raw_status is not None and not isinstance(raw_status, str):
                # A malformed (non-string, e.g. a list) status is unusable --
                # distinct from a legitimate string status this scan simply
                # doesn't treat as an attempt (e.g. "rejected"). Checked
                # against the RAW value, before the `or ""` fallback below:
                # that fallback normalizes any FALSY value -- not just a
                # genuinely absent status (None), but also a malformed falsy
                # non-string like [], {}, 0, or False -- into the string ""
                # just like a legitimately empty status, so a bare
                # `isinstance(status, str)` check on the ALREADY-normalized
                # value never catches those (Codex review: "Reject falsy
                # non-string statuses before normalization"). Because
                # buy_candidates_raw is nonempty, the orders-CSV fallback
                # above never ran for this run_state, so silently skipping
                # this row would report a clean, empty scan even though a
                # confirmed fill for this ticker may sit unread in a sibling
                # orders.csv. Mark the scan incomplete instead (Codex review:
                # "Fall back to fills when every candidate status is
                # malformed").
                if skip_sink is not None:
                    skip_sink.append(run_state_path)
                continue
            status = raw_status or ""
            if status not in _PRIOR_ALLOCATION_ATTEMPT_STATUSES:
                continue
            ticker = candidate.get("ticker")
            # `if not ticker` alone only rejects FALSY values (None, "", 0,
            # False) -- a malformed nonempty list/object ticker (corrupt
            # input surviving JSON parsing) is truthy and passed straight
            # through to aggregated.setdefault(ticker, ...) below, which
            # hashes it and raised TypeError, aborting this whole scan with
            # no per-candidate boundary around it (Codex review: "Validate
            # tickers newly admitted as in-flight"). Require a usable
            # nonempty string.
            if not isinstance(ticker, str) or not ticker:
                continue

            # Every row that reaches here obtained an order_id at submission
            # time (status "submitted"/"filled", or still placed-or-in-flight
            # as "pending"/"unconfirmed") or genuinely attempted placement and
            # raised (status "failed") -- a real broker-facing attempt that
            # consumes one of the shared max_orders_per_day
            # slots regardless of whether it ends up contributing any dollar
            # amount below (Codex review: "Count every prior buy attempt
            # toward the daily limit"). Counted BEFORE the terminal-
            # rejection/zero-amount/malformed-amount continues further down,
            # since those still represent an attempt that was made, just one
            # confirmed to have moved no capital.
            entry = aggregated.setdefault(
                ticker,
                {
                    "amount": 0.0,
                    "reference_price": None,
                    "reference_ts": None,
                    "run_id": run_id,
                    "source": source,
                    "selected_base_amount_usd": None,
                    "selected_base_amount_usd_at": None,
                    "selected_base_amount_usd_seen": False,
                    "attempt_count": 0,
                    "contributing_run_ids": set(),
                    "attempt_run_ids": set(),
                    "contributing_order_ids": set(),
                },
            )
            # A row whose ENTIRE whole_share_claim_breakdown points at
            # trading day(s) strictly before this artifact's own
            # trading_day_iso is a cross-day RECOVERY of an order that was
            # actually attempted (and already counted toward
            # max_orders_per_day) on that earlier day, not a new attempt
            # made today -- dca_risk only reads this breakdown for the
            # DOLLAR figure, but this attempt_count has no date bucketing of
            # its own, so counting it again here seeds a later retry TODAY's
            # own attempt count as if the historical order were a fresh
            # same-day attempt, potentially blocking a legitimate new order
            # today even though ctx.state.record_buy() originally attributed
            # the recovered order to the claim date, not today (Codex
            # review: "Keep recovered attempts on their original claim
            # dates"). A row with NO breakdown, or one covering TODAY
            # (alone or alongside older claims -- e.g. today's own fresh
            # submission merged with a recovered claim), still counts
            # normally.
            _claim_breakdown = candidate.get("whole_share_claim_breakdown")
            _is_cross_day_recovery_only = bool(_claim_breakdown) and isinstance(_claim_breakdown, list) and all(
                isinstance(_entry, dict) and _entry.get("trading_day") != trading_day_iso
                for _entry in _claim_breakdown
            )
            # A settlement-adjustment row (see _book_reconciled_whole_share_
            # order's own "whole_share_settlement_adjustment" marker)
            # NEVER counts as a fresh attempt, regardless of date -- unlike
            # the cross-day check above, this covers the SAME-day case too:
            # when the provisional booking and this settlement both land on
            # the SAME trading_day, the breakdown entry's trading_day equals
            # trading_day_iso, making _is_cross_day_recovery_only False even
            # though the provisional booking already counted this exact
            # physical order's attempt once (Codex review: "Exclude
            # same-day settlement deltas from attempt counts").
            _is_settlement_adjustment = bool(candidate.get("whole_share_settlement_adjustment"))
            # ... but a row carrying its own per-day attempt buckets has
            # ALREADY answered both questions, and more precisely than either
            # test above can. _attempt_side_days() records the fresh side of a
            # merge under the UNDATED bucket (it has no claim breakdown of its
            # own to date it by), so an aggregate of a prior-day recovery and a
            # fresh order placed TODAY carries a whole_share_claim_breakdown
            # naming only the OLD date -- making _is_cross_day_recovery_only
            # True and skipping the bucket-aware count entirely, so today's
            # real attempt was charged as 0 and a later run could exceed
            # max_orders_per_day (Codex review, PR #786: "Count today's attempt
            # in mixed-day aggregate rows"). This is round 35's failure mode on
            # a new pair: an outer guard re-deriving what the inner helper now
            # computes properly. Where the buckets exist they are authoritative
            # -- _broker_attempts_on_day() already excludes every prior day, and
            # _attempt_side_days() already returns NO buckets for a settlement
            # adjustment or a deliberate skip, so neither exclusion is lost.
            _attempt_buckets = candidate.get("merged_attempt_days")
            _has_attempt_buckets = isinstance(_attempt_buckets, dict) and bool(_attempt_buckets)
            if _has_attempt_buckets or (
                not _is_cross_day_recovery_only and not _is_settlement_adjustment
            ):
                # Attempts, not rows: an aggregate row can stand for several
                # real broker orders, each of which took its own slot (see
                # _broker_attempt_count). Unmerged rows still count exactly 1.
                entry["attempt_count"] += _broker_attempts_on_day(
                    candidate, trading_day_iso
                )
                if run_id is not None:
                    entry["attempt_run_ids"].add(run_id)
            if status == "failed" and not candidate.get("ambiguous_placement_exception"):
                # A placement that raised before any capital moved (no fill,
                # no order_id necessarily) -- counted as an attempt above,
                # contributes nothing to amount/reference/base.
                continue

            # The recovery CSV said this order ended REJECTED/CANCELED having
            # executed nothing, which outranks the candidate's submission-time
            # status: no capital moved, so counting its planned amount as prior
            # allocation forces the $0 manual-review guard and suppresses a
            # legitimate top-up (Codex review: "Honor terminal rejections for
            # candidate-backed recoveries"). Ticker-level evidence applies only
            # when the row carried no order_id AND nothing confirms a fill for
            # that ticker, since one ticker can have both a rejected order and a
            # separate real fill.
            _raw_cand_oid = candidate.get("order_id")
            _cand_oid = _raw_cand_oid.strip() if isinstance(_raw_cand_oid, str) else ""
            # PER REPRESENTED ORDER, not per row. An aggregate row's scalar
            # order_id names only ONE of the physical orders it stands for, and
            # which one is an accident of the merge: when both sides submitted,
            # `_merge_whole_share_submission_outcomes` leaves NEW's id there.
            # So an older recovery that really filled, merged with a fresh
            # order that was accepted and then cancelled with an explicit zero,
            # put the CANCELLED id in the scalar field -- and this `continue`
            # then dropped the whole candidate, erasing the older order's real
            # spend from same-day/weekly-cap and top-up reconstruction and
            # leaving room for excess spend (Codex review, PR #786: "Preserve
            # other fills when a merged order later terminates").
            #
            # The merge cannot fix this at its end: whether NEW later turns out
            # terminal is not knowable when the two sides are combined. So the
            # evidence is applied here, where it is read -- skip only when
            # EVERY order the row represents is terminal, since a row with one
            # live-or-filled order still stands for real capital.
            _represented = {_cand_oid} if _cand_oid else set()
            for _oid in candidate.get("whole_share_order_ids") or []:
                _oid = str(_oid).strip()
                if _oid:
                    _represented.add(_oid)
            # This row's decision-time identity, computed only when the row
            # carries NO order_id at all (_represented empty) -- NOT
            # unconditionally. An id-FULL row is already fully proven by
            # contributing_order_ids alone (its actual broker identity),
            # and attaching this ADDITIONAL, weaker proof requirement on
            # top would make resolution depend on decision-time fields that
            # a clean reload is legitimately allowed to CORRECT (e.g.
            # target_price) even while the order_id itself stays the same
            # -- turning a harmless correction into a spurious identity
            # mismatch that wrongly blocks a resolution contributing_
            # order_ids alone already proves is safe (Codex review, PR
            # badMade/all-stock-dca#1171 discussion: "Skip synthetic
            # provenance for already identified orders" -- a P1 caught on
            # an unconditional version of this line). The tradeoff: a row
            # that STARTS id-less and later GAINS an order_id (a distinct,
            # narrower transition) no longer resolves automatically either
            # -- an accepted conservative limitation, not a regression: it
            # matches the SAME fail-closed behavior an id-less
            # unreconstructable_submitted_tickers sentinel already has when
            # it resolves into a normal candidate row (see that block's own
            # dedupe-keyed identity, which has the identical limitation for
            # the identical reason).
            _row_uncertain_key = (
                None
                if _represented
                else _synthetic_uncertain_contributor_key(
                    ticker, run_id, run_state_path, candidate
                )
            )
            if _represented and _represented <= terminal_order_ids:
                # A plain row represents exactly its own scalar id, so this is
                # identical to the previous behaviour for every non-aggregate
                # candidate. Its id(s) are still recorded into
                # contributing_order_ids before skipping, even though this
                # row contributes no DOLLARS -- attempt_count was already
                # bumped above regardless of dollar contribution (Codex
                # review: "Count every prior buy attempt toward the daily
                # limit"), so a known rejected/canceled order's id is
                # available right here but used to be dropped along with
                # the row, leaving that seeded attempt anonymous. A later
                # reconcile_prior_allocation call for a DIFFERENT ambiguous
                # order on the same ticker/day then had no durable id to
                # subtract from buys_today(), read that count as the new
                # order's own persisted charge, and declined to restore its
                # attempt -- two real broker calls collapsed into one
                # counted attempt, permitting an order beyond
                # max_orders_per_day (Codex review, PR #1168: "Seed
                # provenance for zero-dollar attempts"). Mirrors the
                # identical "Require provenance for the uncertain
                # contributor itself" fix a few lines above for the
                # non-finite-amount path.
                entry.setdefault("contributing_order_ids", set()).update(_represented)
                continue
            # Excludes an AMBIGUOUS id-less candidate -- one whose own
            # placement call raised an unresolved
            # `AmbiguousPlacementResponseError`/similar (see the earlier
            # `status == "failed" and not ambiguous_placement_exception`
            # branch above, which already treats this shape specially) --
            # from this ticker-only fallback. Without an order id, the
            # correlation between THIS candidate's own possibly-live order
            # and an unrelated terminal zero-fill row the recovery CSV
            # happens to report for the SAME ticker cannot be proven: two
            # separate broker calls for the same ticker (one ambiguous,
            # one a genuine later rejection) are not the same order, and
            # crediting the ambiguous candidate's planned amount as
            # resolved-away let `load_prior_same_day_allocations` report
            # zero deployed dollars for a ticker whose ambiguous order may
            # already have consumed that capital -- freeing a later top-up
            # to reuse it (Codex review, PR #1164: "Preserve id-less
            # ambiguous candidates across ticker rejections").
            if (
                not _cand_oid
                and not candidate.get("ambiguous_placement_exception")
                and ticker in terminal_tickers
                and fills.get(ticker) is None
            ):
                continue

            # A "submitted" candidate in run_state.json only means an order_id was
            # obtained at submission time, not that it filled. When orders.csv
            # confirms a fill, use the actual filled notional/price. When
            # orders.csv exists but doesn't confirm a fill for this ticker (still
            # "submitted", rejected, canceled, or never refreshed), we can't tell
            # whether real capital moved -- dropping the ticker outright would
            # treat an unrefreshed-but-actually-filled order as "no_prior_run"
            # and risk a double-buy, so instead keep the known planned amount but
            # with no reference price (see below), which routes the guard to its
            # conservative manual-review $0 path rather than a blind top-up.
            fill = fills.get(ticker)
            amount_raw = candidate.get("incremental_order_amount")
            if amount_raw is None:
                amount_raw = candidate.get("planned_amount_usd")
            if isinstance(amount_raw, bool):
                amount = math.nan
            else:
                try:
                    amount = float(cast(Any, amount_raw))
                except (TypeError, ValueError, OverflowError):
                    amount = math.nan
            fill_amount = math.nan
            if fill is not None and fill.get("amount_usd"):
                # Prefer the actual filled notional over the planned amount so a
                # manual override or partial fill doesn't overstate prior allocation.
                try:
                    fill_amount = float(cast(Any, fill["amount_usd"]))
                except (TypeError, ValueError):
                    fill_amount = math.nan
            if (
                not math.isfinite(fill_amount)
                and fill is not None
                and fill["quantity_filled"]
                and fill.get("avg_fill_price") is not None
            ):
                # Prefer the actual filled notional over the planned amount so a
                # partial fill doesn't overstate prior allocation. Requires a
                # confirmed price -- a quantity-only fill with no usable price
                # carries no way to derive a dollar amount and must not be
                # multiplied against a missing (None) price.
                try:
                    fill_amount = float(cast(Any, fill["avg_fill_price"])) * float(
                        cast(Any, fill["quantity_filled"])
                    )
                except (TypeError, ValueError):
                    fill_amount = math.nan
            if math.isfinite(fill_amount):
                amount = fill_amount
            # Nonnumeric values are normalized to NaN above so they reach
            # this same fail-closed path instead of bypassing it on conversion.
            # float() happily parses the JSON strings "NaN"/"Infinity"/
            # "-Infinity" without raising, so a corrupted amount_raw of that
            # shape survived as a non-finite `amount`. Checked AFTER the
            # fill-override attempt above, not before: a candidate's own
            # planned_amount_usd can be corrupted while its referenced
            # orders CSV still carries a valid confirmed fill, and poisoning
            # here first would discard that authoritative recovered amount
            # even though it was available (Codex review: "Prefer confirmed
            # fills before poisoning malformed plans"). A bare `continue`
            # here left the ticker's own aggregate entry at amount_usd==0
            # without appending to unreconstructable_sink -- a genuinely
            # zero-dollar allocation, not a poisoned one:
            # _tickers_with_unresolved_same_day_context() ignores zero-
            # dollar allocations, so neither the bounded reload nor the
            # global worst-case-ceiling fail-closed engaged, even though a
            # real committed order's size is unknown and other tickers
            # could retain daily/weekly headroom it may have already
            # consumed (Codex review: "Fail shared caps closed for
            # non-finite prior notionals"). Routed through the SAME
            # unreconstructable-submission fail-closed path the dedicated
            # unreconstructable_submitted_tickers marker uses elsewhere in
            # this function: seed the conservative sentinel amount and
            # record the ticker in the sink, leaving reference_price
            # poisoned (never set below) so the guard takes its
            # conservative manual-review path.
            if not math.isfinite(amount):
                entry["amount"] += _unreconstructable_amount
                entry["notional_uncertain"] = True
                # Recorded even on this uncertain/sentinel path, unlike the
                # dollar-confirmed contributing_order_ids update further
                # below: a clean reload that loses THIS row entirely while
                # coincidentally correcting a DIFFERENT known order to the
                # same total must not see identical contributing_order_ids
                # sets on both passes -- this row's own identity has to
                # show up as "present but unresolved" on the first pass so
                # its absence from a later pass is detectable (Codex
                # review: "Require provenance for the uncertain contributor
                # itself").
                entry.setdefault("contributing_order_ids", set()).update(_represented)
                if _row_uncertain_key is not None:
                    # No order_id at all -- contributing_order_ids has
                    # nothing to record, so this row is invisible to that
                    # check entirely. Give it a synthetic identity instead
                    # (see uncertain_contributor_ids' docstring).
                    entry.setdefault("uncertain_contributor_ids", set()).add(_row_uncertain_key)
                if unreconstructable_sink is not None:
                    unreconstructable_sink.append(ticker)
                continue
            if isinstance(_claim_breakdown, list) and _claim_breakdown:
                # A whole-share row carrying a claim breakdown attributes
                # its dollars per-claim-date, exactly like
                # dca_risk.deployed_usd_by_claim_date() already does for
                # the kill-switch total -- this loader's own row-level
                # amount above (planned/fill-derived) has no such date
                # split and would otherwise attribute a recovered OLDER
                # claim's dollars to TODAY's own bucket. Since
                # _compute_earlier_week_cross_stream_notional() reuses this
                # loader to seed the shared WEEKLY cap, that misattribution
                # would count a prior week's already-spent recovery as
                # current-week spend, understating remaining headroom and
                # potentially blocking valid orders for the rest of the
                # week (Codex review: "Bucket recovered notional by its
                # claim date"). Sum only the breakdown entries whose OWN
                # trading_day matches this artifact's trading_day_iso --
                # any older-claim portion contributes nothing here (it
                # already contributed to ITS OWN day's allocation, on the
                # earlier run that recorded it).
                #
                # A row can ALSO merge an older recovered claim (which DOES
                # have its own breakdown entry) with a genuinely FRESH order
                # placed today (which does NOT -- only a reconciled recovery
                # ever gets one; see _merge_whole_share_submission_outcomes).
                # Summing only breakdown entries matching today would then
                # attribute $0 to that fresh order entirely, silently
                # dropping real submitted capital from same-day/weekly-cap
                # reconstruction and letting later candidates exceed the
                # configured caps (Codex review: "Preserve fresh notional in
                # mixed recovery rows"). The row's own `amount` (computed
                # above, from planned/fill-derived fields) is the FULL total
                # including any such fresh portion -- subtracting the
                # breakdown's own grand total isolates exactly that
                # unaccounted remainder, attributed to today like an
                # ordinary candidate with no breakdown at all, mirroring
                # dca_risk.deployed_usd_by_claim_date()'s own identical
                # unaccounted-remainder handling.
                # _finite_nonnegative_float(), not a bare float(): a
                # breakdown entry's amount_usd corrupted to the JSON string
                # "NaN"/"Infinity" parses without raising, and a genuinely
                # non-numeric string (e.g. "abc") raised ValueError with no
                # try/except around this sum, aborting the whole loader over
                # one corrupt breakdown entry. An unusable entry contributes
                # 0.0 to both sums rather than propagating NaN/crashing
                # (Codex review: "Reject non-finite notionals for newly
                # admitted statuses").
                total_breakdown = sum(
                    _finite_nonnegative_float(_entry.get("amount_usd")) or 0.0
                    for _entry in _claim_breakdown
                    if isinstance(_entry, dict)
                )
                today_breakdown = sum(
                    _finite_nonnegative_float(_entry.get("amount_usd")) or 0.0
                    for _entry in _claim_breakdown
                    if isinstance(_entry, dict) and _entry.get("trading_day") == trading_day_iso
                )
                if total_breakdown > amount:
                    entry["amount"] += _unreconstructable_amount
                    entry["notional_uncertain"] = True
                    # See the non-finite-amount branch above for why this
                    # uncertain row's own order identity must be recorded
                    # here too (Codex review: "Require provenance for the
                    # uncertain contributor itself").
                    entry.setdefault("contributing_order_ids", set()).update(_represented)
                    if _row_uncertain_key is not None:
                        # See the non-finite-amount branch above for why an
                        # id-less row also needs a synthetic
                        # uncertain_contributor_ids identity.
                        entry.setdefault("uncertain_contributor_ids", set()).add(_row_uncertain_key)
                    if unreconstructable_sink is not None:
                        unreconstructable_sink.append(ticker)
                    continue
                amount = today_breakdown + (amount - total_breakdown)
            if amount <= 0:
                # Two genuinely legitimate zero shapes, neither corruption:
                # (1) a claim breakdown can zero out TODAY's own bucket
                # entirely when the row's whole amount is attributed to
                # earlier claim date(s) -- a cross-day whole-share recovery
                # (see the breakdown handling above; that already validates
                # each entry's own amount, so a breakdown-derived zero here
                # is trusted). (2) the one documented zero-dollar shape a
                # legitimate writer produces outside a breakdown: an
                # inverse-martingale lease recovery row, marked by this
                # exact reason.
                #
                # Every OTHER order-bearing row reaching here (submitted/
                # filled/pending/unconfirmed) with a nonpositive amount and
                # no breakdown is corrupted -- a real broker order has a
                # nonzero minimum -- and a bare `continue` left it as a
                # genuinely zero-dollar aggregate rather than a poisoned
                # one, the same "invisible to _tickers_with_unresolved_
                # same_day_context() and the global worst-case-ceiling
                # fail-closed" gap the non-finite check above exists to
                # close (Codex review: "Treat nonpositive in-flight amounts
                # as unreconstructable").
                if isinstance(_claim_breakdown, list) and _claim_breakdown:
                    continue
                if amount == 0.0 and candidate.get("reason") == "recovered_inverse_martingale_lease":
                    continue
                entry["amount"] += _unreconstructable_amount
                entry["notional_uncertain"] = True
                # See the non-finite-amount branch above for why this
                # uncertain row's own order identity must be recorded here
                # too (Codex review: "Require provenance for the uncertain
                # contributor itself").
                entry.setdefault("contributing_order_ids", set()).update(_represented)
                if _row_uncertain_key is not None:
                    # See the non-finite-amount branch above for why an
                    # id-less row also needs a synthetic
                    # uncertain_contributor_ids identity.
                    entry.setdefault("uncertain_contributor_ids", set()).add(_row_uncertain_key)
                if unreconstructable_sink is not None:
                    unreconstructable_sink.append(ticker)
                continue

            # Reference price preference (same-day top-up guard policy) applies
            # only after capital movement is confirmed. A still-unfilled
            # ``submitted`` row may later be rejected/canceled or may simply have
            # stale order history; using its logged target/decision price as a
            # known reference would let later top-ups silently take
            # price_not_below/no_incremental. Keep that path unknown so the guard
            # routes to missing_prior_price -> $0 + manual review.
            reference_price = None
            base_amount_usd = None
            fill_is_partial = bool(fill and fill.get("_partial_execution"))
            if (status == "filled" or fill is not None) and not fill_is_partial:
                reference_price = _candidate_logged_reference_price(candidate)
                if reference_price is None and fill is not None:
                    reference_price = cast(Any, fill["avg_fill_price"])
                # Same confirmed-capital-movement gate as reference_price: an
                # unconfirmed submitted candidate's base is not trusted as the
                # day's fixed first-allocation base either.
                try:
                    base_amount_usd = float(cast(Any, candidate.get("selected_base_amount_usd")))
                except (TypeError, ValueError):
                    base_amount_usd = None
                if base_amount_usd is not None and not (
                    math.isfinite(base_amount_usd) and base_amount_usd > 0
                ):
                    base_amount_usd = None

            # `entry` was already created (and this row's attempt already
            # counted) above, before the terminal-rejection/zero-amount/
            # malformed-amount continues -- fetch it, don't re-create it.
            entry = aggregated[ticker]
            entry["amount"] += amount
            if run_id is not None:
                # Only recorded once a row actually contributes a positive
                # dollar amount (this line), not at the earlier attempt-count
                # increment -- contributing_run_ids exists to let
                # load_prior_same_day_allocations_multi recognize a fully
                # duplicated DOLLAR contribution across roots, so a $0
                # attempt (already counted toward attempt_count above) must
                # not be treated as if it needs deduplicating here too
                # (Codex review: "Deduplicate mirrored artifacts before
                # pooling spend").
                entry["contributing_run_ids"].add(run_id)
            # Order-level provenance, not just run/artifact-level:
            # contributing_run_ids alone records only which RUN contributed,
            # but a single mutable run_state.json can expose MULTIPLE
            # distinct same-ticker orders under that one run_id (see the
            # attempt-counting comment above this loop) -- an equal
            # contributing_run_ids set between two scans does not prove the
            # SAME order was reconstructed both times, only that the same
            # run contributed SOME dollars each time (Codex review: "Match
            # order-level provenance before clearing uncertainty").
            # _represented (computed above, already used to test against
            # terminal_order_ids) is exactly this row's own order identity;
            # recorded only alongside a real dollar contribution, mirroring
            # contributing_run_ids' own gating.
            entry.setdefault("contributing_order_ids", set()).update(_represented)
            # This row may have no order_id at all (an id-less row is
            # PERMITTED to reach the ordinary confirmed-dollar path -- e.g.
            # a transient NaN/corrupted amount on an earlier scan that a
            # clean reload simply reads correctly this time, with no
            # order_id ever assigned either pass). Record its decision-time
            # identity here too whenever that's the case, not only on the
            # uncertain/sentinel branches above -- otherwise a scan that
            # legitimately resolves the SAME still-id-less row's amount
            # could never reproduce the identity it had while its amount
            # was still unresolved, permanently locking the ticker
            # uncertain even after a clean, complete re-observation (Codex
            # review, PR badMade/all-stock-dca#1171 discussion: "Retain
            # identity after resolving an anonymous row"). Gated on
            # `_represented` being empty here too, same as the branches
            # above -- see `_row_uncertain_key`'s own comment for why an
            # id-FULL row must never touch uncertain_contributor_ids.
            if _row_uncertain_key is not None:
                entry.setdefault("uncertain_contributor_ids", set()).add(_row_uncertain_key)
            # If ANY contributing prior price is unknown, the whole aggregated
            # reference is treated as unknown so the guard takes the conservative
            # missing_prior_price path rather than comparing against only the
            # known portion while silently ignoring the unknown portion.
            if entry.get("reference_price_unknown"):
                pass  # already poisoned; keep None
            elif reference_price is None:
                entry["reference_price"] = None
                entry["reference_ts"] = None
                entry["reference_price_unknown"] = True
            else:
                # Most-recent reference wins: overwrite when this run is at least as
                # recent as the run that currently owns the reference (equal keys and
                # untimestamped runs defer to later scan order, which is more recent).
                if entry["reference_price"] is None or run_ts >= entry["reference_ts"]:
                    entry["reference_price"] = reference_price
                    entry["reference_ts"] = run_ts
            # Only the ticker's FIRST contributing entry sets the base (_parsed_runs
            # is processed in chronological, parsed-generated_at order -- see above)
            # -- gated on a "seen" flag, not on the stored value being None, so a
            # first allocation with an unresolved/untrusted base permanently locks
            # the base unknown rather than letting a later run's own (possibly
            # requalified) base fill it in (Codex review: "Do not infer a
            # first-allocation base from a later run"). See
            # resolve_top_up_desired_amount_usd for how the guard consumes this.
            if not entry["selected_base_amount_usd_seen"]:
                entry["selected_base_amount_usd"] = base_amount_usd
                entry["selected_base_amount_usd_at"] = run_state.get("generated_at")
                entry["selected_base_amount_usd_seen"] = True
            # Keep the most recently scanned (chronologically last) run's identity
            # for auditability.
            entry["run_id"] = run_id
            entry["source"] = source

    return {
        ticker: PriorSameDayAllocation(
            ticker=ticker,
            amount_usd=round(entry["amount"], 2),
            reference_price=entry["reference_price"],
            run_id=entry["run_id"],
            source=entry["source"],
            reference_ts=entry["reference_ts"],
            selected_base_amount_usd=entry.get("selected_base_amount_usd"),
            selected_base_amount_usd_at=entry.get("selected_base_amount_usd_at"),
            attempt_count=entry.get("attempt_count", 0),
            contributing_run_ids=frozenset(entry.get("contributing_run_ids") or ()),
            contributing_order_ids=frozenset(entry.get("contributing_order_ids") or ()),
            uncertain_contributor_ids=frozenset(entry.get("uncertain_contributor_ids") or ()),
            attempt_run_ids=frozenset(entry.get("attempt_run_ids") or ()),
            notional_uncertain=bool(entry.get("notional_uncertain")),
        )
        for ticker, entry in aggregated.items()
    }


def load_prior_same_day_allocations_multi(
    state_roots: Sequence[str | Path],
    trading_day: date,
    *,
    boundary_et: time = MORNING_MANUAL_BOUNDARY_ET,
    include_scheduled_afternoon: bool = False,
    skip_sink: Optional[List[Path]] = None,
    unreconstructable_submission_amount_usd: Optional[float] = None,
    unreconstructable_sink: Optional[List[str]] = None,
) -> Dict[str, PriorSameDayAllocation]:
    """Merge :func:`load_prior_same_day_allocations` across several state roots.

    The afternoon guard folds in earlier same-day fills that live under sibling
    stream roots -- the morning-live root, the midday-live root, and the manual
    override reruns under ``.../manual_reruns/`` -- as well as its own task root.
    Per ticker the dollar amounts are summed and the ticker's *most recent* known
    reference price wins (by ``generated_at``; any unknown reference poisons the
    aggregate to unknown), so the afternoon run must beat that ticker's latest
    earlier entry across every stream before it tops up. Roots that do not exist
    contribute nothing, so passing production stream roots is safe on days a stream
    did not run.

    ``include_scheduled_afternoon`` is forwarded to each per-root call; see
    :func:`load_prior_same_day_allocations` for when to set it True.

    ``skip_sink`` is forwarded to each per-root call and accumulates skipped
    artifact paths across every root; see :func:`load_prior_same_day_allocations`.

    ``unreconstructable_submission_amount_usd`` is forwarded unchanged to each
    per-root call; see :func:`load_prior_same_day_allocations`.

    ``unreconstructable_sink`` is forwarded unchanged to each per-root call
    and accumulates across every root; see :func:`load_prior_same_day_allocations`.
    """
    merged: Dict[str, PriorSameDayAllocation] = {}
    for root in state_roots:
        allocations = load_prior_same_day_allocations(
            root,
            trading_day,
            boundary_et=boundary_et,
            include_scheduled_afternoon=include_scheduled_afternoon,
            skip_sink=skip_sink,
            unreconstructable_submission_amount_usd=unreconstructable_submission_amount_usd,
            unreconstructable_sink=unreconstructable_sink,
        )
        for ticker, alloc in allocations.items():
            existing = merged.get(ticker)
            if existing is None:
                merged[ticker] = alloc
                continue
            if existing.reference_price is None or alloc.reference_price is None:
                ref = None
                ref_ts = None
                ref_run_id = alloc.run_id or existing.run_id
                ref_source = alloc.source or existing.source
            else:
                # Most-recent reference wins across roots. Untimestamped allocations
                # use the floor so any timestamped one outranks them; equal keys defer
                # to the newly folded root (state_roots order = later contributor).
                existing_ts = existing.reference_ts or _TS_FLOOR
                alloc_ts = alloc.reference_ts or _TS_FLOOR
                if alloc_ts >= existing_ts:
                    ref = alloc.reference_price
                    ref_ts = alloc.reference_ts
                    # The run/source that actually supplied the winning reference
                    # price must be recorded together with it, not whichever side
                    # happens to be scanned last -- otherwise a top-up audit trail
                    # can pair a newer reference price with an older run_id.
                    ref_run_id = alloc.run_id or existing.run_id
                    ref_source = alloc.source or existing.source
                else:
                    ref = existing.reference_price
                    ref_ts = existing.reference_ts
                    ref_run_id = existing.run_id or alloc.run_id
                    ref_source = existing.source or alloc.source
            # Pick the chronologically FIRST allocation's base -- state_roots is
            # not guaranteed to be scanned in true chronological order (Codex
            # review: "Select the base from the chronologically first
            # allocation"), so compare each side's own selected_base_amount_usd_at
            # rather than assuming whichever root came first in the caller's list.
            base, base_at = _earlier_selected_base(
                existing.selected_base_amount_usd,
                existing.selected_base_amount_usd_at,
                alloc.selected_base_amount_usd,
                alloc.selected_base_amount_usd_at,
            )
            # A manual override mirrored/backfilled under multiple pooled
            # roots (documented for e.g. midday_dca/manual_reruns AND
            # ce16ba6b/manual_runs) makes each root's OWN per-root scan
            # independently find and count the SAME run's dollars, so
            # summing every root's amount_usd unconditionally records twice
            # the real spend. Only skip the addition when `alloc`'s
            # contributing run_ids are ENTIRELY already present in
            # `existing`'s (a non-empty subset) -- an unambiguous full
            # duplicate of already-counted evidence -- not on any overlap:
            # a PARTIAL overlap (this root has some run_ids already seen
            # plus at least one genuinely new one) can't be cleanly split
            # into "new dollars" vs "duplicate dollars" without a per-run_id
            # amount breakdown this aggregation doesn't track, so it falls
            # through to the existing additive merge -- summing there is
            # the conservative direction (it can only over-restrict
            # headroom, never under-restrict it), whereas silently
            # dropping a possibly-genuine contribution would risk the
            # opposite (Codex review: "Deduplicate mirrored artifacts
            # before pooling spend"). An empty alloc.contributing_run_ids
            # (no run_id resolved -- an older/legacy artifact) can never
            # be recognized as a subset either, so it always falls through
            # to the additive merge too, unchanged from today's behavior.
            #
            # Deliberately NOT also gated on order/uncertain-contributor
            # identity coverage (Codex review, PR badMade/all-stock-dca#1171
            # discussion: "Do not claim skipped anonymous dollars as
            # represented", suggesting exactly that additional gate) --
            # tried, and it broke an existing, deliberately-tested contract
            # this exact "is_full_duplicate keeps identity union
            # unconditional" design already commits to: see
            # test_load_prior_same_day_multi_full_duplicate_merge_still_
            # unions_order_ids (near_close_dca.py) and
            # test_compute_auto_derived_prior_allocations_full_duplicate_
            # merge_unions_order_ids (run_dca.py) -- a sibling root's copy
            # of the SAME run_id exposing an extra order the other root's
            # copy never saw is treated as a full dollar duplicate ON
            # PURPOSE (existing's own total is kept, not additively
            # inflated by a divergent mirror), while the extra identity is
            # unioned in anyway precisely so a LATER pass matching against
            # it is not mistaken for "this order was never observed" --
            # the reverse of what gating this check would accomplish. This
            # pre-existing, tested tradeoff already accepts the same
            # coincidental-match risk Codex describes for
            # contributing_order_ids; uncertain_contributor_ids' identical
            # treatment just extends that SAME established contract
            # consistently, not a new regression.
            is_full_duplicate = bool(
                alloc.contributing_run_ids
            ) and alloc.contributing_run_ids <= existing.contributing_run_ids
            if is_full_duplicate:
                merged_amount = existing.amount_usd
                merged_contributing_run_ids = existing.contributing_run_ids
            else:
                merged_amount = round(existing.amount_usd + alloc.amount_usd, 2)
                merged_contributing_run_ids = (
                    existing.contributing_run_ids | alloc.contributing_run_ids
                )
            # order_ids are ALWAYS unioned, independent of is_full_duplicate:
            # is_full_duplicate is decided on run_id subset alone, but one
            # run_id can expose multiple distinct orders for the same
            # ticker, so a root whose run_ids are a full subset of
            # existing's can still carry an order identity existing has
            # never seen (e.g. an uncertain order discovered only in this
            # root under the same run_id). Restricting the union to the
            # non-duplicate branch would drop that identity and let a later
            # reload's equal order-id set wrongly look like a provenance
            # match (Codex review: "Preserve uncertain order IDs across
            # duplicate-root merges").
            merged_contributing_order_ids = (
                existing.contributing_order_ids | alloc.contributing_order_ids
            )
            # Same reasoning, same union, for id-less uncertain contributors:
            # a root whose run_ids are a full subset of existing's can still
            # carry a synthetic identity existing has never seen, and
            # dropping it would let a later reload's equal
            # uncertain_contributor_ids set wrongly look like proof this
            # root's own anonymous contributor was re-verified.
            merged_uncertain_contributor_ids = (
                existing.uncertain_contributor_ids | alloc.uncertain_contributor_ids
            )
            # Attempt-count dedup is decided INDEPENDENTLY of the dollar dedup
            # above, using attempt_run_ids (a strict superset of
            # contributing_run_ids that also covers zero-dollar attempts). A
            # mirrored zero-notional attempt (e.g. the same rejected order
            # backfilled under both midday_dca/manual_reruns and
            # ce16ba6b/manual_runs) never enters contributing_run_ids at all
            # (it contributed no dollars), so is_full_duplicate above is
            # always False for it and the additive branch double-counts the
            # same broker attempt against max_orders_per_day (Codex review:
            # "Deduplicate mirrored zero-notional attempts"). Same subset
            # logic as the dollar check: a full subset is an unambiguous
            # duplicate; a partial overlap falls through to the conservative
            # additive sum, same as "Count every prior buy attempt toward the
            # daily limit" already established.
            is_full_attempt_duplicate = bool(
                alloc.attempt_run_ids
            ) and alloc.attempt_run_ids <= existing.attempt_run_ids
            if is_full_attempt_duplicate:
                merged_attempt_count = existing.attempt_count
                merged_attempt_run_ids = existing.attempt_run_ids
            else:
                merged_attempt_count = existing.attempt_count + alloc.attempt_count
                merged_attempt_run_ids = (
                    existing.attempt_run_ids | alloc.attempt_run_ids
                )
            merged[ticker] = PriorSameDayAllocation(
                ticker=ticker,
                amount_usd=merged_amount,
                reference_price=ref,
                run_id=ref_run_id,
                source=ref_source,
                reference_ts=ref_ts,
                selected_base_amount_usd=base,
                selected_base_amount_usd_at=base_at,
                attempt_count=merged_attempt_count,
                contributing_run_ids=merged_contributing_run_ids,
                contributing_order_ids=merged_contributing_order_ids,
                uncertain_contributor_ids=merged_uncertain_contributor_ids,
                attempt_run_ids=merged_attempt_run_ids,
                # OR-combined, not overwritten: a ticker unreconstructable
                # in ANY contributing root still carries a fail-closed
                # sentinel amount folded into merged_amount above, so the
                # merged allocation is exactly as uncertain regardless of
                # what any OTHER root resolved cleanly.
                notional_uncertain=existing.notional_uncertain or alloc.notional_uncertain,
            )
    return merged


class _ManualTopUpAllocation(Protocol):
    prior_usd: float
    reference_price: Optional[float]
    order_ids: List[str]
    sources: List[str]
    attempt_count: int
    reference_ts: Optional[int]
    notional_uncertain: bool


def _manual_uncertain_contributor_key(ticker: str, alloc: "_ManualTopUpAllocation") -> str:
    """Stable synthetic identity for an uncertain bare-manual-CSV contribution.

    Mirrors _synthetic_uncertain_contributor_key's purpose for the core
    loader's candidate rows, but ``alloc`` (a
    scripts.run_classification.PriorAllocation) is already a per-ticker
    AGGREGATE across possibly several CSV rows -- it carries no per-row
    decision fields to hash. ``sources`` (the contributing CSV/root paths)
    is the finest-grained identity available, mirroring how the core
    loader's ticker-level unreconstructable_submitted_tickers sentinel is
    keyed on its own contributing artifact path rather than a decision
    hash, for the identical reason.
    """
    root = ",".join(sorted(alloc.sources)) if alloc.sources else "no-source"
    return f"uncertain:{ticker}:manual:{root}"


def merge_manual_top_up_context(
    prior_same_day_allocations: Dict[str, PriorSameDayAllocation],
    manual_context: Mapping[str, _ManualTopUpAllocation],
) -> None:
    """Fold same-day MANUAL fills into a top-up guard's prior-allocation input.

    ``load_prior_same_day_allocations[_multi]`` reads a manual run's fills from its
    embedded ``buy_candidates`` or, absent those, a recorded
    ``artifacts.orders_csv_path`` -- it has no way to find a fill that lives ONLY in
    a sibling orders CSV the run_state never names (see
    ``scripts.run_classification.load_same_day_top_up_context``, a
    :class:`scripts.run_classification.PriorAllocation` map, which scans
    ``top_up_context_roots()`` and also recognizes a bare sibling ``*orders.csv``).
    Jul 21 2026 incident: the 3:20 final run correctly excluded the manual midday
    fills under ``midday_dca/manual_runs/20260721_1345ET`` from scheduled evidence,
    but never loaded them as prior-allocation context, leaving ``prior_usd`` blank
    and ``incremental_usd`` 0 for MSFT/GOOGL/GOOG/MA/IBM despite the fills being on
    disk. This merges the two loaders' results the same way ``load_prior_same_day_
    allocations_multi`` folds in multiple roots: dollar amounts sum, and the ticker's
    MOST RECENT valid reference wins by comparing each side's own recency (ET
    seconds-of-day, not just minutes -- Codex review: "Retain sub-minute
    generated-at ordering" -- two artifacts in the same ET minute must not tie;
    both loaders are already scoped to the same single trading_day, so a
    seconds-of-day comparison is sufficient) -- NOT simply the manual fill,
    which is merged last but is not necessarily more recent (Codex review:
    "Preserve the manual-context timestamp when merging references" -- a 09:00
    manual fill must not out-rank a 12:30 scheduled fill just because it is folded
    in after it). The run_id/source recorded travels with whichever side's
    reference price actually won (Codex review: "Keep the winning manual
    reference's identity"), not unconditionally the core loader's. An unknown
    reference from either source poisons the aggregate to unknown, routing the
    guard to its conservative missing-price path.

    Shared by both ``run_dca.py`` (the 3:30 afternoon guard) and
    ``morning_dca.py``'s ``MorningDCAExecutor._compute_top_up`` (the 10:30/12:30
    morning and midday guards -- Codex review: "Wire manual CSV context into the
    midday guard"): the policy documented in config/run_classification.json
    requires every same-day guard to fold these manual artifacts in, not just the
    afternoon one.

    These manual fills stay prior-allocation context ONLY -- merging them here never
    makes their order IDs scheduled evidence; ``collect_manual_order_ids`` still
    excludes them from every scheduled-live metric.
    """
    for ticker, alloc in manual_context.items():
        if alloc.prior_usd <= 0 and not alloc.notional_uncertain:
            continue
        existing = prior_same_day_allocations.get(ticker)
        if existing is None:
            prior_same_day_allocations[ticker] = PriorSameDayAllocation(
                ticker=ticker,
                amount_usd=alloc.prior_usd,
                reference_price=alloc.reference_price,
                run_id=(alloc.sources[0] if alloc.sources else None),
                source="manual_top_up_context",
                # PriorAllocation.attempt_count is a genuine per-ROW count
                # (one per qualifying CSV order, not one per contributing
                # run) -- len(alloc.sources) undercounted whenever one bare
                # manual/recovery CSV contained multiple distinct orders for
                # the same ticker, reconstructing several real broker
                # attempts as a single one against the shared
                # max_orders_per_day breaker (Codex review: "Count each
                # fallback CSV order as an attempt"). Falls back to 1 only
                # for a PriorAllocation built by some other, older
                # construction site that never populated attempt_count.
                attempt_count=alloc.attempt_count or 1,
                # alloc.order_ids is a bare CSV row's own broker order_id(s)
                # -- real provenance, not synthetic -- so it belongs in
                # contributing_order_ids the same as any other known order
                # (Codex review, PR badMade/all-stock-dca#1171 discussion:
                # "Track the manual contributor before preserving
                # provenance"). Dropping it here left a manual fill with a
                # real order_id looking id-less to every later provenance
                # check.
                contributing_order_ids=frozenset(alloc.order_ids or ()),
                uncertain_contributor_ids=(
                    frozenset({_manual_uncertain_contributor_key(ticker, alloc)})
                    if alloc.notional_uncertain
                    else frozenset()
                ),
                notional_uncertain=alloc.notional_uncertain,
            )
            continue
        if existing.reference_price is None or alloc.reference_price is None:
            # Either side being unknown still poisons the aggregate to unknown.
            ref = None
            ref_ts = None
            ref_run_id = existing.run_id
            ref_source = existing.source or "manual_top_up_context"
        else:
            # Compare actual recency (ET seconds-of-day, not just minutes --
            # Codex review: "Retain sub-minute generated-at ordering") rather
            # than always letting the manual fill win merely because it is
            # merged last. scripts.run_classification.PriorAllocation.reference_ts
            # is ET seconds-since-midnight; existing.reference_ts (this
            # module's own datetime) is reduced to the same seconds-of-day for
            # comparison, since both loaders are already scoped to the same
            # trading_day. Untimestamped on either side defers to the manual
            # fill (merged last), matching the "ties/untimestamped defer to
            # later scan/merge order" convention used elsewhere in this module.
            existing_seconds = (
                existing.reference_ts.hour * 3600
                + existing.reference_ts.minute * 60
                + existing.reference_ts.second
                if existing.reference_ts is not None
                else None
            )
            alloc_seconds = alloc.reference_ts
            if (
                existing_seconds is not None
                and alloc_seconds is not None
                and existing_seconds > alloc_seconds
            ):
                ref = existing.reference_price
                ref_ts = existing.reference_ts
                ref_run_id = existing.run_id
                ref_source = existing.source or "manual_top_up_context"
            else:
                ref = alloc.reference_price
                # The manual side's real datetime isn't available (only its ET
                # seconds-of-day), so this can't be represented exactly here.
                ref_ts = None
                # The manual context's own identity travels with its winning
                # reference price -- pairing a manual reference with the
                # scheduled run's identity would point reconciliation at the
                # wrong artifact (Codex review: "Keep the winning manual
                # reference's identity").
                ref_run_id = alloc.sources[0] if alloc.sources else None
                ref_source = "manual_top_up_context"
        # PriorAllocation (scripts.run_classification) carries no full datetime,
        # but its reference_ts (ET seconds-of-day, same trading_day as
        # `existing`) DOES let us compare against `existing.selected_base_amount_
        # usd_at` -- reduced to the same ET seconds-of-day -- to tell whether
        # this bare-CSV-only manual fill happened before or after the run that
        # established `existing`'s base (Codex review discussion_r3653976740:
        # "Preserve the known base when a later manual fill is merged"). Retain
        # `existing`'s base only when the manual fill is CONFIRMED later: an
        # earlier scheduled allocation's known base is still the true first
        # allocation's base regardless of a later manual top-up being merged in.
        # When the manual fill may be EARLIER (or either timestamp is unknown),
        # it could itself be the true first allocation, whose base a bare CSV
        # cannot tell us -- poison to unknown rather than risk a stale/wrong
        # base doubling the full-day target (Codex review: "Keep the base
        # unknown after merging an earlier manual fill") -- this mirrors
        # reference_price's own poison-on-uncertainty policy above.
        base = None
        base_at = None
        if (
            existing.selected_base_amount_usd is not None
            and alloc.reference_ts is not None
        ):
            existing_base_dt = _prior_run_timestamp(
                existing.selected_base_amount_usd_at
            )
            if existing_base_dt is not None:
                existing_base_seconds = (
                    existing_base_dt.hour * 3600
                    + existing_base_dt.minute * 60
                    + existing_base_dt.second
                )
                if alloc.reference_ts > existing_base_seconds:
                    base = existing.selected_base_amount_usd
                    base_at = existing.selected_base_amount_usd_at
        prior_same_day_allocations[ticker] = PriorSameDayAllocation(
            ticker=ticker,
            amount_usd=existing.amount_usd + alloc.prior_usd,
            reference_price=ref,
            run_id=ref_run_id,
            source=ref_source,
            reference_ts=ref_ts,
            selected_base_amount_usd=base,
            selected_base_amount_usd_at=base_at,
            attempt_count=existing.attempt_count + (alloc.attempt_count or 1),
            # `existing`'s own sets are carried forward -- NOT dropped by a
            # bare `PriorSameDayAllocation(...)` construction's empty
            # defaults, which would silently discard whatever `existing`
            # had. This function runs inside
            # _compute_auto_derived_prior_allocations, called separately for
            # BOTH passes of run_dca.py's bounded reload -- if it drops
            # contributing_order_ids/uncertain_contributor_ids here, the
            # merge's own provenance check can no longer see them on EITHER
            # side, and an empty set is vacuously a subset of anything,
            # silently reopening exactly the wrong-clear hole this whole
            # provenance mechanism exists to close (Codex review, PR
            # badMade/all-stock-dca#1171 discussion: "Preserve anonymous
            # provenance through manual-context merging").
            #
            # `alloc`'s OWN order_ids are unioned in too -- a bare manual CSV
            # row DOES carry real broker order_id provenance of its own
            # (scripts.run_classification.PriorAllocation.order_ids), which
            # the first version of this fix wrongly assumed didn't exist and
            # silently dropped (Codex review, PR badMade/all-stock-dca#1171
            # discussion: "Track the manual contributor before preserving
            # provenance"). And when `alloc` itself is uncertain (a manual
            # row whose own committed notional couldn't be reconstructed --
            # see PriorAllocation.notional_uncertain's own docstring), it
            # gets a synthetic identity of its own here too, the same way an
            # id-less core-loader row does, so a later scan where THIS
            # manual uncertainty disappears or is replaced by an unrelated
            # contributor can't coincidentally satisfy the equal/superset
            # provenance check on `existing`'s core-order identity alone.
            contributing_run_ids=existing.contributing_run_ids,
            contributing_order_ids=(
                existing.contributing_order_ids | frozenset(alloc.order_ids or ())
            ),
            uncertain_contributor_ids=(
                existing.uncertain_contributor_ids
                | (
                    frozenset({_manual_uncertain_contributor_key(ticker, alloc)})
                    if alloc.notional_uncertain
                    else frozenset()
                )
            ),
            attempt_run_ids=existing.attempt_run_ids,
            notional_uncertain=existing.notional_uncertain or alloc.notional_uncertain,
        )


# Mutually exclusive reasons an active-universe ticker did not produce a filled order.
MISSING_FILL_FAILED_TRIGGER = "failed DCA trigger"
MISSING_FILL_BUDGET_CAPPED = "budget capped"
MISSING_FILL_BROKER_BLOCKED = "broker/tradability/order review blocked"
MISSING_FILL_DATA_ERROR = "data error"
MISSING_FILL_EXECUTION_GAP = "execution gap"
# The scheduled afternoon buy was fully offset by an earlier same-day (morning/manual)
# allocation via the top-up guard; no incremental order was placed.
MISSING_FILL_TOP_UP_OFFSET = "top-up offset"
# A whole-share BUY trigger fired and its contribution was accumulated into
# dca_whole_share_accumulator.py's ledger, but the running total is still
# below one share's price -- deliberate, expected non-order, not a failure
# of any kind. Without its own reason, classify_missing_fill would fall
# through to MISSING_FILL_FAILED_TRIGGER (the trigger did NOT fail; it
# succeeded and accumulated) since decision.action == Action.BUY and no
# loop_block_reasons entry was ever recorded for this ticker (Codex review:
# "Classify below-threshold accumulation in coverage reports").
MISSING_FILL_ACCUMULATING = "whole-share accumulating"

MISSING_FILL_REASONS = (
    MISSING_FILL_FAILED_TRIGGER,
    MISSING_FILL_BUDGET_CAPPED,
    MISSING_FILL_BROKER_BLOCKED,
    MISSING_FILL_DATA_ERROR,
    MISSING_FILL_EXECUTION_GAP,
    MISSING_FILL_TOP_UP_OFFSET,
    MISSING_FILL_ACCUMULATING,
)


@dataclass
class OrderExecutionRecord:
    """Durable per-order target and slippage log for one reviewed/submitted order."""

    ticker: str
    status: str  # submitted | filled | unfilled
    order_id: Optional[str] = None
    notional_usd: float = 0.0
    action_reason: str = ""
    target_price: float = 0.0
    target_price_source: str = ""
    target_quote_time: Optional[datetime] = None
    decision_bar_close: float = 0.0
    order_submitted_at: Optional[datetime] = None
    order_filled_at: Optional[datetime] = None
    avg_fill_price: Optional[float] = None
    quantity_filled: Optional[float] = None
    slippage_abs: Optional[float] = None
    slippage_pct: Optional[float] = None
    slippage_cost: Optional[float] = None
    latency_seconds: Optional[float] = None
    execution_quality: str = "unfilled"


def classify_execution_quality(slippage_pct: Optional[float]) -> str:
    """Bucket an order by absolute slippage percentage. None means no fill."""
    if slippage_pct is None:
        return "unfilled"
    magnitude = abs(slippage_pct)
    if magnitude < 0.10:
        return "excellent"
    if magnitude < 0.25:
        return "good"
    if magnitude < 0.50:
        return "acceptable"
    return "poor"


def build_execution_record(
    *,
    ticker: str,
    target_price: float,
    target_price_source: str,
    decision_bar_close: float,
    notional_usd: float,
    action_reason: str = "",
    order_id: Optional[str] = None,
    target_quote_time: Optional[datetime] = None,
    order_submitted_at: Optional[datetime] = None,
    order_filled_at: Optional[datetime] = None,
    avg_fill_price: Optional[float] = None,
    quantity_filled: Optional[float] = None,
    force_filled: bool = False,
) -> OrderExecutionRecord:
    """Compute slippage and latency for a submitted order against its target price.

    For a buy, positive slippage means the average fill was above the target price
    (unfavorable). slippage_cost is the extra dollars paid versus target across the
    filled quantity. Records without a fill are marked ``submitted``.

    ``force_filled`` marks the record ``"filled"`` even when ``avg_fill_price``/
    ``quantity_filled`` are unavailable -- for a crash-lease recovery whose
    ``executed_notional`` alone confirmed the fill (a supported terminal
    history row can report ``state="filled"`` and a positive
    ``executed_notional`` with no separate price/quantity breakdown). Without
    it, such a recovery was recorded as ``"submitted"`` despite being a
    broker-confirmed fill, undercounting ``filled_order_count``/
    ``total_filled_notional`` (Codex review: "Mark executed-notional
    recoveries as filled"). Slippage still requires the granular fields --
    there is nothing to compare against without them -- so this never
    fabricates a slippage figure.
    """
    filled = avg_fill_price is not None and quantity_filled is not None
    slippage_abs: Optional[float] = None
    slippage_pct: Optional[float] = None
    slippage_cost: Optional[float] = None
    latency_seconds: Optional[float] = None

    if filled and target_price and avg_fill_price is not None and quantity_filled is not None:
        # Gated on a real (nonzero) target, not just ``filled``: a recovered
        # crash-lease fire has no ReconciledDecision and so no real target
        # price to compare against (target_price=0.0, a deliberate "no
        # target" sentinel -- see the recovered-fire execution-record call
        # below). Computing slippage_abs/slippage_cost against that zero
        # priced every recovered fill's ENTIRE notional as unfavorable
        # slippage, inflating the run's net_slippage_cost by the full
        # purchase amount with no real comparison behind it (Codex review:
        # "Do not price recovered slippage against zero"). slippage_pct
        # already carried this same guard; extend it to the two fields that
        # feed the aggregate slippage-cost total.
        slippage_abs = avg_fill_price - target_price
        slippage_pct = slippage_abs / target_price * 100.0
        slippage_cost = slippage_abs * quantity_filled
    if order_submitted_at is not None and order_filled_at is not None:
        try:
            latency_seconds = (order_filled_at - order_submitted_at).total_seconds()
        except TypeError:
            # Mixed timezone awareness -- e.g. a broker adapter's
            # get_order_fill() returns one aware and one naive timestamp for
            # the same recovered order. datetime subtraction raises
            # TypeError for that combination even though both values parsed
            # fine individually. This runs after the crash lease was already
            # durably cleared, so raising here would abort the whole
            # recovery-publish loop before the execution record/outcome is
            # published, with no lease left to retry it from (Codex review:
            # "Contain invalid recovery timestamps after the fill lookup").
            # Treated the same as an unparseable timestamp: latency
            # unavailable.
            latency_seconds = None

    return OrderExecutionRecord(
        ticker=ticker,
        status="filled" if (filled or force_filled) else "submitted",
        order_id=order_id,
        notional_usd=notional_usd,
        action_reason=action_reason,
        target_price=target_price,
        target_price_source=target_price_source,
        target_quote_time=target_quote_time,
        decision_bar_close=decision_bar_close,
        order_submitted_at=order_submitted_at,
        order_filled_at=order_filled_at,
        avg_fill_price=avg_fill_price,
        quantity_filled=quantity_filled,
        slippage_abs=slippage_abs,
        slippage_pct=slippage_pct,
        slippage_cost=slippage_cost,
        latency_seconds=latency_seconds,
        execution_quality=classify_execution_quality(slippage_pct),
    )


def _log_execution(
    run_result: "RunResult",
    decision: ReconciledDecision,
    order_id: Optional[str],
    broker: BrokerAdapter,
    *,
    notional_usd: Optional[float] = None,
    known_fill: Optional[OrderFill] = None,
) -> None:
    """Fetch fill details for a placed order and append a durable execution record.

    ``notional_usd`` overrides ``decision.suggested_amount_usd`` when the actual
    submitted amount differs (e.g. the top-up guard's incremental dollar amount or
    the kill-switch's mid-batch cap in ``run_once``), so the durable
    orders.csv/execution record matches what was really ordered.

    ``known_fill``, when given, is used INSTEAD of querying
    ``broker.get_order_fill()`` -- for a caller that already has
    authoritative fill evidence from elsewhere (e.g.
    ``WholeSharePlacementTerminalError``'s own placement-response payload,
    itself the reason a separate order-history lookup exists: that history
    can be eventually consistent). Re-querying it anyway risked a clean
    miss silently discarding a PROVEN partial fill, recording it as
    "submitted"/unfilled instead of "filled" and corrupting
    filled_orders.csv, slippage, and missing-fill coverage with data this
    call already had (Codex review: "Log terminal-response fills without
    re-querying history").
    """
    fill: Optional[OrderFill] = known_fill
    if fill is None:
        get_fill = getattr(broker, "get_order_fill", None)
        if callable(get_fill):
            res = get_fill(order_id)
            if isinstance(res, OrderFill):
                fill = res
    record = build_execution_record(
        ticker=decision.ticker,
        target_price=decision.target_price,
        target_price_source=decision.target_price_source,
        target_quote_time=decision.target_quote_time,
        decision_bar_close=decision.decision_bar_close,
        notional_usd=(
            notional_usd if notional_usd is not None else decision.suggested_amount_usd
        ),
        action_reason=decision.reason,
        order_id=order_id,
        order_submitted_at=fill.order_submitted_at if fill else None,
        order_filled_at=fill.order_filled_at if fill else None,
        avg_fill_price=fill.avg_fill_price if fill else None,
        quantity_filled=fill.quantity_filled if fill else None,
    )
    run_result.execution_records.append(record)
    # A submitted order that never returned a fill is an execution gap, not a
    # trigger/budget/broker failure, so classify it explicitly for coverage.
    if record.status != "filled":
        run_result.loop_block_reasons[decision.ticker] = MISSING_FILL_EXECUTION_GAP


def classify_missing_fill(
    decision: Optional[ReconciledDecision], loop_reason: Optional[str]
) -> str:
    """Classify why an active-universe ticker produced no filled order.

    ``loop_reason`` is the outcome recorded during the order loop (cap, broker, gap),
    which takes precedence. Otherwise the reconciled action determines the category.
    """
    if loop_reason:
        return loop_reason
    action = decision.action if decision else Action.NO_DATA
    if action == Action.NO_DATA or (
        decision is not None and _decision_had_provider_error(decision)
    ):
        # A provider exception is a data problem even when reconciliation degraded
        # it to MANUAL_REVIEW instead of NO_DATA; report it as such so outages
        # surface in the "data error" bucket rather than "failed DCA trigger".
        return MISSING_FILL_DATA_ERROR
    # SKIP / NO_ACTION / MANUAL_REVIEW: no reconciled auto-buy was triggered.
    return MISSING_FILL_FAILED_TRIGGER


def _decision_had_provider_error(decision: ReconciledDecision) -> bool:
    return any(
        signal is not None and signal.provider_error
        for signal in (decision.finance_signal, decision.robinhood_signal)
    )


@dataclass
class RunResult:
    trading_day: date
    decisions: List[ReconciledDecision]
    execution_records: List[OrderExecutionRecord] = field(default_factory=list)
    # ticker -> missing-fill reason captured during the order loop (cap/broker/gap).
    loop_block_reasons: Dict[str, str] = field(default_factory=dict)
    active_universe: List[str] = field(default_factory=list)
    # Kept last so existing positional callers (e.g. RunResult(day, decisions,
    # execution_records)) keep binding to the same fields -- codex review
    # discussion_r3692009447.
    run_label: str = "manual"
    scheduled: bool = False
    # The EXACT bytes _finalize_and_write_artifacts's own write_run_artifacts()
    # call just wrote to run_state.json, stashed here rather than left for a
    # caller to re-read from disk. A caller that re-reads the path instead (as
    # run_daily_compact's own "own state" snapshot used to) can race a
    # concurrent peer's write in the gap between this call's internal lock
    # release and that later unlocked read, silently capturing the PEER's
    # bytes as though they were this invocation's own (Codex review: "Capture
    # this invocation's state at publication time"). None until
    # _finalize_and_write_artifacts runs, or if it never does (artifacts_dir
    # is None, or run_once() raised before reaching it).
    published_run_state_bytes: Optional[bytes] = None
    # Set by _archive_intraday_observations when it detects, under the
    # run_state.json lock, that a PEER has replaced this invocation's own
    # published state since publication -- the path now holds the peer's
    # bytes, not this invocation's validated ones. _finalize_and_write_
    # artifacts's own contract_ok is computed from THIS invocation's own
    # write, before this later check can run; without this flag it stayed
    # True and went on to publish latest_scheduled_run.json pointing at a
    # path whose current content was never actually validated as this
    # invocation's own (Codex review: "Propagate archive ownership
    # rejection before publishing the pointer").
    archive_ownership_rejected: bool = False


@dataclass
class ReportResult:
    generated_at: datetime
    run_label: str
    ranked_slippage: List[OrderExecutionRecord]
    top_slippage_tickers: List[str]
    missing_fills: Dict[str, str]
    metrics: Dict[str, Any]
    report_path: Optional[str] = None
    csv_path: Optional[str] = None


def _percentile(sorted_values: Sequence[float], pct: float) -> float:
    """Linear-interpolation percentile (pct in [0, 100]); empty -> 0.0."""
    if not sorted_values:
        return 0.0
    if len(sorted_values) == 1:
        return sorted_values[0]
    rank = pct / 100.0 * (len(sorted_values) - 1)
    low = int(rank)
    high = min(low + 1, len(sorted_values) - 1)
    frac = rank - low
    return sorted_values[low] * (1.0 - frac) + sorted_values[high] * frac


def build_report(
    run_result: RunResult, run_label: str, generated_at: datetime
) -> ReportResult:
    """Assemble the slippage/coverage report data (no file I/O)."""
    filled = [r for r in run_result.execution_records if r.status == "filled"]
    # A force_filled record confirmed only through executed_notional (no
    # avg_fill_price/quantity_filled breakdown) has slippage_pct=None --
    # there is nothing to compare against a target with. Treating that
    # missing value as 0.0 for ranking purposes let an unmeasured recovery
    # (execution_quality="unfilled" despite status="filled") occupy a "Top
    # Slippage Names" slot next to genuinely measured orders, or dominate
    # the ranking entirely on a run with no measurable fills at all (Codex
    # review: "Exclude unmeasured fills from slippage rankings"). Still
    # counted in filled_order_count/total_filled_notional below -- only
    # excluded from the ranking itself.
    measured = [r for r in filled if r.slippage_pct is not None]
    ranked = sorted(measured, key=lambda r: abs(r.slippage_pct or 0.0), reverse=True)
    top_tickers = [r.ticker for r in ranked[:3]]

    decision_by_ticker = {d.ticker: d for d in run_result.decisions}
    # A recovered crash-lease fill's ticker alone does not prove THIS run's
    # own current-cycle candidate for that ticker filled: the synthetic
    # "<ticker>#imart-recovery" key exists precisely so an older, unrelated
    # recovered order can coexist with a distinct current candidate for the
    # same ticker (Codex review: "Do not let recovery fills cover separate
    # same-ticker orders"). Only trusted to mark a ticker covered when there
    # is no separate current decision for it, or that decision IS itself the
    # recovery (decisions_by_ticker gets replaced with the synthetic fire
    # decision when the recovery and this cycle's fire are the same event --
    # see the recovery-publish loop in _run_once_impl).
    filled_tickers = set()
    for r in filled:
        if r.action_reason == "recovered_inverse_martingale_lease":
            _decision = decision_by_ticker.get(r.ticker)
            if _decision is not None and _decision.reason != "recovered_inverse_martingale_lease":
                continue
        filled_tickers.add(r.ticker)
    missing: Dict[str, str] = {}
    for ticker in run_result.active_universe:
        if ticker in filled_tickers:
            continue
        missing[ticker] = classify_missing_fill(
            decision_by_ticker.get(ticker),
            run_result.loop_block_reasons.get(ticker),
        )

    reason_counts: Dict[str, int] = {reason: 0 for reason in MISSING_FILL_REASONS}
    for reason in missing.values():
        reason_counts[reason] = reason_counts.get(reason, 0) + 1

    # ⚡ Bolt Optimization: Consolidate multiple O(N) generator expression passes
    # into a single manual loop to calculate notional, slippage cost, and abs_pcts.
    total_filled_notional = 0.0
    net_slippage_cost = 0.0
    abs_pcts = []
    for r in filled:
        # A recovered crash-lease fire's notional_usd is the AUTHORITATIVE
        # executed amount (im_recovery.recovered_amount_usd, sourced from
        # _recovered_broker_notional -- which itself prefers the broker's
        # own executed_notional over a quantity*price reconstruction for
        # exactly this reason: two separately-rounded fields can land a
        # fraction of a cent off a genuine whole-cent fill). It must win
        # even when get_order_fill()'s granular price/quantity ALSO happen
        # to be present and their product merely disagrees with it -- e.g.
        # a $7 executed notional with quantity 2 and a rounded $3 price
        # reports only $6 through the product (Codex review: "Prefer
        # authoritative recovered notional in reports"). For every other
        # (non-recovery) record, notional_usd is the SUBMITTED/target
        # amount, not necessarily what executed, so the granular product
        # remains the more precise figure there; a force_filled record with
        # no granular breakdown at all still falls back to notional_usd
        # (Codex review: "Include executed-notional-only fills in the
        # reported notional").
        if r.action_reason == "recovered_inverse_martingale_lease":
            total_filled_notional += r.notional_usd or 0.0
        elif r.avg_fill_price is not None and r.quantity_filled is not None:
            total_filled_notional += r.avg_fill_price * r.quantity_filled
        else:
            total_filled_notional += r.notional_usd or 0.0
        net_slippage_cost += r.slippage_cost or 0.0
        if r.slippage_pct is not None:
            abs_pcts.append(abs(r.slippage_pct))
    abs_pcts.sort()

    metrics: Dict[str, object] = {
        "filled_order_count": len(filled),
        "total_filled_notional": round(total_filled_notional, 6),
        "net_slippage_cost": round(net_slippage_cost, 6),
        "mean_abs_slippage_pct": (
            round(statistics.fmean(abs_pcts), 6) if abs_pcts else 0.0
        ),
        "median_abs_slippage_pct": (
            round(statistics.median(abs_pcts), 6) if abs_pcts else 0.0
        ),
        "p90_abs_slippage_pct": round(_percentile(abs_pcts, 90.0), 6),
        "top_slippage_tickers": top_tickers,
        "missing_fill_count": len(missing),
        "missing_fill_reasons": {k: v for k, v in reason_counts.items() if v},
    }

    return ReportResult(
        generated_at=generated_at,
        run_label=run_result.run_label,
        ranked_slippage=ranked,
        top_slippage_tickers=top_tickers,
        missing_fills=missing,
        metrics=metrics,
    )


_CSV_FIELDS = [
    "ticker",
    "status",
    "order_id",
    "notional_usd",
    "action_reason",
    "target_price",
    "target_price_source",
    "target_quote_time",
    "decision_bar_close",
    "order_submitted_at",
    "order_filled_at",
    "avg_fill_price",
    "quantity_filled",
    "slippage_abs",
    "slippage_pct",
    "slippage_cost",
    "latency_seconds",
    "execution_quality",
]


def _iso(value: object) -> Any:
    return value.isoformat() if isinstance(value, datetime) else value


def write_execution_csv(records: Sequence[OrderExecutionRecord], path: str) -> str:
    """Write the durable per-order execution/slippage log to CSV."""
    os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    with atomic_open_w(path, newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=_CSV_FIELDS)
        writer.writeheader()
        for record in records:
            row = {
                field_name: _iso(getattr(record, field_name))
                for field_name in _CSV_FIELDS
            }
            writer.writerow(row)
    return path


def _row_fill_quantity(row: Dict[str, Any]) -> float:
    """Best-effort ``quantity_filled`` parse for comparing two CSV rows of the
    same order -- 0.0 for missing/unparseable/non-finite/negative values, so
    an unreadable field never outranks a genuinely valued one."""
    try:
        value = float(row.get("quantity_filled") or 0.0)
    except (TypeError, ValueError):
        return 0.0
    return value if math.isfinite(value) and value > 0 else 0.0


def _csv_float(value: Any) -> Optional[float]:
    """Best-effort float parse of a raw CSV field value -- ``None`` for
    missing/blank/unparseable/non-finite, matching how ``_iso``-serialized
    empty fields round-trip through ``csv.DictReader`` as ``""``."""
    if value in (None, ""):
        return None
    try:
        parsed = float(value)
    except (TypeError, ValueError, OverflowError):
        # See _alpaca_float_or_nan: an unbounded int raises rather than
        # overflowing to inf, and this parse promises None, not a raise.
        return None
    return parsed if math.isfinite(parsed) else None


def _merged_execution_row(existing_row: Dict[str, Any], new_row: Dict[str, Any]) -> Dict[str, Any]:
    """Overlay ``new_row``'s fill/status confirmation onto ``existing_row``'s
    real decision metadata, recomputing the derived fields, instead of
    replacing the row wholesale.

    A crash-lease recovery's execution record is built with no
    ``ReconciledDecision`` behind it -- ``target_price=0.0``, an empty
    ``target_price_source``, and no real ``order_submitted_at`` -- while the
    existing row it is upgrading was logged from the ORIGINAL placement's
    real decision. Replacing the row outright therefore discarded that real
    target price/source/decision close/submission time, and the resulting
    "filled" row had no computable slippage (``execution_quality`` reading
    "unfilled" despite a confirmed fill) purely because the upgrade call
    itself carried no target (Codex review: "Preserve target metadata when
    upgrading execution rows"). Only the fields a recovery can actually
    speak to -- status, order id, fill price/quantity, fill timestamp,
    notional -- are taken from ``new_row``; everything decision-derived is
    kept from ``existing_row`` unless ``existing_row`` itself lacks it.
    """
    merged = dict(existing_row)
    merged["status"] = str(new_row.get("status") or merged.get("status") or "")
    for key in ("order_id", "avg_fill_price", "quantity_filled", "order_filled_at", "notional_usd"):
        value = new_row.get(key)
        if value not in (None, ""):
            merged[key] = value
    if not (merged.get("order_submitted_at") or "").strip() and new_row.get("order_submitted_at"):
        merged["order_submitted_at"] = new_row["order_submitted_at"]
    # A terminal notional-only upgrade (new_row confirms "filled" but has no
    # avg_fill_price/quantity_filled of its own -- an executed-notional-only
    # crash-lease recovery) must not let existing_row's STALE granular fields
    # from an earlier premature partial-fill lookup survive as if they were
    # this terminal confirmation's own complete breakdown. Downstream
    # consumers (run_dca._fills_from_orders_csv/_refresh_fills_from_broker)
    # read avg_fill_price/quantity_filled as a complete fill whenever both
    # are present, with no way to know they predate the terminal notional
    # this row now authoritatively carries via notional_usd (Codex review:
    # "Clear stale granular data on notional-only upgrades").
    # Not unconditional: existing_row's own granular breakdown is only
    # STALE when it does not actually agree with the notional this recovery
    # authoritatively confirms. `avg_fill_price * quantity_filled` equal
    # (within a half-cent, the same tolerance this module already uses for
    # notional agreement -- see the `0.005` comparisons above) to the
    # recovery's own notional_usd means existing_row already reports
    # exactly this fill's real price/quantity/slippage detail; clearing it
    # anyway destroyed genuine execution-quality data a later notional-only
    # confirmation happened to reconfirm, for no reason -- it was never a
    # premature partial this recovery is upgrading (Codex review, PR
    # #859/#911 round 45: "Preserve granular data when it matches recovered
    # notional").
    _existing_price = _csv_float(existing_row.get("avg_fill_price"))
    _existing_qty = _csv_float(existing_row.get("quantity_filled"))
    _recovered_notional = _csv_float(merged.get("notional_usd"))
    _existing_matches_recovered_notional = (
        _existing_price is not None
        and _existing_qty is not None
        and _recovered_notional is not None
        and abs(_existing_price * _existing_qty - _recovered_notional) < 0.005
    )
    if (
        new_row.get("status") == "filled"
        and new_row.get("avg_fill_price") in (None, "")
        and new_row.get("quantity_filled") in (None, "")
        and not _existing_matches_recovered_notional
    ):
        merged["avg_fill_price"] = ""
        merged["quantity_filled"] = ""
        # existing_row's order_filled_at can itself be stale: an earlier
        # PARTIAL fill logged before this order went terminal. The overlay
        # loop above already carried forward new_row's own order_filled_at
        # when the terminal recovery supplied one (an authoritative
        # timestamp its own quantity-agreement gate already vetted); when it
        # did NOT, existing_row's premature value must not survive alongside
        # the now-cleared granular fields it was originally paired with --
        # _merged_execution_row recomputes latency_seconds from whatever
        # order_submitted_at/order_filled_at end up in `merged` just below,
        # so a stale filled_at otherwise reports a latency for a fill this
        # row no longer even claims a quantity for (Codex review: "Clear
        # stale partial timestamps during CSV recovery upgrades").
        if not (new_row.get("order_filled_at") or "").strip():
            merged["order_filled_at"] = ""
        # Stamped onto the merged row too, not just cleared granular fields:
        # run_dca._refresh_fills_from_broker() identifies a terminal
        # notional-only recovery by action_reason ==
        # "recovered_inverse_martingale_lease" to skip re-querying it (that
        # independent, later lookup can itself be eventually consistent and
        # return an earlier partial fill, which would otherwise get accepted
        # as this row's terminal execution detail). Leaving the EXISTING
        # row's own action_reason (e.g. "inverse_martingale_fire" from the
        # original placement) in place meant that check never recognized
        # this row as a recovery once merged, undoing the protection (Codex
        # review: "Preserve the recovery marker through CSV upgrades").
        merged["action_reason"] = "recovered_inverse_martingale_lease"

    target_price = _csv_float(merged.get("target_price"))
    avg_fill_price = _csv_float(merged.get("avg_fill_price"))
    quantity_filled = _csv_float(merged.get("quantity_filled"))
    filled = merged.get("status") == "filled" and avg_fill_price is not None and quantity_filled is not None
    slippage_abs = slippage_pct = slippage_cost = None
    if filled and target_price and avg_fill_price is not None and quantity_filled is not None:
        slippage_abs = avg_fill_price - target_price
        slippage_pct = slippage_abs / target_price * 100.0
        slippage_cost = slippage_abs * quantity_filled
    latency_seconds = None
    submitted_at = merged.get("order_submitted_at")
    filled_at = merged.get("order_filled_at")
    if submitted_at and filled_at:
        try:
            latency_seconds = (
                datetime.fromisoformat(filled_at) - datetime.fromisoformat(submitted_at)
            ).total_seconds()
        except (ValueError, TypeError):
            # TypeError, not just ValueError: a naive existing-row timestamp
            # merged with a timezone-aware recovery fill timestamp (or vice
            # versa) parses fine on both sides, but subtracting an aware
            # datetime from a naive one raises TypeError, not ValueError --
            # aborting the whole merge after the strategy state was already
            # written and losing the recovered fill (Codex review: "Handle
            # mixed timezone awareness while merging timestamps"). Treated
            # the same as an unparseable timestamp: latency unavailable.
            latency_seconds = None
    merged["slippage_abs"] = "" if slippage_abs is None else str(slippage_abs)
    merged["slippage_pct"] = "" if slippage_pct is None else str(slippage_pct)
    merged["slippage_cost"] = "" if slippage_cost is None else str(slippage_cost)
    merged["latency_seconds"] = "" if latency_seconds is None else str(latency_seconds)
    merged["execution_quality"] = classify_execution_quality(slippage_pct)
    return merged


def _merge_execution_csv(
    path: Path,
    records: Sequence[OrderExecutionRecord],
    *,
    replace_existing: bool = False,
    always_write: bool = False,
) -> None:
    """Add ``records`` not already present in the CSV at ``path``, preserving it.

    Used in two places that would otherwise clobber or lose durable execution
    rows across a retry of the same scheduled slot:

    * The afternoon failure writer, which runs after ``_run_once_impl``
      raises -- so ``run_daily_compact``'s own success-path write is never
      reached that invocation. A crash-lease recovery's fill logged to
      ``run_result.execution_records`` earlier in the SAME raising
      invocation would otherwise simply vanish: the recovered order is
      already durably "on disk" via ``submitted_orders.csv``/``run_state.json``,
      so the recovery pass never revisits it on a later retry, and nothing
      else ever gets a chance to write its execution row (Codex review:
      "Persist recovered execution rows when the batch fails").
    * ``run_daily_compact``'s own success-path write, which used to call
      ``write_execution_csv`` directly -- an unconditional full overwrite.
      A SUBSEQUENT successful retry of the same slot (after an earlier
      failed attempt had persisted a recovery's row via the path above)
      would silently truncate that row back out the moment it succeeded,
      permanently losing it: the recovery's lease is already cleared, so
      nothing will ever re-produce that row again (Codex review: "Preserve
      recovered fills through successful retries").

    Existing rows are read back as raw dicts (not reconstructed
    ``OrderExecutionRecord`` objects) purely to preserve them and to collect
    the order ids already present, so a retry that failed AGAIN after an
    earlier failure already persisted some rows does not duplicate them. A
    record with no ``order_id`` is always appended -- there is nothing to
    dedupe it against.

    ``replace_existing`` skips reading the file entirely -- for the failure
    writer's SYNTHESIZED-state case, where the existing companions (including
    any pre-existing ``orders.csv``) belong to an unreadable/foreign prior
    attempt being fully replaced, not this run's own history. Merging with it
    would attribute a stale or unrelated attempt's executions to the freshly
    synthesized state (Codex review: "Drop stale execution rows for
    synthesized failure states").

    ``always_write`` forces file creation even with nothing to write --
    matching ``write_execution_csv``'s prior unconditional-create contract
    for the success-path caller. Without it (the failure-writer's default),
    this is a no-op when there is nothing new to add, leaving a nonexistent
    file absent -- orders.csv's existing "absent when nothing was executed"
    contract for that path.

    A record whose ``order_id`` matches an existing row REPLACES it only
    when the new row reports ``status == "filled"`` and the existing one does
    not -- e.g. a crash-lease recovery that just confirmed a fill broker
    history proves, for an order an earlier crashed attempt could only log
    as "submitted" before dying (Codex review: "Upgrade persisted
    submissions when recovery confirms a fill"). Otherwise the existing row
    wins: it is the first durable record of that order and nothing here
    should un-confirm it.

    Existing rows are projected onto ``_CSV_FIELDS`` when rewritten
    (``extrasaction="ignore"``) so a file carrying a column from a newer or
    manually extended schema does not turn an otherwise successful retry
    into a ``ValueError`` (Codex review: "Normalize preserved CSV rows
    before rewriting them").
    """
    existing_rows: List[Dict[str, str]] = []
    existing_rows_by_order_id: Dict[str, int] = {}
    if not replace_existing and path.exists():
        try:
            with path.open(newline="", encoding="utf-8") as handle:
                for row in csv.DictReader(handle):
                    order_id = row.get("order_id")
                    if order_id:
                        existing_rows_by_order_id[order_id] = len(existing_rows)
                    existing_rows.append(row)
        except (OSError, csv.Error, UnicodeDecodeError):
            # Quarantine, don't discard THIS invocation's own records: a
            # corrupt/unreadable existing file is not evidence about
            # ``records``, and returning here silently dropped every new or
            # recovered execution this call was asked to persist -- a valid
            # matching run_state.json continued on to advertise the
            # untouched unreadable CSV as if the retry's own new fills had
            # nowhere to go (Codex review: "Do not drop new executions when
            # the old CSV is unreadable"). Preserving the unreadable rows
            # themselves is not attempted -- they cannot be parsed -- so
            # this falls through and rewrites the file from ``records``
            # alone, exactly like ``replace_existing``.
            logger.warning(
                "could not read existing execution CSV at %s; replacing it with this run's own records",
                path,
            )
            existing_rows = []
            existing_rows_by_order_id = {}
    elif replace_existing and not records and path.exists():
        # Nothing of THIS run's own to write, and the existing content
        # belongs to an invalid/foreign prior attempt being replaced -- it
        # must not simply survive untouched, attributed to nothing (Codex
        # review: "Replace stale execution CSVs even when the new list is
        # empty").
        try:
            path.unlink()
        except OSError:
            logger.warning("could not remove stale execution CSV at %s", path)
        if not always_write:
            # No caller expects a file here (the failure writer's default):
            # done. always_write callers (run_daily_compact's own success
            # path) fall through to the write block below instead, so the
            # stale file's removal still ends in a fresh (possibly
            # header-only) orders.csv rather than no file at all -- a
            # replace-existing invocation reusing artifacts_dir for an
            # unrelated day/slot still owes its own advertised
            # orders_csv_path a real file (Codex review: "Preserve the
            # header-only execution artifact after replacement").
            return

    new_rows: List[Dict[str, Any]] = []
    for record in records:
        row = {field_name: _iso(getattr(record, field_name)) for field_name in _CSV_FIELDS}
        existing_index = existing_rows_by_order_id.get(record.order_id) if record.order_id else None
        if existing_index is None:
            new_rows.append(row)
            continue
        existing_row = existing_rows[existing_index]
        if row.get("status") != "filled":
            continue
        # A new "filled" row wins over a non-"filled" existing one (the
        # original upgrade case), OR over an existing "filled" row that
        # reports a SMALLER filled quantity -- an order's get_order_fill()
        # lookup can report a positive PARTIAL fill (marking the row
        # "filled" without checking the order is terminal) before a later
        # crash-lease recovery supplies the FINAL, complete quantity; both
        # rows say "filled", so comparing status alone left the stale
        # partial permanently in place (Codex review: "Replace stale
        # partial-fill rows with the final recovery"). A new row reporting
        # an equal-or-smaller quantity never wins -- there is nothing to
        # upgrade to -- UNLESS the new row carries no quantity_filled/
        # avg_fill_price breakdown at all: a terminal recovery valued only
        # through executed_notional (force_filled, no granular fields)
        # reports _row_fill_quantity()==0, so the quantity comparison alone
        # never lets its authoritative terminal notional/status win over a
        # stale partial (Codex review: "Upgrade partial rows from
        # notional-only terminal recovery"). Safe to merge in that case
        # regardless: _merged_execution_row only overlays fields the new
        # row actually supplies, so an existing row's real quantity/price
        # survive untouched when the new row has none.
        if (
            existing_row.get("status") != "filled"
            or _row_fill_quantity(row) > _row_fill_quantity(existing_row)
            or (row.get("quantity_filled") in (None, "") and row.get("avg_fill_price") in (None, ""))
        ):
            existing_rows[existing_index] = _merged_execution_row(existing_row, row)
    if not new_rows and not existing_rows and not always_write:
        return
    with atomic_open_w(str(path), newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=_CSV_FIELDS, extrasaction="ignore")
        writer.writeheader()
        for row in existing_rows:
            writer.writerow(row)
        for row in new_rows:
            writer.writerow(row)


def _fmt(value: Optional[float], places: int = 4) -> str:
    return f"{value:.{places}f}" if isinstance(value, (int, float)) else "-"


def render_report_markdown(report: ReportResult, run_result: RunResult) -> str:
    """Render the DCA Manual Run Slippage and Coverage Report as markdown."""
    m = report.metrics
    lines: List[str] = []
    lines.append("# DCA Manual Run Slippage and Coverage Report")
    lines.append("")
    lines.append(f"- Run label: {report.run_label}")
    lines.append(f"- Generated at: {report.generated_at.isoformat()}")
    lines.append(f"- Trading day: {run_result.trading_day.isoformat()}")
    lines.append(f"- Filled orders: {m['filled_order_count']}")
    lines.append(f"- Total filled notional: ${_fmt(m['total_filled_notional'], 2)}")
    lines.append(f"- Net slippage cost: ${_fmt(m['net_slippage_cost'], 4)}")
    lines.append(f"- Mean abs slippage %: {_fmt(m['mean_abs_slippage_pct'])}")
    lines.append(f"- Median abs slippage %: {_fmt(m['median_abs_slippage_pct'])}")
    lines.append(f"- P90 abs slippage %: {_fmt(m['p90_abs_slippage_pct'])}")
    lines.append("")
    lines.append("## Top 3 Slippage Names")
    if report.top_slippage_tickers:
        for rank, record in enumerate(report.ranked_slippage[:3], start=1):
            lines.append(
                f"{rank}. {record.ticker}: {_fmt(record.slippage_pct)}% "
                f"(${_fmt(record.slippage_cost)} cost, {record.execution_quality})"
            )
    else:
        lines.append("_No filled orders._")
    lines.append("")
    lines.append("## Ranked Slippage (by absolute slippage %)")
    lines.append("")
    lines.append(
        "| Rank | Ticker | Target | Avg Fill | Slippage % | Slippage $ | Latency s | Quality |"
    )
    lines.append("| --- | --- | --- | --- | --- | --- | --- | --- |")
    for rank, r in enumerate(report.ranked_slippage, start=1):
        lines.append(
            f"| {rank} | {r.ticker} | {_fmt(r.target_price)} | {_fmt(r.avg_fill_price)} | "
            f"{_fmt(r.slippage_pct)} | {_fmt(r.slippage_cost)} | {_fmt(r.latency_seconds, 2)} | "
            f"{r.execution_quality} |"
        )
    if not report.ranked_slippage:
        lines.append("| - | - | - | - | - | - | - | - |")
    lines.append("")
    lines.append("## Missing Fills vs Active Universe")
    lines.append(f"- Missing fill count: {m['missing_fill_count']}")
    lines.append(f"- Reasons: {m['missing_fill_reasons'] or 'none'}")
    lines.append("")
    lines.append("| Ticker | Classification |")
    lines.append("| --- | --- |")
    for ticker in sorted(report.missing_fills):
        lines.append(f"| {ticker} | {report.missing_fills[ticker]} |")
    if not report.missing_fills:
        lines.append("| - | - |")
    lines.append("")
    return "\n".join(lines)


def generate_slippage_report(
    run_result: RunResult,
    *,
    output_dir: str,
    now: Optional[datetime] = None,
) -> ReportResult:
    """Build and persist the slippage/coverage report + durable CSV log.

    Reusable after manual or scheduled execution. Performs no interactive prompting.
    """
    generated_at = (now or datetime.now(tz=EASTERN)).astimezone(EASTERN)
    report = build_report(run_result, run_result.run_label, generated_at)
    stamp = generated_at.strftime("%Y%m%d-%H%M%S")
    base = f"dca_{run_result.run_label}_{run_result.trading_day.isoformat()}_{stamp}"
    os.makedirs(output_dir, exist_ok=True)
    csv_path = os.path.join(output_dir, f"{base}_orders.csv")
    report_path = os.path.join(output_dir, f"{base}_slippage_coverage.md")
    write_execution_csv(run_result.execution_records, csv_path)
    atomic_write_text(report_path, render_report_markdown(report, run_result))
    report.csv_path = csv_path
    report.report_path = report_path
    return report


def write_run_state(
    state_path: str,
    *,
    run_result: RunResult,
    report: ReportResult,
    config: StrategyConfig,
    state: StrategyState,
) -> str:
    """Write the manual/scheduled run-state JSON including artifact paths + metrics."""
    trading_day = run_result.trading_day
    payload = {
        "run_label": run_result.run_label,
        "scheduled": run_result.scheduled,
        "trading_day": trading_day.isoformat(),
        "generated_at": report.generated_at.isoformat(),
        "dry_run": config.dry_run,
        "artifacts": {
            "slippage_report_path": report.report_path,
            "orders_csv_path": report.csv_path,
        },
        "budget": {
            "budget_tier": state.current_tier().name,
            "day_spend": state.day_notional(trading_day),
            "week_spend": state.week_notional(trading_day),
            "weekly_rollover_reserve_usd": state.weekly_rollover_reserve_usd,
        },
        "summary_metrics": report.metrics,
    }
    os.makedirs(os.path.dirname(state_path) or ".", exist_ok=True)
    atomic_write_text(state_path, json.dumps(payload, indent=2, sort_keys=True))
    return state_path


# Warn this many approved trading days before the configured window's end, so the
# hard stop built into APPROVED_TEST_DATES / trading_window.json is never a
# surprise: past the last approved date every scheduled run is silently blocked.
APPROVED_WINDOW_EXPIRY_WARN_DAYS = 10


def approved_window_status(
    approved_dates: Iterable[date], trading_day: date
) -> Tuple[bool, Optional[date], int]:
    """Return ``(in_window, window_end, remaining_days)`` for the approved-dates gate.

    ``remaining_days`` counts approved dates on or after ``trading_day`` — how
    many approved trading days are left before the configured window stops all
    live trading. ``window_end`` is ``None`` when no approved dates are
    configured (the gate then blocks everything and there is no expiry to warn
    about).
    """
    dates = set(approved_dates)
    if not dates:
        return False, None, 0
    window_end = max(dates)
    remaining = sum(1 for day in dates if day >= trading_day)
    return trading_day in dates, window_end, remaining


def warn_if_window_expiring(
    approved_dates: Iterable[date],
    trading_day: date,
    *,
    log: logging.Logger = logger,
) -> None:
    """Log loudly when the approved trading window is over or about to end.

    Past the window's end every run is blocked by the date gate; without this
    the stop is silent (a blocked run is indistinguishable from a holiday).
    Within :data:`APPROVED_WINDOW_EXPIRY_WARN_DAYS` approved days of the end,
    every run carries a countdown warning so the operator extends
    ``config/trading_window.json`` before trading stops.
    """
    in_window, window_end, remaining = approved_window_status(
        approved_dates, trading_day
    )
    if window_end is None:
        return
    if trading_day > window_end:
        log.error(
            "approved trading window ended %s — live trading is hard-stopped; "
            "extend config/trading_window.json (or approved_test_dates) to resume",
            window_end,
        )
    elif in_window and remaining <= APPROVED_WINDOW_EXPIRY_WARN_DAYS:
        log.warning(
            "approved trading window ends %s — %d approved trading day(s) remaining; "
            "extend config/trading_window.json to avoid a silent stop",
            window_end,
            remaining,
        )


def _write_blocked_run_stub(
    trading_day: date,
    artifacts_dir: Optional[str | Path],
    classification_state_root: Optional[str | Path] = None,
    classification_overrides: Optional[Dict[str, Any]] = None,
    correlation_id: Optional[str] = None,
) -> None:
    """Record a date/holiday-gate block as a complete root-level artifact set.

    "Blocked" is an outcome, not an excuse for a partial artifact set: a consumer
    that finds only run_state.json cannot tell a deliberate calendar block from a
    run that died mid-write. The stub therefore also writes run_summary.json and
    header-only signals.csv / submitted_orders.csv at the RUN ROOT (Jul 27 2026
    12:30 and 1:30 incidents).

    The state carries a non-null ``run_classification`` and an
    ``order_submit_status`` so the set satisfies the live artifact contract and a
    consumer can attribute the directory, but also ``scheduled_evidence_denied``
    so it is never counted as scheduled evidence. Both halves matter: a stub with
    a null classification fails validate_run_artifacts and reads as malformed,
    while a stub that passed as evidence would manufacture an evidence-shaped
    artifact for a day the market was shut (Codex review).

    Nothing already on disk is clobbered: when a directory is reused, only the
    files that do not exist yet are written, so a previously recorded run keeps
    its own artifacts.

    The blocked path returns before the normal finalizer, so it also runs that
    finalizer's last two steps itself: the four-file set is validated, and when
    ``classification_state_root`` is given the same-day pointer is refreshed so a
    pointer-based watchdog sees today's slot resolved as blocked rather than
    still targeting the previous trading day (Codex review). The state carries
    ``scheduled_evidence_denied``, so the pointer publishes as ``pending`` and no
    consumer counts a market-closed day as scheduled evidence.

    ``classification_overrides``/``correlation_id`` let a non-afternoon roster
    slot (``run_dca.run_slot``'s 1030ET/1230ET) stamp its OWN stream/cron_id/
    scheduled_for_et/run_id and deterministic correlation id onto this stub,
    the same way the normal compact path does via ``build_run_artifacts``.
    Without this, a 10:30/12:30 run blocked by the date/holiday gate always
    stamped the afternoon cron/stream/time/run_id -- misattributing watchdog
    diagnosis for the slot that actually fired and losing its deterministic
    correlation id (Codex review: "Preserve slot identity on early failure
    artifacts").
    """
    if not artifacts_dir:
        return
    try:  # pragma: no cover - import shim for flat sys.path
        from scripts.scheduled_artifacts import (
            build_run_summary,
            write_signals_csv,
            write_submitted_orders_csv,
        )
    except ImportError:  # pragma: no cover
        from scheduled_artifacts import (  # type: ignore
            build_run_summary,
            write_signals_csv,
            write_submitted_orders_csv,
        )

    out = Path(artifacts_dir)
    out.mkdir(parents=True, exist_ok=True)
    state_path = out / "run_state.json"
    try:  # pragma: no cover - import shim for flat sys.path
        from scripts.run_classification import build_scheduled_classification
    except ImportError:  # pragma: no cover
        from run_classification import build_scheduled_classification  # type: ignore

    day_iso = trading_day.isoformat()
    classification = dict(build_scheduled_classification(day_iso, **(classification_overrides or {})))
    classification["valid_scheduled_evidence"] = False
    # Deliberately NO top-level run_id / generated_at. The calendar gate fired
    # before any run existed, and downstream model-usage logging keys off the
    # presence of a run_id to decide whether a run happened at all: stamping one
    # here would record a model-usage entry for a day the market was shut. The
    # nested classification still carries its own run_id for attribution.
    run_state: Dict[str, Any] = {
        "trading_day": day_iso,
        "status": RUN_STATUS_BLOCKED,
        "run_classification": classification,
        "order_submit_status": ORDER_SUBMIT_STATUS_NO_ORDERS,
        "orders_submitted_count": 0,
        "run_classification_outcome": RUN_CLASSIFICATION_COMPLETED_NO_ORDERS,
        "completion_reason": COMPLETION_REASON_DATE_GATE_BLOCKED,
        "error_class": None,
        "is_trading_failure": False,
        # The calendar gate stopped this before any slot could execute, so the
        # artifact is well-formed and attributable but never scheduled evidence.
        "scheduled_evidence_denied": True,
        "budget": {"budget_tier": "normal", "daily_cap_usd": 0, "weekly_cap_usd": 0},
        "counts": {"evaluated": 0, "buy_candidates": 0, "submitted": 0},
        "buy_candidates": [],
        "signal_rows": [],
    }
    if correlation_id is not None:
        run_state["correlation_id"] = correlation_id
    # Never clobber a previously recorded run when a directory is reused: an
    # existing run_state.json is left exactly as it is. Each remaining file is
    # guarded on its own, so a directory left partial by an interrupted or legacy
    # write is COMPLETED on the next blocked pass rather than staying partial
    # forever behind a single early return (Codex review).
    if not state_path.exists():
        atomic_write_text(state_path, _serialize_run_state(run_state))
    else:
        try:
            existing = json.loads(state_path.read_bytes())
        except (OSError, json.JSONDecodeError, UnicodeDecodeError):
            existing = None
        if isinstance(existing, dict):
            # Base the companion files on what is actually on disk, so a summary
            # written now mirrors the real run_state rather than this stub.
            run_state = existing
        else:
            # Truncated, non-UTF-8, or not an object: there is no run to preserve,
            # only a malformed file. Leaving it would let this helper write a
            # summary and CSVs around a broken root state and return successfully,
            # defeating the complete-artifact guarantee (Codex review).
            logger.warning(
                "replacing an unreadable run_state.json at %s with the blocked stub",
                state_path,
            )
            atomic_write_text(state_path, _serialize_run_state(run_state))
    if not (out / "run_summary.json").exists():
        atomic_write_text(
            out / "run_summary.json", _serialize_run_state(build_run_summary(run_state))
        )
    if not (out / "signals.csv").exists():
        write_signals_csv(out, [], fieldnames=("ticker",))
    if not (out / "submitted_orders.csv").exists():
        write_submitted_orders_csv(out, [])

    # The normal finalizer never runs on this path, so its validation and
    # pointer refresh happen here (Codex review). Validation gates the pointer
    # rather than rewriting the state: a preserved run_state -- including a
    # legacy one this helper deliberately leaves byte for byte -- is never
    # mutated, so failing closed means the directory is simply not advertised.
    try:  # pragma: no cover - import shim for flat sys.path
        from scripts.scheduled_artifacts import validate_run_artifacts
    except ImportError:  # pragma: no cover
        from scheduled_artifacts import validate_run_artifacts  # type: ignore

    contract = validate_run_artifacts(out, require_summary=True)
    if not contract:
        logger.error(
            "blocked-run artifact contract failed at %s; not refreshing the "
            "latest scheduled pointer: %s",
            out,
            "; ".join(contract.errors),
        )
        return

    if classification_state_root is None:
        return
    try:  # pragma: no cover - import shim for flat sys.path
        from scripts.run_classification import update_latest_scheduled_run_pointer
    except ImportError:  # pragma: no cover
        from run_classification import (  # type: ignore
            update_latest_scheduled_run_pointer,
        )
    try:
        update_latest_scheduled_run_pointer(
            run_state, state_path, Path(classification_state_root)
        )
    except Exception:  # noqa: BLE001 - a pointer failure never blocks the gate
        logger.exception(
            "failed to refresh the latest scheduled pointer under %s",
            classification_state_root,
        )


def _refresh_blocked_run_companions(artifacts_dir: str | Path) -> None:
    """Regenerate run_summary.json/submitted_orders.csv/buy_candidates.csv from
    the current run_state.

    ``_write_blocked_run_stub`` writes both companions ONCE, from whatever
    ``run_state.json`` held at the time (empty candidates, zero orders) and
    deliberately never touches them again -- "nothing already on disk is
    clobbered" is exactly right for its own purpose, an idempotent stub. But
    the calendar-blocked path's own fractional-placement reconciliation
    (a few lines below its call site) mutates ONLY ``run_state.json``
    afterward, via the same reconciler the gate-passing path uses -- so a
    successful gated recovery left the two companions advertising the
    pre-reconciliation zero-order state while run_state.json itself now
    named a real submitted (or proven-rejected) order, an artifact set that
    disagreed with itself (Codex review, PR #911 round 8: "Refresh
    blocked-run companions after reconciliation").

    Best-effort and non-fatal: called from the SAME isolated try/except the
    reconciliation call itself runs under, so any failure here is logged and
    swallowed exactly like a reconciliation failure would be -- the blocked
    stub that already satisfied the artifact contract must survive
    regardless.
    """
    out = Path(artifacts_dir)
    state_path = out / "run_state.json"
    try:
        run_state = json.loads(state_path.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError):
        return
    if not isinstance(run_state, dict):
        return
    try:  # pragma: no cover - import shim for flat sys.path
        from scripts.scheduled_artifacts import (
            ORDER_ATTEMPT_STATUSES,
            build_run_summary,
            validate_run_artifacts,
            write_submitted_orders_csv,
        )
    except ImportError:  # pragma: no cover
        from scheduled_artifacts import (  # type: ignore
            ORDER_ATTEMPT_STATUSES,
            build_run_summary,
            validate_run_artifacts,
            write_submitted_orders_csv,
        )

    candidates = run_state.get("buy_candidates")
    order_rows = [
        {
            "ticker": c.get("ticker"),
            "order_id": c.get("order_id"),
            "submitted_amount_usd": c.get("planned_amount_usd"),
            "status": c.get("status"),
        }
        for c in (candidates if isinstance(candidates, list) else [])
        if isinstance(c, dict)
        and c.get("status") != "dry_run"
        and (c.get("status") in ORDER_ATTEMPT_STATUSES or c.get("order_id"))
    ]
    write_submitted_orders_csv(out, order_rows)
    atomic_write_text(out / "run_summary.json", _serialize_run_state(build_run_summary(run_state)))
    # buy_candidates.csv is normally written ONCE by whichever run first
    # halted at this slot (via _write_afternoon_failure_artifacts's own
    # _failure_candidate_row rows, showing this ticker "failed"). The
    # reconciliation just above updates run_state.json's own buy_candidates
    # entry to "submitted"/proven-"failed", but never touched that earlier
    # CSV -- leaving it advertising the pre-reconciliation "failed" status
    # while run_summary.json/submitted_orders.csv (refreshed above) and
    # run_state.json itself all agree the placement resolved, an artifact
    # set disagreeing with itself the same way round 8 already fixed for
    # the other two companions (Codex review, PR #911 round 20: "Refresh
    # the candidate CSV after gated reconciliation"). Same explicit-
    # unioned-header pattern the failure writer's own equivalent write
    # uses (a merged retry's rows can come from different eras, and
    # _write_csv's default header-from-row-0 crashes the moment a later
    # row carries a key the first one lacks).
    _candidate_rows = [c for c in (candidates if isinstance(candidates, list) else []) if isinstance(c, dict)]
    # Only when there is something to write, or the file already exists
    # from an earlier failed run at this slot: a genuinely empty blocked
    # run (no prior failure, nothing reconciled) must never advertise a
    # buy_candidates.csv run_once itself never created, matching every
    # OTHER blocked-run artifact-completeness contract in this module.
    if _candidate_rows or (out / "buy_candidates.csv").exists():
        _candidate_fieldnames: List[str] = []
        _seen_candidate_fields: set = set()
        for _row in _candidate_rows:
            for _field in _row:
                if _field not in _seen_candidate_fields:
                    _seen_candidate_fields.add(_field)
                    _candidate_fieldnames.append(_field)
        _write_csv(
            out / "buy_candidates.csv",
            _candidate_rows,
            fieldnames=_candidate_fieldnames or None,
        )

    contract = validate_run_artifacts(out, require_summary=True)
    if not contract:
        logger.error(
            "blocked-run companion refresh at %s failed artifact validation: %s",
            out,
            "; ".join(contract.errors),
        )


def _date_or_holiday_blocked(trading_day: date, config: StrategyConfig) -> bool:
    """Return True if the date/holiday gate stops execution for ``trading_day``.

    Called directly by both :func:`_check_execution_gates` (which acts on it) and
    :func:`run_daily_compact` (which reports it): both must agree on when only the
    blocked ``run_state.json`` stub was written, or compact callers can advertise
    signals/candidates/orders CSV paths for files ``run_once`` never created.
    """
    if trading_day not in config.approved_test_dates:
        return True
    # Independent of config.approved_test_dates (which config/trading_window.json
    # can widen to any weekday range with no holiday subtraction of its own): a
    # full NYSE closure is never a trading day, computed here so extending the
    # approved window can never silently reopen a holiday for live orders.
    return trading_day in nyse_holidays(trading_day.year)


def _check_account_pinning(config: StrategyConfig, broker: BrokerAdapter) -> None:
    """Raise RuntimeError if the live account isn't safely pinned to ``broker``.

    Extracted from :func:`_check_execution_gates` so any OTHER path that might
    persist a result for what could be a live, non-dry-run invocation --
    e.g. run_dca.py's preflight-blocked early return, which runs before
    run_daily_compact ever reaches this gate -- can enforce the same refusal
    instead of silently completing with a misconfigured/mismatched account
    undetected (Codex review: "Run account checks before returning the
    preflight failure").

    Validate the CONFIGURED account before comparing it to the broker's. The
    equality check below is satisfied by any two values that happen to match,
    including two empty ones -- so a live StrategyConfig(target_account_number="")
    paired with an injected adapter whose account_number() is also "" sailed
    through and reached placement. build_broker refuses to construct such an
    adapter, but callers may inject a BrokerAdapter into run_once directly and
    bypass the factory entirely, so the same condition has to hold here at the
    execution gate, which every path crosses (Codex review, PR #219).
    """
    if not config.dry_run:
        pinning_failure = account_pinning_failure(
            config.target_account_number, config.broker
        )
        if pinning_failure:
            raise RuntimeError(
                f"Refusing to trade live: {pinning_failure}. Configure a real account "
                "number (ROBINHOOD_AGENTIC_ACCOUNT_NUMBER) before running live, or set "
                "dry_run=True."
            )
    if broker.account_number() != config.target_account_number:
        raise RuntimeError(
            f"Refusing to trade account {broker.account_number()}; expected {config.target_account_number}"
        )


def _check_execution_gates(
    trading_day: date,
    config: StrategyConfig,
    broker: BrokerAdapter,
    artifacts_dir: Optional[str | Path],
    classification_state_root: Optional[str | Path] = None,
    classification_overrides: Optional[Dict[str, Any]] = None,
    correlation_id: Optional[str] = None,
) -> bool:
    warn_if_window_expiring(config.approved_test_dates, trading_day)
    if _date_or_holiday_blocked(trading_day, config):
        if trading_day not in config.approved_test_dates:
            logger.warning(
                "Date gate blocked execution for %s. No trades.", trading_day
            )
        else:
            # Independent of config.approved_test_dates (which config/trading_window.json
            # can widen to any weekday range with no holiday subtraction of its own): a
            # full NYSE closure is never a trading day, so extending the approved window
            # can never silently reopen a holiday for live orders.
            logger.warning(
                "NYSE holiday gate blocked execution for %s. No trades.", trading_day
            )
        _write_blocked_run_stub(
            trading_day,
            artifacts_dir,
            classification_state_root,
            classification_overrides=classification_overrides,
            correlation_id=correlation_id,
        )
        return False

    _check_account_pinning(config, broker)
    return True


def _load_deployment_history_states(
    trading_day: date, deployment_history_root: str | Path
) -> List[Dict[str, Any]]:
    """Every readable, non-blocked run_state in the trailing kill-switch window.

    Shared scan behind :func:`_apply_deployment_history` (the pre-run
    kill-switch injection) and :func:`_same_day_ticker_deployment_already_recorded`
    (same-stream duplicate-preserved accounting), so both agree on exactly
    which artifacts count as deployment evidence.
    """
    from dca_risk import KILL_SWITCH_WINDOW_DAYS, find_run_state_files

    # ⚡ Bolt Optimization: the injected figure only sums the trailing
    # KILL_SWITCH_WINDOW_DAYS calendar days ending on ``trading_day`` (see
    # dca_risk.seven_day_deployed), so a run_state whose trading_day falls
    # outside that window can never change it. This runs on every scheduled live
    # run while the history root grows unbounded over time, so skip the expensive
    # json.load for any artifact that carries no in-window date -- the same
    # fast-substring reject used by load_prior_same_day_allocations. A file that
    # DOES match still passes through the full parse and deployed_by_day
    # stream/afternoon-evidence filters, so a match is never counted unvalidated.
    window_days = {
        (trading_day - timedelta(days=offset)).isoformat()
        for offset in range(KILL_SWITCH_WINDOW_DAYS)
    }

    prior_states = []
    for path in find_run_state_files(deployment_history_root):
        try:
            raw_text = path.read_text(encoding="utf-8")
        except (ValueError, OSError):
            continue

        # Only trust the substring reject when the file contains no JSON unicode
        # escape sequence: a spec-valid encoder may spell an ASCII character such
        # as one of the date's hyphens as a unicode escape, which would not
        # literal-match the ISO date even though the parsed value is in-window.
        # Escaped files fall through to a full parse so a same-window artifact is
        # never silently dropped.
        if "\\u" not in raw_text and not any(day in raw_text for day in window_days):
            continue

        try:
            data = json.loads(raw_text)
        except ValueError:
            continue
        # Exclude date-gate blocked stubs from deployment accounting, but KEEP a
        # contract-rejected state (artifact_contract_failure marker): it is invalid
        # scheduled EVIDENCE, yet any orders it actually placed are real deployed
        # capital that must still count toward the rolling kill-switch/cap so the
        # next run cannot over-deploy. deployed_usd only sums status=='submitted'
        # candidates, so a partial-placement failure contributes exactly its real fills.
        if isinstance(data, dict) and (
            data.get("status") != RUN_STATUS_BLOCKED
            or data.get("artifact_contract_failure") is not None
        ):
            prior_states.append(data)
    return prior_states


def _apply_deployment_history(
    config: StrategyConfig, trading_day: date, deployment_history_root: str | Path
) -> StrategyConfig:
    from dca_risk import (
        STREAM_SCHEDULED,
        apply_risk_guard,
        classify_stream,
        deployed_by_day,
        is_afternoon_scheduled_evidence,
        unusable_deployed_notional_dates,
    )

    prior_states = _load_deployment_history_states(trading_day, deployment_history_root)
    config = apply_risk_guard(config, deployed_by_day(prior_states), trading_day)
    # deployed_notional_uncertain marks a row whose recorded planned_amount_usd
    # is a fail-closed CEILING estimate from the run that wrote it, not the
    # broker's real figure -- see the marker's own write site. That write's own
    # in-memory force_week_notional_to_worst_case_ceiling() only poisons ITS
    # OWN run's weekly bucket and stops applying the moment that run ends; the
    # durable marker exists so a LATER run reading this history back does not
    # trust the (possibly understated) recorded figure as settled fact. But
    # deployed_by_day() above sums plain planned_amount_usd -- it has no idea
    # the marker exists -- so a later scheduled run's live kill-switch
    # injection still trusted the understated total and could regain sizing
    # headroom the true (unknown, possibly higher) historical deployment never
    # actually freed (Codex review: "Enforce uncertain notionals in live
    # deployment history"). Mirrors the same stream/afternoon-evidence filter
    # deployed_by_day() applies above, so this only reacts to a marker that
    # would actually have contributed to the sum it is checking.
    # has_unusable_deployed_notional() answers at the whole-STATE level, but
    # a whole_share_claim_breakdown entry can attribute its unusable amount
    # to a date entirely outside the trailing kill-switch window even while
    # the file itself (and another, healthy candidate in it) is in-window --
    # _load_deployment_history_states()'s fast substring reject only proves
    # SOME window-day string appears somewhere in the file, not that this
    # particular unusable row does. Trusting the state-wide flag poisoned
    # deployed_last_7d_usd over uncertainty deployed_by_day() itself correctly
    # excludes from the very sum being checked (Codex review: "Scope unusable
    # notionals to the kill-switch window"). None (no attributable date) is
    # kept conservatively in-window, matching the "unknown means possibly
    # relevant" convention dca_risk._load_states_with_evidence already uses.
    uncertain_evidence_in_window = any(
        isinstance(state, dict)
        and classify_stream(state) == STREAM_SCHEDULED
        and is_afternoon_scheduled_evidence(state)
        and any(
            # A reconciliation artifact written after a replay can still
            # attribute an unknown order to the replay window. Its artifact
            # date is therefore not decisive; the claim's own attributed date
            # must intersect this window. A claim attributed solely to a
            # future day cannot have affected historical deployment.
            unusable_day is None
            or _within_kill_switch_window(unusable_day, trading_day)
            for unusable_day in unusable_deployed_notional_dates(state)
        )
        for state in prior_states
    )
    if uncertain_evidence_in_window:
        threshold = config.kill_switch_7d_deploy_fraction * config.monthly_cash_allocation_usd
        if config.deployed_last_7d_usd <= threshold:
            config = replace(config, deployed_last_7d_usd=threshold + 0.01)
    return config


def _within_kill_switch_window(claim_day: date, trading_day: date) -> bool:
    """True when ``claim_day`` falls inside the trailing kill-switch window ending
    on ``trading_day``.

    The same bound :func:`_load_deployment_history_states` applies when it builds
    ``config.deployed_last_7d_usd`` from disk, so a runtime addition to that
    figure agrees with what the injected value already covers rather than
    stretching it further back than the kill switch is defined over.
    """
    from dca_risk import KILL_SWITCH_WINDOW_DAYS

    return timedelta(0) <= (trading_day - claim_day) < timedelta(days=KILL_SWITCH_WINDOW_DAYS)


def _order_recorded_in_this_artifacts_dir(
    order_ids: Set[str], artifacts_dir: Optional[str | Path]
) -> bool:
    """True when THIS invocation's OWN ``artifacts_dir`` already has a
    submitted row for one of ``order_ids`` in its ``run_state.json``.

    Narrower than :func:`_same_day_order_recorded_in_any_stream`, which scans
    every scheduled artifact for the day across every stream's own root:
    THIS predicate answers "is the on-disk copy the SAME directory this
    invocation is about to write to" -- true only for an earlier FAILED
    attempt at the exact same slot (a genuine retry), never a sibling
    stream's or an earlier day's own artifact. Recovery's execution-record
    logging needs exactly that distinction: appending a fresh row to THIS
    run's execution_records is a same-file upgrade when the order is
    already on disk here, but a genuine cross-file DUPLICATE -- inflating
    filled-order/slippage reporting across two different orders.csv files
    -- when the on-disk copy lives somewhere else entirely (Codex review:
    "Skip current-run logging for recoveries already on disk").
    """
    if not artifacts_dir:
        return False
    wanted = {i for i in order_ids if i}
    if not wanted:
        return False
    state_path = Path(artifacts_dir) / "run_state.json"
    if not state_path.exists():
        return False
    try:
        state = json.loads(state_path.read_bytes())
    except (OSError, json.JSONDecodeError, UnicodeDecodeError):
        return False
    if not isinstance(state, dict):
        return False
    candidates = state.get("buy_candidates")
    if not isinstance(candidates, list):
        return False
    for candidate in candidates:
        if (
            isinstance(candidate, dict)
            and candidate.get("status") == "submitted"
            and str(candidate.get("order_id") or "") in wanted
        ):
            return True
    return False


def _same_day_order_recorded_in_any_stream(
    order_ids: Set[str], trading_day: date, deployment_history_root: str | Path
) -> bool:
    """True when ANY scheduled artifact for ``trading_day`` -- morning, midday or
    afternoon -- already records a submitted order carrying one of ``order_ids``.

    The idempotency counterpart of
    :func:`_same_day_order_deployment_already_recorded`, which answers the
    narrower KILL-SWITCH question and therefore filters to afternoon evidence.

    Recovery must not reuse that narrower predicate. A morning or midday worker
    that persisted both ``state.record_buy()`` and its submitted-order artifact
    and then crashed before deferred settlement leaves a MORNING artifact, which
    ``is_afternoon_scheduled_evidence`` explicitly rejects -- so the afternoon
    recovery run saw "not on disk", recorded the same dollars and attempt into
    ``StrategyState`` a second time and republished the order, overstating the
    shared daily and weekly caps (Codex review: "Check every roster stream
    before rebooking a recovery"). "Has this order already been booked?" is a
    question about every stream; only "does it count toward the afternoon
    kill-switch total?" is afternoon-scoped.
    """
    return _order_recorded_in_deployment_history(
        order_ids, trading_day, deployment_history_root, afternoon_only=False
    )


def _same_day_order_deployment_already_recorded(
    order_ids: Set[str], trading_day: date, deployment_history_root: str | Path
) -> bool:
    """True when a scheduled-afternoon artifact for ``trading_day`` already records
    a submitted order carrying one of ``order_ids``.

    The order-IDENTITY counterpart of
    :func:`_same_day_ticker_deployment_already_recorded`. Crash-lease recovery
    needs to know whether THIS reconciled order was already booked, and the
    ticker-level question answers something weaker: any other submitted order
    for the same ticker that day (an ordinary ladder buy from another stream,
    say) made the ticker-level check true and suppressed booking for a recovered
    order that has no artifact at all -- so the batch computed its daily, weekly
    and kill-switch headroom without that spend and could exceed its caps (Codex
    review: "Require the recovered order itself in deployment history").

    Matches against a SET because a recovered order can be identified two ways:
    the broker's own order id when history reported one, and the deterministic
    claim ref it was submitted under. Checking both keeps a genuinely-booked
    order recognizable whichever identifier the artifact happens to carry --
    a false negative here re-books real money.

    Afternoon-filtered because the kill-switch figure it guards is
    afternoon-only. For the broader "was this order already booked at all?"
    question, use :func:`_same_day_order_recorded_in_any_stream`.
    """
    return _order_recorded_in_deployment_history(
        order_ids, trading_day, deployment_history_root, afternoon_only=True
    )


def _order_recorded_in_deployment_history(
    order_ids: Set[str],
    trading_day: date,
    deployment_history_root: str | Path,
    *,
    afternoon_only: bool,
) -> bool:
    """Shared scan behind the two order-identity predicates above.

    ``afternoon_only`` selects which question is being asked: kill-switch
    accounting (afternoon evidence only) or plain booking idempotency (any
    scheduled stream).
    """
    from dca_risk import STREAM_SCHEDULED, classify_stream, is_afternoon_scheduled_evidence

    wanted = {i for i in order_ids if i}
    if not wanted:
        return False
    for state in _load_deployment_history_states(trading_day, deployment_history_root):
        if afternoon_only:
            if not is_afternoon_scheduled_evidence(state):
                continue
        elif classify_stream(state) != STREAM_SCHEDULED:
            # Still scheduled-only: a manual run's artifact is deliberately
            # excluded from every automated accounting path in this repo (see
            # docs/run_classification.md), and reading one here would let a
            # manual order suppress a real recovery booking.
            continue
        candidates = state.get("buy_candidates")
        if not isinstance(candidates, list):
            continue
        for candidate in candidates:
            if (
                isinstance(candidate, dict)
                and candidate.get("status") == "submitted"
                and str(candidate.get("order_id") or "") in wanted
            ):
                return True
    return False


def _same_day_ticker_deployment_already_recorded(
    ticker: str, trading_day: date, deployment_history_root: str | Path
) -> bool:
    """True when a scheduled-afternoon artifact for exactly ``trading_day``
    already recorded a submitted order for ``ticker`` on disk (and therefore
    already summed that order's notional into ``config.deployed_last_7d_usd``
    via ``_apply_deployment_history`` above).

    A same-stream retry's preserved-duplicate broker order must add its
    notional to ``running_deployed_7d`` only when this is False: the prior
    attempt that placed the order was interrupted before it could write its
    own run_state.json, so nothing on disk has counted that capital yet.

    Checked per TICKER, not merely "does any artifact exist for today": a
    zero-order (or different-ticker) afternoon artifact can already be on
    disk for today from an earlier invocation, while a LATER invocation's
    real placement for THIS ticker is still unwritten because it was
    interrupted before overwriting that artifact. Treating any same-day
    artifact as proof this ticker's capital was counted would then silently
    under-count deployment and let later candidates evade the kill-switch
    (Codex review, PR #231: "Verify the recovered order is actually in
    deployment history").
    """
    from dca_risk import is_afternoon_scheduled_evidence

    trading_day_iso = trading_day.isoformat()
    for state in _load_deployment_history_states(trading_day, deployment_history_root):
        if state.get("trading_day") != trading_day_iso:
            continue
        if not is_afternoon_scheduled_evidence(state):
            continue
        candidates = state.get("buy_candidates")
        if not isinstance(candidates, list):
            continue
        for candidate in candidates:
            if (
                isinstance(candidate, dict)
                and candidate.get("ticker") == ticker
                and candidate.get("status") == "submitted"
            ):
                return True
    return False


def _same_day_ticker_deployment_recorded_without_order_id(
    ticker: str, trading_day: date, deployment_history_root: str | Path, expected_amount_usd: float
) -> bool:
    """True when a scheduled-afternoon artifact for exactly ``trading_day``
    already recorded a submitted order for ``ticker`` that predates
    order-id tracking -- carrying no ``order_id`` (and no
    ``whole_share_order_ids``) at all -- for the SAME amount as
    ``expected_amount_usd``.

    A companion to :func:`_same_day_order_id_already_recorded`, which alone
    cannot match such a row: an order-id-aware check reading "no match" for
    a legacy record that never carried an id treated it as never having
    been counted, double-counting the SAME physical order (Codex review,
    PR #911 round 24 follow-up: an id-only reading of "already recorded"
    regressed the id-less legacy case round 10's own ticker-only check --
    predating that round -- was written to cover). Deliberately narrow to
    a row with NO id at all: a row that DOES carry an order_id names a
    KNOWN order, and a different id there is real proof of a genuinely
    distinct order, not something this legacy fallback should paper over.

    Also requires the persisted row's OWN ``planned_amount_usd`` to agree
    with ``expected_amount_usd`` within a cent. A legacy row carries no id
    to prove it names the SAME broker order as the one this call is asking
    about -- ticker+day alone matched an id-less row for a TOTALLY
    DIFFERENT order on the same ticker/day (a separate top-up or an older
    recovery) just as readily as the genuinely same one, suppressing a
    newly-recognized DISTINCT order's own deployment bump even though its
    capital was never actually counted on disk (Codex review, PR #911
    round 27: "Do not let an unrelated id-less row suppress deployment").
    Not perfect proof either -- two genuinely different orders CAN request
    an identical amount -- but it is the same amount-evidence standard
    :func:`_reconcile_ambiguous_fractional_placement`'s own multi-candidate
    disambiguation already relies on elsewhere in this module, and
    meaningfully narrows the false-positive window a ticker+day-only match
    left wide open.
    """
    from dca_risk import is_afternoon_scheduled_evidence

    trading_day_iso = trading_day.isoformat()
    for state in _load_deployment_history_states(trading_day, deployment_history_root):
        if state.get("trading_day") != trading_day_iso:
            continue
        if not is_afternoon_scheduled_evidence(state):
            continue
        candidates = state.get("buy_candidates")
        if not isinstance(candidates, list):
            continue
        for candidate in candidates:
            if not (
                isinstance(candidate, dict)
                and candidate.get("ticker") == ticker
                and candidate.get("status") == "submitted"
                and not candidate.get("order_id")
                and not candidate.get("whole_share_order_ids")
            ):
                continue
            _persisted_amount = _finite_nonnegative_float(candidate.get("planned_amount_usd"))
            if _persisted_amount is not None and abs(_persisted_amount - expected_amount_usd) <= 0.001:
                return True
    return False


def _same_day_order_id_already_recorded(
    order_id: Optional[str], ticker: str, trading_day: date, deployment_history_root: str | Path
) -> bool:
    """True when an afternoon-scheduled artifact within the trailing
    kill-switch window ENDING at ``trading_day`` already recorded a
    submitted candidate for ``ticker`` carrying this EXACT broker
    ``order_id`` -- either as its own ``order_id`` or inside an aggregated
    ``whole_share_order_ids`` list.

    Unlike :func:`_same_day_ticker_deployment_already_recorded` (which
    matches on the CLAIM's own trading_day -- correct for a claim that
    resolves and therefore stops being reconciled again), a
    ``"live_order_found"`` claim (see
    :func:`_reconcile_unresolved_whole_share_claim`) stays DELIBERATELY
    unresolved across runs while its order remains live, so it is
    reconciled again on EVERY subsequent invocation until the order
    terminates. Each such recovery is published under THAT LATER run's
    OWN trading_day (today), never the claim's original trading_day --
    an exact trading_day match anchored at the claim's day can therefore
    never find it, letting the SAME planned notional get rebooked and
    republished on every later run while the order remains live (Codex
    review: "Avoid rebooking a recovered live order on every later run").
    Matching on the order id itself, with the trailing-window scan
    anchored at ``trading_day`` (today, so it actually covers a recovery
    artifact written on an earlier day this week), finds it regardless of
    which day it was written under.
    """
    return _find_same_day_recorded_order(order_id, ticker, trading_day, deployment_history_root) is not None


def _find_same_day_recorded_order(
    order_id: Optional[str], ticker: str, trading_day: date, deployment_history_root: str | Path
) -> Optional[Dict[str, Any]]:
    """Return the FIRST afternoon-scheduled ``"submitted"`` candidate row
    (within the trailing kill-switch window ending at ``trading_day``)
    carrying this EXACT broker ``order_id`` for ``ticker`` -- either as its
    own ``order_id`` or inside an aggregated ``whole_share_order_ids`` list
    -- or ``None`` if none is found.

    Shared scan behind :func:`_same_day_order_id_already_recorded` (the
    plain boolean check) and the reconciliation-delta computation in
    :func:`_book_reconciled_whole_share_order` (Codex review: "Reconcile
    provisional deployment to the final fill"), which needs the matched
    row's own ``submitted_amount_usd`` to compute what changed between an
    earlier provisional recovery and this run's now-terminal settlement.
    """
    if not order_id:
        return None
    from dca_risk import is_afternoon_scheduled_evidence

    for state in _load_deployment_history_states(trading_day, deployment_history_root):
        if not is_afternoon_scheduled_evidence(state):
            continue
        candidates = state.get("buy_candidates")
        if not isinstance(candidates, list):
            continue
        for candidate in candidates:
            if (
                not isinstance(candidate, dict)
                or candidate.get("ticker") != ticker
                or candidate.get("status") != "submitted"
            ):
                continue
            if candidate.get("order_id") == order_id:
                return candidate
            ids = candidate.get("whole_share_order_ids")
            if isinstance(ids, list) and order_id in ids:
                return candidate
    return None


def _write_and_validate_scheduled_contract(
    artifacts: Dict[str, Any],
    artifacts_dir: str | Path,
    *,
    require_signals: bool = True,
    known_run_state_bytes: Optional[bytes] = None,
    run_result: Optional[RunResult] = None,
) -> Any:
    """Write the remaining scheduled-live contract files, then validate them.

    The compact daily path already wrote run_state.json + signals.csv. The
    scheduled afternoon (3:30 PM ET) contract additionally requires
    ``submitted_orders.csv`` (header row even with no order) and a canonical
    ``run_summary.json`` whose ``run_classification`` MIRRORS run_state's, and it
    forbids a compute-only terminal state (planned orders but nothing placed). This
    finalizes those files and runs :func:`validate_run_artifacts` so a contract
    breach — a missing/unmirrored summary or the Jul 22 2026 compute-only terminal
    state — is surfaced as a loud error on the live path itself, not only in tests.
    Validation failure is logged (mirroring the run_classification validation just
    below) rather than raised, so it never aborts a run that already placed orders.

    ``require_signals=False`` is used by the raw-persistence failure path, which is
    a fail-closed outcome where no signals could be computed (signals.csv is
    legitimately absent); the mirrored summary + header-only submitted_orders.csv
    are still written and validated so that outcome no longer bypasses the contract.

    ``known_run_state_bytes``, when given, is used AS the run_state.json snapshot
    instead of reading the file: the caller's own write already knows the exact
    bytes it just put on disk, and reading it back here -- even as the first
    statement in this function -- still leaves a window after that writer's lock
    was released and before this read runs, during which an overlapping retry can
    replace run_state.json and have ITS bytes silently adopted as this
    invocation's "own" snapshot (Codex review: "Bind the snapshot to this
    invocation's state"). Passing the writer's own bytes closes that window
    entirely, the same way ``_run_summary_bytes`` below is used directly rather
    than re-read.
    """
    try:
        from scripts.scheduled_artifacts import (
            ORDER_ATTEMPT_STATUSES,
            SUBMITTED_ORDERS_FIELDS,
            ArtifactContractResult,
            artifact_contract_failure,
            build_run_summary,
            validate_run_artifacts,
            write_submitted_orders_csv,
        )
    except ImportError:  # pragma: no cover - import shim for flat sys.path
        from scheduled_artifacts import (  # type: ignore
            ORDER_ATTEMPT_STATUSES,
            SUBMITTED_ORDERS_FIELDS,
            ArtifactContractResult,
            artifact_contract_failure,
            build_run_summary,
            validate_run_artifacts,
            write_submitted_orders_csv,
        )

    out = Path(artifacts_dir)
    # Preferred: known_run_state_bytes, the exact bytes the caller's own prior
    # write put on disk (see the docstring's "Bind the snapshot to this
    # invocation's state" note) -- this needs no read at all, so it cannot be
    # raced.
    #
    # Fallback, when a caller has no such bytes to hand (e.g. it wrote
    # run_state.json itself, outside this function, with no captured copy):
    # read it here, as the FIRST thing this function does, before its own
    # submitted_orders.csv/run_summary.json writes below, so this is the
    # earliest point at which its bytes can be learned and therefore the
    # narrowest possible window for the race this snapshot exists to detect.
    # Capturing it any later -- e.g. immediately before
    # validate_run_artifacts(), as an earlier version of this fix did -- left
    # a window spanning this function's own unrelated I/O in between, during
    # which an overlapping retry replacing run_state.json would have ITS
    # bytes silently captured as this invocation's own "snapshot", validated
    # as part of a mixed self-summary/other-state set, and then wrongly
    # accepted as unchanged when compared against that same already-wrong
    # snapshot later (Codex review: "Bind snapshots to this invocation's
    # writes"). This fallback path still carries the residual window the
    # caller-supplied-bytes path exists to close -- callers that hold the
    # bytes should always pass them.
    if known_run_state_bytes is not None:
        _pre_validation_run_state_snapshot: Optional[bytes] = known_run_state_bytes
    else:
        try:
            _pre_validation_run_state_snapshot = (out / "run_state.json").read_bytes()
        except OSError:
            _pre_validation_run_state_snapshot = None
    # submitted_orders.csv: one row per candidate that actually placed or attempted
    # a real order; header-only when none did. A scheduled dry run assigns each
    # candidate a synthetic DRY-RUN-SIM-* order_id while keeping status="dry_run"
    # (see _process_buy_candidate); those simulated orders must NOT be recorded as
    # broker submissions -- the drift detector treats any non-confirmation status
    # with an order_id as a real submission -- so dry_run is excluded even though it
    # carries an order_id.
    order_rows = [
        {
            "ticker": c.get("ticker"),
            "order_id": c.get("order_id"),
            "submitted_amount_usd": c.get("planned_amount_usd"),
            "status": c.get("status"),
        }
        for c in artifacts.get("buy_candidates", [])
        if c.get("status") != "dry_run"
        and (c.get("status") in ORDER_ATTEMPT_STATUSES or c.get("order_id"))
    ]
    # Computed in-memory, BEFORE the write -- never read back from disk
    # afterward. A read-back, even as the very next statement after the
    # write, still leaves a real window: an overlapping same-slot retry
    # can replace submitted_orders.csv between write_submitted_orders_csv()
    # returning and that read executing, so this invocation would silently
    # adopt the PEER's bytes as its own "known" snapshot -- passing both
    # validate_run_artifacts() (which only checks the CSV parses and has
    # the expected header) and the later byte-comparison it was supposed
    # to guard, publishing an artifact set with this invocation's own
    # state/summary but another retry's orders (Codex review: "Bind the
    # CSV snapshot to this invocation's write", following up on "Snapshot
    # the submitted-orders artifact before validation"). Constructing the
    # exact bytes _write_csv would produce -- same DictWriter config,
    # same fieldnames, same restval -- means there is no read to race at
    # all, mirroring how _run_summary_bytes below is this invocation's own
    # just-computed content, never a re-read of what it wrote.
    import io

    _submitted_orders_csv_buffer = io.StringIO()
    _submitted_orders_csv_writer = csv.DictWriter(
        _submitted_orders_csv_buffer, fieldnames=list(SUBMITTED_ORDERS_FIELDS), restval=""
    )
    _submitted_orders_csv_writer.writeheader()
    for _order_row in order_rows:
        _submitted_orders_csv_writer.writerow(
            {key: _order_row.get(key, "") for key in SUBMITTED_ORDERS_FIELDS}
        )
    _submitted_orders_csv_snapshot: Optional[bytes] = (
        _submitted_orders_csv_buffer.getvalue().encode("utf-8")
    )

    # run_summary.json must mirror the SAME non-null run_classification object as
    # run_state.json (Jul 22 2026 3:20 incident: a null summary classification broke
    # scheduled-vs-manual attribution downstream) AND carry the no-order outcome
    # fields, or a summary-only consumer cannot tell a healthy zero-order run from
    # a failure (Codex review). build_run_summary is the single shape both the
    # morning/midday and afternoon writers use. Computed here (pure, in-memory,
    # from `artifacts` alone) but not yet written -- the write itself happens
    # below, only after re-verifying run_state.json is unchanged.
    summary = build_run_summary(artifacts)
    _run_summary_bytes = json.dumps(summary, indent=2, sort_keys=True).encode("utf-8")

    # Re-verify run_state.json against the snapshot immediately before
    # writing either companion file -- not merely afterward, the way the
    # later `_pre_validation_snapshots` comparison loop does. Without this,
    # an overlapping retry (B) can publish its own complete, valid
    # run_state.json in the gap between this invocation's (A's) snapshot
    # capture above and these unconditional writes; A then overwrites B's
    # submitted_orders.csv/run_summary.json with its own. The later byte
    # comparison still correctly detects the run_state.json mismatch and
    # returns failure -- but by then B's companions are already clobbered
    # and never restored, so an already-published pointer can end up
    # referencing B's state paired with A's order rows and summary (Codex
    # review: "Verify state before writing companion artifacts"). Not
    # wrapped in cross_process_lock: this function's OWN later contract-
    # failure annotation loop already acquires that identical lock file
    # with its own bounded-retry contract, and every existing test
    # exercising that retry/exhaustion behavior intercepts lock/read calls
    # by path alone within this same function's frame -- a second,
    # differently-shaped lock acquisition here would consume those
    # simulated attempts before the annotation loop ever ran, changing
    # what those tests exercise. An unlocked re-read right here still
    # narrows the window this fix targets from "the entire snapshot-to-
    # comparison span" down to "the instant between this read and the
    # writes two lines below" -- not a full close, but the residual gap is
    # already far smaller than what the later comparison loop covers on
    # its own.
    try:
        _current_state_bytes_before_companions = (out / "run_state.json").read_bytes()
    except OSError:
        _current_state_bytes_before_companions = None
    if _current_state_bytes_before_companions != _pre_validation_run_state_snapshot:
        logger.error(
            "Scheduled-run artifact contract for %s can no longer be confirmed "
            "valid: run_state.json changed before its companion artifacts could "
            "be written, most likely due to an overlapping retry; not writing "
            "submitted_orders.csv/run_summary.json over another run's own",
            out,
        )
        return ArtifactContractResult(
            False, ["run_state.json changed before companion artifacts could be written"]
        )
    write_submitted_orders_csv(out, order_rows)
    (out / "run_summary.json").write_bytes(_run_summary_bytes)

    # One exact-bytes snapshot per file this function might later annotate
    # as failed, used to detect whether an overlapping retry has since
    # claimed the file before this invocation stamps it. `artifacts["run_id"]`
    # alone is NOT collision-resistant enough for that comparison: it is
    # only second-granularity (`YYYY-MM-DD-HHMMSS`), so two overlapping
    # retries starting within the same second are given the IDENTICAL
    # run_id by `build_run_artifacts()`, and a run_id match would then
    # wrongly let this invocation stamp its own stale failure onto a
    # different, genuinely successful retry that happens to share it
    # (Codex review: "Use a collision-resistant snapshot identifier").
    #
    # Neither snapshot is a read taken just before validate_run_artifacts()
    # (an earlier version of this fix): run_summary.json's is the exact
    # bytes THIS invocation itself just wrote above, and run_state.json's
    # was captured as the very first thing this function did, before any of
    # its own I/O -- see the comments at each capture site for why a later
    # read of either was itself racy (Codex review: "Bind snapshots to this
    # invocation's writes").
    _pre_validation_snapshots: Dict[str, Optional[bytes]] = {
        "run_summary.json": _run_summary_bytes,
        "run_state.json": _pre_validation_run_state_snapshot,
        "submitted_orders.csv": _submitted_orders_csv_snapshot,
    }
    result = validate_run_artifacts(
        out,
        require_signals=require_signals,
        require_submitted_orders=True,
        require_summary=True,
    )
    if result:
        # validate_run_artifacts() reads run_state.json/run_summary.json
        # fresh from disk, not the snapshot bytes above -- an overlapping
        # retry sharing a colliding (second-granularity) run_id could have
        # replaced either file with its OWN, independently valid content in
        # the gap between this invocation's snapshot capture and this
        # validation call. validate_run_artifacts() would then pass on THAT
        # content, and this function would report a set combining this
        # invocation's own submitted_orders.csv/summary with a different
        # retry's run_state.json as valid, complete scheduled evidence
        # (Codex review: "Verify the state snapshot before accepting the
        # contract"). Confirmed here by comparing the exact bytes actually
        # on disk right now against this invocation's own known-written
        # snapshot. A mismatch is NOT stamped as a contract failure -- doing
        # so would corrupt the other retry's genuinely valid state the same
        # way the annotation loop below already guards against -- it is
        # simply not accepted as proof of THIS invocation's own valid,
        # complete contract.
        for _snapshot_name, _snapshot_bytes in _pre_validation_snapshots.items():
            try:
                _current_bytes = (out / _snapshot_name).read_bytes()
            except OSError:
                _current_bytes = None
            if _current_bytes != _snapshot_bytes:
                logger.error(
                    "Scheduled-run artifact contract for %s can no longer be "
                    "confirmed valid: %s changed since this invocation's own "
                    "snapshot, most likely due to an overlapping retry; not "
                    "publishing this as valid scheduled evidence",
                    out,
                    _snapshot_name,
                )
                return ArtifactContractResult(
                    False, [f"{_snapshot_name} changed since the pre-validation snapshot"]
                )
    if not result:
        logger.error(
            "Scheduled-run artifact contract failed for %s: %s",
            out,
            "; ".join(result.errors),
        )
        # Persist the rejection INTO the run_state (and its summary) so every
        # consumer that discovers the file directly refuses to count it as valid
        # scheduled evidence -- not just the latest-run pointer. select_same_day_
        # run_state gates on derive_valid_scheduled_evidence (now fails closed on
        # the artifact_contract_failure marker) and load_scheduled_run_states drops
        # status=='blocked' stubs.
        failure = artifact_contract_failure(
            "scheduled-run artifact contract failed",
            detail="; ".join(result.errors),
        )
        # Distinguish "the run never actually placed the planned order" (the
        # compute-only terminal state this contract exists to catch) from a
        # companion-artifact-only failure (e.g. a missing/unmirrored
        # run_summary.json) that can follow a REAL broker submission, and from
        # the PARTIAL case (one candidate placed, a different positive-planned
        # candidate left unplaced) -- compute_only describes overall
        # completion validity, not whether a specific row's placement is
        # trustworthy. dca_weekly_dashboard._has_submitted_evidence uses this
        # flag; a placed row still counts regardless of its value (Codex
        # review, PR #538: "Retain real orders when only the artifact
        # contract failed" / "Retain submitted rows in compute-only partial
        # failures").
        failure["compute_only"] = any(
            "compute-only terminal state" in err for err in result.errors
        )
        for name in ("run_state.json", "run_summary.json"):
            fpath = out / name
            if not fpath.exists():
                continue
            # A SINGLE lock-timeout attempt used to give up on this file for
            # good: `derive_valid_scheduled_evidence()` (scripts/
            # same_day_pointer.py) trusts `run_state.json`'s own
            # `artifact_contract_failure` marker directly, with no other
            # path to learn the contract actually failed -- so skipping the
            # annotation just once let a compute-only or otherwise
            # contract-invalid run still be consumed as valid scheduled
            # evidence for good, not merely until the next retry (Codex
            # review: "Keep failed contracts ineligible after lock
            # timeouts"). Retried a bounded number of times instead --
            # `_write_and_validate_scheduled_contract` still must not raise
            # (orders may already be placed by the time the contract is
            # found to have failed, per the original "Keep lock timeouts
            # inside best-effort contract handling" fix this extends), but
            # a transient/short-lived contending holder now gets several
            # chances to clear before this gives up and logs loudly enough
            # to be found.
            _annotation_attempts_remaining = 3
            while True:
                try:
                    with cross_process_lock(fpath.with_name(f"{fpath.name}.lock")):
                        # A transient read failure here (e.g. a race with
                        # another writer's own rename, or a momentary
                        # filesystem error) used to just `break` out of this
                        # entire retry loop on the spot -- silently
                        # abandoning the annotation after a single failed
                        # attempt, with no retry and no durable sidecar,
                        # unlike every other failure mode this loop already
                        # retries and falls back on. Left unguarded here so
                        # it propagates to the SAME (TimeoutError, OSError)
                        # handler below that already retries a bounded
                        # number of times and persists the undurable-evidence
                        # sidecar on exhaustion (Codex review: "Retry failed
                        # reads before abandoning the denial stamp").
                        _raw_bytes = fpath.read_bytes()
                        # `result` above validated THIS invocation's own
                        # artifact set, snapshotted byte-for-byte just before
                        # that validation call; the retry loop can take
                        # several lock acquisitions (one full attempt cycle
                        # per file) across which an overlapping retry
                        # sharing this directory can publish and validate
                        # its OWN, successful artifact set. Comparing exact
                        # bytes -- not `run_id` -- catches that regardless
                        # of collision: `run_id` is only second-granularity
                        # (`YYYY-MM-DD-HHMMSS`), so two overlapping retries
                        # starting within the same second are given the
                        # IDENTICAL run_id, and an id-only comparison would
                        # still let this invocation stamp its stale verdict
                        # onto that other, genuinely successful retry
                        # (Codex review: "Use a collision-resistant snapshot
                        # identifier"). ANY change since the snapshot -- from
                        # any writer, sharing any run_id -- means this
                        # invocation's validation no longer describes what
                        # is currently on disk, so left untouched rather
                        # than corrupted with an unrelated verdict (Codex
                        # review: "Bind contract-failure stamps to the
                        # validated snapshot").
                        if _raw_bytes != _pre_validation_snapshots.get(name):
                            break
                        try:
                            data = json.loads(_raw_bytes)
                        except (json.JSONDecodeError, UnicodeDecodeError):
                            break
                        if not isinstance(data, dict):
                            break
                        data["status"] = RUN_STATUS_BLOCKED
                        data["artifact_contract_failure"] = failure
                        rc = data.get("run_classification")
                        if isinstance(rc, dict):
                            rc["valid_scheduled_evidence"] = False
                        _stamped_bytes = json.dumps(data, indent=2, sort_keys=True).encode("utf-8")
                        atomic_write_text(fpath, _stamped_bytes.decode("utf-8"))
                        # run_state.json's snapshot on RunResult must track
                        # this invocation's OWN latest write, not just
                        # write_run_artifacts()'s earlier one: this stamp is
                        # still THIS invocation's own legitimate follow-up
                        # write (never a peer's -- the exact-bytes compare
                        # above already refused to stamp over any change
                        # since this invocation's own snapshot), so leaving
                        # the earlier, now-stale value in place would make
                        # run_daily_compact's later concurrent-writer check
                        # misread this invocation's own contract-failure
                        # stamp as a foreign peer's write (Codex review:
                        # "Capture this invocation's state at publication
                        # time").
                        if run_result is not None and name == "run_state.json":
                            run_result.published_run_state_bytes = _stamped_bytes
                    break
                except (TimeoutError, OSError):
                    # A lock-setup/IO failure (sidecar cannot be created or
                    # opened -- e.g. transient filesystem error, descriptor
                    # exhaustion, or permissions) surfaces as a plain OSError
                    # from cross_process_lock() itself, not just the
                    # TimeoutError this loop already retries on. Both must
                    # stay inside this best-effort annotation pass rather
                    # than escaping `_write_and_validate_scheduled_contract`
                    # after orders may already have been placed (Codex
                    # review: "Contain non-timeout failures from the
                    # annotation lock").
                    _annotation_attempts_remaining -= 1
                    if _annotation_attempts_remaining <= 0:
                        logger.error(
                            "Could not acquire %s.lock after repeated lock timeouts; "
                            "%s was NOT annotated with the failed artifact "
                            "contract and may still read as valid scheduled "
                            "evidence until manually reconciled",
                            fpath.name,
                            fpath,
                        )
                        # Durably preserved in its own file rather than lost
                        # outright now that the primary annotation is given
                        # up on (Codex review: "Keep contract-invalid state
                        # denied after prolonged contention") -- see
                        # `_persist_undurable_evidence_sidecar`'s own
                        # docstring for why this is a discoverable sidecar
                        # rather than a raise or a further-extended retry.
                        _persist_undurable_evidence_sidecar(
                            out,
                            "unannotated_contract_failure",
                            datetime.now(timezone.utc),
                            {
                                "run_id": artifacts.get("run_id"),
                                "artifact_path": str(fpath),
                                "artifact_contract_failure": failure,
                            },
                        )
                        break
                    continue
    return result


def _finalize_and_write_artifacts(
    now: datetime,
    config: StrategyConfig,
    state: StrategyState,
    decisions: List[ReconciledDecision],
    candidate_outcomes: Dict[str, Dict[str, Any]],
    order_reviews_attempted: int,
    errors_count: int,
    notifications_sent: Optional[int],
    cost_control_notes: Optional[Sequence[str]],
    top_up_outcomes: Optional[Dict[str, TopUpGuardOutcome]],
    scheduled: bool,
    artifacts_dir: Optional[str | Path],
    classification_state_root: Optional[str | Path],
    raw_persistence_state: Optional[Dict[str, object]] = None,
    classification_overrides: Optional[Dict[str, Any]] = None,
    correlation_id: Optional[str] = None,
    broker: Optional["BrokerAdapter"] = None,
    extra_finance_calls_attempted: int = 0,
    run_result: Optional[RunResult] = None,
) -> None:
    if artifacts_dir is None:
        return

    run_context = ArtifactRunContext(
        order_reviews_attempted=order_reviews_attempted,
        # build_usage_proxy's own default (one finance call per scanned
        # ticker) already covers the per-ticker signal scan; this adds
        # whatever genuinely EXTRA same-run finance queries ran on top of
        # that (currently: armed inverse-martingale latches' live
        # corporate-action lookups) so the usage proxy does not silently
        # under-report them (Codex review: "Count live corporate-action
        # finance queries"). None (not 0) when there is nothing extra, so a
        # caller that never passes this keeps the plain per-ticker default
        # build_usage_proxy already documents.
        finance_calls_attempted=(
            len(decisions) + extra_finance_calls_attempted
            if extra_finance_calls_attempted
            else None
        ),
        errors_count=errors_count,
        notifications_sent=notifications_sent,
        cost_control_notes=cost_control_notes,
        top_up_outcomes=top_up_outcomes,
        manual=not scheduled,
        raw_persistence_state=raw_persistence_state,
        classification_overrides=classification_overrides,
        correlation_id=correlation_id,
        broker=broker,
        # Beside the artifacts tree, not inside it -- same convention
        # _book_recovered_lease_durably's own account-fingerprint call uses
        # (key_dir = ledger root's parent) -- so a copy of the artifacts
        # directory alone never carries the key with it.
        account_fingerprint_key_dir=Path(artifacts_dir).parent,
    )
    artifacts = build_run_artifacts(
        now,
        config,
        state,
        decisions,
        candidate_outcomes,
        run_context=run_context,
    )
    paths = write_run_artifacts(artifacts, artifacts_dir)
    logger.info("Wrote run artifacts: %s", paths["run_state"])
    # Stashed on the SAME RunResult object run_daily_compact holds a
    # reference to (ctx.run_result), so it can read this invocation's own
    # just-written bytes back without ever re-reading run_state.json from
    # disk itself -- closing the race an unlocked re-read would reopen (see
    # RunResult.published_run_state_bytes).
    if run_result is not None:
        run_result.published_run_state_bytes = paths.get("_run_state_written_bytes")

    contract_ok = True
    if scheduled:
        contract_ok = bool(
            _write_and_validate_scheduled_contract(
                artifacts,
                artifacts_dir,
                known_run_state_bytes=paths.get("_run_state_written_bytes"),
                run_result=run_result,
            )
        )

    # Archived AFTER the scheduled contract's required run_summary.json and
    # submitted_orders.csv are already on disk (or, for a manual run with no
    # contract step, right after write_run_artifacts above): a per-ticker
    # archive lock can block for several seconds when another process is
    # writing the same ticker file, and the just-fired-run grace period a
    # monitor uses to distinguish a genuinely incomplete run from one still
    # finishing defaults to only 20 seconds -- ordinary archive contention
    # must never delay those REQUIRED files and trigger a false escalation on
    # a run that actually succeeded (Codex review: "Finalize scheduled
    # artifacts before waiting on archive locks").
    snapshot_path = _archive_intraday_observations(
        artifacts,
        Path(artifacts_dir),
        decisions,
        run_state_path=Path(paths["run_state"]),
        run_result=run_result,
    )
    if snapshot_path:
        paths["observations"] = snapshot_path
    # A peer replaced run_state.json since this invocation's own publish
    # (detected by _archive_intraday_observations under the state lock,
    # AFTER contract_ok above was already decided from this invocation's
    # own now-stale bytes): the path this run is about to point
    # latest_scheduled_run.json at no longer holds what contract_ok
    # actually validated, so publishing it would advertise the peer's
    # state as this invocation's own confirmed scheduled evidence (Codex
    # review: "Propagate archive ownership rejection before publishing the
    # pointer").
    if run_result is not None and run_result.archive_ownership_rejected:
        contract_ok = False

    if scheduled and classification_state_root is not None:
        try:
            from scripts.run_classification import (
                update_latest_scheduled_run_pointer,
                validate_classification,
            )
        except ImportError:
            from run_classification import (  # type: ignore
                update_latest_scheduled_run_pointer,
                validate_classification,
            )
        rc = artifacts.get("run_classification")
        result = validate_classification(rc if isinstance(rc, dict) else {})
        if result and contract_ok:
            update_latest_scheduled_run_pointer(
                artifacts,
                paths["run_state"],
                base=Path(classification_state_root) if classification_state_root is not None else None,
            )
        elif not contract_ok:
            # A run that breached the artifact contract (e.g. the compute-only
            # terminal state: planned orders but nothing placed) must NOT be
            # recorded as valid scheduled evidence, even when its run_classification
            # is well-formed. Skip the pointer update so the invalid run cannot be
            # picked up as the latest scheduled run.
            logger.error(
                "Not updating latest_scheduled_run.json: scheduled-run artifact "
                "contract failed (see the artifact-contract error above); this run "
                "is not valid scheduled evidence."
            )
        else:
            logger.error(
                "Not updating latest_scheduled_run.json: invalid run_classification (%s)",
                "; ".join(result.errors),
            )


def _graded_dca_ref_id_prefix(stream: str, kind: str = "") -> str:
    """Build the ``graded-dca[-<stream>][-<kind>]`` prefix for ref ids and
    same-stream duplicate checks.

    The ``"afternoon"`` stream (this module's own historical, single-stream
    default) keeps the exact legacy, unprefixed ``"graded-dca[-kind]"``
    convention byte-for-byte -- ``docs/safeguards.md``'s Gate 4 sole-executor
    check and the real legacy ``10ce362c`` task's own order history depend on
    that literal string. Only a non-``"afternoon"`` stream (``"morning"``/
    ``"midday"``, from the seven-slot roster's ``run_dca.run_slot()``) gets a
    stream token inserted: ``near_close_dca.py`` is now the SAME engine
    shared across all three canonical slots, so without a per-stream token,
    ``_same_stream_order_exists`` cannot tell "this exact run's own retry"
    apart from "a different, earlier canonical slot's genuine cross-stream
    order" -- an earlier slot's real fill would be misread as this slot's own
    duplicate, and the guarded top-up it should have placed would silently
    become a no-op instead (Codex review: "Namespace idempotency keys before
    enabling cross-slot top-ups").
    """
    parts = ["graded-dca"]
    if stream and stream != "afternoon":
        parts.append(stream)
    if kind:
        parts.append(kind)
    return "-".join(parts)


def _same_stream_order_exists(
    broker: BrokerAdapter, ticker: str, trading_day: date, stream: str = "afternoon"
) -> Optional[Dict[str, Any]]:
    """Return the broker order dict when this stream's own idempotency ref id
    already exists for ``ticker`` today, else ``None``.

    A guarded top-up candidate (``ticker_guarded`` in ``_process_buy_candidate``)
    intentionally bypasses the broad ``same_day_strategy_order_exists`` check so
    that an earlier CROSS-stream (morning/midday) allocation is not mistaken for
    a duplicate. But that bypass must not also blind a retry of THIS SAME
    scheduled run (same stream) to an order it already placed for the ticker on
    an earlier attempt today -- with no narrower check, such a retry would
    recompute the top-up guard from the cross-stream prior allocation alone
    (which does not know about this stream's own already-placed top-up) and
    submit a second, duplicate order (mirrors morning_dca.py's
    ``_same_stream_order_exists``).

    Both the plain and topup scheduled ref-id prefixes are checked, matching
    the two ref_id shapes ``_process_buy_candidate`` can have used depending on
    whether the ticker was already guarded on the attempt that placed the order.
    ``stream`` (default ``"afternoon"``, this module's historical sole caller)
    scopes both prefixes to the calling slot -- see
    :func:`_graded_dca_ref_id_prefix`.
    """
    checker = getattr(broker, "same_day_strategy_order_exists_with_ref_id_prefix", None)
    if checker is None:
        raise RuntimeError(
            "broker does not support same-stream ref-id duplicate checks for guarded top-ups"
        )
    prefixes = (
        f"{_graded_dca_ref_id_prefix(stream, 'topup')}-{trading_day.isoformat()}-{ticker}",
        f"{_graded_dca_ref_id_prefix(stream)}-{trading_day.isoformat()}-{ticker}",
    )
    result = checker(ticker, trading_day, prefixes)
    if not isinstance(result, dict):
        # Normalize legacy boolean adapters: False/None -> None (no duplicate),
        # True -> treat as found but without order details.
        return None if not result else {}
    return result


def _same_stream_duplicate_check_or_assume_exists(
    broker: BrokerAdapter, ticker: str, trading_day: date, stream: str
) -> bool:
    """``_same_stream_order_exists`` as a plain bool, fail-closed on error.

    Used only by :func:`_select_final_session_credit_flush_tickers`'s
    duplicate-order-exists check before an otherwise-immediate discard: a
    discard is destructive (it erases the only ledger evidence of a
    possibly-already-placed order), so an inconclusive broker check must
    default to "assume a duplicate might exist" (routing the ticker to a
    real candidate evaluation, which performs its own, authoritative
    duplicate check) rather than silently discarding on uncertainty.
    """
    try:
        return _same_stream_order_exists(broker, ticker, trading_day, stream) is not None
    except Exception as exc:  # noqa: BLE001
        logger.warning(
            "same-stream duplicate check failed for %s during final-session "
            "credit discard; assuming a duplicate may exist: %s",
            ticker,
            exc,
        )
        return True


@dataclass(frozen=True)
class ProcessCandidateContext:
    """Shared, per-run context for :func:`_process_buy_candidate` and
    :func:`_process_buy_candidates_batch`.

    Groups the config/state/broker/market-data/timing/guard fields that are
    identical across every candidate in a single batch into one immutable
    object, instead of threading each of them through as its own positional
    or keyword argument.
    """

    config: StrategyConfig
    state: StrategyState
    broker: BrokerAdapter
    robinhood_data: Optional[MarketDataProvider]
    now: datetime
    trading_day: date
    guard_active: bool
    prior_same_day_allocations: Dict[str, PriorSameDayAllocation]
    scheduled: bool
    run_result: Optional[RunResult]
    deployment_history_root: Optional[str | Path] = None
    stream: str = "afternoon"
    credit_ledger: CumulativeCreditLedger = field(default_factory=CumulativeCreditLedger)


def _whole_share_max_shares_by_ceiling(max_per_order_usd: float, current_share_price: float) -> int:
    """How many whole shares at ``current_share_price`` fit under
    ``max_per_order_usd``, computed on exact integer cents rather than a raw
    float floor-division.

    ``max_per_order_usd // current_share_price`` looks exact but is not: a
    cent-rounded price is frequently NOT representable exactly as a binary
    float (e.g. ``0.10`` is actually ``0.1000000000000000055...``), so
    ``10.0 // 0.10`` evaluates to ``99.0`` in Python, not ``100.0`` --
    unnecessarily clamping a fully-affordable fire by one share and delaying
    real, available credit for no reason (Codex review: "Compute the share
    ceiling with exact cent arithmetic"). Rounding both operands to whole
    cents before dividing sidesteps the float-representation error entirely.
    """
    ceiling_cents = round(max_per_order_usd * 100)
    price_cents = round(current_share_price * 100)
    if price_cents <= 0:
        return 0
    shares = ceiling_cents // price_cents
    # ... and then reconciled against the notional the PLACEMENT path will
    # actually compute, which is `round(quantity * current_share_price, 2)`.
    # The two conversions can disagree on a half-cent boundary: at
    # `current_share_price=50.005` this function's `round(50.005 * 100)` is
    # 5000, so one share reads as fitting under a $50.00 ceiling, while the
    # placement path's `round(50.005, 2)` is $50.01 -- over it. Eligibility
    # approving a fire the placement then oversizes crosses a hard ceiling by
    # rounding disagreement alone (Codex review, PR #786: "Use consistent cent
    # rounding for the whole-share allowance").
    #
    # Reconciling here rather than restating the rounding rule in both places:
    # the invariant that matters is "the notional this fire will really carry
    # is within the ceiling", so it is checked with the very expression that
    # produces that notional. Costs at most a step or two, and cannot loosen
    # the count -- it only ever walks DOWN from the cent-division estimate,
    # leaving the exact-cent cases that estimate exists for untouched.
    while shares > 0 and round(shares * current_share_price, 2) > max_per_order_usd:
        shares -= 1
    return shares


def _whole_share_executable_share_count(
    config: "StrategyConfig",
    current_share_price: float,
    *,
    ceiling_override_usd: Optional[float] = None,
) -> tuple[int, float, bool]:
    """How many whole shares one order may actually place, and under which
    ceiling.

    Returns ``(share_count, effective_ceiling_usd, single_share_allowance_applied)``.

    THE single source of truth for that arithmetic, shared by
    :func:`_whole_share_risk_gates` (execution) and ``_run_once_impl``'s
    tier-planning preview. The preview exists to predict exactly what
    execution will spend -- it feeds ``planned_spend``, which selects the
    budget tier, whose daily/weekly cap then governs UNRELATED orders -- so
    the two computing the ceiling separately is a standing drift hazard. It
    has already bitten twice: the preview had to be taught the kill-switch
    clamp (Codex review: "Apply the kill-switch ceiling in tier planning"),
    and then, when the single-share allowance was added to execution only, the
    preview kept contributing $0 for any share priced above
    ``max_per_order_usd`` while execution could really spend up to
    ``whole_share_max_per_order_usd`` -- understating planned spend enough to
    select a tier whose cap then budget-blocks later valid orders (Codex
    review, PR #786: "Apply the single-share allowance during tier planning").
    One function now, called by both.

    ``ceiling_override_usd`` is the deployment kill switch capping the
    executable fire; it is ``min()``-combined with ``max_per_order_usd`` and
    suppresses the single-share allowance entirely (see below).
    """
    effective_ceiling_usd = config.max_per_order_usd
    if ceiling_override_usd is not None:
        effective_ceiling_usd = min(effective_ceiling_usd, ceiling_override_usd)
    share_count = _whole_share_max_shares_by_ceiling(effective_ceiling_usd, current_share_price)
    # SINGLE-SHARE ALLOWANCE. max_per_order_usd is sized for fractional dollar
    # orders, where any amount is expressible; a whole-share ticker's minimum
    # purchasable unit is one share, so for any symbol priced above that
    # ceiling the count above is 0 and the gate reads as "never buy this
    # ticker at all". RVII (~$23/share) hit exactly that when it moved into
    # the whole-share category -- it would have accumulated in the ledger
    # forever and never fired -- and BYDDY (~$10/share) clears the $10 cap
    # only by a cent or two (PR #786 review: "Allow RVII's share price through
    # the whole-share ceiling").
    #
    # Deliberately narrow, so this is an allowance and not a raised ceiling:
    #
    # * It authorizes exactly ONE share, never more. How many shares may go
    #   into a single fire is still max_per_order_usd's decision, so BYDDY's
    #   existing behavior (1 share, $10) is unchanged rather than becoming
    #   5 shares at $50.
    # * It never applies when ceiling_override_usd was passed. That override
    #   is the deployment kill switch capping the executable fire; rescuing a
    #   share through it would defeat exactly the block it exists to impose.
    #   A kill-switch-capped fire stays blocked and deferred.
    if (
        share_count <= 0
        and ceiling_override_usd is None
        and _whole_share_max_shares_by_ceiling(
            config.whole_share_max_per_order_usd, current_share_price
        )
        >= 1
    ):
        return 1, config.whole_share_max_per_order_usd, True
    return share_count, effective_ceiling_usd, False


def _whole_share_risk_gates(
    ticker: str,
    quantity: int,
    order_notional: float,
    current_share_price: float,
    ctx: "ProcessCandidateContext",
    *,
    ceiling_override_usd: Optional[float] = None,
) -> tuple[Optional[Dict[str, Any]], int, float, Dict[str, Any], bool]:
    """Apply deployment/per-order ceilings, budget caps, and the spread gate.

    Shared by :func:`_process_whole_share_candidate`'s real-placement branch
    and its dry-run preview branch so the two can never drift out of sync
    (Codex review: "Apply safety gates to whole-share dry-run previews" --
    the dry-run branch used to report a full-quantity preview even when the
    identical live run would have blocked or clamped it). Purely read-only:
    makes no ledger writes and no broker review/placement calls, so it is
    safe to call from a dry run.

    A single share priced ABOVE ``max_per_order_usd`` is authorized by
    ``ctx.config.whole_share_max_per_order_usd`` instead -- exactly one share,
    never a larger multi-share fire, and never while ``ceiling_override_usd``
    is in play. See the single-share-allowance comment in the body.

    ``ceiling_override_usd``, when given, is combined with
    ``ctx.config.max_per_order_usd`` via ``min()`` -- the effective ceiling
    is whichever is SMALLER. Used to apply the deployment kill switch to a
    preserved-fire redispatch: capping only today's (already-$0) contribution
    does nothing when the fire is funded entirely by an EARLIER day's
    accumulated balance, so the executable order itself must be capped to
    the kill-switch base too, mirroring how the normal buy path caps
    ``order_amount`` directly rather than just the day's raw signal amount
    (Codex review: "Apply the kill switch to the executable whole-share
    fire").

    Returns ``(block_outcome, quantity, order_notional, spread_fields,
    is_error)``. ``block_outcome`` is ``None`` when every gate passes;
    ``quantity``/``order_notional`` reflect any per-order-ceiling clamp
    regardless of pass/fail. ``is_error`` is only ``True`` for a spread-quote
    lookup failure, distinguishing it from a deliberate policy block for the
    caller's errors_count_inc bookkeeping.

    Known limitation (Codex review: "Enforce dollar caps against the
    executable order price", not applied): ``place_whole_share_buy`` submits
    a QUANTITY-based market order, not a dollar-amount one, so the broker is
    free to fill above the signal-time price used here and the actual spend
    is not hard-capped the way a dollar-amount order's is. A price-headroom
    buffer was evaluated and rejected -- see
    ``docs/whole_share_accumulation.md``'s "Risk gates" section for why (it
    collided with the default ``max_per_order_usd=$10`` ceiling at realistic
    BYDDY-range prices and needs verified broker limit-order support to fix
    properly, which this repo does not have -- see ``RobinhoodBroker``'s
    class docstring). The ``whole_share_max_per_order_usd`` allowance added
    2026-08-24 does NOT close this: it authorizes one share at the
    SIGNAL-TIME price, and the broker can still fill a quantity order above
    that price.
    """
    max_shares_by_ceiling, effective_ceiling_usd, _allowance_applied = (
        _whole_share_executable_share_count(
            ctx.config, current_share_price, ceiling_override_usd=ceiling_override_usd
        )
    )
    if _allowance_applied:
        # Logged, not silent: this is the one path that authorizes a single
        # order above max_per_order_usd, so a run where it fired should say
        # so plainly in the run log.
        logger.info(
            "%s: whole-share single-share allowance applied -- one share at $%.2f is above "
            "max per-order $%.2f but within the $%.2f whole-share allowance",
            ticker,
            current_share_price,
            ctx.config.max_per_order_usd,
            ctx.config.whole_share_max_per_order_usd,
        )
    if max_shares_by_ceiling <= 0:
        return (
            {
                "status": "blocked",
                "skip_reason": (
                    f"whole-share: one share (${current_share_price:.2f}) exceeds max per-order "
                    f"${effective_ceiling_usd:.2f}"
                    + (
                        ""
                        if ceiling_override_usd is not None
                        else (
                            " and the whole-share single-share allowance "
                            f"${ctx.config.whole_share_max_per_order_usd:.2f}"
                        )
                    )
                ),
                "deliberate_skip": True,
                "budget_blocked": True,
            },
            quantity,
            order_notional,
            {},
            False,
        )
    if quantity > max_shares_by_ceiling:
        quantity = max_shares_by_ceiling
        order_notional = round(quantity * current_share_price, 2)

    if not within_caps(order_notional, ctx.state, ctx.trading_day, ctx.config):
        return (
            {
                "status": "blocked",
                "skip_reason": "whole-share: cap would be exceeded",
                "deliberate_skip": True,
                "budget_blocked": True,
            },
            quantity,
            order_notional,
            {},
            False,
        )

    try:
        spread_pct = quote_spread_pct(ctx.robinhood_data, ticker, ctx.now)
    except Exception as exc:  # noqa: BLE001
        return (
            {
                "status": "blocked",
                "skip_reason": f"whole-share: spread quote failed: {exc}",
                "deliberate_skip": True,
                **spread_gate_fields(spread_pct=None, max_spread_pct=ctx.config.max_bid_ask_spread_pct),
            },
            quantity,
            order_notional,
            {},
            True,
        )
    spread_fields = spread_gate_fields(spread_pct=spread_pct, max_spread_pct=ctx.config.max_bid_ask_spread_pct)
    if spread_pct is None and ctx.scheduled:
        return (
            {
                "status": "blocked",
                "skip_reason": "whole-share: bid/ask spread unavailable for scheduled run",
                "deliberate_skip": True,
                "blocked_by": BLOCKED_BY_SPREAD_GATE,
                **spread_fields,
            },
            quantity,
            order_notional,
            spread_fields,
            False,
        )
    if spread_pct is not None and spread_pct > ctx.config.max_bid_ask_spread_pct:
        return (
            {
                "status": "blocked",
                "skip_reason": (
                    f"whole-share: bid/ask spread {spread_pct:.2f}% exceeds "
                    f"{ctx.config.max_bid_ask_spread_pct:.2f}% limit"
                ),
                "deliberate_skip": True,
                **spread_fields,
            },
            quantity,
            order_notional,
            spread_fields,
            False,
        )

    return None, quantity, order_notional, spread_fields, False


def _whole_share_claim_is_stale(claimed_at: Optional[str], now_iso: Optional[str]) -> bool:
    """Whether an unresolved claim's ``claimed_at`` is old enough (past
    ``UNRESOLVED_CLAIM_STALE_SECONDS``, the SAME window
    ``dca_whole_share_accumulator``'s own ``record_contribution`` reclaim
    uses) to treat a clean "no live order found" broker result as real
    evidence rather than a possibly-still-in-flight claim.

    Defaults to NOT stale (safer: leave the claim reserved) whenever either
    timestamp is missing or unparseable, mirroring
    ``dca_whole_share_accumulator._claim_is_stale``'s own identical
    default -- not reimplemented from there directly since it is a
    module-private helper.
    """
    if not claimed_at or not now_iso:
        return False
    try:
        claimed_dt = datetime.fromisoformat(claimed_at)
        now_dt = datetime.fromisoformat(now_iso)
        elapsed = (now_dt - claimed_dt).total_seconds()
    except (ValueError, TypeError):
        return False
    return elapsed >= UNRESOLVED_CLAIM_STALE_SECONDS


def _reconcile_unresolved_whole_share_claim(
    ledger: "WholeShareAccumulationLedger",
    broker: "BrokerAdapter",
    ticker: str,
    stream: str,
    idempotency_key: str,
    claim_trading_day_iso: str,
    claim: Dict[str, Any],
    now_iso: Optional[str] = None,
) -> Optional[Dict[str, Any]]:
    """Settle an unresolved whole-share claim IF the broker confirms this
    EXACT ref_id landed, using the claim's own recorded quantity/price.

    Returns ``{"order_id", "shares_purchased", "order_notional_usd"}`` when
    this claim was actually settled, ``{"zero_fill_attempt": True,
    "order_id"}`` when a confirmed EXPLICIT zero-fill terminal order
    released the claim without settling it (a real broker attempt the
    caller must still count toward ``max_orders_per_day``, just without a
    purchase to book -- Codex review: "Count pre-roll zero-fill orders
    toward the attempt cap"), ``{"live_order_found": True, "order_id",
    "planned_notional_usd", "planned_quantity"}`` when a live/working match
    was found but has not yet reached a terminal state (the ledger claim
    stays reserved for a later reconciliation attempt, but the caller must
    still book the claim's own planned notional/quantity as submitted/
    unfilled -- Codex review: "Book live orders discovered during claim
    recovery"), else ``None``. The caller is responsible for booking a
    non-``None`` result into ``ctx.state``/``running_deployed_7d``/
    execution records (Codex review: "Book reconciled orders into the
    strategy budget state") -- this function only touches the whole-share
    ledger itself.

    Shared by the initial same-day duplicate-check reconciliation and the
    cross-day recovery check in :func:`_process_whole_share_candidate` --
    both need the identical safety posture:

    - Only settle on an EXACT ref_id match, never a broad "some same-day
      order exists" match -- the broad check can be True because of a
      completely UNRELATED live order (a manual trade, or a different
      stream's own fire), and settling on that alone would record a
      purchase that never happened for THIS claim, corrupting
      ``shares_purchased_total`` (Codex review: "Require an exact order
      match before settling"). A no-match leaves the claim exactly as-is.
    - Only settle once the matched order has reached a TERMINAL ``"filled"``
      state. While the order is still live and working
      (``"new"``/``"queued"``/``"confirmed"``/``"unconfirmed"``/
      ``"partially_filled"``), its final filled quantity is not yet known --
      settling now (even reserving credit for the full submitted quantity,
      an earlier version of this fix) would mark the claim resolved before
      that is actually true: if the working remainder is later cancelled or
      rejected, there is no unresolved claim left to revisit, so the ledger
      permanently overstates purchased shares while withholding the unfilled
      credit forever (Codex review: "Defer settling recovered orders until
      they are terminal"). A non-terminal match therefore leaves the claim
      reserved and returns ``None`` -- exactly like "no match found" -- so a
      LATER reconciliation attempt (once the order actually settles) can
      complete it correctly.
    - Falls back to the claim's own UNCLAMPED ``shares_to_buy`` only when
      the matched (now-filled) order carries no usable quantity field at
      all -- a per-order-ceiling clamp at placement time would otherwise
      understate the shortfall ``settle()`` restores if this fallback were
      used more broadly.
    - Pass the claim's OWN ``claimed_at`` as ``recorded_at``, never a fresh
      timestamp from this reconciling call -- ``settle()``'s ownership
      guard only reconciles (marks resolved, restores any shortfall) when
      ``recorded_at`` matches the cache entry's own ``claimed_at``; a fresh
      timestamp would silently skip that guard, still bump
      ``shares_purchased_total``, and leave the claim (and any shortfall)
      unresolved forever -- double-counting on every future reconciliation
      attempt too (Codex review: "Reconcile using the original claim
      timestamp").
    - Checks ``settle()``'s own return value to confirm THIS call actually
      transitioned the claim from unresolved to resolved before returning a
      booking result. Two concurrent reconciliation attempts (e.g. the
      same-day duplicate check and the cross-day check both examining the
      SAME claim, or two overlapping scheduler runs) can both discover the
      SAME exact ref_id match and both reach this point; without checking
      ownership, both would call ``settle()`` for the SAME physical broker
      order and both would get back a non-``None`` result, and the caller
      would book (state, budget, execution records) the SAME order twice
      (Codex review: "Make recovered-claim settlement idempotent"). Only
      the caller that actually resolved the claim gets a result back.

    A CLEAN "no match" (the lookup itself succeeded, it simply found no live
    order under this ref_id) is different from the lookup raising -- the
    caller's own try/except already handles a raised lookup conservatively
    (leaves the claim untouched, see "Keep ambiguous claims reserved when
    reconciliation fails"). A clean no-match, once the claim is STALE
    (``now_iso`` is far enough past ``claimed_at``, the SAME
    ``UNRESOLVED_CLAIM_STALE_SECONDS`` window ``record_contribution``'s own
    reclaim eligibility uses), is itself real evidence the order was never
    accepted or was genuinely rejected -- e.g. an ambiguous placement that
    was actually REJECTED, whose OWN immediate ref-id lookup ALSO failed at
    the time (a transient outage), left this claim unresolved rather than
    restored. Without this, every LATER retry's ref-id lookup keeps cleanly
    finding nothing (correctly -- it really was rejected) and this function
    keeps returning `None` unchanged, permanently stranding the deducted
    credit: cross-day recovery only repeats the SAME lookup, and a new
    trading day's own dedup key can never touch this old reservation (Codex
    review: "Restore old claims after a confirmed no-match"). Once stale,
    this releases the claim via ``preserve_pending`` (still returns ``None``
    -- nothing was SETTLED). A claim NOT yet stale is left untouched on a
    clean no-match too -- it could still be genuinely in flight (e.g. a
    same-day claim another active process is still working through between
    its own ``record_contribution`` and ``settle()``/``preserve_pending``
    calls), and restoring it prematurely would double-credit a fire that
    process may yet complete.

    No-op (returns ``None`` without settling) if ``claim["shares_to_buy"]``
    isn't positive, ``claim_trading_day_iso`` doesn't parse as a date, no
    exact ref_id match is found, the match is not yet in a terminal state,
    or a concurrent caller already resolved this claim first.
    """
    if not isinstance(claim, dict) or claim.get("shares_to_buy", 0) <= 0:
        return None
    try:
        claim_trading_day_date = date.fromisoformat(claim_trading_day_iso)
    except ValueError:
        return None
    ref_id = f"{_graded_dca_ref_id_prefix(stream, 'wholeshare')}-{claim_trading_day_iso}-{ticker}"
    matched_order = broker.same_day_strategy_order_exists_with_ref_id_prefix(ticker, claim_trading_day_date, (ref_id,))
    if not matched_order:
        # The live-only lookup above deliberately excludes a genuinely
        # TERMINAL order (cancelled/rejected/expired -- see
        # _LIVE_ORDER_STATES's own comment: "never consumed capacity"). That
        # is the wrong question here: an order that PARTIALLY filled and was
        # THEN cancelled is real, already-executed capital, and this clean
        # "no match" is indistinguishable from an order that never reached
        # the broker at all. Check the terminal-inclusive lookup before
        # falling back to the staleness-based release below, so a partial
        # fill is settled for its real quantity rather than silently
        # released back into pending_usd alongside the unfilled remainder
        # (Codex review: "Reconcile partial fills before releasing canceled
        # claims"). A RAISED lookup is different from a clean "found
        # nothing" -- it establishes NEITHER outcome (mirrors the live
        # lookup's own failure posture, handled by this function's caller):
        # falling through to the staleness-release logic below as if the
        # terminal-inclusive lookup had cleanly found nothing would restore
        # the full planned notional for a claim whose order may have
        # genuinely partially filled, discarding evidence of real spend a
        # transient failure merely hid this attempt (Codex review: "Preserve
        # claims when terminal-history lookup fails"). Leave the claim
        # exactly as record_contribution left it and return immediately.
        try:
            terminal_order = broker.same_day_order_with_ref_id_prefix_any_state(
                ticker, claim_trading_day_date, (ref_id,)
            )
        except Exception:  # noqa: BLE001
            return None
        if terminal_order:
            # The any-state fallback exists to see a genuinely TERMINAL order
            # the live-only lookup deliberately excludes -- but it carries no
            # state filter of its own, so it can just as easily surface a
            # LIVE order that only became visible in the moment between the
            # two lookups (e.g. the live-only call ran before the broker
            # indexed it). That order's cumulative_quantity is not yet final:
            # a positive value would settle the claim while the order can
            # still fill further, and a zero value would release the FULL
            # reservation while the order may still fill later -- either
            # outcome lets the eventual real fill reuse already-spent credit
            # or vanish entirely. Only a genuinely TERMINAL state (this
            # module's canonical non-fill-terminal set, or "filled" itself)
            # is authoritative evidence of the final outcome; anything else
            # leaves the claim exactly as record_contribution left it, for a
            # later attempt once the order actually terminates (Codex
            # review: "Verify terminal state after the any-state fallback").
            # Mirrors the live-only branch's own "matched_state != 'filled':
            # return None" guard just below in this same function.
            terminal_order_state = str(terminal_order.get("state", "")).lower()
            if terminal_order_state not in _TERMINAL_NON_FILL_STATES and terminal_order_state != "filled":
                return None
            # For a genuinely non-fill terminal state (cancelled/rejected/
            # expired), only cumulative_quantity is trustworthy evidence of
            # what actually executed -- that order's own "quantity" field is
            # merely what was REQUESTED/submitted, not what executed.
            # Falling back to it there (as an earlier version of this fix
            # did) would treat every requested share of a genuinely rejected
            # order as filled, inflating the ledger and withholding credit
            # for shares that never executed (Codex review: "Do not treat
            # requested quantity as a terminal fill"). But when this
            # any-state lookup instead finds the order EXPLICITLY "filled"
            # (the live-only lookup can miss an eventually-consistent order
            # that the immediately following any-state lookup then does
            # see), it is exactly as authoritative as the live matched_state
            # == "filled" branch below, which already falls back to
            # "quantity" -- restricting this branch to cumulative_quantity
            # alone in that case left filled_shares at 0 whenever a filled
            # order omitted cumulative_quantity, silently restoring the
            # FULL claim as if nothing executed and making its spent credit
            # reusable (Codex review: "Use requested quantity for any-state
            # filled orders"). An absent cumulative_quantity (and, for a
            # filled order, an absent quantity too) leaves the execution
            # amount UNKNOWN, not zero -- a cancelled/rejected/expired order
            # can still have partially executed before it terminated, and
            # the omission of the field proves nothing either way. Restoring
            # the claim on an unknown quantity would release spent credit
            # for shares that may really have filled (Codex review: "Keep
            # terminal claims reserved when fill quantity is absent"),
            # mirroring this module's own identical distinction for CSV-
            # sourced terminal evidence (see
            # _executed_quantity_is_explicit_zero's docstring).
            raw_terminal_quantity = terminal_order.get("cumulative_quantity")
            if raw_terminal_quantity is None and terminal_order_state == "filled":
                raw_terminal_quantity = terminal_order.get("quantity")
            filled_shares = 0
            quantity_is_known = False
            if raw_terminal_quantity is not None:
                try:
                    filled_shares = int(float(raw_terminal_quantity))
                    quantity_is_known = True
                except (TypeError, ValueError, OverflowError):
                    # OverflowError as well: Python ints are unbounded, so a
                    # broker-supplied 10**1000 or an infinite float raises
                    # here rather than converting, and this is external data.
                    # It escaped the handler entirely -- past the placement
                    # `except` that discovered this terminal order, past this
                    # function, into the batch loop's last-resort net, which
                    # has no idea a terminal order was ever found and writes
                    # an ordinary failed row while the batch keeps placing
                    # (Codex review, PR #786: "Preserve terminal orders when
                    # quantity parsing overflows"). Caught, it lands where an
                    # unreadable figure belongs: quantity_is_known stays
                    # False, so the claim is left exactly as
                    # record_contribution wrote it, reserved for better
                    # evidence -- an unparseable fill is UNKNOWN, never zero.
                    filled_shares = 0
            if filled_shares > 0:
                # Routed through `_normalized_order_id`, not the bare
                # `str(_first_usable_order_id_alias(...) or "") or None`
                # this used to be: `_is_usable_order_id_scalar` (which
                # gates whether `terminal_order` is trusted at all) already
                # accepts a positive native integer beyond Python's
                # integer-to-string conversion digit limit (e.g.
                # `10**5000`), so the bare `str()` call raised `ValueError`
                # for exactly the recovered terminal order this settlement
                # exists to durably record -- aborting bookkeeping for a
                # broker order already known to have a positive fill
                # (Codex review, PR #1169: "Avoid stringifying
                # unrepresentable recovered IDs").
                return _settle_whole_share_claim(
                    ledger, ticker, claim, claim_trading_day_iso, filled_shares, stream, idempotency_key,
                    order_id=_normalized_order_id(_first_usable_order_id_alias(terminal_order)),
                    fill_price_usd=_usable_positive_float(terminal_order.get("average_price")),
                )
            if not quantity_is_known:
                # Terminal, but with no parseable evidence of what (if
                # anything) executed -- leave the claim exactly as
                # record_contribution left it, for a later attempt once
                # better evidence is available, rather than guessing zero.
                return None
            # A confirmed EXPLICIT zero fill (a clean rejection/cancellation
            # before any execution) is definitive -- no need to wait for
            # staleness, unlike the "found nothing at all" case below, which
            # cannot rule out the order still being in flight somewhere the
            # lookup didn't see.
            #
            # Restore and verify ownership as ONE atomic, single-locked
            # operation -- a separate still_claimed() check followed by a
            # separate preserve_pending() call is NOT atomic: the broker's
            # terminal-order lookup above is itself a network round-trip,
            # and another attempt can reclaim this exact claim in the gap
            # between two independently locked calls, so a still_claimed()
            # pass would not guarantee the FOLLOWING preserve_pending()
            # still owns the claim (Codex review: "Make zero-fill claim
            # release atomic"). preserve_pending_if_claimed() performs the
            # SAME ownership check and restoration inside a single lock and
            # reports whether THIS call actually won it.
            try:
                resolved = ledger.preserve_pending_if_claimed(
                    ticker,
                    claim_trading_day_iso,
                    float(claim.get("order_notional_usd", 0.0)),
                    stream=stream,
                    recorded_at=claim.get("claimed_at"),
                    idempotency_key=idempotency_key,
                    claim_token=claim.get("claim_token"),
                    # ``claim`` is the snapshot returned by
                    # unresolved_claim() BEFORE the network round-trip above
                    # that produced this "confirmed zero-fill" evidence --
                    # passing what it showed for "placed" lets
                    # preserve_pending_if_claimed() detect a genuinely NEW
                    # order landing for this same claim_token in the gap and
                    # decline instead of erasing that live order's markers
                    # (Codex review discussion_r3825818000, "Preserve orders
                    # placed during zero-fill restoration").
                    expected_placed=bool(claim.get("placed")),
                    expected_placing=bool(claim.get("placing")),
                )
            except Exception:  # noqa: BLE001 - the claim release itself failed,
                # so the claim is STILL unresolved -- returning the
                # zero_fill_attempt result below unconditionally (as an
                # earlier version of this fix did) would still tell the
                # caller to book a real attempt and publish this order id
                # even though nothing was actually released. A LATER
                # reconciliation pass (this same function runs from both a
                # pre-pass and the per-candidate safety net) would then
                # encounter the SAME still-unresolved claim again and record
                # the identical attempt a second (or third) time, inflating
                # max_orders_per_day accounting for a single real order
                # (Codex review: "Book zero-fill attempts only after
                # releasing the claim"). Return None -- exactly like a
                # failed lookup elsewhere in this function -- so a later,
                # successful reconciliation attempt is the one that books it.
                return None
            if not resolved:
                # Lost the claim to a newer attempt (either before this
                # call started, or in the gap this atomic call closes) --
                # nothing was restored, so the reclaiming owner's own
                # reconciliation of this SAME broker order is the one that
                # should book it, not this caller.
                return None
            # Returning None here (as an earlier version of this fix did)
            # told the caller "nothing to book" -- but a confirmed zero-fill
            # order is a REAL broker attempt, and config.max_orders_per_day
            # (circuit_breakers) is defined as an ATTEMPT count where a
            # cancelled/rejected order still consumes one of the shared
            # daily slots (matching seed_prior_allocation's own identical
            # contract, and the immediate placement-error sibling branch's
            # own record_buy(..., 0.0) fix). Without this, the pre-roll/
            # cross-day reconciliation path (the caller of THIS function)
            # left the in-memory attempt count one too low and the
            # persisted artifact with no order ID to reconstruct the
            # missing attempt from on a later run, letting later candidates
            # place beyond the configured ceiling (Codex review: "Count
            # pre-roll zero-fill orders toward the attempt cap"). A
            # distinct shape from a real settlement result (no
            # "shares_purchased"/"order_notional_usd") so the caller can
            # book just the attempt without publishing a false "submitted"
            # outcome.
            return {
                "zero_fill_attempt": True,
                "order_id": _normalized_order_id(_first_usable_order_id_alias(terminal_order)),
            }
        if _whole_share_claim_is_stale(claim.get("claimed_at"), now_iso):
            try:
                ledger.preserve_pending(
                    ticker,
                    claim_trading_day_iso,
                    float(claim.get("order_notional_usd", 0.0)),
                    stream=stream,
                    recorded_at=claim.get("claimed_at"),
                    idempotency_key=idempotency_key,
                    claim_token=claim.get("claim_token"),
                )
            except Exception:  # noqa: BLE001 - best-effort release; the caller's
                # own try/except already treats this whole function as
                # best-effort, but a raise here must not propagate a
                # DIFFERENT exception type mid-branch.
                pass
        return None
    matched_state = str(matched_order.get("state", "")).lower()
    if matched_state != "filled":
        # A live/working match (new/confirmed/partially_filled) IS real
        # evidence the broker accepted this order -- returning None here (as
        # an earlier version of this fix did) told the caller "nothing to
        # book," so a batch pre-pass or the initial same-day duplicate-check
        # call could find this exact order, correctly leave the LEDGER claim
        # reserved (its final filled quantity genuinely isn't known yet), but
        # then skip the ticker entirely without calling record_buy() or
        # adding its requested notional to running_deployed_7d -- letting
        # later candidates in the same batch exceed the daily attempt count,
        # daily/weekly notional caps, or the kill switch while this accepted
        # order remains live and uncounted, exactly the gap the immediate
        # ordinary-success-path's own "not yet visible"/nonterminal branch
        # was already fixed to close (Codex review: "Book live orders
        # discovered during claim recovery"). Distinct shape from a real
        # settlement result: carries the actual EXECUTABLE notional/
        # quantity (the real fill is not yet known), not
        # "shares_purchased"/"order_notional_usd", so the caller books it as
        # submitted/unfilled without touching the ledger's own claim.
        #
        # Uses the matched order's OWN submitted "quantity" when available,
        # NOT the claim's cached (pre-clamp) shares_to_buy/order_notional_usd
        # -- a per-order-ceiling or kill-switch clamp at placement time can
        # have submitted FEWER shares than the claim originally planned
        # (e.g. a 3-share $30 fire actually placed as a 1-share $10 order),
        # and booking the unclamped claim figure here would overstate this
        # run's own batch caps and trailing deployment enough to spuriously
        # block unrelated candidates (Codex review: "Book only the
        # executable quantity for recovered live orders"). Falls back to
        # the claim's own shares_to_buy only when the broker's response
        # carries no usable quantity field at all.
        raw_submitted_quantity = matched_order.get("quantity")
        planned_quantity = int(claim.get("shares_to_buy", 0))
        if raw_submitted_quantity is not None:
            try:
                planned_quantity = int(float(raw_submitted_quantity))
            except (TypeError, ValueError, OverflowError):
                # OverflowError as well -- see the terminal-quantity parse
                # above. Falls back to the claim's own shares_to_buy, which
                # is already this branch's documented no-usable-quantity
                # answer, rather than escaping as an unhandled raise.
                pass
        planned_notional = round(planned_quantity * float(claim.get("current_share_price_usd", 0.0)), 2)
        return {
            "live_order_found": True,
            "order_id": _normalized_order_id(_first_usable_order_id_alias(matched_order)),
            "planned_notional_usd": planned_notional,
            "planned_quantity": planned_quantity,
        }
    shares_purchased = int(claim["shares_to_buy"])
    raw_quantity = matched_order.get("cumulative_quantity") or matched_order.get("quantity")
    if raw_quantity is not None:
        try:
            shares_purchased = int(float(raw_quantity))
        except (TypeError, ValueError, OverflowError):
            # OverflowError as well -- see the terminal-quantity parse above.
            pass
    return _settle_whole_share_claim(
        ledger, ticker, claim, claim_trading_day_iso, shares_purchased, stream, idempotency_key,
        order_id=_normalized_order_id(_first_usable_order_id_alias(matched_order)),
        fill_price_usd=_usable_positive_float(matched_order.get("average_price")),
    )


def _usable_positive_float(raw: Any) -> Optional[float]:
    """Best-effort ``float(raw)``, or ``None`` if unparseable/non-positive.

    Shared by the whole-share reconciliation settlement helper below to
    validate a broker order's ``average_price`` before trusting it over the
    claim's own cached signal-time price.
    """
    if raw is None:
        return None
    try:
        value = float(raw)
    except (TypeError, ValueError, OverflowError):
        # See _alpaca_float_or_nan. This one guards a broker average_price
        # headed for budget state, so a raise here escapes into the batch.
        return None
    # A parseable but non-finite value (e.g. "Infinity"/"NaN", which some
    # JSON encoders/broker payloads can produce) passes a bare `value > 0`
    # check -- infinity IS greater than zero -- and would compute an
    # infinite order notional written straight into strategy budget state,
    # deployment totals, and JSON artifacts (Codex review: "Reject
    # non-finite recovered fill prices").
    if not math.isfinite(value):
        return None
    return value if value > 0 else None


def _settle_whole_share_claim(
    ledger: Any,
    ticker: str,
    claim: Dict[str, Any],
    claim_trading_day_iso: str,
    shares_purchased: int,
    stream: str,
    idempotency_key: str,
    *,
    order_id: Optional[str],
    fill_price_usd: Optional[float] = None,
) -> Optional[Dict[str, Any]]:
    """Shared ``ledger.settle()`` call + idempotency check for
    :func:`_reconcile_unresolved_whole_share_claim`'s two settlement sites
    (an exact terminal-filled live match, and a terminal-inclusive match
    that executed a partial fill before being cancelled/rejected).

    ``fill_price_usd``, when given (the broker order's own reported
    ``average_price``), is used to compute the booked notional INSTEAD of
    the claim's cached signal-time price -- a quantity-based market order
    can fill above or below the price that was quoted when the fire was
    originally planned, so using the stale cached price would book a
    different dollar amount into ``StrategyState``/deployment history/the
    kill-switch total than what the broker actually spent (Codex review:
    "Use the recovered fill price when booking deployment"). The cached
    price remains authoritative for the ledger's OWN shortfall math inside
    ``settle()`` itself (comparing planned vs. purchased SHARE counts, not
    dollars) -- only the returned/booked notional changes here.
    """
    cached_price = float(claim.get("current_share_price_usd", 0.0))
    price_for_notional = fill_price_usd if fill_price_usd is not None else cached_price
    order_notional = round(shares_purchased * price_for_notional, 2)
    resolved_by_this_call = ledger.settle(
        ticker,
        claim_trading_day_iso,
        shares_purchased,
        order_notional,
        stream=stream,
        recorded_at=claim.get("claimed_at"),
        idempotency_key=idempotency_key,
        claim_token=claim.get("claim_token"),
        # This helper only ever settles a claim it DISCOVERED via a
        # reconciliation lookup, never one it just placed -- require_claim_
        # ownership=True ensures a losing concurrent reconciler's call
        # mutates nothing at all (not even shares_purchased_total/the audit
        # event), matching this function's own idempotency check just below
        # (Codex review: "Update ledger totals only for the winning
        # reconciliation").
        require_claim_ownership=True,
    )
    if not resolved_by_this_call:
        return None
    result: Dict[str, Any] = {
        "order_id": order_id,
        "shares_purchased": shares_purchased,
        "order_notional_usd": order_notional,
    }
    # Carry the broker's own authoritative fill evidence (already extracted
    # above as fill_price_usd/shares_purchased) through to the caller's
    # execution-record logging, so it can pass it as _log_execution's
    # known_fill instead of re-querying broker.get_order_fill() for an order
    # this reconciliation call already proved landed -- a separate lookup
    # can itself be eventually consistent and report a clean miss, silently
    # discarding proven fill data and misrecording a real fill as submitted/
    # unfilled (Codex review: "Reuse known fill data when logging recovered
    # claims"). Only built when a real broker-reported price is available --
    # a fallback to the claim's own cached signal-time price is not
    # broker-confirmed fill evidence and must not masquerade as one.
    if fill_price_usd is not None:
        result["known_fill"] = OrderFill(avg_fill_price=fill_price_usd, quantity_filled=shares_purchased)
    return result


def _book_reconciled_whole_share_order(
    ctx: "ProcessCandidateContext",
    decision: ReconciledDecision,
    ticker: str,
    claim_trading_day_iso: str,
    reconciled: Dict[str, Any],
    running_deployed_7d: float,
) -> float:
    """Book a reconciled whole-share order (see
    :func:`_reconcile_unresolved_whole_share_claim`) into the SAME places a
    normal, in-line placement books into -- ``ctx.state.record_buy``,
    ``ctx.state.own_orders_recorded``, the running 7-day deployment total
    (for kill-switch accuracy this run), and the in-flight/execution
    record artifacts.

    Without this, a reconciled order that genuinely landed at the broker
    was recorded in the whole-share ledger but nowhere else: daily/weekly
    budget caps, the deployment kill switch, and persisted execution
    artifacts all silently omitted real spend the broker already executed
    (Codex review: "Book reconciled orders into the strategy budget
    state"). Returns the (possibly updated) ``running_deployed_7d``.
    """
    if reconciled.get("zero_fill_attempt"):
        # A confirmed EXPLICIT zero-fill terminal order: nothing was
        # purchased (no shares, no notional), but it is still a REAL
        # broker attempt that must count toward max_orders_per_day, just
        # like the immediate placement-error branch's own identical fix
        # (Codex review: "Count pre-roll zero-fill orders toward the
        # attempt cap"). Distinct handling from the settled-order path
        # below: publishing a "submitted" outcome for zero shares/zero
        # dollars would misreport a rejected order as a purchase.
        order_id = reconciled.get("order_id")
        try:
            claim_trading_day_date = date.fromisoformat(claim_trading_day_iso)
        except ValueError:
            claim_trading_day_date = ctx.trading_day
        already_recorded = (
            ctx.deployment_history_root is not None
            and _same_day_ticker_deployment_already_recorded(
                ticker, claim_trading_day_date, ctx.deployment_history_root
            )
        )
        if already_recorded:
            return running_deployed_7d
        ctx.state.record_buy(ticker, claim_trading_day_date, 0.0, order_id=order_id)
        ctx.state.own_orders_recorded.add((ticker, claim_trading_day_date))
        # MERGED, not suppressed. This used to skip publication entirely when
        # another claim for the same ticker had already settled for real in
        # this batch, on the grounds that "the attempt is still counted above
        # via record_buy regardless of whether this outcome gets published".
        # That is true of THIS run's in-memory state and false of the next
        # one: `load_prior_same_day_allocations` reconstructs the cap from the
        # ARTIFACT, so a suppressed zero-fill took its `merged_attempt_days`,
        # `merged_attempt_count` and order id with it, and one slot was
        # charged for two real broker attempts -- leaving room for an order
        # beyond `max_orders_per_day`. Which claim happened to be reconciled
        # first is arbitrary, so the outcome must not depend on it (Codex
        # review, PR #786: "Merge zero-fill recoveries regardless of arrival
        # order"). Round 38's lesson at a second publication site: a value
        # that never reaches the artifact is a value the next run does not
        # have.
        #
        # `_publish_or_merge_whole_share_outcome` is exactly the right
        # publisher and needed no change: `_outcome_is_mergeable_recovery`
        # already counts a marked zero-fill attempt alongside a submission
        # (round 34), and the merge keeps the settled claim's own
        # status/notional while recording this attempt's day and id beside
        # it -- so nothing here can misreport a rejected order as a purchase,
        # which is what the old suppression was protecting.
        _publish_or_merge_whole_share_outcome(
            ticker,
            {
                "status": "failed",
                "order_id": order_id,
                "skip_reason": (
                    f"whole-share: confirmed zero-fill terminal order reconciled cross-day "
                    f"(trading_day={claim_trading_day_iso})"
                ),
                # A "status": "failed" recovery is otherwise
                # indistinguishable from an ORDINARY failed-candidate
                # outcome once this batch's own outer loop later reads
                # it back -- that loop's seeded/mid-call recovery
                # preservation only ever looked for "submitted", so this
                # real broker attempt (a confirmed zero-fill terminal
                # order, still countable toward max_orders_per_day) was
                # silently overwritten the moment today's own processing
                # for the SAME ticker produced any outcome at all (Codex
                # review: "Preserve recovered zero-fill attempts through
                # the batch"). This explicit marker lets that loop
                # recognize and preserve it the same way it already
                # preserves a "submitted" recovery.
                "whole_share_zero_fill_attempt": True,
                # The claim's own trading day is otherwise recorded only
                # inside the free-text skip_reason above --
                # load_prior_same_day_allocations's cross-day-recovery
                # exclusion reads ONLY this machine-readable breakdown
                # field (never skip_reason text) to tell "this attempt
                # belongs to an earlier claim day, already counted via
                # ctx.state.record_buy(..., claim_trading_day_date, ...)
                # above" apart from "this is a fresh attempt made today".
                # Without it, a cross-day zero-fill recovery reloaded on
                # a LATER run would be misattributed to that later run's
                # own trading day, double-counting against
                # max_orders_per_day for a day the attempt never
                # actually happened on (Codex review: "Keep recovered
                # zero-fill attempts on the claim day"). amount_usd is
                # 0.0 -- a confirmed zero fill moved no capital.
                "whole_share_claim_breakdown": [
                    {"trading_day": claim_trading_day_iso, "amount_usd": 0.0}
                ],
            },
        )
        return running_deployed_7d
    if reconciled.get("live_order_found"):
        # A live/working match was found but has not yet reached a terminal
        # state -- the ledger claim stays reserved (its real filled quantity
        # isn't known yet), but the accepted order is real evidence that
        # must still count toward this run's own budget/attempt tracking,
        # mirroring the ordinary in-line placement path's own identical
        # "not yet visible"/nonterminal branch (Codex review: "Book live
        # orders discovered during claim recovery"). Books the CLAIM's own
        # planned notional/quantity -- the real fill is not yet known -- and
        # publishes a "submitted"/unfilled outcome without ever calling
        # ledger.settle().
        order_id = reconciled.get("order_id")
        planned_notional = float(reconciled.get("planned_notional_usd") or 0.0)
        planned_quantity = int(reconciled.get("planned_quantity") or 0)
        try:
            claim_trading_day_date = date.fromisoformat(claim_trading_day_iso)
        except ValueError:
            claim_trading_day_date = ctx.trading_day
        # Anchored at ctx.trading_day (TODAY), not claim_trading_day_date --
        # this claim stays deliberately unresolved while the order remains
        # live, so it is reconciled and (without this) rebooked on EVERY
        # later run; the prior recovery's own artifact was written under
        # THAT run's trading_day, never the claim's original day, so an
        # exact-trading_day match can never find it (Codex review: "Avoid
        # rebooking a recovered live order on every later run"). Matches by
        # order id instead, see _same_day_order_id_already_recorded's own
        # docstring.
        already_recorded = (
            ctx.deployment_history_root is not None
            and _same_day_order_id_already_recorded(
                order_id, ticker, ctx.trading_day, ctx.deployment_history_root
            )
        )
        if already_recorded:
            return running_deployed_7d
        ctx.state.record_buy(ticker, claim_trading_day_date, planned_notional, order_id=order_id)
        ctx.state.own_orders_recorded.add((ticker, claim_trading_day_date))
        from dca_risk import KILL_SWITCH_WINDOW_DAYS

        if ctx.scheduled and 0 <= (
            ctx.trading_day.toordinal() - claim_trading_day_date.toordinal()
        ) < KILL_SWITCH_WINDOW_DAYS:
            running_deployed_7d += planned_notional
        _publish_or_merge_whole_share_outcome(
            ticker,
            {
                "status": "submitted",
                "order_id": order_id,
                "skip_reason": None,
                "submitted_amount_usd": planned_notional,
                "whole_share_quantity": planned_quantity,
                "whole_share_settlement_reconciliation_needed": True,
                "whole_share_claim_breakdown": [
                    {"trading_day": claim_trading_day_iso, "amount_usd": planned_notional}
                ],
            },
        )
        if ctx.run_result is not None:
            log_decision = decision
            if not log_decision.target_price and planned_quantity:
                log_decision = replace(
                    decision,
                    target_price=round(planned_notional / planned_quantity, 4),
                    target_price_source="whole_share_reconciliation:booked_price",
                )
            _log_execution(ctx.run_result, log_decision, order_id or "", ctx.broker, notional_usd=planned_notional)
        return running_deployed_7d
    order_notional = reconciled["order_notional_usd"]
    order_id = reconciled["order_id"]
    try:
        claim_trading_day_date = date.fromisoformat(claim_trading_day_iso)
    except ValueError:
        claim_trading_day_date = ctx.trading_day
    # A settle()-failure branch elsewhere in this module (the ambiguous
    # placement-recovery path, and the ordinary in-line placement path) both
    # already book ctx.state.record_buy/own_orders_recorded and write a
    # "submitted" execution artifact for their own trading day WHEN THE
    # BROKER ORDER IS CONFIRMED, even if the ledger's own settle() call then
    # raises and leaves the claim unresolved. A LATER run's cross-day
    # reconciliation can find that same still-unresolved claim, settle it
    # successfully this time, and reach this function -- rebooking the SAME
    # already-persisted order a second time would double-count it in both
    # this run's own daily/weekly caps and the persisted deployment history
    # a future run's kill-switch figure sums from disk (Codex review: "Avoid
    # rebooking orders after a settlement-only retry"). Check on-disk
    # deployment history for THIS ticker/day before booking again -- the
    # same evidence check the same-stream duplicate-preserved path already
    # uses for an identical reason just below in this module.
    #
    # ALSO checked by order id, anchored at today: this exact order may
    # already have been provisionally booked as "live_order_found" (see
    # above) on some EARLIER run while it was still live -- that
    # provisional row was published under THAT run's own trading_day, not
    # claim_trading_day_date, so the ticker/day check above can never see
    # it. Without this, a later run that finds the SAME order now
    # terminally filled books and publishes it a SECOND time, and
    # dca_risk.deployed_usd_by_claim_date() then attributes both rows to
    # the claim date, doubling trailing deployment and potentially
    # engaging the kill switch or caps prematurely (Codex review:
    # "Deduplicate terminal recoveries by broker order ID").
    ticker_day_already_recorded = ctx.deployment_history_root is not None and (
        _same_day_ticker_deployment_already_recorded(
            ticker, claim_trading_day_date, ctx.deployment_history_root
        )
    )
    recorded_order = (
        _find_same_day_recorded_order(order_id, ticker, ctx.trading_day, ctx.deployment_history_root)
        if ctx.deployment_history_root is not None
        else None
    )
    if recorded_order is not None:
        # This exact order was already published -- either by an earlier
        # run's own settlement-only retry of THIS SAME claim day (the
        # ticker/day check above would also catch that), or by an earlier
        # run's PROVISIONAL "live_order_found" booking while the order was
        # still live (only THIS order-id match can catch that; see that
        # check's own docstring). A provisional booking used the CLAIM's
        # own submitted quantity at the claim's cached signal-time price --
        # not the broker's real fill price, which is not yet known while
        # an order is still live -- so the terminal settlement reached HERE
        # (using the broker's own average_price when available) can differ
        # from what was provisionally recorded. Unconditionally skipping
        # (an earlier version of this fix did) would suppress that
        # correction forever: the provisional artifact's dollar figure
        # stays permanently wrong, and dca_risk.deployed_usd_by_claim_date()
        # (which sums whole_share_claim_breakdown across every artifact for
        # this claim date) keeps summing the stale, uncorrected amount
        # (Codex review: "Reconcile provisional deployment to the final
        # fill"). Read the recorded PROVISIONAL amount from the matched
        # row's own whole_share_claim_breakdown entry for THIS claim date --
        # NOT a top-level submitted_amount_usd/planned_amount_usd (the
        # persisted field is actually "planned_amount_usd", not
        # "submitted_amount_usd" -- Codex review: "Read the persisted
        # provisional amount before applying the delta") and NOT the row's
        # own total (which can be an AGGREGATE of several separate orders'
        # notionals merged together by _merge_whole_share_submission_
        # outcomes, misattributing the whole aggregate to just the one
        # order settling here -- Codex review: "Associate provisional
        # notionals with individual order IDs"). The breakdown entry is
        # keyed by claim trading_day, one entry per distinct claim/order,
        # so it survives aggregation intact regardless of how many OTHER
        # orders got merged into the same row.
        recorded_amount = 0.0
        for _entry in recorded_order.get("whole_share_claim_breakdown") or []:
            if isinstance(_entry, dict) and _entry.get("trading_day") == claim_trading_day_iso:
                try:
                    recorded_amount = float(_entry.get("amount_usd") or 0.0)
                except (TypeError, ValueError):
                    recorded_amount = 0.0
                break
        delta = round(order_notional - recorded_amount, 2)
        # Only an UPWARD correction (the real settlement exceeds what was
        # already recorded) is ever published -- schemas/run_state.schema
        # constrains planned_amount_usd to be non-negative, and a negative
        # submitted_amount_usd would also be silently discarded outright by
        # this same loader's own `amount <= 0: continue` guard just below,
        # so a downward correction has no safe persisted representation
        # without deeper schema/loader changes (Codex review: "Represent
        # negative reconciliation deltas outside order amounts"). The
        # existing provisional record therefore stands as a (deliberately
        # conservative, upper-bound) estimate when the real fill comes in
        # lower -- erring toward OVER-counting deployed capital is the safe
        # direction for a risk/budget system: it can only make this run's
        # own caps/kill-switch MORE conservative, never less, at the cost
        # of a minor, self-correcting-on-signal-price-drift inaccuracy
        # rather than a systemic under-count.
        if delta <= 0.0:
            logger.info(
                "Whole-share claim for %s (trading_day=%s) settled by this retry at $%.2f, at or "
                "below the $%.2f already recorded -- skipping rebooking (downward corrections are "
                "not published; the existing record stands as a conservative upper bound), "
                "order_id=%s",
                ticker,
                claim_trading_day_iso,
                order_notional,
                recorded_amount,
                order_id,
            )
            return running_deployed_7d
        logger.info(
            "Whole-share claim for %s (trading_day=%s) settled by this retry at $%.2f, but a "
            "provisional recovery already recorded $%.2f -- publishing a $%.2f reconciliation "
            "adjustment instead of rebooking the full amount, order_id=%s",
            ticker,
            claim_trading_day_iso,
            order_notional,
            recorded_amount,
            delta,
            order_id,
        )
        # Deliberately does NOT call ctx.state.record_buy() here -- that
        # would increment submitted_order_count_by_day for
        # claim_trading_day_date a SECOND time (the provisional booking
        # already incremented it once for this same physical order),
        # inflating max_orders_per_day accounting for one real attempt
        # (Codex review: "Avoid counting a settlement adjustment as
        # another order attempt"). Only the kill-switch total and the
        # persisted breakdown need the correction; within_caps only ever
        # checks ctx.trading_day's own totals, never an arbitrary historical
        # claim_trading_day_date, so skipping record_buy here costs nothing
        # for this run's own remaining candidates.
        from dca_risk import KILL_SWITCH_WINDOW_DAYS

        if ctx.scheduled and 0 <= (
            ctx.trading_day.toordinal() - claim_trading_day_date.toordinal()
        ) < KILL_SWITCH_WINDOW_DAYS:
            running_deployed_7d += delta
        _publish_or_merge_whole_share_outcome(
            ticker,
            {
                "status": "submitted",
                "order_id": order_id,
                "skip_reason": None,
                "submitted_amount_usd": delta,
                "whole_share_quantity": 0,
                "whole_share_claim_breakdown": [
                    {"trading_day": claim_trading_day_iso, "amount_usd": delta}
                ],
                # Explicit marker (not just "does the breakdown avoid
                # today's own trading_day_iso" -- the SAME-day case, where
                # the provisional booking and this settlement both happen
                # on today's own trading_day, makes that check false even
                # though this row still must never count as a fresh
                # attempt: the provisional booking already counted it once
                # (Codex review: "Exclude same-day settlement deltas from
                # attempt counts"). load_prior_same_day_allocations checks
                # this marker unconditionally, regardless of date.
                "whole_share_settlement_adjustment": True,
            },
        )
        if ctx.run_result is not None:
            _log_execution(
                ctx.run_result,
                decision,
                order_id or "",
                ctx.broker,
                notional_usd=delta,
                known_fill=reconciled.get("known_fill"),
            )
        return running_deployed_7d
    if ticker_day_already_recorded:
        logger.info(
            "Whole-share claim for %s (trading_day=%s) settled by this retry, but its order "
            "was already recorded in deployment history -- skipping rebooking, order_id=%s",
            ticker,
            claim_trading_day_iso,
            order_id,
        )
        return running_deployed_7d
    ctx.state.record_buy(ticker, claim_trading_day_date, order_notional, order_id=order_id)
    ctx.state.own_orders_recorded.add((ticker, claim_trading_day_date))
    # Cross-day recovery (see the caller's own docstring) can discover a
    # claim from ANY earlier trading day, including one outside the
    # trailing 7-calendar-day window `dca_risk.seven_day_deployed` (the
    # normal history loader `running_deployed_7d` is seeded from) itself
    # explicitly excludes. Adding an old reconciled notional to the
    # in-memory running_deployed_7d total unconditionally would treat a
    # purchase from, say, three weeks ago as CURRENT deployment and could
    # spuriously engage the kill switch for later candidates in this SAME
    # batch, even though the loader this figure is otherwise built from
    # would never have counted it (Codex review: "Exclude old
    # reconciliations from the trailing deployment total"). Local import:
    # dca_risk imports FROM this module (StrategyConfig,
    # kill_switch_engaged), so importing it back at module level here would
    # be circular.
    from dca_risk import KILL_SWITCH_WINDOW_DAYS

    if ctx.scheduled and 0 <= (
        ctx.trading_day.toordinal() - claim_trading_day_date.toordinal()
    ) < KILL_SWITCH_WINDOW_DAYS:
        running_deployed_7d += order_notional
    logger.info(
        "Reconciled whole-share buy for %s: %d share(s), $%.2f, order_id=%s (trading_day=%s)",
        ticker,
        reconciled["shares_purchased"],
        order_notional,
        order_id,
        claim_trading_day_iso,
    )
    # Publishing into THIS run's own buy_candidates.csv/run_state.json
    # always tags the row with whole_share_claim_trading_day (the claim's
    # TRUE execution date), so dca_risk.deployed_usd_by_claim_date() can
    # bucket it under that date rather than this artifact's own
    # trading_day (today) -- a three-week-old fill no longer looks like
    # FRESH seven-day deployment on the next run's kill-switch seeding, and
    # an in-window fill's effective window no longer stretches by however
    # many days separate the claim date from today (Codex review:
    # "Attribute reconciled deployment to the claim date", "Preserve the
    # claim date for in-window recoveries"). This makes the publication
    # itself unconditionally safe regardless of window -- an earlier
    # version of this fix instead skipped publishing entirely for an
    # out-of-window claim, since without a dated field there was no way to
    # publish one without misattributing it.
    _publish_or_merge_whole_share_outcome(
        ticker,
        {
            "status": "submitted",
            "order_id": order_id,
            "skip_reason": None,
            "submitted_amount_usd": order_notional,
            "whole_share_quantity": reconciled["shares_purchased"],
            # A LIST, not a single date -- when this outcome is later
            # aggregated (see _merge_whole_share_submission_outcomes) with
            # ANOTHER reconciled claim from a DIFFERENT trading day, a
            # single scalar override could only ever carry one of the two
            # dates, permanently misattributing whichever claim lost. Each
            # entry keeps its own claim date paired with its own dollar
            # amount so dca_risk.deployed_usd_by_claim_date() can bucket
            # every contributing claim correctly even after aggregation.
            "whole_share_claim_breakdown": [
                {"trading_day": claim_trading_day_iso, "amount_usd": order_notional}
            ],
        },
    )
    if ctx.run_result is not None:
        # The batch pre-pass's synthetic decision (see
        # _reconcile_cross_day_whole_share_claims_for_batch) leaves
        # target_price at its dataclass default of 0.0 -- it is built once
        # per ticker BEFORE any claim is reconciled, so it cannot know the
        # price a specific claim booked at. build_execution_record()
        # computes slippage as avg_fill_price - target_price; with
        # target_price=0.0, the ENTIRE fill price reads as adverse
        # slippage and the entire notional as slippage cost, misreporting
        # a normal reconciled fill as catastrophically poor execution
        # (Codex review: "Supply a real target for recovered execution
        # records"). The reconciled order's own effective price-per-share
        # (order_notional_usd / shares_purchased -- the fill price when
        # one was used, else the claim's cached signal-time price; see
        # _settle_whole_share_claim) is the correct target for a claim
        # that was reconciled after the fact, not a decision this run
        # never fetched a fresh quote for.
        log_decision = decision
        if not log_decision.target_price and reconciled.get("shares_purchased"):
            log_decision = replace(
                decision,
                target_price=round(order_notional / reconciled["shares_purchased"], 4),
                target_price_source="whole_share_reconciliation:booked_price",
            )
        _log_execution(
            ctx.run_result,
            log_decision,
            order_id or "",
            ctx.broker,
            notional_usd=order_notional,
            known_fill=reconciled.get("known_fill"),
        )
    return running_deployed_7d


def _book_reconciled_whole_share_order_durably(
    state: "StrategyState",
    ticker: str,
    claim_trading_day_iso: str,
    reconciled: Dict[str, Any],
    trading_day: date,
    deployment_history_root: Optional[str | Path],
) -> None:
    """Book only the DURABLE half of a reconciled whole-share order --
    ``state.record_buy``/``state.own_orders_recorded`` -- for the
    date/holiday-gated early-return path in :func:`_run_once_impl`, which
    has no full :class:`ProcessCandidateContext` to hand
    :func:`_book_reconciled_whole_share_order`.

    Mirrors :func:`_book_recovered_lease_durably`'s identical scope
    narrowing for the inverse-Martingale recovery on that SAME gated path:
    a whole-share claim's exact-ref-id ledger reconciliation
    (:func:`_reconcile_unresolved_whole_share_claim`) needs neither a
    current price nor the rest of a run, so it must not wait behind the
    date/holiday gate either -- without this, an ambiguous placement
    claimed on the FINAL approved trading date (or the day before a
    holiday) left an unresolved claim no later invocation could ever
    reach, since every subsequent scheduled run returns before the
    ordinary reconciliation pass further down in ``_run_once_impl`` even
    runs, permanently stranding that ticker's balance until an operator
    manually reopens the trading window (Codex review: "Reconcile
    whole-share claims before date-gated returns").

    Deliberately skips what :func:`_book_reconciled_whole_share_order`
    otherwise does: ``running_deployed_7d`` (ephemeral, this-run-only, and
    meaningless for a gated run that evaluates no candidates) and
    publishing a ``candidate_outcomes``/execution-record row (no run
    artifact is written on the gated path at all). A zero-fill attempt is
    still counted (zero notional) for the same ``max_orders_per_day``
    attempt-accounting reason :func:`_book_reconciled_whole_share_order`
    itself counts one.
    """
    try:
        claim_trading_day_date = date.fromisoformat(claim_trading_day_iso)
    except ValueError:
        claim_trading_day_date = trading_day
    # A "live_order_found" claim (see _reconcile_unresolved_whole_share_
    # claim) stays deliberately unresolved while its order remains live, so
    # it is reconciled and rebooked again on EVERY later run -- unlike the
    # other two shapes, whose underlying claim actually resolves in the
    # ledger and therefore stops being found at all. Its recovery is
    # published (by a later, non-gated run) under THAT run's own
    # trading_day, never the claim's original day, so the exact-trading_day
    # match below can never find it (Codex review: "Avoid rebooking a
    # recovered live order on every later run"). Deduplicate by order id
    # instead, anchored at today (trading_day) so the trailing-window scan
    # actually covers a recovery artifact from an earlier day this week.
    if reconciled.get("live_order_found"):
        already_recorded = (
            deployment_history_root is not None
            and _same_day_order_id_already_recorded(
                reconciled.get("order_id"), ticker, trading_day, deployment_history_root
            )
        )
    else:
        # ALSO checked by order id (mirrors _book_reconciled_whole_share_
        # order's own identical fix): this exact order may already have
        # been provisionally booked as "live_order_found" on an earlier
        # run while still live, under THAT run's own trading_day rather
        # than claim_trading_day_date, which the ticker/day check alone
        # can never find (Codex review: "Deduplicate terminal recoveries
        # by broker order ID").
        already_recorded = deployment_history_root is not None and (
            _same_day_ticker_deployment_already_recorded(
                ticker, claim_trading_day_date, deployment_history_root
            )
            or _same_day_order_id_already_recorded(
                reconciled.get("order_id"), ticker, trading_day, deployment_history_root
            )
        )
    if already_recorded:
        return
    # Mirrors _book_reconciled_whole_share_order's own three-way branch --
    # a live/working match (Codex review: "Book live orders discovered
    # during claim recovery") books the CLAIM's own planned notional here
    # too, exactly like a zero-fill attempt books zero: this durable-only
    # helper has no running_deployed_7d/execution-record row to publish
    # regardless of which of the three shapes ``reconciled`` is.
    if reconciled.get("zero_fill_attempt"):
        order_notional = 0.0
    elif reconciled.get("live_order_found"):
        order_notional = float(reconciled.get("planned_notional_usd") or 0.0)
    else:
        order_notional = reconciled["order_notional_usd"]
    state.record_buy(ticker, claim_trading_day_date, order_notional, order_id=reconciled.get("order_id"))
    state.own_orders_recorded.add((ticker, claim_trading_day_date))


def _reconcile_cross_day_whole_share_claims(
    ticker: str,
    decision: ReconciledDecision,
    ctx: "ProcessCandidateContext",
    idempotency_key: str,
    running_deployed_7d: float,
    error_sink: Optional[List[str]] = None,
) -> float:
    """Reconcile every unresolved claim for ``ticker`` -- including TODAY's
    own trading day -- booking each settled result into
    ``running_deployed_7d``/``ctx.state``/execution artifacts.

    Extracted from :func:`_process_whole_share_candidate` (Codex review:
    "Reconcile recovered spend before starting the candidate batch") so it
    can ALSO be run as a pre-pass over the whole batch, before any
    candidate's own placement, by
    :func:`_reconcile_cross_day_whole_share_claims_for_batch`. Previously
    this only ran when THIS ticker itself reached
    :func:`_process_whole_share_candidate` in the sorted candidate batch --
    if a recovered order within the trailing kill-switch window pushed
    ``running_deployed_7d`` across the threshold, any OTHER candidate
    sorted earlier in the batch had already placed using the lower,
    not-yet-recovered figure, and only candidates sorted AFTER this ticker
    ever saw the recovered spend.

    An earlier attempt's placement can have raised AND its ref-id
    reconciliation lookup can have ALSO raised, deliberately leaving that
    claim unresolved. If that ambiguity survives past midnight, TODAY's own
    ``trading_day_iso`` can never retrieve that prior day's entry, and the
    broad same-day duplicate check only looks at orders from TODAY onward
    -- it would never even notice a stale claim whose real order landed on
    an EARLIER day. Actively search for one here, unconditionally, against
    that OLD trading day's own ref_id (Codex review: "Reconcile unresolved
    claims across trading days"). Best-effort: a failure here must not
    abort the caller. Skipped entirely during a dry run -- ``ledger.settle()``
    durably mutates the REAL ledger, and a demo/shadow invocation must
    never resolve a real claim, change its pending balance, bump
    ``shares_purchased_total``, or append an event that a later LIVE run
    would then see (Codex review: "Keep cross-day reconciliation read-only
    during dry runs").

    ``error_sink``, when supplied, collects one short reason string per
    best-effort failure swallowed below. Those failures leave a real claim
    unreconciled, but logging alone kept them invisible to the run's own
    health metrics: unlike the signal loop and the candidate batch, nothing
    here fed ``errors_count``, so a run whose whole-share pre-roll pass could
    not read its ledger still reported ``usage_proxy.manual_recovery_required
    = False`` (Antigravity review, PR #786: "Error tracking in
    _reconcile_cross_day_whole_share_claims_for_batch"). A list rather than a
    return value so the existing signature -- and every caller that only
    wants the deployment figure -- is unchanged.
    """
    if ctx.config.dry_run:
        return running_deployed_7d
    ledger = WholeShareAccumulationLedger()
    try:
        cross_day_claims = ledger.unresolved_claims_any_day(ticker, idempotency_key)
    except Exception as cross_day_exc:  # noqa: BLE001 - best-effort; a
        # corrupt/unreadable ledger here must not abort the caller.
        cross_day_claims = []
        logger.warning(
            "Whole-share cross-day unresolved-claim lookup failed for %s: %s",
            ticker,
            cross_day_exc,
        )
        # Type only, never the message: this string is destined for the run's
        # own error accounting, and a ledger/broker exception can carry an
        # account identifier -- the same rule the candidate batch's isolation
        # net applies to skip_reason.
        if error_sink is not None:
            error_sink.append(
                f"{ticker}: unresolved-claim lookup raised {type(cross_day_exc).__name__}"
            )
    trading_day_iso = ctx.trading_day.isoformat()
    for claim_trading_day_iso, claim in cross_day_claims:
        if claim_trading_day_iso == trading_day_iso:
            # TODAY's own claim is now ALSO reconciled here (not
            # unconditionally skipped) when this runs as part of the
            # batch-wide pre-pass -- a same-day retry after an AMBIGUOUS
            # PLACEMENT can leave an unresolved claim for today whose real
            # order already landed at the broker, and skipping it here left
            # that recovered fill invisible to running_deployed_7d until
            # this ticker's own candidate later reached the duplicate-check
            # reconciliation, by which point earlier-sorted candidates in
            # the batch had already placed against the stale figure (Codex
            # review: "Include same-day claims in the batch pre-pass").
            #
            # Gated on the SAME broad same_day_strategy_order_exists check
            # the initial duplicate-check branch already uses, though --
            # NOT reconciled unconditionally. A same-day claim that is
            # merely STALE with no placement ever attempted is a genuinely
            # different case this function's own general staleness-release
            # fallback (further below, for cross-day claims) would
            # mishandle: record_contribution()'s OWN reclaim-and-reprice
            # logic is what's designed to own that scenario (see its
            # module docstring), and calling preserve_pending on it here
            # instead would flatten a reclaimable, repriceable fire into a
            # plain released balance, discarding the reclaim/reprice
            # behavior a genuine same-day retry actually needs. Checking
            # the broad existence signal first mirrors exactly the
            # condition under which the initial duplicate check itself
            # would have reconciled this same claim, just earlier.
            try:
                today_order_exists = ctx.broker.same_day_strategy_order_exists(ticker, ctx.trading_day)
            except Exception as today_check_exc:  # noqa: BLE001 - best-effort;
                # a failed lookup must not abort the caller OR any other
                # claim's own reconciliation attempt.
                logger.warning(
                    "Whole-share same-day order-existence check failed for %s during batch pre-pass: %s",
                    ticker,
                    today_check_exc,
                )
                # Best-effort for CONTROL FLOW, not for run health: `continue`
                # leaves this claim unreconciled, and without telling the sink
                # the run still reports itself clean -- no errors_count, no
                # manual_recovery_required -- for a claim it could not resolve
                # (Codex review, PR #786: "Count broker lookup failures in
                # pre-roll health"). Exception TYPE only: this string reaches
                # persisted artifacts, and a broker error can carry an account
                # identifier.
                if error_sink is not None:
                    error_sink.append(
                        f"{ticker}: same-day order-existence check raised "
                        f"{type(today_check_exc).__name__}"
                    )
                continue
            if not today_order_exists:
                # The broad check above is LIVE-only (see
                # _LIVE_ORDER_STATES's own comment: a cancelled/rejected
                # order "never consumed capacity") -- it misses a genuinely
                # TERMINAL order an earlier placement attempt today left
                # behind (e.g. it partially filled and was THEN cancelled
                # before a retry ran). Without also checking the exact
                # ref-id terminal-inclusive lookup here, this claim falls
                # straight through to `continue` and is left unreconciled;
                # once it goes stale, record_contribution() reclaims it and
                # submits the FULL planned quantity again, never booking
                # the earlier partial fill -- excess shares purchased and
                # reused credit (Codex review: "Reconcile terminal same-day
                # fills before reclaiming the claim").
                today_ref_id = f"{_graded_dca_ref_id_prefix(ctx.stream, 'wholeshare')}-{claim_trading_day_iso}-{ticker}"
                try:
                    today_terminal_match = ctx.broker.same_day_order_with_ref_id_prefix_any_state(
                        ticker, ctx.trading_day, (today_ref_id,)
                    )
                except Exception as today_terminal_exc:  # noqa: BLE001 - best-effort.
                    logger.warning(
                        "Whole-share same-day terminal-history check failed for %s during batch "
                        "pre-pass: %s",
                        ticker,
                        today_terminal_exc,
                    )
                    # Same reasoning as the existence check above, and the
                    # stakes are higher here: this is the lookup that catches
                    # a partially-filled-then-cancelled order, so a swallowed
                    # failure can end with record_contribution() reclaiming
                    # the claim and re-submitting the full quantity.
                    if error_sink is not None:
                        error_sink.append(
                            f"{ticker}: same-day terminal-history check raised "
                            f"{type(today_terminal_exc).__name__}"
                        )
                    continue
                if not today_terminal_match:
                    # Genuinely nothing attempted today -- leave this claim
                    # for record_contribution()'s own reclaim-and-reprice
                    # logic, unchanged from before.
                    continue
        # Isolated PER claim, not around the whole loop -- if the oldest
        # claim's history lookup consistently raises (e.g. that date is no
        # longer available from the broker), a single try/except around the
        # entire loop exits before any LATER claim is ever examined, on
        # every future run too, so a later genuinely-accepted order remains
        # permanently unreconciled despite now being present in the
        # returned list (Codex review: "Isolate failures for each
        # unresolved claim").
        try:
            reconciled = _reconcile_unresolved_whole_share_claim(
                ledger, ctx.broker, ticker, ctx.stream, idempotency_key, claim_trading_day_iso, claim,
                now_iso=ctx.now.isoformat(),
            )
        except Exception as cross_day_exc:  # noqa: BLE001 - best-effort; must not
            # abort the caller, or any OTHER claim's own reconciliation
            # attempt, over one claim's failure.
            logger.warning(
                "Whole-share cross-day unresolved-claim reconciliation failed for %s (trading_day=%s): %s",
                ticker,
                claim_trading_day_iso,
                cross_day_exc,
            )
            if error_sink is not None:
                error_sink.append(
                    f"{ticker}: claim {claim_trading_day_iso} reconciliation raised "
                    f"{type(cross_day_exc).__name__}"
                )
            continue
        if reconciled is not None:
            running_deployed_7d = _book_reconciled_whole_share_order(
                ctx, decision, ticker, claim_trading_day_iso, reconciled, running_deployed_7d
            )
    return running_deployed_7d


def _reconcile_cross_day_whole_share_claims_for_batch(
    ctx: "ProcessCandidateContext",
    running_deployed_7d: float,
    decisions_by_ticker: Optional[Dict[str, "ReconciledDecision"]] = None,
    error_sink: Optional[List[str]] = None,
) -> float:
    """Run :func:`_reconcile_cross_day_whole_share_claims` for EVERY
    configured whole-share ticker (``ctx.config.whole_share_tickers`` minus
    ``ctx.config.excluded_tickers``) BEFORE any candidate in the batch is
    allowed to place (Codex review: "Reconcile recovered spend before
    starting the candidate batch").

    Cross-day recovery used to run only once THIS ticker itself reached
    :func:`_process_whole_share_candidate` in the sorted batch loop -- a
    recovered order that pushes deployment across the trailing 7-day
    kill-switch threshold was then only visible to candidates sorted AFTER
    the whole-share ticker, letting earlier candidates place uncapped
    orders against a stale, too-low ``running_deployed_7d``. Running this
    reconciliation as a pre-pass, before any candidate in the batch places,
    ensures EVERY candidate -- regardless of sort position -- sees the
    same, fully-recovered deployment figure.

    Iterates ``ctx.config.whole_share_tickers`` directly rather than
    ``buy_candidates`` -- a whole-share ticker with a genuine unresolved
    claim can be ABSENT from ``buy_candidates`` entirely (e.g. today's own
    signal is NO_ACTION and
    ``_whole_share_redispatch_reconciled_price()`` returns ``None`` because
    the two data sources disagree), even though reconciling the STORED
    claim against broker history needs no current quote at all. Scanning
    only ``buy_candidates`` left such a ticker's recovered spend invisible
    to ``running_deployed_7d`` for the whole batch (Codex review: "Scan
    unresolved tickers independently of buy candidates").

    ``decisions_by_ticker``, when given, supplies a REAL decision object
    (used only for execution-log fidelity -- target price/quote time/
    reason) for tickers that do have one; a ticker without one (not yet
    evaluated, e.g. this runs before signal evaluation) gets a minimal
    synthetic ``NO_ACTION`` decision instead, which is all
    :func:`_book_reconciled_whole_share_order`'s own ``_log_execution``
    call actually needs.
    """
    decisions_by_ticker = decisions_by_ticker or {}
    # Discovers any ticker with an existing ledger directory that is NOT
    # currently in ctx.config.whole_share_tickers at all -- e.g. an
    # operator removed it from that category (delisted, or moved to
    # excluded_tickers) while a real unresolved claim was still pending.
    # Without this, such a ticker's claim can NEVER be reconciled again
    # by any later run (this pre-pass otherwise only iterates the
    # CURRENT config's own set), permanently stranding its accumulated
    # balance (Codex review: "Reconcile claims for tickers removed from
    # configuration"). A no-op for any orphaned symbol with nothing left
    # to reconcile -- _reconcile_cross_day_whole_share_claims itself
    # already handles "no unresolved claims" cleanly.
    orphaned = set(WholeShareAccumulationLedger().discover_symbols()) - ctx.config.whole_share_tickers
    for ticker in sorted((ctx.config.whole_share_tickers - ctx.config.excluded_tickers) | orphaned):
        decision = decisions_by_ticker.get(ticker)
        if decision is None:
            decision = ReconciledDecision(
                ticker=ticker,
                action=Action.NO_ACTION,
                reason="whole-share cross-day reconciliation pre-pass",
                finance_signal=None,
                robinhood_signal=None,
            )
        idempotency_key = f"{ctx.stream}-{ticker}"
        # DELIBERATELY NOT wrapped in a per-ticker try/except, unlike the
        # candidate batch and the signal loop. A net was added here during
        # the 2026-08-24 isolation work and then removed on review, because
        # it made this path LESS safe, not more:
        #
        # 1. Isolation is already handled one level down, and more precisely.
        #    _reconcile_cross_day_whole_share_claims wraps its own claims
        #    lookup, its same-day existence check, its terminal-history
        #    check, and every individual claim's reconciliation -- each
        #    logging and continuing. A whole-symbol net here adds nothing for
        #    the failure modes that actually isolate cleanly.
        # 2. The ONE thing it did newly swallow is the thing that must stay
        #    fatal: a raise from _book_reconciled_whole_share_order, which
        #    runs AFTER _reconcile_unresolved_whole_share_claim has already
        #    DURABLY settled the claim. That order is real, recovered spend
        #    that the ledger will never surface again -- it is not "left
        #    unresolved for the next run". Continuing past it would let every
        #    later candidate in this batch place against an understated
        #    running_deployed_7d and miss a kill-switch transition the
        #    recovered order should have caused (Codex review, PR #786:
        #    "Stop placements when recovered spend cannot be booked").
        #
        # Failing the run is the fail-closed answer for a deployment-accounting
        # failure: no order is placed against a total that is known to be wrong.
        running_deployed_7d = _reconcile_cross_day_whole_share_claims(
            ticker, decision, ctx, idempotency_key, running_deployed_7d, error_sink=error_sink
        )
    return running_deployed_7d


def _process_whole_share_candidate(
    decision: ReconciledDecision,
    ctx: ProcessCandidateContext,
    running_deployed_7d: float,
) -> tuple[Dict[str, Any], Optional["TopUpGuardOutcome"], float, int, int]:
    """Route a whole-share ticker's decision through the accumulator instead
    of a normal dollar-amount order.

    ``decision.ticker`` is in ``ctx.config.whole_share_tickers`` (see
    ``near_close_dca.WHOLE_SHARE_TICKERS`` and
    ``docs/whole_share_accumulation.md``) -- a ticker not tradable for
    fractional/notional buys on Robinhood. This bypasses the same-day top-up
    guard, the cumulative sub-dollar credit ledger, and the
    ``is_tradable_for_fractional_buy`` gate entirely: none of those apply to
    a ticker whose accumulated total, once it crosses one share's price,
    places a QUANTITY-based order via
    ``RobinhoodBroker.review_whole_share_buy``/``place_whole_share_buy``
    instead of the dollar-amount ``review_market_buy``/``place_market_buy``.
    It DOES apply the same hard per-order ceiling, daily/weekly budget caps,
    and bid/ask spread gate every normal candidate goes through (Codex
    review: "Apply the normal risk gates before whole-share dispatch") --
    only the top-up/credit-ledger/fractional-tradability machinery is
    genuinely inapplicable here.

    Returns the same 5-tuple shape as :func:`_process_buy_candidate` so
    :func:`_process_buy_candidates_batch` can treat both uniformly; the
    second element (``TopUpGuardOutcome``) is always ``None`` here -- a
    whole-share fire has no top-up-guard concept.
    """
    ticker = decision.ticker
    errors_count_inc = 0
    order_reviews_attempted_inc = 0
    trading_day_iso = ctx.trading_day.isoformat()
    ledger = WholeShareAccumulationLedger()
    # Keyed by (stream, ticker) rather than including the trading day inside
    # the string -- record_contribution/settle/preserve_pending all take
    # trading_day as a SEPARATE argument and namespace the idempotency key
    # under it internally, exactly like _graded_dca_ref_id_prefix's own
    # stream-token convention below. Computed here (rather than just before
    # its first use further down) so the initial duplicate-order check can
    # also reconcile an unresolved claim before returning (see that check's
    # own comment below).
    idempotency_key = f"{ctx.stream}-{ticker}"

    # Snapshotted BEFORE the reconciliation call just below, purely to tell
    # apart "this ticker's entry changed BECAUSE of THIS call's own
    # reconciliation pass" from "this ticker already had a submitted entry
    # for some OTHER reason before this call even started" (a legitimate
    # pre-existing seed the OUTER batch loop's own seeded_outcome mechanism
    # already handles, or -- in a direct-call test/isolated context -- an
    # unrelated leftover from something else entirely). Comparing by
    # identity against this snapshot after the call is what makes the
    # capture below trustworthy.
    _outcomes_ref_before_reconciliation = _IN_FLIGHT_CANDIDATE_OUTCOMES.get("outcomes")
    _pre_reconciliation_outcome = (
        _outcomes_ref_before_reconciliation.get(ticker)
        if _outcomes_ref_before_reconciliation is not None
        else None
    )

    # Cross-day recovery is now ALSO run as a pre-pass over the whole batch
    # before any candidate places (see
    # _reconcile_cross_day_whole_share_claims_for_batch), so
    # running_deployed_7d already reflects any recovered spend by the time
    # candidates are processed in sorted order. This per-candidate call is
    # kept as a safety net (e.g. a whole-share ticker somehow not covered
    # by the pre-pass) -- settle()'s own idempotency means a claim the
    # pre-pass already resolved is simply not returned by
    # unresolved_claims_any_day here, so this degrades to a no-op scan in
    # the common case rather than double-booking anything.
    running_deployed_7d = _reconcile_cross_day_whole_share_claims(
        ticker, decision, ctx, idempotency_key, running_deployed_7d
    )

    def _block(reason: str, message: str) -> None:
        if ctx.run_result is not None:
            ctx.run_result.loop_block_reasons[ticker] = reason
        logger.info(message)

    # A recovered fill from an OLDER claim, published into
    # _IN_FLIGHT_CANDIDATE_OUTCOMES by the reconciliation call just above,
    # is a genuinely DIFFERENT order than whatever the REST of this call
    # (processing TODAY's own signal) ends up deciding. Every self-
    # publishing return path further down in this function uses a plain,
    # OVERWRITING publish -- without capturing the recovery here, first,
    # the moment any of those paths runs it would silently clobber this
    # recovery with today's own outcome (even a "still accumulating"/
    # blocked non-placement), and _process_buy_candidates_batch's own
    # OUTER seeded_outcome snapshot (captured before THIS call even
    # started) can never see it either, since it was written mid-call, not
    # before it (Codex review: "Merge recoveries published during
    # candidate processing").
    _recovered_before_todays_processing = None
    _outcomes_ref = _IN_FLIGHT_CANDIDATE_OUTCOMES.get("outcomes")
    if _outcomes_ref is not None:
        _candidate_from_reconciliation = _outcomes_ref.get(ticker)
        if (
            _candidate_from_reconciliation is not None
            # Identity, not equality, against the snapshot taken BEFORE the
            # reconciliation call above -- an entry that was ALREADY there
            # (whatever its origin) is not something THIS call's own
            # reconciliation pass produced, and merging it in here would be
            # redundant at best (the outer batch loop's own seeded_outcome
            # mechanism already handles a genuinely pre-existing seed) and
            # WRONG at worst (e.g. leftover module-global state from an
            # unrelated earlier call in the same process).
            and _candidate_from_reconciliation is not _pre_reconciliation_outcome
            and _candidate_from_reconciliation.get("status") == "submitted"
        ):
            _recovered_before_todays_processing = _candidate_from_reconciliation

    def _publish_whole_share_outcome(candidate_outcome: Dict[str, Any]) -> Dict[str, Any]:
        """Publish this call's own final outcome, merging in a same-call
        recovery captured above instead of silently overwriting it.

        Every return path below that has already built its own final
        ``candidate_outcome`` calls this INSTEAD OF
        ``_publish_in_flight_outcome`` directly. Returns the (possibly
        merged) outcome; callers must reassign their own ``candidate_outcome``
        to this return value before returning it, so the function's actual
        return value (not just the published dict) reflects the merge --
        otherwise the outer batch loop's own unconditional
        ``candidate_outcomes[ticker] = c_outcome`` would overwrite the
        correctly-merged dict entry with a stale, unmerged return value.
        """
        nonlocal _recovered_before_todays_processing
        if _recovered_before_todays_processing is not None:
            if candidate_outcome.get("status") == "submitted":
                # Shared with the outer batch loop's own identical
                # aggregation need (Codex review: "Aggregate all recovered
                # claims for the same ticker").
                candidate_outcome = _merge_whole_share_submission_outcomes(
                    _recovered_before_todays_processing, candidate_outcome
                )
            else:
                # Today's own outcome is not a real placement -- the
                # recovered fill remains the only real order for this
                # ticker today.
                candidate_outcome = _recovered_before_todays_processing
            # Consumed -- a LATER self-publish in this same call (this
            # ticker reaching more than one publish point) must not merge
            # the SAME recovery in twice.
            _recovered_before_todays_processing = None
        _publish_in_flight_outcome(ticker, candidate_outcome)
        return candidate_outcome

    # Same broad broker-level same-day check the normal path applies
    # unconditionally when not ticker_guarded (whole-share candidates have
    # no guarded/top-up concept at all, so this is the ONLY same-day
    # duplicate protection here, run BEFORE the ledger is ever touched so a
    # same-day retry never even records a duplicate contribution).
    try:
        duplicate_order_exists_initial = ctx.broker.same_day_strategy_order_exists(ticker, ctx.trading_day)
    except Exception as exc:  # noqa: BLE001 - this initial lookup can itself raise
        # (network/API outage), exactly like the second, pre-placement recheck
        # further below (already wrapped) -- without an equivalent boundary
        # here, the exception would escape _process_buy_candidates_batch
        # entirely, aborting the WHOLE run and preventing outcomes/artifacts
        # for every other, independent candidate still to be processed. No
        # ledger restoration is needed (this check runs before
        # record_contribution ever touches the ledger) (Codex review:
        # "Isolate the initial duplicate-order lookup failure").
        errors_count_inc += 1
        candidate_outcome = {
            "status": "blocked",
            "skip_reason": f"whole-share: same-day duplicate order lookup failed: {exc}",
            "deliberate_skip": True,
            # Marks this outcome as whole-share-originated for
            # _build_buy_candidates's key-based detection (see that
            # function's own comment) -- this check runs before the ledger
            # and every other whole-share-marking helper, so without SOME
            # "whole_share_" field, a NO_ACTION-redispatched ticker's
            # early lookup-failure outcome would be silently dropped from
            # buy_candidates.csv/run_state.json by the BUY-only filter,
            # even though errors_count_inc correctly counted the failure
            # (Codex review: "Retain early redispatch lookup failures in
            # candidate artifacts").
            "whole_share_planned_notional_usd": 0.0,
        }
        _block(
            MISSING_FILL_DATA_ERROR,
            f"{ticker}: whole-share same-day duplicate order lookup failed: {exc}; skipping",
        )
        return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc
    if duplicate_order_exists_initial:
        # An EARLIER attempt today may have left this exact idempotency slot
        # deliberately unresolved -- a placement that raised whose ref-id
        # reconciliation lookup ALSO raised (Codex review: "Keep ambiguous
        # claims reserved when reconciliation fails") intentionally leaves
        # the claim untouched rather than guessing whether the order landed.
        # This broad, ref-id-agnostic check just confirmed SOME same-day
        # order now exists for this ticker -- strong evidence the earlier
        # placement DID succeed. Without reconciling here, this early return
        # would fire on every future retry too (the same broad check would
        # always find the same live order), permanently stranding that
        # claim's reservation -- including any per-order-ceiling-clamped
        # shortfall still deducted from pending_usd that settle() would
        # otherwise restore (Codex review: "Reconcile reserved claims before
        # the duplicate early return"). Best-effort: a failure here must not
        # block this (already deliberate) skip outcome.
        # Skipped entirely during a dry run -- see the cross-day check's own
        # identical guard above (Codex review: "Keep cross-day
        # reconciliation read-only during dry runs"): settling here would
        # durably mutate the REAL ledger and now also books into REAL
        # ctx.state/execution artifacts, both violating the dry-run path's
        # non-mutation guarantee.
        if not ctx.config.dry_run:
            try:
                unresolved = ledger.unresolved_claim(ticker, trading_day_iso, idempotency_key)
                if unresolved is not None:
                    # This broad, ref-id-agnostic check being True only proves
                    # SOME same-day order exists for this ticker -- it could be
                    # a completely UNRELATED live order (a manual trade, or a
                    # different stream's own fire) that has nothing to do with
                    # THIS claim. _reconcile_unresolved_whole_share_claim only
                    # settles on an EXACT ref_id match (Codex review: "Require
                    # an exact order match before settling") and, using the
                    # claim's OWN claimed_at rather than a fresh timestamp,
                    # actually satisfies settle()'s ownership guard (Codex
                    # review: "Reconcile using the original claim timestamp")
                    # -- see that helper's own docstring for both.
                    reconciled = _reconcile_unresolved_whole_share_claim(
                        ledger, ctx.broker, ticker, ctx.stream, idempotency_key, trading_day_iso, unresolved,
                        now_iso=ctx.now.isoformat(),
                    )
                    if reconciled is not None:
                        # Without this, a reconciled order that genuinely
                        # landed at the broker was recorded in the
                        # whole-share ledger but NOWHERE else -- daily/
                        # weekly budget caps, the deployment kill switch,
                        # and persisted execution artifacts all silently
                        # omitted real spend the broker already executed
                        # (Codex review: "Book reconciled orders into the
                        # strategy budget state").
                        running_deployed_7d = _book_reconciled_whole_share_order(
                            ctx, decision, ticker, trading_day_iso, reconciled, running_deployed_7d
                        )
            except Exception as reconcile_exc:  # noqa: BLE001 - reconciliation is
                # best-effort here; a failure must not turn this deliberate skip
                # into an error outcome, and must not prevent the skip itself.
                logger.warning(
                    "Whole-share unresolved-claim reconciliation failed for %s during the "
                    "same-day duplicate check: %s",
                    ticker,
                    reconcile_exc,
                )
        candidate_outcome = {
            "status": "skipped",
            "skip_reason": "same-day broker order exists",
        }
        _block(
            MISSING_FILL_BUDGET_CAPPED,
            f"{ticker}: same-day broker order already exists; skipping",
        )
        return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc

    contribution_usd = decision.suggested_amount_usd if decision.action == Action.BUY else 0.0
    kill_switch_active = kill_switch_engaged(replace(ctx.config, deployed_last_7d_usd=running_deployed_7d))
    # kill_switch_ceiling_usd is passed into _whole_share_risk_gates below (both
    # the dry-run preview and the real placement path) as ceiling_override_usd
    # -- capping the EXECUTABLE order/preview, not just today's contribution.
    # Capping only contribution_usd (the next few lines) does nothing for a
    # preserved-fire redispatch (Codex review: "Re-dispatch preserved fires
    # without requiring a new BUY"), whose contribution is already $0 --
    # the fire is funded entirely by an EARLIER day's accumulated balance,
    # so an uncapped executable order could still spend well beyond the
    # kill-switch base while the switch is engaged (Codex review: "Apply the
    # kill switch to the executable whole-share fire").
    kill_switch_ceiling_usd = decision.selected_base_amount_usd if kill_switch_active else None
    if kill_switch_active:
        # Mirrors the normal buy path's own kill-switch cap (see that
        # branch's own comment below _process_buy_candidate's duplicate
        # check): when the rolling 7-day deployment threshold is engaged,
        # TODAY's contribution is capped to this candidate's own selected
        # base ($1 or $2, unmultiplied), not the full ladder-multiplied
        # suggested_amount_usd. This is the same real-money deployment-risk
        # reduction every normal candidate gets -- a whole-share ticker's
        # contribution must not bypass it just because it accumulates
        # toward a quantity-based order instead of firing immediately
        # (Codex review: "Apply the deployment kill switch to whole-share
        # orders").
        contribution_usd = min(contribution_usd, decision.selected_base_amount_usd)
    # target_price is the signal-time quote (see ReconciledDecision's own
    # docstring); decision_bar_close is the fallback for a decision that
    # never took the Action.BUY branch in reconcile_signals (so target_price
    # is still its bare 0.0 default) but still carries a usable close.
    current_share_price = decision.target_price or decision.decision_bar_close
    if decision.action == Action.BUY and decision.finance_signal is not None and decision.robinhood_signal is not None:
        # reconcile_signals's own "finance and Robinhood agree on BUY" branch
        # (see that function's own comment) selects ONE winning signal's
        # quote_price via _target_fields based purely on whichever produced
        # the smaller suggested_amount_usd -- it never checks that winning
        # quote against the OTHER source's own quote for agreement. For a
        # normal dollar-amount order this is harmless (the order still
        # spends the same number of dollars regardless of price), but a
        # whole-share order's share COUNT and per-order ceiling check are
        # both computed directly from this price -- e.g. finance quoting
        # $9.50 and Robinhood quoting $20 could let the $10 ceiling approve
        # one share as a $9.50 order right before Robinhood actually
        # executes it near $20 (Codex review: "Reconcile fresh whole-share
        # BUY prices before sizing"). Reuse the SAME cross-source agreement
        # check the preserved-fire redispatch path already applies (see
        # _whole_share_redispatch_reconciled_price and
        # _run_once_impl's redispatch loop) rather than trusting
        # decision.target_price directly.
        reconciled_price = _whole_share_redispatch_reconciled_price(decision)
        if reconciled_price is None:
            candidate_outcome = {
                "status": "blocked",
                "skip_reason": "whole-share: finance/Robinhood execution quotes disagree",
                "deliberate_skip": True,
            }
            _block(
                MISSING_FILL_BROKER_BLOCKED,
                f"{ticker}: whole-share finance/Robinhood execution quotes disagree; skipping",
            )
            return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc
        current_share_price = reconciled_price
    if current_share_price <= 0:
        candidate_outcome = {
            "status": "blocked",
            "skip_reason": "whole-share: no usable current price",
            "deliberate_skip": True,
        }
        _block(
            MISSING_FILL_DATA_ERROR,
            f"{ticker}: whole-share accumulation has no usable current price; skipping",
        )
        return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc

    # A dry run (config.dry_run -- --demo or a manual dry-run invocation)
    # must NEVER durably mutate the real accumulation ledger: unlike the
    # normal dollar-amount path (whose dry-run branch never calls
    # ctx.state.record_buy either), the ORIGINAL version of this function
    # called ledger.record_contribution() unconditionally, before this
    # check -- a below-threshold demo run durably grew BYDDY's real pending
    # balance with no way to undo it, and a firing demo run marked the
    # day's idempotency key "resolved", silently preventing a LATER real
    # scheduled run that day from ever recording its own contribution
    # (Codex review: "Avoid mutating the accumulator during dry runs").
    # Compute a PURE preview instead: read the current balance read-only and
    # run the exact same decision function the real path uses, without
    # writing anything.
    if ctx.config.dry_run:
        try:
            # If THIS exact slot already recorded a real contribution (a
            # same-day retry previewed via --demo after a genuine scheduled
            # run already ran), record_contribution() is idempotent per
            # (trading_day, idempotency_key) -- but what it would ACTUALLY
            # return for an already-recorded slot depends on that entry's
            # state, not just "already recorded": resolved or still within
            # its claim window both return zero shares regardless of the
            # current pending_usd balance (Codex review: "Honor slot
            # idempotency in dry-run previews"), but an UNRESOLVED, STALE
            # entry is actionable -- a real call right now would RECLAIM it
            # and return its cached POSITIVE decision, so the dry-run
            # preview must match that too, not flatten it to a skip (Codex
            # review: "Account for actionable stale claims in tier
            # planning", the same gap in this dry-run preview branch).
            # cached_fire_decision returns exactly what a real call would
            # produce for any already-recorded case; None means never
            # recorded, so the normal preview below applies.
            cached_decision = ledger.cached_fire_decision(
                ticker, trading_day_iso, idempotency_key, ctx.now.isoformat(), current_share_price, contribution_usd
            )
            if cached_decision is not None:
                preview = cached_decision
            else:
                pending_before = ledger.pending_usd(ticker)
                preview = apply_contribution(pending_before, contribution_usd, current_share_price)
        except Exception as exc:  # noqa: BLE001 - a corrupt/unreadable/locked
            # BYDDY ledger must not abort THIS whole candidate batch (dry-run
            # preview or otherwise) -- matches the real (non-dry-run) path's
            # own identical ledger-error handling a few branches below (Codex
            # review: "Isolate dry-run ledger read failures").
            errors_count_inc += 1
            candidate_outcome = {
                "status": "blocked",
                "skip_reason": f"whole-share ledger error: {exc}",
                # Marks this outcome as whole-share-originated for
                # _build_buy_candidates's key-based detection (see that
                # function's own comment) -- without SOME "whole_share_"
                # field, a non-BUY (NO_ACTION-redispatched or ordinary)
                # ticker's ledger-error block would be silently dropped from
                # buy_candidates.csv/run_state.json by the BUY-only filter,
                # even though errors_count_inc correctly counted the failure
                # (Codex review: "Surface ledger failures during
                # preserved-fire redispatch").
                "whole_share_planned_notional_usd": 0.0,
            }
            _block(MISSING_FILL_DATA_ERROR, f"{ticker}: whole-share ledger error: {exc}; skipping")
            return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc
        if preview.shares_to_buy <= 0:
            candidate_outcome = {
                "status": "skipped",
                "skip_reason": "whole-share: contribution accumulated, share threshold not yet reached",
                "deliberate_skip": True,
                "whole_share_pending_usd": preview.pending_after_usd,
                "whole_share_contribution_usd": preview.contribution_usd,
            }
            # A BUY trigger fired and accumulated -- deliberate, not a
            # failure -- but without an explicit loop_block_reasons entry,
            # classify_missing_fill falls through to
            # MISSING_FILL_FAILED_TRIGGER since decision.action == Action.BUY
            # (Codex review: "Classify below-threshold accumulation in
            # coverage reports").
            _block(
                MISSING_FILL_ACCUMULATING,
                f"{ticker}: whole-share contribution accumulated (dry-run), share threshold not yet reached",
            )
            return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc

        # Run the SAME risk gates the real placement path applies (Codex
        # review: "Apply safety gates to whole-share dry-run previews") --
        # read-only, no ledger writes -- so a dry-run artifact never claims
        # an order the identical live run would block or clamp.
        preview_quantity = preview.shares_to_buy
        preview_order_notional = preview.order_notional_usd
        # Clamp using the SAME cent-rounded price apply_contribution used
        # (preview.current_share_price_usd), not the raw current_share_price
        # -- keeps the dry-run preview on the same price basis as the real
        # path's identical fix just below (Codex review: "Restore clamped
        # credit using the ledger price").
        block_outcome, preview_quantity, preview_order_notional, spread_fields, is_error = (
            _whole_share_risk_gates(
                ticker,
                preview_quantity,
                preview_order_notional,
                preview.current_share_price_usd,
                ctx,
                ceiling_override_usd=kill_switch_ceiling_usd,
            )
        )
        if block_outcome is not None:
            if is_error:
                errors_count_inc += 1
                reason_code = MISSING_FILL_DATA_ERROR
            elif block_outcome.get("budget_blocked"):
                reason_code = MISSING_FILL_BUDGET_CAPPED
            else:
                reason_code = MISSING_FILL_BROKER_BLOCKED
            _block(reason_code, f"{ticker}: {block_outcome['skip_reason']}; skipping")
            # See _preserve_and_block's identical field below (Codex review:
            # "Persist the actual whole-share planned notional") -- the
            # accumulated notional this preview was about to attempt, not
            # $0 or today's raw contribution.
            block_outcome.setdefault("whole_share_planned_notional_usd", preview_order_notional)
            return block_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc

        # Buying power, same as the real placement path's own check below --
        # a demo/shadow run must not report success for an order the SAME
        # config in live mode would block for insufficient funds (Codex
        # review: "Check buying power in whole-share dry-run previews").
        try:
            preview_buying_power = ctx.broker.available_buying_power()
        except Exception as exc:  # noqa: BLE001 - the broker's buying-power lookup
            # can raise (network/API failure) during a dry run too, exactly like
            # the real placement path's identical call -- without this boundary
            # the exception would escape _process_buy_candidates_batch entirely,
            # aborting the whole demo run and preventing artifacts for every
            # OTHER, independent candidate still to be processed (Codex review:
            # "Catch buying-power failures in dry-run previews").
            errors_count_inc += 1
            candidate_outcome = {
                "status": "blocked",
                "skip_reason": f"whole-share: buying power lookup failed: {exc}",
                "deliberate_skip": True,
                "whole_share_planned_notional_usd": preview_order_notional,
                **spread_fields,
            }
            _block(MISSING_FILL_DATA_ERROR, f"{ticker}: whole-share buying power lookup failed: {exc}; skipping")
            return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc
        if preview_buying_power < preview_order_notional:
            candidate_outcome = {
                "status": "blocked",
                "skip_reason": "whole-share: insufficient buying power",
                "deliberate_skip": True,
                "budget_blocked": True,
                "whole_share_planned_notional_usd": preview_order_notional,
                **spread_fields,
            }
            _block(MISSING_FILL_BUDGET_CAPPED, f"{ticker}: whole-share insufficient buying power; skipping")
            return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc

        # Checked unconditionally, mirroring how is_tradable_for_fractional_buy
        # gates the normal buy path regardless of ctx.scheduled -- distinct
        # from review_whole_share_buy below, which (like review_market_buy)
        # only runs on a manual run. A ticker that has gone halted/inactive/
        # non-tradeable while quote data remains available must not preview
        # a plausible dry_run success the SAME config in live mode would
        # actually block (Codex review: "Verify whole-share tradability
        # before scheduled placement").
        try:
            preview_tradable = ctx.broker.is_tradable_for_whole_share_buy(ticker)
        except Exception as exc:  # noqa: BLE001 - the broker's tradability lookup
            # can raise (network/API failure) during a dry run too, exactly like
            # the real placement path's identical call -- without this boundary
            # the exception would escape _process_buy_candidates_batch entirely,
            # aborting the whole demo run and preventing artifacts for every
            # OTHER, independent candidate still to be processed (Codex review:
            # "Catch tradability failures in dry-run previews").
            errors_count_inc += 1
            candidate_outcome = {
                "status": "blocked",
                "skip_reason": f"whole-share: tradability lookup failed: {exc}",
                "deliberate_skip": True,
                "whole_share_planned_notional_usd": preview_order_notional,
                **spread_fields,
            }
            _block(MISSING_FILL_DATA_ERROR, f"{ticker}: whole-share tradability lookup failed: {exc}; skipping")
            return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc
        if not preview_tradable:
            candidate_outcome = {
                "status": "blocked",
                "skip_reason": "whole-share: not tradable",
                "deliberate_skip": True,
                "whole_share_planned_notional_usd": preview_order_notional,
                **spread_fields,
            }
            _block(MISSING_FILL_BROKER_BLOCKED, f"{ticker}: whole-share not tradable; skipping")
            return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc

        # A dry-run preview must not claim success for a broker that cannot
        # actually place a whole-share order -- whole-share is Robinhood-only
        # by design (AlpacaBroker.place_whole_share_buy raises), so fabricating
        # a synthetic order_id for it here would report a plausible dry_run
        # outcome that the SAME config in live mode would immediately fail
        # (Codex review: "Reject unsupported brokers in whole-share previews").
        # review_whole_share_buy is read-only/side-effect-free (per its own
        # docstring), so calling it here regardless of ctx.scheduled is safe.
        # Counted the same as the normal candidate path counts a
        # review_market_buy call -- this is a real broker review/capability
        # request even though nothing gets placed, so cost-control telemetry
        # must see it (Codex review: "Count whole-share dry-run reviews in
        # usage metrics").
        order_reviews_attempted_inc += 1
        try:
            review_ok, review_reason = ctx.broker.review_whole_share_buy(ticker, preview_quantity)
        except Exception as exc:  # noqa: BLE001 - the broker's review call itself
            # can raise (network/API failure) during a dry run too, exactly like
            # the real (non-scheduled) manual-review branch's identical try/
            # except further below -- without this, the exception would escape
            # _process_buy_candidates_batch entirely, aborting the whole demo
            # and preventing artifacts for every OTHER, independent candidate
            # still to be processed. No ledger restoration is needed here (this
            # branch is read-only -- no record_contribution call has run) (Codex
            # review: "Catch whole-share dry-run review failures").
            errors_count_inc += 1
            candidate_outcome = {
                "status": "blocked",
                "skip_reason": f"whole-share: dry-run review failed: {exc}",
                "deliberate_skip": True,
                "whole_share_planned_notional_usd": preview_order_notional,
                **spread_fields,
            }
            _block(MISSING_FILL_DATA_ERROR, f"{ticker}: whole-share dry-run review failed: {exc}; skipping")
            return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc
        if not review_ok:
            candidate_outcome = {
                "status": "blocked",
                "skip_reason": f"whole-share review blocked order: {review_reason}",
                "deliberate_skip": True,
                "whole_share_planned_notional_usd": preview_order_notional,
                **spread_fields,
            }
            _block(MISSING_FILL_BROKER_BLOCKED, f"{ticker}: whole-share review blocked order: {review_reason}")
            return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc

        logger.info(
            "[DRY RUN] Would buy %s whole share(s): %d @ ~$%.2f each ($%.2f total) (%s)",
            ticker,
            preview_quantity,
            current_share_price,
            preview_order_notional,
            decision.reason,
        )
        ref_id = f"{_graded_dca_ref_id_prefix(ctx.stream, 'wholeshare')}-{trading_day_iso}-{ticker}"
        order_id = (
            ctx.broker.place_whole_share_buy(ticker, preview_quantity, ref_id)
            if isinstance(ctx.broker, DryRunBroker)
            else f"DRY-RUN-SIM-WHOLESHARE-{ticker}-{preview_quantity}-{ref_id}"
        )
        candidate_outcome = {
            "status": "dry_run",
            "order_id": order_id,
            "skip_reason": "dry_run: whole-share order not placed",
            "submitted_amount_usd": preview_order_notional,
            "whole_share_quantity": preview_quantity,
            # Reported by the below-threshold preview branch above
            # (`preview.pending_after_usd`/`preview.contribution_usd`) and
            # by the live success path -- omitting them here left
            # `_build_buy_candidates` writing both as null for a
            # successful, threshold-crossing dry run even though the SAME
            # `preview` decision already carries the simulated carry-
            # forward balance and contribution, making demo artifacts
            # unable to show them (Codex review: "Persist accumulator
            # details for successful dry-run fires"). When the per-order
            # ceiling above clamped preview_order_notional below
            # preview.order_notional_usd, the unsubmitted shares' notional
            # must be added back onto the reported pending balance -- the
            # equivalent live path restores that exact shortfall during
            # settle() (see "Persist the post-fire accumulator balance"
            # below), and a dry run must report the SAME simulated
            # carry-forward the identical live run would actually produce,
            # not the pre-clamp preview's unclamped remainder (Codex
            # review: "Restore clamped credit in dry-run pending
            # previews").
            "whole_share_pending_usd": preview.pending_after_usd
            + round(max(0.0, preview.order_notional_usd - preview_order_notional), 2),
            "whole_share_contribution_usd": preview.contribution_usd,
            **spread_fields,
        }
        # Mirrors the normal buy path's own dry-run branch, which always
        # falls through to a common _log_execution call regardless of
        # dry_run/live status -- without this, RunResult.execution_records
        # would omit every whole-share dry-run preview even though
        # DryRunBroker.place_whole_share_buy already created a simulated
        # order (and potentially a fill), leaving orders.csv and dry-run
        # fill/slippage reporting silently disagree with the "dry_run"
        # candidate artifact (Codex review: "Log successful whole-share
        # dry-run executions").
        if ctx.run_result is not None:
            _log_execution(ctx.run_result, decision, order_id, ctx.broker, notional_usd=preview_order_notional)
        return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc

    try:
        wsa_decision = ledger.record_contribution(
            ticker,
            trading_day_iso,
            contribution_usd,
            current_share_price,
            stream=ctx.stream,
            recorded_at=ctx.now.isoformat(),
            idempotency_key=idempotency_key,
        )
    except Exception as exc:  # noqa: BLE001
        errors_count_inc += 1
        candidate_outcome = {
            "status": "blocked",
            "skip_reason": f"whole-share ledger error: {exc}",
            # See the dry-run branch's identical marker above (Codex review:
            # "Surface ledger failures during preserved-fire redispatch") --
            # without SOME "whole_share_" field, a non-BUY (NO_ACTION-
            # redispatched or ordinary) ticker's ledger-error block would be
            # silently dropped from buy_candidates.csv/run_state.json by the
            # BUY-only filter, even though errors_count_inc correctly
            # counted the failure.
            "whole_share_planned_notional_usd": 0.0,
        }
        _block(MISSING_FILL_DATA_ERROR, f"{ticker}: whole-share ledger error: {exc}; skipping")
        return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc

    if wsa_decision.shares_to_buy <= 0:
        candidate_outcome = {
            "status": "skipped",
            "skip_reason": "whole-share: contribution accumulated, share threshold not yet reached",
            "deliberate_skip": True,
            "whole_share_pending_usd": wsa_decision.pending_after_usd,
            "whole_share_contribution_usd": wsa_decision.contribution_usd,
        }
        # A BUY trigger fired and accumulated -- deliberate, not a failure --
        # but without an explicit loop_block_reasons entry,
        # classify_missing_fill falls through to MISSING_FILL_FAILED_TRIGGER
        # since decision.action == Action.BUY (Codex review: "Classify
        # below-threshold accumulation in coverage reports").
        _block(
            MISSING_FILL_ACCUMULATING,
            f"{ticker}: whole-share contribution accumulated, share threshold not yet reached",
        )
        return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc

    # planned_order_notional is the FULL amount record_contribution already
    # deducted from the ledger -- the figure any preserve_pending call below
    # must restore in full when this candidate is blocked before placement
    # (nothing submitted at all). quantity/order_notional are what this run
    # actually attempts to submit, which the per-order-ceiling clamp below
    # may reduce below the planned amount; settle()'s own shortfall
    # restoration (given the same idempotency_key) reconciles the two
    # automatically once a submission is confirmed.
    planned_order_notional = wsa_decision.order_notional_usd
    quantity = wsa_decision.shares_to_buy
    order_notional = planned_order_notional

    def _preserve_and_block(reason_code: str, block_outcome: Dict[str, Any]) -> Dict[str, Any]:
        nonlocal errors_count_inc
        try:
            ledger.preserve_pending(
                ticker,
                trading_day_iso,
                planned_order_notional,
                stream=ctx.stream,
                recorded_at=ctx.now.isoformat(),
                idempotency_key=idempotency_key,
                claim_token=wsa_decision.claim_token,
            )
        except Exception as exc:  # noqa: BLE001 - preserve_pending itself can raise
            # (a lock timeout, unreadable ledger, or write failure) here --
            # the same failure-isolation problem already handled for
            # still_claimed() above. Without this boundary the exception
            # would escape _process_buy_candidates_batch entirely, aborting
            # unrelated candidates while this ticker gets no data-error
            # outcome and its deducted fire stays unresolved with no record
            # of why. record_contribution's deduction is left exactly as-is
            # (neither settled nor restored) rather than retried, since this
            # claim's true state could not be verified -- the ORIGINAL block
            # reason is superseded by this restoration failure so the
            # returned outcome reflects what actually happened (Codex
            # review: "Isolate failures while restoring blocked fires").
            errors_count_inc += 1
            _block(
                MISSING_FILL_DATA_ERROR,
                f"{ticker}: whole-share preserve_pending failed: {exc}; skipping",
            )
            return {
                "status": "blocked",
                "skip_reason": f"whole-share: failed to restore pending balance: {exc}",
                "deliberate_skip": True,
                # Marks this outcome as whole-share-originated for
                # _build_buy_candidates's key-based detection (see that
                # function's own comment) -- without SOME "whole_share_"
                # field, a non-BUY (NO_ACTION-redispatched or ordinary)
                # ticker's restoration-failure outcome would be silently
                # dropped from buy_candidates.csv/run_state.json by the
                # BUY-only filter, even though errors_count_inc correctly
                # counted the failure (Codex review: "Retain the whole-share
                # marker when restoration fails").
                "whole_share_planned_notional_usd": planned_order_notional,
            }
        _block(reason_code, f"{ticker}: {block_outcome['skip_reason']}; skipping")
        # A fire that got THIS far (past the below-threshold skip) blocked
        # with a real planned notional in flight -- the full accumulated
        # order_notional_usd record_contribution already deducted, not just
        # today's contribution. _build_buy_candidates reads this to record
        # what the run actually planned to spend, not $0 or the raw
        # suggested_amount_usd (Codex review: "Persist the actual
        # whole-share planned notional").
        block_outcome.setdefault("whole_share_planned_notional_usd", planned_order_notional)
        return block_outcome

    # Hard per-order ceiling, within_caps budget check, and bid/ask spread
    # gate -- the SAME gates the dry-run preview branch above applies, via
    # the shared _whole_share_risk_gates helper, mirroring the normal buy
    # path's own checks (Codex review: "Apply the normal risk gates before
    # whole-share dispatch"). Run BEFORE any broker round-trip. A whole-share
    # order is discrete, so a partial per-order-ceiling cap clamps the
    # QUANTITY down rather than blocking outright.
    # Clamp using the ledger's OWN cent-rounded price (wsa_decision.current_share_price_usd),
    # not the raw current_share_price -- record_contribution already rounded
    # it via _money() before computing planned_order_notional, and settle()'s
    # shortfall restoration below subtracts a submitted notional derived here
    # from that SAME cached planned_order_notional. Clamping from the raw,
    # unrounded price instead would compute a submitted notional on a
    # different price basis than the plan, corrupting the shortfall math
    # (Codex review: "Restore clamped credit using the ledger price" -- e.g.
    # $20 pending at a raw $0.996 price deducts 20 shares at the ledger's
    # rounded $1.00, so a clamp to 10 shares must submit $10.00, not the
    # raw-price $9.96 that would report a $10.04 "shortfall").
    block_outcome, quantity, order_notional, spread_fields, is_error = _whole_share_risk_gates(
        ticker,
        quantity,
        order_notional,
        wsa_decision.current_share_price_usd,
        ctx,
        ceiling_override_usd=kill_switch_ceiling_usd,
    )
    if block_outcome is not None:
        if is_error:
            errors_count_inc += 1
            reason_code = MISSING_FILL_DATA_ERROR
        elif block_outcome.get("budget_blocked"):
            reason_code = MISSING_FILL_BUDGET_CAPPED
        else:
            reason_code = MISSING_FILL_BROKER_BLOCKED
        candidate_outcome = _preserve_and_block(reason_code, block_outcome)
        return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc

    try:
        available_buying_power = ctx.broker.available_buying_power()
    except Exception as exc:  # noqa: BLE001 - record_contribution already
        # deducted the full planned notional by this point; a raise from this
        # lookup (broker/network outage) must not escape without restoring it
        # the same way the tradability-lookup failure just above does, or the
        # batch aborts with no order submitted AND the accumulator
        # permanently short by the unplaced amount (Codex review: "Restore
        # pending credit when buying-power lookup fails").
        errors_count_inc += 1
        candidate_outcome = _preserve_and_block(
            MISSING_FILL_DATA_ERROR,
            {
                "status": "blocked",
                "skip_reason": f"whole-share: buying power lookup failed: {exc}",
                "deliberate_skip": True,
                **spread_fields,
            },
        )
        return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc
    if available_buying_power < order_notional:
        candidate_outcome = _preserve_and_block(
            MISSING_FILL_BUDGET_CAPPED,
            {
                "status": "blocked",
                "skip_reason": "whole-share: insufficient buying power",
                "deliberate_skip": True,
                "budget_blocked": True,
                **spread_fields,
            },
        )
        return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc

    # Checked unconditionally (both scheduled and manual), mirroring how
    # is_tradable_for_fractional_buy gates the normal buy path -- distinct
    # from review_whole_share_buy below, which (like review_market_buy) only
    # runs on a manual run. Without this, a scheduled run could reach
    # place_whole_share_buy for an instrument that went halted/inactive/
    # non-tradeable while quote data remained available, with no
    # pre-placement tradability check at all (Codex review: "Verify
    # whole-share tradability before scheduled placement").
    try:
        tradable = ctx.broker.is_tradable_for_whole_share_buy(ticker)
    except Exception as exc:  # noqa: BLE001 - the broker's tradability lookup
        # itself can raise (network/API failure); record_contribution already
        # deducted the full planned notional by this point, so a raise here
        # must not escape without restoring it -- otherwise the batch aborts
        # with no order submitted AND the accumulator permanently short by
        # the unplaced amount (Codex review: "Restore the deduction when
        # tradability lookup raises").
        errors_count_inc += 1
        candidate_outcome = _preserve_and_block(
            MISSING_FILL_DATA_ERROR,
            {
                "status": "blocked",
                "skip_reason": f"whole-share: tradability lookup failed: {exc}",
                "deliberate_skip": True,
                **spread_fields,
            },
        )
        return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc
    if not tradable:
        candidate_outcome = _preserve_and_block(
            MISSING_FILL_BROKER_BLOCKED,
            {
                "status": "blocked",
                "skip_reason": "whole-share: not tradable",
                "deliberate_skip": True,
                **spread_fields,
            },
        )
        return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc

    reviewed_order = None
    if not ctx.scheduled:
        order_reviews_attempted_inc += 1
        try:
            review_ok, review_reason = ctx.broker.review_whole_share_buy(ticker, quantity)
        except Exception as exc:  # noqa: BLE001 - the broker's review call itself
            # can raise (network/API failure) on a manual run, exactly like the
            # tradability lookup above -- record_contribution already deducted
            # the full planned notional by this point, so a raise here must not
            # escape without restoring it (Codex review: "Restore the ledger
            # when manual review raises").
            errors_count_inc += 1
            candidate_outcome = _preserve_and_block(
                MISSING_FILL_DATA_ERROR,
                {
                    "status": "blocked",
                    "skip_reason": f"whole-share: review failed: {exc}",
                    "deliberate_skip": True,
                    **spread_fields,
                },
            )
            return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc
        if not review_ok:
            candidate_outcome = _preserve_and_block(
                MISSING_FILL_BROKER_BLOCKED,
                {
                    "status": "blocked",
                    "skip_reason": f"whole-share review blocked order: {review_reason}",
                    "deliberate_skip": True,
                    **spread_fields,
                },
            )
            return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc
        reviewed_order = {
            "quantity": quantity,
            "side": "buy",
            "order_type": "market",
            "time_in_force": None,
            "review_passed": True,
        }

    # Re-verify this call still holds the fire's claim immediately before the
    # one truly irreversible step -- placement. record_contribution's
    # stale-claim reclaim (see dca_whole_share_accumulator.py's
    # UNRESOLVED_CLAIM_STALE_SECONDS) only establishes that a NEW overlapping
    # caller is free to try; it does not, by itself, stop THIS caller from
    # placing an order it no longer exclusively owns if a reclaim happened
    # in between (Codex review: "Fence the previous owner before reclaiming
    # stale fires"). A caller that lost the claim abstains without touching
    # the ledger -- the reclaiming caller owns the SAME single deduction
    # already made by record_contribution, so preserving it here would
    # incorrectly restore money a still-viable attempt may yet spend.
    try:
        still_owns_claim = ledger.still_claimed(
            ticker, trading_day_iso, idempotency_key, ctx.now.isoformat(), wsa_decision.claim_token
        )
    except Exception as exc:  # noqa: BLE001 - a corrupt/unreadable ledger or a lock
        # timeout here means this call cannot establish whether it still owns
        # the claim record_contribution already made. Unlike the OTHER
        # ledger-error boundaries in this function, calling preserve_pending()
        # would be unsafe here: if a reclaiming caller actually does own the
        # claim now, preserving would restore money that caller may yet
        # spend. Fail this candidate closed instead -- record the error and
        # skip without mutating a claim whose ownership could not be
        # established, leaving its resolution to whichever caller can
        # actually verify it (Codex review: "Isolate claim-verification
        # ledger failures").
        errors_count_inc += 1
        candidate_outcome = {
            "status": "blocked",
            "skip_reason": f"whole-share: claim verification failed: {exc}",
            "deliberate_skip": True,
            **spread_fields,
        }
        _block(MISSING_FILL_DATA_ERROR, f"{ticker}: whole-share claim verification failed: {exc}; skipping")
        return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc
    if not still_owns_claim:
        candidate_outcome = {
            "status": "skipped",
            "skip_reason": "whole-share: lost the fire claim to a newer overlapping attempt",
            "deliberate_skip": True,
        }
        _block(MISSING_FILL_BUDGET_CAPPED, f"{ticker}: whole-share claim reclaimed by a newer attempt; skipping")
        return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc

    # A SECOND, fresh same-day-order check, immediately before placement --
    # still_claimed() only detects a reclaim that already happened by the
    # time it runs; it cannot detect one that starts DURING this caller's own
    # broker round-trip (Codex review: "Hold the claim through the broker
    # placement", evaluated: a lock spanning the whole broker call would
    # close this fully but would mean holding a cross-process file lock
    # across network I/O, which this module's own separation of concerns --
    # "deliberately contains only deterministic math plus a durable ledger"
    # -- deliberately keeps broker-agnostic; see
    # docs/whole_share_accumulation.md's "Concurrency" section for the full
    # reasoning). This recheck cannot close the race either (both callers
    # could still be mid-placement simultaneously), but it narrows the
    # window from the full UNRESOLVED_CLAIM_STALE_SECONDS reclaim window down
    # to one broker round-trip: if a reclaiming caller's OWN placement has
    # already landed at the broker by the time this check runs, this caller
    # aborts instead of submitting a second live order for the same fire.
    ref_id = f"{_graded_dca_ref_id_prefix(ctx.stream, 'wholeshare')}-{trading_day_iso}-{ticker}"
    try:
        duplicate_order_exists = ctx.broker.same_day_strategy_order_exists(ticker, ctx.trading_day)
    except Exception as exc:  # noqa: BLE001 - this second, pre-placement duplicate
        # lookup can itself raise (network/API failure), exactly like the
        # earlier tradability/review lookups -- record_contribution already
        # deducted the full planned notional by this point, so letting the
        # exception escape here would abort the run with the cached fire
        # still unresolved and its amount absent from pending_usd. Unlike a
        # successful duplicate match (a genuine reclaim, where preserving
        # would incorrectly restore money a still-viable attempt may yet
        # spend), this is a known pre-placement failure -- no order has been
        # placed by anyone, so it is always safe to preserve the deduction
        # (Codex review: "Restore the fire when the final duplicate lookup
        # raises").
        errors_count_inc += 1
        candidate_outcome = _preserve_and_block(
            MISSING_FILL_DATA_ERROR,
            {
                "status": "blocked",
                "skip_reason": f"whole-share: same-day duplicate order lookup failed: {exc}",
                "deliberate_skip": True,
                **spread_fields,
            },
        )
        return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc
    if duplicate_order_exists:
        # The broad check above is True for ANY live same-day order for this
        # ticker, including a completely UNRELATED one (a manual trade, or a
        # different stream's own fire) that has nothing to do with THIS
        # claim -- skipping on that broad signal alone left this claim's
        # still-deducted, still-owned reservation untouched (neither placed
        # nor preserved), and every LATER retry hits the initial broad
        # duplicate check (top of this function), fails to find an exact
        # ref_id match there either, and keeps skipping forever, permanently
        # stranding the deduction (Codex review: "Preserve the claim when a
        # late duplicate is unrelated"). Verify with an EXACT ref_id match
        # before deciding: a real match means a reclaiming attempt's OWN
        # placement for THIS fire already landed at the broker -- correctly
        # abort without preserving (crediting back would double-credit a
        # claim someone else already spent). No exact match means the broad
        # signal was unrelated -- fall through and attempt placement
        # normally instead of treating it as this claim's own. This second
        # lookup only runs when the broad check is ALREADY true, so the
        # common case (no duplicate at all) makes no extra broker call.
        try:
            duplicate_order = ctx.broker.same_day_strategy_order_exists_with_ref_id_prefix(
                ticker, ctx.trading_day, (ref_id,)
            )
        except Exception as exc:  # noqa: BLE001 - a failed verification lookup
            # cannot distinguish "our own reclaimed order" from "unrelated" --
            # UNLIKE the broad lookup's own exception just above, this is NOT
            # unconditionally safe to preserve: the broad check that gated
            # entry into this branch already established that SOME live
            # same-day order exists for this ticker RIGHT NOW. If that order
            # is actually this candidate's own claim, reclaimed and already
            # placed by a concurrent attempt in the window between
            # still_claimed() and here, restoring the deduction (as
            # _preserve_and_block does) would let that same money fire again
            # once the reclaimed order fills -- exactly the double-credit
            # hazard the exact-ref verification exists to rule out (Codex
            # review: "Keep reclaimed claims reserved when exact lookup
            # fails"). A failed broad lookup, by contrast, proves nothing
            # lives at the broker at all, so preserving there is safe. Leave
            # the claim exactly as record_contribution/the reclaimer left it
            # -- neither settled nor restored -- for a later reconciliation
            # attempt to resolve, mirroring this module's other genuinely
            # ambiguous post-submission/history lookup failures.
            errors_count_inc += 1
            candidate_outcome = {
                "status": "blocked",
                "skip_reason": f"whole-share: duplicate ref_id verification failed: {exc}",
                "deliberate_skip": True,
                **spread_fields,
            }
            _block(
                MISSING_FILL_DATA_ERROR,
                f"{ticker}: whole-share duplicate ref_id verification failed: {exc}; "
                "leaving claim reserved rather than restoring credit",
            )
            return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc
        duplicate_order_exists = bool(duplicate_order)
    if duplicate_order_exists:
        candidate_outcome = {
            "status": "skipped",
            "skip_reason": "whole-share: same-day broker order now exists (reclaimed and placed elsewhere)",
            "deliberate_skip": True,
        }
        _block(
            MISSING_FILL_BUDGET_CAPPED,
            f"{ticker}: whole-share same-day broker order now exists; a reclaiming attempt likely already "
            "placed it; skipping",
        )
        return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc

    try:
        owns_claim, placement = ledger.execute_claimed(
            ticker,
            trading_day_iso,
            idempotency_key,
            ctx.now.isoformat(),
            lambda: ctx.broker.place_whole_share_buy(ticker, quantity, ref_id),
            # Token-aware ownership check, not just the timestamp -- a
            # fenced-out caller sharing the same recorded_at as a later
            # reclaim must not slip past execute_claimed()'s own check (see
            # its docstring; Codex review discussion_r3818217238, "Validate
            # the claim token before placing the order").
            claim_token=wsa_decision.claim_token,
        )
        if not owns_claim or placement is None:
            candidate_outcome = {
                "status": "skipped",
                "skip_reason": "whole-share: lost the fire claim to a newer overlapping attempt",
                "deliberate_skip": True,
            }
            return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc
        order_id = placement
        # The broker has accepted. Everything from here to the first publish
        # is fallible (order-history lookup, quantity parsing, ledger
        # settlement), and a raise in that window leaves nothing published --
        # which the batch's isolation net would otherwise read as "no order
        # was ever placed" (Codex review, PR #786: "Halt on unpublished
        # whole-share acceptances"). Marked at the placement site rather than
        # on any return path, so no future branch can forget to.
        _mark_whole_share_acceptance(ticker, order_id, order_notional)
    except WholeShareClaimPersistenceError as exc:
        # operation() (the broker call) already SUCCEEDED -- exc.result is a
        # real, live order id -- but ledger.execute_claimed() could not
        # durably persist the ledger's own "placed" marker afterward. Unlike
        # every OTHER exception this try/except catches (which all mean NO
        # order was ever submitted, so the generic `except Exception` branch
        # below correctly calls preserve_pending() to restore the deduction),
        # falling into that same restore-and-retry handling here would
        # restore credit for an order that is actually live at the broker,
        # letting a later fire spend the same deducted dollars again (Codex
        # review discussion_r3804235587, "Preserve broker acceptance when
        # persisting `placed` fails"). Treat this exactly like a normal
        # successful placement instead -- keep the order id and fall through
        # into the same post-placement reconciliation flow every other
        # accepted order goes through -- but log it distinctly, since this
        # ledger's own claim bookkeeping for this fire may still need manual
        # reconciliation if a retry is attempted before the ledger can
        # durably write again.
        order_id = exc.result
        # Same post-broker evidence as the clean acceptance above -- this
        # branch exists precisely because the order IS live at the broker.
        _mark_whole_share_acceptance(ticker, order_id, order_notional)
        logger.error(
            "Whole-share order accepted for %s (order_id=%s) but the ledger could not persist its "
            "'placed' marker: %s; continuing as a normal accepted order, but this claim may need "
            "manual reconciliation",
            ticker,
            order_id,
            exc,
        )
    except OrderConfirmationRequiredError:
        # Mirrors the normal buy path's own identical branch: review passed
        # but the broker requires a separate post-review confirmation step
        # before it will actually submit -- an expected hold, not a
        # placement failure, so this must NOT count toward errors_count_inc
        # or be classified "failed" (which the generic handler below would
        # do, misclassifying a manual whole-share run as
        # not_submitted_error and potentially triggering failure recovery/
        # escalation for something that isn't an error) (Codex review:
        # "Handle confirmation-required whole-share placements distinctly").
        # No order was placed, so the deduction must still be restored.
        try:
            ledger.preserve_pending(
                ticker,
                trading_day_iso,
                planned_order_notional,
                stream=ctx.stream,
                recorded_at=ctx.now.isoformat(),
                idempotency_key=idempotency_key,
                claim_token=wsa_decision.claim_token,
            )
        except Exception as restore_exc:  # noqa: BLE001 - this restoration call
            # can itself raise (a lock timeout, corrupt ledger, or write
            # error) the same way the generic placement-failure branch's own
            # identical call can -- without an adjacent boundary here, the
            # exception escapes _process_buy_candidates_batch entirely,
            # aborting every other, unrelated candidate still to be
            # processed (Codex review: "Isolate restoration failures in the
            # confirmation-required path"). The claim is left exactly as
            # record_contribution left it (neither settled nor restored,
            # since its true state could not be verified) -- handled as a
            # per-candidate data error rather than the "not_submitted_
            # confirmation_required" status this branch would otherwise
            # report.
            errors_count_inc += 1
            candidate_outcome = {
                "status": "blocked",
                "broker_placement_failed": True,
                "order_id": None,
                "skip_reason": (
                    "whole-share broker requires confirmation before submission; "
                    f"restoration also failed: {restore_exc}"
                ),
                "reviewed_order": reviewed_order,
                "submitted_amount_usd": order_notional,
                **spread_fields,
            }
            logger.error(
                "Whole-share confirmation-required restoration failed for %s: %s",
                ticker,
                restore_exc,
            )
            return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc
        candidate_outcome = {
            "status": "not_submitted_confirmation_required",
            "broker_placement_failed": True,
            "order_id": None,
            "skip_reason": "broker requires post-review confirmation before submission",
            "reviewed_order": reviewed_order,
            "submitted_amount_usd": order_notional,
            # Marks this outcome as whole-share-originated for
            # _build_buy_candidates's key-based detection (see that
            # function's own comment) -- without SOME "whole_share_" field,
            # a manual, NO_ACTION-redispatched ticker's confirmation-required
            # outcome would be silently dropped from buy_candidates.csv/
            # run_state.json by the BUY-only filter, and if it were the
            # ONLY candidate this run, the run would report no_candidates
            # instead of confirmation_required (Codex review: "Preserve
            # confirmation-required redispatch outcomes").
            "whole_share_planned_notional_usd": planned_order_notional,
            **spread_fields,
        }
        _block(
            MISSING_FILL_BROKER_BLOCKED,
            f"{ticker}: whole-share broker requires confirmation before submission; skipping",
        )
        return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc
    except Exception as exc:  # noqa: BLE001
        # place_whole_share_buy can raise AFTER the broker has already
        # accepted the order -- a response timeout or connector failure
        # while relaying the accepted order back is indistinguishable, from
        # here, from a genuine rejection. Blindly restoring the deducted
        # pending credit below in that case would let a LATER trading day
        # spend the same dollars again while the broker-side order already
        # consumed them; a same-day retry might independently notice the
        # order via the duplicate-order check above and skip, but nothing
        # else re-examines an already-restored balance (Codex review:
        # "Reconcile ambiguous placement failures before restoring
        # credit"). ref_id is deterministic and reused verbatim on every
        # retry for this idempotency slot (see its construction above), so
        # an exact-match lookup against the broker's own same-day order
        # history settles the ambiguity authoritatively before deciding
        # whether to preserve or settle this claim.
        #
        # A WholeSharePlacementTerminalError already carries the broker's
        # OWN immediate response -- itself authoritative terminal evidence
        # (state + cumulative_quantity + average_price) -- so this live-only
        # lookup is skipped entirely for it: the order is KNOWN to be
        # terminal, so a live-only lookup could only ever report "no match"
        # regardless of what actually executed (Codex review: "Reconcile
        # terminal fills from the placement response").
        if isinstance(exc, WholeSharePlacementTerminalError):
            matched_order = None
        else:
            try:
                matched_order = ctx.broker.same_day_strategy_order_exists_with_ref_id_prefix(
                    ticker, ctx.trading_day, (ref_id,)
                )
            except Exception as lookup_exc:  # noqa: BLE001
                # A failed reconciliation lookup establishes NEITHER outcome -- it
                # is NOT proof the order was rejected, so falling through to the
                # preserve_pending branch below (as an earlier version of this
                # fix did) would restore credit for an order that may actually be
                # LIVE at the broker, letting a later trading day spend it again
                # -- exactly the hazard this reconciliation step exists to close
                # (Codex review: "Keep ambiguous claims reserved when
                # reconciliation fails"). Mirrors the placement-time
                # still_claimed verification failure's own posture (see that
                # branch's "Isolate claim-verification ledger failures" comment
                # above): fail this candidate closed WITHOUT mutating the ledger
                # at all -- neither settled nor restored -- leaving the claim
                # exactly as record_contribution left it for a later run (once
                # the broker's order history is reachable again) or manual
                # reconciliation to resolve.
                errors_count_inc += 1
                candidate_outcome = {
                    "status": "blocked",
                    "broker_placement_failed": True,
                    "order_id": None,
                    "skip_reason": (
                        f"whole-share placement failed: {type(exc).__name__}; reconciliation lookup also failed: "
                        f"{type(lookup_exc).__name__}; claim left reserved pending manual reconciliation"
                    ),
                    "reviewed_order": reviewed_order,
                    "submitted_amount_usd": order_notional,
                    "whole_share_planned_notional_usd": planned_order_notional,
                    **spread_fields,
                }
                logger.error(
                    "Whole-share placement-failure reconciliation lookup failed for %s: %s "
                    "(original placement error: %s); leaving claim reserved rather than restoring credit",
                    ticker,
                    lookup_exc,
                    exc,
                )
                return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc
        if matched_order and str(matched_order.get("state", "")).lower() != "filled":
            # A live/working match (new/queued/confirmed/unconfirmed/
            # partially_filled) is NOT yet proof of what actually happened --
            # its final filled quantity is not known until it reaches a
            # TERMINAL state, mirroring
            # _reconcile_unresolved_whole_share_claim's own identical
            # requirement (see that function's "Only settle once the matched
            # order has reached a TERMINAL 'filled' state" note). The
            # whole-share LEDGER claim therefore stays exactly as
            # record_contribution left it -- neither settled nor restored --
            # for a later reconciliation attempt (the cross-day/same-day
            # duplicate-check paths both retry via
            # _reconcile_unresolved_whole_share_claim) once the order
            # actually terminates. But reporting "blocked" here (an earlier
            # version of this fix did) mirrors the SAME hazard the
            # terminal-inclusive fallback's own identical branch below was
            # already fixed to close: never calling record_buy()/bumping
            # running_deployed_7d lets later candidates in this SAME batch
            # exceed the daily attempt count, daily/weekly notional caps, or
            # the kill switch while this accepted order remains live and
            # completely uncounted, and a "blocked" row cannot reconstruct
            # the attempt on a later run's prior-allocation reload either
            # (Codex review: "Book matched live orders before continuing").
            # Books the LOCALLY-CLAMPED quantity/order_notional (already
            # narrowed by _whole_share_risk_gates before this placement
            # attempt, so it reflects what was actually submitted, not the
            # claim's unclamped plan).
            errors_count_inc += 1
            matched_state = str(matched_order.get("state", "")) or "unknown"
            # Routed through `_normalized_order_id` (which `record_buy`
            # also calls internally on entry), not the raw `str(x or "")
            # or None` this site used before: that pre-stringified a
            # truthy NON-SCALAR primary alias (`{"id": ["BAD"], "order_id":
            # "REAL", "state": "queued"}` -- `_first_usable_order_id_alias`
            # returns the list verbatim) into the apparently-valid string
            # "['BAD']" BEFORE `record_buy`'s own internal normalization
            # ever ran, so its non-scalar rejection (added for exactly
            # this class of bug) never got a chance to see the ORIGINAL
            # list -- only the already-stringified text, which reads as an
            # ordinary non-numeric id and is durably recorded as-is,
            # burying the real, usable "REAL" secondary alias. If history
            # later supplies "REAL" for the same ambiguous attempt,
            # reconciliation treats it as a different order and can
            # restore the same attempt again (Codex review, PR #1168:
            # "Preserve usable secondary IDs when recording whole-share
            # attempts").
            order_id = _normalized_order_id(_first_usable_order_id_alias(matched_order))
            ctx.state.record_buy(ticker, ctx.trading_day, order_notional, order_id=order_id)
            ctx.state.own_orders_recorded.add((ticker, ctx.trading_day))
            if ctx.scheduled:
                running_deployed_7d += order_notional
            logger.warning(
                "Whole-share placement-failure reconciliation for %s found a still-live order "
                "(state=%s); recorded as submitted/unfilled, ledger claim left reserved until it "
                "terminates",
                ticker,
                matched_state,
            )
            candidate_outcome = {
                "status": "submitted",
                "broker_placement_succeeded": True,
                "order_id": order_id,
                "skip_reason": None,
                "reviewed_order": reviewed_order,
                "submitted_amount_usd": order_notional,
                "buy_multiplier": decision.buy_multiplier,
                "whole_share_quantity": quantity,
                "whole_share_pending_usd": wsa_decision.pending_after_usd,
                "whole_share_contribution_usd": wsa_decision.contribution_usd,
                "whole_share_settlement_reconciliation_needed": True,
                "whole_share_settlement_shortfall_usd": 0.0,
                **spread_fields,
            }
            candidate_outcome = _publish_whole_share_outcome(candidate_outcome)
            if ctx.run_result is not None:
                _log_execution(ctx.run_result, decision, order_id or "", ctx.broker, notional_usd=order_notional)
            return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc
        if matched_order:
            # The broker DID accept the order despite the exception, and it
            # has reached a TERMINAL 'filled' state -- mirror the ordinary
            # success path below: settle (never restore) the claim and
            # report a submitted outcome using the broker's own order id.
            # Routed through `_normalized_order_id`, not a raw
            # `str(... or "")`: when the primary "id" alias is blank and
            # the fallback "order_id" is a malformed non-scalar (a list or
            # mapping), `_first_usable_order_id_alias` returns that
            # fallback unchanged, and a raw `str()` would fabricate an
            # apparently-valid id like "['BAD']" before `record_buy()` can
            # ever validate it. If later history reports the real scalar
            # id for the same broker order, reconciliation would treat the
            # fabricated id as an unrelated durable attempt and restore
            # the same order again, inflating the daily attempt count and
            # notional (Codex review, PR #1168: "Normalize secondary IDs
            # before stringifying").
            order_id = _normalized_order_id(_first_usable_order_id_alias(matched_order)) or ""
            # Use the matched order's OWN filled quantity/average_price, not
            # the locally-computed planned quantity/order_notional -- a
            # market order can fill at a different price than the
            # signal-time quote this candidate was planned against, and the
            # cross-day/terminal-partial-fill reconciliation paths already
            # prefer the broker's real fill price for this same reason
            # (Codex review: "Book the actual fill notional after immediate
            # recovery"). Falls back to the locally-planned quantity/price
            # only when the matched order carries no usable quantity/price
            # field at all.
            #
            # PRESENCE, not truthiness: the sibling construction in the
            # ordinary-success branch below made the same mistake, and this
            # is where the finding says it originates -- `... or
            # matched_order.get("quantity")` reads an explicit
            # `cumulative_quantity: 0` the same as an absent one and falls
            # through to the REQUESTED quantity, settling for a full-share
            # spend on a fill the broker explicitly reported as zero. A
            # negative `cumulative_quantity` was accepted the same wrong way
            # (Codex review, PR #786: "Reject invalid cumulative quantities
            # before settling"). `_finite_nonnegative_float` is this
            # module's existing "usable broker figure" gate; an unreadable
            # or invalid `cumulative_quantity` now falls back to
            # `quantity`'s presence rather than being silently replaced by
            # it, and the unreadable-figure fallback to the planned quantity
            # is unchanged for the case neither key resolves.
            if "cumulative_quantity" in matched_order:
                raw_filled_quantity = matched_order.get("cumulative_quantity")
                filled_quantity_field_present = True
            elif "quantity" in matched_order:
                raw_filled_quantity = matched_order.get("quantity")
                filled_quantity_field_present = True
            else:
                raw_filled_quantity = None
                filled_quantity_field_present = False
            filled_shares = quantity
            validated_filled_quantity = _finite_nonnegative_float(raw_filled_quantity)
            if validated_filled_quantity is not None:
                filled_shares = int(validated_filled_quantity)
            # PRESENT but unreadable/negative is a different answer from
            # ABSENT -- see the sibling ordinary-success branch's identical
            # flag for the full reasoning (Codex review, PR #786: "Keep
            # invalid filled quantities unresolved"). A contradictory
            # `cumulative_quantity` on an order this branch just recovered
            # via ref_id is not silence about the fill; settling against the
            # locally-planned `filled_shares` here would book an unverified
            # guess as a confirmed fact.
            #
            # PRESENCE of the key decides, not truthiness of its value: an
            # explicit `cumulative_quantity: null` is Python `None`, exactly
            # like an absent key, so reading `raw_filled_quantity is not
            # None` let that exact null bypass this guard too (Codex review,
            # PR #786: "Treat explicit null fill quantities as unresolved").
            quantity_evidence_unreadable = filled_quantity_field_present and validated_filled_quantity is None
            fill_price = _usable_positive_float(matched_order.get("average_price"))
            price_for_notional = fill_price if fill_price is not None else current_share_price
            filled_notional = round(filled_shares * price_for_notional, 2)
            # Mirrors settle()'s OWN internal shortfall math exactly: (the
            # claim's ORIGINAL cached-price-priced planned notional) minus
            # (the REAL filled share count, also at the cached price) --
            # both quantity (the per-order-ceiling-CLAMPED submission) and
            # filled_shares (the broker's real, possibly-partial execution)
            # can each be less than the claim's own original shares_to_buy,
            # and settle() restores the combined difference from ITS cached
            # claim entry, not from a locally-recomputed share delta. Using
            # the REAL fill price here (as an earlier version of this fix
            # did, via filled_notional) would mix two different prices into
            # one shortfall figure -- a two-share $20 claim at a $10 cached
            # price, filled 1 share at $12, needs the unfilled share's $10
            # restored, not $20-$12=$8 (Codex review: "Compute partial-fill
            # shortfalls from the cached share price"). Computed
            # unconditionally (used both if settle() fails AND, below, as
            # the read-failure fallback when settle() succeeds but the
            # authoritative post-settlement balance can't be re-read).
            settlement_shortfall_usd = round(
                max(0.0, planned_order_notional - filled_shares * current_share_price), 2
            )
            settlement_failed = False
            resolved_by_this_call = False
            if quantity_evidence_unreadable:
                # Never settle against a quantity this branch cannot trust --
                # same treatment as a settle() exception below: the ledger
                # claim is left exactly as record_contribution left it,
                # neither settled nor restored, for manual reconciliation.
                settlement_failed = True
                logger.error(
                    "whole-share accumulation ledger settlement skipped for %s (order_id=%s) after "
                    "reconciling an ambiguous placement failure: broker reported an unreadable/"
                    "contradictory fill quantity (%r) -- claim left reserved for manual reconciliation",
                    ticker,
                    order_id,
                    raw_filled_quantity,
                )
            else:
                try:
                    resolved_by_this_call = ledger.settle(
                        ticker,
                        trading_day_iso,
                        filled_shares,
                        filled_notional,
                        stream=ctx.stream,
                        recorded_at=ctx.now.isoformat(),
                        idempotency_key=idempotency_key,
                        claim_token=wsa_decision.claim_token,
                        require_claim_ownership=True,
                    )
                except Exception as settle_exc:  # noqa: BLE001
                    settlement_failed = True
                    logger.error(
                        "whole-share accumulation ledger settlement failed for %s (order_id=%s) "
                        "after reconciling an ambiguous placement failure: %s",
                        ticker,
                        order_id,
                        settle_exc,
                    )
            if not settlement_failed and not resolved_by_this_call:
                # require_claim_ownership=True means settle() returning
                # False (no exception) is a CLEAN signal that a concurrent
                # reconciler already won this exact claim and already
                # booked it -- unconditionally recording the buy/
                # incrementing running_deployed_7d/publishing another
                # "submitted" execution here would double-book the SAME
                # physical broker order this run never actually needs to
                # book again (Codex review: "Skip immediate booking after
                # losing claim ownership").
                candidate_outcome = {
                    "status": "skipped",
                    "order_id": order_id or None,
                    "skip_reason": "whole-share: claim already resolved by a concurrent reconciler",
                    "deliberate_skip": True,
                    "reviewed_order": reviewed_order,
                    **spread_fields,
                }
                candidate_outcome = _publish_whole_share_outcome(candidate_outcome)
                return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc
            ctx.state.record_buy(ticker, ctx.trading_day, filled_notional, order_id=order_id)
            ctx.state.own_orders_recorded.add((ticker, ctx.trading_day))
            if ctx.scheduled:
                running_deployed_7d += filled_notional
            logger.info(
                "Whole-share buy for %s already accepted by broker despite a placement "
                "error (%s); reconciled via ref_id, order_id=%s",
                ticker,
                exc,
                order_id,
            )
            # Read the AUTHORITATIVE post-settlement pending balance here too --
            # mirrors the ordinary success path's own identical read just below
            # this branch. When a per-order-ceiling clamp reduced quantity/
            # order_notional below the originally-planned fire, settle()
            # restores the unsubmitted shares' credit back into pending_usd;
            # reporting the pre-settlement wsa_decision.pending_after_usd here
            # instead would understate the ledger's real balance by exactly
            # that restored shortfall (e.g. a two-share $16 fire clamped to
            # one $8 share leaves the ledger at $8 after settlement, but the
            # pre-settle snapshot would report $0) (Codex review: "Report the
            # restored balance after ambiguous placement recovery").
            try:
                post_fire_pending_usd = ledger.pending_usd(ticker)
            except Exception as read_exc:  # noqa: BLE001
                logger.warning(
                    "whole-share accumulation ledger read failed for %s after reconciled settlement: %s",
                    ticker,
                    read_exc,
                )
                post_fire_pending_usd = wsa_decision.pending_after_usd + (
                    0.0 if settlement_failed else settlement_shortfall_usd
                )
            candidate_outcome = {
                "status": "submitted",
                "broker_placement_succeeded": True,
                "order_id": order_id or None,
                "skip_reason": None,
                "reviewed_order": reviewed_order,
                "submitted_amount_usd": filled_notional,
                "buy_multiplier": decision.buy_multiplier,
                "whole_share_quantity": filled_shares,
                "whole_share_pending_usd": post_fire_pending_usd,
                "whole_share_contribution_usd": wsa_decision.contribution_usd,
                "whole_share_settlement_reconciliation_needed": settlement_failed,
                "whole_share_settlement_shortfall_usd": settlement_shortfall_usd,
                **spread_fields,
            }
            candidate_outcome = _publish_whole_share_outcome(candidate_outcome)
            if ctx.run_result is not None:
                _log_execution(ctx.run_result, decision, order_id, ctx.broker, notional_usd=filled_notional)
            return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc

        # The live-only lookup above cannot see a genuinely TERMINAL order
        # (cancelled/rejected/expired) -- exactly the gap
        # _reconcile_unresolved_whole_share_claim's own no-match branch
        # closes via the terminal-inclusive lookup. Without checking it
        # here too, a response-timeout retry whose order PARTIALLY filled
        # and was THEN cancelled before the live-only lookup ran would fall
        # straight through to preserve_pending below and restore the FULL
        # planned notional, discarding the executed shares' spent credit
        # and letting it fund another purchase (Codex review: "Check
        # terminal orders before restoring failed placements").
        # Reuses the broker's own already-known terminal payload for a
        # WholeSharePlacementTerminalError -- no need to perform (or risk a
        # failure of) the SAME terminal-inclusive lookup this branch exists
        # to answer, since that answer was already given in the placement
        # response itself (Codex review: "Reconcile terminal fills from the
        # placement response").
        if isinstance(exc, WholeSharePlacementTerminalError):
            terminal_order = exc.order
        else:
            try:
                terminal_order = ctx.broker.same_day_order_with_ref_id_prefix_any_state(
                    ticker, ctx.trading_day, (ref_id,)
                )
            except Exception as terminal_lookup_exc:  # noqa: BLE001
                # A raised terminal-inclusive lookup establishes NEITHER outcome
                # -- mirrors the live lookup's own failure posture just above
                # (Codex review: "Preserve claims when terminal-history lookup
                # fails"). Fail this candidate closed WITHOUT mutating the
                # ledger at all, rather than falling through to the restore
                # branch below as if the order were confirmed rejected.
                errors_count_inc += 1
                candidate_outcome = {
                    "status": "blocked",
                    "broker_placement_failed": True,
                    "order_id": None,
                    "skip_reason": (
                        f"whole-share placement failed: {exc}; terminal-order reconciliation lookup also "
                        f"failed: {terminal_lookup_exc}; claim left reserved pending manual reconciliation"
                    ),
                    "reviewed_order": reviewed_order,
                    "submitted_amount_usd": order_notional,
                    "whole_share_planned_notional_usd": planned_order_notional,
                    **spread_fields,
                }
                logger.error(
                    "Whole-share placement-failure terminal-order reconciliation lookup failed for %s: %s "
                    "(original placement error: %s); leaving claim reserved rather than restoring credit",
                    ticker,
                    terminal_lookup_exc,
                    exc,
                )
                return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc
        if terminal_order:
            # The any-state fallback exists to see a genuinely TERMINAL order
            # the live-only lookup deliberately excludes -- but it carries no
            # state filter of its own, so it can just as easily surface a
            # LIVE order that only became visible in the moment between the
            # two lookups. That order's cumulative_quantity is not yet
            # final: a positive value would settle the claim while the order
            # can still fill further, and a zero value would release the
            # FULL reservation while the order may still fill later. Only a
            # genuinely TERMINAL state (this module's canonical non-fill-
            # terminal set, or "filled" itself) is authoritative evidence of
            # the final outcome; anything else leaves the claim reserved,
            # mirroring the live-only matched_order branch's own identical
            # nonterminal guard above (Codex review: "Verify terminal state
            # after the any-state fallback").
            terminal_order_state = str(terminal_order.get("state", "")).lower()
            if terminal_order_state not in _TERMINAL_NON_FILL_STATES and terminal_order_state != "filled":
                # The broker DID accept this order despite the exception --
                # order_id is real and live (now routinely surfaced by
                # WholeSharePlacementTerminalError's own outer-failure inner
                # order too, see dca_live_adapters.py's "Preserve accepted
                # nonterminal orders in failure envelopes" fix). Reporting
                # "blocked" here (an earlier version of this fix did)
                # mirrors the SAME hazard the ordinary success path's "not
                # yet visible"/nonterminal branch was already fixed to
                # close: never calling record_buy()/bumping
                # running_deployed_7d lets later candidates in this SAME
                # batch exceed the daily attempt count, daily/weekly
                # notional caps, or the kill switch while this accepted
                # order remains live and completely uncounted, and a
                # "blocked" row cannot reconstruct the attempt on a later
                # run's prior-allocation reload either (Codex review: "Book
                # live failure-envelope orders before continuing"). Books
                # the LOCALLY-CLAMPED quantity/order_notional (already
                # narrowed by _whole_share_risk_gates before this
                # placement attempt, so it reflects what was actually
                # submitted, not the claim's unclamped plan) -- but the
                # whole-share LEDGER's own claim stays UNRESOLVED, exactly
                # like the ordinary success path's identical branch.
                errors_count_inc += 1
                # Routed through `_normalized_order_id`, not a raw
                # `str(... or "") or None`: the raw stringify accepts a
                # non-scalar/boolean/non-positive alias unchanged (e.g. a
                # terminal-inclusive row `{"id": true, "order_id": "REAL"}`
                # returns the boolean primary, which `str()` turns into the
                # apparently-valid id "True" before `record_buy()` can
                # reject the original sentinel). The fabricated id is then
                # durably recorded; if later history reports the real
                # order, reconciliation treats it as a distinct order and
                # restores the same attempt again, prematurely consuming
                # the daily order cap (Codex review, PR #1168: "Normalize
                # terminal-inclusive IDs before stringifying").
                order_id = _normalized_order_id(_first_usable_order_id_alias(terminal_order))
                ctx.state.record_buy(ticker, ctx.trading_day, order_notional, order_id=order_id)
                ctx.state.own_orders_recorded.add((ticker, ctx.trading_day))
                if ctx.scheduled:
                    running_deployed_7d += order_notional
                logger.warning(
                    "Whole-share placement-failure terminal-inclusive reconciliation for %s found a "
                    "still-live order (state=%s); recorded as submitted/unfilled, ledger claim left "
                    "reserved until it terminates",
                    ticker,
                    terminal_order_state or "unknown",
                )
                candidate_outcome = {
                    "status": "submitted",
                    "broker_placement_succeeded": True,
                    "order_id": order_id,
                    "skip_reason": None,
                    "reviewed_order": reviewed_order,
                    "submitted_amount_usd": order_notional,
                    "buy_multiplier": decision.buy_multiplier,
                    "whole_share_quantity": quantity,
                    "whole_share_pending_usd": wsa_decision.pending_after_usd,
                    "whole_share_contribution_usd": wsa_decision.contribution_usd,
                    "whole_share_settlement_reconciliation_needed": True,
                    "whole_share_settlement_shortfall_usd": 0.0,
                    **spread_fields,
                }
                candidate_outcome = _publish_whole_share_outcome(candidate_outcome)
                if ctx.run_result is not None:
                    _log_execution(ctx.run_result, decision, order_id or "", ctx.broker, notional_usd=order_notional)
                return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc
            # For a genuinely non-fill terminal state (cancelled/rejected/
            # expired), only cumulative_quantity is trustworthy evidence of
            # what actually executed -- that order's own "quantity" field is
            # merely what was REQUESTED/submitted, not what executed.
            # Falling back to it there (as an earlier version of this fix
            # did) would treat every requested share of a genuinely rejected
            # order as filled, inflating the ledger and withholding credit
            # for shares that never executed (Codex review: "Do not treat
            # requested quantity as a terminal fill"). But when this
            # any-state lookup instead finds the order EXPLICITLY "filled",
            # it is exactly as authoritative as the live matched_state ==
            # "filled" branch, which already falls back to "quantity" --
            # restricting this branch to cumulative_quantity alone in that
            # case silently restored the FULL claim as if nothing executed
            # whenever a filled order omitted cumulative_quantity (Codex
            # review: "Use requested quantity for any-state filled orders").
            raw_terminal_quantity = terminal_order.get("cumulative_quantity")
            if raw_terminal_quantity is None and terminal_order_state == "filled":
                raw_terminal_quantity = terminal_order.get("quantity")
            filled_shares = 0
            quantity_is_known = False
            if raw_terminal_quantity is not None:
                try:
                    filled_shares = int(float(raw_terminal_quantity))
                    quantity_is_known = True
                except (TypeError, ValueError, OverflowError):
                    # OverflowError as well: Python ints are unbounded, so a
                    # broker-supplied 10**1000 or an infinite float raises
                    # here rather than converting, and this is external data.
                    # It escaped the handler entirely -- past the placement
                    # `except` that discovered this terminal order, past this
                    # function, into the batch loop's last-resort net, which
                    # has no idea a terminal order was ever found and writes
                    # an ordinary failed row while the batch keeps placing
                    # (Codex review, PR #786: "Preserve terminal orders when
                    # quantity parsing overflows"). Caught, it lands where an
                    # unreadable figure belongs: quantity_is_known stays
                    # False, so the claim is left exactly as
                    # record_contribution wrote it, reserved for better
                    # evidence -- an unparseable fill is UNKNOWN, never zero.
                    filled_shares = 0
            if filled_shares > 0:
                # A partial fill executed before the order terminated
                # (cancelled/rejected) -- real, already-spent capital. Settle
                # it for its REAL filled quantity, using the broker's own
                # average_price when usable (mirrors
                # _reconcile_unresolved_whole_share_claim's identical
                # reasoning: a quantity-based market order can fill above or
                # below the signal-time price this candidate was planned
                # against).
                fill_price = _usable_positive_float(terminal_order.get("average_price"))
                price_for_notional = fill_price if fill_price is not None else current_share_price
                filled_notional = round(filled_shares * price_for_notional, 2)
                # Routed through `_normalized_order_id`, not a raw
                # `str(... or "")`: when the primary "id" alias is blank
                # and the fallback "order_id" is a malformed non-scalar (a
                # list or mapping), `_first_usable_order_id_alias` returns
                # that fallback unchanged, and a raw `str()` would
                # fabricate an apparently-valid id like "['BAD']" before
                # `record_buy()` below can ever validate it -- the sibling
                # filled-recovery branch above already routes through
                # `_normalized_order_id` for the identical reason (Codex
                # review, PR #1168: "Normalize partial-fill IDs before
                # stringifying").
                order_id = _normalized_order_id(_first_usable_order_id_alias(terminal_order)) or ""
                # Mirrors settle()'s OWN internal shortfall math -- the
                # claim's cached-price-priced planned notional minus the
                # REAL filled share count at the SAME cached price, never
                # the real fill price (Codex review: "Compute partial-fill
                # shortfalls from the cached share price"). See the
                # sibling "if matched_order:" branch above for the full
                # reasoning.
                settlement_shortfall_usd = round(
                    max(0.0, planned_order_notional - filled_shares * current_share_price), 2
                )
                settlement_failed = False
                resolved_by_this_call = False
                try:
                    resolved_by_this_call = ledger.settle(
                        ticker,
                        trading_day_iso,
                        filled_shares,
                        filled_notional,
                        stream=ctx.stream,
                        recorded_at=ctx.now.isoformat(),
                        idempotency_key=idempotency_key,
                        claim_token=wsa_decision.claim_token,
                        require_claim_ownership=True,
                    )
                except Exception as settle_exc:  # noqa: BLE001
                    settlement_failed = True
                    logger.error(
                        "whole-share accumulation ledger settlement failed for %s (order_id=%s) "
                        "after reconciling a partially-filled ambiguous placement: %s",
                        ticker,
                        order_id,
                        settle_exc,
                    )
                if not settlement_failed and not resolved_by_this_call:
                    # See the sibling "if matched_order:" branch above for
                    # the full reasoning (Codex review: "Skip immediate
                    # booking after losing claim ownership").
                    candidate_outcome = {
                        "status": "skipped",
                        "order_id": order_id or None,
                        "skip_reason": "whole-share: claim already resolved by a concurrent reconciler",
                        "deliberate_skip": True,
                        "reviewed_order": reviewed_order,
                        **spread_fields,
                    }
                    candidate_outcome = _publish_whole_share_outcome(candidate_outcome)
                    return (
                        candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc,
                    )
                ctx.state.record_buy(ticker, ctx.trading_day, filled_notional, order_id=order_id)
                ctx.state.own_orders_recorded.add((ticker, ctx.trading_day))
                if ctx.scheduled:
                    running_deployed_7d += filled_notional
                logger.info(
                    "Whole-share buy for %s partially filled (%d share(s)) then terminated despite a "
                    "placement error (%s); reconciled via ref_id, order_id=%s",
                    ticker,
                    filled_shares,
                    exc,
                    order_id,
                )
                try:
                    post_fire_pending_usd = ledger.pending_usd(ticker)
                except Exception as read_exc:  # noqa: BLE001
                    logger.warning(
                        "whole-share accumulation ledger read failed for %s after reconciled "
                        "partial-fill settlement: %s",
                        ticker,
                        read_exc,
                    )
                    post_fire_pending_usd = wsa_decision.pending_after_usd + (
                        0.0 if settlement_failed else settlement_shortfall_usd
                    )
                candidate_outcome = {
                    "status": "submitted",
                    "broker_placement_succeeded": True,
                    "order_id": order_id or None,
                    "skip_reason": None,
                    "reviewed_order": reviewed_order,
                    "submitted_amount_usd": filled_notional,
                    "buy_multiplier": decision.buy_multiplier,
                    "whole_share_quantity": filled_shares,
                    "whole_share_pending_usd": post_fire_pending_usd,
                    "whole_share_contribution_usd": wsa_decision.contribution_usd,
                    "whole_share_settlement_reconciliation_needed": settlement_failed,
                    "whole_share_settlement_shortfall_usd": settlement_shortfall_usd,
                    **spread_fields,
                }
                candidate_outcome = _publish_whole_share_outcome(candidate_outcome)
                if ctx.run_result is not None:
                    # terminal_order (the broker's own placement response
                    # for a WholeSharePlacementTerminalError, or the
                    # terminal-inclusive lookup's result otherwise) already
                    # carries authoritative fill evidence -- the same
                    # cumulative_quantity/average_price just used to settle
                    # this claim above. _log_execution's own default
                    # behavior re-queries broker.get_order_fill(order_id),
                    # a SEPARATE endpoint that can still be eventually
                    # consistent for the very order this response already
                    # proved landed; a clean miss there would record this
                    # proven partial fill as "submitted"/unfilled instead of
                    # "filled", corrupting filled_orders.csv, slippage, and
                    # missing-fill coverage with data this call already had
                    # (Codex review: "Log terminal-response fills without
                    # re-querying history"). Pass it directly when usable.
                    known_fill = (
                        OrderFill(avg_fill_price=fill_price, quantity_filled=float(filled_shares))
                        if fill_price is not None
                        else None
                    )
                    _log_execution(
                        ctx.run_result, decision, order_id, ctx.broker,
                        notional_usd=filled_notional, known_fill=known_fill,
                    )
                return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc
            if not quantity_is_known:
                # Terminal, but with no parseable evidence of what (if
                # anything) executed -- a cancelled/rejected/expired order
                # can still have partially executed before it terminated,
                # and an omitted quantity field proves nothing either way.
                # Falling through to the ordinary restore branch below would
                # release the FULL planned notional as if nothing executed,
                # making already-spent credit reusable (Codex review: "Keep
                # terminal claims reserved when fill quantity is absent").
                # Leave the claim exactly as record_contribution left it,
                # mirroring the still-live-order branch above.
                errors_count_inc += 1
                candidate_outcome = {
                    "status": "blocked",
                    "broker_placement_failed": True,
                    "order_id": _normalized_order_id(_first_usable_order_id_alias(terminal_order)),
                    "skip_reason": (
                        f"whole-share placement failed: {exc}; a terminal order was found but its "
                        "filled quantity is unknown; claim left reserved pending better evidence"
                    ),
                    "reviewed_order": reviewed_order,
                    "submitted_amount_usd": order_notional,
                    "whole_share_planned_notional_usd": planned_order_notional,
                    **spread_fields,
                }
                logger.warning(
                    "Whole-share placement-failure terminal-inclusive reconciliation for %s found a "
                    "terminal order (state=%s) with no parseable filled quantity; leaving claim "
                    "reserved",
                    ticker,
                    terminal_order_state,
                )
                return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc
            # A confirmed EXPLICIT zero fill: the broker definitively
            # rejected/cancelled this order before any execution. Distinct
            # from the generic "no confirmed terminal order at all" failure
            # below -- config.max_orders_per_day (circuit_breakers) is
            # defined as an ATTEMPT count where a cancelled/rejected order
            # still consumes one of the shared daily slots, matching every
            # other confirmed-terminal-order path in this module
            # (seed_prior_allocation's own "a cancelled or rejected buy
            # still consumes one" contract). Booking a zero-notional
            # record_buy here, and preserving the real broker order ID,
            # keeps this specific, PROVEN attempt counted and traceable --
            # without this, the in-memory count stayed one too low and the
            # persisted artifact had no order ID to reconstruct the missing
            # attempt from on a later run, letting later candidates place
            # beyond the configured ceiling (Codex review: "Count confirmed
            # zero-fill orders toward the attempt cap").
            zero_fill_order_id = _normalized_order_id(_first_usable_order_id_alias(terminal_order))
            errors_count_inc += 1
            # Restore and verify ownership as ONE atomic, single-locked
            # operation -- a separate still_claimed() check followed by a
            # separate preserve_pending() call is NOT atomic: the broker
            # call that raised (the exception this whole branch recovers
            # from) and the follow-up terminal-order lookup above are both
            # network round-trips during which another attempt can reclaim
            # this exact claim, so a still_claimed() pass would not
            # guarantee the FOLLOWING preserve_pending() still owns the
            # claim (Codex review: "Make zero-fill claim release atomic",
            # generalizing the prior "Confirm zero-fill restoration
            # actually won ownership" fix). Without this, record_buy(...,
            # 0.0) below would book this attempt even though nothing was
            # actually released, so the reclaiming owner's own
            # reconciliation of the SAME cancelled/rejected order
            # double-counts it against max_orders_per_day.
            try:
                resolved = ledger.preserve_pending_if_claimed(
                    ticker,
                    trading_day_iso,
                    planned_order_notional,
                    stream=ctx.stream,
                    recorded_at=ctx.now.isoformat(),
                    idempotency_key=idempotency_key,
                    claim_token=wsa_decision.claim_token,
                    # execute_claimed() durably set ``placing`` before it
                    # invoked the broker operation that raised. Require
                    # that exact marker snapshot to survive the broker
                    # reconciliation lookups above; a newer ``placed``
                    # transition must not be cleared by this stale result.
                    expected_placed=False,
                    expected_placing=True,
                )
            except Exception as restore_exc:  # noqa: BLE001 - best-effort
                # release; mirrors the generic failure branch's own
                # identical isolation below. Deliberately does NOT call
                # record_buy() when the release itself fails -- the claim
                # is STILL unresolved, so a LATER reconciliation attempt
                # (via _reconcile_unresolved_whole_share_claim, once
                # preserve_pending finally succeeds) is the one that
                # should book this attempt; booking it here TOO would
                # double-count one real cancelled/rejected order across
                # two separate calls (Codex review: "Deduplicate zero-fill
                # attempts when claim release fails"), mirroring that
                # reconciliation helper's own identical fix for the same
                # hazard.
                candidate_outcome = {
                    "status": "failed",
                    "broker_placement_failed": True,
                    "order_id": zero_fill_order_id,
                    "skip_reason": (
                        f"whole-share placement failed: {exc}; a terminal zero-fill order was "
                        f"confirmed (order_id={zero_fill_order_id}), but restoration also failed: "
                        f"{restore_exc}"
                    ),
                    "reviewed_order": reviewed_order,
                    "submitted_amount_usd": order_notional,
                    **spread_fields,
                }
                logger.error(
                    "Whole-share placement failed for %s: %s (confirmed zero-fill order_id=%s; "
                    "restoration also failed: %s)",
                    ticker,
                    exc,
                    zero_fill_order_id,
                    restore_exc,
                )
                return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc
            if not resolved:
                # Lost the claim to a newer attempt before this call, or in
                # the gap this atomic call closes -- nothing was restored,
                # so the reclaiming owner's own reconciliation of this SAME
                # broker order is the one that should book it.
                candidate_outcome = {
                    "status": "failed",
                    "broker_placement_failed": True,
                    "order_id": zero_fill_order_id,
                    "skip_reason": (
                        f"whole-share placement failed: {exc}; a terminal zero-fill order was "
                        f"confirmed (order_id={zero_fill_order_id}), but the claim was reclaimed by "
                        "a newer attempt before restoration; deferring to that attempt's own "
                        "reconciliation"
                    ),
                    "reviewed_order": reviewed_order,
                    "submitted_amount_usd": order_notional,
                    **spread_fields,
                }
                logger.warning(
                    "Whole-share placement-failure zero-fill restoration for %s lost the claim "
                    "before restoring (confirmed zero-fill order_id=%s); deferring to the "
                    "reclaiming attempt's own reconciliation",
                    ticker,
                    zero_fill_order_id,
                )
                return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc
            # NOT record_buy() here. This outcome sets `broker_placement_failed`
            # below, and `_process_buy_candidates_batch`'s one funnel already
            # charges a zero-notional `record_buy` for every candidate whose
            # outcome carries that marker -- "Charged at the batch loop's ONE
            # funnel rather than at each of the twelve sites that set the
            # marker" was the round-58 rule, and this branch was a thirteenth
            # site the sweep never reached, because it returns through a
            # different function than the ordinary fractional path. Calling it
            # here too double-charged one real broker attempt against
            # `max_orders_per_day`: measured, a single raise-then-confirmed-
            # zero-fill event consumed two slots, not one, which can skip a
            # later valid candidate near the daily cap (Codex review, PR #786:
            # "Avoid charging zero-fill whole-share attempts twice").
            candidate_outcome = {
                "status": "failed",
                "broker_placement_failed": True,
                "order_id": zero_fill_order_id,
                "skip_reason": (
                    f"whole-share placement failed: {exc}; confirmed terminal zero-fill order "
                    f"(order_id={zero_fill_order_id})"
                ),
                "reviewed_order": reviewed_order,
                "submitted_amount_usd": order_notional,
                **spread_fields,
            }
            logger.error(
                "Whole-share placement failed for %s: %s (confirmed zero-fill order_id=%s)",
                ticker,
                exc,
                zero_fill_order_id,
            )
            return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc

        errors_count_inc += 1
        try:
            ledger.preserve_pending(
                ticker,
                trading_day_iso,
                planned_order_notional,
                stream=ctx.stream,
                recorded_at=ctx.now.isoformat(),
                idempotency_key=idempotency_key,
                claim_token=wsa_decision.claim_token,
            )
        except Exception as restore_exc:  # noqa: BLE001 - the restoration
            # call itself can raise (a lock timeout, corrupt ledger, or write
            # error) here -- the same failure-isolation problem already
            # handled for _preserve_and_block's own preserve_pending call
            # above. The reconciliation lookup just above already ruled out
            # the broker having accepted this order, so restoration was safe
            # to ATTEMPT, but an unguarded call here would let this second
            # exception replace the original broker failure and escape
            # _process_buy_candidates_batch entirely -- aborting unrelated
            # candidates while this ticker gets no failed outcome at all
            # (Codex review: "Isolate restoration errors after placement
            # failures"). The claim is left exactly as record_contribution
            # left it (neither settled nor restored, since its true state
            # could not be verified).
            candidate_outcome = {
                "status": "failed",
                "broker_placement_failed": True,
                "order_id": None,
                "skip_reason": (
                    f"whole-share placement failed: {exc}; restoration also failed: {restore_exc}"
                ),
                "reviewed_order": reviewed_order,
                "submitted_amount_usd": order_notional,
                **spread_fields,
            }
            logger.error(
                "Whole-share placement failed for %s: %s (restoration also failed: %s)",
                ticker,
                exc,
                restore_exc,
            )
            return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc
        candidate_outcome = {
            "status": "failed",
            "broker_placement_failed": True,
            "order_id": None,
            "skip_reason": f"whole-share placement failed: {exc}",
            "reviewed_order": reviewed_order,
            "submitted_amount_usd": order_notional,
            **spread_fields,
        }
        logger.error("Whole-share placement failed for %s: %s", ticker, exc)
        return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc

    # place_whole_share_buy returning without raising only means the broker
    # ACCEPTED the order -- not that it is FILLED. A nonterminal state
    # (new/queued/confirmed/partially_filled) means the final executed
    # quantity is not yet known, exactly the same ambiguity the placement-
    # EXCEPTION reconciliation branch above already guards against via its
    # own "if matched_order and ... != 'filled'" check. Settling
    # unconditionally for the full REQUESTED quantity here (as this path did
    # before this fix) would mark the claim resolved before that is true: if
    # the working remainder is later cancelled or rejected, no unresolved
    # claim is left to revisit, and the ledger permanently overstates
    # purchased shares while withholding the unfilled credit forever (Codex
    # review: "Keep ordinary nonterminal submissions unresolved"). ref_id is
    # deterministic and reused verbatim for this idempotency slot, so an
    # exact-match lookup against the broker's own same-day order history
    # confirms the real state before settling.
    try:
        placed_order = ctx.broker.same_day_strategy_order_exists_with_ref_id_prefix(
            ticker, ctx.trading_day, (ref_id,)
        )
    except Exception as lookup_exc:  # noqa: BLE001 - a lookup outage here must not
        # turn an already-accepted order into a lost claim. The ledger claim
        # itself is correctly left unresolved (its true terminal state
        # genuinely could not be verified, exactly like the "not yet
        # visible"/nonterminal branch below), but reporting this candidate
        # as "blocked" -- an earlier version of this fix did -- was itself
        # misleading and had a real cost: place_whole_share_buy() ALREADY
        # returned a real, live order_id, so the broker genuinely accepted
        # and is holding this order, yet a "blocked" outcome never calls
        # record_buy()/bumps running_deployed_7d, and prior-allocation
        # loading excludes "blocked" rows entirely -- so later candidates in
        # THIS SAME batch (or a future run reconstructing the day's
        # attempts from the persisted artifact) could exceed the daily
        # attempt count, daily/weekly notional caps, or the kill switch
        # while this accepted order remains live and uncounted (Codex
        # review: "Book accepted orders when state verification raises").
        # Account for and report it exactly like the clean "not yet
        # visible"/nonterminal branch just below does.
        errors_count_inc += 1
        ctx.state.record_buy(ticker, ctx.trading_day, order_notional, order_id=order_id)
        ctx.state.own_orders_recorded.add((ticker, ctx.trading_day))
        if ctx.scheduled:
            running_deployed_7d += order_notional
        logger.error(
            "Whole-share post-placement state verification failed for %s (order_id=%s): %s; "
            "recording as submitted/unfilled and leaving the ledger claim reserved",
            ticker,
            order_id,
            lookup_exc,
        )
        candidate_outcome = {
            "status": "submitted",
            "broker_placement_succeeded": True,
            "order_id": order_id or None,
            "skip_reason": None,
            "reviewed_order": reviewed_order,
            "submitted_amount_usd": order_notional,
            "buy_multiplier": decision.buy_multiplier,
            "whole_share_quantity": quantity,
            "whole_share_pending_usd": wsa_decision.pending_after_usd,
            "whole_share_contribution_usd": wsa_decision.contribution_usd,
            "whole_share_settlement_reconciliation_needed": True,
            "whole_share_settlement_shortfall_usd": 0.0,
            **spread_fields,
        }
        candidate_outcome = _publish_whole_share_outcome(candidate_outcome)
        if ctx.run_result is not None:
            _log_execution(ctx.run_result, decision, order_id or "", ctx.broker, notional_usd=order_notional)
        return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc
    # A clean "no match" is NOT proof of anything either -- Robinhood's own
    # order-history endpoint is eventually consistent, so the just-accepted
    # order may simply not be indexed yet while still genuinely working.
    # Falling through to settle here (an earlier version of this fix did)
    # would settle the full requested quantity before that is known, the
    # exact same premature-resolution hazard the nonterminal-state branch
    # below guards against (Codex review: "Keep claims reserved when
    # accepted orders are not yet visible"). Treat "not found" identically
    # to "found but not yet filled": leave the claim reserved for a later
    # reconciliation attempt (the cross-day/same-day duplicate-check paths
    # both retry via _reconcile_unresolved_whole_share_claim) once the order
    # is actually visible and terminal.
    if not placed_order or str(placed_order.get("state", "")).lower() != "filled":
        # The broker DID accept this order -- order_id is real and live --
        # so reporting it as "blocked" (an earlier version of this fix did)
        # is itself misleading: run_result.execution_records never gets an
        # entry, submitted_orders.csv/fill-coverage reporting says nothing
        # was submitted even though real capital is genuinely committed at
        # the broker, and this contradicts the coverage setup that expects
        # an accepted-but-unfilled whole-share order to have an execution
        # record (Codex review: "Record accepted nonterminal orders as
        # submitted"). Reports "submitted" using the LOCALLY-PLANNED
        # quantity/notional (the real fill is not yet known) and books it
        # into ctx.state/running_deployed_7d exactly like a normal
        # submission -- but the whole-share LEDGER's own claim stays
        # UNRESOLVED (settle() is not called here), so a later
        # reconciliation attempt still owns confirming the real terminal
        # fill. That later settlement's own _book_reconciled_whole_share_
        # order call already checks _same_day_ticker_deployment_already_
        # recorded before booking again, using this exact submission (once
        # written to today's run artifact) to avoid double-counting.
        placed_state = str(placed_order.get("state", "")) if placed_order else "not yet visible"
        ctx.state.record_buy(ticker, ctx.trading_day, order_notional, order_id=order_id)
        ctx.state.own_orders_recorded.add((ticker, ctx.trading_day))
        if ctx.scheduled:
            running_deployed_7d += order_notional
        logger.warning(
            "Whole-share buy for %s accepted but still %s; recorded as submitted/unfilled, "
            "ledger claim left reserved until it terminates",
            ticker,
            placed_state,
        )
        candidate_outcome = {
            "status": "submitted",
            "broker_placement_succeeded": True,
            "order_id": order_id or None,
            "skip_reason": None,
            "reviewed_order": reviewed_order,
            "submitted_amount_usd": order_notional,
            "buy_multiplier": decision.buy_multiplier,
            "whole_share_quantity": quantity,
            "whole_share_pending_usd": wsa_decision.pending_after_usd,
            "whole_share_contribution_usd": wsa_decision.contribution_usd,
            "whole_share_settlement_reconciliation_needed": True,
            "whole_share_settlement_shortfall_usd": 0.0,
            **spread_fields,
        }
        candidate_outcome = _publish_whole_share_outcome(candidate_outcome)
        if ctx.run_result is not None:
            _log_execution(ctx.run_result, decision, order_id or "", ctx.broker, notional_usd=order_notional)
        return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc

    # Confirmed filled -- use the broker's own REAL executed quantity/price,
    # not the locally-planned estimate this candidate was sized against. A
    # quantity-based market order can fill at a different price than the
    # signal-time quote (or per-order-ceiling-clamped local price) used to
    # plan it, and every other reconciliation branch in this module already
    # prefers the broker's own fill data for the same reason (Codex review:
    # "Book the verified fill price on ordinary successful orders"). Falls
    # back to the locally-planned quantity/price only when the confirmed
    # order carries no usable quantity/price field at all.
    #
    # PRESENCE, not truthiness, decides which field wins: the previous
    # `... or placed_order.get("quantity")` treated an explicit
    # `cumulative_quantity: 0` the same as an ABSENT one and fell through to
    # the REQUESTED quantity, so `{"state": "filled", "cumulative_quantity":
    # 0, "quantity": 1}` -- a fill the broker explicitly reported as zero --
    # settled the ledger for a full share nothing bought (Codex review, PR
    # #786: "Reject invalid cumulative quantities before settling"). A
    # negative `cumulative_quantity` went the same wrong way: truthy, so it
    # was accepted and could reduce cap accounting once multiplied into
    # `order_notional` below. `_finite_nonnegative_float` is this module's
    # existing "usable broker figure" gate -- absent, non-numeric,
    # NaN/Infinity, and negative all read as unusable here exactly as they
    # do for a money field, and an unusable `cumulative_quantity` now falls
    # back to `quantity`'s presence rather than being silently replaced by
    # it.
    if "cumulative_quantity" in placed_order:
        raw_filled_quantity = placed_order.get("cumulative_quantity")
        filled_quantity_field_present = True
    elif "quantity" in placed_order:
        raw_filled_quantity = placed_order.get("quantity")
        filled_quantity_field_present = True
    else:
        raw_filled_quantity = None
        filled_quantity_field_present = False
    validated_filled_quantity = _finite_nonnegative_float(raw_filled_quantity)
    if validated_filled_quantity is not None:
        quantity = int(validated_filled_quantity)
    # PRESENT but unreadable/negative is a DIFFERENT answer from ABSENT, and
    # this distinction has to survive past the line above: falling back to
    # `quantity`'s presence when `cumulative_quantity` is unusable is right
    # for choosing WHICH requested field to read (round 64's fix), but it
    # then lets a broker-reported `-1` or `"unknown"` on a `state: "filled"`
    # order settle the ledger against the locally-PLANNED quantity as if it
    # were a verified fill -- `quantity` here is contradictory broker
    # evidence, not silence, and settling on a guess can misstate the ledger
    # by a real, unrecoverable amount (Codex review, PR #786: "Keep invalid
    # filled quantities unresolved").
    #
    # PRESENCE of the key, not truthiness of the raw value, decides
    # unreadability too: `raw_filled_quantity is not None` reads an explicit
    # JSON `cumulative_quantity: null` the same as an ABSENT key -- both are
    # Python `None` -- so a `state: "filled"` order supplying that exact
    # null let `quantity` keep the locally-planned estimate and settle()
    # still ran, exactly the bypass this fix exists to close (Codex review,
    # PR #786: "Treat explicit null fill quantities as unresolved").
    # `filled_quantity_field_present` was computed from the key's presence
    # in `placed_order` above and is unaffected by what its value turned out
    # to be.
    quantity_evidence_unreadable = filled_quantity_field_present and validated_filled_quantity is None
    fill_price = _usable_positive_float(placed_order.get("average_price"))
    price_for_notional = fill_price if fill_price is not None else current_share_price
    order_notional = round(quantity * price_for_notional, 2)

    # The broker has ALREADY accepted this order -- a failure past this
    # point must never make the caller believe nothing happened (Codex
    # review: "Preserve accepted orders when ledger settlement fails").
    # Mirrors the normal path's own credit_ledger.settle() call: log and
    # continue rather than raise, exactly like that call's own try/except --
    # status stays "submitted" (a real order was genuinely placed), but a
    # settle() failure here is NOT merely cosmetic the way it might look:
    # settle() is the ONLY thing that restores an unfilled shortfall back to
    # pending_usd when the per-order ceiling clamped a multi-share fire down
    # to fewer shares than record_contribution originally deducted for --
    # when settle() itself fails (a lock timeout or unwritable ledger), that
    # shortfall stays stranded, permanently understating pending_usd by
    # exactly the clamped amount, since same-day retries for this same
    # idempotency_key exit at the broker-duplicate check before ever
    # touching the claim again (a real order already exists), and the NEXT
    # trading day's dedup key never revisits it either. A bare warning log
    # was too easy to miss for a real-money discrepancy; the shortfall (if
    # any) is now computed here directly and persisted onto the outcome
    # itself so it survives into buy_candidates.csv/run_state.json for an
    # operator to reconcile by hand via this ledger's own tooling, rather
    # than existing only as a log line (Codex review: "Preserve clamped
    # shortfalls when settlement fails").
    settlement_failed = False
    settlement_shortfall_usd = 0.0
    if quantity_evidence_unreadable:
        # Never call settle() against a quantity this branch cannot trust.
        # Treated exactly like a settle() failure below -- same shortfall
        # math, same "reconciliation needed" outcome, same untouched ledger
        # claim (neither settled nor restored) -- because the failure MODE
        # is the same: the true fill could not be verified, so recording it
        # as a clean success would misstate the ledger by an amount nobody
        # can currently prove.
        settlement_failed = True
        settlement_shortfall_usd = round(
            max(0.0, planned_order_notional - quantity * current_share_price), 2
        )
        logger.error(
            "whole-share accumulation ledger settlement skipped for %s (order_id=%s): broker reported "
            "an unreadable/contradictory fill quantity (%r) on a confirmed-filled order -- claim left "
            "reserved for manual reconciliation rather than settled against an unverified estimate",
            ticker,
            order_id,
            raw_filled_quantity,
        )
    else:
        try:
            ledger.settle(
                ticker,
                trading_day_iso,
                # `quantity` was already overwritten above with the broker's own
                # CONFIRMED terminal fill quantity (cumulative_quantity/quantity
                # from the exact-ref_id-matched, state=="filled" order) -- unlike
                # the immediate get_order_fill()-based flow this replaced, there
                # is no separate, possibly-stale fill object to reconcile against
                # here; settle() itself only runs once that terminal state is
                # confirmed (Codex review comments r3804235562/r3804235574: don't
                # restore a shortfall before a terminal fill is confirmed, and
                # don't let a fallible fill lookup bypass settle() -- both closed
                # by settling only after this exact-match terminal lookup
                # succeeds, never off an unguarded get_order_fill() call).
                float(quantity),
                order_notional,
                stream=ctx.stream,
                recorded_at=ctx.now.isoformat(),
                idempotency_key=idempotency_key,
                claim_token=wsa_decision.claim_token,
            )
        except Exception as exc:  # noqa: BLE001
            settlement_failed = True
            # Mirrors settle()'s OWN internal shortfall math (and every sibling
            # branch's identical convention): the claim's cached-price-priced
            # planned notional minus the REAL filled share count, but AT THE
            # CACHED price -- never the real fill price, which would mix two
            # different prices into one shortfall figure (Codex review:
            # "Compute partial-fill shortfalls from the cached share price").
            settlement_shortfall_usd = round(
                max(0.0, planned_order_notional - quantity * current_share_price), 2
            )
            logger.error(
                "whole-share accumulation ledger settlement failed for %s (order_id=%s): %s -- "
                "$%.2f shortfall not yet restored to pending_usd; reconcile manually",
                ticker,
                order_id,
                exc,
                settlement_shortfall_usd,
            )
    ctx.state.record_buy(ticker, ctx.trading_day, order_notional, order_id=order_id)
    ctx.state.own_orders_recorded.add((ticker, ctx.trading_day))
    if ctx.scheduled:
        running_deployed_7d += order_notional
    logger.info(
        "Placed whole-share buy for %s: %d share(s), $%.2f, order_id=%s",
        ticker,
        quantity,
        order_notional,
        order_id,
    )
    # Read the AUTHORITATIVE post-settlement pending balance, not
    # wsa_decision.pending_after_usd captured before settle() ran -- a
    # per-order-ceiling clamp restores a shortfall back into pending_usd
    # during settle(), so the pre-settle snapshot can under-report what's
    # actually left in the ledger after a partial fire. Without this, a
    # successful fire that leaves a remainder (e.g. $15 pending at a $10
    # share price buys one share and carries $5 forward) recorded no
    # pending/contribution fields at all, so _build_buy_candidates wrote
    # both as None and run artifacts couldn't show the cross-day balance a
    # completed purchase actually produced (Codex review: "Persist the
    # post-fire accumulator balance"). A read failure here must not turn an
    # already-successful, already-published "submitted" outcome into an
    # error -- fall back to the pre-settle snapshot instead.
    try:
        post_fire_pending_usd = ledger.pending_usd(ticker)
    except Exception as exc:  # noqa: BLE001
        logger.warning("whole-share accumulation ledger read failed for %s after settlement: %s", ticker, exc)
        # settle() ALREADY succeeded by this point (this except is for the
        # SEPARATE pending_usd() read immediately after it) -- when it did,
        # it restored (planned_order_notional - order_notional) back into
        # pending_usd for a clamped multi-share fire, exactly like
        # settlement_shortfall_usd computes above for the settle()-failure
        # case. Falling back to the bare pre-settle wsa_decision.pending_after_usd
        # would silently discard that restoration and understate available
        # accumulated credit precisely during a transient post-settlement
        # read failure (e.g. a two-share $20 fire clamped to one $10 share
        # leaves the ledger at $10 after settlement, but this fallback would
        # report $0) (Codex review: "Preserve restored shortfalls in the
        # read-failure fallback"). When settle() itself failed instead
        # (settlement_failed), nothing was restored, so no addition is
        # correct there.
        post_fire_pending_usd = wsa_decision.pending_after_usd + (
            0.0 if settlement_failed else max(0.0, planned_order_notional - quantity * current_share_price)
        )
    candidate_outcome = {
        "status": "submitted",
        "broker_placement_succeeded": True,
        "order_id": order_id,
        "skip_reason": None,
        "reviewed_order": reviewed_order,
        "submitted_amount_usd": order_notional,
        "buy_multiplier": decision.buy_multiplier,
        "whole_share_quantity": quantity,
        "whole_share_pending_usd": post_fire_pending_usd,
        "whole_share_contribution_usd": wsa_decision.contribution_usd,
        "whole_share_settlement_reconciliation_needed": settlement_failed,
        "whole_share_settlement_shortfall_usd": settlement_shortfall_usd,
        **spread_fields,
    }
    # Publish the accepted order NOW, before the fallible follow-up below --
    # mirrors the normal path's own identical publish-before-fallible-work
    # call (Codex review: "Publish the accepted order before fill lookup").
    # The broker has ALREADY accepted this order; _log_execution's fill
    # lookup (get_order_fill) can itself raise, and the batch only records
    # an outcome once this function RETURNS, so without this a raise here
    # would leave a real, already-placed order out of the failure artifact
    # entirely.
    candidate_outcome = _publish_whole_share_outcome(candidate_outcome)
    if ctx.run_result is not None:
        # Pass the broker's own already-known fill (fill_price/quantity, both
        # already read from placed_order above to compute order_notional)
        # instead of letting _log_execution re-query broker.get_order_fill(),
        # which can be eventually consistent and miss a fill this function
        # already has authoritative evidence for -- the same "known_fill"
        # pattern used by every other reconciliation branch in this module
        # (Codex review: "Pass the verified fill into execution logging").
        # Falls back to a query (known_fill=None) only when placed_order
        # carried no usable price at all.
        known_fill = (
            OrderFill(avg_fill_price=fill_price, quantity_filled=float(quantity))
            if fill_price is not None
            else None
        )
        _log_execution(
            ctx.run_result, decision, order_id, ctx.broker, notional_usd=order_notional, known_fill=known_fill
        )
    return candidate_outcome, None, running_deployed_7d, errors_count_inc, order_reviews_attempted_inc


def _process_buy_candidate(
    decision: ReconciledDecision,
    ctx: ProcessCandidateContext,
    running_deployed_7d: float,
) -> tuple[Dict[str, Any], Optional[TopUpGuardOutcome], float, int, int]:
    ticker = decision.ticker
    # A whole-share ticker (near_close_dca.WHOLE_SHARE_TICKERS) is never
    # bought through the normal dollar-amount pipeline below -- it always
    # blocks at the is_tradable_for_fractional_buy gate further down, and
    # the top-up guard / cumulative credit ledger machinery in between was
    # never designed to interpret a quantity-based order. Route it entirely
    # separately; see docs/whole_share_accumulation.md.
    if ticker in ctx.config.whole_share_tickers:
        return _process_whole_share_candidate(decision, ctx, running_deployed_7d)
    # A ticker reaching this function solely because it carries a positive
    # pending same-day credit -- not because its own signal is a fresh BUY
    # (see _run_once_impl's flush-only injection into buy_candidates) -- has
    # suggested_amount_usd pinned to 0.0 for a non-BUY decision. Starting
    # order_amount from that would cap every later min(...) against it down
    # to 0.0, silently discarding the flush the top-up guard computes below
    # (Codex review: "Flush credits even when the final signal is not BUY").
    # Bounded by max_per_order_usd rather than left literally unconstrained:
    # the duplicate-check path below can fall back to this value as a dollar
    # amount (dup_amount = order_amount) when a matched broker order carries
    # no usable amount fields, so an unbounded sentinel (e.g. float("inf"))
    # could get durably recorded as a same-day spend figure. The kill-switch
    # cap, the guard's own incremental amount, and max_per_order_usd's own
    # hard-ceiling check all still narrow this further down.
    order_amount = (
        decision.suggested_amount_usd
        if decision.action == Action.BUY
        else ctx.config.max_per_order_usd
    )
    prior = ctx.prior_same_day_allocations.get(ticker) if ctx.guard_active else None
    ticker_guarded = ctx.guard_active and prior is not None
    top_up_outcome = None
    errors_count_inc = 0
    order_reviews_attempted_inc = 0
    candidate_outcome: Dict[str, Any] = {}
    # Initialized here (not just inside the `if ctx.guard_active:` block
    # below) so the same-stream duplicate check further down can safely
    # reference it even when this ticker has no prior allocation context at
    # all -- see that check's own comment for why (Codex review discussion
    # on commit f0b4177: "Recover duplicates for prior-less flush
    # survivors").
    existing_pending_credit_usd = 0.0

    def _block(reason: str, message: str) -> None:
        if ctx.run_result is not None:
            ctx.run_result.loop_block_reasons[ticker] = reason
        logger.info(message)

    # Computed here (before any early-return gate below) purely for context --
    # its incremental_order_amount still caps order_amount further down, but
    # its own skipped/manual_review verdict must not be honored until AFTER
    # the same-stream duplicate check just below has a chance to find and
    # preserve an order this stream already placed earlier the same run.
    if ctx.guard_active:
        effective_prior = prior
        if ticker_guarded and prior is not None and not ctx.config.dry_run:
            # KNOWN GAP fix (Codex review: "Include broker orders in the delta
            # before disabling the duplicate gate"): evaluate_top_up_guard's own
            # docstring already documents that `prior.amount_usd` is
            # artifact-derived only -- a same-day buy confirmed at the broker but
            # missing or incomplete in the artifact trail (or placed by an
            # entirely different ref-id convention, e.g. a legacy
            # morning_dca.py/midday_dca.py order for this same ticker) would
            # otherwise be invisible here, letting the guard compute a delta
            # larger than what is actually still unallocated. Cross-check
            # against the broker's own ground-truth same-day total for this
            # ticker (regardless of ref id/stream) and never trust an artifact
            # figure lower than what the broker itself reports.
            try:
                broker_reported_usd = ctx.broker.same_day_ticker_notional_usd(
                    ticker, ctx.trading_day
                )
            except Exception as exc:  # noqa: BLE001
                errors_count_inc += 1
                candidate_outcome = {
                    "status": "blocked",
                    "skip_reason": f"same-day notional check failed: {exc}",
                }
                _block(
                    MISSING_FILL_DATA_ERROR,
                    f"{ticker}: same-day notional check failed: {exc}; skipping",
                )
                return (
                    candidate_outcome,
                    top_up_outcome,
                    running_deployed_7d,
                    errors_count_inc,
                    order_reviews_attempted_inc,
                )
            if broker_reported_usd > prior.amount_usd:
                effective_prior = replace(prior, amount_usd=broker_reported_usd)
        # Read (never write) any pre-existing same-day pending credit for
        # this ticker so the final session's own contract -- flush ANY
        # positive pending balance -- is honored even when this call's own
        # decision price shows no further decline (Codex review: "Accumulate
        # credits instead of resetting pending state"). A read failure (e.g.
        # a transiently corrupt ledger file) falls back to 0.0 rather than
        # aborting this candidate: the settle() call below already durably
        # records the real outcome once placement succeeds, so a missed
        # read here only means a rare pending balance is picked up on a
        # later retry instead of this pass.
        #
        # Restricted to the afternoon stream only: evaluate_top_up_guard
        # always applies final-session (apply_cumulative_credit(...,
        # final_session=True)) discard/fold/round semantics whenever
        # existing_pending_credit_usd is positive, regardless of which
        # stream called it. Without this stream check, an ordinary 10:30/
        # 12:30 BUY candidate would discard or fold a pending remainder --
        # meant to accumulate through the whole day -- hours before the
        # actual 3:30 PM final pass (Codex review discussion on commit
        # f46f29c: "Restrict per-candidate credit resolution to the
        # afternoon").
        if ctx.stream == "afternoon":
            try:
                existing_pending_credit_usd = ctx.credit_ledger.minimum_order_pending_tickers(
                    ctx.trading_day.isoformat()
                ).get(ticker, 0.0)
            except Exception as exc:  # noqa: BLE001
                existing_pending_credit_usd = 0.0
                logger.warning(
                    "cumulative credit ledger pending-balance read failed for %s: %s", ticker, exc
                )
        else:
            existing_pending_credit_usd = 0.0
        top_up_outcome = evaluate_top_up_guard(
            decision,
            effective_prior,
            ctx.config,
            existing_pending_credit_usd=existing_pending_credit_usd,
        )
        # evaluate_top_up_guard is a pure computation (no ledger I/O). When
        # its ladder-combination branch concludes the existing remainder,
        # even combined with this call's own qualifying decline, stays below
        # the final-session discard threshold, it reports that decision here
        # rather than writing to the ledger itself. Durably reflect it now --
        # this is the only branch that can ever set this field (see
        # TopUpGuardOutcome.discarded_pending_credit_usd's docstring), so
        # this narrowly closes the gap _select_final_session_credit_flush_
        # tickers's deferral can otherwise leave open, without touching the
        # two flush-only branches' pre-existing no-ledger-write behavior
        # (Codex review discussion on commit 0af4768: "Clear combined
        # credits that remain below fifty cents").
        if top_up_outcome.discarded_pending_credit_usd is not None and ctx.config.dry_run:
            discarded = True  # simulate success; never mutate the live-root
            # ledger from a dry run -- see the matching guard and comment on
            # _select_final_session_credit_flush_tickers's discard callback
            # in _run_once_impl (Codex review discussion on commit e385a54:
            # "Keep dry runs from discarding the live credit ledger").
        elif top_up_outcome.discarded_pending_credit_usd is not None:
            try:
                discarded = ctx.credit_ledger.discard_minimum_order_pending(
                    ticker,
                    ctx.trading_day.isoformat(),
                    observed_amount_usd=existing_pending_credit_usd,
                )
            except Exception as exc:  # noqa: BLE001
                discarded = True  # do not retry on a ledger I/O failure
                logger.warning(
                    "cumulative credit ledger final discard failed for %s: %s",
                    ticker,
                    exc,
                )
            if discarded is False:
                # A concurrent update raised the ledger's CURRENT balance to
                # or above the discard threshold since existing_pending_
                # credit_usd was read above -- e.g. a scanned $0.10 plus this
                # call's own $0.10 decline computed a sub-$0.50 discard, but
                # a concurrent stream's contribution landed in between and
                # pushed the real balance to $0.50. The stale evaluation
                # above must not stand: re-read the now-larger balance and
                # re-evaluate so the now-qualifying order can actually be
                # placed instead of leaving it stranded after the final pass
                # (Codex review discussion on commit e385a54: "Route a
                # concurrently qualified discard into evaluation", mirroring
                # _select_final_session_credit_flush_tickers's equivalent
                # concurrency handling for the same scenario one level up).
                try:
                    existing_pending_credit_usd = (
                        ctx.credit_ledger.minimum_order_pending_tickers(
                            ctx.trading_day.isoformat()
                        ).get(ticker, 0.0)
                    )
                except Exception as exc:  # noqa: BLE001
                    existing_pending_credit_usd = 0.0
                    logger.warning(
                        "cumulative credit ledger pending-balance re-read failed for %s: %s",
                        ticker,
                        exc,
                    )
                top_up_outcome = evaluate_top_up_guard(
                    decision,
                    effective_prior,
                    ctx.config,
                    existing_pending_credit_usd=existing_pending_credit_usd,
                )
                if top_up_outcome.discarded_pending_credit_usd is not None:
                    # The re-evaluation ALSO came back a discard, so the
                    # concurrent update moved the balance without carrying it
                    # over the threshold ($0.20 -> $0.30, say). The ledger
                    # refused the first attempt only because that amount was
                    # not the one this call observed, and it refuses on ANY
                    # mismatch, not just a threshold-crossing one -- so the
                    # "a refusal means it now qualifies" reasoning does not
                    # cover this case, and leaving it here would strand a
                    # sub-threshold balance pending past the day's LAST pass
                    # with nothing left to resolve it (Codex review, P2:
                    # "Retry discards after sub-threshold balance changes").
                    # Retry the discard against the refreshed observation,
                    # which is the amount now under the ledger's own lock.
                    #
                    # Exactly one retry, never a loop: a further concurrent
                    # update racing THIS attempt refuses again and leaves the
                    # balance pending for out-of-band reconciliation, which is
                    # the same fail-safe outcome as before.
                    try:
                        discarded = ctx.credit_ledger.discard_minimum_order_pending(
                            ticker,
                            ctx.trading_day.isoformat(),
                            observed_amount_usd=existing_pending_credit_usd,
                        )
                    except Exception as exc:  # noqa: BLE001
                        discarded = True  # do not retry on a ledger I/O failure
                        logger.warning(
                            "cumulative credit ledger final discard retry failed for %s: %s",
                            ticker,
                            exc,
                        )
                    if discarded is False:
                        logger.warning(
                            "cumulative credit ledger final discard refused twice for %s; "
                            "leaving the balance pending for reconciliation",
                            ticker,
                        )
                # A re-evaluation that came back as an ORDER needs no second
                # discard: apply_cumulative_credit's final-session semantics
                # mean the refreshed balance now qualifies, which is exactly
                # the case the original refusal was written for.

    # A morning/manual run must NOT block the scheduled afternoon run: when the
    # top-up guard has a loaded prior allocation for this ticker, the earlier
    # same-day allocation is handled via the top-up guard below, so the
    # broker's broad same-day-order block further down is intentionally
    # bypassed here for guarded tickers. That bypass must not also blind a RETRY of
    # this same scheduled afternoon run to an order it already placed for this
    # ticker on an earlier attempt today -- prior_same_day_allocations
    # deliberately excludes this stream's own earlier same-day runs (see
    # load_prior_same_day_allocations), so nothing else would catch that case.
    # A narrower same-stream ref-id check closes that gap without reopening the
    # broad block for a legitimate cross-stream top-up.
    #
    # This runs BEFORE the top-up guard's own skip-return, the kill-switch
    # cap, and the per-order ceiling below: a retry's freshly recomputed
    # top-up math (or a freshly recomputed order_amount that happens to sit
    # above max_per_order_usd) must never suppress or overwrite evidence of an
    # order this same stream already placed earlier the same run (Codex
    # review, PR #231: "Check for an existing order before returning from the
    # top-up guard").
    #
    # Skipped entirely under config.dry_run: this whole check exists only to
    # prevent a REAL duplicate broker order, and a dry run never submits one
    # (the placement branch further down short-circuits into a simulated
    # order instead of calling the broker at all -- see "if config.dry_run"
    # below). Querying the broker's narrow duplicate lookup here anyway would
    # let a fail-closed adapter (e.g. AlpacaBroker, which now raises when it
    # cannot verify a real duplicate) block a harmless simulated candidate
    # for a risk that cannot occur in dry-run mode (Codex review, PR #231:
    # "Allow guarded Alpaca simulations through the duplicate hook").
    #
    # Also run for a credit-flush survivor with NO prior allocation entry
    # (ticker_guarded False, existing_pending_credit_usd > 0): the final-
    # session flush routes a ticker here specifically because a same-stream
    # duplicate might exist (_select_final_session_credit_flush_tickers's
    # duplicate_order_exists check), independent of whether this retry's
    # own prior-allocation artifact happened to load. Without this, that
    # ticker skips the duplicate lookup entirely -- an unsafe decision would
    # then be blocked below without ever getting a chance to recover the
    # accepted order, and a safe decision would fall through to evaluating
    # a fresh order with no duplicate check at all (Codex review discussion
    # on commit f0b4177: "Recover duplicates for prior-less flush
    # survivors").
    if (ticker_guarded or existing_pending_credit_usd > 0) and not ctx.config.dry_run:
        try:
            dup_order = _same_stream_order_exists(ctx.broker, ticker, ctx.trading_day, ctx.stream)
        except Exception as exc:  # noqa: BLE001
            errors_count_inc += 1
            candidate_outcome = {
                "status": "blocked",
                "skip_reason": f"duplicate-check failed: {exc}",
            }
            _block(
                MISSING_FILL_DATA_ERROR,
                f"{ticker}: same-stream duplicate check failed: {exc}; skipping",
            )
            return (
                candidate_outcome,
                top_up_outcome,
                running_deployed_7d,
                errors_count_inc,
                order_reviews_attempted_inc,
            )
        if dup_order is not None:
            order_id = _first_usable_order_id_alias(dup_order)
            if not order_id:
                # A legacy boolean-style adapter (True, normalized to {} by
                # _same_stream_order_exists) or a matched order dict missing
                # both id fields carries no traceable identity: recording
                # status="submitted" with a null order_id would land an
                # unidentifiable row in submitted_orders.csv that
                # reconciliation can never match to a broker fill, while
                # _log_execution can't query a fill for it either. Classify
                # it as incomplete and let a human/recovery pass resolve the
                # real order id rather than publish an untraceable
                # submission (Codex review, PR #231: "Require an order ID
                # before marking legacy duplicates submitted").
                errors_count_inc += 1
                candidate_outcome = {
                    "status": "blocked",
                    "skip_reason": "same-stream broker order exists but adapter returned no order id",
                }
                _block(
                    MISSING_FILL_DATA_ERROR,
                    f"{ticker}: same-stream duplicate found but broker returned no order id; skipping",
                )
                return (
                    candidate_outcome,
                    top_up_outcome,
                    running_deployed_7d,
                    errors_count_inc,
                    order_reviews_attempted_inc,
                )
            # Set True only when dup_amount is booked at THIS retry's current
            # max_per_order_usd because the originating order's true size
            # could not be recovered from anything the broker returned --
            # not a bound proven safe for all time, since config can be
            # lowered before a LATER run reads this same persisted figure
            # back as historical evidence. Carried onto the row (see
            # candidate_outcome/candidate_row below) so dca_risk.py's
            # evidence gate treats it as unusable there too, not just via
            # this run's in-memory force_week_notional_to_worst_case_ceiling
            # call, which stops mattering the moment this run ends (Codex
            # review: "Poison durable deployment instead of only the
            # current week").
            dup_amount_notional_uncertain = False
            try:
                dup_amount = float(
                    dup_order.get("dollar_amount") or dup_order.get("notional") or 0
                )
            except (TypeError, ValueError):
                dup_amount = 0.0
            # A matched order missing both amount fields carries no real
            # dollar figure -- fall back to this run's own freshly
            # recomputed order_amount (pre-kill-switch, pre-top-up-cap at
            # this point) rather than record a nonsensical $0 buy against
            # the ticker's daily cap. The real production broker adapter
            # always reports dollar_amount for a matched order, so this
            # fallback is not reachable there.
            if not math.isfinite(dup_amount) or dup_amount <= 0:
                # Prefer the matched order's OWN fill, exactly as the immediate
                # -recovery path does (see "Book the actual fill notional after
                # immediate recovery"): it is the real deployment, not an
                # estimate of it.
                #
                # Exact only for a SETTLED order. The same-day lookup that
                # produced this match admits `partially_filled` (see
                # dca_live_adapters._LIVE_ORDER_STATES), and a partial fill's
                # executed amount is a floor on what the order will finally
                # take, not the total -- the unfilled remainder is still live
                # and can execute at any moment. Booking the executed slice
                # alone understates daily/weekly deployment and the rolling
                # kill-switch total, and hands later candidates budget the
                # outstanding order may still consume (Codex review: "Keep
                # partially filled duplicates booked at the requested
                # notional"). _SETTLED_BROKER_ORDER_STATES draws exactly this
                # line -- see its own comment. A missing or unrecognized state
                # counts as non-terminal, the same conservative reading.
                #
                # For a SETTLED, non-filled row (canceled/expired after
                # executing some shares), cumulative_quantity is the ONLY field
                # that means "executed": `quantity` on such a row is what was
                # REQUESTED, not executed, so substituting it books a partially
                # filled cancellation at its full requested size and overstates
                # daily/weekly deployment, suppressing later candidates that
                # should still fit (Codex review discussion_r3868141054:
                # "Avoid treating requested quantity as a terminal partial
                # fill"). Only a FILLED row's plain `quantity` equals its
                # executed amount too -- the same scoping
                # _recovered_broker_notional() applies to the same fallback.
                dup_state = str(dup_order.get("state", "")).strip().lower()
                if dup_state not in _SETTLED_BROKER_ORDER_STATES:
                    dup_shares = _usable_positive_float(
                        dup_order.get("cumulative_quantity") or dup_order.get("quantity")
                    )
                else:
                    dup_shares = _usable_positive_float(
                        dup_order.get("cumulative_quantity")
                        or (dup_order.get("quantity") if dup_state == "filled" else None)
                    )
                dup_price = _usable_positive_float(dup_order.get("average_price"))
                if dup_shares is not None and dup_price is not None:
                    dup_amount = round(dup_shares * dup_price, 2)
                    if dup_state not in _SETTLED_BROKER_ORDER_STATES:
                        # A non-terminal (e.g. partially_filled) order's executed
                        # slice is a FLOOR on the original request, not the
                        # total -- but order_amount is not a reliable ceiling for
                        # it either: it is this retry's own freshly recomputed
                        # figure (an incremental top-up can be far smaller than
                        # the original full-size order that is still partially
                        # live), so a $20 original with $5 executed and a $10
                        # retry still under-records at max($5, $10) == $10 while
                        # the live remainder can still consume the full $20
                        # (Codex review: "Preserve the original notional for
                        # live partial duplicates"). Nothing durable available at
                        # this point identifies the true original size -- the
                        # broker returned no dollar_amount/notional for this
                        # match, and a same-stream duplicate bypasses the
                        # cross-stream prior-allocation scan by design (see
                        # _same_stream_order_exists's own docstring). The only
                        # figure guaranteed to be at least as large as ANY order
                        # this system could ever place is the configured
                        # absolute per-order ceiling (config/budgets.json's
                        # max_per_order_note) -- book that instead of a smaller
                        # recomputed or partially-filled figure, so an
                        # unrecoverable original notional caps later candidates
                        # too tightly rather than too loosely, the same
                        # direction every other branch here already fails
                        # closed in.
                        dup_amount = max(dup_amount, order_amount, ctx.config.max_per_order_usd)
                        # ctx.config.max_per_order_usd is still only THIS
                        # retry's own current ceiling, not proof about
                        # whatever ceiling governed the order actually
                        # placed -- config can be lowered between the
                        # original submission and this recovery retry, so a
                        # $50 original order booked here at a since-lowered
                        # $10 ceiling would leave $40 of false daily/weekly
                        # headroom for later candidates (Codex review:
                        # "Bound duplicates by the originating order
                        # ceiling"). There is no way to recover the true
                        # originating ceiling from anything the broker
                        # returned, so rather than risk under-counting real
                        # deployed capital, force the shared weekly bucket to
                        # the worst-case tier ceiling -- the same fail-closed
                        # response every other unrecoverable-historical-
                        # ceiling case in this run applies.
                        ctx.state.force_week_notional_to_worst_case_ceiling(ctx.trading_day)
                        dup_amount_notional_uncertain = True
                else:
                    # No fill detail either, so this duplicate genuinely cannot
                    # be priced from anything the broker returned. Book the
                    # retry's own order_amount and nothing smaller.
                    #
                    # The retry's freshly recomputed incremental top-up is NOT a
                    # safer figure here, in either direction. When it is zero
                    # (the top-up is now skipped entirely) min()-ing it in
                    # booked the already-placed order as a $0 buy -- the very
                    # "nonsensical $0 buy" the comment above exists to prevent
                    # (Codex review: "Preserve recovered notional when the retry
                    # delta is zero"). When it is positive but SMALLER than
                    # order_amount -- e.g. additional prior-allocation context
                    # appeared between the attempts -- min()-ing it in books the
                    # historical order at today's delta, understating
                    # StrategyState deployment, the rolling kill-switch total
                    # and the persisted candidate notional, and leaving later
                    # candidates budget the duplicate order already consumed
                    # (Codex review: "Avoid shrinking amountless duplicates to
                    # the retry delta"). Over-recording caps later candidates
                    # too tightly, which is the safe direction for an order this
                    # path cannot verify.
                    #
                    # order_amount alone is still only THIS retry's own
                    # recomputed figure, not a bound on the original order's
                    # true size -- the same gap the terminal-fill branch above
                    # closes with the configured per-order ceiling. A still-
                    # live duplicate this path cannot price at all (no
                    # dollar_amount, no cumulative_quantity/average_price
                    # either) can therefore still consume up to that ceiling
                    # even though order_amount alone under-recorded it (Codex
                    # review: "Use the order ceiling when fill detail is
                    # absent").
                    dup_amount = max(order_amount, ctx.config.max_per_order_usd)
                    # Same gap as the terminal-fill branch above (Codex
                    # review: "Bound duplicates by the originating order
                    # ceiling"): ctx.config.max_per_order_usd is only THIS
                    # retry's current ceiling, not proof about whatever
                    # ceiling governed the order actually placed. Force the
                    # shared weekly bucket closed the same way.
                    ctx.state.force_week_notional_to_worst_case_ceiling(ctx.trading_day)
                    dup_amount_notional_uncertain = True
            order_key = (ticker, ctx.trading_day)
            # A fractional-placement recovery earlier THIS SAME invocation
            # (book_reconciled_attempt_notional) already called record_buy
            # for this exact ticker/day, but marks it under a RECOVERY-
            # SPECIFIC key -- (f"{ticker}#fractional-recovery", trading_day)
            # -- deliberately never the bare order_key, so
            # _seed_prior_allocations still folds in OTHER streams'
            # cross-stream context for it (see that method's own docstring).
            # This duplicate-broker-order lookup queries the broker directly,
            # so it finds that SAME now-real order and, seeing the bare key
            # absent, called record_buy a second time for it -- doubling
            # daily/weekly notional, the attempt count, and deployment-
            # history accounting for the one broker order (Codex review,
            # PR #911 round 9: "Deduplicate fractional recoveries before
            # duplicate booking").
            recovery_key = (f"{ticker}#fractional-recovery", ctx.trading_day)
            # A recovery_key MATCH alone does not prove this broker row IS
            # the recovered order -- own_orders_recorded only ever tracked
            # ticker+day, so a genuinely DIFFERENT order for the same
            # ticker/day (a distinct top-up reference, or an afternoon
            # order after reconciling a morning claim) looked identical and
            # its own record_buy call was wrongly skipped, omitting its
            # notional/attempt from the daily/weekly breakers and
            # potentially authorizing an excess broker call (Codex review,
            # PR #911 round 18: "Compare order IDs before suppressing
            # duplicate booking"). own_recovered_order_ids resolves the
            # ambiguity: suppress only when the recovered order's own id
            # matches ONE OF THIS ticker/day's tracked ids -- there can be
            # more than one when two distinct unresolved reference groups
            # for the same ticker/day were both recovered this same run
            # (a plain placement and a later "-topup-" retry), each its
            # own broker order. Checking against only the LAST id tracked
            # let this duplicate lookup rediscover an EARLIER recovered
            # order, find its id absent from that single scalar, and read
            # it as "a genuinely different order" -- booking an
            # already-recovered order a second time (Codex review, PR
            # #911 round 25: "Track every recovered order ID per ticker
            # and day"). A recovery with no tracked id at all (an
            # older/legacy call site, or one that genuinely had none)
            # falls back to the prior, more conservative ticker+day-only
            # reading -- there is nothing here to prove they differ, so
            # treating them as the same order remains the safe default.
            #
            # `order_id` here is whatever the broker's own dup_order.get(
            # "id"/"order_id") returned -- a supported broker can report a
            # bare numeric id, not just a string -- while
            # own_recovered_order_ids stores ids the SAME way
            # _reconcile_ambiguous_fractional_placement does: `str(...).
            # strip()`. Comparing the raw value directly against that set
            # made a numeric 12345 read as absent from a set holding the
            # string "12345", so this lookup rediscovered the ALREADY-
            # recovered order, found no exact membership match, and
            # concluded it was a different order -- booking it a second
            # time and inflating attempt, notional, and kill-switch
            # accounting for one physical order (Codex review, PR #911
            # round 36: "Normalize recovered IDs before duplicate
            # comparison").
            _recovered_order_ids = ctx.state.own_recovered_order_ids.get(order_key)
            _dup_order_id_normalized = str(order_id).strip() if order_id is not None else None
            _is_recovery_own_order = recovery_key in ctx.state.own_orders_recorded and (
                not _recovered_order_ids or _dup_order_id_normalized in _recovered_order_ids
            )
            if order_key not in ctx.state.own_orders_recorded and not _is_recovery_own_order:
                ctx.state.record_buy(ticker, ctx.trading_day, dup_amount, order_id=_dup_order_id_normalized)
                ctx.state.own_orders_recorded.add(order_key)
            # else: this exact StrategyState instance already booked THIS
            # STREAM's own order for this ticker/day earlier in the SAME run
            # (e.g. an in-process retry that reuses its StrategyState rather
            # than starting a fresh one) -- recording it again here would
            # inflate today's/this week's spend and buy count, incorrectly
            # capping later candidates and overstating the persisted budget
            # audit (Codex review, PR #231: "Avoid rebooking duplicates in
            # reused strategy state"). Checked via own_orders_recorded, NOT
            # buys_today: _seed_prior_allocations also calls record_buy to
            # seed CROSS-stream (morning/midday) prior context into this
            # ticker's day/week spend, which bumps buys_today to a nonzero
            # value even on a freshly restarted process whose OWN afternoon
            # order was never booked into this state instance -- checking
            # buys_today alone would then wrongly skip recording a genuinely
            # new-to-this-state recovered order, omitting it from day/week
            # spend and letting later candidates exceed the corrected cap
            # (Codex review, PR #231: "Record the recovered buy separately
            # from seeded prior context").
            #
            # Whether this order is already counted toward the trailing-7-day
            # kill-switch figure depends on whether THIS ticker's submitted
            # order is recorded in an on-disk scheduled-afternoon artifact for
            # today: _apply_deployment_history sums deployment from disk once
            # before this batch starts, so a written artifact already reflects
            # it (adding it again here would double-count against the
            # kill-switch threshold -- Codex review, PR #231: "Do not add a
            # preserved duplicate to deployment again"). But when the prior
            # attempt was interrupted after the broker accepted the order yet
            # before it could write ITS OWN artifact for this ticker, nothing
            # on disk has ever counted this capital, and the recovered order
            # must be added so later candidates in this retry's batch (and the
            # kill-switch audit) see the real deployed total. Checked per
            # ticker, not merely "does any artifact exist for today's date":
            # a same-day artifact that doesn't itself contain THIS ticker's
            # submitted order (e.g. a zero-order artifact from an earlier,
            # unrelated invocation) must not be mistaken for proof that this
            # order was already counted (Codex review, PR #231: "Verify the
            # recovered order is actually in deployment history"). Matched
            # on THIS row's own order_id first, not merely ticker+day: a
            # ticker-only check treats ANY already-written submitted row for
            # this ticker/day as proof this specific order was counted, so
            # once an earlier recovery for a DIFFERENT order (order A) on
            # this same ticker/day was already on disk, a later invocation
            # recognizing a genuinely distinct broker order (order B, per
            # the order-ID-aware _is_recovery_own_order check above) would
            # still see the ticker/day match and skip adding B's own
            # notional here, even though B's capital was never counted on
            # disk -- under-counting the trailing-7-day kill-switch total
            # by exactly the amount that let it bypass the cap (Codex
            # review, PR #911 round 24: "Count the second recovered order
            # in deployment history"). But an order-id-only check cannot
            # match a LEGACY on-disk row recorded before order-id tracking
            # existed (no order_id field at all) -- reading that as "never
            # counted" double-counts the very order round 10's own ticker-
            # only check already existed to dedupe, so
            # _same_day_ticker_deployment_recorded_without_order_id keeps
            # that legacy fallback alive for exactly (and only) an id-less
            # row; a row that DOES carry a different order_id is real proof
            # of a distinct order, not something this fallback papers over.
            # And not when THIS broker order is the exact fractional
            # recovery `_is_recovery_own_order` above already proved it is:
            # `_run_once_impl` folds every recovered outcome's own
            # `submitted_amount_usd` into `running_deployed_7d`'s STARTING
            # baseline (`_recovered_fractional_notional`) before this batch
            # ever runs, using the identical disk-lookup this branch
            # repeats. When that recovery is absent from deployment_history_
            # root (the same reason this branch's own disk checks fail),
            # both sites add the SAME order's dollars: once into the
            # baseline, and again here for the ordinary duplicate-broker-
            # order path -- inflating running_deployed_7d for every LATER
            # candidate in this batch and risking a premature kill-switch
            # trip (Codex review, PR #911 round 30: "Avoid double-counting
            # a recovered duplicate in the kill switch").
            if (
                ctx.deployment_history_root is not None
                and not _is_recovery_own_order
                and not (
                    _same_day_order_id_already_recorded(
                        order_id, ticker, ctx.trading_day, ctx.deployment_history_root
                    )
                    or _same_day_ticker_deployment_recorded_without_order_id(
                        ticker, ctx.trading_day, ctx.deployment_history_root, dup_amount
                    )
                )
            ):
                running_deployed_7d += dup_amount
            # This row's real order was authorized by the spread gate on the
            # EARLIER attempt that actually placed it, and that original
            # evidence isn't available here without threading the prior
            # artifact's path through this call (out of scope for this
            # change). Taking a fresh retry-time quote_spread_pct and
            # recording it as an ordinary spread_ok/spread_not_ok/
            # spread_unavailable verdict would be worse than recording
            # nothing: the spread can move between the original placement and
            # this retry, and a fresh unfavorable reading would relabel an
            # already-authorized, genuinely submitted order as having failed
            # or never reached the safety gate, corrupting the historical
            # evidence config/scheduled_tasks.json's audit consumers rely on
            # (Codex review, PR #231: "Retain the original spread verdict for
            # recovered orders"). A prior attempt at this used a bespoke
            # "duplicate_recovered" status, but config/scheduled_tasks.json's
            # row_level_statuses contract enumerates exactly spread_ok,
            # spread_unavailable, spread_not_ok, and not_evaluated -- emitting
            # anything outside that declared enum breaks contract consumers
            # (Codex review, PR #231: "Keep recovered spread evidence within
            # the declared contract"). SPREAD_STATUS_NOT_EVALUATED is the
            # nearest compliant value: like this row, it commits to no
            # pass/fail verdict and per the contract's own note is "never
            # recorded as spread_ok=true" -- spread_ok/spread_pct stay None
            # rather than a fabricated True/False. duplicate_preserved=True
            # on the outcome remains the signal that this status reflects
            # missing RETRY evidence, not a row that skipped the gate outright.
            spread_fields = {
                "spread_ok": None,
                "spread_pct": None,
                "spread_status": SPREAD_STATUS_NOT_EVALUATED,
            }
            # This SAME broker order may be the one a fractional-placement
            # recovery earlier THIS invocation already booked and published
            # under its own synthetic ref_id-qualified key -- see the
            # recovery_key comment above. Publishing this row as another
            # "submitted" row too would give dca_risk.deployed_usd() (which
            # sums every "submitted" buy_candidates row without
            # deduplicating by order_id) two rows for the one order,
            # inflating a later run's trailing-seven-day kill-switch scan
            # (Codex review, PR #911 round 9: "Deduplicate fractional
            # recoveries before duplicate booking"). "skipped" is a
            # schema-valid status that keeps every other field (order_id,
            # submitted_amount_usd, duplicate_preserved) for audit purposes
            # without counting a second time. Reuses the SAME order-id-aware
            # `_is_recovery_own_order` computed above the booking gate --
            # nothing between there and here can change whether this broker
            # row is the recovered order, so recomputing it here added
            # nothing but a second (and, before this fix, less precise)
            # copy of the same check.
            candidate_outcome = {
                "status": "skipped" if _is_recovery_own_order else "submitted",
                "order_id": order_id,
                "skip_reason": (
                    "already recorded this run by fractional-placement recovery"
                    if _is_recovery_own_order
                    else "same-stream broker order exists"
                ),
                "submitted_amount_usd": dup_amount,
                # True only when dup_amount above is a fail-closed ceiling
                # estimate, not the broker's own real figure -- see its
                # own comment. Copied onto the persisted row by
                # _build_buy_candidates so dca_risk.py's evidence gate
                # keeps treating this figure as unusable evidence even
                # after this run's own in-memory
                # force_week_notional_to_worst_case_ceiling stops applying
                # (Codex review: "Poison durable deployment instead of
                # only the current week").
                "deployed_notional_uncertain": dup_amount_notional_uncertain,
                # Carried on the outcome so a failure handler synthesizing a
                # buy_candidates row from this outcome alone (see
                # _publish_in_flight_outcome / _failure_candidate_row) can
                # still record the real multiplier, matching the fresh-
                # placement branch below.
                "buy_multiplier": decision.buy_multiplier,
                # Preserves the real broker order rather than a fresh placement,
                # so a caller booking this candidate into a persistent ledger
                # must not double-count it against an earlier attempt's record,
                # and so _build_buy_candidates keeps this amount instead of
                # clamping it against THIS retry's freshly recomputed
                # incremental_order_amount (Codex review, PR #231: "Keep the
                # broker notional when rebuilding duplicate artifacts").
                "duplicate_preserved": True,
                # Same aggregate-topup audit contract as the fresh-placement
                # branch below: if THIS retry's own evaluate_top_up_guard
                # call (above, before the duplicate check) shows the
                # aggregate rule applied, the recovered real order deserves
                # the same audit fields a fresh placement would carry --
                # otherwise a crash-recovered aggregate order silently
                # serializes aggregate_minimum_topup_applied=false forever
                # (Codex review discussion on commit 8720cec: "Reconcile
                # aggregate credits on duplicate recovery").
                **(
                    {
                        "aggregate_minimum_topup_applied": True,
                        "aggregate_minimum_topup_remainder_usd": existing_pending_credit_usd,
                        "aggregate_minimum_topup_order_usd": dup_amount,
                        "aggregate_minimum_topup_reason": (
                            "aggregate_at_or_above_minimum"
                            if round(
                                existing_pending_credit_usd
                                + top_up_outcome.cumulative_credit_decline_usd,
                                2,
                            )
                            >= 1.0
                            else "aggregate_rounded_up_to_minimum"
                        ),
                    }
                    if top_up_outcome is not None
                    and top_up_outcome.cumulative_credit_decline_usd is not None
                    and existing_pending_credit_usd > 0
                    else {}
                ),
                **spread_fields,
            }
            # Settle the credit ledger for the SAME reason the fresh-
            # placement branch below does: the earlier attempt that actually
            # placed this order crashed before it could settle its own
            # credit-ledger write, so this recovery is the only chance to
            # durably clear it -- otherwise the remainder is left stranded
            # even though the real order it was rolled into already exists
            # at the broker.
            if top_up_outcome is not None and top_up_outcome.cumulative_credit_decline_usd is not None:
                try:
                    ctx.credit_ledger.settle(
                        ticker,
                        ctx.trading_day.isoformat(),
                        dup_amount,
                        stream=ctx.stream,
                        # THE case settle()'s order-id dedup exists for: the
                        # earlier attempt may have settled this very order
                        # before dying, and settling it again would subtract
                        # its notional from the pending balance a second time.
                        order_id=candidate_outcome.get("order_id"),
                    )
                except Exception as exc:  # noqa: BLE001
                    logger.warning(
                        "cumulative credit ledger settlement failed for %s: %s", ticker, exc
                    )
            _publish_in_flight_outcome(ticker, candidate_outcome)
            logger.info(
                "%s: same-stream broker order already exists; not re-submitting (order_id=%s)",
                ticker,
                candidate_outcome.get("order_id"),
            )
            if ctx.run_result is not None and not any(
                r.order_id == candidate_outcome.get("order_id")
                for r in ctx.run_result.execution_records
            ):
                # Log this the same way as a fresh placement (not via _block):
                # this ticker's order was actually submitted, so it must appear
                # in execution_records for the slippage/coverage report, and
                # any missing-fill classification must come from the real fill
                # status (_log_execution only classifies MISSING_FILL_EXECUTION_GAP
                # when the order truly has no fill) rather than a hardcoded
                # "budget capped" reason that would misreport a submitted order.
                #
                # Skipped entirely when this order_id is ALREADY in
                # execution_records: the crash-lease recovery-publish loop
                # (near_close_dca._run_once_impl, earlier in the same run)
                # can have already appended an execution record for this
                # exact order when its ticker also remains a current buy
                # candidate that this same-stream-duplicate check then
                # recognizes as the SAME broker order. Logging it again here
                # left two execution records with the same order_id --
                # _merge_execution_csv does not deduplicate within its own
                # incoming batch -- double-counting one execution in
                # orders.csv, filled-order counts, and filled notional
                # (Codex review: "Deduplicate recovered execution records by
                # order ID").
                _log_execution(
                    ctx.run_result,
                    decision,
                    candidate_outcome.get("order_id"),
                    ctx.broker,
                    notional_usd=dup_amount,
                )
            return (
                candidate_outcome,
                top_up_outcome,
                running_deployed_7d,
                errors_count_inc,
                order_reviews_attempted_inc,
            )

    # No same-stream duplicate was found above: everything from here on can
    # place a genuinely NEW broker order. An ordinary buy_candidates entry is
    # always Action.BUY (upstream confidence checks already enforced that),
    # but a ticker reaching this function via the final-session credit
    # flush's duplicate-recovery survivor path (Codex review discussion on
    # commit be6b992: "Recover duplicates before filtering unsafe flush
    # signals") can carry a MANUAL_REVIEW/NO_DATA decision -- injected
    # specifically to let a CONFIRMED duplicate be recovered, not to
    # authorize a fresh order from a provider error or Finance/Robinhood
    # disagreement. _run_once_impl's injection loop no longer filters these
    # out itself (that would also block the duplicate-recovery return path
    # above), so this is the one remaining place that must refuse to place a
    # new order once no duplicate has actually been confirmed -- the same
    # policy _is_flush_safe_decision originally enforced, just applied after
    # duplicate recovery gets its chance instead of before it.
    if not _is_flush_safe_decision(decision):
        candidate_outcome = {
            "status": "blocked",
            "skip_reason": "unreliable decision (manual review/no data); no duplicate order found to recover",
            "deliberate_skip": True,
        }
        _block(
            MISSING_FILL_DATA_ERROR,
            f"{ticker}: unreliable decision and no recoverable duplicate order; skipping",
        )
        return (
            candidate_outcome,
            top_up_outcome,
            running_deployed_7d,
            errors_count_inc,
            order_reviews_attempted_inc,
        )

    if kill_switch_engaged(replace(ctx.config, deployed_last_7d_usd=running_deployed_7d)):
        # Cap at THIS candidate's own selected base ($1 or $2), not the fixed
        # config.base_buy_amount_usd ($2) -- a below-close-only candidate's 1x
        # kill-switch amount is $1, and capping it at $2 would let it submit
        # double the reduced-scale risk cap the kill switch is meant to enforce
        # (Codex review: "Cap the kill switch at the selected base"). When an
        # earlier same-day allocation already fixed this ticker's base for the
        # day (see resolve_top_up_desired_amount_usd), the kill-switch ceiling
        # must use THAT preserved base, not this run's own freshly recomputed
        # decision.selected_base_amount_usd -- a deeper price that newly
        # crosses the prior regular-session low can raise this run's own base
        # from $1 to $2 for a ticker whose day is still pinned to the $1
        # scale, and capping at the fresh $2 would let a guarded top-up submit
        # double the reduced-scale risk the kill switch is meant to enforce
        # for that ticker (Codex review: "Cap guarded top-ups using the
        # preserved base").
        kill_switch_base = (
            prior.selected_base_amount_usd
            if prior is not None
            and prior.selected_base_amount_usd
            and prior.selected_base_amount_usd > 0
            else decision.selected_base_amount_usd
        )
        order_amount = min(order_amount, kill_switch_base)
        # A credit-only flush candidate (no prior context, non-BUY decision
        # with selected_base_amount_usd == 0 -- see the "no prior" branch's
        # ReconciledDecision, which was never assigned a base) clamps to
        # exactly $0 here rather than a reduced-but-positive amount, since
        # there is no base to fall back to at all. Nothing downstream checks
        # for a non-positive order_amount before place_market_buy, so this
        # would otherwise submit a genuine $0 broker order while the
        # qualifying credit's settle() call clears nothing (pending_after =
        # pending_before - 0), silently stranding it as though the final
        # pass had already resolved it (Codex review discussion on commit
        # db6ef02: "Keep recovered-price flushes above the kill-switch
        # floor"). Block explicitly instead, leaving the ledger balance
        # untouched for a later day's pass to resolve, rather than either
        # placing a bad order or raising the kill switch's own cap to let a
        # credit-only flush bypass the risk limit it exists to enforce.
        if order_amount <= 0:
            candidate_outcome = {
                "status": "blocked",
                "skip_reason": "kill switch engaged; no positive base to cap a credit-only flush",
                "deliberate_skip": True,
                "budget_blocked": True,
            }
            _block(
                MISSING_FILL_BUDGET_CAPPED,
                f"{ticker}: kill switch engaged with no positive base for this candidate; skipping",
            )
            return (
                candidate_outcome,
                top_up_outcome,
                running_deployed_7d,
                errors_count_inc,
                order_reviews_attempted_inc,
            )

    if ctx.guard_active and top_up_outcome is not None:
        order_amount = min(top_up_outcome.incremental_order_amount, order_amount)
        if top_up_outcome.skipped:
            candidate_outcome = {
                "status": "skipped",
                "order_id": None,
                "skip_reason": top_up_outcome.top_up_guard_result,
            }
            if top_up_outcome.manual_review:
                logger.warning(
                    "%s: prior same-day amount $%.2f but no comparable price; "
                    "conservative $0 top-up, manual review required",
                    ticker,
                    top_up_outcome.prior_same_day_amount,
                )
            _block(
                MISSING_FILL_TOP_UP_OFFSET,
                f"{ticker}: top-up guard offset ({top_up_outcome.top_up_guard_result}); no incremental buy",
            )
            return (
                candidate_outcome,
                top_up_outcome,
                running_deployed_7d,
                errors_count_inc,
                order_reviews_attempted_inc,
            )

    # Hard per-order ceiling is checked before any broker round-trip -- including
    # the one_order_per_ticker_per_day duplicate check just below -- so that an
    # over-cap candidate never needs a same-day-duplicate lookup or a spread
    # quote. Moving this ahead of the roster's broad broker check keeps the
    # existing cap-before-duplicate contract (see
    # test_run_daily_compact_checks_per_order_cap_before_broker_duplicate_lookup)
    # intact now that one_order_per_ticker_per_day also triggers a broker
    # round-trip on this path (Codex review, discussion_r3679633773: "Check the
    # hard ceiling before the broker duplicate lookup").
    if order_amount > ctx.config.max_per_order_usd:
        candidate_outcome = {
            "status": "blocked",
            "skip_reason": "max per-order ceiling exceeded",
            "deliberate_skip": True,
            "budget_blocked": True,
        }
        _block(
            MISSING_FILL_BUDGET_CAPPED,
            f"{ticker}: order amount ${order_amount:.2f} exceeds max per-order "
            f"${ctx.config.max_per_order_usd:.2f}; skipping",
        )
        return (
            candidate_outcome,
            top_up_outcome,
            running_deployed_7d,
            errors_count_inc,
            order_reviews_attempted_inc,
        )
    if ctx.config.one_order_per_ticker_per_day and ctx.broker.same_day_strategy_order_exists(
        ticker, ctx.trading_day
    ):
        if top_up_outcome is not None:
            top_up_outcome = replace(top_up_outcome, incremental_order_amount=0.0)
        candidate_outcome = {
            "status": "skipped",
            "skip_reason": "same-day broker order exists",
        }
        _block(
            MISSING_FILL_BUDGET_CAPPED,
            f"{ticker}: same-day broker order already exists; skipping",
        )
        return (
            candidate_outcome,
            top_up_outcome,
            running_deployed_7d,
            errors_count_inc,
            order_reviews_attempted_inc,
        )
    if (ctx.config.one_order_per_ticker_per_day or not ticker_guarded) and (
        ctx.state.buys_today(ticker, ctx.trading_day) >= ctx.config.max_buys_per_ticker_per_day
    ):
        # Zero the top-up guard's incremental amount the same way the broker
        # duplicate check above does: this candidate is being skipped, so a
        # downstream reader of top_up_outcome (_build_buy_candidates) must not
        # still see a nonzero incremental_order_amount for a row whose status is
        # "skipped" (Antigravity review: "Inconsistent top_up_outcome zeroing
        # when one_order_per_ticker_per_day triggers").
        if top_up_outcome is not None:
            top_up_outcome = replace(top_up_outcome, incremental_order_amount=0.0)
        candidate_outcome = {
            "status": "skipped",
            "skip_reason": "already bought today",
            "budget_blocked": True,
        }
        _block(MISSING_FILL_BUDGET_CAPPED, f"{ticker}: already bought today; skipping")
        return (
            candidate_outcome,
            top_up_outcome,
            running_deployed_7d,
            errors_count_inc,
            order_reviews_attempted_inc,
        )
    # A morning/manual run must NOT block the scheduled afternoon run: when the
    # top-up guard has a loaded prior allocation for this ticker, the earlier
    # same-day allocation is handled above (and any same-stream retry of THIS
    # ticker was already caught by the duplicate check at the top of this
    # function), so the broker's broad same-day-order block is intentionally
    # bypassed here for guarded tickers -- a legitimate cross-stream top-up
    # must not be blocked by the morning stream's own earlier order. When the
    # roster's one-order-per-day policy is enabled, the unconditional broker
    # check above already enforced the broader rule, so do not query it twice.
    if (
        not ctx.config.one_order_per_ticker_per_day
        and not ticker_guarded
        and ctx.broker.same_day_strategy_order_exists(ticker, ctx.trading_day)
    ):
        candidate_outcome = {
            "status": "skipped",
            "skip_reason": "same-day broker order exists",
        }
        _block(
            MISSING_FILL_BUDGET_CAPPED,
            f"{ticker}: same-day broker order already exists; skipping",
        )
        return (
            candidate_outcome,
            top_up_outcome,
            running_deployed_7d,
            errors_count_inc,
            order_reviews_attempted_inc,
        )
    # Budget/cap checks run BEFORE the spread lookup, matching the per-order
    # ceiling above ("an over-cap candidate should never need a same-day-duplicate
    # lookup or a spread quote") and the blocked_before_spread_gate contract: a
    # cap-blocked candidate carries NO spread verdict, so a run stopped only by
    # caps is never misreported as missing_spread_data (Codex review).
    if not within_caps(order_amount, ctx.state, ctx.trading_day, ctx.config):
        candidate_outcome = {
            "status": "blocked",
            "skip_reason": "cap would be exceeded",
            "deliberate_skip": True,
            "budget_blocked": True,
        }
        _block(MISSING_FILL_BUDGET_CAPPED, f"{ticker}: cap would be exceeded; skipping")
        return (
            candidate_outcome,
            top_up_outcome,
            running_deployed_7d,
            errors_count_inc,
            order_reviews_attempted_inc,
        )

    # This candidate qualified on the ladder and top-up rules, so it reaches the
    # spread gate. Only rows that get this far carry a spread verdict, and only
    # they can be counted as blocked for want of a proven spread
    # (config/scheduled_tasks.json:spread_data_availability_policy.evaluation_order).
    try:
        spread_pct = quote_spread_pct(ctx.robinhood_data, ticker, ctx.now)
    except Exception as exc:  # noqa: BLE001
        errors_count_inc += 1
        candidate_outcome = {
            "status": "blocked",
            "skip_reason": f"spread quote error: {exc}",
            **spread_gate_fields(
                spread_pct=None, max_spread_pct=ctx.config.max_bid_ask_spread_pct
            ),
        }
        _block(
            MISSING_FILL_DATA_ERROR, f"{ticker}: spread quote failed: {exc}; skipping"
        )
        return (
            candidate_outcome,
            top_up_outcome,
            running_deployed_7d,
            errors_count_inc,
            order_reviews_attempted_inc,
        )
    spread_fields = spread_gate_fields(
        spread_pct=spread_pct, max_spread_pct=ctx.config.max_bid_ask_spread_pct
    )
    if spread_pct is None and ctx.scheduled:
        # config/scheduled_tasks.json requires spread_ok=true before any
        # scheduled live order: a provider without bid/ask support, or a
        # quote lookup that returned nothing, must fail closed here
        # rather than silently bypass the breaker. Manual runs still go
        # through review_market_buy as a human-reviewed safety net, so
        # they are not blocked on a missing spread alone.
        candidate_outcome = {
            "status": "blocked",
            "skip_reason": "bid/ask spread unavailable; scheduled runs require spread_ok",
            "deliberate_skip": True,
            # The spread gate itself stopped this row, recorded explicitly rather
            # than inferred from spread_status (Codex review).
            "blocked_by": BLOCKED_BY_SPREAD_GATE,
            **spread_fields,
        }
        _block(
            MISSING_FILL_BROKER_BLOCKED,
            f"{ticker}: bid/ask spread unavailable for scheduled run; skipping",
        )
        return (
            candidate_outcome,
            top_up_outcome,
            running_deployed_7d,
            errors_count_inc,
            order_reviews_attempted_inc,
        )
    if spread_pct is not None and spread_pct > ctx.config.max_bid_ask_spread_pct:
        candidate_outcome = {
            "status": "blocked",
            "skip_reason": (
                f"bid/ask spread {spread_pct:.2f}% exceeds "
                f"{ctx.config.max_bid_ask_spread_pct:.2f}% limit"
            ),
            "deliberate_skip": True,
            **spread_fields,
        }
        _block(
            MISSING_FILL_BROKER_BLOCKED,
            f"{ticker}: bid/ask spread {spread_pct:.2f}% exceeds "
            f"{ctx.config.max_bid_ask_spread_pct:.2f}% limit; skipping",
        )
        return (
            candidate_outcome,
            top_up_outcome,
            running_deployed_7d,
            errors_count_inc,
            order_reviews_attempted_inc,
        )
    if ctx.broker.available_buying_power() < order_amount:
        candidate_outcome = {
            "status": "blocked",
            "skip_reason": "insufficient buying power",
            "deliberate_skip": True,
            "budget_blocked": True,
            **spread_fields,
        }
        _block(
            MISSING_FILL_BUDGET_CAPPED, f"{ticker}: insufficient buying power; skipping"
        )
        return (
            candidate_outcome,
            top_up_outcome,
            running_deployed_7d,
            errors_count_inc,
            order_reviews_attempted_inc,
        )
    if not ctx.broker.is_tradable_for_fractional_buy(ticker):
        candidate_outcome = {
            "status": "blocked",
            "skip_reason": "not tradable for fractional buy",
            "deliberate_skip": True,
            **spread_fields,
        }
        _block(
            MISSING_FILL_BROKER_BLOCKED,
            f"{ticker}: not tradable for fractional/notional buy; skipping",
        )
        return (
            candidate_outcome,
            top_up_outcome,
            running_deployed_7d,
            errors_count_inc,
            order_reviews_attempted_inc,
        )

    reviewed_order = None
    if not ctx.scheduled:
        order_reviews_attempted_inc += 1
        review_ok, review_reason = ctx.broker.review_market_buy(ticker, order_amount)
        if not review_ok:
            candidate_outcome = {
                "status": "blocked",
                "skip_reason": f"review blocked: {review_reason}",
                "deliberate_skip": True,
                **spread_fields,
            }
            _block(
                MISSING_FILL_BROKER_BLOCKED,
                f"{ticker}: review blocked order: {review_reason}",
            )
            return (
                candidate_outcome,
                top_up_outcome,
                running_deployed_7d,
                errors_count_inc,
                order_reviews_attempted_inc,
            )
        reviewed_order = {
            "notional_usd": round(order_amount, 2),
            "side": "buy",
            "order_type": "market",
            "time_in_force": None,
            "estimated_price": None,
            "review_passed": True,
        }

    # A manual (non-scheduled) placement gets its own "-manual-" ref-id
    # segment, distinct from a plain scheduled order's ref_id. guard_active
    # (and so ticker_guarded) is only ever True for scheduled runs, so a
    # manual placement always falls to this branch. Without a distinct
    # segment a manual fill's ref_id would be indistinguishable from a plain
    # scheduled order's, so a LATER scheduled run that finds this manual fill
    # as cross-stream prior context and computes a guarded top-up would have
    # its same-stream duplicate check match the manual fill's ordinary ref_id
    # and wrongly treat the fresh incremental top-up as an already-submitted
    # retry -- recording it as "submitted" without ever calling
    # place_market_buy (Codex review, PR #231: "Separate manual ref IDs from
    # scheduled retry IDs"; mirrors morning_dca.py's identical fix, PR #42).
    # A synthetic inverse-Martingale fire candidate (decision.synthetic_source
    # == "inverse_martingale") gets its own "-imart-" segment so it is
    # distinguishable in the order history / same-stream duplicate checks from
    # an ordinary ladder buy for the same ticker/day. The injection site
    # (_run_once_impl) never lets a guarded ticker (one with a prior same-day
    # allocation) reach this function as a fire candidate, so this branch and
    # the "topup" branch above it are mutually exclusive in practice; the
    # ordering here still puts "topup" first so a future caller that violated
    # that invariant would fail toward the more conservative, already
    # extensively reviewed top-up ref-id convention rather than the newer one.
    ref_id = (
        f"{_graded_dca_ref_id_prefix(ctx.stream, 'topup')}-{ctx.trading_day.isoformat()}-{ticker}"
        if ticker_guarded
        else (
            f"{_graded_dca_ref_id_prefix(ctx.stream, 'imart')}-{ctx.trading_day.isoformat()}-{ticker}"
            if decision.synthetic_source == "inverse_martingale"
            else (
            f"{_graded_dca_ref_id_prefix(ctx.stream)}-{ctx.trading_day.isoformat()}-{ticker}"
            if ctx.scheduled
            else f"{_graded_dca_ref_id_prefix(ctx.stream, 'manual')}-{ctx.trading_day.isoformat()}-{ticker}"
            )
        )
    )
    if ctx.config.dry_run:
        logger.info(
            "[DRY RUN] Would buy %s: $%.2f (%s)",
            ticker,
            order_amount,
            decision.reason,
        )
        if isinstance(ctx.broker, DryRunBroker):
            order_id = ctx.broker.place_market_buy(ticker, order_amount, ref_id=ref_id)
        else:
            order_id = f"DRY-RUN-SIM-{ticker}-{order_amount:.2f}-{ref_id}"
        candidate_outcome = {
            "status": "dry_run",
            "order_id": order_id,
            "skip_reason": "dry_run: order not placed",
            "reviewed_order": reviewed_order,
            "submitted_amount_usd": order_amount,
            **spread_fields,
        }
    else:
        try:
            order_id = ctx.broker.place_market_buy(ticker, order_amount, ref_id=ref_id)
        except OrderConfirmationRequiredError:
            candidate_outcome = {
                "status": "not_submitted_confirmation_required",
                "order_id": None,
                "skip_reason": "broker requires post-review confirmation before submission",
                "reviewed_order": reviewed_order,
                "submitted_amount_usd": order_amount,
                # A REAL broker placement call that did not result in an order.
                # See the "broker_placement_failed" note on the branch below:
                # the consecutive-failure breaker counts broker-facing
                # failures, and a broker refusing every direct submission is
                # exactly the systemic condition it exists to stop (Codex
                # review, PR #786: "Count confirmation-required placement
                # failures").
                "broker_placement_failed": True,
                **spread_fields,
            }
            _block(
                MISSING_FILL_BROKER_BLOCKED,
                f"{ticker}: broker requires confirmation before submission; skipping",
            )
            return (
                candidate_outcome,
                top_up_outcome,
                running_deployed_7d,
                errors_count_inc,
                order_reviews_attempted_inc,
            )
        except Exception as exc:  # noqa: BLE001
            # A raise here does not prove the broker created nothing. The
            # adapter raises the same plain RuntimeError for an outright
            # refusal and for a connector that died while returning an
            # acceptance, and in the second case the order is live while this
            # run has no record of it -- absent from candidate_outcomes,
            # deployment totals, buying-power arithmetic and every later
            # candidate's cap check. So the exact ref_id is reconciled against
            # the day's order history before this is called a failure.
            if isinstance(exc, FractionalPlacementRejectedError):
                # The placement response itself is authoritative terminal
                # evidence. Do not turn an ordinary refusal back into an
                # unresolved outcome merely because eventually-consistent
                # order history has not indexed a rejection row.
                #
                # Its id rides along on the FAILED row, exactly as the
                # reconciler's own no-order verdict carries one: the response
                # named the order it refused, and this path skips history, so
                # discarding the id would leave the artifact with no way to
                # look that order up by hand. Validated the same way the
                # reconciler validates a history row's id, so an unusable
                # shape is not recorded as though it were trackable.
                _rejected_id = getattr(exc, "order_id", None)
                verdict = _PLACEMENT_NO_ORDER
                reconciled_order_id = (
                    str(_rejected_id).strip()
                    if _is_usable_reconciled_order_id(_rejected_id)
                    else None
                )
                history_readable = True
            else:
                try:
                    verdict, reconciled_order_id, _ = _reconcile_ambiguous_fractional_placement(
                        ctx,
                        ticker,
                        ref_id,
                        order_amount,
                        response_notional_usd=getattr(exc, "response_notional_usd", None),
                        response_may_have_executed=bool(
                            getattr(exc, "response_may_have_executed", False)
                        ),
                    )
                    history_readable = True
                except Exception as reconcile_exc:  # noqa: BLE001
                    # The history itself could not be read, so nothing was learned
                    # -- distinct from reading it and finding nothing. Isolation is
                    # still what the batch's last-resort net does with a raise from
                    # here, so re-raising would change nothing; what this DOES
                    # change is that the row says so, and errors_count -> the run's
                    # manual_recovery_required flag is set below either way.
                    logger.error(
                        "Could not reconcile ambiguous placement for %s (%s): %s",
                        ticker,
                        ref_id,
                        type(reconcile_exc).__name__,
                    )
                    verdict, reconciled_order_id = _PLACEMENT_UNKNOWN, None
                    history_readable = False
            if isinstance(exc, AmbiguousPlacementResponseError):
                _response_order_id = getattr(exc, "order_id", None)
                _response_order_id = (
                    str(_response_order_id).strip()
                    if _is_usable_reconciled_order_id(_response_order_id)
                    else None
                )
                if reconciled_order_id is None:
                    # History could not name the order; the response that
                    # raised already did. Carried only as an identifier --
                    # the verdict above is untouched, so an unproven
                    # outcome stays unproven.
                    reconciled_order_id = _response_order_id
                elif _response_order_id is not None and reconciled_order_id != _response_order_id:
                    # History matched a DIFFERENT usable id than the one
                    # THIS EXACT placement call's own response reported --
                    # and that response's order already carried positive-
                    # or-unreadable fill evidence, exactly why
                    # AmbiguousPlacementResponseError was raised instead of
                    # a proven rejection. Trusting either verdict here -- an
                    # ACCEPTED history row that books and continues, or a
                    # NO_ORDER one that writes the response's own order off
                    # as never placed -- silently discards whichever of the
                    # two ids this outcome does NOT keep, from
                    # reconciliation and cap accounting entirely (Codex
                    # review, PR #911 round 27: "Keep mismatched response
                    # and history IDs unresolved"). Neither id is
                    # trustworthy alone here, so the verdict is forced back
                    # to unresolved rather than picking one -- deliberately
                    # not gated on the verdict already being something
                    # other than UNKNOWN: reconciliation can itself return
                    # `_PLACEMENT_UNKNOWN` directly (an unrecognized state,
                    # a recovered-amount conflict) carrying a usable id
                    # that still disagrees with the response's own, and an
                    # `and verdict != _PLACEMENT_UNKNOWN` guard here used to
                    # skip this branch in exactly that case, leaving
                    # `reconciled_order_id` at the untrustworthy history id
                    # while the response's own id -- which the adapter
                    # never appends to raw placement history at all --
                    # disappeared from durable recovery evidence entirely
                    # (Codex review, PR #859 round 39: "Preserve both IDs
                    # when reconciliation disagrees"). Setting `verdict =
                    # _PLACEMENT_UNKNOWN` when it is already that value is
                    # simply a no-op.
                    #
                    # `reconciled_order_id` is switched to RESPONSE-ID here
                    # too, not just downgrading the verdict: this value is
                    # what gets PERSISTED as the outcome's own `order_id` a
                    # few lines down, and leaving it at the untrustworthy
                    # HISTORY-ID broke the ONE mechanism that could ever
                    # catch this disagreement again -- a LATER retry's own
                    # persisted-id conflict check (Codex review, PR #911
                    # round 33: "Preserve conflicts with persisted
                    # response order IDs") only flags a conflict when the
                    # PERSISTED id disagrees with what a fresh lookup
                    # reports THEN. If history is self-consistent across
                    # retries -- the ordinary case -- persisting HISTORY-ID
                    # here made that later lookup return the SAME id this
                    # call already found, so the round-33 check saw no
                    # disagreement and treated the row as cleanly
                    # resolved, silently dropping RESPONSE-ID -- the id
                    # THIS EXACT placement call's own response reported,
                    # and which never got a chance to be reconciled at all
                    # -- from cap accounting for good (Codex review, PR
                    # #911 round 38: "Preserve both IDs when response and
                    # history disagree"). Persisting RESPONSE-ID instead
                    # keeps the round-33 check comparing against the
                    # correct anchor: a later retry's fresh HISTORY-ID
                    # lookup still disagrees with the persisted
                    # RESPONSE-ID, so the conflict keeps getting caught on
                    # every subsequent retry until a human resolves it,
                    # rather than the row self-healing the moment history
                    # settles on one value.
                    verdict = _PLACEMENT_UNKNOWN
                    reconciled_order_id = _response_order_id
                elif verdict in (_PLACEMENT_ACCEPTED, _PLACEMENT_NO_ORDER) and getattr(
                    exc, "structurally_ambiguous", False
                ):
                    # The response itself named TWO OR MORE disagreeing
                    # identities (e.g. `{"id": "A", "order_id": "B"}`), and
                    # `AmbiguousPlacementResponseError.order_id` can only
                    # ever carry ONE of them -- here, the one this exact
                    # ref_id lookup happened to match. A match on THIS id
                    # proves only that THIS id is real; it says nothing
                    # about the OTHER, discarded identity the SAME response
                    # also named, which could just as easily be a second,
                    # live order this run never accounts for. Trusting the
                    # coincidental match let the caller book one identity as
                    # a successful submission while the other silently
                    # vanished from reconciliation and cap accounting
                    # (Codex review, PR #859/#911 round 42: "Keep
                    # structurally ambiguous responses unresolved").
                    # `reconciled_order_id` is left as-is -- it is still a
                    # real, trackable order at the broker, just not proof
                    # that the response's whole ambiguity is resolved.
                    verdict = _PLACEMENT_UNKNOWN
            # PROVEN means the history was read AND it settled the question:
            # a declined terminal order, or a cancelled/expired one whose
            # executed quantity is an explicit zero. A clean miss is NOT that
            # -- Robinhood's order history is eventually consistent, so a
            # just-accepted order may simply not be indexed yet.
            placement_outcome_proven = history_readable and verdict == _PLACEMENT_NO_ORDER
            if verdict == _PLACEMENT_ACCEPTED:
                # The broker did accept it. Fall through to the ordinary
                # success path so record_buy, the deployment total and the
                # submitted row all happen exactly as they would have.
                logger.warning(
                    "Placement for %s raised %s but the order exists at the broker "
                    "(ref_id=%s); recording it as submitted",
                    ticker,
                    type(exc).__name__,
                    ref_id,
                )
                order_id = reconciled_order_id
            else:
                errors_count_inc += 1
                candidate_outcome = {
                    "status": "failed",
                    # Carried whenever history positively found an order,
                    # including a terminal order that proves the placement
                    # failed. Keeping the broker identity makes the evidence
                    # auditable without changing the verdict that controls
                    # booking and breaker accounting.
                    "order_id": reconciled_order_id,
                    # Type only, never the message: this is persisted verbatim
                    # into run_state.json and buy_candidates.csv, and a broker
                    # exception can embed an account id or token.
                    "skip_reason": (
                        f"placement failed: {type(exc).__name__}"
                        if placement_outcome_proven
                        else f"placement outcome unproven: {type(exc).__name__}"
                    ),
                    # PROVEN means the history was read AND settled it: a
                    # declined terminal order, or a cancelled/expired one whose
                    # executed quantity is an explicit zero. A clean miss is
                    # not that -- the history is eventually consistent, so a
                    # just-accepted order may simply not be indexed yet, and
                    # this row must not claim otherwise.
                    "placement_outcome_unproven": not placement_outcome_proven,
                    # Durable exact-reference evidence for the next invocation.
                    # A history miss is only temporary; without this value a
                    # restart cannot ask the broker about this particular call.
                    "placement_ref_id": ref_id,
                    # THIS EXACT response's own recovered execution notional,
                    # persisted alongside the reference rather than kept only
                    # in-process: a fresh process restart's own reconciliation
                    # pass (_reconcile_prior_unproven_fractional_placements)
                    # reads this outcome back from disk and calls the SAME
                    # reconciler again, and without this value that later call
                    # has no way to reconstruct it -- a stale `state=queued,
                    # dollar_amount=2` row could then be silently accepted at
                    # $2 even though this exact response already proved $100
                    # executed (Codex review, PR #911 round 41: "Persist
                    # response notional for restarted reconciliation").
                    "response_notional_usd": getattr(exc, "response_notional_usd", None),
                    "response_may_have_executed": bool(
                        getattr(exc, "response_may_have_executed", False)
                    ),
                    # Retain response-level identity ambiguity across a
                    # restart; matching one selected id proves nothing about
                    # the other identity named by the same response.
                    "structurally_ambiguous": bool(getattr(exc, "structurally_ambiguous", False)),
                    # Independent of whether order history was readable: the
                    # placement API was called, so this event consumes an
                    # attempt slot and advances the consecutive-call-failure
                    # breaker even when reconciliation itself is unavailable.
                    "broker_placement_attempted": True,
                    "reviewed_order": reviewed_order,
                    "submitted_amount_usd": order_amount,
                    # Carried for the same reason the SUBMITTED outcome below
                    # carries it: the failure writer can only rebuild this
                    # candidate through _failure_candidate_row, which reads
                    # it straight from the outcome and copies a missing value
                    # as null. An unresolved placement's own artifact is the
                    # ONE durable record of the sizing tier that produced a
                    # possibly-live order, so losing it here loses it for
                    # good (Codex review, PR #859: "Preserve the halted
                    # candidate's multiplier").
                    "buy_multiplier": decision.buy_multiplier,
                    # THE signal the consecutive-failure breaker counts, set
                    # only where a broker placement call was actually made and
                    # failed. Status alone cannot carry this: "failed" is also
                    # what the batch's own last-resort net assigns to a
                    # candidate that raised BEFORE reaching the broker (bad
                    # quote arithmetic, a ledger error), and three of those
                    # would trip a BROKER-health breaker with no placement
                    # having failed at all -- while
                    # OrderConfirmationRequiredError, a genuine broker-facing
                    # failure, carries a different status entirely and would
                    # never be counted (Codex review, PR #786: "Base the
                    # breaker on actual placement failures").
                    #
                    # Keyed on whether the HISTORY WAS READABLE, not on
                    # whether it proved anything -- the two come apart and
                    # getting this wrong breaks the breaker in one direction
                    # or the other.
                    #
                    # A readable history that did not name an order means this
                    # placement produced no order this run can see, which is a
                    # placement failure whatever the eventual-consistency
                    # caveat says about tomorrow. That is the ordinary refusal
                    # -- the reported RVII shape -- and it is precisely what
                    # the breaker exists to count: an outage times out every
                    # placement and leaves a readable, empty history, so
                    # withholding the marker here would mean the breaker never
                    # trips at all.
                    #
                    # A history this run could NOT read taught it nothing, and
                    # says nothing about whether the broker is refusing
                    # placements. Counting that would let an unreachable order
                    # history trip a breaker about something else entirely --
                    # the same category error round 27 fixed when this marker
                    # was first split from the status.
                    "broker_placement_failed": history_readable,
                    # A SEPARATE fact from the one above, and the separation is
                    # the whole point. `broker_placement_failed` answers "is the
                    # broker leg unhealthy?" and is therefore withheld when the
                    # order history could not be READ, because an unreachable
                    # history says nothing about the broker refusing placements.
                    # The daily attempt cap asks a different question -- "did a
                    # broker call happen?" -- and reaching this `except` at all
                    # is the answer: `place_market_buy` was called and raised.
                    #
                    # Charging the cap off the health marker meant that when the
                    # history lookup ALSO failed, neither the counter nor the
                    # breaker advanced: measured, an order-history outage during
                    # placement errors sent the ENTIRE candidate batch out
                    # against a cap of 3, with the counter still at 0 (Codex
                    # review, PR #786: "Count attempts when reconciliation
                    # history is unreadable").
                    #
                    # Round 55 fixed the accounting and reused the nearest
                    # marker to trigger it; this is my own rule -- a predicate
                    # is chosen for the QUESTION it answers rather than for
                    # being nearest to hand -- broken in the round that applied
                    # it.
                    "broker_call_attempted": True,
                    **spread_fields,
                }
                logger.error("Placement failed for %s: %s", ticker, exc)
                if not placement_outcome_proven:
                    # Preserve the unresolved row for the failure artifact,
                    # then stop before another candidate can place against
                    # deployment, buying-power, or cap arithmetic that may be
                    # missing a live order.  The batch's broad isolation net
                    # must not turn this safety halt back into a ticker-local
                    # failure.
                    _publish_in_flight_outcome(ticker, candidate_outcome)
                    raise UnresolvedPlacementError(
                        f"placement outcome remains unresolved for {ticker}"
                    ) from exc
                return (
                    candidate_outcome,
                    top_up_outcome,
                    running_deployed_7d,
                    errors_count_inc,
                    order_reviews_attempted_inc,
                )
        ctx.state.record_buy(ticker, ctx.trading_day, order_amount, order_id=order_id)
        ctx.state.own_orders_recorded.add((ticker, ctx.trading_day))
        if ctx.scheduled:
            running_deployed_7d += order_amount
        logger.info(
            "Placed buy for %s: $%.2f, order_id=%s",
            ticker,
            order_amount,
            order_id,
        )
        candidate_outcome = {
            "status": "submitted",
            "broker_placement_succeeded": True,
            "order_id": order_id,
            "skip_reason": None,
            "reviewed_order": reviewed_order,
            "submitted_amount_usd": order_amount,
            # Carried on the outcome so the failure handlers, which synthesize
            # buy_candidates rows from these outcomes alone, can record the real
            # multiplier. run_state.schema.json requires the property on every
            # candidate row, and a failure artifact that schema-based reporting
            # rejects is not the complete record it claims to be (Codex review).
            "buy_multiplier": decision.buy_multiplier,
            # config/scheduled_tasks.json's minimum_order_aggregate_topup_1530
            # requires these four audit fields on every 15:30 order that
            # closes an aggregated broker-minimum remainder (codex review
            # discussion_r3785797973). top_up_outcome.cumulative_credit_decline_usd
            # is set only by evaluate_top_up_guard's final-session aggregate
            # branch, so its presence IS the "rule was applied" signal;
            # existing_pending_credit_usd is the pre-existing minimum-order
            # remainder read at the top of this function, before this run's own
            # decline was combined in.
            **(
                {
                    "aggregate_minimum_topup_applied": True,
                    "aggregate_minimum_topup_remainder_usd": existing_pending_credit_usd,
                    "aggregate_minimum_topup_order_usd": order_amount,
                    "aggregate_minimum_topup_reason": (
                        "aggregate_at_or_above_minimum"
                        if round(
                            existing_pending_credit_usd
                            + top_up_outcome.cumulative_credit_decline_usd,
                            2,
                        )
                        >= 1.0
                        else "aggregate_rounded_up_to_minimum"
                    ),
                }
                if top_up_outcome is not None
                and top_up_outcome.cumulative_credit_decline_usd is not None
                # A fresh sub-dollar decline with NO prior remainder
                # (existing_pending_credit_usd == 0) still routes through
                # this same final-session credit-combination branch and
                # still sets cumulative_credit_decline_usd -- but it isn't
                # an AGGREGATION of anything a broker-minimum block earlier
                # carried forward, it's an ordinary final-session top-up.
                # Gating on a genuinely positive carried remainder too keeps
                # these audit fields identifying only the policy they exist
                # to audit (Codex review discussion on commit bb3d494:
                # "Require a carried remainder before marking aggregation").
                and existing_pending_credit_usd > 0
                else {}
            ),
            **spread_fields,
        }
        # Publish the accepted order NOW, before any fallible follow-up
        # (including the credit-ledger settlement right below). The batch
        # only records an outcome once _process_buy_candidate RETURNS, so a
        # raise in either the ledger settle() call or _log_execution's fill
        # lookup below would otherwise leave this real, already-placed order
        # out of the failure artifact entirely and let a later same-day run
        # re-allocate it (Codex review: "Publish accepted orders before
        # settling the credit ledger").
        _publish_in_flight_outcome(ticker, candidate_outcome)
        # Durably settle the cumulative sub-dollar credit ledger ONLY now that
        # the order is actually confirmed submitted -- not during
        # evaluate_top_up_guard's earlier, pre-placement computation, which
        # runs before the cap/spread/buying-power/review gates above and
        # before this broker call could still block, clamp (e.g. the
        # kill-switch base cap), or fail the placement (Codex review: "Defer
        # ledger updates until the submitted amount is known"). Recording the
        # ACTUAL submitted notional here, not the originally-computed
        # decline-derived amount, keeps the ledger's audit trail accurate for
        # a candidate the kill-switch or another gate shrank before placement.
        # A corrupt/locked/unwritable ledger must never mask this real,
        # already-placed and already-published order -- log and continue
        # rather than raise (Codex review: same finding, "or make settlement
        # failure non-fatal").
        if top_up_outcome is not None and top_up_outcome.cumulative_credit_decline_usd is not None:
            try:
                ctx.credit_ledger.settle(
                    ticker,
                    ctx.trading_day.isoformat(),
                    order_amount,
                    stream=ctx.stream,
                    # Stamped on the ORIGINAL settlement too -- that is what a
                    # later duplicate-recovery of this same order dedups
                    # against. Without it here the recovery has nothing to
                    # match and would settle a second time.
                    order_id=order_id,
                )
            except Exception as exc:  # noqa: BLE001
                logger.warning(
                    "cumulative credit ledger settlement failed for %s: %s", ticker, exc
                )

    if ctx.run_result is not None:
        _log_execution(
            ctx.run_result,
            decision,
            candidate_outcome.get("order_id"),
            ctx.broker,
            notional_usd=order_amount,
        )

    return (
        candidate_outcome,
        top_up_outcome,
        running_deployed_7d,
        errors_count_inc,
        order_reviews_attempted_inc,
    )


def _evaluate_all_signals(
    now: datetime,
    config: StrategyConfig,
    tradable_tickers: List[str],
    finance_data: MarketDataProvider,
    robinhood_data: MarketDataProvider,
) -> tuple[List[ReconciledDecision], int]:
    errors_count = 0

    def _degraded_signal(
        ticker: str, data: MarketDataProvider, reason: str, *, provider_error: bool
    ) -> SourceSignal:
        return SourceSignal(
            ticker=ticker,
            source=getattr(data, "source", SourceName.FINANCE),
            action=Action.NO_DATA,
            reason=reason,
            provider_error=provider_error,
        )

    def _safe_signal(
        ticker: str, data: MarketDataProvider, interval_minutes: int
    ) -> SourceSignal:
        nonlocal errors_count
        try:
            signal = evaluate_source_signal(
                ticker=ticker,
                now=now,
                config=config,
                data=data,
                interval_minutes=interval_minutes,
            )
            if not isinstance(signal, SourceSignal):
                # A provider (or a wrapper around one) that returns an
                # unexpected value instead of raising is the malformed-signal
                # case the try/except cannot catch, and it does NOT stay
                # contained: the value flows into reconcile_signals and, if it
                # survives that, into _signal_row, which reads
                # `signal.action.value` while BUILDING THE RUN ARTIFACTS --
                # long after other candidates have placed. A raise there costs
                # the whole run its artifacts rather than costing this ticker
                # its signal (Codex review, PR #786: "Replace malformed
                # signals in the reconciliation fallback"). Normalized to a
                # real NO_DATA signal at the boundary, so nothing downstream
                # ever handles a non-SourceSignal.
                errors_count += 1
                reason = (
                    f"provider returned a non-signal value "
                    f"(type={type(signal).__name__})"
                )
                logger.warning(
                    "%s: %s returned %s instead of a SourceSignal; degrading that source "
                    "to NO_DATA and continuing with the remaining tickers",
                    ticker,
                    getattr(data, "source", SourceName.FINANCE).value,
                    type(signal).__name__,
                )
                # provider_error=True: an unusable response is a provider
                # fault, and must block auto-buy via reconcile_signals'
                # provider_error guard exactly like a raised one.
                return _degraded_signal(ticker, data, reason, provider_error=True)
            # isinstance() is not the whole question. A REAL SourceSignal whose
            # emitted fields are malformed passes the check above and then
            # takes the run down at artifact-build time: `reason=object()`
            # survives reconcile_signals untouched, `_signal_row` copies it
            # into signal_rows, and json.dumps raises TypeError while writing
            # run_state.json -- after other tickers' orders have been placed
            # (Codex review, PR #786: "Validate normal provider signals before
            # retaining them").
            #
            # _serializable_signal already encodes exactly this test and was
            # applied ONLY in the reconciliation-exception fallback below, so
            # the guard existed and the path a signal normally arrives on never
            # consulted it. Degraded rather than returned as None, because
            # every caller here expects a SourceSignal.
            if _serializable_signal(signal) is None:
                errors_count += 1
                reason = (
                    "provider returned a SourceSignal the run artifacts cannot "
                    "serialize"
                )
                logger.warning(
                    "%s: %s returned a SourceSignal with unserializable fields; degrading "
                    "that source to NO_DATA and continuing with the remaining tickers",
                    ticker,
                    getattr(data, "source", SourceName.FINANCE).value,
                )
                # provider_error=True for the same reason the non-signal branch
                # above uses it: an unusable response is a provider fault and
                # must block auto-buy, not merely be dropped from the artifact.
                return _degraded_signal(ticker, data, reason, provider_error=True)
            return signal
        except Exception as exc:  # noqa: BLE001 - count and degrade to NO_DATA
            not_found = _is_ticker_not_found_error(exc)
            source_name = getattr(data, "source", SourceName.FINANCE).value
            if not_found:
                reason = f"ticker not found on {source_name}: {exc}"
                # A permanent, source-specific condition (see the
                # provider_error note below), not a fault -- info, so the run
                # log still names every symbol a provider could not resolve
                # without dressing an expected outcome up as a failure.
                logger.info(
                    "%s: not found on %s; degrading that source to NO_DATA (%s)",
                    ticker,
                    source_name,
                    exc,
                )
            else:
                errors_count += 1
                reason = f"provider error: {exc}"
                # Logged per ticker, not just counted: errors_count alone
                # tells a post-run reader THAT something failed but never
                # WHICH symbol or why, and this degradation is otherwise
                # silent -- the ticker simply shows up as NO_DATA in
                # signals.csv, indistinguishable from a provider that had
                # nothing to say (Codex-style review of the "log every
                # erroring stock and keep going" requirement).
                logger.warning(
                    "%s: %s signal evaluation failed; degrading that source to "
                    "NO_DATA and continuing with the remaining tickers: %s",
                    ticker,
                    source_name,
                    exc,
                )
            return SourceSignal(
                ticker=ticker,
                source=getattr(data, "source", SourceName.FINANCE),
                action=Action.NO_DATA,
                reason=reason,
                # Ticker-not-found is a permanent, source-specific condition documented in config/tickers.json
                # data_source_notes; it must not force MANUAL_REVIEW via reconcile_signals' provider_error guard.
                # Any other exception still sets provider_error so provider failures block auto-buy.
                provider_error=not not_found,
            )

    decisions = []
    for ticker in tradable_tickers:
        finance_signal = _safe_signal(
            ticker, finance_data, config.finance_interval_minutes
        )
        robinhood_signal = _safe_signal(
            ticker, robinhood_data, config.robinhood_interval_minutes
        )
        # _safe_signal covers the PROVIDER call; reconcile_signals itself sits
        # outside it and used to be the one unprotected statement in this
        # loop, so a raise there (a malformed quote reaching the arithmetic,
        # an unexpected signal shape) aborted signal evaluation for every
        # ticker after it as well -- and, since this runs before any
        # placement, cost the whole run its buys rather than just this
        # ticker's. Degrade the offending ticker to MANUAL_REVIEW (fail
        # closed: never an auto-buy on a decision we could not compute) and
        # keep evaluating the rest.
        try:
            decisions.append(
                reconcile_signals(ticker, finance_signal, robinhood_signal)
            )
        except Exception as exc:  # noqa: BLE001 - log, degrade, keep going
            errors_count += 1
            logger.exception(
                "%s: signal reconciliation failed; flagging it for manual "
                "review and continuing with the remaining tickers: %s",
                ticker,
                exc,
            )
            decisions.append(
                ReconciledDecision(
                    ticker=ticker,
                    action=Action.MANUAL_REVIEW,
                    reason=f"signal reconciliation failed: {type(exc).__name__}",
                    # Belt-and-braces alongside _safe_signal's own
                    # normalization: whatever made reconcile_signals raise must
                    # not be RETAINED on the decision, or _signal_row hits it
                    # later while building the run artifacts and takes the
                    # whole run down instead of this one ticker.
                    #
                    # isinstance() alone was not enough. A provider can return
                    # a real SourceSignal whose FIELDS are malformed -- most
                    # directly `action=None`, which passes the type check and
                    # then makes _signal_row's `signal.action.value` raise, at
                    # artifact-build time, after other candidates have already
                    # placed. The type was right and the contents were not
                    # (Codex review, PR #786: "Discard malformed signals after
                    # reconciliation fails").
                    finance_signal=_serializable_signal(finance_signal),
                    robinhood_signal=_serializable_signal(robinhood_signal),
                )
            )

    return decisions, errors_count


def _seed_prior_allocations(
    state: StrategyState,
    trading_day: date,
    guard_active: bool,
    prior_same_day_allocations: Optional[Dict[str, PriorSameDayAllocation]],
    *,
    one_order_per_ticker_per_day: bool,
) -> None:
    # ``one_order_per_ticker_per_day`` no longer skips seeding: this call is
    # what folds an earlier roster slot's spend into day_notional()/
    # week_notional() for the ABSOLUTE $ cap accounting. Early-returning here
    # left duplicate-buy prevention to the broker's same_day_strategy_order_exists
    # check alone, but that check says nothing about the previously-spent
    # dollar amount -- so a later slot's own (different-ticker) candidates
    # still saw the full daily/weekly cap as if nothing had been spent yet,
    # letting successive roster slots exceed the configured absolute caps
    # (Codex review, discussion_r3679391265: "Preserve prior allocations in
    # cap bookkeeping"). Seeding also bumps buys_today() for the ticker,
    # which is a harmless belt-and-suspenders duplicate for the one-order
    # gates below since same_day_strategy_order_exists already blocks a
    # second buy for that ticker first. The bool parameter is kept for
    # call-site clarity/back-compat rather than removed.
    if guard_active and prior_same_day_allocations:
        for _ticker, _alloc in prior_same_day_allocations.items():
            # Seed on attempt_count, not amount_usd > 0: a ticker whose only
            # earlier-slot evidence is a rejected/canceled/failed attempt has
            # amount_usd == 0 but still consumed one of the shared
            # max_orders_per_day slots and must still be reconstructed here
            # (Codex review: "Count every prior buy attempt toward the daily
            # limit" -- record_buy's fixed +1 per call previously collapsed
            # however many earlier attempts a ticker had, successful or not,
            # into exactly one seeded attempt).
            #
            # Gated on own_orders_recorded, NOT buys_today() == 0: a retry's
            # fresh scan can discover MORE evidence for a ticker already
            # seeded on an earlier pass (e.g. a manual fill written between
            # the original run and its retry), and reconcile_prior_allocation
            # tops up only the newly-discovered delta rather than treating
            # any prior count as proof the aggregate is already current
            # (Codex review: "Reconcile increases to already-seeded ticker
            # allocations"). A ticker THIS stream has already bought for real
            # today is excluded here -- its own record_buy call already
            # accounts for it, and topping it up again from this separate
            # tracker would double-count it.
            # An allocation ENTIRELY explained by run_ids this process's own
            # fractional-placement reconciliation already restored an
            # attempt for is not new cross-stream evidence -- it is the
            # SAME crashed run's unresolved candidate, independently
            # rediscovered by this scan. own_orders_recorded's synthetic
            # "#fractional-recovery" key (see its own docstring) does not
            # satisfy the bare-tuple check just above by design -- that
            # check exists so OTHER slots' genuinely separate spend for
            # this ticker still gets folded in -- so a same-stream retry
            # re-seeded the identical attempt a second time, doubling
            # day_order_count() for one real broker call (Codex review, PR
            # #911 round 30: "Avoid reseeding a recovered earlier-slot
            # attempt"). Matched via attempt_run_ids -- the same run-
            # identity signal load_prior_same_day_allocations_multi
            # already tracks for its own mirrored-artifact dedup -- and
            # only when it is a NONEMPTY subset of the already-recovered
            # set: a ticker with at least one OTHER, not-yet-recovered
            # contributing run still needs its (coarser, whole-allocation)
            # evidence folded in normally, exactly like every other
            # partial-overlap case this aggregation already accepts.
            #
            # Run-ID membership alone is not proof every ATTEMPT from that
            # run was restored: one source run can make several same-
            # ticker attempts (e.g. an ordinary submitted order followed
            # by an ambiguous top-up), and reconciling only the ambiguous
            # one still adds that single run_id to own_recovered_attempt_
            # run_ids. A subset test on run_ids alone then read the
            # ENTIRE allocation as explained and skipped it, leaving the
            # OTHER attempt's own count/notional out of day_order_count()
            # and cap accounting (Codex review, PR #911 round 33: "Do not
            # skip multi-attempt allocations by run ID"). Neither
            # attempt_run_ids nor own_recovered_attempt_run_ids tracks a
            # per-run attempt COUNT, so this is provable, not merely
            # heuristic, only in the one shape where run-ID membership
            # genuinely does prove full explanation: `attempt_run_ids`
            # only ever gains a run_id that contributed AT LEAST ONE
            # attempt (see its own docstring), so `attempt_count` can
            # never be LESS than the number of distinct contributing
            # runs -- `attempt_count <= len(attempt_run_ids)` therefore
            # forces equality, i.e. every contributing run made EXACTLY
            # one attempt, and subset membership on run_ids then is
            # exactly subset membership on attempts too. When a run made
            # two or more attempts (`attempt_count > len(attempt_run_ids)`),
            # that guarantee does not hold, and the allocation must fall
            # through to the safe, ordinary reconciliation path below
            # instead of being skipped on unproven evidence.
            _already_recovered_run_ids = state.own_recovered_attempt_run_ids.get(
                (_ticker, trading_day), set()
            )
            _fully_explained_by_recovery = (
                bool(_alloc.attempt_run_ids)
                and _already_recovered_run_ids
                and set(_alloc.attempt_run_ids) <= _already_recovered_run_ids
                and _alloc.attempt_count <= len(_alloc.attempt_run_ids)
            )
            if (
                _alloc.attempt_count > 0
                and (_ticker, trading_day) not in state.own_orders_recorded
                and not _fully_explained_by_recovery
            ):
                state.reconcile_prior_allocation(
                    _ticker,
                    trading_day,
                    _alloc.amount_usd,
                    _alloc.attempt_count,
                    order_ids=_alloc.contributing_order_ids,
                )


def _process_buy_candidates_batch(
    buy_candidates: List[ReconciledDecision],
    ctx: ProcessCandidateContext,
    *,
    initial_candidate_outcomes: Optional[Dict[str, Dict[str, Any]]] = None,
) -> tuple[Dict[str, Dict[str, Any]], Dict[str, TopUpGuardOutcome], float, int, int]:
    # Seeded from TWO independent sources, both of which must survive:
    #
    # 1. Whatever _run_once_impl's own pre-roll cross-day reconciliation pass
    #    already published (a "submitted" outcome for any whole-share ticker
    #    whose unresolved claim it resolved) -- that pass runs BEFORE this
    #    function starts, so without carrying its entries forward here they
    #    would be silently overwritten by this function's own fresh dict and
    #    never reach buy_candidates.csv/run_state.json (Codex review:
    #    "Persist fills recovered by the pre-roll reconciliation pass").
    # 2. Any crash-lease recoveries already reconciled THIS run, passed in as
    #    ``initial_candidate_outcomes`` and keyed under their synthetic
    #    "#imart-recovery" ticker key so a placement below can never collide
    #    with one. Seeding them HERE, before any candidate is processed, is
    #    what keeps a recovered fire's outcome in the failure artifact when a
    #    LATER candidate in this batch raises (Codex review: "Publish
    #    recovered outcomes before processing new candidates").
    #
    # Copied rather than mutated in place so neither the caller's dict nor the
    # previously-installed in-flight dict is touched. A ticker THIS batch's own
    # loop later processes for a real, independent decision still overwrites
    # its seeded entry exactly like any other candidate_outcomes assignment
    # below.
    candidate_outcomes: Dict[str, Dict[str, Any]] = dict(_IN_FLIGHT_CANDIDATE_OUTCOMES.get("outcomes") or {})
    if initial_candidate_outcomes:
        candidate_outcomes.update(initial_candidate_outcomes)
    # Published by reference BEFORE any placement so a failure part-way through
    # the batch can still see every order that landed (mirrors the morning
    # executor), INCLUDING a recovered order this run already reconciled and
    # cleared the lease for -- a raise later in this loop must not make that
    # already-settled recovery vanish from the failure artifact, since retrying
    # it from a stale artifact could no longer reconstruct it (Codex review:
    # "Publish recovered outcomes before processing new candidates"). Without
    # this the afternoon failure writer would also assert zero orders for a
    # slot that had already placed some.
    _IN_FLIGHT_CANDIDATE_OUTCOMES["outcomes"] = candidate_outcomes
    top_up_outcomes: Dict[str, TopUpGuardOutcome] = {}
    running_deployed_7d = ctx.config.deployed_last_7d_usd
    errors_count_inc = 0
    order_reviews_attempted_inc = 0

    # Reconcile every whole-share ticker's cross-day unresolved claims
    # BEFORE any candidate in this batch is allowed to place -- otherwise a
    # recovered order that pushes deployment across the kill-switch
    # threshold is only visible to candidates sorted AFTER the whole-share
    # ticker in buy_candidates, letting earlier candidates place uncapped
    # orders against a stale, too-low running_deployed_7d (Codex review:
    # "Reconcile recovered spend before starting the candidate batch").
    running_deployed_7d = _reconcile_cross_day_whole_share_claims_for_batch(
        ctx, running_deployed_7d, decisions_by_ticker={d.ticker: d for d in buy_candidates}
    )

    # Consecutive, not cumulative -- see the breaker at the bottom of the loop.
    # Same knob dca_runner.execute_plan and MorningDCAExecutor use, so the three
    # live paths cannot disagree about when a batch stops.
    consecutive_placement_failures = 0

    for candidate_index, decision in enumerate(buy_candidates):
        # Captured BEFORE _process_buy_candidate runs -- candidate_outcomes
        # IS (by reference) _IN_FLIGHT_CANDIDATE_OUTCOMES["outcomes"], and
        # _process_buy_candidate's own success/failure paths publish into
        # that SAME dict via _publish_in_flight_outcome as soon as they
        # know an outcome, well before returning. Reading
        # candidate_outcomes.get(decision.ticker) AFTER the call (an
        # earlier version of this fix did) would already see whatever
        # _process_buy_candidate itself just wrote there -- the SAME value
        # as c_outcome -- making the seeded pre-roll outcome unrecoverable
        # and silently defeating the aggregation below. This is a plain
        # snapshot, not a merge point in itself -- see
        # _process_whole_share_candidate's own internal
        # `_publish_whole_share_outcome` closure for how a recovery
        # discovered DURING this call (by that function's own internal
        # cross-day reconciliation pass, after this snapshot was taken) is
        # preserved through every one of its self-publishing return paths
        # instead of being silently clobbered by them (Codex review: "Merge
        # recoveries published during candidate processing").
        seeded_outcome = candidate_outcomes.get(decision.ticker)
        # Any acceptance marker present now belongs to an EARLIER candidate's
        # call (or an earlier run in this process), never to this one -- see
        # _clear_whole_share_acceptance for why it is cleared here rather
        # than after the call returns.
        _clear_whole_share_acceptance(decision.ticker)
        # PER-TICKER ERROR ISOLATION. _process_buy_candidate already converts
        # every failure mode it ANTICIPATES into a returned outcome row (a
        # failed placement, a data error, an unreadable ledger, ...), and the
        # comment trail throughout that function records exactly why: "the
        # exception would escape _process_buy_candidates_batch entirely,
        # aborting" the remaining candidates. That reasoning was applied one
        # `except` at a time, so any path nobody thought to wrap -- a provider
        # returning an unexpected shape, an arithmetic error on a malformed
        # quote, a KeyError in a helper -- still took the WHOLE batch down
        # with it: every ticker sorted after the raising one was never even
        # evaluated, and the run ended in the failure writer instead of
        # completing. One bad symbol must never cost the other 56 their buy,
        # so the last-resort net lives here, around the call itself, where it
        # covers every present and future path at once rather than depending
        # on each one remembering to catch for itself.
        try:
            c_outcome, t_outcome, running_deployed_7d, err_inc, rev_inc = (
                _process_buy_candidate(
                    decision=decision,
                    ctx=ctx,
                    running_deployed_7d=running_deployed_7d,
                )
            )
        except UnresolvedPlacementError:
            # THE BROKER CALL STILL HAPPENED, so it still consumes a
            # `max_orders_per_day` slot. The charge below normally runs after
            # _process_buy_candidate RETURNS, and this raise skips it -- so a
            # caller that catches the halt and retries in-process with the same
            # StrategyState made a placement call that cost nothing, and
            # repeated retries could issue more live calls than the configured
            # cap while each earlier one may already have created a live order
            # (Codex review, PR #859: "Charge unresolved calls against the
            # daily attempt cap"). That is the exact failure mode the
            # unconditional charge below was written for; an unresolved outcome
            # is the LAST case that may escape it. Zero notional, because
            # nothing is known to have been bought -- only the attempt counter
            # moves -- and deliberately NOT added to `own_orders_recorded`, for
            # the reasons spelled out at that charge site.
            #
            # order_id looked up from the JUST-PUBLISHED in-flight outcome,
            # not left anonymous: `_process_buy_candidate` publishes into
            # `candidate_outcomes` (== `_IN_FLIGHT_CANDIDATE_OUTCOMES
            # ["outcomes"]`) via `_publish_in_flight_outcome` BEFORE it can
            # raise `UnresolvedPlacementError` -- e.g. a structurally
            # ambiguous response whose one id was found in history still
            # carries that id on its published outcome. This centralized
            # charge normally passes `c_outcome.get("order_id")` through
            # for exactly this reason (see its own comment, a few thousand
            # lines below), but THIS earlier handler -- reached only when
            # the exception escapes before that charge ever runs -- bypassed
            # it and charged anonymously, leaving a known order id able to
            # mask a different same-ticker reconciliation's own restoration
            # (Codex review, PR #1168: "Propagate known IDs through the
            # unresolved halt charge").
            _unresolved_halt_outcome = candidate_outcomes.get(decision.ticker)
            _unresolved_halt_order_id = (
                _unresolved_halt_outcome.get("order_id")
                if isinstance(_unresolved_halt_outcome, dict)
                else None
            )
            ctx.state.record_buy(decision.ticker, ctx.trading_day, 0.0, order_id=_unresolved_halt_order_id)
            # Same obligation the consecutive-failure breaker discharges for
            # its own unattempted tail, for the same reason: the failure
            # writer serializes only _IN_FLIGHT_CANDIDATE_OUTCOMES, and it
            # derives its candidate count from that map too, so a candidate
            # this halt skipped simply VANISHED from buy_candidates -- no row,
            # no reason, and a count that made it look as though the ticker
            # never qualified (Codex review, PR #859: "Record candidates
            # skipped by an unresolved halt"). Annotated BEFORE the re-raise,
            # since nothing downstream of it runs.
            unattempted = buy_candidates[candidate_index + 1:]
            halt_reason = (
                "not attempted: batch halted because the placement outcome for "
                f"{decision.ticker} could not be proven"
            )
            for unattempted_decision in unattempted:
                unattempted_outcome = {
                    "status": "skipped",
                    "order_id": None,
                    "skip_reason": halt_reason,
                    # A deliberate safety stop, not a per-ticker block: no
                    # broker call was made for this ticker, so it must not
                    # read as an attempt (and must not inflate the connector
                    # error count in _apply_no_order_classification).
                    "deliberate_skip": True,
                    "submitted_amount_usd": 0.0,
                    "unresolved_placement_halted": True,
                }
                seeded = candidate_outcomes.get(unattempted_decision.ticker)
                if seeded is not None:
                    # A pre-roll recovery already published for this ticker.
                    # Both facts are true and neither may erase the other --
                    # annotate in place on keys of their own, exactly as the
                    # breaker's tail does.
                    seeded["unresolved_placement_halted"] = True
                    seeded["today_order_not_attempted"] = True
                    seeded["breaker_halt_reason"] = halt_reason
                    _publish_in_flight_outcome(unattempted_decision.ticker, seeded)
                    continue
                candidate_outcomes[unattempted_decision.ticker] = unattempted_outcome
                _publish_in_flight_outcome(
                    unattempted_decision.ticker, unattempted_outcome
                )
            logger.error(
                "Stopping candidate batch because placement outcome for %s remains "
                "unresolved; %d candidate(s) never attempted: %s",
                decision.ticker,
                len(unattempted),
                ", ".join(d.ticker for d in unattempted) or "none",
            )
            # `errors_count_inc` here is every EARLIER candidate's own error
            # contribution THIS batch already accumulated (a same-day
            # notional check failing, a buying-power lookup raising, ...) --
            # never the halting candidate's own, since the try above never
            # reached the line that folds that in. The raise unwinds past
            # that line entirely, so without publishing it here it is lost
            # the same way round 28 found pre-batch evaluation errors lost:
            # `_write_afternoon_failure_artifacts` reads `_evaluated.get(
            # "errors_count")` -- exactly what `_publish_in_flight_
            # evaluation` stamped BEFORE this batch even started -- plus
            # `max(1, orders_failed_count)` for the halt itself, and
            # `orders_failed_count` only counts a literal ``"failed"``
            # status; a "blocked" row an earlier candidate published for its
            # OWN error is invisible to it. One earlier candidate error
            # followed by this halt reported as a single error instead of
            # two, understating usage/cost and incident telemetry exactly
            # as round 28's pre-batch gap did (Codex review, PR #859 round
            # 39: "Carry candidate-stage errors into halt telemetry").
            if errors_count_inc:
                _IN_FLIGHT_RUN_EVALUATION["errors_count"] = _coerce_nonnegative_int(
                    _IN_FLIGHT_RUN_EVALUATION.get("errors_count")
                ) + errors_count_inc
            raise
        except Exception as exc:  # noqa: BLE001 - log, record, keep going
            logger.exception(
                "Candidate processing failed for %s; skipping this ticker and "
                "continuing with the rest of the batch: %s",
                decision.ticker,
                exc,
            )
            # AN ORDER ALREADY PLACED BEFORE THE RAISE FAILS THE RUN.
            # _publish_in_flight_outcome is called the moment the broker
            # accepts, so a published attempt here means real capital went out
            # and then something after it broke. Three things are then true at
            # once: the order is real, this run's deployment accounting for it
            # is unknown (_process_buy_candidate increments its LOCAL
            # running_deployed_7d and the raise stops that value from being
            # returned), and the execution logging for it may be incomplete.
            #
            # Continuing to place is the wrong move in BOTH directions, which
            # two review rounds found from opposite sides: carrying the
            # caller's stale total under-counts the order and lets later
            # candidates miss a kill-switch transition ("Preserve deployment
            # totals after a post-placement exception"), while adding the
            # published notional back unconditionally DOUBLE-counts a
            # duplicate-preserved recovery whose deployment
            # _process_buy_candidate deliberately did not add, falsely
            # tripping the kill switch instead ("Preserve duplicate recovery's
            # deployment-history check"). Reconstructing the exact figure means
            # mirroring every branch's own condition here and keeping the two
            # copies in step forever.
            #
            # So don't reconstruct it: fail the run, the same fail-closed
            # answer a whole-share booking failure gets (see
            # _reconcile_cross_day_whole_share_claims_for_batch) -- no further
            # order is placed against a total known to be wrong. The published
            # outcome stays in _IN_FLIGHT_CANDIDATE_OUTCOMES, which is exactly
            # what the failure writer reads, so the real order still reaches
            # the artifact and a later same-day run will not re-allocate it.
            #
            # This costs the isolation goal nothing that matters: the incident
            # this whole change exists for is a ticker the broker REFUSED (no
            # order, nothing ambiguous), and that path -- along with every
            # raise before the broker boundary -- still isolates below.
            published = candidate_outcomes.get(decision.ticker)
            if (
                published is not None
                and published is not seeded_outcome
                and (
                    published.get("status") in _PRIOR_ALLOCATION_ATTEMPT_STATUSES
                    or published.get("whole_share_zero_fill_attempt")
                )
            ):
                # Type only, never the message -- this marker is copied into
                # run_state.json/buy_candidates.csv by _failure_candidate_row
                # exactly like skip_reason, so it is subject to the same
                # secrets policy (Codex review, PR #786: "Redact unexpected
                # exception text before persisting it"). logger.exception
                # above already gave the operator the full traceback.
                published["candidate_processing_error"] = (
                    f"candidate processing raised {type(exc).__name__}"
                )
                raise
            # THE SAME EVENT, ONE STEP EARLIER, ON THE WHOLE-SHARE PATH.
            # _process_whole_share_candidate does a lot of fallible work
            # between the broker accepting the order and the first
            # _publish_whole_share_outcome call -- an order-history lookup,
            # int(float(...)) over a broker-supplied quantity, ledger
            # settlement -- so a raise in that window reaches here with
            # NOTHING published, and the test above reads it as a pre-broker
            # failure. Isolating it writes a zero-notional "failed" row for
            # an order that is live at the broker, leaving its real spend out
            # of deployment, daily/weekly cap, and attempt accounting for
            # every later candidate and for any run that rebuilds the day
            # from this artifact (Codex review, PR #786: "Halt on unpublished
            # whole-share acceptances").
            #
            # The acceptance marker is that missing evidence, so this gets
            # the same fail-closed answer. Publish the order first: the
            # failure writer reads _IN_FLIGHT_CANDIDATE_OUTCOMES, and without
            # a row the accepted order would be absent from the recovery
            # artifact too, which is the one place it still has to appear.
            accepted = _IN_FLIGHT_WHOLE_SHARE_ACCEPTANCES.get(decision.ticker)
            if accepted is not None:
                accepted_order_id, accepted_notional = accepted
                _publish_in_flight_outcome(
                    decision.ticker,
                    {
                        "status": "submitted",
                        "broker_placement_succeeded": True,
                        "order_id": str(accepted_order_id) if accepted_order_id else None,
                        "skip_reason": None,
                        # Numeric, like every other synthesized row here --
                        # run_state.schema.json requires it and
                        # _failure_candidate_row maps it straight across.
                        "submitted_amount_usd": float(accepted_notional or 0.0),
                        # Type only, never the message: this is persisted
                        # verbatim into run_state.json/buy_candidates.csv.
                        "candidate_processing_error": (
                            f"whole-share order accepted, then candidate processing raised "
                            f"{type(exc).__name__} before its outcome was published"
                        ),
                    },
                )
                raise
            # "failed", not a new status string: run_state.schema.json's
            # buy_candidates.status is a CLOSED enum, and "failed" is
            # already the repo's word for "a genuine attempt for this
            # ticker did not complete" (see _process_buy_candidate's own
            # placement-exception branch, which returns exactly this
            # shape). It also carries the right downstream semantics:
            # _PRIOR_ALLOCATION_ATTEMPT_STATUSES counts it as one
            # consumed buy ATTEMPT when a later run rebuilds state from
            # this artifact. Counting it is the fail-closed reading -- an
            # exception can have been raised on either side of a broker
            # submission, so treating the ticker as having already used
            # one of the day's order slots risks under-buying, while
            # treating it as untouched risks a duplicate order.
            #
            # Within THIS run the day's attempt count is already correct
            # without booking anything here: _process_buy_candidate calls
            # state.record_buy immediately after place_market_buy returns,
            # with nothing between them that can raise, so any raise at or
            # after the broker boundary has already consumed its slot in
            # ctx.state -- and any raise before it made no attempt to
            # consume (Codex review, PR #786: "Count isolated failures
            # before continuing the batch").
            #
            # NOT, however, enough on its own to change the run's
            # top-level order_submit_status: _derive_order_submit_status
            # returns ORDER_SUBMIT_STATUS_SUBMITTED as soon as ANY row
            # submitted, before it ever looks at failed rows or
            # errors_count, so a partially-failed batch still reports
            # "submitted" -- which is accurate for that field (orders did
            # reach the broker) but is not the partial-failure signal
            # (Codex review, PR #786: "Prioritize isolated failures over
            # submitted status"). The signal that a ticker was abandoned
            # and needs recovery is carried by errors_count, which sets
            # usage_proxy.manual_recovery_required, and by this row's own
            # "failed" status plus candidate_processing_error in
            # buy_candidates. Changing that precedence would reclassify
            # every partially-failed run for the watchdog and
            # run-classification consumers and is deliberately left
            # alone here.
            c_outcome = {
                "status": "failed",
                "order_id": None,
                # Only the exception's TYPE, never its message: an
                # unexpected exception from a broker/provider helper can
                # carry an account identifier, an access token, or request
                # metadata, and _build_buy_candidates persists skip_reason
                # verbatim into run_state.json and buy_candidates.csv,
                # which AGENTS.md's secrets policy forbids. Mirrors
                # dca_runner's own "place_fn raised {type}" treatment of
                # connector exceptions (Codex review, PR #786: "Redact
                # unexpected exception text before persisting it"). The
                # full message still reaches the operator through
                # logger.exception above, which is not a repo artifact.
                "skip_reason": f"candidate processing raised {type(exc).__name__}",
                # schemas/run_state.schema.json REQUIRES planned_amount_usd to
                # be a number, and _failure_candidate_row maps it straight from
                # this key -- so omitting it wrote a null and made the recovery
                # artifact schema-invalid exactly when a partially processed
                # batch later failed, which is when that artifact matters most
                # (Codex review, PR #786: "Preserve a numeric planned amount
                # for isolated failures"). 0.0, not the ladder's suggested
                # amount: nothing was submitted, and load_prior_same_day_
                # allocations sums this figure for "failed" rows -- reporting a
                # would-be amount there would inflate a later run's prior-
                # allocation total and suppress a legitimate top-up.
                "submitted_amount_usd": 0.0,
                # Distinguishes THIS net (an unhandled raise) from an
                # ordinary failed placement in artifacts and post-run
                # triage; both are "failed", only this one means the
                # ticker was abandoned mid-evaluation with its broker
                # state unproven. Type only, for the same reason.
                "candidate_processing_error": f"candidate processing raised {type(exc).__name__}",
            }
            _publish_in_flight_outcome(decision.ticker, c_outcome)
            t_outcome = None
            # rev_inc is deliberately 0: an order review may or may not have
            # been attempted before the raise, and _process_buy_candidate's
            # counters are lost with its frame. errors_count is what this
            # branch must move -- it drives manual_recovery_required and the
            # run's error classification.
            err_inc = 1
            rev_inc = 0
        # THIS candidate's own broker-facing result, captured before the
        # cross-day recovery merge below can rewrite it. That merge can turn
        # today's genuinely failed placement into a "submitted" row by
        # aggregating it with an EARLIER day's recovered fill for the same
        # ticker -- correct for the artifact (both orders are real) but wrong
        # for the broker-health breaker at the bottom of this loop, which is
        # asking only "did the placement we just attempted fail?".
        raw_broker_placement_failed = bool(c_outcome.get("broker_placement_failed"))
        raw_broker_placement_attempted = bool(c_outcome.get("broker_placement_attempted"))
        raw_broker_placement_succeeded = bool(c_outcome.get("broker_placement_succeeded"))
        # Most of _process_whole_share_candidate's ~40 return paths never
        # touch candidate_outcomes again once its own internal cross-day
        # reconciliation pass (at the top of that function) has run -- they
        # simply return their own outcome value without publishing it
        # themselves (relying on THIS assignment, below, to do it). For one
        # of those non-self-publishing paths (e.g. "still accumulating"),
        # a recovery that pass discovered and published MID-CALL survives
        # untouched in candidate_outcomes right up until this exact
        # assignment -- distinct from BOTH seeded_outcome (which only
        # covers a recovery already published BEFORE this call started)
        # and c_outcome (today's own, unrelated non-submission result).
        # Without checking for it here too, this assignment would silently
        # overwrite it (Codex review: "Merge recoveries published during
        # candidate processing"). The self-publishing paths (which merge
        # internally -- see that function's own `_publish_whole_share_
        # outcome` closure) already leave candidate_outcomes[ticker] EQUAL
        # to c_outcome by the time this runs, so identity against c_outcome
        # (not just non-None) is what keeps this from re-merging an
        # already-merged result a second time.
        mid_call_recovery = candidate_outcomes.get(decision.ticker)
        # A recovery worth preserving is either a real "submitted" order, OR
        # a confirmed zero-fill terminal order booked by
        # _book_reconciled_whole_share_order's own zero_fill_attempt branch
        # -- that branch deliberately reports "status": "failed" (nothing
        # was purchased) but is still a REAL broker attempt that must count
        # toward max_orders_per_day, exactly like a submitted recovery. This
        # loop previously only ever looked for "submitted", so a zero-fill
        # recovery seeded (or discovered mid-call) here was silently
        # overwritten the instant today's own processing of the SAME ticker
        # produced ANY outcome at all, erasing the attempt from the run
        # artifact (Codex review: "Preserve recovered zero-fill attempts
        # through the batch"). The explicit whole_share_zero_fill_attempt
        # marker (see that branch) is what makes a zero-fill recovery
        # recognizable here, since its status alone is indistinguishable
        # from an ordinary failed candidate.
        recovered_outcome = (
            seeded_outcome
            if seeded_outcome is not None
            and (seeded_outcome.get("status") == "submitted" or seeded_outcome.get("whole_share_zero_fill_attempt"))
            else None
        )
        if (
            mid_call_recovery is not None
            and mid_call_recovery is not c_outcome
            and mid_call_recovery is not seeded_outcome
            and (mid_call_recovery.get("status") == "submitted" or mid_call_recovery.get("whole_share_zero_fill_attempt"))
        ):
            recovered_outcome = (
                _merge_whole_share_submission_outcomes(recovered_outcome, mid_call_recovery)
                if recovered_outcome is not None
                else mid_call_recovery
            )
        # Today's own row, held before the recovery branch below may replace
        # it, so its accumulation bookkeeping can be carried across.
        c_outcome_today = c_outcome if isinstance(c_outcome, dict) else None
        if recovered_outcome is not None and recovered_outcome is not c_outcome:
            # A recovered fill from an EARLIER trading day's claim (seeded
            # above from _run_once_impl's own pre-roll reconciliation pass,
            # or from this candidate's own per-candidate safety-net
            # reconciliation mid-call) and TODAY's own, independent
            # processing of this SAME ticker are two genuinely different
            # orders -- unconditionally overwriting the seed with c_outcome
            # (as this loop did before this fix) silently erased the
            # recovered fill whenever today's own outcome was anything
            # other than a fresh submission (often just "still
            # accumulating"), and dca_risk.deployed_usd() sums exactly ONE
            # row's planned_amount_usd per ticker, so the recovered spend
            # then vanished from trailing deployment accounting on the next
            # run (Codex review: "Preserve recovered fills when processing
            # today's candidate"). Aggregate the two into a single row
            # instead of letting either replace the other.
            # _PRIOR_ALLOCATION_ATTEMPT_STATUSES, not a bare "submitted":
            # today's own outcome can be a real broker ATTEMPT that did not
            # end in a submission -- a failed placement, or this batch's
            # own isolation net's "failed" row -- and that attempt and the
            # recovered fill are still two different orders. Narrowing this
            # to "submitted" sends every such pair down the else branch,
            # which keeps the recovery but drops today's attempt from the
            # row entirely, taking `whole_share_order_ids` with it.
            # ... and `broker_placement_failed` beside the status set, because
            # that set does not cover every real broker attempt. A whole-share
            # placement whose own reconciliation lookup then failed is
            # recorded "blocked" -- deliberately, so the claim stays RESERVED
            # pending manual reconciliation -- and a confirmation-required
            # hold is recorded "not_submitted_confirmation_required". Both
            # made a genuine broker-facing call, neither is in
            # _PRIOR_ALLOCATION_ATTEMPT_STATUSES, so both fell to the else
            # branch and were replaced wholesale by the recovered row: the
            # failure marker, its terminal order id and its
            # "claim left reserved" reason all vanished, leaving a run that
            # needed a human look reading as a plain recovered submission
            # (Codex review, PR #786: "Preserve blocked placement failures
            # beside recovered fills"). The explicit marker is what makes
            # these recognizable -- it is set only by branches that really did
            # call the broker, never by a policy block decided before
            # submission.
            if _outcome_records_a_broker_attempt(c_outcome):
                # Shared with _book_reconciled_whole_share_order's own
                # identical aggregation need (Codex review: "Aggregate all
                # recovered claims for the same ticker") -- keeps order_id a
                # SINGLE exact broker order id rather than a synthetic
                # joined string that no exact-ID consumer could ever match
                # (Codex review: "Preserve each broker order ID when
                # aggregating outcomes").
                c_outcome = _merge_whole_share_submission_outcomes(recovered_outcome, c_outcome)
            else:
                # Today's own outcome is not a real placement (still
                # accumulating, blocked, skipped, etc.) -- the recovered
                # fill remains the only real order for this ticker today,
                # so its status, spend and order ids are kept exactly as
                # recovered rather than replaced with a non-submission.
                #
                # But today's BOOKKEEPING is not the recovery's to discard.
                # The ledger has already recorded today's contribution, so
                # replacing the row wholesale dropped
                # whole_share_contribution_usd, the updated
                # whole_share_pending_usd and any current block reason from
                # run_state.json and buy_candidates.csv -- leaving the
                # persisted accumulator state stale and the run looking like
                # it contained only the older recovery (Codex review,
                # PR #786: "Preserve today's accumulation metadata beside a
                # recovery"). Carried across explicitly, and only where the
                # recovery has nothing of its own to say, so nothing the
                # recovered order established can be overwritten by a
                # non-placement.
                c_outcome = dict(recovered_outcome)
                for carried in _TODAY_ACCUMULATION_FIELDS:
                    value = c_outcome.get(carried, _MISSING)
                    if value is _MISSING or value is None:
                        today_value = (c_outcome_today or {}).get(carried)
                        if today_value is not None:
                            c_outcome[carried] = today_value
        candidate_outcomes[decision.ticker] = c_outcome
        if t_outcome is not None:
            top_up_outcomes[decision.ticker] = t_outcome
        errors_count_inc += err_inc
        order_reviews_attempted_inc += rev_inc

        # A ticker's own rejection is isolated -- that is the whole point of
        # this batch's design -- but an unbroken RUN of failed placements means
        # the broker leg itself is unhealthy (an outage, an expired session, an
        # account block, exhausted buying power) and every further candidate is
        # a doomed live call. Counted CONSECUTIVELY: any real submission resets
        # the streak, so a batch that keeps succeeding between isolated bad
        # symbols runs to completion (Codex review, PR #786: "Enforce the
        # streak breaker in every live executor" -- the finding named the
        # afternoon placement path alongside the morning executors).
        #
        # Counted on the explicit broker_placement_failed marker, NOT on the
        # status: only a real, broker-facing placement call that failed says
        # anything about broker health. A "blocked"/"skipped" candidate is a
        # deliberate policy decision made before any submission, and a
        # "failed" row can equally be this loop's own last-resort net catching
        # a raise that never reached the broker.
        #
        # A broker call HAPPENED, whatever the history could or could not say
        # about it. Kept separate from `raw_broker_placement_failed`, which is
        # the broker-HEALTH signal and is deliberately withheld when the order
        # history was unreadable -- see the `broker_call_attempted` comment at
        # its one producer. Every site that sets `broker_placement_failed` also
        # made a broker call, so the health marker implies this one. The
        # whole-share placement path also publishes the older
        # `broker_placement_attempted`/`broker_placement_succeeded` pair on its
        # own artifact row, and "attempted without success" answers this same
        # question there too, so keep that sibling input rather than making
        # those producers relearn the predicate.
        raw_broker_call_attempted = (
            bool(c_outcome.get("broker_call_attempted"))
            or raw_broker_placement_failed
            or (raw_broker_placement_attempted and not raw_broker_placement_succeeded)
        )
        # EXCEPT a confirmation-required hold, which sets `broker_placement_
        # failed` for the DIFFERENT reasons `_outcome_records_a_broker_
        # attempt`'s own docstring gives -- worth preserving through a
        # recovery merge, and worth counting toward the consecutive-failure
        # breaker just below, which is a broker-HEALTH question this status
        # legitimately answers ("Persist the placement-breaker halt in run
        # artifacts" was fixed FOR this exact status). Neither of those is
        # "did this consume an order-placement slot", which is what this
        # charge answers, and `OrderConfirmationRequiredError`'s own contract
        # says no: "no order was attempted and nothing needs retrying by this
        # run." `_orders_csv_attempt_counts` -- the CROSS-RUN reconstruction
        # this in-run counter must stay consistent with -- already excludes
        # this exact status for the same reason ("never reached the broker at
        # all"). Charging it here anyway meant two confirmation holds with
        # max_orders_per_day=2 consumed both of this run's slots and blocked
        # a later, genuinely tradable candidate, while restarting from this
        # same day's artifacts freed them straight back up (Codex review,
        # PR #786: "Exclude confirmation holds from the daily attempt
        # count"). Read off `c_outcome` -- the same outcome this charge and
        # the breaker below both key on -- not off the pre-merge candidate,
        # so a confirmation hold that a recovery merge folded a real order
        # into is judged by what actually happened today.
        #
        # `merged_confirmation_required`, not just the raw status, because a
        # recovery merge FORCES the row's status to "submitted" the moment
        # either side is a real submission -- `_merge_whole_share_submission_
        # outcomes` sets exactly this marker for that reason ("without one
        # the hold would vanish from the artifact entirely"). Reading only
        # `status` here missed the merged case: `broker_placement_failed`
        # survives the merge unchanged (inherited from today's own outcome),
        # but `status` no longer says "not_submitted_confirmation_required",
        # so today's hold was charged anyway even though it made no
        # placement attempt of its own (Codex review, PR #786: "Check the
        # pre-merge status before charging confirmation holds").
        if (
            c_outcome.get("status") == "not_submitted_confirmation_required"
            or c_outcome.get("merged_confirmation_required")
        ):
            raw_broker_call_attempted = False
        if raw_broker_call_attempted:
            # A broker-facing attempt that produced no order still CONSUMED a
            # `max_orders_per_day` slot, and until now only the success path
            # charged one. `config/budgets.json` states the contract -- "a
            # cancelled or rejected buy still consumes one -- the conservative
            # direction" -- and `seed_prior_allocation` already honours it when
            # a LATER run reconstructs today from artifacts, so the in-run
            # counter and the cross-run reconstruction disagreed about the same
            # events, with the in-run one permissive. Measured: with a cap of 3
            # and an alternating failure/success sequence, six broker calls go
            # out before `within_caps` blocks the seventh, and the next run
            # charges all six (Codex review, PR #786: "Count failed broker
            # calls toward the daily attempt cap"). The alternation also keeps
            # the consecutive-failure breaker permanently reset, so neither
            # limit stops it.
            #
            # Charged HERE rather than at each of the twelve sites that set
            # this marker: `raw_broker_placement_failed` is already the one
            # place that means "this candidate's own placement reached the
            # broker and produced no order", captured before the recovery
            # merge can rewrite it, and the breaker just below reads exactly
            # the same signal. Twelve edits would be the patch-don't-sweep
            # mistake this PR keeps re-learning.
            #
            # ZERO notional, because nothing was bought -- only the attempt
            # counters move.
            #
            # Charged UNCONDITIONALLY, once per broker-facing call. The first
            # version gated this on `own_orders_recorded`, borrowing the
            # success path's idiom -- and that set answers a DIFFERENT
            # question: "has artifact reconstruction already accounted for this
            # ticker?", not "has this broker call been counted?". An in-process
            # retry reusing the same `StrategyState` calls `place_market_buy`
            # again for the same ticker, and the guard silently swallowed every
            # charge after the first: measured, eight broker calls for one
            # ticker against a cap of 3 left `day_order_count()` at 1, and the
            # consecutive-failure streak is local to each batch invocation so
            # it does not stop them either (Codex review, PR #786: "Count
            # repeated broker calls when state is reused").
            #
            # That is the same rule two rounds running -- a predicate is chosen
            # for the QUESTION it answers -- and the same set, borrowed for the
            # wrong one twice.
            #
            # The success path KEEPS its guard, and the difference is the
            # notional: re-booking a duplicate recovery would inflate real
            # spend, while a second failed call moves only the attempt counter,
            # which is exactly what a second broker call should move.
            #
            # order_id=c_outcome.get("order_id"): several of the twelve
            # failure sites this charge covers (e.g. FractionalPlacement
            # RejectedError's own terminal response, or a reconciled
            # no-order verdict) DO know the broker's own id for this exact
            # attempt and already carry it on `c_outcome["order_id"]` --
            # leaving it off here left the attempt anonymous in
            # `recorded_attempt_order_ids`, so a LATER reconciliation for a
            # genuinely different ambiguous order on the same ticker/day
            # could mistake this attempt's own count for its target order's
            # already-durable charge and decline to restore it (Codex
            # review, PR #1164/#1165: "Pass known IDs into zero-dollar
            # attempt charges"). `record_buy` already no-ops safely on a
            # `None`/blank id for the many sites where none is known.
            ctx.state.record_buy(decision.ticker, ctx.trading_day, 0.0, order_id=c_outcome.get("order_id"))
            # And NOTHING is added to `own_orders_recorded` here. The first
            # version of this fix still marked the ticker there "for the
            # seeding dedup", which was the SAME borrowed-predicate error one
            # step smaller: that set means "this stream booked a REAL order for
            # this ticker today", and a broker call that produced no order is
            # not one. Two live readers take it at its word:
            #
            # * `_seed_prior_allocations` skips any ticker in it, so a later
            #   scan discovering that the day's aggregate has GROWN -- another
            #   stream bought the same ticker -- folded in neither the extra
            #   dollars nor the extra attempt, and the shared caps stayed at
            #   the stale figure (Codex review, PR #786: "Keep failed-attempt
            #   markers out of allocation deduplication").
            # * the duplicate-recovery site above gates `record_buy(
            #   dup_amount)` on it, so a real recovered fill for a ticker whose
            #   earlier call had failed would never have had its dollars booked
            #   at all.
            #
            # The dedup it was supposed to buy is already bought, and by a
            # mechanism that measures instead of guessing: `record_buy` above
            # makes `buys_today()` positive, and `reconcile_prior_allocation`
            # takes that exact ticker-specific count as its attempt baseline
            # and adds only the newly-discovered delta. Re-scanning this
            # failure's own artifact row therefore contributes zero, which is
            # the right answer, while a genuine later increase still lands.
        # The BREAKER still keys on the health marker alone: an unreachable
        # order history taught this run nothing about whether the broker is
        # refusing placements, and counting it would trip a breaker about
        # something else entirely.
        if raw_broker_placement_failed:
            consecutive_placement_failures += 1
            if (
                ctx.config.max_consecutive_placement_failures is not None
                and consecutive_placement_failures
                >= ctx.config.max_consecutive_placement_failures
            ):
                # Recorded in the ARTIFACT, not just the log. Breaking here
                # left every remaining candidate with no outcome at all, and
                # _build_buy_candidates serializes those as generic
                # "not_submitted" rows with a null skip_reason -- so
                # run_state.json could not say the breaker fired, nor which
                # orders were deliberately left unattempted. That gap bites
                # hardest in the all-confirmation-required case, which does
                # not increment errors_count either, leaving NO signal
                # anywhere (Codex review, PR #786: "Persist the
                # placement-breaker halt in run artifacts").
                # LOOP POSITION, not dict membership. candidate_outcomes is
                # pre-seeded before this loop starts, by
                # _reconcile_cross_day_whole_share_claims_for_batch, for
                # tickers that are ALSO in buy_candidates -- that is exactly
                # what `seeded_outcome` at the top of the loop reads. A
                # membership test therefore reads a seeded-but-never-reached
                # ticker as "already processed" and silently drops it from the
                # halt record, leaving its artifact row showing only the older
                # recovered submission and no sign that today's order was
                # never attempted (Codex review, PR #786: "Track processed
                # candidates when recording breaker skips"). Everything after
                # the candidate that tripped the breaker is unattempted by
                # construction, whatever is or is not in the dict.
                unattempted = buy_candidates[candidate_index + 1:]
                halt_reason = (
                    f"not attempted: batch halted after {consecutive_placement_failures} "
                    "consecutive placement failures "
                    "(circuit_breakers.max_consecutive_placement_failures)"
                )
                # The row that TRIPPED the breaker carries the marker too, not
                # only the tail. When the trip happens on the FINAL candidate
                # the tail is empty, so marking the tail alone leaves no row
                # anywhere saying the batch stopped. Run HEALTH is already
                # covered here by the unconditional errors_count_inc below --
                # unlike the executor, where the same zero-length tail let a
                # partially submitted run persist as an ordinary success
                # (Codex review, PR #786: "Mark the triggering outcome when
                # the breaker fires") -- but the ARTIFACT has to name the halt
                # either way, and keeping the two paths symmetric is what
                # stops the next consumer of this marker from inheriting the
                # executor's version of the bug.
                trigger_outcome = candidate_outcomes.get(decision.ticker)
                if isinstance(trigger_outcome, dict):
                    trigger_outcome["placement_breaker_halted"] = True
                    # "This row is where it tripped", as against the tail's
                    # "this row was skipped because it did".
                    trigger_outcome["placement_breaker_tripped_here"] = True
                    trigger_outcome["breaker_halt_reason"] = halt_reason
                    _publish_in_flight_outcome(decision.ticker, trigger_outcome)
                for unattempted_decision in unattempted:
                    unattempted_outcome = {
                        "status": "skipped",
                        "order_id": None,
                        "skip_reason": halt_reason,
                        # A deliberate policy stop, not a per-ticker block:
                        # nothing about THIS ticker failed, and no broker call
                        # was made for it, so it must not read as an attempt.
                        "deliberate_skip": True,
                        "submitted_amount_usd": 0.0,
                        "placement_breaker_halted": True,
                    }
                    seeded = candidate_outcomes.get(unattempted_decision.ticker)
                    if seeded is not None:
                        # A pre-roll recovery already published for this
                        # ticker. Both facts are true and neither may erase
                        # the other: an earlier order WAS recovered, and
                        # today's decision was NOT attempted. Overwriting
                        # would discard settled-spend evidence the recovery
                        # pass exists to preserve; leaving it alone would let
                        # the row read as if today's decision produced that
                        # submission. Annotate in place instead, on keys of
                        # their own so the recovery's own status/skip_reason
                        # stay exactly as it wrote them.
                        seeded["placement_breaker_halted"] = True
                        seeded["today_order_not_attempted"] = True
                        seeded["breaker_halt_reason"] = halt_reason
                        _publish_in_flight_outcome(
                            unattempted_decision.ticker, seeded
                        )
                        continue
                    candidate_outcomes[unattempted_decision.ticker] = unattempted_outcome
                    _publish_in_flight_outcome(
                        unattempted_decision.ticker, unattempted_outcome
                    )
                # Counted once so usage_proxy.manual_recovery_required is set
                # even when every failure in the streak was a
                # confirmation-required hold, which contributes nothing to
                # errors_count on its own. A tripped systemic breaker always
                # warrants a human look.
                errors_count_inc += 1
                logger.error(
                    "Halting the batch after %d consecutive placement failures "
                    "(circuit_breakers.max_consecutive_placement_failures); "
                    "%d candidate(s) never attempted: %s",
                    consecutive_placement_failures,
                    len(unattempted),
                    ", ".join(d.ticker for d in unattempted) or "none",
                )
                break
        elif raw_broker_placement_succeeded:
            # Reset on an explicit FRESH placement success, not on a
            # "submitted" status. A same-stream duplicate recovery also
            # returns "submitted" (duplicate_preserved=True) while making no
            # successful placement call of its own, so a
            # failure-duplicate-failure-failure sequence during an outage
            # would keep resetting the streak and never trip the breaker
            # (Codex review, PR #786: "Reset the breaker only after a fresh
            # placement succeeds"). An order this invocation placed and then
            # RECONCILED after a raise (the broker accepted it; the raise was
            # in the follow-up) does reset -- it is proof the broker leg
            # works. An earlier revision excluded those too, on the theory
            # that tripping sooner is the safe direction; it is not, when the
            # harm this whole change exists to prevent is tickers going
            # unbought. failure -> proven-accepted -> failure -> failure would
            # have tripped at three with only two CONSECUTIVE placement
            # failures (Codex review, PR #786: "Reset the streak after
            # reconciled fresh submissions").
            consecutive_placement_failures = 0

    return (
        candidate_outcomes,
        top_up_outcomes,
        running_deployed_7d,
        errors_count_inc,
        order_reviews_attempted_inc,
    )


# Placement outcomes for the run currently in flight, keyed so the failure
# handler can read whatever the batch had produced when it raised.
_IN_FLIGHT_CANDIDATE_OUTCOMES: Dict[str, Dict[str, Dict[str, Any]]] = {}


# The evaluation the run currently in flight had COMPLETED before it reached
# the broker. Published once, immediately after tier selection, so a failure
# after that point can write an artifact that says what was really evaluated
# instead of the all-zeros stub that only ever fit a startup failure.
#
# The same in-flight idiom as the outcomes above, and for the same reason: the
# values live in `_run_once_impl` locals that the raise unwinds past, and
# `run_once`'s handler has no other way to reach them. `state` and `config` are
# stored BY REFERENCE on purpose -- the budget block is built at write time, so
# it reports the caps as they stood when the run stopped, not as they stood at
# tier selection (Codex review, PR #859: "Preserve completed evaluation data in
# halt artifacts").
_IN_FLIGHT_RUN_EVALUATION: Dict[str, Any] = {}


def _publish_in_flight_evaluation(
    *,
    decisions: Sequence["ReconciledDecision"],
    config: "StrategyConfig",
    state: "StrategyState",
    trading_day: date,
    planned_spend: float,
    high_multiplier_signals: int,
    errors_count: int = 0,
) -> None:
    """Record what this run evaluated, for a failure writer that runs later.

    ``errors_count`` is everything ACCUMULATED before this call -- signal-
    evaluation provider errors, pre-roll whole-share reconciliation errors --
    not the eventual unresolved-placement error itself, which has not
    happened yet at the point this publishes. The failure writer's own
    synthesized ``usage_proxy.errors_count`` used to start over from
    ``max(1, orders_failed_count)``, discarding whatever this run had
    already accumulated before the halt: one provider error followed by one
    unresolved placement reported as a single error instead of two,
    understating usage/cost and incident telemetry (Codex review, PR #859
    round 28: "Preserve evaluation errors in halt telemetry").
    """
    _IN_FLIGHT_RUN_EVALUATION.clear()
    _IN_FLIGHT_RUN_EVALUATION.update(
        {
            "decisions": decisions,
            "config": config,
            "state": state,
            "trading_day": trading_day,
            "planned_spend": planned_spend,
            "high_multiplier_signals": high_multiplier_signals,
            "errors_count": errors_count,
        }
    )


# Whole-share orders the broker ACCEPTED during the candidate call currently
# in flight, before any outcome for them has been published. Keyed
# ticker -> (order_id, notional).
#
# _process_buy_candidates_batch's isolation net decides halt-vs-isolate by
# asking whether an outcome was already published: a published attempt means
# real capital went out, so the run fails closed rather than guessing at its
# deployment accounting. That test alone misses the whole-share path, which
# does a substantial amount of fallible work between the broker accepting the
# order and its first publish -- an order-history lookup, quantity parsing
# (``int(float(raw_filled_quantity))`` raises OverflowError on an oversized or
# infinite figure), ledger settlement. A raise anywhere in there left nothing
# published, so the net read it as a pre-broker failure and isolated a REAL
# accepted order out of deployment, cap, and attempt accounting entirely
# (Codex review, PR #786: "Halt on unpublished whole-share acceptances").
#
# This marker is the post-broker evidence that window lacks. It is set the
# instant ``place_whole_share_buy`` returns an order id and is deliberately
# NOT written into ``candidate_outcomes``: a provisional "submitted" entry
# there would be picked up by the batch loop's own mid-call-recovery merge and
# aggregated with the same order's real outcome, double-counting it.
_IN_FLIGHT_WHOLE_SHARE_ACCEPTANCES: Dict[str, tuple] = {}


#: The three answers order history can give about an ambiguous placement.
#: Deliberately three rather than two: "we could not find it" and "we proved
#: it does not exist" are different claims, and collapsing them is what round
#: 47 caught (Codex review, PR #786: "Do not treat an immediate history miss
#: as proof of rejection").
_PLACEMENT_ACCEPTED = "accepted"
_PLACEMENT_NO_ORDER = "no_order"
_PLACEMENT_UNKNOWN = "unknown"

#: Terminal states meaning the broker DECLINED the order outright -- it was
#: never working, so it cannot have executed anything. The complement within
#: _TERMINAL_BROKER_ORDER_STATES (cancelled/canceled/expired) means the order
#: EXISTED and was then killed, which can happen after a partial fill. Exactly
#: the distinction dca_runner._POST_ACCEPTANCE_TERMINAL_STATES draws for a
#: placement response, applied here to an order-history row.
_DECLINED_BROKER_ORDER_STATES = frozenset({"rejected", "failed", "voided"})

#: The states that positively mean "this order is working, or worked".
#: Mirrors dca_live_adapters._LIVE_ORDER_STATES, the set that module already
#: uses to decide whether a same-day order still occupies an idempotency slot.
#:
#: An ALLOWLIST rather than "not terminal", because those are not complements
#: over a broker payload that may be partial: a row carrying a usable id and a
#: missing, empty or unrecognized `state` was classified accepted and booked
#: for the full requested notional, when an incomplete terminal rejection has
#: exactly that shape (Codex review, PR #786: "Require a recognized state
#: before booking the order"). Booking fabricates deployment and resets the
#: failure streak; leaving it unknown costs a manual reconciliation.
_WORKING_BROKER_ORDER_STATES = frozenset(
    {"new", "queued", "confirmed", "unconfirmed", "partially_filled", "filled"}
)


def _unwrap_fill_alias_value(value: Any) -> Any:
    """Unwrap a Robinhood money value shaped ``{"amount": ...}`` to its scalar.

    A Robinhood money value is a scalar or an ``{"amount": ...}`` mapping, as
    ``_finite_nonnegative_float`` documents. Shared by every caller that
    scans the same seven fill-evidence aliases (``terminal_broker_row_proves_
    no_order``'s explicit-zero loop and ``_reconciled_order_may_have_
    executed``) so a mapping-shaped value reads the same way everywhere: two
    near-identical inline copies of this unwrap already disagreed once
    (Codex review, PR #859: "Require an explicit scalar zero before proving
    cancellation") -- the explicit-zero loop unwrapped nothing, so a BLANK
    mapping amount (``{"amount": ""}``) was read as the nonblank container
    itself rather than as the blank scalar it wraps, proving a cancelled/
    expired order's zero fill from a field that in fact told it nothing.

    Only a mapping that actually CARRIES an amount is unwrapped -- ``{}`` or
    ``{"amount": null}`` stays the container it is and falls through to
    the caller's own unreadable-value handling, which is what it is.
    """
    if isinstance(value, Mapping):
        amount = value.get("amount")
        if amount is not None:
            return amount
    return value


def terminal_broker_row_proves_no_order(order: Mapping) -> bool:
    """Whether a broker order row PROVES the broker is holding no live order.

    One implementation of a rule two callers need and neither may restate:
    :func:`_reconcile_ambiguous_fractional_placement` asks it of a row it read
    back out of the day's order HISTORY, and
    ``dca_live_adapters.RobinhoodBroker.place_market_buy`` asks it of the
    broker's own IMMEDIATE placement response before deciding whether a refusal
    is provable enough to let the batch continue past it. The two used to
    disagree, and every way they disagreed was a bug in the same direction --
    the adapter calling something proven that the reconciler treats as
    unresolved, so the batch placed later orders while a possible fill sat
    outside deployment and cap accounting (Codex review, PR #859: "Preserve
    execution evidence in terminal placement responses" and "Recognize every
    proven terminal no-order response").

    ``False`` for every shape short of proof, in this order:

    * conflicting ``state``/``status`` aliases on the SAME row -- both
      present, both nonblank, and disagreeing -- are not proof of anything;
      preferring one over the other silently could prove an order unplaced
      from a row that, read through its OTHER alias, says the exact
      opposite (Codex review, PR #859 round 25: "Reject conflicting
      lifecycle aliases within one order row");
    * a WORKING state (``queued``/``confirmed``/``filled``/...) is a possible
      acceptance, never a refusal;
    * a state that is neither recognizably working nor recognizably terminal is
      as likely an incomplete terminal rejection as a live order, and an
      allowlist is the only safe reading of a partial payload;
    * POSITIVE OR UNREADABLE FILL EVIDENCE OVERRIDES THE LABEL, on every
      terminal state including the declined ones. "Rejected means it was never
      working, so it cannot have executed" is true of a self-consistent broker
      row and is not true of the row in front of us:
      ``_recovered_broker_notional`` already treats positive execution evidence
      on EVERY settled state as real settled spend, and discarding the same
      evidence here would mark the placement proven-failed while the fill sat
      outside deployment, buying-power and cap accounting (Codex review,
      PR #786: "Inspect fills before declaring declined orders unplaced").

    ``True`` for the two shapes that ARE proof: a DECLINED state
    (``rejected``/``failed``/``voided``) the fill check did not contradict --
    an absent fill figure is expected there rather than suspicious, since a
    declined order has nothing to report -- and a ``cancelled``/``canceled``/
    ``expired`` order whose executed quantity is an EXPLICIT zero. Those
    EXISTED and were then killed, so they may have partially filled first, and
    only an explicit zero rules that out; an absent or unreadable figure leaves
    the executed amount unknown, never zero, which is the same reading
    ``_recovered_broker_notional`` gives it.
    """
    # Normalized via the SAME `_normalize_broker_lifecycle_alias` the
    # WORKING-branch conflict check in `_reconcile_ambiguous_fractional_
    # placement` uses -- this classifier and that check must never
    # disagree (see this function's own docstring), and a raw string
    # comparison here still read Robinhood's "cancelled"/"canceled"
    # spelling variants for the identical terminal state as a genuine
    # conflict, proving nothing for a row the other check would have
    # accepted (Codex review, PR #911 round 32: "Normalize lifecycle
    # aliases before declaring conflicts").
    _state_str = _normalize_broker_lifecycle_alias(order.get("state")) or ""
    _status_str = _normalize_broker_lifecycle_alias(order.get("status")) or ""
    if _state_str and _status_str and _state_str != _status_str:
        # Genuinely conflicting lifecycle aliases on ONE row -- {"id":
        # "ORD", "state": "rejected", "status": "queued"} -- cannot be
        # resolved by silently preferring one over the other. The plain
        # `state or status` fallback this replaced always picked "state"
        # when both were present, proving the order unplaced from a row
        # that, read through its OTHER alias, says the exact opposite
        # (Codex review, PR #859 round 25: "Reject conflicting lifecycle
        # aliases within one order row"). Not proof of anything, the same
        # verdict every other unresolved shape this function reads gets.
        return False
    state = _state_str or _status_str
    if state in _WORKING_BROKER_ORDER_STATES:
        return False
    if state not in _TERMINAL_BROKER_ORDER_STATES:
        return False
    if _reconciled_order_may_have_executed(order):
        return False
    if state in _DECLINED_BROKER_ORDER_STATES:
        return True
    # Scanned across the SAME alias set `_reconciled_order_may_have_executed`
    # just checked above -- not `cumulative_quantity` alone. That call
    # already returned False, meaning every field it read is either absent
    # or an explicit, parseable, non-boolean zero (it returns True for
    # anything else: a positive figure, an unreadable one, or a boolean).
    # Checking only `cumulative_quantity` here missed a row that reported
    # its zero fill through one of the other six aliases (e.g.
    # `filled_quantity: "0"`) -- present evidence, silently skipped, so the
    # row read as merely unreadable/absent and this whole check returned
    # False (unresolved) for a cancelled/expired order that had, in fact,
    # already proven its zero fill (Codex review, PR #859: "Accept explicit
    # zeroes from every supported fill alias"). Presence alone is enough to
    # prove it here, given the precondition above; no need to re-parse and
    # re-compare to zero. Unwrapped through the SAME mapping-aware helper
    # `_reconciled_order_may_have_executed` just used above -- reading the
    # raw field here let a mapping-shaped value with a BLANK amount
    # (`{"amount": ""}`) count as the nonblank container itself, proving a
    # zero fill from a field that in fact carried no reading at all (Codex
    # review, PR #859: "Require an explicit scalar zero before proving
    # cancellation").
    for _field in (
        "executed_notional",
        "executed_dollar_amount",
        "filled_notional",
        "cumulative_quantity",
        "executed_quantity",
        "filled_quantity",
        "quantity_filled",
    ):
        _value = _unwrap_fill_alias_value(order.get(_field))
        if not isinstance(_value, bool) and not _is_blank_broker_field(_value):
            return True
    return False


def _is_usable_reconciled_order_id(value: object) -> bool:
    """Whether a history row's id is one this run could actually track.

    The same validity rules ``dca_runner._is_usable_order_id`` applies to a
    placement response, restated here rather than imported -- `near_close_dca`
    does not depend on `dca_runner`, and the repo's convention for these two
    is to share the predicate's SHAPE, not its code.

    `_is_blank_broker_field` alone was not enough: it covers ``None``, ``""``
    and whitespace, and every other JSON-valid but unusable shape survived
    ``str(...)`` as a nonempty string -- ``true`` became ``"True"``, ``{}``
    became ``"{}"``, and ``0``/``-1``/``NaN`` became ordinary-looking numeric
    ids. Each of those was recorded as a successful submission carrying an id
    no later reconciliation can resolve (Codex review, PR #786: "Keep unusable
    reconciled IDs untrackable").
    """
    if value is None or isinstance(value, bool):
        return False
    if not isinstance(value, (str, int, float)):
        return False
    if isinstance(value, str):
        return bool(value.strip())
    # `math.isfinite()` converts to a float first, so a syntactically valid
    # but astronomically large JSON integer (`10**1000`) raises OverflowError
    # rather than returning False -- and this call sits inside a function this
    # module never wraps in a try/except, so the raise propagated all the way
    # out of `_reconcile_ambiguous_fractional_placement` and was caught by its
    # caller's OWN "the history could not be read" handler. That handler
    # withholds `broker_placement_failed`, so a broker returning this exact
    # shape on every retry never trips `max_consecutive_placement_failures` --
    # it advances only the separate daily-attempt cap (Codex review, PR #786:
    # "Guard oversized reconciled order IDs"). Unrepresentable is the same
    # verdict as unusable: no broker assigns an identifier a float cannot
    # hold, matching `dca_runner._numeric_value_is_unusable`'s reasoning for
    # the placement-response twin of this same id.
    try:
        if not math.isfinite(value):
            return False
    except OverflowError:
        return False
    return value > 0


def _reconciled_order_may_have_executed(order: dict) -> bool:
    """Whether a terminal history row reports, or fails to rule out, a fill.

    True for a POSITIVE figure and for an UNREADABLE one -- an unparseable
    quantity proves nothing either way, and this module reads that as unknown
    rather than zero everywhere else. An EXPLICIT null counts as unreadable
    too, not as absent: a key mapped to ``None`` is the broker actively
    reporting this alias, distinct from the key being missing entirely
    (Codex review, PR #859 round 25: "Keep explicit null fill evidence
    unresolved"). False only when every alias the row carries is either an
    EXPLICIT ZERO or genuinely absent.

    Reads ``executed_notional`` first, matching `_recovered_broker_notional`
    and `scripts/broker_reconciliation._executed_dollars`: it is the broker's
    own cent-precise settled figure.

    Also reads ``executed_dollar_amount`` and ``filled_notional`` --
    ``dca_runner._EXECUTED_NOTIONAL_KEYS``'s other two aliases for the same
    figure, which `_recovered_execution_exceeds_approved` (this module's
    sibling check, a few functions below) already recognizes. This function
    checked only ``executed_notional``, so a placement that raises whose
    exact-reference history row is ``{"id": "ORD", "state": "rejected",
    "filled_notional": 5}`` found nothing here, read as NO execution, and
    `_reconcile_ambiguous_fractional_placement` returned ``no_order`` --
    letting the run continue while a real $5 of reported spend never reached
    deployment, buying-power, or cap accounting (Codex review, PR #786:
    "Inspect every terminal execution-notional alias").

    Also reads ``executed_quantity``, ``filled_quantity``, and
    ``quantity_filled`` -- three more of `dca_runner._PARTIAL_FILL_EVIDENCE_
    KEYS`'s seven aliases for the same evidence, alongside `cumulative_
    quantity`. Checking only `cumulative_quantity` meant a DECLINED order
    reporting a fill solely through one of those three aliases (a whole-share
    quantity fill in a differently-normalized field) supplied no evidence
    here, and `terminal_broker_row_proves_no_order`'s declined-state branch
    then called it a proven no-order despite the reported fill (Codex review,
    PR #859: "Inspect all execution-quantity aliases before proving
    rejection").
    """
    for _field in (
        "executed_notional",
        "executed_dollar_amount",
        "filled_notional",
        "cumulative_quantity",
        "executed_quantity",
        "filled_quantity",
        "quantity_filled",
    ):
        # `_unwrap_fill_alias_value`: a Robinhood money value is a scalar or
        # an `{"amount": ...}` mapping, as `_finite_nonnegative_float`
        # documents. Read without unwrapping, the mapping form raised out of
        # `float()` below and returned True -- so `executed_notional=
        # {"amount": "0"}`, an EXPLICIT zero and the one figure that rules
        # execution out, was read as unreadable and an ordinary declined
        # order came back UNKNOWN instead of NO_ORDER. Swept here alongside
        # `_recovered_execution_exceeds_approved`, which had the same
        # blindness on the same shape (Codex review, PR #786: "Parse
        # supported mapping-shaped execution notionals").
        value = _unwrap_fill_alias_value(order.get(_field))
        if isinstance(value, bool):
            # Malformed, not a measurement -- and `float(False)` is `0.0`.
            return True
        if value is None and _field in order:
            # An EXPLICIT null -- ``{"id": "ORD", "state": "rejected",
            # "cumulative_quantity": null}`` -- is the broker actively
            # reporting this alias as unreadable, not omitting it.
            # ``dict.get`` cannot tell the two apart on its own (a missing
            # key and a key mapped to ``None`` both read back as ``None``),
            # so this loop treated an explicit null exactly like an absent
            # field and moved on to the next alias -- and once every alias
            # was either absent or explicitly null, fell through to the
            # same ``False`` this function returns for a row that supplies
            # NOTHING at all. That let a genuinely unreadable execution
            # measurement prove "no fill" instead of staying unresolved,
            # the opposite of this module's own convention (an unparseable
            # quantity proves nothing either way) applied everywhere else
            # in this function (Codex review, PR #859 round 25: "Keep
            # explicit null fill evidence unresolved").
            return True
        if _is_blank_broker_field(value):
            continue
        try:
            parsed = float(value)
        except (TypeError, ValueError, OverflowError):
            return True
        # An EXPLICIT ZERO is the only figure that rules execution out. `> 0`
        # read a NEGATIVE `executed_notional`/`cumulative_quantity` as proof
        # of no fill, so a declined row carrying `-5` returned
        # `_PLACEMENT_NO_ORDER` and the batch continued while whatever that
        # row really describes stayed out of cap accounting. A negative fill
        # is malformed evidence exactly like the boolean and non-finite cases
        # above -- it is not a measurement of "nothing was bought" (Codex
        # review, PR #786: "Treat negative fill measurements as ambiguous").
        #
        # Both siblings already read it that way, which is what makes this
        # the outlier rather than a new rule: `dca_runner`'s
        # `BrokerOrder.counts_toward_budget` trusts a negative
        # `executed_dollar_amount` as "counts" so `budget_snapshot()` can
        # raise on it, and `_combined_fill_evidence` classifies one as
        # `positive_or_unreadable`. This module's own terminal-row collector
        # has required "an EXPLICIT numeric zero ... not merely the absence
        # of a positive quantity" since long before this PR.
        #
        # `NaN`/`inf` need no separate test: neither equals zero.
        if parsed != 0:
            return True
    # Robinhood can report fills exclusively through a standard `executions`
    # collection instead of, or alongside, the top-level notional/quantity
    # aliases above: `{"state": "rejected", "executions": [{"quantity": "1",
    # "price": "5"}]}` carries no top-level fill alias at all, so the loop
    # above found nothing and this function returned False -- proving a
    # declined order unfilled while a confirmed execution row sat right next
    # to it, unread. Every row is treated the same way the top-level aliases
    # are: an explicit numeric zero quantity is the only reading that rules a
    # row out, and anything else -- positive, negative, non-numeric, or a
    # malformed (non-mapping) row -- is fill evidence this function cannot
    # rule out (Codex review, PR #1164: "Inspect execution rows before
    # proving a declined order unfilled").
    _executions = order.get("executions")
    if isinstance(_executions, list):
        for _execution in _executions:
            if not isinstance(_execution, dict):
                return True
            # Every alias is inspected, not just the first nonblank one:
            # `{"quantity": "0", "filled_quantity": "1"}` has a BLANK-ruling
            # "quantity" alongside a live "filled_quantity", and stopping at
            # the first nonblank alias read the row through "quantity" alone,
            # classified it as an explicit zero, and never looked at the
            # alias that actually confirmed the fill (Codex review, PR #1164:
            # "Inspect every quantity alias in execution rows"). One row can
            # supply the SAME evidence multiple aliases already require of
            # the top-level scan above it -- any single alias reporting
            # positive, negative, non-numeric, or a boolean is fill evidence
            # regardless of what an earlier-checked alias on the same row
            # said.
            _row_has_quantity_alias = False
            for _qty_field in (
                "quantity",
                "executed_quantity",
                "filled_quantity",
                "quantity_filled",
                "cumulative_quantity",
            ):
                _exec_quantity = _unwrap_fill_alias_value(_execution.get(_qty_field))
                if _is_blank_broker_field(_exec_quantity):
                    continue
                _row_has_quantity_alias = True
                if isinstance(_exec_quantity, bool):
                    return True
                try:
                    _parsed_exec_quantity = float(_exec_quantity)
                except (TypeError, ValueError, OverflowError):
                    return True
                if _parsed_exec_quantity != 0:
                    return True
            if not _row_has_quantity_alias:
                # No quantity alias at all -- an unreadable row, not a
                # proven zero -- is fill evidence this function cannot rule
                # out, the same reading a malformed (non-mapping) row gets
                # above.
                return True
    elif not _is_blank_broker_field(_executions):
        # A PRESENT but non-list `executions` -- a miswrapped single
        # execution object, `{"state": "rejected", "executions":
        # {"quantity": "1", "price": "5"}}`, rather than the standard
        # list-of-rows shape -- silently failed the `isinstance(...,
        # list)` guard above and fell straight through to `return False`,
        # the SAME reading a genuinely ABSENT `executions` field gets.
        # That treated a present-but-malformed collection as proof of no
        # fill instead of as unreadable evidence, letting a declined order
        # reporting a real execution through this one non-standard shape
        # be proven unfilled anyway (Codex review, PR #1164: "Treat
        # malformed execution collections as unresolved"). Blank (``None``/
        # ``""``/whitespace) is still read as genuinely absent, matching
        # every other field this function reads via `_is_blank_broker_
        # field` elsewhere.
        return True
    return False


def _recovered_execution_exceeds_approved(order: dict, approved_amount_usd) -> bool:
    """Whether a recovered history row reports spend the caps never approved.

    Reads the same executed spellings `dca_runner._EXECUTED_NOTIONAL_KEYS`
    does, and applies the same two rules: a figure ABOVE the approved amount is
    unaccounted spend, and a figure SUPPLIED but unreadable -- ``True``,
    ``"unknown"``, ``NaN``, a container -- or NEGATIVE cannot establish that
    real spend stayed inside the cap. An ABSENT figure is not evidence of
    anything and does not trip this: a `queued` order has not executed yet, and
    halting on its silence would refuse every ordinary recovery.

    Restated here rather than imported, matching this module's convention for
    its `dca_runner` counterparts: `near_close_dca` does not depend on
    `dca_runner`, and these two share the RULE, not the code.
    """
    if approved_amount_usd is None:
        return False
    try:
        approved = float(approved_amount_usd)
    except (TypeError, ValueError, OverflowError):
        return False
    if not math.isfinite(approved):
        return False
    for _field in ("executed_notional", "executed_dollar_amount", "filled_notional"):
        if _field not in order:
            continue
        # Parsed through this module's OWN money reader, not a local
        # `float()`. A Robinhood money value is either a scalar or an
        # `{"amount": ...}` mapping, which `_finite_nonnegative_float`
        # documents and unwraps -- and which the first version of this helper,
        # restating the rule instead of reusing the parser, read as unreadable:
        # measured, `executed_notional={"amount": "1.50"}` against an approved
        # $2 returned True and refused a perfectly ordinary $1.50 recovery.
        # That is the OVER-halt direction this PR exists to prevent, and it is
        # a defect the same parser had already been fixed for once (Codex
        # review: "Parse mapping-shaped executed notionals"), reintroduced one
        # module over by restating rather than reusing (Codex review, PR #786:
        # "Parse supported mapping-shaped execution notionals").
        #
        # `None` back from it still means SUPPLIED AND UNREADABLE here, because
        # the absent case has already returned above: bool, a container with
        # no `amount`, `"unknown"`, `NaN`/`inf`, an unbounded int, or a
        # NEGATIVE figure all land there, and none of them can establish that
        # real spend stayed inside the cap.
        executed = _finite_nonnegative_float(order.get(_field))
        if executed is None:
            return True
        if executed - approved > 0.001:
            return True
    return False


#: Requested-notional spellings on a broker history row. `dollar_amount` is
#: what the production adapter reports for a matched notional buy; `notional`
#: is the alias this module's duplicate-recovery path already falls back to.
_RECOVERED_REQUESTED_NOTIONAL_KEYS = ("dollar_amount", "notional")


def _recovered_requested_notional_conflicts(order: dict, approved_amount_usd) -> bool:
    """Whether a recovered history row was placed for an amount nobody approved.

    A separate question from :func:`_recovered_execution_exceeds_approved`, and
    the only one a WORKING row can answer: a `queued` order has not executed
    yet, so it carries no executed figure at all and the ceiling never fires --
    while the amount it was PLACED FOR is stated right there and settles
    whether this run can book it. Measured before the fix, an exact-reference
    row `{"id": "ORD", "state": "queued", "dollar_amount": 100}` recovered
    against an approved $2 returned ACCEPTED, and the caller booked the
    REQUESTED $2 while a live $100 order sat outside deployment, buying-power
    and every later candidate's cap check (Codex review, PR #786: "Validate
    requested notional in reconciled live orders").

    EQUALITY, not a ceiling, matching `dca_runner`'s chain check on the same
    field: the executed figure is compared as a ceiling because a partial fill
    below the request is ordinary, but the amount an order was placed for is
    either the amount the caps approved or it is a different order than the one
    this run placed. A supplied-but-unreadable figure conflicts too -- it
    cannot establish agreement -- while an ABSENT one does not, for the same
    reason absence does not trip the executed ceiling.
    """
    if approved_amount_usd is None:
        return False
    try:
        approved = float(approved_amount_usd)
    except (TypeError, ValueError, OverflowError):
        return False
    if not math.isfinite(approved):
        return False
    for _field in _RECOVERED_REQUESTED_NOTIONAL_KEYS:
        if _field not in order:
            continue
        requested = _finite_nonnegative_float(order.get(_field))
        if requested is None:
            return True
        if abs(requested - approved) > 0.001:
            return True
    return False


def _response_evidence_conflicts_with_matched_row(
    matched_order: dict,
    response_notional_usd: Optional[float],
    response_may_have_executed: bool = False,
) -> bool:
    """Whether a WORKING history row's own notional contradicts the fill
    THIS EXACT placement call's response already reported executing.

    The response that raised ``AmbiguousPlacementResponseError`` carries its
    OWN recovered execution notional (``response_notional_usd``) -- real
    evidence, not a guess, since it comes straight from the same terminal
    envelope that made the caller unable to prove a rejection. Discarding it
    the moment history is consulted let a STALE working row for the same id
    win outright: a response reporting `executed_notional=100` next to a
    freshly-queried `{"state": "queued", "dollar_amount": 2}` row (the
    APPROVED size) passed neither `_recovered_execution_exceeds_approved`
    nor `_recovered_requested_notional_conflicts` -- both compare only
    against the CAP, not against what the response itself already proved --
    so reconciliation returned ACCEPTED, and the caller booked the
    requested $2 while the response's own $100 fill vanished from
    deployment, buying-power and every later candidate's cap check (Codex
    review, PR #859 round 39: "Retain response fill evidence through
    reconciliation").

    No evidence to reconcile against (``response_notional_usd is None``,
    the ordinary case -- a raise for a reason OTHER than fill evidence, or a
    response the adapter could not itself read a notional from) leaves this
    check inert, matching the pre-existing behavior exactly. Evidence that
    IS present but that the row does not corroborate -- no comparable
    figure on the row at all, or one that disagrees outside a cent's
    tolerance -- is treated as unresolved rather than silently accepted:
    the response's own proof of execution outranks a row this call cannot
    show describes the same spend.
    """
    if response_notional_usd is None:
        # A response with execution-shaped evidence but no recoverable dollar
        # value cannot be corroborated safely by a later history row.
        return response_may_have_executed
    row_notional = _recovered_broker_notional(matched_order)
    if row_notional is None:
        for _field in _RECOVERED_REQUESTED_NOTIONAL_KEYS:
            row_notional = _finite_nonnegative_float(matched_order.get(_field))
            if row_notional is not None:
                break
    if row_notional is None:
        return True
    return abs(row_notional - response_notional_usd) > 0.01


def _reconcile_ambiguous_fractional_placement(
    ctx,
    ticker: str,
    ref_id: str,
    approved_amount_usd: float | Sequence[Optional[float]] | None = None,
    matched_order_out: Optional[Dict[str, Any]] = None,
    response_notional_usd: Optional[float] = None,
    response_may_have_executed: bool = False,
):
    """What the day's order history says about a placement that raised.

    Returns ``(verdict, order_id, accepted_amount_usd)`` where ``verdict`` is
    one of :data:`_PLACEMENT_ACCEPTED`, :data:`_PLACEMENT_NO_ORDER` or
    :data:`_PLACEMENT_UNKNOWN`. ``accepted_amount_usd`` is the specific
    candidate from ``approved_amount_usd`` that the ACCEPTED verdict
    validated against -- ``None`` for every other verdict -- so a caller
    checking several candidate amounts for one shared reference knows which

    ``matched_order_out``, when a caller passes a dict, is populated with
    the raw broker row this call matched (before it returns, on every
    outcome that reached a lookup at all) -- so a caller that also needs
    the row's own lifecycle/execution fields for something else (an
    execution-log entry, say) can read them from HERE, the single lookup
    this function already made, instead of repeating an identical,
    supposedly idempotent broker call that can itself transiently fail,
    return no row, or return an incomplete one on a second try -- silently
    discarding the FIRST call's already-proven evidence (Codex review, PR
    #911 round 36: "Reuse the broker row that proved the recovered fill").
    one to book, not merely that one of them matched. Re-raises when the
    history itself could not be read, which the caller reads as a fourth
    thing again: nothing was learned.

    ``RobinhoodBroker.place_market_buy`` is string-or-raise: it raises a plain
    ``RuntimeError`` for a broker refusing the ticker outright -- the reported
    RVII incident, where isolating is the whole point of this PR -- and for a
    connector that timed out while carrying an acceptance back, where the order
    is live and this run knows nothing about it. The exception cannot tell
    those apart, so the ``except`` site cannot either, which is why round 22's
    "halt on every raise" prescription was measured and rejected. What is
    available HERE is the deterministic per-order ``ref_id``, so the ambiguity
    can be RESOLVED rather than guessed at.

    ``approved_amount_usd`` accepts either a single figure or a sequence of
    them: a retried fractional placement can resize its requested amount
    between attempts while reusing the SAME deterministic ``ref_id`` (a
    persisted artifact can hold several unproven rows sharing one
    reference), and the broker lookup below names ONE order regardless of
    which amount is checked against it -- there is only one order at that
    reference, and only one lookup call is made no matter how many
    candidates are tried. Validating against a single (e.g. only-the-latest)
    recorded amount could report a genuine match for a DIFFERENT row's
    amount as a permanent conflict -- UNKNOWN forever despite an exact
    reference match (Codex review, PR #911 round 9: "Match grouped
    references against every attempted amount"). Each candidate is tried in
    order; the first that does not conflict decides ACCEPTED.

    Resolving it is not the same as reading an id, though, and the first
    version of this function did exactly that -- with three consequences it
    took a review round to see:

    * ``same_day_order_with_ref_id_prefix_any_state`` returns TERMINAL orders
      on purpose, and ``place_market_buy`` raises for exactly those states. So
      the ordinary rejection this PR exists to isolate came back carrying a
      broker id, and returning that id made the caller book the full requested
      notional as a successful submission and reset the failure streak -- a
      phantom buy, strictly worse than the bug being fixed (Codex review,
      PR #786: "Reject terminal history matches instead of booking
      submissions"). The state decides, not the presence of an id.
    * A match whose id is missing or blank was converted to "no match", so an
      order history had POSITIVELY FOUND became proof that none exists. That is
      round 39's rule -- rejecting an identifier is not concluding the thing it
      names does not exist -- broken in new code in the same round that cited
      it (Codex review, PR #786: "Preserve visible matches that lack a usable
      ID").
    * And a clean miss proves nothing at all. Robinhood's order history is
      eventually consistent, which this module documents in as many words a few
      thousand lines up: a just-accepted order may simply not be indexed yet.
      An immediate ``None`` is "not visible", never "does not exist" (Codex
      review, PR #786: "Do not treat an immediate history miss as proof of
      rejection").
    """
    lookup = getattr(ctx.broker, "same_day_order_with_ref_id_prefix_any_state", None)
    if lookup is None:
        # A broker that cannot answer the question has not answered "no".
        raise RuntimeError(
            "broker cannot reconcile an ambiguous placement: "
            "same_day_order_with_ref_id_prefix_any_state is unavailable"
        )
    matched_order = lookup(ticker, ctx.trading_day, (ref_id,))
    if not matched_order:
        return _PLACEMENT_UNKNOWN, None, None
    if isinstance(matched_order_out, dict):
        matched_order_out.clear()
        matched_order_out.update(matched_order)
    order_id = None
    for _key in ("id", "order_id"):
        if _is_usable_reconciled_order_id(matched_order.get(_key)):
            order_id = str(matched_order[_key]).strip()
            break
    if order_id is None:
        # Visible, but untrackable. Ambiguity, not absence.
        return _PLACEMENT_UNKNOWN, None, None
    # `order_id` above always prefers "id" over "order_id" -- correct when
    # only one alias is usable, but when BOTH are usable and DISAGREE
    # (``{"id": "A", "order_id": "B", "state": "queued", "dollar_amount":
    # 2}``), silently trusting "id" discards "B"'s own, possibly-live order
    # exactly as if history had never named it at all: the ACCEPTED branch
    # below would book "A" and continue while "B" disappears from
    # reconciliation and cap accounting for good (Codex review, PR
    # #859/#911 round 42: "Reject conflicting identifier aliases in
    # history rows"). Neither alias is more authoritative than the other,
    # so this is unresolved -- exactly the id-less case just above -- not a
    # pick.
    # Compared via `_normalized_order_id`, the same numeric-aware
    # canonicalizer this module already trusts for comparing a single
    # order's own id aliases, not a raw `str(...).strip()`: an exact-
    # reference history row repeating one supported numeric broker id
    # through different encodings (`id=123.0` alongside `order_id=123`)
    # is not a genuine disagreement -- `_normalized_order_id` already
    # canonicalizes both to the identical `"123"` -- but the raw string
    # comparison read the formatting difference alone as a conflict and
    # returned UNKNOWN for a valid working order, leaving the persisted
    # placement unresolved and blocking subsequent placements
    # indefinitely (Codex review, PR #1169: "Normalize equivalent IDs
    # before declaring a conflict").
    if (
        _is_usable_reconciled_order_id(matched_order.get("id"))
        and _is_usable_reconciled_order_id(matched_order.get("order_id"))
        and _normalized_order_id(matched_order["id"]) != _normalized_order_id(matched_order["order_id"])
    ):
        return _PLACEMENT_UNKNOWN, None, None
    # BOTH lifecycle aliases checked for a same-row conflict before either
    # is trusted to pick a branch below -- this used to read "state" alone,
    # so a row reporting `state="queued"` (working) alongside a
    # contradictory `status="rejected"` entered the WORKING branch on
    # "state" without ever consulting "status", even though
    # terminal_broker_row_proves_no_order (the identical-shape classifier
    # the terminal branch below already defers to) explicitly treats this
    # exact same-row conflict as unresolved. The artifact was then marked
    # proven and the requested amount booked from a broker row that
    # provides no CONSISTENT lifecycle evidence at all (Codex review, PR
    # #911 round 30: "Reject conflicting lifecycle aliases before
    # reconciliation"). Checked independently of which alias happens to be
    # non-blank, matching the SAME "state or status" fallback every other
    # lifecycle reader in this module and dca_live_adapters.py already use.
    #
    # Both values are normalized via ``_normalize_broker_lifecycle_alias``
    # before the comparison, not raw: a row supplying one real alias and
    # leaving the other an empty string (``state="queued", status=""``) is
    # the ordinary single-alias case, not a conflict, and Robinhood's own
    # "cancelled"/"canceled" spelling variants for the identical terminal
    # state are one answer, not two disagreeing ones (Codex review, PR
    # #911 round 32: "Normalize lifecycle aliases before declaring
    # conflicts"). See that function's docstring for the full reasoning.
    _state_normalized = _normalize_broker_lifecycle_alias(matched_order.get("state"))
    _status_normalized = _normalize_broker_lifecycle_alias(matched_order.get("status"))
    if (
        _state_normalized is not None
        and _status_normalized is not None
        and _state_normalized != _status_normalized
    ):
        return _PLACEMENT_UNKNOWN, order_id, None
    state = _state_normalized or _status_normalized or ""
    if state in _WORKING_BROKER_ORDER_STATES:
        # Working or filled: a real order this run must account for -- but for
        # HOW MUCH is a separate question, and the caller books the REQUESTED
        # amount on an accepted verdict. A row reporting more spend than the
        # caps approved is therefore accepted and then under-booked: measured,
        # `{"id": "ORD", "state": "filled", "executed_notional": 100}` for a
        # requested $2 recorded $2 and left $98 outside deployment,
        # buying-power and every later candidate's cap check (Codex review,
        # PR #786: "Validate recovered execution amounts before booking").
        #
        # Same rule as the placement classifier's executed-notional CEILING and
        # its supplied-but-unreadable test, reaching the reconciliation path --
        # which predates both. Below the approved amount is an ordinary fill;
        # above it, or supplied and unreadable, is spend this run cannot
        # account for, and UNKNOWN is what that means here: the id is carried
        # so the order stays reconcilable by hand, and the caller flags the run
        # rather than booking a figure it knows is wrong.
        #
        # ...and the amount the order was PLACED FOR is the other half of "for
        # how much", and the only half a WORKING row can answer at all: a
        # `queued` order has not executed, so the ceiling above finds nothing
        # to read, while `dollar_amount` states the size of the live order
        # right there. Measured before this check existed, a `queued` row for
        # $100 recovered against an approved $2 returned ACCEPTED and the
        # caller booked $2 (Codex review, PR #786: "Validate requested notional
        # in reconciled live orders").
        #
        # Checked ONCE here, before any candidate-amount logic below: unlike
        # the two conflict checks above (compared against the APPROVED cap),
        # this compares the row against what THIS EXACT response already
        # proved it executed -- independent of which approved candidate
        # amount is eventually tried, since a response reporting real
        # execution is disputed by a non-corroborating row no matter which
        # candidate size it is checked against. A stale queued row at the
        # approved size passes every candidate-amount check below yet still
        # contradicts a response reporting real fill evidence (Codex review,
        # PR #859 round 39: "Retain response fill evidence through
        # reconciliation").
        if _response_evidence_conflicts_with_matched_row(
            matched_order, response_notional_usd, response_may_have_executed
        ):
            return _PLACEMENT_UNKNOWN, order_id, None
        # Filled is classified as a working state, but it also carries settled
        # execution evidence. Validate all of that evidence even when the
        # ambiguous response itself supplied no notional; otherwise a direct
        # $5 notional conflicting with quantity*price=$200 could be accepted
        # and booked at the approved request amount.
        # A filled row with only a requested amount or an incomplete quantity
        # breakdown remains usable for the ordinary approved-amount checks.
        # Validate the stronger recovered-notional path only when it actually
        # has a positive or unusable direct execution alias to reconcile.
        _direct_execution_requires_validation = any(
            _field in matched_order
            and (
                _finite_nonnegative_float(matched_order.get(_field)) is None
                or _finite_nonnegative_float(matched_order.get(_field)) > 0
            )
            for _field in ("executed_notional", "executed_dollar_amount", "filled_notional")
        )
        if (
            state == "filled"
            and _direct_execution_requires_validation
            and _recovered_broker_notional(matched_order) is None
        ):
            return _PLACEMENT_UNKNOWN, order_id, None
        #
        # Tried against EVERY candidate amount, not just one: see this
        # function's own docstring for why a shared ref_id can carry more
        # than one recorded amount. The first candidate that conflicts with
        # NEITHER check decides ACCEPTED.
        _candidates = (
            approved_amount_usd
            if isinstance(approved_amount_usd, (list, tuple))
            else (approved_amount_usd,)
        )
        # Both conflict checks above read ABSENCE as "no conflict" -- exactly
        # right for a SINGLE candidate, where a queued order's silence about
        # its requested/executed notional is ordinary, not suspicious. But
        # with two or more DISTINCT candidate amounts sharing this ref_id (a
        # resized retry), that same silence cannot tell them apart either:
        # every candidate passes both checks identically, and the loop below
        # would always accept the FIRST one in file order regardless of
        # which candidate the real order was actually for. If the initial
        # attempt never reached the broker and a later resized retry is the
        # one that created this order, that silently books the STALE,
        # smaller amount and understates daily/weekly deployment -- exactly
        # the gap this function's own docstring says resolving is for (Codex
        # review, PR #911 round 26: "Keep indistinguishable resized attempts
        # unresolved"). Requires the SAME amount evidence the two conflict
        # checks themselves read (a readable dollar_amount/notional, or a
        # readable executed_notional/executed_dollar_amount/filled_notional)
        # before trusting either to have distinguished anything.
        _distinct_candidates = {c for c in _candidates if c is not None}
        if len(_distinct_candidates) > 1:
            if not any(
                _field in matched_order
                for _field in (*_RECOVERED_REQUESTED_NOTIONAL_KEYS, "executed_notional", "executed_dollar_amount", "filled_notional")
            ):
                return _PLACEMENT_UNKNOWN, order_id, None
            # Presence of SOME amount evidence is not the same as evidence
            # that picks one candidate over another: a below-every-candidate
            # `executed_notional` (approved $10/$12, executed $5) passes the
            # ceiling check against BOTH, and an absent `dollar_amount`
            # conflicts with neither, so every distinct candidate looked
            # equally consistent and the loop below silently accepted
            # whichever happened to come first in file order -- booking the
            # stale $10 attempt when the real order was the resized $12
            # retry, understating deployment and letting later orders past
            # caps that should have already been hit (Codex review, PR #911
            # round 28: "Require amount evidence that identifies one resized
            # attempt"). Only a reported value that is consistent with
            # EXACTLY ONE distinct candidate actually identifies which
            # attempt this order belongs to.
            _consistent_candidates = {
                _candidate
                for _candidate in _distinct_candidates
                if not _recovered_execution_exceeds_approved(matched_order, _candidate)
                and not _recovered_requested_notional_conflicts(matched_order, _candidate)
            }
            if len(_consistent_candidates) == 1:
                return _PLACEMENT_ACCEPTED, order_id, next(iter(_consistent_candidates))
            return _PLACEMENT_UNKNOWN, order_id, None
        for _candidate in _candidates:
            if _recovered_execution_exceeds_approved(matched_order, _candidate):
                continue
            if _recovered_requested_notional_conflicts(matched_order, _candidate):
                continue
            return _PLACEMENT_ACCEPTED, order_id, _candidate
        return _PLACEMENT_UNKNOWN, order_id, None
    if state not in _TERMINAL_BROKER_ORDER_STATES:
        # Neither recognizably working nor recognizably dead. A partial row is
        # as likely to be an incomplete terminal rejection as a live order, so
        # it is neither booked nor written off; the id rides on the failed row
        # for hand reconciliation.
        return _PLACEMENT_UNKNOWN, order_id, None
    # POSITIVE OR UNREADABLE FILL EVIDENCE OVERRIDES THE LABEL, on every
    # terminal state including the declined ones. "Rejected means it was never
    # working, so it cannot have executed" is true of a self-consistent broker
    # row and is not true of the row in front of us: `_recovered_broker_notional`
    # already treats positive execution evidence on EVERY settled state as real
    # settled spend, and this helper discarding the same evidence would mark
    # the placement proven-failed while the fill sat outside deployment,
    # buying-power and cap accounting (Codex review, PR #786: "Inspect fills
    # before declaring declined orders unplaced"). Round 29's rule again: a
    # carve-out no wider than the sentence justifying it.
    if _response_evidence_conflicts_with_matched_row(
        matched_order, response_notional_usd, response_may_have_executed
    ):
        return _PLACEMENT_UNKNOWN, order_id, None
    if terminal_broker_row_proves_no_order(matched_order):
        # A declined order the fill check did not contradict, or a
        # cancelled/expired one whose executed quantity is an EXPLICIT zero.
        # Preserve its id as terminal evidence; the verdict, not id presence,
        # decides whether the caller books a submission.
        return _PLACEMENT_NO_ORDER, order_id, None
    # Everything else this state can mean is real spend -- but not
    # necessarily an amount this function cannot compute: a terminal row
    # (cancelled, expired, rejected) that partially filled before settling
    # has the identical final notional a `filled` row has, and
    # `_recovered_broker_notional` already reads it the same authoritative
    # way (executed_notional, or a quantity*price reconstruction) that
    # `scripts/broker_reconciliation` does. Treating every one of these as
    # forever unresolved sent an already-settled partial fill to manual
    # recovery on EVERY subsequent invocation even once its final amount
    # was both readable and consistent with exactly one approved candidate
    # (Codex review, PR #911 round 28: "Settle terminal partial fills
    # during retry reconciliation"). Booking the full requested notional
    # when the final spend is genuinely unreadable would still overstate
    # it, so that case is unchanged: unresolved, carrying the id, and
    # errors_count -> manual_recovery_required does the rest.
    _final_notional = _recovered_broker_notional(matched_order)
    # POSITIVE, not merely readable: a cancelled/expired row that omits
    # every execution field entirely reaches `_recovered_broker_notional`'s
    # OWN "no fields at all" fallback, which returns 0.0 by that function's
    # design (see its docstring) so a claimed accumulator balance is
    # restored rather than written off -- but `terminal_broker_row_proves_
    # no_order` just above deliberately refused to call THIS SAME row a
    # proven zero-fill, because it requires an EXPLICIT zero cumulative_
    # quantity field, not mere absence of evidence. Treating that 0.0 as a
    # settled amount here selected the sole approved candidate and booked
    # the FULL approved notional as though the broker had confirmed a
    # fill, when it supplied no fill evidence at all (Codex review, PR
    # #911 round 32: "Require positive evidence before accepting terminal
    # fills"). An unreadable amount (``None``) already fell through to
    # UNKNOWN unchanged; this narrows the accepted branch to a genuine,
    # positive settled figure -- the explicit-zero case stays on the
    # no-order path above, and an ambiguous absence of evidence now stays
    # unresolved instead of silently becoming either one.
    if _final_notional is not None and _final_notional > 0:
        _candidates = (
            approved_amount_usd
            if isinstance(approved_amount_usd, (list, tuple))
            else (approved_amount_usd,)
        )
        # Same discipline as the working-order branch above: a final amount
        # consistent with more than one distinct candidate has not actually
        # identified which attempt this settled order belongs to, and must
        # stay unresolved rather than guess the first match in file order.
        #
        # The execution ceiling is not the only evidence a settled row can
        # carry, though: a row reporting BOTH a below-every-candidate
        # executed_notional AND a requested notional (dollar_amount et al.)
        # matching exactly ONE candidate -- e.g. executed_notional=1 with
        # candidates $5/$8, but dollar_amount=8 -- passed the ceiling
        # check against both $5 and $8 equally, so this loop kept both and
        # returned UNKNOWN forever even though the requested-notional
        # field uniquely identifies the $8 attempt. The working-order
        # branch already combines both checks
        # (_recovered_execution_exceeds_approved AND
        # _recovered_requested_notional_conflicts) for exactly this
        # reason; applying the same combination here settles the order
        # instead of blocking every future retry on it (Codex review, PR
        # #911 round 30: "Use requested notional to disambiguate terminal
        # partial fills").
        #
        # The ceiling itself is now `_recovered_execution_exceeds_approved`,
        # not a standalone `_final_notional <= approved + 1e-6` comparison,
        # for two reasons Codex review, PR #911 round 36 raised together.
        # First, a terminal row can carry CONFLICTING supported execution
        # aliases (e.g. executed_notional=5, filled_notional=100):
        # `_recovered_broker_notional` returns only the first positive one
        # it finds, so `_final_notional` alone never sees the other alias,
        # and a row that would make a WORKING-order recovery UNKNOWN
        # ("Validate all execution aliases before settling terminal
        # fills") settled here anyway. Second, `1e-6` is tighter than the
        # $0.001 tolerance `_recovered_execution_exceeds_approved` already
        # grants elsewhere in this reconciliation: a terminal partial fill
        # reconstructed from separately-rounded quantity/price fields (the
        # same reconstruction `_recovered_broker_notional`'s own docstring
        # documents) can miss an exact cent by more than a millionth of a
        # dollar and stay UNKNOWN forever on an otherwise-settled order
        # ("Reuse the monetary tolerance for terminal partial fills").
        # Checking every alias with the wider, already-shared tolerance
        # fixes both at once.
        #
        # But `_recovered_execution_exceeds_approved` -- per its own
        # docstring -- reads ONLY the three direct notional aliases
        # (executed_notional, executed_dollar_amount, filled_notional);
        # it never looks at a quantity*price RECONSTRUCTION. A settled
        # row reporting its fill exclusively through cumulative_quantity/
        # average_price (no direct alias at all) therefore has NOTHING
        # for that ceiling check to see -- it returns False, "not
        # exceeded", regardless of how large the reconstructed spend
        # actually is -- while `_final_notional` (computed above, the
        # SAME reconstruction) already knows the true figure. A cancelled
        # row with quantity=2, average_price=100 reconstructs to $200 but
        # was accepted and booked at a $5 approved candidate, leaving
        # $195 outside daily/weekly and kill-switch accounting (Codex
        # review, PR #911 round 37: "Check reconstructed notional against
        # approval"). Compared with the SAME $0.001 tolerance
        # `_recovered_execution_exceeds_approved` itself grants.
        _settled_candidates = set()
        for _candidate in _candidates:
            if _candidate is None:
                continue
            try:
                _approved_candidate = float(_candidate)
            except (TypeError, ValueError, OverflowError):
                continue
            if not math.isfinite(_approved_candidate):
                continue
            if (
                not _recovered_execution_exceeds_approved(matched_order, _approved_candidate)
                and _final_notional <= _approved_candidate + 0.001
                and not _recovered_requested_notional_conflicts(matched_order, _approved_candidate)
            ):
                _settled_candidates.add(_approved_candidate)
        if len(_settled_candidates) == 1:
            return _PLACEMENT_ACCEPTED, order_id, next(iter(_settled_candidates))
    return _PLACEMENT_UNKNOWN, order_id, None


def _mark_whole_share_acceptance(ticker: str, order_id: object, notional_usd: float) -> None:
    """Record that the broker accepted a whole-share order for ``ticker``.

    Called from the placement site itself, not from a return path, so it is
    already recorded no matter where the post-placement work raises.
    """
    _IN_FLIGHT_WHOLE_SHARE_ACCEPTANCES[ticker] = (order_id, notional_usd)


def _clear_whole_share_acceptance(ticker: str) -> None:
    """Drop any acceptance marker left over for ``ticker``.

    The batch loop calls this before each candidate rather than after, so a
    marker survives exactly the event it exists to report -- a raise between
    acceptance and publication -- while a marker from an earlier candidate,
    or from an earlier run in the same process, can never be mistaken for
    this one's.
    """
    _IN_FLIGHT_WHOLE_SHARE_ACCEPTANCES.pop(ticker, None)




def _failed_placement_count(outcomes: Mapping) -> int:
    """How many rows in ``outcomes`` are failed placements an operator must chase.

    One implementation for the failure writer's two branches: the synthesized
    state and the same-slot retry merge both report this figure, and the merge
    left it at the earlier attempt's value once attempt-specific keys began
    retaining a second unresolved call for the same ticker.

    Deduplicated by ``placement_ref_id`` when present: several attempt-
    specific ``broker_outcomes`` keys can share the identical ref_id -- the
    SAME deterministic broker call, retried -- and the gated fractional-
    placement reconciler's own shared-reference row collapse (see
    ``_reconcile_prior_unproven_fractional_placements``) already marks
    every one of them ``"failed"`` when the shared reference resolves as a
    terminal rejection, even though ``persisted["buy_candidates"]`` itself
    collapses to a single row for the one real order. Counting each raw
    row here reported N failures for that one broker call, overstating how
    many orders an operator actually needs to chase (Codex review, PR
    #911 round 21: "Deduplicate resolved failure counts by placement
    reference"). A row with no ref_id (a legacy shape, or one that
    genuinely never had one) is never deduped against anything else --
    it is always counted on its own, exactly as before.

    A literal ``status == "failed"`` row is not the only shape a failed
    placement takes: a whole-share (or same-day) recovery merge can force a
    row's aggregate ``status`` to ``"submitted"`` while still marking
    ``merged_placement_failed`` to say a FRESH placement failed underneath
    that merged recovery -- the exact same shape ``_apply_no_order_
    classification`` already recognizes for its own ``orders_failed_count``.
    Counting only the literal ``"failed"`` status here let the synthesized
    or merged halt artifact's own count disagree with that aggregate,
    underreporting how many broker attempts actually failed (Codex review,
    PR #859 round 32: "Count failures hidden inside merged submission
    rows").

    ``placement_ref_id`` is only trusted as a dedup key when it is a
    STRING. A readable, otherwise well-formed outcome from an older or
    damaged artifact can carry a malformed ``placement_ref_id`` -- a JSON
    object or list, say -- and ``ref_id in counted_refs`` raised
    ``TypeError: unhashable type`` on that value, aborting this call
    entirely instead of producing a count. Both callers of this function
    (prior-placement reconciliation and the unresolved-failure-artifact
    writer) have no fallback for that: the code handling one malformed row
    would itself abort before completing or refreshing the artifact, and
    every later retry would hit the identical crash on the same row
    forever (Codex review, PR #859/#911 round 44: "Validate reference IDs
    before deduplicating failures"). A non-string ref_id is treated the
    same as a missing one -- counted on its own, never deduped against
    anything -- rather than crashing the whole call over one malformed
    row.

    A WHITESPACE-ONLY ref_id (``"   "``) is treated the same way, not as
    a real shared reference: several damaged or legacy rows can each
    carry the identical blank placeholder, and a bare truthiness check
    (``ref_id`` alone, without stripping) reads a nonempty whitespace
    string as a genuine dedup key -- collapsing every failed row after
    the first into "already counted" and understating how many
    unresolved broker outcomes an operator actually needs to chase
    (Codex review, PR #1164: "Treat whitespace-only placement refs as
    missing"). Missing/blank ref_ids are already counted independently of
    each other, which is exactly the reading a shared blank placeholder
    needs too.
    """
    counted_refs: set = set()
    count = 0
    for outcome in outcomes.values():
        if not isinstance(outcome, dict):
            continue
        is_failed = outcome.get("status") == "failed" or (
            bool(outcome.get("merged_placement_failed")) and outcome.get("status") == "submitted"
        )
        if not is_failed:
            continue
        ref_id = outcome.get("placement_ref_id")
        if isinstance(ref_id, str) and ref_id.strip():
            if ref_id in counted_refs:
                continue
            counted_refs.add(ref_id)
        count += 1
    return count


def _unproven_retry_key(ticker: str, existing: Dict[str, Any]) -> str:
    """A collision-free ``broker_outcomes`` key for an ID-less unproven retry.

    The ordinary disambiguator is the order id, and an unproven placement is
    precisely the outcome that has none. Numbering the attempt keeps each
    retry's row instead of letting the second overwrite the first, and the real
    ticker travels INSIDE the outcome (see the merge site) so no consumer reads
    the synthetic key as a symbol.
    """
    attempt = 2
    while f"{ticker}:unproven-{attempt}" in existing:
        attempt += 1
    return f"{ticker}:unproven-{attempt}"


def _reconcile_prior_unproven_fractional_placements(
    ctx: RunContext,
    *,
    persist_stale_day_execution: bool = False,
) -> Dict[str, Dict[str, Any]]:
    """Settle persisted ambiguous placements before this run may place again.

    Returns a synthetic-keyed outcome (mirroring the inverse-Martingale
    recovery loop's own ``"<ticker>#imart-recovery"`` convention) for every
    reconciliation ACCEPTED on the SAME trading day as this invocation's
    own. The caller folds these into ``recovered_fire_outcomes`` before
    ``_process_buy_candidates_batch`` runs, because this function updates
    only the persisted artifact and ``ctx.state`` directly -- and that
    artifact is unconditionally overwritten the moment this run goes on to
    build its OWN fresh ``run_state.json``, which silently dropped the
    recovered submission (and, because deployment-history accounting sums
    submitted candidate rows rather than ``broker_outcomes``, its dollars
    from the trailing-seven-day kill switch too) unless something re-seeds
    it into that fresh build (Codex review, PR #911: "Publish recovered
    submissions into the fresh run artifacts"). A reconciliation for an
    EARLIER trading day is still booked into ``ctx.state``/the original
    artifact -- just never surfaced as a row in TODAY's candidates, exactly
    like the inverse-Martingale loop's own ``claim_trading_day != trading_day``
    scoping a few hundred lines below.

    ``persist_stale_day_execution`` controls whether an ACCEPTED
    reconciliation for an EARLIER trading day is also appended to
    ``ctx.run_result.execution_records`` -- the list ``run_daily_compact``'s
    own success-path write treats as RUN-SPECIFIC. Pass ``True`` only from
    the calendar-blocked caller, which never reaches that success-path
    write and merges ``execution_records`` into ``orders.csv`` itself
    immediately after this call returns -- the only route a blocked-day
    recovery has to reach the execution log at all. The ordinary gate-
    passing caller (trading open today) must leave this ``False``: when its
    ``artifacts_dir`` was reused and still carried unresolved evidence from
    an earlier day, appending unconditionally folded that earlier day's
    order into THIS run's own fresh ``orders.csv`` and fill totals even
    though ``run_daily_compact`` had already determined it was a different
    run (Codex review, PR #911 round 28: "Keep prior-day executions out of
    the current run log").
    """
    if not ctx.artifacts_dir:
        return {}
    # `_persist_cross_account_unresolved_evidence` writes THIS account's own
    # unresolved outcomes to a sibling sidecar file whenever the artifact's
    # existing `run_state.json` is fingerprinted for a DIFFERENT account and
    # cannot safely absorb them. No other runtime path ever reads that
    # sidecar back: a retry under the same (mismatched) account whose OWN
    # `run_state.json` happens to have no unproven rows of its own sailed
    # straight through this function and placed again, while the earlier,
    # possibly-live order recorded only in the sidecar stayed outside
    # deployment and cap accounting for good (Codex review, PR #1164:
    # "Reconcile account-scoped sidecar evidence before new placements").
    # Blocked here, before `run_state.json` is even read, rather than
    # attempting to reconcile the sidecar's broker outcomes the way the
    # main artifact's own unproven rows are reconciled below: the sidecar
    # can hold evidence from more than one mismatched attempt, and a human
    # resolving the underlying account misconfiguration is the same
    # "refuse until manually reconciled" posture this function already
    # takes for every other shape of evidence it cannot safely act on
    # itself.
    _cross_account_side_path = Path(ctx.artifacts_dir) / "cross_account_unresolved_placements.json"
    # A QUARANTINED sidecar (`_persist_cross_account_unresolved_evidence`'s
    # own `<name>.unreadable.<timestamp>` sibling, written whenever a prior
    # sidecar was itself unreadable or structurally malformed) is never
    # read by this reconciliation gate at all -- only the canonical path
    # above is. An unreadable sidecar containing account A's own only
    # possibly-live order can be quarantined here while a fresh canonical
    # file is written for a DIFFERENT account B's evidence; a later
    # account-A run then reads the canonical file, sees only B's
    # non-matching fingerprint, finds nothing of its own, and proceeds
    # with placement -- while A's quarantined evidence sits ignored
    # forever (Codex review, PR #1169: "Keep quarantined sidecars in the
    # reconciliation gate"). Blocks unconditionally whenever ANY quarantine
    # sibling exists: this function cannot safely parse or fingerprint-
    # match content it could not even read the first time, so the same
    # "refuse until manually reconciled" posture this function already
    # takes for a malformed canonical sidecar applies here too.
    if any(Path(ctx.artifacts_dir).glob(f"{_cross_account_side_path.name}.unreadable.*")):
        raise UnresolvedPlacementError(
            f"a quarantined cross-account unresolved placement sidecar exists alongside "
            f"{_cross_account_side_path}; refusing new placements until it is manually reconciled"
        )
    try:
        _cross_account_evidence = json.loads(_cross_account_side_path.read_text(encoding="utf-8"))
    except FileNotFoundError:
        _cross_account_evidence = None
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise UnresolvedPlacementError(
            "cannot read cross-account unresolved placement evidence; refusing new placements"
        ) from exc
    if _cross_account_evidence is not None:
        _cross_account_entries = (
            _cross_account_evidence.get("entries") if isinstance(_cross_account_evidence, dict) else None
        )
        # Fail closed on ANY unreadable shape -- a top-level value that is
        # not an object (`[]`), an "entries" field that is not a list
        # (`{"entries": {"saved": "row"}}`), or a list containing anything
        # but a readable dict row -- rather than silently treating it as
        # "nothing to reconcile". `_persist_cross_account_unresolved_
        # evidence` only ever writes the well-formed `{"entries": [...]}`
        # shape with dict rows itself, so any other shape means the file
        # was damaged (or produced some other way) -- and an unreadable
        # row may be exactly the unresolved placement this check exists to
        # catch, the same "malformed storage is not proof of nothing
        # unresolved" reasoning this function already applies to
        # `run_state.json`'s own `broker_outcomes` a few hundred lines
        # below (Codex review, PR #1164: "Reject malformed cross-account
        # sidecar structures"). A well-formed EMPTY list is the only shape
        # that safely means nothing is recorded.
        if not isinstance(_cross_account_entries, list) or not all(
            isinstance(_entry, dict) for _entry in _cross_account_entries
        ):
            raise UnresolvedPlacementError(
                f"cross-account unresolved placement evidence at {_cross_account_side_path} is "
                "malformed; refusing new placements until it is manually reconciled"
            )
        if _cross_account_entries:
            _current_fingerprint_for_side_check = _broker_account_fingerprint(
                ctx.broker, Path(ctx.artifacts_dir).parent
            )
            # A `None` fingerprint (the local HMAC key unavailable) cannot
            # rule out that one of the recorded entries belongs to THIS
            # account -- the same "cannot verify" reasoning the persisted-
            # account-fingerprint check a few lines below already applies
            # -- so it fails closed rather than silently skipping the
            # sidecar entirely.
            #
            # An entry recorded with `_ACCOUNT_FINGERPRINT_UNAVAILABLE_
            # SENTINEL` -- written by `_account_number_for_unresolved_
            # evidence` when THAT run could not compute its own
            # fingerprint -- is treated as matching every account, not
            # compared for equality like an ordinary fingerprint: the
            # sentinel is a non-empty string that can never equal a REAL
            # fingerprint, so a plain `==` check here permitted a run
            # whose fingerprinting later starts working again to sail
            # straight past an entry that might well be its own, exactly
            # the same "fingerprinting broke, so we lost the ability to
            # prove this ISN'T ours" case the sentinel exists to keep
            # unresolved on the read side (Codex review, PR #1164: "Block
            # on sidecar entries with unavailable fingerprints").
            #
            # An entry with a MISSING, blank, or otherwise malformed
            # `account_number` -- not even the sentinel, just an unusable
            # binding, e.g. `{"broker_outcomes": {...}}` with no
            # `account_number` key at all -- is the SAME "cannot verify"
            # shape as the sentinel: the earlier dict-only validation
            # accepts the row (it is still a readable dict), but this
            # equality/membership test then silently fails to match it
            # against either the current fingerprint or the sentinel, so
            # the row was treated as "confirmed a different account" and
            # ignored even though nothing here actually proves that. If
            # that row is the only durable record of a possibly-live
            # placement, a later invocation could place again with it
            # excluded from deployment and cap accounting (Codex review,
            # PR #1164: "Reject sidecar entries without a valid account
            # binding").
            #
            # A NONBLANK string that is neither the sentinel nor shaped
            # like a real fingerprint (`_LEASE_ACCOUNT_FINGERPRINT_LENGTH`
            # lowercase hex characters -- see `_broker_account_fingerprint`)
            # is the identical "cannot verify" shape one level further:
            # `{"account_number": "garbage", ...}` matches neither the
            # current fingerprint nor the sentinel by equality, so it
            # sailed through the check above exactly like the missing/
            # blank case it was meant to catch, silently treated as
            # "confirmed a different account" (Codex review, PR #1164:
            # "Validate nonblank sidecar fingerprints by shape").
            if _current_fingerprint_for_side_check is None or any(
                not isinstance(_entry.get("account_number"), str)
                or not _entry.get("account_number", "").strip()
                or _entry.get("account_number") in (
                    _current_fingerprint_for_side_check,
                    _ACCOUNT_FINGERPRINT_UNAVAILABLE_SENTINEL,
                )
                or not re.fullmatch(
                    f"[0-9a-f]{{{_LEASE_ACCOUNT_FINGERPRINT_LENGTH}}}",
                    _entry.get("account_number", ""),
                )
                for _entry in _cross_account_entries
            ):
                raise UnresolvedPlacementError(
                    f"unresolved placement evidence for this account is recorded in "
                    f"{_cross_account_side_path} (could not be merged into run_state.json "
                    "because that artifact belongs to a different account); refusing new "
                    "placements until it is manually reconciled"
                )
    state_path = Path(ctx.artifacts_dir) / "run_state.json"
    # The existence check itself must happen behind the lock, not just the
    # later writes: a concurrent retry can be between acquiring this same
    # sidecar and its own atomic publish of a first-ever run_state.json, so
    # an unlocked `state_path.exists()`/read here can observe "nothing yet"
    # and skip reconciliation entirely, sailing past evidence that writer is
    # about to record (Codex review, PR #1166: "Check for prior evidence
    # only after acquiring the lock"). The lock is released as soon as the
    # read completes -- the broker call and the eventual writes below take
    # it again on their own -- so this only serializes the read against a
    # concurrent writer's publish, not the (potentially slow) broker I/O.
    try:
        with cross_process_lock(state_path.with_name(f"{state_path.name}.lock")):
            try:
                raw_state_text = state_path.read_text(encoding="utf-8")
            except FileNotFoundError:
                return {}
            except (OSError, UnicodeDecodeError) as exc:
                raise UnresolvedPlacementError(
                    "cannot read prior placement evidence; refusing new placements"
                ) from exc
    except TimeoutError as exc:
        raise UnresolvedPlacementError(
            "could not acquire the run-state lock to check for prior placement "
            "evidence; refusing new placements"
        ) from exc
    try:
        persisted = json.loads(raw_state_text)
    except json.JSONDecodeError as exc:
        raise UnresolvedPlacementError(
            "cannot read prior placement evidence; refusing new placements"
        ) from exc
    # The exact on-disk bytes this function's in-memory `persisted` was
    # built from. Every write below is a full-document replace built from
    # accumulated in-memory state, not an incremental patch -- so before
    # each one, the lock is used to verify the file still holds exactly
    # this text. A mismatch means some OTHER writer (an overlapping retry
    # that shares this artifact directory) published newer evidence in the
    # gap between this read and that write -- e.g. its own recovered order
    # -- and blindly overwriting it with this invocation's now-stale
    # snapshot would silently discard that evidence (Codex review, PR
    # #1166: "Merge fresh run state before reconciliation writes"). Safely
    # merging two independently-evolved snapshots of this many
    # interdependent aggregate fields (broker_outcomes, buy_candidates,
    # placement_evidence_incomplete, the *_count fields) is not something
    # this function can do correctly in general, so it fails closed instead
    # -- the same posture it already takes for every other shape of
    # evidence it cannot safely act on itself.
    _last_known_state_text = raw_state_text
    # `json.loads` succeeds on any valid JSON document, not just an object --
    # a damaged run_state.json that degraded to a top-level list or scalar
    # (e.g. "[]", "null", "42") parses cleanly, and the very next line's
    # `persisted.get(...)` then raises a plain, UNCAUGHT AttributeError
    # instead of the fail-closed UnresolvedPlacementError every other
    # malformed-evidence shape in this function already raises. That
    # AttributeError propagates out of this function entirely, and
    # run_once()'s own exception handling forwards it to
    # _write_afternoon_failure_artifacts, whose non-object branch REPLACES
    # the original (still explicitly unresolved) file with a synthesized
    # startup-failure state -- destroying the only on-disk record of the
    # possibly-live placement instead of preserving it for manual recovery
    # (Codex review, PR #911 round 38: "Preserve non-object placement
    # evidence"). Raising HERE, before any `.get()` call, keeps this
    # exactly like every other malformed shape: fail closed without ever
    # reaching a code path that could overwrite the evidence.
    if not isinstance(persisted, dict):
        raise UnresolvedPlacementError(
            "prior placement evidence is not a JSON object; refusing new "
            "placements"
        )
    outcomes = persisted.get("broker_outcomes")
    if not isinstance(outcomes, dict):
        # A malformed broker_outcomes (null, a list, ...) is not proof there
        # is nothing to reconcile -- an artifact that explicitly says
        # placement_evidence_incomplete=true is telling us the OPPOSITE: an
        # unresolved placement exists, and its storage merely got corrupted
        # (or damaged/produced externally) in a way that also broke the
        # column reconciliation itself needs to read. Reading malformed
        # storage as "nothing unresolved" let a live retry issue another
        # broker order on top of a placement that may already be live, and
        # let a dry run reach its own normal finalizer, which unconditionally
        # overwrites run_state.json -- permanently deleting the only
        # remaining evidence (Codex review, PR #911 round 28: "Fail closed
        # on malformed unresolved outcome storage"). Silently returning
        # empty stays correct only when the artifact itself agrees there is
        # nothing unresolved.
        if persisted.get("placement_evidence_incomplete"):
            raise UnresolvedPlacementError(
                "prior placement evidence storage is malformed but the artifact "
                "reports incomplete placement evidence; refusing new placements"
            )
        return {}
    # The SAME fail-closed reasoning as the malformed-container check just
    # above, one level deeper: a `broker_outcomes` mapping whose entries
    # are not ALL readable dicts is not confirmed clean either -- a
    # malformed entry may be exactly the unresolved placement the
    # artifact's own placement_evidence_incomplete flag is about, its
    # storage corrupted the same way the whole-container case above
    # already guards against (Codex review, PR #911 round 30: "Fail
    # closed when flagged evidence has no readable rows"; round 35: "Fail
    # closed on mixed malformed outcome storage").
    #
    # Checked HERE, unconditionally, BEFORE `unproven_keys` is computed --
    # not only when `unproven_keys` ends up empty. A mapping with one
    # readable, genuinely UNPROVEN row alongside a separate malformed
    # entry has a nonempty `unproven_keys`, so a check placed only inside
    # `if not unproven_keys:` never ran at all: the readable row goes on
    # to reconcile normally, and once it resolves, the fresh
    # `placement_evidence_incomplete` recomputation a few hundred lines
    # down derives its value from dict rows only -- silently clearing the
    # flag while the malformed entry, which may represent an entirely
    # separate live placement, was never examined even once (Codex
    # review, PR #911 round 37: "Reject malformed rows even alongside
    # unresolved rows").
    if persisted.get("placement_evidence_incomplete") and not all(
        isinstance(raw, dict) for raw in outcomes.values()
    ):
        raise UnresolvedPlacementError(
            "prior placement evidence reports incomplete placement evidence "
            "but no readable unresolved row could be recovered; refusing "
            "new placements"
        )
    unproven_keys = [
        key
        for key, raw in outcomes.items()
        if isinstance(raw, dict) and raw.get("placement_outcome_unproven")
    ]
    if not unproven_keys:
        # Every entry has already been confirmed a readable dict by the
        # check above, so the only remaining "all clear" this scan cannot
        # actually vouch for is a `broker_outcomes` mapping that is
        # EMPTY -- `all(...)` over zero items is vacuously True and would
        # otherwise let this fall through as a silent pass, even though
        # the artifact's own flag says an unresolved placement genuinely
        # exists somewhere this scan found nothing at all to read (Codex
        # review, PR #911 round 30: "Fail closed when flagged evidence
        # has no readable rows"). A mapping that is non-empty and (per
        # the check above) fully readable -- even when every one of its
        # rows is proven/resolved, none unproven -- has actually been
        # read in full and confirmed clean, which is a fundamentally
        # different, legitimate "nothing unresolved" than data this scan
        # never got to see at all. Raising on THAT case too would fail
        # closed on every ordinary fully-resolved retry that happens to
        # share an artifact with an unrelated failure that (over
        # broadly) set the flag -- exactly the false-positive round 28's
        # own fix required narrowing test_a_malformed_prior_broker_
        # outcomes_does_not_abort_a_successful_retry for.
        if persisted.get("placement_evidence_incomplete") and not outcomes:
            raise UnresolvedPlacementError(
                "prior placement evidence reports incomplete placement evidence "
                "but no readable unresolved row could be recovered; refusing "
                "new placements"
            )
        return {}
    # A dry run must never perform the broker reconciliation itself below
    # (it makes real broker calls and books real spend into ctx.state) --
    # but bailing out BEFORE ever reading the artifact, as this used to,
    # let a dry run that reuses a directory containing a genuinely
    # unresolved placement from an earlier LIVE invocation reach its own
    # normal finalizer, which unconditionally overwrites run_state.json
    # with a fresh simulated artifact. That permanently deleted the only
    # on-disk reference to a possibly-still-live broker order: no later
    # invocation (dry-run or live) can ever reconstruct it from an
    # overwritten file, and a subsequent live run could place a genuine
    # duplicate (Codex review, PR #911 round 20: "Preserve unresolved live
    # evidence during dry runs"). Fail closed instead, the same way an
    # unreadable artifact already does a few lines up: the caller's own
    # failure-artifact writer preserves this evidence untouched, and the
    # dry run's fresh-overwrite finalizer is never reached.
    if ctx.config.dry_run:
        raise UnresolvedPlacementError(
            "dry run reused a directory containing unresolved live placement "
            "evidence; refusing to let a simulated run overwrite it"
        )

    # Bound to the account that WROTE this artifact, when it recorded one:
    # account pinning only proves the CURRENTLY injected broker matches the
    # current config, not that this persisted artifact came from that same
    # account. A deterministic stream/date/ticker ref_id can exist under two
    # DIFFERENT configured accounts if an artifacts directory is ever reused
    # after switching between them, and without this check that collision
    # would let this account's broker history "prove" the OTHER account's
    # ambiguous row, booking the wrong exposure while the real placement
    # stays unresolved (Codex review, PR #911: "Bind persisted reconciliation
    # evidence to the broker account"). A missing/null value predates this
    # field and is not itself proof of a mismatch, so it is not rejected --
    # only an explicit, different account is. Compared as the SAME
    # non-reversible keyed fingerprint build_run_artifacts stamps, never the
    # raw account number (Codex review, PR #911 round 3: "Persist a
    # non-sensitive account fingerprint instead") -- the key_dir must match
    # the one used at write time (beside, not inside, the artifacts tree)
    # for the two fingerprints to ever agree.
    #
    # Checked ONLY NOW that there is unresolved evidence to bind, not
    # earlier: a completed artifact with no unproven rows at all needs no
    # broker-history trust and the normal finalizer can safely replace it,
    # so a correctly-pinned run reusing a directory left by a DIFFERENT
    # account's earlier, fully-resolved run must not be blocked just
    # because that leftover artifact happens to carry the other account's
    # fingerprint (Codex review, PR #911 round 7: "Check artifact
    # fingerprints only for unresolved evidence").
    persisted_account_fingerprint = persisted.get("account_number")
    # A PRESENT but non-string value -- an int, a list, a mapping, from a
    # damaged or externally produced artifact -- is not the same thing as
    # an absent/null legacy binding: it is an explicit account_number this
    # function cannot read, and the `isinstance(..., str)` check below
    # treated both the same way, skipping verification entirely and
    # reconciling against the current broker unverified. This function
    # already fails closed on malformed dates and placement rows for the
    # identical reason -- an unreadable claim must not be treated as
    # proof of nothing wrong (Codex review, PR #911 round 25: "Reject
    # malformed persisted account fingerprints"). An explicit empty or
    # whitespace-only string is the same failure in a different shape --
    # it is a present, non-null claim that carries no actual fingerprint
    # to verify, not a legacy artifact that never recorded one, so it
    # must fail closed the same way rather than silently falling through
    # to the legacy-skip branch below (Codex review, PR #911 round 28:
    # "Reject empty persisted account fingerprints").
    if persisted_account_fingerprint is not None and (
        not isinstance(persisted_account_fingerprint, str) or not persisted_account_fingerprint.strip()
    ):
        raise UnresolvedPlacementError(
            "prior placement evidence carries a malformed account fingerprint; "
            "refusing to reconcile it against this account's broker history"
        )
    if isinstance(persisted_account_fingerprint, str) and persisted_account_fingerprint:
        current_account_fingerprint = _broker_account_fingerprint(
            ctx.broker, Path(ctx.artifacts_dir).parent
        )
        # A `None` here means the local HMAC key could not be read or
        # created (see _lease_fingerprint_key), NOT that the account
        # matches -- silently skipping the whole check in that case let a
        # reused artifacts directory's evidence sail through unverified
        # whenever the key happened to be unavailable, defeating the exact
        # binding this check exists for (Codex review, PR #911 round 6:
        # "Fail closed when the current fingerprint is unavailable"). The
        # persisted evidence explicitly claims a fingerprint; being unable
        # to compute this run's own is "cannot verify", which this
        # function already treats as grounds to refuse everywhere else.
        if current_account_fingerprint is None:
            raise UnresolvedPlacementError(
                "cannot compute this account's fingerprint to verify prior "
                "placement evidence; refusing new placements"
            )
        if current_account_fingerprint != persisted_account_fingerprint:
            raise UnresolvedPlacementError(
                "prior placement evidence was recorded for a different account; "
                "refusing to reconcile it against this account's broker history"
            )

    # The BROKER LOOKUP and the BOOKING must use the day this evidence was
    # actually recorded for, not today's: a reused artifacts directory can
    # carry evidence from an earlier trading day, and querying/booking
    # against today's date would neither find the exact order (the same-day
    # lookup is scoped by date) nor charge the right daily/weekly bucket if
    # a match were somehow returned anyway (Codex review, PR #911:
    # "Reconcile using the persisted placement date"). Missing or malformed
    # evidence of WHICH day this was is treated the same as any other
    # incomplete evidence below: fail closed rather than guess "today".
    try:
        evidence_trading_day = date.fromisoformat(str(persisted.get("trading_day")))
    except (TypeError, ValueError) as exc:
        raise UnresolvedPlacementError(
            "prior placement evidence carries no valid trading_day; refusing new placements"
        ) from exc
    today = ctx.now.astimezone(EASTERN).date()
    # The STREAM this evidence belongs to, not just its date: a same-day
    # artifacts directory can be reused by a DIFFERENT scheduled slot (the
    # morning/midday/afternoon roster all run against the same trading day),
    # and matching on date alone published a morning or midday recovery into
    # an afternoon-classified candidate row, so
    # dca_risk.is_afternoon_scheduled_evidence() counted non-afternoon
    # capital in the afternoon kill-switch stream instead of preserving its
    # actual provenance (Codex review, PR #911 round 4: "Preserve the
    # originating stream for recovered orders"). Missing/malformed is not
    # itself proof of a mismatch -- an artifact predating this field, or one
    # this stream itself wrote -- so only an explicit, different stream
    # withholds same-day surfacing.
    _persisted_classification = persisted.get("run_classification")
    persisted_stream = (
        _persisted_classification.get("stream")
        if isinstance(_persisted_classification, dict)
        else None
    )
    # The identity of the SOURCE ARTIFACT this evidence came from -- the
    # same nested-or-top-level fallback every other run_id reader in this
    # codebase uses -- so book_reconciled_attempt_notional can mark
    # exactly this run as already-recovered, letting _seed_prior_
    # allocations recognize a same-stream retry's own rediscovery of it
    # (Codex review, PR #911 round 30: "Avoid reseeding a recovered
    # earlier-slot attempt"). None when absent/malformed is not itself a
    # problem: it simply means this recovery cannot be matched against a
    # PriorSameDayAllocation's own attempt_run_ids, so seeding falls back
    # to its ordinary (pre-existing) behavior for that ticker.
    _persisted_run_id = (
        _persisted_classification.get("run_id")
        if isinstance(_persisted_classification, dict) and _persisted_classification.get("run_id")
        else persisted.get("run_id")
    )
    # The RUN ORIGIN this evidence belongs to, not just its named stream: a
    # manual run's own run_classification carries no "stream" key at all
    # (see scripts.run_classification.build_manual_classification), so
    # `persisted_stream is None` -- the permissive branch above, meant for an
    # artifact that predates this field -- also passed trivially for every
    # manual run's evidence, publishing a manual recovery into a same-day
    # SCHEDULED artifact's own candidates/execution log (or the reverse) and
    # letting dca_risk.classify_stream() attribute manual-run capital to the
    # scheduled kill-switch stream, or vice versa (Codex review, PR #911
    # round 8: "Preserve the originating run type for recovered rows").
    # Reuses dca_risk.classify_stream() itself rather than restating its
    # manual/scheduled rule, so the two can never read the same block
    # differently. STREAM_OTHER (missing, or present but not validly
    # scheduled) stays permissive, matching `persisted_stream is None` above.
    from dca_risk import STREAM_MANUAL, STREAM_OTHER, STREAM_SCHEDULED, classify_stream

    _persisted_run_type = classify_stream(persisted)
    _current_run_type = STREAM_SCHEDULED if ctx.scheduled else STREAM_MANUAL
    _run_type_compatible = (
        _persisted_run_type == STREAM_OTHER or _persisted_run_type == _current_run_type
    )

    # GROUPED BY REFERENCE, not reconciled per row. A retried fractional
    # placement reuses the SAME deterministic ref_id for a given ticker,
    # stream and day, and _unproven_retry_key lets several unproven rows
    # for that ticker accumulate under distinct keys across retries.
    # Reconciling and booking each row independently found the SAME
    # accepted broker order every time and booked its notional once PER
    # ROW instead of once per order (Codex review, PR #911: "Deduplicate
    # recovered rows by broker reference or order ID").
    groups: Dict[str, List[str]] = {}
    row_ticker_amount: Dict[str, tuple[str, float, Optional[float], bool]] = {}
    for key in unproven_keys:
        raw = outcomes[key]
        ticker = str(raw.get("ticker") or str(key).split(":", 1)[0]).strip().upper()
        ref_id = raw.get("placement_ref_id")
        amount = _finite_nonnegative_float(raw.get("submitted_amount_usd"))
        # STRICTLY positive, not merely readable-and-nonnegative: the
        # placement path never submits a non-positive order, so a
        # persisted $0 approved amount is not a legitimate small placement
        # -- it is damaged or externally produced evidence. Accepting it
        # let a working broker row that omits requested/executed-notional
        # fields (an ordinary, unremarkable shape for a `queued` order)
        # match the sole $0 candidate by default, after which the artifact
        # was marked resolved and the real broker order was booked at $0 --
        # permanently omitting its exposure from daily/weekly deployment
        # and letting later orders past the caps (Codex review, PR #911
        # round 29: "Reject zero-dollar unresolved placement evidence").
        if not ticker or not isinstance(ref_id, str) or not ref_id.strip() or amount is None or amount <= 0:
            raise UnresolvedPlacementError(
                f"prior placement evidence for {ticker or 'unknown ticker'} is incomplete"
            )
        ref_id = ref_id.strip()
        # Carried alongside ticker/amount so the reconciliation call below
        # can supply it to `_reconcile_ambiguous_fractional_placement`
        # exactly like the in-process retry path already does: without it,
        # a fresh process restart's own reconciliation pass drops the
        # original response's execution evidence entirely, and a stale
        # working history row can be silently accepted at its own smaller
        # requested amount despite that response already proving a larger
        # execution (Codex review, PR #911 round 41: "Persist response
        # notional for restarted reconciliation").
        _raw_response_notional = raw.get("response_notional_usd")
        _row_response_notional = _finite_nonnegative_float(_raw_response_notional)
        if _raw_response_notional is not None and _row_response_notional is None:
            raise UnresolvedPlacementError(
                f"prior placement evidence for {ticker} has an unreadable response notional"
            )
        row_ticker_amount[key] = (
            ticker,
            amount,
            _row_response_notional,
            bool(raw.get("response_may_have_executed", False)),
        )
        groups.setdefault(ref_id, []).append(key)

    # Every row grouped under one reference MUST be the same ticker -- the
    # processing loop below trusts exactly that ("every row in a reference
    # group is the same ticker") to justify looking up only the LAST row's
    # ticker for the whole group. A damaged or externally produced artifact
    # can give two rows for DIFFERENT tickers the identical placement_ref_id
    # (this reference is deterministic from stream/date/ticker, so a
    # genuine collision should be impossible, but malformed storage does
    # not have to be genuine); silently trusting that never happened would
    # look the OTHER ticker's own broker order up under the wrong symbol,
    # mark BOTH rows resolved from one lookup, and collapse the other
    # ticker's real evidence -- so a later run could place it again with no
    # trace anything was ever ambiguous about it (Codex review, PR #911
    # round 29: "Reject reference groups containing multiple tickers").
    # This path already fails closed on every other shape of malformed
    # persisted evidence; a shared reference across tickers is no
    # different.
    for _ref_id, _keys in groups.items():
        _group_tickers = {row_ticker_amount[_key][0] for _key in _keys}
        if len(_group_tickers) > 1:
            raise UnresolvedPlacementError(
                f"prior placement evidence groups multiple tickers "
                f"({', '.join(sorted(_group_tickers))}) under one reference "
                f"({_ref_id}); refusing to guess which one this order belongs to"
            )

    recovered: Dict[str, Dict[str, Any]] = {}
    for ref_id, keys in groups.items():
        # EVERY row's amount, not just the latest: a retried fractional
        # placement can change its requested amount between attempts (a
        # resized signal) while reusing the SAME deterministic ref_id, so a
        # single shared reference can carry several distinct recorded
        # amounts. `_reconcile_ambiguous_fractional_placement` makes exactly
        # ONE broker lookup for this ref_id regardless of how many
        # candidates it checks, and tries each in turn -- validating against
        # only the latest (or only the first) could report a genuine match
        # for a DIFFERENT row's amount as a permanent conflict, UNKNOWN
        # forever despite an exact reference match (Codex review, PR #911
        # round 9: "Match grouped references against every attempted
        # amount"; round 7 partially addressed this by preferring the
        # latest row alone). `keys[-1]` (the most recently appended, per
        # `unproven_keys`'s file order) still names the ticker, since every
        # row in a reference group is the same ticker.
        ticker, _, _, _ = row_ticker_amount[keys[-1]]
        candidate_amounts = [row_ticker_amount[key][1] for key in keys]
        # The first row in the group that persisted its own response
        # evidence -- ordinarily there is exactly one, since only the
        # placement call that actually raised `AmbiguousPlacementResponseError`
        # ever had a response notional to persist in the first place; the
        # others are `None`.
        response_notionals = {
            row_ticker_amount[key][2] for key in keys if row_ticker_amount[key][2] is not None
        }
        # Every response in a shared-reference retry group is direct broker
        # evidence. Picking the first one could erase a larger execution.
        if len(response_notionals) > 1:
            raise UnresolvedPlacementError(
                f"prior placement evidence for {ticker} has conflicting response notionals"
            )
        response_notional_usd = next(iter(response_notionals), None)
        response_may_have_executed = any(row_ticker_amount[key][3] for key in keys)
        try:
            # The placement reconciler intentionally needs only these two
            # fields; RunContext derives (rather than stores) trading_day.
            reconciliation_ctx = SimpleNamespace(
                broker=ctx.broker,
                trading_day=evidence_trading_day,
            )
            # Populated by the call below with the same broker row that
            # decides `verdict`, so the execution-log block further down
            # this loop iteration can reuse it instead of repeating an
            # identical broker lookup that could itself transiently fail
            # (Codex review, PR #911 round 36: "Reuse the broker row that
            # proved the recovered fill").
            _matched_order_for_execution_log: Dict[str, Any] = {}
            verdict, order_id, accepted_amount = _reconcile_ambiguous_fractional_placement(
                reconciliation_ctx, ticker, ref_id, candidate_amounts,
                matched_order_out=_matched_order_for_execution_log,
                response_notional_usd=response_notional_usd,
                response_may_have_executed=response_may_have_executed,
            )
            # A prior process may have persisted only one selected identity
            # from an ambiguous response. A later match for that one identity
            # cannot resolve the other one, including when this lookup says
            # the selected order never existed.
            if any(bool(outcomes[key].get("structurally_ambiguous")) for key in keys):
                verdict = _PLACEMENT_UNKNOWN
            # The row actually matched, not merely the one this group last
            # recorded: booking `candidate_amounts[-1]` unconditionally on
            # ACCEPTED would overstate an accepted $10 order as $12 whenever
            # the LATEST row is the one that did NOT match.
            amount = accepted_amount if verdict == _PLACEMENT_ACCEPTED else candidate_amounts[-1]
        except Exception as exc:  # noqa: BLE001 - unreadable history stays blocked
            for key in keys:
                _IN_FLIGHT_CANDIDATE_OUTCOMES.setdefault("outcomes", {})[str(key)] = outcomes[key]
            raise UnresolvedPlacementError(
                f"prior placement outcome remains unresolved for {ticker}"
            ) from exc
        # A row in this group can already carry an order_id from the
        # ORIGINAL immediate placement response -- persisted by the
        # failure writer before this retry ever ran -- and that persisted
        # id can legitimately disagree with what THIS retry's exact-
        # reference history lookup just resolved: either one may name a
        # real order (a race could have left a genuinely different broker
        # id in the response than what history now reports, or the
        # history lookup itself could be reading a stale/foreign row).
        # The immediate placement path (RobinhoodBroker.place_market_buy /
        # _order_identifier_aliases_conflict) explicitly keeps that exact
        # shape unresolved rather than picking one; blindly overwriting
        # the persisted id with the reconciled one here on restart
        # silently discarded that same caution, booking the history's
        # order while the original response's own possibly-live order
        # dropped out of cap accounting entirely (Codex review, PR #911
        # round 33: "Preserve conflicts with persisted response order
        # IDs"). Downgrades to UNKNOWN and discards the untrustworthy
        # reconciled id rather than deciding between the two -- the SAME
        # fail-closed reading a genuine history ambiguity already gets.
        if order_id and any(
            _is_usable_reconciled_order_id(outcomes[_key].get("order_id"))
            and str(outcomes[_key]["order_id"]).strip() != str(order_id).strip()
            for _key in keys
        ):
            verdict = _PLACEMENT_UNKNOWN
            order_id = None
        if verdict == _PLACEMENT_UNKNOWN:
            # The exact order may still have been FOUND -- only its state or
            # execution amount was ambiguous -- and a usable id is durable
            # reconciliation evidence worth keeping even though the verdict
            # itself stays unproven (Codex review, PR #911: "Persist matched
            # order IDs when the verdict remains unknown").
            if order_id:
                for key in keys:
                    outcomes[key]["order_id"] = order_id
                # Locked the same way every other run_state.json writer in
                # this module is, but scoped to ONLY this write -- not the
                # broker lookup above or the rest of this loop -- so this
                # critical section never spans network I/O. An overlapping
                # retry's own writer blocked behind a lock held across a
                # slow/stalled broker call could otherwise itself time out
                # and fail to publish its own evidence (Codex review:
                # "Release the run-state lock before broker I/O"). A
                # TimeoutError here still needs to reach the caller as an
                # unresolved placement -- this write is the one piece of
                # durable evidence that a usable order_id was found even
                # though the verdict stays unknown -- so it is allowed to
                # propagate into the ABORT path below rather than being
                # swallowed as best-effort. Also re-verified against
                # `_last_known_state_text` (see the comment at this
                # function's initial read) before writing, so an
                # overlapping retry's own evidence published in the gap
                # since that read is never silently overwritten.
                _serialized = _serialize_run_state(persisted)
                try:
                    with cross_process_lock(state_path.with_name(f"{state_path.name}.lock")):
                        try:
                            _on_disk_text = state_path.read_text(encoding="utf-8")
                        except (OSError, UnicodeDecodeError) as exc:
                            raise UnresolvedPlacementError(
                                "cannot verify prior placement evidence is unchanged "
                                f"for {ticker}; refusing new placements"
                            ) from exc
                        if _on_disk_text != _last_known_state_text:
                            raise UnresolvedPlacementError(
                                "prior placement evidence for "
                                f"{ticker} changed concurrently; refusing new placements",
                                concurrent_writer_detected=True,
                            )
                        atomic_write_text(state_path, _serialized)
                        _last_known_state_text = _serialized
                except TimeoutError as exc:
                    raise UnresolvedPlacementError(
                        "could not acquire the run-state lock to persist the matched "
                        f"order id for {ticker}; refusing new placements"
                    ) from exc
            for key in keys:
                _IN_FLIGHT_CANDIDATE_OUTCOMES.setdefault("outcomes", {})[str(key)] = outcomes[key]
            raise UnresolvedPlacementError(
                f"prior placement outcome remains unresolved for {ticker}"
            )
        for key in keys:
            row = outcomes[key]
            row["placement_outcome_unproven"] = False
            row["order_id"] = order_id
            row["reconciled_on_retry"] = True
            if verdict == _PLACEMENT_ACCEPTED:
                row["status"] = "submitted"
                row["skip_reason"] = None
            else:
                row["status"] = "failed"
                row["skip_reason"] = "placement rejected: reconciled on retry"
        if verdict in (_PLACEMENT_ACCEPTED, _PLACEMENT_NO_ORDER):
            # Durably appended into THIS ARTIFACT's own buy_candidates,
            # regardless of same-day or prior-day, and regardless of whether
            # a LATER reference group in this same loop goes on to raise.
            # The alternative -- relying on the `recovered` dict this
            # function returns to seed a fresh build later -- only works
            # when this invocation reaches that fresh build at all: if a
            # later group remains unknown and this function raises, the
            # caller never gets `recovered`, and this run's OWN failure
            # writer runs the MERGE branch instead of a fresh synthesis,
            # which only touches rows for outcomes newly published to
            # `_IN_FLIGHT_CANDIDATE_OUTCOMES` (i.e. the LATER, still-
            # unresolved group) -- never refreshing THIS group's already-
            # stale "failed" row from its now-updated (submitted, proven)
            # broker_outcomes entry. dca_risk.deployed_usd() sums
            # buy_candidates rows, not broker_outcomes, so that stale row
            # left this order's dollars permanently uncounted even though
            # StrategyState was booked (Codex review, PR #911 round 4:
            # "Publish each recovered group before processing the next").
            # A prior-day recovery is bucketed under this artifact's own
            # top-level trading_day, which IS `evidence_trading_day` --
            # exactly what dca_risk.deployed_usd_by_claim_date's fallback
            # bucket already keys on (Codex review, PR #911 round 3: "Keep
            # prior-day recoveries in deployment accounting"). A same-day
            # recovery is bucketed the identical way, under today's own
            # trading_day -- consistent either way. On the common path
            # (this run finishes normally) this row is moot: the fresh
            # `write_run_artifacts` call at the end of a successful run
            # replaces this whole file, and `recovered`'s own seeding into
            # that fresh build already covers the same-day case. This only
            # matters, and only takes effect, on the less-common path this
            # finding names -- a later group still raises.
            persisted_candidates = persisted.setdefault("buy_candidates", [])
            if not isinstance(persisted_candidates, list):
                persisted_candidates = []
                persisted["buy_candidates"] = persisted_candidates
            # status/skip_reason mirror the SAME per-verdict split the
            # broker_outcomes row above just applied to this identical
            # group -- a proven REJECTION collapses to one "failed" row
            # too, not just an accepted one, or the stale duplicate rows a
            # retried, shared-ref_id rejection left behind were never
            # cleaned up: load_prior_same_day_allocations counts every
            # "failed" candidate row as its own consumed max_orders_per_day
            # slot, so N stale rows for ONE real broker call could exhaust
            # the daily attempt cap early (Codex review, PR #911 round 19:
            # "Collapse shared-reference rows after terminal rejection").
            _reconciled_row = {
                "ticker": ticker,
                "reason": "reconciled_fractional_placement",
                "buy_multiplier": 0.0,
                "planned_amount_usd": round(amount, 2),
                "status": "submitted" if verdict == _PLACEMENT_ACCEPTED else "failed",
                "order_id": order_id,
                "skip_reason": (
                    None
                    if verdict == _PLACEMENT_ACCEPTED
                    else "placement rejected: reconciled on retry"
                ),
                "placement_ref_id": ref_id,
            }
            # Replace the ORIGINAL "failed"/unresolved row for THIS EXACT
            # ref_id in place, rather than appending a second row for the
            # same broker attempt. `load_prior_same_day_allocations` counts
            # every candidate row whose status shows an order was placed
            # (both "failed" and "submitted" qualify) as a consumed
            # `max_orders_per_day` slot, so leaving the stale failed row in
            # place charged one real broker call as two attempts and could
            # wrongly block a later, genuinely new order for this ticker
            # (Codex review, PR #911 round 8: "Update the original candidate
            # when reconciliation resolves").
            #
            # Matched by `placement_ref_id`, not merely ticker: two distinct
            # unproven ref_id groups for the SAME ticker can both be present
            # (see "Preserve every distinct recovered order for a ticker"
            # below), and a ticker-only match couldn't tell which of the two
            # original rows belonged to the group JUST resolved, so both
            # resolutions fell back to appending and left two stale failed
            # rows alongside two new submitted ones for only two broker
            # calls (Codex review, PR #911 round 10: "Replace every resolved
            # original attempt row"). `_failure_candidate_row` now carries
            # `placement_ref_id` on every row it builds, from this run
            # onward, so each group's own original row is unambiguous.
            _exact_ref_matches = [
                _i
                for _i, _row in enumerate(persisted_candidates)
                if isinstance(_row, dict) and _row.get("placement_ref_id") == ref_id
            ]
            if _exact_ref_matches:
                # Unlike a ticker-only match, an EXACT ref_id match is never
                # ambiguous: every row carrying this literal ref_id is the
                # SAME deterministic broker call, retried (this is exactly
                # `keys` -- the `unproven_keys` sharing this ref_id -- since
                # each was independently persisted as its own failed
                # candidate row by an earlier attempt). Two or more such
                # rows must therefore ALL collapse into the one true
                # resolution, not be left in place while ALSO appending a
                # third: the earlier version of this fix only replaced a
                # single match and appended on 2+, which is exactly the
                # "retried attempts sharing one reference" case this whole
                # function groups by ref_id to handle correctly elsewhere
                # (Codex review, PR #911 round 12: "Replace a retry row
                # when references are shared"). Replace the first, drop
                # the rest.
                persisted_candidates[_exact_ref_matches[0]] = _reconciled_row
                for _extra_index in sorted(_exact_ref_matches[1:], reverse=True):
                    del persisted_candidates[_extra_index]
            else:
                # No row carries a matching placement_ref_id -- either no
                # original row exists at all (e.g. a blocked-date gated
                # recovery that never wrote one), or it predates this field.
                # Fall back to the ticker-based heuristic for that legacy
                # shape, excluding any row that already carries SOME OTHER
                # placement_ref_id (a distinct, still-tracked group) or a
                # `_RECOVERY_ROW_REASONS` reason (a prior reconciliation's
                # own row) -- exactly one such untracked match is still safe
                # to replace; two or more is genuinely ambiguous and appends
                # instead, the same double-count this path has always had
                # rather than a new misattribution.
                _legacy_ticker_matches = [
                    _i
                    for _i, _row in enumerate(persisted_candidates)
                    if isinstance(_row, dict)
                    and _row.get("ticker") == ticker
                    and _row.get("reason") not in _RECOVERY_ROW_REASONS
                    and not _row.get("placement_ref_id")
                ]
                if len(_legacy_ticker_matches) == 1:
                    persisted_candidates[_legacy_ticker_matches[0]] = _reconciled_row
                else:
                    persisted_candidates.append(_reconciled_row)
        # PERSISTED BEFORE ctx.state IS EVER BOOKED for this group, not after
        # -- and before the next reference group is even attempted, never
        # batched until the whole loop finishes. Booking first and persisting
        # second left a window where a transient write failure (e.g. a full
        # disk) landed AFTER state_transaction()'s own finally block had
        # already saved the incremented StrategyState, but BEFORE the
        # artifact recorded the row as proven: the next invocation would
        # still see it unproven, reconcile the same accepted broker order
        # again, and book its dollars a second time (Codex review, PR #911:
        # "Make reconciliation booking durable with its artifact update").
        # Writing first means a failure here raises with NEITHER side
        # updated -- the artifact still shows this group unproven and
        # ctx.state was never touched for it -- so a retry starts from
        # exactly the same, still-consistent place. A LATER group left
        # unresolved after this write succeeds still raises out of this
        # loop, and that is fine: state_transaction() saves the
        # StrategyState mutation even on that exception, and the artifact
        # already agrees with it for every group resolved so far (Codex
        # review, PR #911: "Persist reconciliations before processing
        # another ambiguous row").
        #
        # A Codex review on PR #1164 ("Commit recovered state before
        # clearing unresolved evidence") proposed reversing this again --
        # booking first, in memory, then deferring the artifact write
        # through `ctx.state.pending_durable_commit_callbacks` so it only
        # runs once `state_transaction()` has already durably saved the
        # booking. That does close a real, if narrow, gap (this
        # function's own caller is NOT in this repository -- see
        # `docs/live_wiring.md` -- so nothing here can prove how wide the
        # window between this call returning and that external
        # `state_transaction()` block's own save actually is in
        # production). It was deliberately NOT applied: this exact
        # ordering is locked in by this module's own test suite --
        # `tests/test_near_close_dca.py::test_retry_reconciliation_does_
        # not_book_state_when_the_artifact_write_fails` asserts booking
        # must NOT happen when this write fails, and roughly twenty other
        # `test_retry_reconciliation_*`/`test_run_daily_compact_*` cases
        # call this function directly, never through a
        # `state_transaction()` wrapper that would drain queued
        # callbacks -- so deferring the write silently dropped it in
        # every one of those tests and broke them outright. Revisiting
        # this needs either updating that whole test suite's contract
        # deliberately (a decision for whoever owns it, not a side effect
        # of one review comment) or a durable, ON-DISK idempotency marker
        # (own_recovered_order_ids -- the in-memory guard that keeps a
        # retried `book_reconciled_attempt_notional` call from double-
        # booking -- is explicitly NOT persisted, so a plain reordering
        # alone reopens double-booking across a restart in exchange for
        # closing the under-booking gap, not a strict improvement).
        persisted["placement_evidence_incomplete"] = any(
            isinstance(row, dict) and row.get("placement_outcome_unproven")
            for row in outcomes.values()
        )
        # Distinct ORDERS, not rows: several persisted unproven rows can
        # share one placement_ref_id (a retried fractional placement reuses
        # the same deterministic ref for a ticker/stream/day), and every row
        # in that group is marked "submitted" once the shared reference
        # resolves. Summing rows here reported multiple submissions for the
        # single broker order this loop actually found and booked once,
        # disagreeing with the one appended candidate row (Codex review,
        # PR #911 round 6: "Count accepted reference groups instead of
        # duplicate rows"). Falls back to the row's own key when a
        # submitted row somehow carries no order_id, so two such rows are
        # never silently collapsed into one. Deduplicating to ONE
        # representative row per order_id is still correct even when that
        # row is itself a whole-share AGGREGATE representing more than one
        # broker order under a single scalar order_id (a same-artifact
        # whole-share outcome merged via `merged_submission_count`) --
        # `_submitted_orders_in_row` reads that aggregate count off the
        # representative row instead of assuming exactly one, the same
        # helper the fresh (non-gated) submission count already uses.
        # Counting the deduplicated group as a flat 1 collapsed a
        # two-order whole-share aggregate down to one order, understating
        # `orders_submitted_count`/`counts.submitted` by exactly the
        # orders the aggregate represents beyond its first (Codex review,
        # PR #911 round 24: "Preserve merged submissions when refreshing
        # recovery counts").
        _submitted_order_groups: Dict[Any, Dict[str, Any]] = {}
        for key, row in outcomes.items():
            if isinstance(row, dict) and row.get("status") == "submitted":
                # A malformed persisted `order_id` -- a JSON object or
                # list, from damaged or externally produced storage -- is
                # unhashable, and the bare `or` here never falls back to
                # the row-specific key for it (a truthy dict/list is never
                # blank), so it reached this dict key position unguarded
                # and raised `TypeError: unhashable type` -- AFTER another,
                # unrelated unproven placement earlier in this same
                # function had already been authoritatively reconciled in
                # memory, so the refreshed artifact was never written and
                # that reconciliation was lost, repeating on every later
                # invocation. Normalized the same defensive way
                # `_failed_placement_count` already validates a
                # `placement_ref_id` before using it, falling back to the
                # row-specific key for anything else (Codex review, PR
                # #1164: "Validate order IDs before grouping submitted
                # outcomes").
                _raw_group_order_id = row.get("order_id")
                if isinstance(_raw_group_order_id, str) and _raw_group_order_id.strip():
                    _group_key = _raw_group_order_id
                elif isinstance(_raw_group_order_id, (int, float)) and not isinstance(
                    _raw_group_order_id, bool
                ):
                    _group_key = _raw_group_order_id
                else:
                    _group_key = f"row:{key}"
                _submitted_order_groups.setdefault(_group_key, row)
        persisted["orders_submitted_count"] = sum(
            _submitted_orders_in_row(row) for row in _submitted_order_groups.values()
        )
        # Recomputed alongside orders_submitted_count, from the SAME
        # just-updated outcomes -- not left at whatever the original
        # unresolved-halt write recorded. `_refresh_blocked_run_companions`
        # (the calendar-blocked path just below) copies this persisted
        # state verbatim into run_summary.json/submitted_orders.csv, so a
        # stale orders_failed_count left an artifact simultaneously
        # reporting a recovered submission AND still counting that same
        # now-resolved order as failed (Codex review, PR #911 round 12:
        # "Refresh failure aggregates after resolving a placement"). Shares
        # `_failed_placement_count`, the same helper the failure writer's
        # own two branches already use for this exact figure.
        persisted["orders_failed_count"] = _failed_placement_count(outcomes)
        # A truthy NON-mapping `counts` (a damaged or externally produced
        # string/list) is not the same as an absent one: `or {}` never
        # engages for a truthy value, so `**persisted["counts"]` raised a
        # plain TypeError before this resolved state could be written at
        # all -- leaving the original row permanently unproven and this
        # same failure repeating on every later invocation despite
        # authoritative broker-history reconciliation having already
        # settled it. Guarded here the same way the failure-state merge
        # path a few hundred lines below already guards the identical
        # shape (Codex review, PR #911 round 31/35: "Parse/validate
        # preserved counts before merging"; PR #1164: "Normalize malformed
        # counts before refreshing recovered state").
        _preserved_counts = persisted.get("counts")
        persisted["counts"] = {
            **(_preserved_counts if isinstance(_preserved_counts, dict) else {}),
            "submitted": persisted["orders_submitted_count"],
            "buy_candidates": len(persisted.get("buy_candidates") or []),
        }
        # A normal, gate-passing run can reuse this directory for a different
        # trading day and then replace its root artifacts during finalization.
        # Preserve the resolved old-day state under a day-keyed archive first;
        # deployment-history scans include ``run_state*.json`` recursively, so
        # the recovered order remains visible after the root is replaced.
        if (
            verdict == _PLACEMENT_ACCEPTED
            and evidence_trading_day != today
            and not persist_stale_day_execution
        ):
            stale_archive = (
                state_path.parent
                / "reconciled_stale_placements"
                / evidence_trading_day.isoformat()
                / state_path.parent.name
                / "run_state.json"
            )
            stale_archive.parent.mkdir(parents=True, exist_ok=True)
            atomic_write_text(stale_archive, _serialize_run_state(persisted))
        # usage_proxy.manual_recovery_required is deliberately left
        # untouched: it is a shared, overloaded flag (Codex review round 6
        # already found `placement_evidence_incomplete` has the same
        # property and reverted a similarly-scoped fix over it) that other
        # failure modes besides fractional-placement ambiguity can also
        # set, and this function has no way to tell whether THIS resolution
        # was the only thing that set it. Leaving it True when it could be
        # cleared is a false-positive nudge to check manually, not a safety
        # gap; clearing it prematurely could hide a real, unrelated issue.
        # Restored for BOTH verdicts reaching this point, not only ACCEPTED:
        # a terminal rejection (_PLACEMENT_NO_ORDER) still represents a
        # broker placement call that consumed a daily attempt slot, and this
        # row is about to be marked proven and never revisited. Skipping the
        # restore for a rejection left day_order_count() permanently short
        # by exactly the lost-final-save scenario ACCEPTED already guards
        # against (Codex review, PR #911 round 5: "Restore the attempt count
        # for reconciled rejections"). Zero notional for a rejection --
        # nothing was bought -- so book_reconciled_attempt_notional's own
        # "restore the attempt, add nothing extra" branch handles it
        # correctly either way.
        # Published BEFORE ctx.state is booked for this group -- see the
        # "PERSISTED BEFORE ctx.state IS EVER BOOKED" comment a little above,
        # which this call must match. book_reconciled_attempt_notional's own
        # notional add is NOT idempotent (it unconditionally adds
        # `notional_usd` to submitted_notional_by_day/_week every call, only
        # the separate attempt-count restore is dedup-gated) -- writing the
        # artifact second left a window where a transient write failure
        # landed AFTER StrategyState was already mutated but BEFORE the
        # artifact recorded this row as proven, so the next invocation still
        # saw it unproven and re-booked the same accepted order's dollars a
        # second time. A write failure here now raises with NEITHER side
        # updated (Codex review, PR #859/#911 round 44: "Persist reconciled
        # evidence before mutating strategy state"). See that same comment
        # above for why a Codex review on PR #1164 proposing the OPPOSITE
        # order (book first, defer the write to a
        # `pending_durable_commit_callback`) was evaluated and not applied.
        #
        # Locked the same way every other run_state.json writer in this
        # module is, but scoped to ONLY this write -- not the broker lookup
        # earlier in this loop iteration or any other pure in-memory work --
        # so the critical section never spans network I/O. An overlapping
        # retry's own writer blocked behind a lock held across a slow or
        # stalled broker call could otherwise itself time out and fail to
        # publish its own evidence (Codex review: "Release the run-state
        # lock before broker I/O"). A TimeoutError here must still leave
        # NEITHER side updated, matching the write-failure comment just
        # above -- raised as UnresolvedPlacementError, the same fail-closed
        # verdict every other unresolvable-evidence branch in this function
        # already returns, BEFORE ctx.state can be booked. Also re-verified
        # against `_last_known_state_text` (see the comment at this
        # function's initial read) before writing: `persisted` was read
        # once up front and is only ever mutated in memory across however
        # many reference groups this loop resolves, so an overlapping
        # retry sharing this artifact directory could have published its
        # own evidence in the gap since that read (or since this
        # function's own prior write, earlier in this same loop). Blindly
        # overwriting with this stale snapshot would silently discard that
        # evidence (Codex review, PR #1166: "Merge fresh run state before
        # reconciliation writes") -- and this function has no general way
        # to safely merge two independently-evolved snapshots of this many
        # interdependent aggregate fields, so a mismatch fails closed the
        # same way a lock timeout does, rather than guessing.
        _serialized = _serialize_run_state(persisted)
        try:
            with cross_process_lock(state_path.with_name(f"{state_path.name}.lock")):
                try:
                    _on_disk_text = state_path.read_text(encoding="utf-8")
                except (OSError, UnicodeDecodeError) as exc:
                    raise UnresolvedPlacementError(
                        "cannot verify prior placement evidence is unchanged for "
                        f"{ticker}; refusing new placements"
                    ) from exc
                if _on_disk_text != _last_known_state_text:
                    raise UnresolvedPlacementError(
                        f"prior placement evidence for {ticker} changed concurrently; "
                        "refusing new placements",
                        concurrent_writer_detected=True,
                    )
                atomic_write_text(state_path, _serialized)
                _last_known_state_text = _serialized
        except TimeoutError as exc:
            raise UnresolvedPlacementError(
                "could not acquire the run-state lock to persist the reconciled "
                f"placement for {ticker}; refusing new placements"
            ) from exc
        ctx.state.book_reconciled_attempt_notional(
            ticker,
            evidence_trading_day,
            amount if verdict == _PLACEMENT_ACCEPTED else 0.0,
            order_id=order_id,
            source_run_id=_persisted_run_id if isinstance(_persisted_run_id, str) else None,
        )
        if verdict in (_PLACEMENT_ACCEPTED, _PLACEMENT_NO_ORDER):
            if (
                evidence_trading_day == today
                and (persisted_stream is None or persisted_stream == ctx.stream)
                and _run_type_compatible
            ):
                # Published for a proven REJECTION too, not only an accepted
                # order: the attempt-count restore just above already makes
                # ctx.state's own day_order_count durable and cross-stream
                # (state_transaction() shares one locked, canonical file),
                # but today's own fresh run_state.json/buy_candidates.csv is
                # a SEPARATE artifact this same invocation is about to
                # finalize -- and the finalizer publishes it from THIS run's
                # own candidate outcomes, which a prior halted invocation's
                # ambiguous placement was never part of. Skipping the
                # rejection case left today's artifact with no record at all
                # that this ticker was ever attempted, even though the
                # broker call happened and consumed a real attempt slot --
                # an audit gap the same reasoning already closed for the
                # accepted branch (Codex review, PR #911 round 14: "Preserve
                # reconciled rejection attempts in fresh artifacts"). Zero
                # notional and a "failed" status -- nothing was bought --
                # mirroring _failure_candidate_row's own reading of a
                # declined outcome.
                #
                # Keyed by ref_id, not bare ticker: two distinct unproven
                # groups for the SAME ticker (e.g. a plain placement and a
                # later "-topup-" retry) are two separate broker orders, and
                # a ticker-only key let the second overwrite the first here,
                # permanently dropping one order's exposure from both this
                # run's candidates and every later deployment-history scan
                # (Codex review, PR #911: "Preserve every distinct recovered
                # order for a ticker").
                recovered[f"{ticker}#fractional-recovery:{ref_id}"] = {
                    "status": "submitted" if verdict == _PLACEMENT_ACCEPTED else "failed",
                    "order_id": order_id,
                    "skip_reason": None,
                    "reviewed_order": None,
                    "submitted_amount_usd": amount if verdict == _PLACEMENT_ACCEPTED else 0.0,
                    # Read by _build_buy_candidates to synthesize an
                    # auditable row, mirroring recovered_inverse_martingale_
                    # lease's identical treatment.
                    "reconciled_fractional_placement": True,
                    "ticker": ticker,
                }
            else:
                logger.info(
                    "Reconciled a fractional placement for %s from %s (stream=%s); "
                    "booked to that day's budget and recorded in the original "
                    "artifact, not today's candidates",
                    ticker,
                    evidence_trading_day.isoformat(),
                    persisted_stream,
                )
        if verdict == _PLACEMENT_ACCEPTED and (
            persist_stale_day_execution
            or (
                evidence_trading_day == today
                and (persisted_stream is None or persisted_stream == ctx.stream)
                and _run_type_compatible
            )
        ):
            # The SAME-DAY branch here now requires the identical stream/
            # run-type compatibility the "publish to today's candidates"
            # gate above already checks -- deliberately NOT the bare
            # `evidence_trading_day == today` this used to be. That bare
            # date check let a scheduled run's same-day reconciliation of a
            # MANUAL or different-stream evidence artifact append its
            # execution record to THIS run's own run_result even though the
            # gate above correctly excluded it from today's candidates for
            # exactly that incompatibility -- run_daily_compact then wrote
            # that foreign order into this slot's own orders.csv, so fill/
            # coverage/slippage reporting attributed a manual or other-
            # stream order to this scheduled run (Codex review, PR #911
            # round 31: "Gate same-day execution recovery on run
            # identity"). `persist_stale_day_execution` (the calendar-
            # blocked caller's own prior-day override) stays unconditional:
            # a different day's evidence was never a same-day identity
            # question at all, and that path's own orders.csv merge target
            # is the reused artifact's own log, not a distinct fresh slot's.
            #
            # Deliberately OUTSIDE the `evidence_trading_day == today` gate
            # above: that gate decides whether this recovery is ALSO
            # published into TODAY's own fresh run_state.json/candidates
            # (a same-day concern), but orders.csv is a completely
            # different, day-independent artifact -- the canonical fill/
            # slippage log every later fill-refresh/coverage/slippage pass
            # reads, regardless of which day placed the order. Nesting this
            # append inside that gate meant a PRIOR-DAY placement (e.g. the
            # final approved trading day's own ambiguous order, reconciled
            # only once trading is calendar-blocked the next invocation)
            # never reached it at all: evidence_trading_day != today there
            # by construction, so run_state.json's own broker_outcomes row
            # became proven while orders.csv stayed silently missing it
            # forever -- no later pass ever revisits an artifact whose
            # run_state.json already marks the placement settled (Codex
            # review, PR #911 round 24: "Persist prior-day gated recoveries
            # to orders.csv").
            #
            # `persist_stale_day_execution` narrows WHICH callers get that
            # day-independent treatment: only the calendar-blocked caller
            # passes it, because a blocked run never reaches run_daily_
            # compact's own success-path write at all -- this append,
            # merged into orders.csv immediately by that caller, is the
            # ONLY route a blocked-day recovery has. The ordinary gate-
            # passing caller (trading open today) reaches that success
            # path, which treats orders.csv as RUN-SPECIFIC: when this
            # artifacts_dir was reused and still carried unresolved
            # evidence from an earlier trading day, the unconditional
            # append used to add that prior day's order to THIS run's own
            # run_result -- which run_daily_compact's own `_orders_csv_
            # same_run` check had already decided was a DIFFERENT run, so
            # its later `_merge_execution_csv(..., replace_existing=True)`
            # wrote every record in that list, folding the prior day's
            # order into today's orders.csv and fill totals as though this
            # run had placed it (Codex review, PR #911 round 28: "Keep
            # prior-day executions out of the current run log"). The
            # recovery is still fully durable either way -- run_state.json
            # above already proved it -- this only decides whether it also
            # lands in a run-specific execution log it does not belong to.
            #
            # run_daily_compact() writes orders.csv -- the canonical
            # execution/fill log -- SOLELY from run_result.execution_
            # records, never from run_state.json. Without this, an
            # accepted recovery reports "submitted" in run_state.json
            # while the broker order it names is invisible to every
            # later fill-refresh, coverage, or slippage pass that reads
            # only orders.csv, unlike an ordinary accepted placement or
            # the inverse-Martingale recovery path, both of which append
            # here (Codex review, PR #911 round 3: "Record fractional
            # recoveries in the execution log"). Not reached for a
            # proven rejection: nothing filled, so there is nothing
            # for the fill/slippage log to record.
            #
            # force_filled is NOT unconditional: _PLACEMENT_ACCEPTED
            # covers every state in _WORKING_BROKER_ORDER_STATES, which
            # includes genuinely still-working orders (new/queued/
            # confirmed/unconfirmed/partially_filled), not only a
            # completed "filled". Claiming every accepted recovery is a
            # fill inflated filled-order counts and filled-notional
            # reporting for orders that have not actually settled yet
            # (Codex review, PR #911 round 4: "Do not mark working
            # recoveries as filled"). Settling which one this is used to
            # require a SECOND, read-only lookup by the SAME ref_id -- a
            # supposedly idempotent repeat of the identical call
            # _reconcile_ambiguous_fractional_placement itself just made.
            # But idempotent does not mean infallible: when that repeat
            # transiently raised, returned no row, or returned an
            # incomplete row, the `except` below discarded the FIRST
            # call's already-proven lifecycle/notional entirely and fell
            # back to the safe-but-wrong "submitted" default, writing
            # orders.csv as merely submitted at the larger approved
            # amount even though the reconciliation decision above had
            # already settled this exact order (Codex review, PR #911
            # round 36: "Reuse the broker row that proved the recovered
            # fill"). `_matched_order_for_execution_log` is that FIRST
            # call's own matched row, captured via `_reconcile_ambiguous_
            # fractional_placement`'s `matched_order_out` -- reused here
            # instead of repeating the lookup, so there is nothing left
            # to transiently fail.
            _recovery_force_filled = False
            # The FINAL settled notional a confirmed fill actually
            # moved, when readable -- distinct from `amount`, the
            # originally APPROVED/requested figure this reconciler
            # keeps booking into ctx.state above regardless (that
            # booking stays conservative on purpose: the caps care
            # about what was authorized, not what settled). A
            # partial execution that still cleared the approval
            # ceiling (or a broker-side adjustment) settles for LESS
            # than `amount`, and the execution record -- force-
            # marked "filled" with no separate price/quantity
            # breakdown of its own -- previously reported the
            # larger requested figure as though it were the
            # confirmed fill, overstating filled notional in
            # orders.csv and build_report() (Codex review, PR #911
            # round 19: "Record the recovered fill notional instead
            # of the request"). None here (unreadable, or the
            # lookup never confirmed a fill) keeps `amount` as the
            # honest fallback -- never a fabricated smaller figure.
            _recovery_actual_notional: Optional[float] = None
            try:
                if _matched_order_for_execution_log:
                    _recovery_matched: Optional[Dict[str, Any]] = _matched_order_for_execution_log
                    if isinstance(_recovery_matched, dict):
                        # Reads "state" OR "status" -- the SAME lifecycle-
                        # alias normalization the reconciliation decision
                        # above already applies -- not "state" alone. A
                        # matched row reporting its terminal fill only
                        # through "status" (e.g. {"status": "filled"} with
                        # no "state" field) is exactly the shape the
                        # reconciliation pass above already accepts as a
                        # fill, but this block used to read it via a
                        # separate, repeated lookup that missed it
                        # entirely: the execution record was emitted as
                        # still "submitted" and fell back to the approved
                        # amount instead of the actual executed notional,
                        # corrupting filled-order and filled-notional
                        # reporting in orders.csv (Codex review, PR #911
                        # round 32: "Read recovered fill state from the
                        # status alias").
                        _recovery_state = _normalize_broker_lifecycle_alias(
                            _recovery_matched.get("state")
                        ) or _normalize_broker_lifecycle_alias(
                            _recovery_matched.get("status")
                        ) or ""
                        # _recovered_broker_notional itself reads only the
                        # literal "state" field (it has its own, much wider
                        # set of callers this fix must not reach into), so a
                        # row carrying its lifecycle exclusively through
                        # "status" still valued as unreadable there even
                        # after the force_filled/terminal check above
                        # correctly recognized it -- the execution record
                        # was marked "filled" but still fell back to the
                        # approved amount instead of its actual executed
                        # notional. A shallow copy with "state" resolved to
                        # the SAME normalized value just computed fixes the
                        # read without touching the shared classifier itself
                        # (Codex review, PR #911 round 32: "Read recovered
                        # fill state from the status alias").
                        _recovery_notional_source = (
                            {**_recovery_matched, "state": _recovery_state}
                            if _recovery_state
                            else _recovery_matched
                        )
                        if _recovery_state == "filled":
                            # State alone proves this is a genuine fill --
                            # unchanged from before this fix. The actual
                            # settled notional is still best-effort: when
                            # _recovered_broker_notional can't read it,
                            # `amount` (the approved/requested figure)
                            # remains the honest fallback below, but the
                            # row is still correctly marked "filled".
                            _recovery_force_filled = True
                            _recovery_actual_notional = _recovered_broker_notional(
                                _recovery_notional_source
                            )
                        elif _recovery_state in _TERMINAL_BROKER_ORDER_STATES:
                            # NEW: reads the SAME settled shape
                            # _reconcile_ambiguous_fractional_placement's
                            # own terminal-row branch now accepts, not
                            # just the literal "filled" state -- a
                            # cancelled/expired order that partially
                            # filled before settling has an identically
                            # final, readable notional
                            # (_recovered_broker_notional treats every
                            # settled state the same way), and reporting
                            # it as a still-"submitted" order at the
                            # larger approved/requested figure would be
                            # the exact overstatement round 19 already
                            # fixed for the "filled" case specifically --
                            # reopened for terminal partial fills the
                            # moment that path could accept them (Codex
                            # review, PR #911 round 30: "Record terminal
                            # partial recoveries at their executed
                            # notional"). Unlike the literal "filled" case,
                            # the TERMINAL label alone does not prove a
                            # fill -- a proven ZERO fill (a terminal row
                            # this session's own round-28 fix could still
                            # accept via an ambiguous amount match) is not
                            # a fill at all, so force_filled here requires
                            # genuine, readable, POSITIVE settled evidence.
                            _recovery_actual_notional = _recovered_broker_notional(
                                _recovery_notional_source
                            )
                            _recovery_force_filled = (
                                _recovery_actual_notional is not None
                                and _recovery_actual_notional > 0
                            )
            except Exception:  # noqa: BLE001 - a read failure here must not
                # abort a reconciliation that already succeeded; it only
                # narrows this cosmetic execution-log detail to the safe
                # default. No broker call happens in this block any more
                # (see the comment above `_matched_order_for_execution_
                # log`'s reuse), but the classification reads above can
                # still raise on a surprising row shape.
                _recovery_force_filled = False
                _recovery_actual_notional = None
            if ctx.run_result is not None:
                ctx.run_result.execution_records.append(
                    build_execution_record(
                        ticker=ticker,
                        target_price=0.0,
                        target_price_source="",
                        decision_bar_close=0.0,
                        notional_usd=(
                            _recovery_actual_notional
                            if _recovery_actual_notional is not None
                            else amount
                        ),
                        action_reason="reconciled_fractional_placement",
                        order_id=order_id,
                        force_filled=_recovery_force_filled,
                    )
                )
    return recovered


def _failure_candidate_row(ticker: str, outcome: Dict[str, Any]) -> Dict[str, Any]:
    """A buy_candidates row synthesized from a broker outcome by a failure path.

    One builder for both failure paths -- the direct write and the retry merge --
    so a field added for the schema cannot land on one and miss the other, which
    is how the two drifted before. run_state.schema.json requires ticker,
    buy_multiplier, planned_amount_usd, and status on every candidate row;
    validate_run_artifacts does not run schema validation, so an omission here
    produces an artifact that reads as a complete failure record while
    schema-based reporting rejects it (Codex review).

    ``buy_multiplier`` is carried on the placement outcome; null only when an
    outcome predates that (schema-valid, and honest about not knowing).

    ``ticker`` is the ``candidate_outcomes``/``broker_outcomes`` dict KEY, not
    necessarily the real symbol: a recovered inverse-Martingale lease is
    stored under a synthetic ``"<ticker>#imart-recovery"`` key so it cannot
    collide with an ordinary same-run candidate for the same ticker (see the
    lease-recovery publication block in ``_run_once_impl``), and carries its
    real ticker INSIDE the outcome instead. Preferring
    ``outcome.get("ticker", ticker)`` -- the same fallback
    ``_build_buy_candidates`` already uses for its own success-path rows --
    keeps a failure artifact honest about which symbol a row belongs to
    rather than writing the synthetic key into ``buy_candidates`` as though
    it were a real ticker (Codex review: "Preserve real tickers in recovery
    failure artifacts").
    """
    return {
        "ticker": outcome.get("ticker", ticker),
        "status": outcome.get("status", "not_submitted"),
        "order_id": outcome.get("order_id"),
        # Carried so a LATER reconciliation of this exact call can find and
        # replace this specific row rather than guessing among several
        # candidate rows for the same ticker (Codex review, PR #911 round
        # 10: "Replace every resolved original attempt row") -- an
        # unresolved fractional placement's own broker_outcomes entry
        # always carries this (see the candidate_outcome dict at the
        # placement-failure site); null only for an outcome shape that
        # never had one.
        "placement_ref_id": outcome.get("placement_ref_id"),
        "buy_multiplier": outcome.get("buy_multiplier"),
        # Coerced to a number, never left null: run_state.schema.json REQUIRES
        # planned_amount_usd on every candidate row, so ANY outcome reaching
        # this failure-path builder without a submitted amount would make the
        # recovery artifact schema-invalid -- and this builder runs precisely
        # when a run failed, i.e. when that artifact is the only record left
        # (Codex review, PR #786: "Preserve a numeric planned amount for
        # isolated failures"). 0.0 is the honest figure for an outcome that
        # never recorded a submitted amount: no capital moved.
        "planned_amount_usd": (
            outcome.get("submitted_amount_usd")
            if isinstance(outcome.get("submitted_amount_usd"), (int, float))
            and not isinstance(outcome.get("submitted_amount_usd"), bool)
            else 0.0
        ),
        "skip_reason": outcome.get("skip_reason"),
        # Mirrors _build_buy_candidates's own copy of this marker -- this
        # failure-path rebuild is a SEPARATE artifact-construction path, and
        # is in fact the MORE likely one to carry the marker: a candidate
        # that raised is exactly the case that can also end the run (Codex
        # review, PR #786: "Persist the candidate processing error marker").
        "candidate_processing_error": outcome.get("candidate_processing_error"),
        # Mirrors _build_buy_candidates's own breaker markers, for the same
        # reason this rebuild mirrors candidate_processing_error: a breaker
        # halt followed by a fatal error rebuilds the canonical rows through
        # THIS path, and a seeded recovery annotated in place would otherwise
        # lose every trace that today's order went unattempted (Codex review,
        # PR #786: "Serialize breaker annotations on recovered rows").
        "placement_breaker_halted": outcome.get("placement_breaker_halted"),
        "placement_breaker_tripped_here": outcome.get("placement_breaker_tripped_here"),
        "merged_placement_failed": outcome.get("merged_placement_failed"),
        "merged_placement_blocked": outcome.get("merged_placement_blocked"),
        "merged_confirmation_required": outcome.get("merged_confirmation_required"),
        "merged_failure_reason": outcome.get("merged_failure_reason"),
        "today_order_not_attempted": outcome.get("today_order_not_attempted"),
        "breaker_halt_reason": outcome.get("breaker_halt_reason"),
        # Mirrors _build_buy_candidates's own key for the unresolved-placement
        # halt. THIS builder is the one that actually runs for it: the halt
        # re-raises, so run_state.json's buy_candidates are rebuilt here, and
        # an omission would drop every skipped ticker's explanation from the
        # only artifact the run leaves behind (Codex review, PR #859: "Record
        # candidates skipped by an unresolved halt").
        "unresolved_placement_halted": outcome.get("unresolved_placement_halted"),
        # Mirrors _build_buy_candidates's own whole-share fields (Codex
        # review: "Preserve whole-share fields in failure candidate rows")
        # -- an accepted whole-share order followed by an exception while a
        # LATER candidate is processed rebuilds run_state.json's canonical
        # buy_candidates through this failure-path builder instead, which
        # previously retained only the standard fields and silently dropped
        # the settlement quantity/pending-balance/contribution values a
        # whole-share candidate's own outcome dict carries.
        "whole_share_pending_usd": outcome.get("whole_share_pending_usd"),
        "whole_share_contribution_usd": outcome.get("whole_share_contribution_usd"),
        "whole_share_quantity": outcome.get("whole_share_quantity"),
        "whole_share_settlement_reconciliation_needed": outcome.get(
            "whole_share_settlement_reconciliation_needed"
        ),
        "whole_share_settlement_shortfall_usd": outcome.get("whole_share_settlement_shortfall_usd"),
        # Mirrors _build_buy_candidates's own identical fields (Codex
        # review: "Preserve claim metadata in failure candidate rows") --
        # this failure-path rebuild is a SEPARATE artifact-construction path
        # from _build_buy_candidates's normal one, and previously dropped a
        # recovered outcome's own claim-date/order-id detail entirely when a
        # LATER candidate's exception forced run_state.json's buy_candidates
        # to be rebuilt through this helper instead. Without
        # whole_share_claim_breakdown, dca_risk.deployed_usd_by_claim_date()
        # would attribute the recovered amount to THIS run's own
        # trading_day, extending its effective kill-switch window exactly
        # like the bug that field exists to prevent; without
        # whole_share_order_ids, the additional broker order id(s) an
        # aggregated row carries are lost from the artifact entirely.
        "whole_share_order_ids": outcome.get("whole_share_order_ids"),
        "whole_share_claim_breakdown": outcome.get("whole_share_claim_breakdown"),
        "whole_share_settlement_adjustment": outcome.get("whole_share_settlement_adjustment", False),
        # See _build_buy_candidates's own note on these two: a submitted
        # aggregate that later hits a failure path is rebuilt through THIS
        # helper, so omitting them here loses the same cap evidence.
        "merged_attempt_days": outcome.get("merged_attempt_days"),
        "merged_attempt_count": outcome.get("merged_attempt_count"),
        # Same audit contract as _build_buy_candidates's success-path rows:
        # unconditionally present (defaulted), never conditionally added --
        # _write_csv derives buy_candidates.csv's header from row 0's keys
        # alone, so a later failure row carrying extra keys not in row 0
        # would crash csv.DictWriter (Codex review discussion on commit
        # 6e896c5: "Propagate aggregate fields into failure candidate
        # rows" -- a submitted aggregate order that later hits a failure
        # path via _write_afternoon_failure_artifacts previously lost all
        # four fields, even though the real order already applied the rule).
        "aggregate_minimum_topup_applied": outcome.get(
            "aggregate_minimum_topup_applied", False
        ),
        "aggregate_minimum_topup_remainder_usd": outcome.get(
            "aggregate_minimum_topup_remainder_usd"
        ),
        "aggregate_minimum_topup_order_usd": outcome.get("aggregate_minimum_topup_order_usd"),
        "aggregate_minimum_topup_reason": outcome.get("aggregate_minimum_topup_reason"),
    }


# Today's own accumulator bookkeeping, which survives even when a recovered
# order from an earlier claim supplies the row's status and spend. The ledger
# has already recorded these for today; dropping them leaves the persisted
# accumulator state stale.
_TODAY_ACCUMULATION_FIELDS = (
    "whole_share_contribution_usd",
    "whole_share_pending_usd",
    "whole_share_planned_notional_usd",
    "skip_reason",
    "blocked_by",
)

# Distinguishes "key absent" from "key present and None" when carrying fields
# across, so a recovery that deliberately recorded None is not overwritten.
_MISSING = object()


def _is_distinct_broker_attempt(outcome: Dict[str, Any]) -> bool:
    """Whether one side of a merge represents a DISTINCT broker attempt --
    an order that consumed a ``max_orders_per_day`` slot of its own.

    Deliberately wider than "submitted". A zero-fill recovery reports
    ``status="failed"`` because nothing was purchased, and a rejected
    placement reports ``failed`` too, but each is a real order the broker
    took a slot for. Narrower than "any row", because a settlement
    adjustment corrects an order some earlier booking already counted and is
    never an attempt of its own.
    """
    if outcome.get("whole_share_settlement_adjustment"):
        return False
    if outcome.get("status") == "not_submitted_confirmation_required":
        # A confirmation hold carries `broker_placement_failed`, because a
        # real broker call WAS made -- but no order reached the broker, which
        # is why a standalone hold is excluded from both
        # `_PRIOR_ALLOCATION_ATTEMPT_STATUSES` and
        # `_orders_csv_attempt_counts`. Reading the broad marker without this
        # carve-out made a merged hold count as a second daily attempt,
        # prematurely consuming `max_orders_per_day` (Codex review, PR #786:
        # "Exclude confirmation holds from merged attempt counts"). Merged or
        # standalone, it has to answer the same way.
        return False
    return bool(
        outcome.get("status") in _PRIOR_ALLOCATION_ATTEMPT_STATUSES
        or outcome.get("whole_share_zero_fill_attempt")
        or outcome.get("broker_placement_failed")
    )


# Bucket key for an attempt with no claim breakdown of its own -- today's own
# fresh order, which `load_prior_same_day_allocations` attributes to the
# artifact's own trading day exactly as it always has.
_UNDATED_ATTEMPT_DAY = ""


def _attempt_side_days(outcome: Dict[str, Any]) -> Dict[str, int]:
    """The broker attempts one side of a merge stands for, BY TRADING DAY.

    ``max_orders_per_day`` is a per-day limit, so a flat total is the wrong
    shape for it. A prior-day recovered order merged with a fresh order placed
    today produced ``merged_attempt_count == 2``, and because the aggregate's
    claim breakdown then spans both days it is not "cross-day only" either --
    so `load_prior_same_day_allocations` charged BOTH against today, and one
    old recovery plus one fresh order could block a later valid order (Codex
    review, PR #786: "Bucket merged attempts by their trading day"). That is
    the opposite error from the one the flat count was added to fix, in the
    same line of code.

    A side carrying a ``whole_share_claim_breakdown`` is attributed to the
    day(s) that breakdown names; one without is today's own and lands in
    ``_UNDATED_ATTEMPT_DAY``. An aggregate reports its own recorded buckets.
    """
    recorded = outcome.get("merged_attempt_days")
    if isinstance(recorded, dict):
        return {
            str(day): count
            for day, count in recorded.items()
            if isinstance(count, int) and not isinstance(count, bool) and count > 0
        }
    if not _is_distinct_broker_attempt(outcome):
        return {}
    breakdown = outcome.get("whole_share_claim_breakdown")
    if isinstance(breakdown, list) and breakdown:
        days = {
            str(entry.get("trading_day"))
            for entry in breakdown
            if isinstance(entry, dict) and entry.get("trading_day")
        }
        if days:
            # One attempt, attributed to the day it was placed. A breakdown
            # naming several days belongs to several claims, so each gets one.
            return {day: 1 for day in days}
    return {_UNDATED_ATTEMPT_DAY: 1}


def _attempt_side_count(outcome: Dict[str, Any]) -> int:
    """How many broker attempts one side of a merge stands for, across all
    days -- the flat total, kept for the aggregate's own record."""
    return sum(_attempt_side_days(outcome).values())


def _broker_attempts_on_day(outcome: Dict[str, Any], trading_day_iso: str) -> int:
    """How many ``max_orders_per_day`` slots a row used ON ONE trading day.

    ``trading_day_iso`` is always THIS ARTIFACT'S OWN trading day -- that is
    the only value `load_prior_same_day_allocations` ever passes, and the
    undated bucket is defined relative to it ("the order this run placed").
    Calling this with some other day would fold today's undated attempts into
    that day's answer; there is no caller that does, and this is not a
    general per-day query.

    A row with no buckets counts 1, so an unmerged candidate is unchanged.
    """
    buckets = outcome.get("merged_attempt_days")
    if isinstance(buckets, dict):
        return sum(
            count
            for day, count in buckets.items()
            if str(day) in (trading_day_iso, _UNDATED_ATTEMPT_DAY)
            and isinstance(count, int)
            and not isinstance(count, bool)
            and count > 0
        )
    return _broker_attempt_count(outcome)


def _broker_attempt_count(outcome: Dict[str, Any]) -> int:
    """How many ``max_orders_per_day`` slots a published candidate row used.

    ``load_prior_same_day_allocations`` increments ``attempt_count`` once per
    ROW, which is right for an ordinary candidate and wrong for an aggregate:
    two recovered zero-fill attempts merge into one row carrying both order
    ids and counted as a single attempt, understating the shared daily limit
    and leaving room for a later run to place an extra live order (Codex
    review, PR #786: "Track every attempt represented by merged outcomes").

    Defaults to 1 so a row with no aggregation history counts exactly as it
    always did -- this changes the merged case only.
    """
    recorded = outcome.get("merged_attempt_count")
    if isinstance(recorded, int) and not isinstance(recorded, bool) and recorded >= 0:
        return recorded
    return 1


def _submission_count(outcome: Dict[str, Any]) -> int:
    """How many real broker submissions ``outcome`` represents: 0 if it never
    submitted, 1 for an ordinary row, and its own recorded total when it is
    itself an already-aggregated row (the batch loop merges a seeded pre-roll
    recovery with a mid-call one before merging in today's own submission, so
    an aggregate really can be an input to another aggregate).
    """
    if outcome.get("status") != "submitted":
        return 0
    if outcome.get("whole_share_settlement_adjustment"):
        # A settlement adjustment is a CORRECTION to an already-counted
        # physical order, not a second one: `_book_reconciled_whole_share_
        # order` publishes it as "submitted" carrying the SAME order_id, and
        # deliberately skips `record_buy()` for exactly this reason, as
        # `load_prior_same_day_allocations` skips its attempt count. Counting
        # it here reported two orders for one (Codex review, PR #786:
        # "Exclude settlement adjustments from submission counts").
        return 0
    recorded = outcome.get("merged_submission_count")
    if isinstance(recorded, int) and not isinstance(recorded, bool) and recorded > 0:
        return recorded
    return 1


def _submitted_orders_in_row(outcome: Dict[str, Any]) -> int:
    """The number of orders a row ALREADY established as submitted stands for.

    Deliberately separate from :func:`_submission_count`: the callers below
    have each applied their own (different) test for whether the row counts at
    all -- one checks the status, the other also requires an ``order_id`` --
    and this only answers "how many", never "does it count". Defaults to 1, so
    a row with no aggregation history counts exactly as it always did.
    """
    recorded = outcome.get("merged_submission_count")
    # ``>= 0``, not ``> 0``: an aggregate of nothing but settlement
    # adjustments records a real, meaningful zero -- every physical order it
    # corrects was counted by the run that placed it -- and reading that as
    # "no record, assume 1" would put the miscount straight back.
    if isinstance(recorded, int) and not isinstance(recorded, bool) and recorded >= 0:
        return recorded
    if outcome.get("whole_share_settlement_adjustment"):
        # The same rule for a row that was never merged at all: an adjustment
        # published on its own is still a correction to an order some earlier
        # run already counted, so this run placed no order for that ticker.
        return 0
    return 1


def _represented_order_ids_for_count(outcome: Dict[str, Any]) -> frozenset:
    """Every id-shaped ``order_id``/``whole_share_order_ids`` entry ``outcome``
    itself names, normalized -- used ONLY to detect when two SEPARATE rows
    reinjected into ``_fresh_broker_outcomes`` refer to overlapping orders,
    not as a substitute for ``_submitted_orders_in_row``'s own
    ``merged_submission_count`` (which deliberately EXCLUDES a failed/
    blocked side's own id -- see that field's own docstring -- so this
    broader set can legitimately be LARGER than the row's real submission
    count).
    """
    ids: set = set()
    order_id = outcome.get("order_id")
    if isinstance(order_id, (str, int, float, bool)):
        normalized = _normalized_order_id(order_id)
        if normalized:
            ids.add(normalized)
    whole_share_ids = outcome.get("whole_share_order_ids")
    if isinstance(whole_share_ids, list):
        ids |= {_normalized_order_id(wid) for wid in whole_share_ids if wid}
    ids.discard(None)
    return frozenset(ids)


def _grouped_submission_rows_by_represented_order(
    rows: Iterable[Dict[str, Any]], *, ticker_prefix: str
) -> List[Dict[str, Any]]:
    """Collapse ``rows`` into one representative per set of OVERLAPPING
    represented order ids, not one representative per distinct scalar
    ``order_id`` alone.

    A prior aggregate outcome (scalar ``order_id="B"``,
    ``whole_share_order_ids=["A", "B"]``, ``merged_submission_count=2``)
    reinjected alongside a PRE-EXISTING single-order row for the SAME
    scalar "B" grouped as two entries sharing the identical key under a
    plain ``setdefault(order_id, row)`` -- keeping whichever row was
    encountered FIRST and silently discarding the other. If the aggregate
    lost that race, its own second represented order "A" -- and the "2"
    submissions it stands for -- vanished from the derived
    ``orders_submitted_count``/``usage_proxy.orders_placed_count`` even
    though the reinjection loop's own dedup (see the "Deduplicate
    aggregate recoveries per represented order" fix above) had already
    decided this exact aggregate belongs in ``_fresh_broker_outcomes``
    precisely BECAUSE "A" was not yet known (Codex review, PR #1168:
    "Count unique members of partially overlapping aggregates").

    Two rows are merged into ONE group whenever their represented-id sets
    (:func:`_represented_order_ids_for_count`) share ANY id -- not just an
    exact scalar match -- and the group keeps whichever row reports the
    LARGER :func:`_submitted_orders_in_row` count as its representative,
    so a partial-overlap aggregate's own higher multiplicity always wins
    over a narrower single-order row it overlaps. An id-less row (no
    usable ``order_id`` and no ``whole_share_order_ids``) can never be
    proven to overlap with anything and keeps its own ticker-keyed
    fallback group, exactly like the callers' original bare
    ``order_id or f"ticker:..."`` fallback already did.

    A new row merges into EVERY existing group it overlaps, not just the
    first one found, and those groups are then coalesced into ONE --
    including groups that only become connected TRANSITIVELY through this
    row: rows representing ``{A}``, ``{C}``, then an aggregate ``{A, C}``
    (``merged_submission_count=2``) used to merge the aggregate into
    whichever of the ``{A}``/``{C}`` groups the old first-match-then-break
    loop reached first, leaving the OTHER as a separate group and
    reporting three submissions (``2 + 1``) for the two PHYSICAL orders
    the three rows actually represent (Codex review, PR #1169: "Merge
    every transitively overlapping submission group").

    The group's own reported count is the UNION of its rows' represented
    ids, not merely whichever single row happened to report the larger
    :func:`_submitted_orders_in_row` count: two PARTIALLY overlapping
    aggregates -- ``{A, B}`` and ``{B, C}``, each with
    ``merged_submission_count=2`` -- coalesce their id sets into ``{A, B,
    C}`` here, but keeping only the larger representative row's own count
    (``2``) reported 2 physical orders for the 3 the union actually names,
    understating ``orders_submitted_count``/``counts.submitted``/
    ``usage_proxy.orders_placed_count`` in the regenerated artifacts
    (Codex review, PR #1169: "Count unique IDs across overlapping
    aggregates"). A settlement-adjustment-only row (count ``0``, per
    :func:`_submitted_orders_in_row`) contributes its ids for OVERLAP
    detection -- it can still be the transitive link connecting two
    otherwise-separate real groups -- but never contributes them to the
    counted total, since it corrects an order some other row (or an
    earlier run) already counted, not a submission of its own.

    ONLY trusted, though, when every row entering a group is itself
    "id-count-consistent" -- its own :func:`_submitted_orders_in_row`
    exactly equals the number of ids :func:`_represented_order_ids_for_count`
    found for it (or is ``0``, the adjustment case). ``merged_submission_
    count`` is an opaque, independently-set field with no guarantee it
    matches how many ids happen to be listed: a lone row can legitimately
    report ``merged_submission_count=3`` while naming only ONE id (no
    ``whole_share_order_ids`` at all) when its extra submissions were never
    individually tracked by id. Trusting ``len(ids)`` there collapsed that
    row's already-correct count of 3 down to 1. A group containing any such
    row falls back to the ORIGINAL representative-row selection (the
    larger single count) instead of the id-union count, which is exactly
    this function's own pre-existing behavior for a row that never merges
    with anything.
    """
    groups: List[Tuple[frozenset, frozenset, bool, Dict[str, Any]]] = []
    idless_groups: Dict[str, Dict[str, Any]] = {}
    for row in rows:
        ids = _represented_order_ids_for_count(row)
        if not ids:
            idless_groups.setdefault(f"{ticker_prefix}{row.get('ticker')}", row)
            continue
        row_count = _submitted_orders_in_row(row)
        row_id_count_consistent = row_count == len(ids) or row_count == 0
        merged_ids = set(ids)
        merged_counted_ids = set(ids) if row_count > 0 else set()
        merged_consistent = row_id_count_consistent
        merged_row = row
        remaining_groups: List[Tuple[frozenset, frozenset, bool, Dict[str, Any]]] = []
        for group_ids, group_counted_ids, group_consistent, group_row in groups:
            if merged_ids & group_ids:
                merged_ids |= group_ids
                merged_counted_ids |= group_counted_ids
                merged_consistent = merged_consistent and group_consistent
                if _submitted_orders_in_row(group_row) > _submitted_orders_in_row(merged_row):
                    merged_row = group_row
            else:
                remaining_groups.append((group_ids, group_counted_ids, group_consistent, group_row))
        remaining_groups.append(
            (frozenset(merged_ids), frozenset(merged_counted_ids), merged_consistent, merged_row)
        )
        groups = remaining_groups
    representatives = []
    for _, counted_ids, consistent, group_row in groups:
        if consistent:
            union_count = len(counted_ids)
            if union_count != _submitted_orders_in_row(group_row):
                group_row = dict(group_row)
                group_row["merged_submission_count"] = union_count
        representatives.append(group_row)
    return representatives + list(idless_groups.values())


def _outcome_records_a_broker_attempt(outcome: Dict[str, Any]) -> bool:
    """Whether today's own outcome for a ticker represents a real, broker-
    facing placement call -- the test the batch loop applies before deciding
    whether an earlier day's recovered fill may REPLACE it or must be MERGED
    with it.

    ``_PRIOR_ALLOCATION_ATTEMPT_STATUSES`` (submitted/filled/failed) does not
    cover every such call. A whole-share placement whose own reconciliation
    lookup then raised is recorded ``"blocked"`` -- deliberately, so the ledger
    claim stays RESERVED pending manual reconciliation -- and a
    confirmation-required hold is recorded
    ``"not_submitted_confirmation_required"``. Both really did call the broker;
    neither is in that set, so both were replaced wholesale by the recovered
    row, taking the failure marker, the terminal order id and the "claim left
    reserved" reason with them (Codex review, PR #786: "Preserve blocked
    placement failures beside recovered fills").

    The explicit ``broker_placement_failed`` marker is what makes those
    recognizable: it is set only by branches that really did reach the broker,
    never by a policy block decided before submission (a budget cap, the
    duplicate guard, a whitelist), which is why a status test alone cannot
    stand in for it.
    """
    return bool(
        outcome.get("status") in _PRIOR_ALLOCATION_ATTEMPT_STATUSES
        or outcome.get("broker_placement_failed")
    )


def _fire_attempt_reached_the_broker(outcome: Dict[str, Any]) -> bool:
    """Whether an inverse-Martingale fire this run CLAIMED was ever actually
    attempted at the broker.

    ``max_fire_attempts`` is a retry budget for orders the broker refused, so
    only a real broker-facing call may consume one. Two shapes never make that
    call and must not:

    * ``dry_run`` -- no order is ever submitted in that mode, so a repeated
      scheduled dry-run/``--demo`` invocation would otherwise abandon a
      recovered cycle's accumulated balance after ``max_fire_attempts``
      dry runs (Codex review: "Do not count dry runs as fire attempts").
    * a candidate the CONSECUTIVE-FAILURE BREAKER never reached. Those rows
      are ``status='skipped'`` with ``deliberate_skip`` on the unattempted
      tail, or a recovered row annotated ``today_order_not_attempted`` -- and
      they are the breaker's whole point: the batch stopped BEFORE this
      ticker, so nothing about this ticker's own order was ever tried. Counted
      as attempts, a broker outage that trips the breaker on three consecutive
      mornings silently abandons every accumulated cycle behind it, which
      inverts the mode's "deferred, not lost" contract exactly as the dry-run
      case did (Codex review, PR #786: "Do not count breaker-skipped inverse-
      Martingale fires").

    The row that TRIPPED the breaker is deliberately NOT exempt: its own
    placement really was attempted and really did fail, which is precisely
    what the retry budget is counting. It carries
    ``placement_breaker_tripped_here`` and never ``deliberate_skip``.
    """
    if outcome.get("status") == "dry_run":
        return False
    if outcome.get("placement_breaker_halted") and (
        outcome.get("deliberate_skip") or outcome.get("today_order_not_attempted")
    ):
        return False
    return True


def _outcome_is_mergeable_recovery(outcome: Dict[str, Any]) -> bool:
    """Whether an already-published row represents a real broker attempt that
    a later publication for the same ticker must MERGE with rather than
    overwrite.

    Two shapes qualify, and the second is the one a bare ``status ==
    "submitted"`` test misses. ``_book_reconciled_whole_share_order``'s
    zero-fill branch deliberately reports ``status="failed"`` -- nothing was
    purchased -- while still describing a REAL broker order that consumed a
    ``max_orders_per_day`` slot, and marks it ``whole_share_zero_fill_
    attempt``. When one ticker has several unresolved claims and the zero-fill
    one is reconciled FIRST, the later filled claim overwrote it outright,
    dropping the consumed attempt and its order id from the artifact --
    so prior-allocation loading undercounts the daily limit and the run is
    classified without that attempt (Codex review, PR #786: "Merge recovered
    zero-fill attempts before later submissions").

    The batch loop has tested for exactly this pair since the zero-fill branch
    was added; this publication site was still on the narrower status check.
    Shared here so the two cannot drift apart again.
    """
    return bool(
        outcome.get("status") == "submitted"
        or outcome.get("whole_share_zero_fill_attempt")
    )


def _merge_whole_share_submission_outcomes(
    existing: Dict[str, Any], new: Dict[str, Any]
) -> Dict[str, Any]:
    """Combine two broker-attempt whole-share outcomes for the SAME ticker
    into one, when both represent real, independent broker orders -- e.g.
    two separate unresolved claims recovered in the same pre-roll pass, or
    a recovered fill and today's own fresh submission.

    Sums ``submitted_amount_usd``/``whole_share_quantity`` so
    ``dca_risk.deployed_usd()`` (which sums exactly this field over
    ``submitted`` ``buy_candidates`` rows) counts BOTH orders' capital, not
    just whichever call happened to publish last (Codex review: "Aggregate
    all recovered claims for the same ticker", "Preserve recovered fills
    when processing today's candidate"). ``order_id`` stays a SINGLE, exact
    broker order id (the newer of the two) rather than a synthetic joined
    string -- exact-ID consumers such as ``reconcile_foreground_orders()``
    cannot match a composite ``"old-id,new-id"`` against either real broker
    record (Codex review: "Preserve each broker order ID when aggregating
    outcomes"). Every distinct order id involved is still recorded, in
    ``whole_share_order_ids``, for audit/debugging.
    """
    merged = dict(new)
    # If EITHER independent attempt moved (or may still move) capital, the
    # aggregate is a submission. ``merged = dict(new)`` alone would let
    # today's non-submitting attempt -- a rejected placement, or
    # _process_buy_candidates_batch's own isolation-net "failed" row --
    # decide the status for a row that also carries a REAL recovered fill,
    # so the recovered order silently stops counting as one. Two failed
    # attempts stay failed.
    if existing.get("status") == "submitted" or new.get("status") == "submitted":
        merged["status"] = "submitted"
        # ... but the aggregate STATUS is not the only thing the run reports.
        # A recovered fill from an older claim and a fresh placement that
        # FAILED today are two independent events, and forcing "submitted"
        # made the second invisible: `_apply_no_order_classification` counts
        # `status == "failed"` rows, so a run whose today-order was rejected
        # recorded as an ordinary submitted run with no is_trading_failure,
        # no failure outcome and no error class (Codex review, PR #786:
        # "Preserve fresh placement failures when merging recoveries"). The
        # marker rides alongside the status rather than fighting it -- the
        # recovered order really did submit, and today's really did fail.
        for side in (existing, new):
            if side.get("status") == "failed":
                merged["merged_placement_failed"] = True
                # Whichever side failed keeps its own reason readable; the
                # merged row's own skip_reason belongs to `new`.
                merged.setdefault(
                    "merged_failure_reason", side.get("skip_reason")
                )
            # A "blocked" side carrying the broker_placement_failed marker is
            # NOT the same event as a "failed" one, and collapsing the two
            # would misreport it: `_apply_no_order_classification` counts a
            # non-deliberate block as a CONNECTOR ERROR (a pre-placement or
            # reconciliation call that raised, claim left reserved for a human)
            # and a "failed" row as an order that failed. Forcing the aggregate
            # status to "submitted" hid the block just as completely as it hid
            # the failure, so it needs its own marker rather than borrowing the
            # failure one (Codex review, PR #786: "Preserve blocked placement
            # failures beside recovered fills").
            elif side.get("status") == "blocked" and side.get(
                "broker_placement_failed"
            ) and not side.get("deliberate_skip"):
                merged["merged_placement_blocked"] = True
                merged.setdefault(
                    "merged_failure_reason", side.get("skip_reason")
                )
            # A confirmation-required hold carries broker_placement_failed too
            # -- a real broker call was made -- so the round-28 predicate here
            # ("any non-submitted side with the marker") captured it and
            # reported the run as a partial placement FAILURE with error_class
            # degraded_market_data. That is not what this status means:
            # everywhere else in this module a confirmation hold is a routine
            # non-error outcome (`_derive_order_submit_status` gives it its own
            # ORDER_SUBMIT_STATUS_CONFIRMATION_REQUIRED, and the attempt
            # counters exclude it) unless the breaker trips on a run of them
            # (Codex review, PR #786: "Exclude confirmation holds from merged
            # connector errors"). The same mistake as the round-28 scoping this
            # narrows: the predicate was written wider than the case it was
            # reasoned about.
            #
            # It still gets a marker, on a key that classifies nothing. The
            # merge forces the row's status to "submitted", so without one the
            # hold would vanish from the artifact entirely -- and a merged row
            # silently swallowing its second event is the exact failure this
            # whole marker family exists to prevent.
            elif side.get("status") == "not_submitted_confirmation_required":
                merged["merged_confirmation_required"] = True
                merged.setdefault(
                    "merged_confirmation_reason", side.get("skip_reason")
                )
    # A failure outcome can still carry the REQUESTED order notional in
    # submitted_amount_usd for diagnostics even though the broker confirmed
    # no deployment, so only sides that actually submitted contribute here
    # -- dca_risk.deployed_usd() sums exactly this field.
    merged["submitted_amount_usd"] = round(
        (existing.get("submitted_amount_usd") or 0.0 if existing.get("status") == "submitted" else 0.0)
        + (new.get("submitted_amount_usd") or 0.0 if new.get("status") == "submitted" else 0.0),
        2,
    )
    merged["whole_share_quantity"] = (
        (existing.get("whole_share_quantity") or 0) + (new.get("whole_share_quantity") or 0)
    )
    # How many real broker SUBMISSIONS this one row now stands for. The
    # aggregate's notional and share count are summed above, but the row is
    # still one dict, and both activity counters count ROWS: two unresolved
    # claims for the same ticker recovered in one run reported
    # orders_submitted_count 1 and usage_proxy.orders_placed_count 1 while
    # execution logging and the order artifacts carried both orders, so the
    # top-level metrics disagreed with the files underneath them (Codex
    # review, PR #786: "Count every order represented by a merged outcome").
    #
    # An explicit count rather than len(whole_share_order_ids): that list is
    # deliberately wider than "orders that submitted" -- it also carries a
    # failed or blocked side's own terminal order id, so that the id stays
    # reconcilable (see the round-28 merged_placement_blocked case) -- and
    # counting it would report a submission for an order the broker refused.
    merged["merged_submission_count"] = _submission_count(existing) + _submission_count(new)
    # Attempts are counted SEPARATELY from submissions, because they are a
    # different question and the two genuinely differ: two recovered zero-fill
    # attempts submitted nothing and still consumed two `max_orders_per_day`
    # slots. Recording only submissions left that row counted as one attempt
    # (Codex review, PR #786: "Track every attempt represented by merged
    # outcomes").
    # Per DAY, because `max_orders_per_day` is a per-day limit -- see
    # _attempt_side_days. The flat total rides alongside for the record.
    merged_days: Dict[str, int] = {}
    for side in (existing, new):
        for day, count in _attempt_side_days(side).items():
            merged_days[day] = merged_days.get(day, 0) + count
    merged["merged_attempt_days"] = merged_days
    merged["merged_attempt_count"] = sum(merged_days.values())
    # ``merged = dict(new)`` copies whatever ``new`` carried, and
    # ``whole_share_settlement_adjustment`` is a claim about the WHOLE row: it
    # means "this row is a correction to an order some earlier booking already
    # counted". That is false the moment the aggregate also contains a real
    # physical order, and the copy asserted it anyway whenever the adjustment
    # happened to be the newer side. Two things then read it and got the wrong
    # answer: `load_prior_same_day_allocations` skipped the attempt count for
    # an aggregate that really does contain a placement, understating the
    # shared max_orders_per_day usage; and `_submission_count` -- which round
    # 30 taught to return 0 for an adjustment -- reported zero for the whole
    # aggregate, so re-merging it (the batch loop routinely merges an
    # already-merged row again) discarded the real order's own count (Codex
    # review, PR #786: "Clear adjustment marker from mixed submission
    # aggregates").
    #
    # Kept only when EVERY submitting side is an adjustment, which is the one
    # case where the claim is still true of the row as a whole.
    # ANY distinct broker attempt clears it, not only a submission. The first
    # version of this test read `status == "submitted"`, which is narrower than
    # the reason given for it: a zero-fill recovery reports `status="failed"`
    # because nothing was purchased while still being a real order that took a
    # slot, and a rejected placement likewise. Merging one of those with an
    # adjustment produced a row carrying BOTH markers, and
    # `load_prior_same_day_allocations` reads the adjustment one -- skipping
    # the attempt entirely, understating `max_orders_per_day` and leaving room
    # for an extra live order (Codex review, PR #786: "Clear adjustment marker
    # when merging any real attempt").
    if any(_is_distinct_broker_attempt(side) for side in (existing, new)):
        merged.pop("whole_share_settlement_adjustment", None)
    # ``merged = dict(new)`` carries NEW's markers and silently drops
    # EXISTING's. That is invisible while `existing` is a plain outcome --
    # the status checks below rebuild the markers from its status -- and
    # wrong the moment `existing` is itself an AGGREGATE: its status is
    # already "submitted", so those checks see two submitted sides and
    # recreate nothing, and a recovery merged with a failed attempt and
    # then merged again with a second recovery reported an ordinary
    # successful multi-order run with no trading failure at all (Codex
    # review, PR #786: "Carry aggregate failure markers through subsequent
    # merges"). The same `dict(new)` blind spot round 31 found from the
    # other direction, where a whole-row claim was wrongly CARRIED rather
    # than wrongly dropped.
    #
    # Unioned explicitly from BOTH sides rather than relying on `dict(new)`
    # to carry half of the contract. That makes the preservation rule
    # symmetric when an already-aggregated outcome arrives as either argument
    # and keeps future changes to the initial copy from silently weakening it.
    # `setdefault` on the reasons keeps the newer side's prose when both sides
    # provide one, matching the rest of the merged row.
    for side in (existing, new):
        for marker in (
            "merged_placement_failed",
            "merged_placement_blocked",
            "merged_confirmation_required",
            # A recovered zero-fill attempt is a real broker attempt that must
            # keep counting as one; every consumer reads this marker as an
            # INCLUSION test ("persist/count this row"), never as an exclusion,
            # so an aggregate containing one genuinely carries it.
            "whole_share_zero_fill_attempt",
        ):
            if side.get(marker):
                merged[marker] = True
        for reason_key in ("merged_failure_reason", "merged_confirmation_reason"):
            if side.get(reason_key) is not None:
                merged.setdefault(reason_key, side.get(reason_key))
    existing_ids = existing.get("whole_share_order_ids") or (
        [existing["order_id"]] if existing.get("order_id") else []
    )
    # ``new`` can itself already be a PREVIOUSLY-aggregated outcome (e.g. the
    # outer batch loop merging a seeded pre-roll recovery with an
    # already-merged mid-call recovery, before merging in today's own fresh
    # submission) -- consuming only new["order_id"] then silently drops
    # every id BUT the newest from new["whole_share_order_ids"], and since
    # scripts/foreground_primary.reconcile_foreground_orders validates
    # exactly the ids present in this list, the dropped broker order is
    # never reconciled and drift detection can falsely pass (Codex review:
    # "Merge every ID from pre-aggregated outcomes"). Union BOTH sides' full
    # id lists rather than picking one id off each.
    new_ids = new.get("whole_share_order_ids") or (
        [new["order_id"]] if new.get("order_id") else []
    )
    merged_ids = list(existing_ids)
    for new_id in new_ids:
        if new_id and new_id not in merged_ids:
            merged_ids.append(new_id)
    merged["whole_share_order_ids"] = merged_ids
    # ``merged = dict(new)`` above means the top-level scalar ``order_id`` is
    # whatever ``new`` carried. When ``new`` is a failed attempt -- with no id
    # of its own, or with its own rejected/zero-fill id -- that scalar stops
    # representing the side that actually deployed capital, even though the
    # real id is still present in ``whole_share_order_ids`` above.
    # build_usage_proxy counts orders-placed off this top-level field, and
    # load_prior_same_day_allocations() skips a whole aggregate row whose
    # scalar id appears in terminal_order_ids, so either shape erases real
    # recovered spend from cap and duplicate-buy accounting. Prefer the
    # submitting side's id whenever it is the only one that submitted, and
    # otherwise fall back to it only when the newer side supplied none.
    if new.get("status") != "submitted" and existing.get("status") == "submitted" and existing.get("order_id"):
        merged["order_id"] = existing.get("order_id")
    elif not merged.get("order_id") and existing.get("order_id"):
        merged["order_id"] = existing.get("order_id")
    # Concatenates rather than picking one -- see
    # _book_reconciled_whole_share_order's own comment on why a single
    # scalar claim-date override cannot survive aggregating claims from two
    # DIFFERENT trading days. A submission with no breakdown of its own
    # (e.g. today's own ordinary fresh buy, not a reconciled recovery)
    # contributes nothing to the list -- dca_risk.deployed_usd_by_claim_date()
    # attributes whatever notional isn't covered by the breakdown to this
    # artifact's own trading_day, exactly like an ordinary candidate.
    merged_breakdown = list(existing.get("whole_share_claim_breakdown") or [])
    merged_breakdown.extend(new.get("whole_share_claim_breakdown") or [])
    if merged_breakdown:
        merged["whole_share_claim_breakdown"] = merged_breakdown
    # merged = dict(new) above keeps only NEW's own settlement-state
    # fields -- if `existing` is a recovered live order still awaiting
    # ledger settlement (whole_share_settlement_reconciliation_needed=True,
    # possibly with a nonzero whole_share_settlement_shortfall_usd from a
    # clamped fire whose settle() call itself failed) and this same ticker
    # then submits a fresh, cleanly-settled order in this SAME run, the
    # fresh outcome's own (False/0.0) settlement fields would silently
    # overwrite and discard the unresolved recovery's marker and any
    # outstanding shortfall -- the persisted evidence an operator needs
    # when ledger settlement fails would simply vanish from the merged row
    # (Codex review: "Preserve settlement state when aggregating
    # outcomes"). OR the reconciliation-needed flag (true if EITHER side
    # still needs it) and SUM any outstanding shortfalls, mirroring how
    # submitted_amount_usd/whole_share_quantity are already aggregated
    # above rather than overwritten.
    merged["whole_share_settlement_reconciliation_needed"] = bool(
        existing.get("whole_share_settlement_reconciliation_needed")
    ) or bool(new.get("whole_share_settlement_reconciliation_needed"))
    merged["whole_share_settlement_shortfall_usd"] = round(
        (existing.get("whole_share_settlement_shortfall_usd") or 0.0)
        + (new.get("whole_share_settlement_shortfall_usd") or 0.0),
        2,
    )
    return merged


def _publish_in_flight_outcome(ticker: str, outcome: Dict[str, Any]) -> None:
    """Record a placement outcome for the failure handler as soon as it exists.

    Called from inside the per-candidate path rather than waiting for the batch
    loop to store the returned value, so an order the broker has already accepted
    is never lost to a raise in the follow-up work between placement and return.
    """
    outcomes = _IN_FLIGHT_CANDIDATE_OUTCOMES.get("outcomes")
    if outcomes is not None:
        outcomes[ticker] = outcome


def _publish_or_merge_whole_share_outcome(ticker: str, outcome: Dict[str, Any]) -> None:
    """Like :func:`_publish_in_flight_outcome`, but AGGREGATES with an
    existing published ``"submitted"`` outcome for the same ticker instead
    of overwriting it.

    Used specifically by :func:`_book_reconciled_whole_share_order`: the
    cross-day reconciliation pass's own per-ticker loop
    (:func:`_reconcile_cross_day_whole_share_claims`) can settle MULTIPLE
    separate unresolved claims for the SAME ticker in one call (e.g. two
    different earlier trading days both left an unresolved claim), and each
    settled claim calls this booking helper independently -- a plain
    overwrite left only the LAST claim's notional/quantity visible to
    ``_build_buy_candidates``, silently dropping the first from
    ``dca_risk.deployed_usd()``'s next-run kill-switch seeding (Codex
    review: "Aggregate all recovered claims for the same ticker").
    """
    outcomes = _IN_FLIGHT_CANDIDATE_OUTCOMES.get("outcomes")
    if outcomes is None:
        return
    existing = outcomes.get(ticker)
    if existing is not None and _outcome_is_mergeable_recovery(existing):
        outcome = _merge_whole_share_submission_outcomes(existing, outcome)
    outcomes[ticker] = outcome


@dataclass(frozen=True)
class RunContext:
    """Immutable execution context for a single afternoon DCA run.

    Bundles ``run_once``'s inputs and options -- broker, data providers,
    artifact directory, etc. -- into a single object rather than a long
    keyword-argument list. Mirrors the individual parameters
    :func:`_run_once_impl` still accepts; ``run_once`` unpacks this back
    into that call.
    """

    now: datetime
    config: StrategyConfig
    state: StrategyState
    finance_data: MarketDataProvider
    robinhood_data: MarketDataProvider
    broker: BrokerAdapter
    artifacts_dir: Optional[str | Path] = None
    run_result: Optional[RunResult] = None
    notifications_sent: Optional[int] = None
    cost_control_notes: Optional[Sequence[str]] = None
    prior_same_day_allocations: Optional[Dict[str, PriorSameDayAllocation]] = None
    deployment_history_root: Optional[str | Path] = None
    scheduled: bool = True
    classification_state_root: Optional[str | Path] = None
    raw_persistence_state: Optional[Dict[str, object]] = None
    classification_overrides: Optional[Dict[str, Any]] = None
    correlation_id: Optional[str] = None
    stream: str = "afternoon"
    earlier_week_notional_usd: float = 0.0
    earlier_week_scan_had_failures: bool = False


def run_once(
    ctx: RunContext,
) -> List[ReconciledDecision]:
    """Run the afternoon scan, guaranteeing an artifact set even when it raises.

    The scheduled contract requires the complete root-level artifact set on every
    outcome, but nothing wrapped this path: an exception from the account lookup,
    signal evaluation, or any per-candidate broker check escaped before
    _finalize_and_write_artifacts ran, so the slot produced no artifacts at all,
    and a failure after an earlier order was accepted lost that submission from
    the canonical state (Codex review). This mirrors MorningDCAExecutor.run.
    """
    # Clear any in-flight state from a PREVIOUS call before anything can fail, or
    # a startup failure here would record the prior run's orders as this one's.
    _IN_FLIGHT_CANDIDATE_OUTCOMES.pop("outcomes", None)
    # Cleared for the same reason and at the same moment: a startup failure in
    # THIS call must not describe itself with the PREVIOUS run's evaluated
    # universe, signal rows and caps.
    _IN_FLIGHT_RUN_EVALUATION.clear()
    scheduled = ctx.scheduled
    try:
        return _run_once_impl(ctx)
    except Exception as exc:  # noqa: BLE001 - always re-raised below
        if ctx.artifacts_dir:
            try:
                _write_afternoon_failure_artifacts(
                    ctx.artifacts_dir,
                    ctx.now,
                    exc,
                    classification_state_root=ctx.classification_state_root,
                    classification_overrides=ctx.classification_overrides,
                    correlation_id=ctx.correlation_id,
                    scheduled=scheduled,
                    # ctx.run_result is the SAME object _run_once_impl mutated
                    # before raising -- its execution_records survive the
                    # exception since this is a reference, not a copy.
                    execution_records=(
                        ctx.run_result.execution_records if ctx.run_result is not None else None
                    ),
                    broker=ctx.broker,
                    broker_name=ctx.config.broker.value,
                )
            except Exception:  # noqa: BLE001 - never mask the original failure
                logger.exception(
                    "failed to write afternoon failure artifacts to %s; re-raising "
                    "the original run failure",
                    ctx.artifacts_dir,
                )
        raise


def _coerce_nonnegative_int(value: Any, default: int = 0) -> int:
    """Parse ``value`` as a non-negative int, or return ``default`` for anything else.

    A preserved artifact field like ``usage_proxy.errors_count`` can be
    corrupted by whatever wrote the earlier state -- a mapping, a
    non-numeric string, ``NaN`` -- and a bare ``int(value or 0)`` raises on
    any of those. Used where that raise is unacceptable: it aborted the
    WHOLE failure-artifact write further down in
    :func:`_write_afternoon_failure_artifacts`, silently discarding a
    newly-published, possibly-live recovery this same call had already
    computed, despite this function otherwise treating malformed preserved
    fields defensively (Codex review, PR #859: "Parse preserved error
    counts defensively"). A bool is rejected like every other malformed
    shape in this module -- ``int(True)`` is a real integer but not an
    honest count -- and a negative parse is treated as malformed too: a
    count can never be negative.

    ``OverflowError`` is caught alongside ``TypeError``/``ValueError``:
    Python's JSON loader happily accepts ``Infinity``/``-Infinity`` as a
    float, and converting an infinite float straight to ``int`` raises
    ``OverflowError`` rather than either of those -- an artifact carrying
    a preserved ``errors_count`` of ``Infinity`` aborted the SAME whole
    failure-artifact write this function exists to keep from aborting,
    discarding a newly-published, possibly-live placement (Codex review,
    PR #859 round 35: "Reject non-finite preserved error counts").
    """
    if isinstance(value, bool):
        return default
    try:
        parsed = int(value)
    except (TypeError, ValueError, OverflowError):
        return default
    return parsed if parsed >= 0 else default


# Same account-shaped-literal detection test_config_invariants.py's own
# tracked-source scan uses, so a brokerage account number surfacing inside
# an exception message is caught by the identical rule that forbids it
# everywhere else in this repo -- not a narrower, independently-reasoned
# pattern that could disagree with it.
#
# The trailing lookahead is `(?!\w|\.\d)`, not the simpler `(?![\w.])`: a
# bare `(?![\w.])` also refuses to match when the digits are immediately
# followed by ANY period, including one that is ordinary sentence-ending
# punctuation -- "...for account 123456789." (the connector's own message
# ending the sentence there) left the account number unredacted, since the
# lookahead rejected the match at that position and no shorter/different
# match ever recovers it. Only a period immediately followed by ANOTHER
# digit -- an actual decimal continuation like "123456789.05" -- still
# blocks the match, exactly like before; a period followed by whitespace,
# a quote, end-of-string, or anything else is not a decimal point and must
# not shield the digits in front of it (Codex review, PR #859/#911 round
# 44: "Redact account numbers followed by sentence punctuation").
_ACCOUNT_SHAPED_LITERAL = re.compile(r"(?<![.\w])\d{6,12}(?!\w|\.\d)")
# `_ACCOUNT_SHAPED_LITERAL`'s own leading lookbehind `(?<![.\w])` exists to
# avoid mis-redacting a digit run that is merely a SUBSTRING of some larger,
# unrelated word-character token (a hash, a version string) -- but that same
# guard also refuses to match the far more common shape a connector's own
# exception text actually uses: the account number glued directly onto an
# identifying label, as `account_123456789` or `acct123456789`, where the
# character immediately before the digits is part of that very label, not
# an unrelated token. `_ACCOUNT_SHAPED_LITERAL` alone left the account
# number in those two spellings completely unredacted, in a message
# `run_state.json` persists to disk -- the exact leak this repo's account-
# number secrecy invariant (AGENTS.md) exists to prevent (Codex review, PR
# #1169: "Redact account digits adjacent to identifier text"). Matched and
# redacted separately, keeping the identifying label itself intact (only
# the digits are a secret) rather than widening the shared literal pattern
# and risking a new false positive on ordinary unrelated tokens.
#
# The label alternation also accepts an optional "number"/"id" word
# fused directly onto "account"/"acct" -- with no separator at all
# (camelCase: "accountNumber123456789"), with an underscore separator
# ("account_id_123456789"), or the combination -- not just the bare
# "account"/"acct" word alone. A connector rendering the account
# identifier as `accountNumber123456789`, `accountId123456789`, or
# `account_number_123456789` has a WORD character (the "N" of "Number",
# the "i" of "id") directly before the digit run, so this pattern's own
# `[_-]?` separator (requiring nothing but an optional underscore/hyphen)
# never matched past that extra word, and the general
# `_ACCOUNT_SHAPED_LITERAL` pattern independently refuses to match here
# too (its own leading lookbehind rejects a digit run preceded by a word
# character). Both patterns left the account number in these three
# common compound-label spellings completely unredacted, in a message
# `run_state.json` persists to disk (Codex review, PR #1168: "Redact
# compound account-number labels"). The whole compound label -- not just
# the bare "account"/"acct" word -- is captured into group 1 so the
# replacement keeps it intact ("accountNumber[REDACTED]"), the same
# "keep the label, redact only the digits" convention this pattern
# already follows for the bare-word case.
#
# The compound-suffix alternation also accepts "no"/"nbr"/"num", not just
# "number"/"id": a connector using a compact abbreviated label --
# `accountNo123456789`, `acctNbr123456789` -- has the same word-character-
# before-digits shape the "number"/"id" fix above addresses, and neither
# that fix nor the general `_ACCOUNT_SHAPED_LITERAL` pattern matched these
# equally common compact spellings, leaving the account number
# unredacted in a message `run_state.json` persists to disk (Codex
# review, PR #1169: "Redact compact account-number abbreviations").
#
# The separator between the label and the digits also accepts "." --
# not just "_"/"-": a connector spelling `accountNo.123456789` or
# `acctNbr.123456789` has a period directly between the compact label
# and the digits, which neither this pattern's own separator class nor
# `_ACCOUNT_SHAPED_LITERAL` (whose lookbehind independently refuses a
# digit run preceded by a period) matched, leaving the account number
# unredacted (Codex review, PR #1169: "Redact dotted account-number
# labels"). Safe here specifically because the "." is only ever
# consumed immediately after an explicit "account"/"acct" label this
# pattern already requires -- an ordinary decimal amount elsewhere in
# the message never reaches this alternation at all.
_ACCOUNT_LABELED_DIGITS = re.compile(
    r"(?i)((?:account|acct)(?:[_-]?(?:number|id|no|nbr|num))?)[_.-]?(\d{6,12})(?!\d)"
)
# Basic-auth credentials embedded in a URL (``https://user:pass@host/...``).
_URL_EMBEDDED_CREDENTIALS = re.compile(r"://[^/\s@]+:[^/\s@]+@")
# A labeled secret anywhere in the message -- a query parameter, a header
# rendered into a connector's own exception text, or a plain "key: value"
# pair -- covering the same credential-parameter shapes .jules/sentinel.md's
# own accumulated learnings (API key leakage in error logs, Pipedream token
# logging) already name.
#
# The value is everything up to the end of the line, not `\S+`: a standard
# ``Authorization: Bearer <token>`` header value is TWO space-separated
# tokens, and `\S+` consumed only the first ("Bearer"), leaving the actual
# secret ("supersecret" or a real token) sitting in the redacted message
# untouched -- the same gap for any multi-token labeled value, not just
# this one header shape (Codex review, PR #859 round 36: "Redact complete
# authorization header values"). Redacting to end-of-line is deliberately
# broad rather than trying to bound the value precisely -- a manual run's
# exception text is free-form connector output, and over-redacting a few
# extra characters of a diagnostic message costs far less than leaving a
# credential in a persisted artifact.
#
# The label itself is captured as `(?:[\w-]*[_-])?(token|...)`, not the
# bare word alone: a leading `\b` cannot match immediately before `token`
# or `secret` when the preceding character is `_`, since both `_` and a
# letter are word characters and there is no boundary between them. An
# OAuth-based connector's own exception text ordinarily uses exactly that
# shape -- `access_token=...`, `refresh_token=...`, `client_secret=...` --
# and those previously passed through this filter unredacted even after
# the authorization-header fix above (Codex review, PR #859 round 39:
# "Redact underscored OAuth credential labels"). Capturing the optional
# underscore/hyphen-joined prefix into the same group the replacement
# re-inserts keeps the redacted message readable (`access_token=
# [REDACTED]`, not just `token=[REDACTED]` with the prefix silently
# dropped).
#
# An optional quote (`'` or `"`) is now permitted both immediately after
# the label and immediately after the separator: ordinary JSON/Python-repr
# rendering of a credential mapping -- `{"access_token": "supersecret"}` or
# `{'client_secret': 'supersecret'}`, exactly what an OAuth-based
# connector's own exception text can carry -- puts the label's OWN closing
# quote between it and the `:`, which the separator pattern (whitespace
# then `[=:]` then whitespace) could not cross: `\s*` never matches a `"`,
# so the whole match failed at that position and the credential passed
# through unredacted (Codex review, PR #859/#911 round 44: "Redact quoted
# JSON credential labels"). Both quote positions are independently
# optional, so every previously-supported unquoted/space-separated shape
# (`access_token=...`, `Bearer ...`, `API key: ...`) still matches exactly
# as before.
#
# The optional prefix also accepts a camelCase lead-in now: `clientSecret`/
# `accessToken` -- the OTHER common JSON credential naming convention
# alongside `client_secret`/`access_token` -- has no `_`/`-` separator at
# all, just a lowercase-to-uppercase letter transition, so the underscore/
# hyphen-only prefix never consumed "client"/"access" and the following
# `\b` found no boundary between two word characters ("t" then "S"),
# failing the match entirely (Codex review, PR #859/#911 round 44: "Redact
# camelCase credential labels"). Detecting that transition needs real case
# information, which a blanket `(?i)` flag erases -- so the top-level flag
# is replaced with a scoped `(?i:...)` around just the keyword alternation
# (still fully case-insensitive: "API", "Bearer", "TOKEN" all still match),
# leaving the surrounding boundary/prefix logic case-SENSITIVE, exactly
# where the camelCase-vs-not distinction actually lives.
#
# The lead-in prefix's own character class was `[a-z]+` -- lowercase
# only -- which matched "client" in "clientSecret" but not "Client" in
# "ClientSecret"/"Access" in "AccessToken": a PascalCase-leading SDK
# emitting `ClientSecret=supersecret`/`AccessToken=supersecret` has no
# `_`/`-` separator either, and its lead-in word is itself capitalized, so
# neither the snake/kebab prefix nor the lowercase-only camelCase prefix
# ever consumed it, and the credential passed through this function
# unredacted into the persisted failure artifact. Widened to `[A-Za-z]+`
# -- any letters, so long as the SAME lookahead still requires the run to
# end right before an uppercase letter -- which still only ever engages
# immediately before the keyword alternation (never inside plain prose
# with no credential keyword at all), so this cannot widen what counts as
# a label, only which CASE its lead-in word may use (Codex review, PR
# #1164: "Redact PascalCase credential labels").
#
# The lead-in prefix's charset was `[A-Za-z]+` -- letters only, no
# digits -- which matched "OAuth"/"oauth" but not a lead-in word that
# itself contains a version number: `OAuth2AccessToken=supersecret`/
# `oauth2Token=supersecret` are common compound SDK credential labels
# (OAuth 2.0), and the digit inside "OAuth2"/"oauth2" broke the
# all-letters run the case-transition lookahead depends on, so the
# prefix consumed nothing, the keyword alternation had no `\b` word
# boundary to anchor on mid-word, and the whole match failed -- exactly
# the "no separator at all" gap the camelCase/PascalCase fixes closed
# for a plain letter transition, just one character class too narrow.
# Widened to `[A-Za-z0-9]+`, still gated on the SAME lookahead (must end
# right before an uppercase letter), so this still only ever engages
# immediately before the keyword alternation (Codex review, PR #1164:
# "Redact credential labels containing numeric prefixes").
# The alternation includes `credential(s)` and `private[-_ ]?key` alongside
# the original token/api-key/secret/password/bearer/authorization spellings:
# a connector's own exception text just as ordinarily uses a generic
# `credentials: ...`/`clientCredential=...` label, or a `private_key=...`
# spelling, as it does the narrower ones already covered -- and none of
# those generic shapes matched this alternation, so `_redacted_exception_
# detail()` passed the secret through completely unredacted into both
# failure-artifact writers' `run_state.json` (Codex review, PR #1169:
# "Redact generic credential labels from persisted errors").
_LABELED_SECRET = re.compile(
    r"\b((?:[\w-]*[_-])?(?:[A-Za-z0-9]+(?=[A-Z]))?"
    r"(?i:token|api[-_ ]?key|secret|password|passwd|bearer|authorization|credentials?|private[-_ ]?key))\b"
    r"['\"]?(?:\s*[=:]\s*['\"]?|\s+)"
    # A PEM-shaped value (`private_key=-----BEGIN PRIVATE KEY-----` followed
    # by base64-encoded body lines and a matching END marker) is consumed in
    # full, not just its labeled first line: the plain `[^\r\n]+` fallback
    # below stops at the first newline, so only the "-----BEGIN..." header
    # was ever redacted -- the key's own body and END marker were left
    # verbatim and persisted into `run_state.json`/the cross-account sidecar
    # (Codex review, PR #1169: "Redact the complete multiline private key").
    # Tried FIRST, before the single-line fallback, so a genuine PEM block
    # is matched by this branch rather than the greedy single-line one.
    r"(?:-----BEGIN[^\r\n]*-----[\s\S]*?-----END[^\r\n]*-----|[^\r\n]+)"
)


def _redacted_exception_detail(exc: BaseException) -> str:
    """A safe-to-persist ``"{type}: {message}"`` rendering of ``exc``.

    A broker/provider connector's own exception text can embed the
    brokerage account number, a credential-bearing URL, or a labeled
    secret (API key, token, password) -- ordinary shapes for a connection
    or authentication failure to surface. This is not hypothetical
    caution: a manual run's ``artifacts_dir`` can be an ARBITRARY,
    potentially checkout-local directory (the same risk the lease-
    fingerprint-key gitignore rule exists for), and a manual failure that
    previously produced no artifact at all now persists this exception
    text into ``run_state.json`` -- widening the exposure surface to
    exactly the class of secret this repo's own hard invariant on the
    account number, and .jules/sentinel.md's accumulated API-key-leakage
    learnings, both forbid (Codex review, PR #859 round 35: "Redact
    manual failure exception messages"). Redacted, not dropped entirely
    (``type(exc).__name__`` alone): the surrounding message is still real
    debugging value for an operator triaging a startup/placement failure,
    and the account-number/credential patterns are the specific,
    well-understood shapes this repo already treats as forbidden
    everywhere else.

    ``str(exc)`` itself is not guaranteed safe: an exception constructed
    with an oversized native int argument (e.g. a malformed broker
    response's ``RuntimeError(10**5000)``, or any exception subclass that
    embeds a rejected raw id in its own message) raises ``ValueError`` the
    instant anything renders it -- Python's integer-to-string conversion
    digit limit applies inside the exception's own default ``__str__``
    just as it does to a bare ``str()``/``repr()`` call elsewhere in this
    module. A bare ``str(exc)`` here crashed instead of persisting a safe,
    redacted diagnostic for an already-broker-accepted response (Codex
    review, PR #1169: "Render malformed exception messages safely").
    """
    return f"{type(exc).__name__}: {_redacted_diagnostic_text(_safe_exception_message(exc))}"


def _safe_exception_message(exc: BaseException) -> str:
    """``str(exc)``, or a bounded fallback when that itself raises.

    A connector -- or a stub/hostile one under test -- can raise an
    exception whose message ARGS embed a native int beyond Python's
    integer-to-string conversion digit limit (e.g. ``RuntimeError(
    10**5000)``): a bare ``str(exc)`` on it raises ``ValueError`` from
    deep inside the interpreter's own exception-formatting machinery,
    not from any code this module controls. `_write_afternoon_failure_
    artifacts` reaches exactly this call while trying to preserve the
    durable failure/possibly-live-placement evidence this whole function
    exists for, so that SECONDARY exception aborted the artifact write
    entirely -- an accepted order could then be left with no durable
    recovery record at all, the one outcome this repo's fail-closed
    evidence-preservation posture is built to prevent (Codex review, PR
    #1169: "Render malformed exception messages safely"). Every OTHER
    caller of :func:`_redacted_exception_detail` (the live placement
    failure path, the scheduled-run error artifact, ...) is equally
    exposed the moment a connector raises a pathological exception like
    this, so the guard belongs here, before redaction ever runs, rather
    than patched into each call site separately.

    Falls back to a bounded rendering of ``exc.args`` rather than just
    ``type(exc).__name__`` alone: the surrounding message is still real
    triage value for an operator, and most exceptions carry more than
    just the one unrepresentable arg (a mixed ``RuntimeError("placement
    failed for", 10**5000)`` still has a genuinely useful string arg
    alongside the oversized one). Each arg is rendered independently and
    guarded the same way, not the whole tuple at once -- one
    unrepresentable arg must not blank out every OTHER, readable arg
    sitting beside it.
    """
    try:
        return str(exc)
    except (ValueError, OverflowError):
        _arg_reprs: List[str] = []
        for _arg in exc.args:
            try:
                _arg_reprs.append(str(_arg))
            except (ValueError, OverflowError):
                _arg_reprs.append(f"<{type(_arg).__name__}: unrepresentable -- contains an oversized numeric value>")
        return f"<{type(exc).__name__} with unrepresentable message; args=({', '.join(_arg_reprs)})>"


def _redacted_diagnostic_text(message: str) -> str:
    """The same account-number/credential redaction :func:`_redacted_exception_detail`
    applies, factored out for plain diagnostic STRINGS that never had an
    exception object of their own to begin with.

    ``skip_reason``/similar candidate-outcome fields across this module
    routinely interpolate a raw exception directly (``f"... failed:
    {exc}"``), and those already-formatted strings flow into ``placed``/
    ``execution_records`` -- which
    :func:`_persist_cross_account_unresolved_evidence` persists to
    ``cross_account_unresolved_placements.json`` VERBATIM, never through
    :func:`_redacted_exception_detail` (that function only ever saw the
    single top-level failure message, not the individual outcome dicts'
    own diagnostic fields). An account number or credential already
    redacted everywhere else this repo persists exception text still
    reached this sidecar unredacted (Codex review, PR #1169: "Redact
    broker outcomes before writing account sidecars").
    """
    message = _URL_EMBEDDED_CREDENTIALS.sub("://[REDACTED]@", message)
    message = _LABELED_SECRET.sub(lambda m: f"{m.group(1)}=[REDACTED]", message)
    message = _ACCOUNT_LABELED_DIGITS.sub(lambda m: f"{m.group(1)}[REDACTED]", message)
    message = _ACCOUNT_SHAPED_LITERAL.sub("[REDACTED]", message)
    return message


def _persist_undurable_evidence_sidecar(
    artifacts_dir: str | Path,
    kind: str,
    now: datetime,
    entry: Dict[str, Any],
) -> None:
    """Best-effort, durably record evidence a bounded lock-retry loop could
    not write into its primary artifact, in its own uniquely-named file.

    Several read-modify-write passes against ``run_state.json``/
    ``run_summary.json`` retry a bounded number of times on ``TimeoutError``/
    ``OSError`` before giving up (e.g. the scheduled-contract failure
    annotation, the prior-recovery reinjection). On exhaustion, the evidence
    they were trying to record -- a contract-failure verdict, a recovered
    order -- would otherwise simply vanish: nothing else in the run persists
    it, and raising instead would misreport a run that may have already
    placed a real, live order as a hard failure (this whole call tree runs
    under ``dca_alerts.guarded_run``, which alerts the operator and pings a
    failed heartbeat on any escaping exception -- exactly the false-failure
    signal a genuinely successful placement must not produce).

    Written to its OWN uniquely-named file under ``artifacts_dir`` (keyed by
    ``kind``, this call's ISO timestamp, and a short random suffix) rather
    than appended into one shared JSON list: every writer here has already
    just exhausted several retries against a CONTENDED lock, so requiring
    yet another lock acquisition (for a shared sidecar's own read-modify-
    write) to durably record the very fact that locking is contended would
    undermine the durability this function exists to provide. A unique
    filename needs no read-modify-write at all -- the write is atomic on its
    own -- and a directory listing surfaces every pending entry for manual
    reconciliation. Not automatically re-consumed by any later run today;
    this is the same posture ``_persist_cross_account_unresolved_evidence``
    already takes for its own sibling sidecar (discoverable and durable, not
    silently lost, without wiring a new automatic consumer as a side effect
    of one review comment).

    Failure to even write this fallback sidecar (e.g. the directory itself
    is unwritable) is swallowed and logged rather than raised, for the same
    reason described above: this is already the last-resort path after the
    primary write failed, so raising here would only replace one silent
    loss with a worse, uncaught one.
    """
    sidecar_path = Path(artifacts_dir) / (
        f"{kind}.{now.strftime('%Y%m%dT%H%M%S%f')}.{secrets.token_hex(4)}.json"
    )
    try:
        atomic_write_text(sidecar_path, json.dumps(entry, indent=2, sort_keys=True))
    except OSError:
        logger.error(
            "could not persist undurable %s evidence to %s: %r",
            kind, sidecar_path, entry,
        )


def _persist_foreign_directory_execution_sidecar(
    artifacts_dir: str | Path,
    now: datetime,
    execution_records: Sequence["OrderExecutionRecord"],
    broker: Optional["BrokerAdapter"],
) -> None:
    """Preserve THIS invocation's own newly-placed/filled orders when the
    shared artifacts directory turns out to belong to a different run.

    run_daily_compact's downstream orders.csv write is skipped entirely once
    a directory is known foreign (Codex review: "Stop downstream writes when
    the run identity changes") -- correctly, since writing into it would
    corrupt the other run's own log. But that also means run_result.
    execution_records -- real orders THIS invocation's own run_once() call
    placed before the foreign claim was discovered -- would otherwise simply
    vanish from every artifact-derived accounting (deployed_usd's seven-day
    exposure sum included), just because the directory they would normally
    land in is no longer safe to write (Codex review: "Preserve newly placed
    orders before returning on foreign ownership"). Uses the same lock-free
    sidecar mechanism the rest of this module's undurable-evidence paths do
    -- no failed/no-op records, only genuinely submitted/filled ones.
    """
    _placed_records = [r for r in execution_records if r.status in ("submitted", "filled")]
    if not _placed_records:
        return
    _account_fingerprint = (
        _account_number_for_unresolved_evidence(broker, Path(artifacts_dir).parent)
        if broker is not None
        else None
    )
    _persist_undurable_evidence_sidecar(
        artifacts_dir,
        "unwritten_execution_after_foreign_directory_claim",
        now,
        {
            "broker_outcomes": {
                (record.order_id or f"ticker:{record.ticker}:{_index}"): {
                    field_name: _iso(getattr(record, field_name)) for field_name in _CSV_FIELDS
                }
                for _index, record in enumerate(_placed_records)
            },
            "account_fingerprint": _account_fingerprint,
        },
    )


# Broker order-identifier fields exempt from `_persist_cross_account_
# unresolved_evidence`'s per-field redaction (see that function's own
# comment): a real `order_id`/reference alias is ordinarily a 6-12 digit
# numeric string, the identical shape `_ACCOUNT_SHAPED_LITERAL` exists to
# catch -- so an unqualified per-field redaction pass rewrote the one piece
# of durable evidence this sidecar exists to preserve (Codex review, PR
# #1169: "Preserve numeric order IDs in cross-account sidecars").
_ORDER_IDENTIFIER_FIELDS_EXEMPT_FROM_REDACTION = frozenset(
    {"order_id", "id", "ref_id", "client_order_id", "client_order_uuid", "client_id"}
)


def _persist_cross_account_unresolved_evidence(
    artifacts_dir: str | Path,
    now: datetime,
    current_account_fingerprint: str,
    existing_account_fingerprint: str,
    placed: Dict[str, Dict[str, Any]],
    execution_records: Optional[Sequence[OrderExecutionRecord]] = None,
) -> None:
    """Durably record THIS run's own unresolved outcomes when they cannot
    be merged into the artifact's existing (different-account) fingerprint.

    ``_write_afternoon_failure_artifacts`` used to ``raise
    UnresolvedPlacementError`` the moment it detected this mismatch,
    aborting the ENTIRE write -- including this invocation's own ``placed``
    outcomes, which describe calls THIS broker just made and which may
    include a live, possibly-accepted order. Nothing else in the run ever
    persists that evidence once this function returns, so it was gone for
    good the instant the exception propagated: outside reconciliation and
    cap accounting for every later run, on either account (Codex review, PR
    #859/#911 round 45: "Persist cross-account ambiguous placements
    separately").

    Written to a SIBLING file, never merged into the fingerprinted
    ``run_state.json`` itself: one artifact-level fingerprint still cannot
    safely bind unresolved outcomes from two accounts (the reasoning the
    original raise existed for is unchanged), so this file is scoped to the
    account that produced it. Appends to any prior mismatch already
    recorded here rather than overwriting it, keyed by ``now``'s ISO
    timestamp -- a directory can be retried more than once, by more than
    one misconfigured account, and each attempt's evidence is real.

    The read-append-write sequence is wrapped in :func:`scripts.file_lock.
    cross_process_lock`: ``atomic_write_text`` alone only makes the WRITE
    itself atomic (no reader ever sees a half-written file), not the
    read-modify-write as a whole. Two overlapping invocations that both
    fail against the SAME mismatched artifact -- plausible, since both are
    hitting the identical account-fingerprint conflict -- could otherwise
    both read the same ``entries`` list, each append only its own row, and
    each atomically replace the file; the second write still wins cleanly,
    but it silently DISCARDS the first process's own possibly-live order
    instead of merging it in, dropping that evidence from every later
    reconciliation and cap accounting pass (Codex review, PR #1164:
    "Serialize cross-account sidecar appends"). Mirrors the identical
    read-then-publish race this module's own lease-fingerprint-key
    publisher guards against a few thousand lines above.
    """
    from scripts.file_lock import cross_process_lock

    side_path = Path(artifacts_dir) / "cross_account_unresolved_placements.json"
    with cross_process_lock(side_path.with_name(f"{side_path.name}.lock")):
        _quarantine_unreadable_sidecar = False
        try:
            existing = json.loads(side_path.read_text(encoding="utf-8"))
        except FileNotFoundError:
            existing = None
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            # UNREADABLE is not the same as ABSENT: a genuinely missing
            # file (FileNotFoundError, handled above) means there is
            # nothing to lose by starting fresh, but a PRESENT, truncated/
            # non-UTF-8/malformed one may be the only durable record of an
            # EARLIER mismatched-account order this exact function already
            # exists to preserve. Reading it as empty here fed straight
            # into the same overwrite below, discarding that prior
            # evidence outright the moment this run's own new entry was
            # appended -- if the erased entries belonged to account A and
            # the new one belongs to account B, a LATER account-A run sees
            # only B's non-matching fingerprint and could place again with
            # A's earlier order excluded from deployment and cap
            # accounting entirely (Codex review, PR #1164: "Preserve
            # unreadable sidecar evidence before appending"). Quarantined
            # to a sibling file instead of silently dropped: this run's
            # OWN new evidence still must not be lost either (that is the
            # whole reason this function exists over the plain raise it
            # replaced), so the fix is to keep BOTH, not to fail closed
            # and lose the new entry the same way the old ones were about
            # to be lost.
            existing = None
            _quarantine_unreadable_sidecar = True
        entries = existing.get("entries") if isinstance(existing, dict) else None
        if not isinstance(entries, list):
            if existing is not None:
                # `existing` parsed as valid JSON but is not the expected
                # `{"entries": [...]}` shape -- a top-level list, a dict
                # whose "entries" is itself a dict/string/missing, etc.
                # This is STRUCTURALLY malformed, not genuinely absent (a
                # true FileNotFoundError already left `existing` as `None`
                # above and never reaches this branch), and is exactly as
                # much a loss of the only durable record of an earlier
                # mismatched-account order as the decode-failure case just
                # above -- resetting `entries` to `[]` here without also
                # quarantining fed straight into the same silent-overwrite
                # this function exists to prevent (Codex review, PR #1169:
                # "Quarantine structurally malformed sidecars before
                # appending").
                _quarantine_unreadable_sidecar = True
            entries = []
        if _quarantine_unreadable_sidecar and side_path.exists():
            _quarantine_path = side_path.with_name(
                f"{side_path.name}.unreadable.{now.strftime('%Y%m%dT%H%M%S%f')}"
            )
            try:
                side_path.replace(_quarantine_path)
                logger.warning(
                    "cross-account sidecar %s was unreadable; quarantined to %s before "
                    "recording this run's own evidence",
                    side_path,
                    _quarantine_path,
                )
            except OSError as exc:
                # Could not even quarantine it (e.g. a permissions issue).
                # Swallowing this and falling through used to let the
                # `atomic_write_text` call below overwrite `side_path`
                # anyway -- if the rename failure was transient or
                # destination-specific (not the SAME reason a later write
                # to the same path would also fail), that overwrite still
                # succeeds, destroying the only durable record of an
                # earlier possibly-live order this whole function exists
                # to preserve, with no trace it was ever there (Codex
                # review, PR #1168: "Abort when an unreadable sidecar
                # cannot be quarantined"). Propagated instead: this run's
                # OWN new evidence is not durably recorded either way when
                # quarantining fails, so raising loses nothing further
                # this invocation could have saved, and preserves the
                # unreadable original at its current path for manual
                # recovery instead of silently destroying it.
                raise OSError(
                    f"cross-account sidecar {side_path} is unreadable and could not be "
                    f"quarantined to {_quarantine_path} ({exc}); refusing to overwrite it "
                    "and lose the only durable record of its prior evidence"
                ) from exc
        # `execution_records` is a SEPARATE evidence source from `placed`
        # (the in-flight candidate outcomes global) -- `run_once` can fail
        # with a nonempty `execution_records` (a recovery row appended
        # before the raise) while `placed` stays empty, an execution-only
        # path this mismatch gate now also detects (see its own caller's
        # comment). Persisting only `placed` in that shape wrote an EMPTY
        # `broker_outcomes` entry here, and the caller's own guard already
        # skips merging `execution_records` into the OTHER account's
        # `orders.csv`, so the current account's own known fill was absent
        # from every artifact despite this function's whole purpose being
        # to keep it durable somewhere (Codex review, PR #1164/#1169:
        # "Persist execution-only cross-account evidence"). Serialized the
        # same way `write_execution_csv` does (`_iso` over each `_CSV_
        # FIELDS` attribute) since `OrderExecutionRecord` carries `datetime`
        # fields `json.dumps` cannot serialize directly.
        entries.append(
            {
                "recorded_at": now.isoformat(),
                "account_number": current_account_fingerprint,
                "conflicting_artifact_account_number": existing_account_fingerprint,
                # Redacted via `_redacted_diagnostic_text`, not `placed`
                # persisted verbatim: a candidate outcome's own diagnostic
                # fields (`skip_reason` in particular) routinely interpolate
                # a raw connector exception (`f"... failed: {exc}"`)
                # directly, which can carry the SAME account-number/
                # credential shapes `_redacted_exception_detail` already
                # redacts everywhere else this repo persists exception
                # text -- but this sidecar previously persisted the whole
                # outcome mapping unredacted, since only the top-level
                # failure message (not each outcome's own fields) ever
                # passed through that redactor (Codex review, PR #1169:
                # "Redact broker outcomes before writing account
                # sidecars").
                #
                # Fields in `_ORDER_IDENTIFIER_FIELDS_EXEMPT_FROM_REDACTION`
                # are left untouched, even though they are ordinary strings:
                # `_redacted_diagnostic_text`'s own `_ACCOUNT_SHAPED_LITERAL`
                # pattern matches ANY standalone 6-12 digit run, and a real
                # broker `order_id` (or an opaque reference alias containing
                # one) is exactly that shape. Redacting it here rewrote the
                # only durable, unresolved recovery-target identity this
                # sidecar exists to preserve to "[REDACTED]", blocking the
                # manual reconciliation this whole quarantine path is for
                # (Codex review, PR #1169: "Preserve numeric order IDs in
                # cross-account sidecars"). `whole_share_order_ids` needs no
                # exemption of its own -- it is a list, not a string, so the
                # `isinstance(field_value, str)` guard already skips it.
                "broker_outcomes": {
                    ticker: {
                        field_name: (
                            field_value
                            if field_name in _ORDER_IDENTIFIER_FIELDS_EXEMPT_FROM_REDACTION
                            else _redacted_diagnostic_text(field_value)
                        )
                        if isinstance(field_value, str)
                        else field_value
                        for field_name, field_value in outcome.items()
                    }
                    for ticker, outcome in placed.items()
                },
                "execution_records": [
                    {field_name: _iso(getattr(record, field_name)) for field_name in _CSV_FIELDS}
                    for record in (execution_records or [])
                ],
            }
        )
        atomic_write_text(
            side_path,
            json.dumps({"entries": entries}, indent=2, sort_keys=True),
        )
    logger.warning(
        "unresolved placement evidence for account %s could not be merged into "
        "%s (owned by a different account); recorded separately at %s",
        current_account_fingerprint,
        Path(artifacts_dir) / "run_state.json",
        side_path,
    )


def _write_afternoon_failure_artifacts(
    artifacts_dir: str | Path,
    now: datetime,
    exc: BaseException,
    classification_state_root: Optional[str | Path] = None,
    classification_overrides: Optional[Dict[str, Any]] = None,
    correlation_id: Optional[str] = None,
    execution_records: Optional[Sequence[OrderExecutionRecord]] = None,
    scheduled: bool = True,
    broker: Optional["BrokerAdapter"] = None,
    broker_name: Optional[str] = None,
) -> None:
    """Write the complete root-level set for an afternoon run that raised.

    Preserves any order already placed, never overwrites a run_state the run had
    already written, and completes a partial directory. The artifact proves the
    slot fired; it is never scheduled evidence.

    ``classification_overrides``/``correlation_id`` let a non-afternoon roster
    slot (``run_dca.run_slot``'s 1030ET/1230ET) stamp its OWN stream/cron_id/
    scheduled_for_et/run_id and deterministic correlation id onto this failure
    artifact, the same way ``_write_blocked_run_stub``/``raw_persistence_failure_run_state``
    already do. Without this, an ordinary runtime failure (account lookup,
    signal evaluation, or a per-candidate broker check raising before
    ``_finalize_and_write_artifacts`` ran) still stamped the default afternoon
    identity for a 10:30/12:30 run, even though the raw-persistence and
    calendar-gate failure paths were already fixed to carry the slot's own
    identity (Codex review: "Forward slot identity into exception artifacts").

    ``broker_name`` is the run's OWN configured broker
    (``ctx.config.broker.value``), not always Robinhood: this writer used to
    stamp every synthesized state with ``config_broker_name()``, a stub that
    unconditionally returns ``"robinhood"`` because this function is built
    without a ``StrategyConfig`` in hand. That was silently correct while
    this path only ever fired for Robinhood-configured runs; once it started
    firing for a manual Alpaca run too, the artifact misidentified its own
    execution broker for dashboards and recovery tooling (Codex review, PR
    #859 round 32: "Preserve the configured broker in manual failure
    artifacts"). Falls back to ``config_broker_name()`` when omitted, so a
    caller with no ``StrategyConfig`` in scope keeps the prior default.
    Distinct from ``broker`` above -- that is the live ``BrokerAdapter``
    instance the account-fingerprint lookup needs; this is just its
    configured NAME for the artifact's own ``"broker"`` field.
    """
    try:  # pragma: no cover - import shim for flat sys.path
        from scripts.run_classification import (
            build_manual_classification,
            build_scheduled_classification,
            update_latest_scheduled_run_pointer,
        )
        from scripts.scheduled_artifacts import (
            build_run_summary,
            submitted_order_rows,
            write_signals_csv,
            write_submitted_orders_csv,
        )
    except ImportError:  # pragma: no cover
        from run_classification import (  # type: ignore
            build_manual_classification,
            build_scheduled_classification,
            update_latest_scheduled_run_pointer,
        )
        from scheduled_artifacts import (  # type: ignore
            build_run_summary,
            submitted_order_rows,
            write_signals_csv,
            write_submitted_orders_csv,
        )

    out = Path(artifacts_dir)
    out.mkdir(parents=True, exist_ok=True)
    state_path = out / "run_state.json"
    trading_day = now.astimezone(EASTERN).date().isoformat()

    placed = {
        ticker: outcome
        for ticker, outcome in (
            _IN_FLIGHT_CANDIDATE_OUTCOMES.get("outcomes") or {}
        ).items()
        if isinstance(outcome, dict)
    }
    # Filtered to outcomes/records that reflect an ACTUAL broker call, shared
    # by every account-mismatch gate in this function -- both the early
    # same-identity-different-account return below and the later merge-
    # branch's own `_cross_account_mismatch` check. A batch containing only
    # skipped/internally-blocked candidate rows (no broker call ever made),
    # or only dry-run executions, is not evidence worth sidecaring at all:
    # persisting it created a `cross_account_unresolved_placements.json`
    # entry for evidence that was never actually ambiguous, and the NEXT run
    # for this account treats any matching sidecar entry as unresolved and
    # refuses all placements until manual cleanup (Codex review, PR #1168:
    # "Do not sidecar outcomes that made no broker call" / PR #1169:
    # "Exclude dry-run execution rows from mismatch evidence"). Computed
    # ONCE here, before either gate can run, so both apply the identical
    # filter rather than one gate refining it and the other still reading
    # the raw, unfiltered `placed`/`execution_records`.
    _execution_records_with_broker_call = [
        record
        for record in (execution_records or [])
        if not (isinstance(record.order_id, str) and record.order_id.startswith("DRY-RUN-"))
    ]
    _placed_with_broker_call = {
        ticker: outcome
        for ticker, outcome in placed.items()
        if outcome.get("status") != "dry_run"
        and (
            outcome.get("order_id")
            or outcome.get("broker_call_attempted")
            or outcome.get("broker_placement_attempted")
            or outcome.get("placement_outcome_unproven")
        )
    }

    # A run_state.json compare-and-swap deep in reconciliation already
    # determined that a DIFFERENT, overlapping retry sharing this exact
    # trading_day/stream/slot identity published its own evidence since this
    # invocation's last known view of the file, and correctly refused to
    # overwrite it (Codex review: "Preserve the concurrent writer after
    # rejecting stale state"). Everything below this point -- the
    # existing_is_usable merge-or-synthesize logic -- treats a same-identity
    # run_state.json as THIS invocation's own prior attempt to fold outcomes
    # into; here it is not: it is another process's genuinely successful
    # (or still-in-progress) run of the SAME identity, which already owns
    # publishing the scheduled contract for this slot. Merging this
    # invocation's failure onto it would corrupt that other run's state
    # exactly the way the CAS was raised to prevent. This invocation has
    # nothing of its own to publish under this identity, so run_state.json
    # and its companions are left completely untouched; any orders this
    # invocation itself placed before the halt still need a durable record,
    # so they go to the same lock-free sidecar mechanism the primary-lock
    # exhaustion path below uses, rather than being silently dropped.
    if getattr(exc, "concurrent_writer_detected", False):
        logger.error(
            "not writing failure artifacts to %s: a concurrent retry already "
            "published its own evidence for this run's identity; %d "
            "in-flight outcome(s) preserved via sidecar instead",
            state_path,
            len(placed),
        )
        if placed:
            _account_fingerprint = (
                _account_number_for_unresolved_evidence(broker, Path(artifacts_dir).parent)
                if broker is not None
                else None
            )
            _persist_undurable_evidence_sidecar(
                out,
                "foreign_run_state_after_concurrency_rejection",
                now,
                {
                    "broker_outcomes": placed,
                    "account_fingerprint": _account_fingerprint,
                },
            )
        return

    submitted = sum(1 for oc in placed.values() if oc.get("status") == "submitted")
    # A deliberate unresolved-placement halt is NOT a startup failure, and the
    # difference matters to every consumer downstream: `startup_failed` /
    # `error_class=startup_failure` says the run never got going, so monitoring
    # and recovery read it as an initialization problem and look at the wrong
    # thing entirely. This run evaluated its signals and reached the broker
    # placement boundary; it stopped there BECAUSE a placement's outcome could
    # not be proven, which is a placement failure. Zero submitted orders is
    # what makes it reach this branch at all, and the ordinary zero-order path
    # (`_apply_no_order_classification` -> `classify_no_order_run`) would have
    # classified exactly this as `failed_after_connector_native_recovery_attempt`
    # -- or `failed_placement` for a manual run, which never runs the
    # connector-native recovery policy. The halt re-raises before that path
    # runs, so the same verdict is reproduced here (Codex review, PR #859:
    # "Classify unresolved halts as placement failures").
    unresolved_placement_halt = isinstance(exc, UnresolvedPlacementError)
    _placement_failure_class = (
        RUN_CLASSIFICATION_PLACEMENT_FAILED
        if scheduled
        else RUN_CLASSIFICATION_MANUAL_PLACEMENT_FAILED
    )
    # ...and a run classified as a PLACEMENT failure must not also assert that
    # it evaluated nothing. The generic synthesized state below writes
    # `counts.evaluated=0`, empty `signal_rows` and zero caps, which is honest
    # for a startup failure and false for this one: an unresolved placement
    # happens only after signal evaluation and candidate construction have
    # COMPLETED. Reporting and recovery consumers would see a placement-
    # classified run carrying none of the signals or real cap context that led
    # to the attempted order (Codex review, PR #859: "Preserve completed
    # evaluation data in halt artifacts"). `_run_once_impl` publishes that
    # context the moment it is settled; read it here.
    _evaluated: Dict[str, Any] = {}
    if unresolved_placement_halt:
        _evaluated = dict(_IN_FLIGHT_RUN_EVALUATION)
    _evaluated_decisions = list(_evaluated.get("decisions") or [])
    _evaluated_budget: Optional[Dict[str, Any]] = None
    if _evaluated.get("config") is not None and _evaluated.get("state") is not None:
        _eval_state = _evaluated["state"]
        _evaluated_budget = _build_budget_block(
            _evaluated["config"],
            _eval_state,
            _eval_state.current_tier(),
            float(_evaluated.get("planned_spend") or 0.0),
            int(_evaluated.get("high_multiplier_signals") or 0),
            _evaluated["trading_day"],
        )

    # A truncated, non-UTF-8, or non-object existing state is not a run to
    # preserve, only a malformed file: it is replaced with the full synthesized
    # failure state exactly as the no-file branch does, rather than being wrapped
    # in fresh companions around a broken root (Codex review).
    existing_is_usable = False
    # Initialized here, not only inside the merge branch below: the
    # run_summary.json regeneration gate at the end of this function reads it
    # unconditionally, so a run that never reaches the `if added:` branch (no
    # outcome to merge at all) raised UnboundLocalError while handling another
    # failure, losing the artifact repair entirely.
    state_was_mutated = False
    # Initialized here for the identical reason as `state_was_mutated`
    # above: the orders.csv merge guard near the end of this function reads
    # it unconditionally, but only the "merge into an existing preserved
    # artifact" branch below ever assigns it -- a fresh-synthesis run (no
    # preserved artifact to conflict with at all) never touches it, and
    # would otherwise raise `UnboundLocalError` reaching that guard.
    _cross_account_mismatch = False
    # Set when an unresolved-halt merge replaces a preserved state's signal
    # rows with this invocation's own, so the companion CSV is rewritten to
    # match rather than left describing the earlier attempt.
    _rewrite_merged_signals_csv = False
    # Initialized here too, for the identical reason `state_was_mutated`
    # is: the shared orders.csv/usage-backfill block much further down in
    # this function reads it unconditionally to decide whether writing
    # THIS invocation's own execution_records is safe, and a run that
    # never reaches the merge branch below (a fresh synthesis, with no
    # preserved artifact to compare accounts against) must read this as
    # "no mismatch", not raise `UnboundLocalError`.
    _cross_account_mismatch = False
    # Same UnboundLocalError-safety reasoning as `_cross_account_mismatch`
    # above, for the pure fingerprint-disagreement signal the downstream
    # orders.csv/pointer-validation guards key off of directly (Codex
    # review, PR #1168: "Separate account mismatch from sidecar
    # eligibility").
    _account_fingerprint_mismatch = False
    _loaded: Optional[Dict[str, Any]] = None
    # Captured at whichever of the two write sites below actually runs, the
    # exact bytes THIS invocation itself just wrote to state_path -- reused
    # later as the pre-validation snapshot for the separate contract-
    # failure annotation pass, instead of a re-read. A re-read there is
    # itself racy: an overlapping retry replacing run_state.json between
    # this write and that later read would have its bytes silently
    # captured as this invocation's own "snapshot" instead of what this
    # invocation actually published (Codex review: "Bind the failure
    # snapshot to this invocation's state", extending the identical
    # "Bind snapshots to this invocation's writes" fix already applied to
    # _write_and_validate_scheduled_contract).
    _written_run_state_bytes: Optional[bytes] = None
    # The read-modify-write of run_state.json below (deciding whether the
    # prior file is usable, merging this invocation's outcomes into it or
    # synthesizing a fresh failure state, and writing the result back) is a
    # single critical section shared with every other run_state.json writer
    # -- the primary publisher, the intraday archive annotation, the
    # recovery reinjection, and the CSV-usage backfill all take the same
    # sidecar lock. An overlapping retry sharing this artifact directory
    # could otherwise read this file between another writer's read and
    # write, then overwrite that writer's recovered submission evidence or
    # usage update with this call's stale copy (Codex review: "Put every
    # run-state writer behind the sidecar lock").
    try:
        with cross_process_lock(state_path.with_name(f"{state_path.name}.lock")):
            if state_path.exists():
                try:
                    parsed = json.loads(state_path.read_bytes())
                    if isinstance(parsed, dict):
                        _loaded = parsed
                except (OSError, json.JSONDecodeError, UnicodeDecodeError):
                    _loaded = None
                existing_is_usable = _loaded is not None
                state_was_mutated = False
                if not existing_is_usable:
                    logger.warning(
                        "replacing an unreadable run_state.json at %s with the failure state",
                        state_path,
                    )

            # A readable existing run_state.json can still belong to a DIFFERENT
            # trading day or stream than this invocation -- the directory was simply
            # reused. The success path (run_daily_compact) already refuses to merge
            # orders.csv in that case (_orders_csv_same_run); this failure path
            # merged into it unconditionally as long as the file merely parsed,
            # attributing this run's newly placed/recovered order to a foreign run's
            # execution log and inflating ITS metrics (Codex review: "Replace
            # execution rows when the failure directory is foreign"). Folded
            # straight into existing_is_usable -- not tracked as a separate flag --
            # so a foreign state gets the SAME full-synthesis treatment as an
            # unreadable one everywhere below (run_state.json itself, signals.csv,
            # submitted_orders.csv, orders.csv, and the summary regeneration gate),
            # rather than only replacing orders.csv while still preserving the
            # foreign run_id/trading_day/stream as this invocation's own state
            # (Codex review: "Replace the foreign run state along with its
            # execution log"). Computed from the freshly-loaded state, before any
            # merge below can touch it, against this invocation's OWN identity --
            # trading_day is always the afternoon stream's default unless a slot
            # override says otherwise.
            if existing_is_usable:
                assert _loaded is not None
                _prior_classification = _loaded.get("run_classification")
                _prior_stream = (
                    _prior_classification.get("stream")
                    if isinstance(_prior_classification, dict)
                    else None
                )
                # A shared stream alone does not identify a slot: the intraday
                # stream covers three distinct fire times (11:30/13:30/14:30 ET)
                # under one stream name, distinguished only by scheduled_for_et/
                # run_id -- see scripts/run_classification.py's
                # INTRADAY_SLOT_IDENTITIES (Codex review: "Include the scheduled
                # slot when identifying retries", raised against run_daily_compact's
                # own identical check; applied here too for the same reason).
                _prior_scheduled_for_et = (
                    _prior_classification.get("scheduled_for_et")
                    if isinstance(_prior_classification, dict)
                    else None
                )
                # RUN ORIGIN FIRST, because it decides what the other two even mean.
                # build_manual_classification stamps run_origin="manual" and sets
                # NEITHER `stream` NOR `scheduled_for_et`, so a manual artifact's slot
                # identity is (None, None). Comparing that against the SCHEDULED
                # defaults below marked this writer's own prior manual artifact
                # foreign, and a second manual run into the same directory replaced it
                # -- deleting the first unresolved placement, which may still be live
                # at the broker, instead of letting it reach the unproven-retry merge
                # (Codex review, PR #859: "Preserve prior manual unresolved attempts on
                # retry"). Only reachable at all because this writer now runs for
                # manual failures too. Mirrors run_daily_compact's own
                # `_orders_csv_same_run` identity, which already tracks run_origin
                # separately for exactly this reason.
                _prior_run_origin = (
                    _prior_classification.get("run_origin")
                    if isinstance(_prior_classification, dict)
                    else None
                )
                _current_run_origin = "scheduled" if scheduled else "manual"
                _current_stream = (
                    (classification_overrides or {}).get("stream", "afternoon")
                    if scheduled
                    else None
                )
                _current_scheduled_for_et = (
                    (classification_overrides or {}).get("scheduled_for_et", "15:30")
                    if scheduled
                    else None
                )
                # A malformed broker_outcomes field (anything but a mapping or
                # absent, e.g. a corrupted list) is not a shape the merge branch
                # below can preserve: it unconditionally does
                # `dict(merged.get("broker_outcomes") or {})`, which raises for a
                # non-empty non-mapping value -- AFTER this invocation may have
                # already placed live orders and cleared their leases, losing the
                # recovery/execution record entirely instead of falling through to
                # full synthesis (Codex review: "Reject malformed outcomes before
                # preserving the prior state"). _write_afternoon_failure_artifacts
                # itself performs the same unchecked conversion further below.
                _prior_broker_outcomes_field = _loaded.get("broker_outcomes")
                _prior_broker_outcomes_malformed = _prior_broker_outcomes_field is not None and not isinstance(
                    _prior_broker_outcomes_field, dict
                )
                if (
                    _loaded.get("trading_day") != trading_day
                    # An absent run_origin predates the field and belongs to the
                    # scheduled path, which is the only one that used to reach here.
                    or (_prior_run_origin or "scheduled") != _current_run_origin
                    or _prior_stream != _current_stream
                    or _prior_scheduled_for_et != _current_scheduled_for_et
                    or _prior_broker_outcomes_malformed
                ):
                    existing_is_usable = False
                    logger.warning(
                        "replacing a foreign or malformed run_state.json at %s (trading_day=%s "
                        "stream=%s) with this invocation's own failure state",
                        state_path,
                        _loaded.get("trading_day"),
                        _prior_stream,
                    )
                elif isinstance(_loaded.get("account_number"), str) and _loaded.get("account_number"):
                    # Reached only when trading_day/stream/slot/run_origin all
                    # match: this is genuinely the SAME identity slot, still
                    # actively bound to a DIFFERENT account's fingerprint. That
                    # is NOT the same situation the block above replaces --
                    # a foreign trading_day/stream means the directory has
                    # moved on to a new identity and is safe to reclaim by
                    # overwriting; a same-identity account mismatch means a
                    # DIFFERENT account is (or very recently was) actively
                    # using this exact directory, which the existing
                    # `_cross_account_mismatch` check further below already
                    # refuses to merge new outcomes into -- but that check
                    # only fires when `placed` is non-empty, and even then it
                    # never stopped `stamp_failure_classification()` from
                    # unconditionally overwriting this OTHER account's
                    # `status`/classification with THIS run's own failure
                    # (Codex review: "Leave another account's failure state
                    # untouched"). A startup failure with nothing placed at
                    # all previously fell through that gap entirely. Checked
                    # here, before any merge or synthesis path can touch
                    # `state_path`, and fails closed the same way every other
                    # account comparison in this module does: "cannot verify"
                    # (broker missing, or the HMAC key unavailable -- the
                    # sentinel, not a bare fingerprint) is never treated as
                    # "assume it matches".
                    _existing_state_account_fingerprint = _loaded.get("account_number")
                    _this_runs_account_fingerprint_for_ownership = (
                        _account_number_for_unresolved_evidence(broker, Path(artifacts_dir).parent)
                        if broker is not None
                        else None
                    )
                    if (
                        _this_runs_account_fingerprint_for_ownership is None
                        or _this_runs_account_fingerprint_for_ownership
                        == _ACCOUNT_FINGERPRINT_UNAVAILABLE_SENTINEL
                        or _this_runs_account_fingerprint_for_ownership
                        != _existing_state_account_fingerprint
                    ):
                        logger.error(
                            "not writing failure artifacts to %s: it is bound to a "
                            "different (or unverifiable) account than this run's own; "
                            "%d in-flight outcome(s) preserved via sidecar instead",
                            state_path,
                            len(placed),
                        )
                        # `execution_records`, not just `placed`, alone: the same
                        # execution-only shape the `_cross_account_mismatch` sidecar
                        # convention below now also detects (Codex review, PR
                        # #1164/#1169: "Include execution-only failures in the
                        # account mismatch gate") can reach this earlier same-
                        # identity-different-account return path too -- `placed`
                        # empty but a recovery row already appended to
                        # `execution_records` before the raise. Gating this branch
                        # on `placed` alone silently dropped that evidence: the log
                        # line above claims it was "preserved via sidecar" while
                        # neither sidecar call below ever ran.
                        #
                        # Filtered through `_placed_with_broker_call`/
                        # `_execution_records_with_broker_call`, not the raw
                        # `placed`/`execution_records`: an outcome that never
                        # reached the broker (no order_id/broker_call_attempted/
                        # broker_placement_attempted/placement_outcome_unproven,
                        # or a dry-run execution row) is not evidence worth
                        # sidecaring, the same reasoning the later merge branch's
                        # own `_cross_account_mismatch` gate already applies
                        # (Codex review, PR #1168: "Separate account mismatch
                        # from sidecar eligibility"). The MERGE SKIP above
                        # (the early `return` at the bottom of this branch) is
                        # NOT similarly gated -- the fingerprints genuinely
                        # disagree regardless of whether this run's own outcome
                        # happens to be sidecar-worthy, and merging it into a
                        # different account's preserved artifact would still be
                        # wrong even with nothing to sidecar (Codex review, PR
                        # #1168: "... still skips merge with no sidecar
                        # evidence").
                        if _placed_with_broker_call or _execution_records_with_broker_call:
                            if (
                                _this_runs_account_fingerprint_for_ownership is not None
                                and _this_runs_account_fingerprint_for_ownership
                                != _ACCOUNT_FINGERPRINT_UNAVAILABLE_SENTINEL
                            ):
                                # A real (non-sentinel) fingerprint for THIS
                                # run: bind the evidence to it, matching the
                                # existing `_cross_account_mismatch` sidecar
                                # convention below. The sentinel is
                                # explicitly excluded here even though it is
                                # `is not None` too -- binding a sidecar
                                # entry to the sentinel string would make
                                # the reconciliation scan treat it as
                                # unresolved evidence for EVERY current
                                # account whose own fingerprint happens to
                                # be unavailable, persistently blocking
                                # unrelated accounts' placements until
                                # manual cleanup (Codex review: "Keep
                                # unavailable fingerprints out of account
                                # sidecars").
                                _persist_cross_account_unresolved_evidence(
                                    artifacts_dir,
                                    now,
                                    _this_runs_account_fingerprint_for_ownership,
                                    _existing_state_account_fingerprint,
                                    _placed_with_broker_call,
                                    _execution_records_with_broker_call,
                                )
                            else:
                                # This run's own fingerprint could not even
                                # be computed (no broker, or the HMAC key is
                                # unavailable) -- still not lost, via the
                                # generic undurable-evidence sidecar rather
                                # than the cross-account one, which requires
                                # a real fingerprint string on both sides.
                                _persist_undurable_evidence_sidecar(
                                    out,
                                    "unwritten_failure_artifact_placement",
                                    now,
                                    {
                                        "broker_outcomes": _placed_with_broker_call,
                                        "account_fingerprint": None,
                                    },
                                )
                        return

            if not existing_is_usable:
                classification = dict(
                    build_scheduled_classification(trading_day, **(classification_overrides or {}))
                    if scheduled
                    else build_manual_classification(
                        now.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
                    )
                )
                classification["valid_scheduled_evidence"] = False
                _failure_candidate_rows = [
                    _failure_candidate_row(ticker, outcome) for ticker, outcome in placed.items()
                ]
                _failure_signal_rows = (
                    _build_signal_rows(_evaluated_decisions, placed) if _evaluated_decisions else []
                )
                # The same backfill the normal artifact path applies right after it
                # builds its rows -- without it a failure report reads each provider's
                # raw suggested amount as money that went missing.
                _backfill_reconciled_signal_amounts(_failure_signal_rows, _failure_candidate_rows)
                run_state: Dict[str, Any] = {
                    # Unlike the deliberately runless calendar-gate stub, a failure state
                    # IS a run: it carries the scheduled run id the schema requires and
                    # build_run_summary reads (Codex review). Derived from the (possibly
                    # slot-overridden) classification rather than always the afternoon
                    # scheduled_run_id, so a 10:30/12:30 run's failure artifact carries
                    # its own run_id instead of the afternoon one (Codex review: "Forward
                    # slot identity into exception artifacts").
                    "run_id": classification["run_id"],
                    "trading_day": trading_day,
                    "generated_at": now.astimezone(EASTERN).isoformat(),
                    "broker": broker_name or config_broker_name(),
                    # The SAME non-reversible keyed fingerprint build_run_artifacts
                    # stamps on a successful write, computed the same way (same
                    # key_dir convention: beside, not inside, the artifacts tree).
                    # This writer runs precisely when a placement halted ambiguous
                    # -- i.e. exactly the artifact _reconcile_prior_unproven_
                    # fractional_placements later reads back to verify account
                    # provenance -- so leaving it null here (the previous state)
                    # defeated that check for every FIRST-halt artifact: the one
                    # this whole feature exists to protect (Codex review, PR #911
                    # round 4: "Stamp fingerprints on ambiguous failure artifacts").
                    "account_number": _account_number_for_unresolved_evidence(
                        broker, Path(artifacts_dir).parent
                    ),
                    "status": "failed",
                    "run_classification": classification,
                    "run_classification_outcome": (
                        RUN_CLASSIFICATION_FAILED_AFTER_SUBMISSION
                        if submitted
                        else _placement_failure_class
                        if unresolved_placement_halt
                        else RUN_CLASSIFICATION_STARTUP_FAILED
                    ),
                    "order_submit_status": (
                        ORDER_SUBMIT_STATUS_SUBMITTED
                        if submitted
                        else ORDER_SUBMIT_STATUS_ERROR
                    ),
                    "error_class": (
                        ERROR_CLASS_POST_SUBMISSION_FAILURE
                        if submitted
                        else _placement_failure_class
                        if unresolved_placement_halt
                        else ERROR_CLASS_STARTUP_FAILURE
                    ),
                    "error_detail": _redacted_exception_detail(exc),
                    "is_trading_failure": True,
                    "scheduled_evidence_denied": True,
                    "orders_submitted_count": submitted,
                    # DERIVED from the published outcomes, not hard-coded zero. An
                    # unresolved placement's own candidate necessarily PASSED the
                    # spread gate before it could reach place_market_buy, so a run
                    # summary reporting "nothing reached the gate" contradicts its own
                    # candidate rows and hides how far evaluation got (Codex review,
                    # PR #859: "Preserve spread-gate counts in unresolved artifacts").
                    # Same two aggregates _apply_no_order_classification computes from
                    # the same per-row verdicts.
                    "candidates_reaching_spread_gate": sum(
                        1
                        for oc in placed.values()
                        if oc.get("spread_status")
                        and oc.get("spread_status") != SPREAD_STATUS_NOT_EVALUATED
                    ),
                    "candidates_blocked_missing_spread": sum(
                        1 for oc in placed.values() if oc.get("blocked_by") == BLOCKED_BY_SPREAD_GATE
                    ),
                    "budget": _evaluated_budget
                    or {
                        "budget_tier": "normal",
                        "daily_cap_usd": 0,
                        "weekly_cap_usd": 0,
                    },
                    "counts": {
                        "evaluated": len(_evaluated_decisions),
                        "buy_candidates": len(placed),
                        "submitted": submitted,
                    },
                    "signal_rows": _failure_signal_rows,
                    "buy_candidates": _failure_candidate_rows,
                    "broker_outcomes": placed,
                }
                if unresolved_placement_halt:
                    # The count an operator reads to know how many orders to chase.
                    # `classify_no_order_run` does not carry it either -- the
                    # zero-order path stamps it separately, from the same row
                    # statuses -- so the halt path stamps it here for the same reason.
                    run_state["orders_failed_count"] = _failed_placement_count(placed)
                    # AND THE FLAG THAT SUMMONS THE OPERATOR. The raise unwinds past
                    # the batch's `errors_count_inc` accounting, and this writer
                    # synthesized no usage_proxy at all, so the one artifact left by a
                    # run that may have a LIVE order at the broker carried no
                    # `manual_recovery_required` anywhere -- the exact signal the
                    # normal path derives from the placement error count, missing from
                    # the exact case that needs it most (Codex review, PR #859: "Mark
                    # unresolved halts as requiring manual recovery"). Built through
                    # build_usage_proxy rather than hand-rolled so every
                    # USAGE_PROXY_FIELDS key is present and a consumer reading this
                    # block does not have to special-case the failure artifact.
                    run_state["usage_proxy"] = build_usage_proxy(
                        decisions=_evaluated_decisions,
                        signal_rows=_failure_signal_rows,
                        buy_candidates=_failure_candidate_rows,
                        candidate_outcomes=placed,
                        # Left unset (build_usage_proxy defaults to len(buy_candidates))
                        # reported reviews that never happened: _process_buy_candidate
                        # only ever calls review_market_buy when `not ctx.scheduled`,
                        # so a SCHEDULED halt -- the common case, and the only one an
                        # unresolved fractional placement can occur on -- attempted
                        # zero reviews, not one per reconstructed candidate row (most
                        # of which are the unattempted tail after the halt, never
                        # reviewed at all). A manual run's actual count is reconstructed
                        # from the published outcomes: order_reviews_attempted_inc is
                        # bumped immediately before every review_market_buy call, and
                        # every candidate that reached one is published either with
                        # `reviewed_order` set (review passed) or a "review blocked:"
                        # skip_reason (review ran and refused) -- the two outcomes a
                        # completed review call can leave behind (Codex review,
                        # PR #859: "Report only broker reviews that actually ran").
                        order_reviews_attempted=(
                            0
                            if scheduled
                            else sum(
                                1
                                for oc in placed.values()
                                if isinstance(oc, dict)
                                and (
                                    oc.get("reviewed_order") is not None
                                    or (
                                        isinstance(oc.get("skip_reason"), str)
                                        and oc["skip_reason"].startswith("review blocked:")
                                    )
                                )
                            )
                        ),
                        # At least one: the unresolved placement itself. An outcome
                        # count of zero would silently clear the flag on the one path
                        # that must always raise it. PLUS whatever this same run
                        # already accumulated BEFORE the halt -- signal-evaluation
                        # provider errors, pre-roll whole-share reconciliation
                        # errors -- published into _IN_FLIGHT_RUN_EVALUATION the
                        # moment evaluation completed. Starting over from just the
                        # placement error discarded that count entirely: one
                        # provider error followed by one unresolved placement
                        # reported as a single error instead of two, understating
                        # usage/cost and incident telemetry (Codex review, PR #859
                        # round 28: "Preserve evaluation errors in halt telemetry").
                        errors_count=(
                            _coerce_nonnegative_int(_evaluated.get("errors_count"))
                            + max(1, run_state["orders_failed_count"])
                        ),
                    )
                if placed or unresolved_placement_halt:
                    # `placed` alone misses the STARTUP reconciliation halt: when
                    # `_reconcile_prior_unproven_fractional_placements` raises
                    # `UnresolvedPlacementError` because the PRIOR artifact's own
                    # `broker_outcomes` was malformed (a list/null) alongside its
                    # own `placement_evidence_incomplete=True`, that raise happens
                    # BEFORE any candidate in this run is ever processed -- `placed`
                    # is still empty, so the flag was never set on the freshly
                    # synthesized state that overwrites the malformed one. The next
                    # invocation's own reconciliation pass then reads a clean, valid,
                    # EMPTY `broker_outcomes` with no flag set at all, sees nothing
                    # to fail closed on, and may place a fresh order over a
                    # placement neither confirmed nor denied (Codex review, PR #911
                    # round 39: "Preserve malformed unresolved storage after
                    # raising"). `unresolved_placement_halt` is exactly this run's
                    # own signal that placement evidence is incomplete regardless of
                    # whether any candidate got as far as publishing an outcome.
                    run_state["placement_evidence_incomplete"] = True
                if correlation_id is not None:
                    run_state["correlation_id"] = correlation_id
                _synthesized_run_state_text = _serialize_run_state(run_state)
                atomic_write_text(state_path, _synthesized_run_state_text)
                _written_run_state_bytes = _synthesized_run_state_text.encode("utf-8")
            else:
                logger.warning(
                    "afternoon run failed after run_state.json was written; preserving it "
                    "and completing any missing companion artifacts"
                )
                assert _loaded is not None
                run_state = _loaded
                # The preserved file can belong to an EARLIER invocation at this slot, so
                # fold in whatever THIS one placed. Discarding it would hide an accepted
                # order from the same-day guards and let a later run buy it again (Codex
                # review). The ROWS are folded in only when there is something to add;
                # the failure stamp below always runs.
                merged = dict(run_state)
                # Backfilled, not stamped unconditionally: this preserved artifact
                # may predate account fingerprinting (round 4 stamped it only on the
                # fresh-synthesis branch above), and `_reconcile_prior_unproven_
                # fractional_placements` treats a missing/null persisted fingerprint
                # as "nothing to verify" and skips its account check entirely. A
                # retry that merges new unresolved evidence into such an artifact
                # left it permanently unfingerprinted -- unlike the fresh-synthesis
                # branch's own artifact, which is always stamped from its very first
                # write -- so a later invocation under a MISWIRED broker for a
                # different account could satisfy this same deterministic reference
                # and have that account's history trusted (Codex review, PR #911
                # round 8: "Stamp fingerprints when merging ambiguous failure
                # evidence"). Never overwrites an existing non-empty fingerprint:
                # this run's own broker is not necessarily the one that first wrote
                # this artifact, and a fingerprint already present is that first
                # writer's authoritative identity, not this retry's.
                existing_account_fingerprint = merged.get("account_number")
                current_account_fingerprint = (
                    _account_number_for_unresolved_evidence(broker, Path(artifacts_dir).parent)
                    if broker is not None
                    else None
                )
                # Gated on `placed` OR `execution_records`, not `placed` alone:
                # `run_once` can fail with a nonempty `execution_records` (a
                # recovery row appended before the raise) while `placed` -- the
                # in-flight candidate outcomes -- is still empty, an execution-
                # only path independent of `_IN_FLIGHT_CANDIDATE_OUTCOMES`. Gating
                # on `placed` alone let that shape slip past this mismatch check
                # entirely, so the `orders.csv` merge/backfill block further down
                # (guarded by `not _cross_account_mismatch`) went on to merge
                # account B's execution into account A's preserved log and
                # backfill A's state from it (Codex review, PR #1164/#1169:
                # "Include execution-only failures in the account mismatch gate").
                #
                # `placed` itself is filtered to outcomes that reflect an ACTUAL
                # broker call -- an `order_id`, `broker_call_attempted`/
                # `broker_placement_attempted`, or `placement_outcome_unproven` --
                # not just truthy-dict-valued. A batch containing only skipped/
                # internally-blocked candidate rows (no broker call ever made) was
                # still `placed`-truthy, so a later exception in this same run
                # created a `cross_account_unresolved_placements.json` sidecar for
                # evidence that was never actually ambiguous, and the NEXT run for
                # this account treats any matching sidecar entry as unresolved and
                # raises in `_reconcile_prior_unproven_fractional_placements`,
                # blocking all placements until manual cleanup (Codex review, PR
                # #1168: "Do not sidecar outcomes that made no broker call").
                # `execution_records` DOES need an equivalent filter: a dry run
                # that logs a simulated order still calls `_log_execution` from
                # both the normal and whole-share buy paths (see "Log successful
                # whole-share dry-run executions"), appending a record to
                # `execution_records` even though no broker call ever happened.
                # Every dry-run order id -- `DryRunBroker.place_market_buy`/
                # `place_whole_share_buy`'s own `"DRY-RUN-<ticker>-..."`/
                # `"DRY-RUN-WHOLESHARE-<ticker>-..."`, and the synthetic
                # `"DRY-RUN-SIM-..."`/`"DRY-RUN-SIM-WHOLESHARE-..."` ids used when
                # `ctx.broker` is not a `DryRunBroker` -- starts with the same
                # `"DRY-RUN-"` prefix, so treating a nonempty `execution_records`
                # as real broker evidence created a cross-account unresolved
                # sidecar for a call that was never sent, and the next REAL run
                # for this account sees the matching sidecar and refuses all
                # placements until manual cleanup (Codex review, PR #1169:
                # "Exclude dry-run execution rows from mismatch evidence").
                _execution_records_with_broker_call = [
                    record
                    for record in (execution_records or [])
                    if not (isinstance(record.order_id, str) and record.order_id.startswith("DRY-RUN-"))
                ]
                #
                # Excludes `status == "dry_run"` outcomes unconditionally, even
                # though every scheduled dry run stamps a synthetic
                # `DRY-RUN-SIM-*` `order_id` (see the whole-share/fractional
                # placement paths a few thousand lines below) -- that id predicate
                # alone still classified a dry run as an actual broker call, so a
                # dry run landing in a directory containing another account's
                # preserved artifact wrote a cross-account sidecar for a call that
                # was never sent, blocking every later real placement for this
                # account until manual cleanup (Codex review, PR #1168: "Exclude
                # dry-run IDs from cross-account evidence").
                _placed_with_broker_call = {
                    ticker: outcome
                    for ticker, outcome in placed.items()
                    if outcome.get("status") != "dry_run"
                    and (
                        outcome.get("order_id")
                        or outcome.get("broker_call_attempted")
                        or outcome.get("broker_placement_attempted")
                        or outcome.get("placement_outcome_unproven")
                    )
                }
                # Fingerprint disagreement alone, with NO evidence-presence gating --
                # this is the fact that the preserved artifact belongs to a
                # different account than this run's own, independent of whether
                # this run happened to produce any placement/execution evidence
                # worth sidecaring. Every downstream guard that exists to avoid
                # mutating/merging into the OTHER account's artifact (skipping the
                # run_state stamp, the orders.csv merge, the pointer/contract
                # validation) must key off THIS, not off evidence eligibility: a
                # run whose own placements were all filtered out of
                # `_placed_with_broker_call`/`_execution_records_with_broker_call`
                # (e.g. every outcome was a dry run, or nothing was placed at all)
                # still must not have its `placed`/`execution_records` merged into
                # a differently-fingerprinted preserved artifact just because there
                # was nothing worth sidecaring (Codex review, PR #1168: "Separate
                # account mismatch from sidecar eligibility").
                # A present, NON-STRING preserved fingerprint (an int or
                # list from damaged or externally-produced storage) used to
                # fall through this check entirely -- the `isinstance(...,
                # str)` guard made the whole `and` chain False, reporting
                # no mismatch, and the falsey-only backfill a few lines
                # below (`if not merged.get("account_number")`) also leaves
                # an already-truthy malformed value untouched. This run's
                # own possibly-live outcomes and execution rows were then
                # merged into an artifact whose account ownership could
                # never actually be verified -- exactly the risk the
                # string-mismatch check exists to catch -- and the NEXT
                # reconciliation, which explicitly rejects a malformed
                # binding, then blocked recovery over evidence merged in
                # under false pretenses (Codex review, PR #1169: "Reject
                # malformed preserved account fingerprints"). Treated as an
                # unconditional mismatch -- fail closed -- so it is routed
                # through the SAME cross-account sidecar/no-merge path a
                # genuine cross-account mismatch already uses, rather than
                # silently binding this run's evidence to an unverifiable
                # fingerprint.
                #
                # Deliberately NOT gated on truthiness (no ``bool(...)``
                # guard): a FALSEY non-string binding -- ``account_number=
                # 0``, ``[]``, ``{}`` -- is exactly as malformed as a
                # truthy one; only ``None`` (never persisted at all) is the
                # genuine "nothing recorded" shape a legacy artifact can
                # carry. Gating on truthiness let a falsey malformed value
                # report no mismatch AND then be silently overwritten by
                # the falsey-only backfill below, binding this run's
                # evidence to the same unverifiable fingerprint the
                # truthy case was already fixed to reject (Codex review,
                # PR #1169: "Reject falsey malformed preserved account
                # fingerprints").
                _existing_account_fingerprint_malformed = (
                    existing_account_fingerprint is not None and not isinstance(existing_account_fingerprint, str)
                )
                _account_fingerprint_mismatch = _existing_account_fingerprint_malformed or (
                    isinstance(existing_account_fingerprint, str)
                    and existing_account_fingerprint
                    and current_account_fingerprint is not None
                    and existing_account_fingerprint != current_account_fingerprint
                )
                # Sidecar-persist eligibility additionally requires real evidence:
                # persisting a `cross_account_unresolved_placements.json` sidecar
                # for a run that made no broker call at all would create a
                # phantom "unresolved" entry the NEXT run for this account then
                # refuses to place around, for evidence that was never actually
                # ambiguous (see the "Do not sidecar outcomes that made no broker
                # call" / "Exclude dry-run execution rows from mismatch evidence"
                # comments above this block).
                _cross_account_mismatch = _account_fingerprint_mismatch and (
                    _placed_with_broker_call or _execution_records_with_broker_call
                )
                if _cross_account_mismatch:
                    # One artifact-level fingerprint cannot safely bind unresolved
                    # outcomes from two accounts -- that reasoning is unchanged.
                    # What changed is what happens to THIS run's own evidence: it
                    # used to be discarded outright by raising here, aborting the
                    # whole write before this call's outcomes were persisted
                    # anywhere at all. Persisted separately instead (never merged
                    # into `merged`, which keeps the ORIGINAL fingerprint's own
                    # evidence intact below), so a possibly-live order this
                    # invocation just placed is not lost to reconciliation and cap
                    # accounting on either account (Codex review, PR #859/#911
                    # round 45: "Persist cross-account ambiguous placements
                    # separately").
                    # Filtered the SAME way the mismatch decision above already is
                    # -- `_placed_with_broker_call`/`_execution_records_with_
                    # broker_call`, not the raw `placed`/`execution_records` --
                    # not just when it is the ONLY evidence gating eligibility. A
                    # mismatched run mixing real broker-backed evidence with
                    # dry-run/skipped rows still persisted the unfiltered
                    # collections, recording synthetic DRY-RUN-* executions and
                    # no-broker-call outcomes as though they were unresolved
                    # brokerage evidence in the account-scoped audit sidecar
                    # (Codex review, PR #1169: "Persist only broker-backed rows in
                    # mismatch sidecars").
                    _persist_cross_account_unresolved_evidence(
                        artifacts_dir,
                        now,
                        current_account_fingerprint,
                        existing_account_fingerprint,
                        _placed_with_broker_call,
                        _execution_records_with_broker_call,
                    )
                # Everything in this block mutates and persists the PRIMARY
                # run_state.json artifact -- skipped entirely on a cross-account
                # mismatch, since that artifact's own outcomes/counts/fingerprint
                # belong to a DIFFERENT account than the one that just raised.
                # This run's own evidence is already durably recorded in the
                # cross-account sidecar above; rewriting the primary artifact's
                # status/classification/companion reports (signals.csv,
                # run_summary.json) with THIS run's exception would corrupt
                # account-scoped audit data -- the artifact would retain the
                # OTHER account's fingerprint, outcomes, and counts while
                # claiming THIS account's failure (Codex review, PR #1164/#1165:
                # "Avoid stamping the prior account's artifact after sidecar
                # fallback"). Leaving `run_state`/`merged` as the untouched
                # preserved artifact and skipping the write keeps the primary
                # artifact exactly as it was for its own account.
                if _account_fingerprint_mismatch:
                    logger.warning(
                        "skipping run_state.json stamp/write at %s: preserved artifact belongs to "
                        "a different account than this run's own evidence%s",
                        state_path,
                        ", already persisted separately" if _cross_account_mismatch else "",
                    )
                    run_state = merged
                    # Nothing was merged into the (untouched) primary artifact, and
                    # its status is unchanged -- matching the values every reader
                    # below this skipped block expects when nothing happened here.
                    added = False
                else:
                    if not merged.get("account_number") and broker is not None:
                        # Sentinel-on-failure, not a bare None: see
                        # _account_number_for_unresolved_evidence's own docstring
                        # (Codex review, PR #911 round 10: "Fail closed when evidence
                        # fingerprinting fails").
                        merged["account_number"] = current_account_fingerprint
                    added = False
                    # Counts a failed outcome dropped by the order-id dedup below (line
                    # ~18755's `continue`) -- a row this run genuinely halted on, sharing
                    # an order_id with an EARLIER preserved outcome, is discarded as "the
                    # same order restated" rather than added to broker_outcomes.
                    # _failed_placement_count only ever scans broker_outcomes, so without
                    # this a same-slot unresolved retry that happened to collide with an
                    # already-submitted order_id vanished from orders_failed_count
                    # entirely -- reporting zero orders to chase on a run stamped failed
                    # and flagged manual_recovery_required (Codex review, PR #859:
                    # "Count deduplicated unresolved orders as failed").
                    deduped_failed_count = 0
                    if placed and not _account_fingerprint_mismatch:
                        existing_outcomes = dict(merged.get("broker_outcomes") or {})
                        rows = [
                            row
                            for row in (merged.get("buy_candidates") or [])
                            if isinstance(row, dict)
                        ]
                        # Keyed by ORDER ID, not ticker. A retry can place a distinct
                        # incremental order for a ticker the earlier attempt already bought,
                        # and a ticker-keyed setdefault would silently keep only the old one
                        # while the count and the CSV are derived from these outcomes (Codex
                        # review).
                        # Both sources are read defensively against a MALFORMED nested
                        # order_id, not just a missing one: a readable artifact whose
                        # order_id happens to be a truthy non-scalar (e.g. `["BAD"]`,
                        # from external or hand-edited damage) is unhashable, and an
                        # unguarded set comprehension over it raises `TypeError`
                        # before this run's own current, possibly-live outcome is
                        # ever merged in or `run_state.json` is rewritten -- the
                        # unresolved retry this whole branch exists to preserve is
                        # lost to an uncaught crash instead (Codex review, PR #859
                        # round 38: "Validate preserved order IDs before building the
                        # dedup set"). Scalar strings are the only shape a real order
                        # id ever takes elsewhere in this module; anything else is
                        # excluded from the dedup set the same way a missing id
                        # already is, rather than aborting the whole merge over it.
                        seen_orders = {
                            oc.get("order_id")
                            for oc in existing_outcomes.values()
                            if isinstance(oc, dict) and isinstance(oc.get("order_id"), str) and oc.get("order_id")
                        }
                        seen_orders.update(
                            row.get("order_id")
                            for row in rows
                            if isinstance(row.get("order_id"), str) and row.get("order_id")
                        )
                        for ticker, outcome in placed.items():
                            order_id = outcome.get("order_id")
                            # Validated the SAME way `seen_orders` itself was built
                            # just above: a truthy non-scalar current order_id (a
                            # list/mapping, from a malformed broker adapter) is
                            # unhashable, and an unguarded `order_id in seen_orders`
                            # raised `TypeError` here -- the surrounding `run_once`
                            # handler only logs that the failure-artifact write
                            # itself failed and re-raises the ORIGINAL error, so
                            # this run's own current, possibly-live outcome was
                            # never merged or persisted at all (Codex review, PR
                            # #1169: "Validate current order IDs before retry
                            # deduplication"). Treated as ID-less evidence instead,
                            # the same as a genuinely missing order_id, so it falls
                            # through to the ID-less handling just below rather
                            # than aborting the whole write.
                            if not isinstance(order_id, str):
                                order_id = None
                            if order_id and order_id in seen_orders:
                                if outcome.get("status") == "failed":
                                    deduped_failed_count += 1
                                continue
                            if (
                                not order_id
                                and ticker in existing_outcomes
                                and not outcome.get("placement_outcome_unproven")
                                and not outcome.get("unresolved_placement_halted")
                            ):
                                # An ID-less outcome for a ticker the artifact already
                                # covers is ordinarily the same non-order restated, and
                                # dropping it keeps the record clean. An UNPROVEN placement
                                # is the one ID-less outcome that is never a restatement:
                                # it reports a call that may have created a live order the
                                # broker has not indexed yet. Skipping it left the artifact
                                # showing only the earlier attempt's row, with no evidence
                                # anywhere that a second, possibly-live order exists --
                                # exactly what this halt is supposed to preserve (Codex
                                # review, PR #859: "Preserve ID-less outcomes from
                                # unresolved retries").
                                #
                                # A HALTED TAIL row is the other ID-less shape that is
                                # never a restatement either: a candidate AFTER the
                                # ticker this batch actually halted on, deliberately
                                # marked unresolved_placement_halted=True because it
                                # never got a chance to place at all -- a fundamentally
                                # different kind of evidence than "the same order
                                # restated". Dropping it left the merged artifact
                                # showing only the PRIOR invocation's outcome for that
                                # ticker, losing this run's own halt reason, and let a
                                # later evaluation refresh leave auto_buy_signal enabled
                                # instead of recognizing the deliberate skip (Codex
                                # review, PR #859 round 35: "Preserve halted tail rows
                                # during retry merges").
                                continue
                            if order_id:
                                seen_orders.add(order_id)
                            # A second order for the same ticker needs its own key so it is
                            # not lost to the collision this fixes. The real ticker is
                            # carried INSIDE the outcome, because submitted_order_rows()
                            # would otherwise write the synthetic key into the canonical
                            # order row as the symbol (Codex review).
                            key = (
                                ticker
                                if ticker not in existing_outcomes
                                # An unproven retry has no order id to distinguish it, so
                                # it is keyed by ATTEMPT instead -- `AAPL:unproven-2` --
                                # rather than by `f"{ticker}:None"`, which would collide
                                # with the next unproven retry for the same ticker and
                                # lose it the same way the ticker key did.
                                else f"{ticker}:{order_id}"
                                if order_id
                                else _unproven_retry_key(ticker, existing_outcomes)
                            )
                            if key != ticker:
                                outcome = {**outcome, "ticker": ticker}
                            existing_outcomes[key] = outcome
                            rows.append(_failure_candidate_row(ticker, outcome))
                            added = True

                        # ROWS are merged only when there is something new to merge; the
                        # FAILURE STAMP below is not conditional on that. Gating both on
                        # `added` meant a retry whose every outcome deduped away -- the
                        # broker returning the same idempotent order id for a retried
                        # deterministic ref_id, say -- left the preserved state exactly as
                        # it was, classification included. When that preserved state
                        # recorded an earlier SUCCESS, the artifact went on advertising a
                        # successful run while this invocation had just halted for an
                        # order that needs reconciliation (Codex review, PR #859:
                        # "Preserve failure state for unresolved retries with known IDs").
                        # This writer only ever runs because this invocation raised, so
                        # that fact must reach the state whether or not any row is new.
                        if added:
                            merged["broker_outcomes"] = existing_outcomes
                            merged["buy_candidates"] = rows
                            # Read the SAME defensive way `seen_orders` above now is: a
                            # truthy but NON-SCALAR order_id (e.g. `["BAD"]`, from
                            # external or hand-edited damage) is unhashable, and the
                            # bare `or` here never engages for it (the list is already
                            # truthy), so it reached this set literal unguarded and
                            # raised `TypeError` -- after `existing_outcomes`/`rows`
                            # were already reassigned onto `merged` a few lines above,
                            # but before `run_state.json` was ever rewritten with them
                            # (Codex review, PR #859 round 38: "Validate preserved
                            # order IDs before building the dedup set"). Falls back to
                            # the same ticker-keyed synthetic id a missing order_id
                            # already uses.
                            # ONE representative row per distinct identity (order_id, or
                            # the same ticker-keyed synthetic fallback the set-union
                            # version of this used), summed via `_submitted_orders_in_row`
                            # rather than just counted as a flat `len(...)` of distinct
                            # identities: a preserved whole-share AGGREGATE row can carry
                            # `merged_submission_count=2`, standing for TWO physical
                            # broker orders behind one identity, while a
                            # `whole_share_settlement_adjustment` row stands for ZERO new
                            # orders despite having its own "submitted" status -- both
                            # already correctly weighted by `_submitted_orders_in_row`
                            # everywhere else this module recomputes this same figure
                            # (see the `_submitted_order_groups` loop a few hundred lines
                            # above). The flat count-of-distinct-identities this replaced
                            # treated every row as exactly one order regardless, so a
                            # retry merge left `orders_submitted_count`/`counts.submitted`
                            # UNDER-counting a preserved aggregate's true order count, or
                            # OVER-counting a settlement adjustment that added none
                            # (Codex review, PR #1164: "Preserve merged order multiplicity
                            # in retry counts").
                            _submitted_identity_rows: Dict[str, Dict[str, Any]] = {}
                            for _key, _oc in existing_outcomes.items():
                                if isinstance(_oc, dict) and _oc.get("status") == "submitted":
                                    _identity = (
                                        _oc.get("order_id") if isinstance(_oc.get("order_id"), str) else None
                                    ) or f"ticker:{_key}"
                                    _submitted_identity_rows.setdefault(_identity, _oc)
                            for _row in rows:
                                if _row.get("status") in ("submitted", "filled"):
                                    _identity = (
                                        _row.get("order_id") if isinstance(_row.get("order_id"), str) else None
                                    ) or f"ticker:{_row.get('ticker')}"
                                    _submitted_identity_rows.setdefault(_identity, _row)
                            merged["orders_submitted_count"] = sum(
                                _submitted_orders_in_row(_row) for _row in _submitted_identity_rows.values()
                            )
                            # A malformed preserved `counts` (a string or list, from
                            # damaged or externally produced storage) is truthy, so
                            # `or {}` never engages and `**value` raised BEFORE
                            # run_state.json could be rewritten -- abandoning the
                            # newly-added, possibly-live outcome this whole `added`
                            # branch exists to persist. The LATER `_merged_counts`
                            # conversion a few hundred lines down already guards this
                            # exact shape for the fully-deduplicated-retry evaluation
                            # refresh (Codex review, PR #859 round 31: "Parse
                            # preserved counts before refreshing retry state"); this
                            # merge runs FIRST and needed the identical guard (Codex
                            # review, PR #859 round 35: "Validate preserved counts
                            # before merging new outcomes").
                            _preserved_counts_for_merge = merged.get("counts")
                            merged["counts"] = {
                                **(_preserved_counts_for_merge if isinstance(_preserved_counts_for_merge, dict) else {}),
                                "submitted": merged["orders_submitted_count"],
                                "buy_candidates": len(rows),
                            }
                            # RECOMPUTED from the MERGED outcomes (old rows plus this
                            # retry's own), never left at whatever the preserved state
                            # happened to carry. The preserved artifact's own
                            # candidates_reaching_spread_gate/candidates_blocked_missing_
                            # spread describe only the EARLIER attempt's rows; a
                            # newly-merged unresolved placement necessarily passed the
                            # spread gate before it could reach place_market_buy, so
                            # leaving these two aggregates unrefreshed let the summary
                            # claim no candidate reached the gate even though the merged
                            # failed outcome proves one did (Codex review, PR #859:
                            # "Recompute spread counts during retry merges"). Same
                            # formula the fresh-synthesis branch above uses, applied to
                            # the full merged outcome set instead of just `placed`.
                            merged["candidates_reaching_spread_gate"] = sum(
                                1
                                for oc in existing_outcomes.values()
                                if isinstance(oc, dict)
                                and oc.get("spread_status")
                                and oc.get("spread_status") != SPREAD_STATUS_NOT_EVALUATED
                            )
                            merged["candidates_blocked_missing_spread"] = sum(
                                1
                                for oc in existing_outcomes.values()
                                if isinstance(oc, dict) and oc.get("blocked_by") == BLOCKED_BY_SPREAD_GATE
                            )
                            # counts.buy_candidates above already reflects the newly
                            # appended recovery row(s); usage_proxy predates this merge
                            # entirely (it was computed by whatever wrote the preserved
                            # run_state.json) and so still carries the PRIOR attempt's
                            # candidate/placement counts unless refreshed here too --
                            # the same staleness the successful-retry reinjection path in
                            # run_daily_compact() already guards against (Codex review:
                            # "Refresh failure-state counts for seeded recoveries").
                            merged_usage = merged.get("usage_proxy")
                            if isinstance(merged_usage, dict):
                                merged_usage["buy_candidates_written"] = len(rows)
                                # ONE representative row per distinct order_id,
                                # summed via `_submitted_orders_in_row` rather than
                                # counted as a flat `1` per row: the same
                                # merged_submission_count/whole_share_settlement_
                                # adjustment weighting `orders_submitted_count` above
                                # already applies (Codex review, PR #1169: "Weight
                                # failure-merge usage by submission multiplicity") --
                                # a preserved whole-share aggregate carrying
                                # `merged_submission_count=2` stands for TWO physical
                                # broker orders behind one identity, so the flat
                                # count-of-rows this replaced under/over-counted the
                                # same way `orders_submitted_count` used to.
                                _placed_identity_rows: Dict[str, Dict[str, Any]] = {}
                                for _oc in existing_outcomes.values():
                                    if (
                                        isinstance(_oc, dict)
                                        and _oc.get("order_id")
                                        and _oc.get("status") in {"submitted", "dry_run"}
                                    ):
                                        _placed_identity = (
                                            _oc.get("order_id") if isinstance(_oc.get("order_id"), str) else str(_oc.get("order_id"))
                                        )
                                        _placed_identity_rows.setdefault(_placed_identity, _oc)
                                merged_usage["orders_placed_count"] = sum(
                                    _submitted_orders_in_row(_row) for _row in _placed_identity_rows.values()
                                )
                    # THIS invocation raised, so the merged state is a failure. The
                    # label is gated on the merged submitted COUNT, not on merely
                    # having an outcome to merge: a retry whose only outcomes were
                    # blocked or failed placed nothing, and calling that a
                    # post-submission failure would claim an order landed when none
                    # did (Codex review). Shared with morning_dca so the two cannot
                    # drift. Runs OUTSIDE the `if added:` block above -- see its
                    # comment for why a fully-deduped retry must still be stamped.
                    merged.setdefault(
                        "orders_submitted_count", run_state.get("orders_submitted_count", 0) or 0
                    )
                    # Captured before the stamp below, which unconditionally overwrites
                    # "status" (to "failed") on EVERY invocation of this merge branch --
                    # a second same-slot invocation (manual retries in particular,
                    # since round 27's "Preserve prior manual unresolved attempts on
                    # retry" widened this handler to merge into a prior MANUAL artifact
                    # too) that fails before publishing any new outcome (`added` stays
                    # False) and is not itself an unresolved-placement halt genuinely
                    # transitions a preserved SUCCESSFUL state to a failed one here,
                    # even though neither of state_was_mutated's other two inputs
                    # fires. Leaving that transition out of state_was_mutated left an
                    # existing run_summary.json unregenerated, so summary consumers
                    # kept reporting the prior successful run while run_state.json
                    # itself now says the slot failed (Codex review, PR #859 round 31:
                    # "Regenerate summaries after manual failure stamps"). Compared
                    # against "status" specifically, not the finer-grained
                    # classification/error_class fields the stamp also always
                    # rewrites: a retry of an ALREADY-failed slot re-confirming the
                    # same failure is not a meaningful transition worth regenerating
                    # over, matching state_was_mutated's own documented "rows changed"
                    # standard for what counts as mutation.
                    _pre_stamp_status = merged.get("status")
                    run_state = stamp_failure_classification(
                        merged,
                        submitted=merged["orders_submitted_count"],
                        error_detail=_redacted_exception_detail(exc),
                    )
                    _status_transitioned_to_failed = _pre_stamp_status != run_state.get("status")
                    if unresolved_placement_halt:
                        # Recomputed from the MERGED outcomes, never left at the
                        # earlier attempt's figure: the attempt-specific key now
                        # retains every unresolved call for a ticker, so two
                        # halted AAPL attempts leave two rows an operator must
                        # reconcile while the stale count still said one (Codex
                        # review, PR #859: "Recompute failed-placement counts
                        # after retaining retries").
                        # Plus any genuinely-failed outcome the order-id dedup above
                        # dropped before it ever reached broker_outcomes -- otherwise a
                        # same-slot unresolved retry that collided with an
                        # already-submitted order_id vanished from this count entirely,
                        # reporting zero orders to chase on a run stamped failed (Codex
                        # review, PR #859: "Count deduplicated unresolved orders as
                        # failed").
                        run_state["orders_failed_count"] = (
                            _failed_placement_count(run_state.get("broker_outcomes") or {})
                            + deduped_failed_count
                        )
                        _merged_usage = run_state.get("usage_proxy")
                        if not isinstance(_merged_usage, dict):
                            _merged_usage = {}
                        # The preserved state may predate this run entirely, and
                        # its usage_proxy said nothing about the order this
                        # invocation may have left live. The comparison also omitted
                        # THIS invocation's own accumulated evaluation errors --
                        # provider errors, pre-roll whole-share reconciliation errors,
                        # published into _IN_FLIGHT_RUN_EVALUATION the moment
                        # evaluation completed -- unlike the synthesized branch above
                        # (`errors_count=_evaluated.get("errors_count") + max(1,
                        # orders_failed_count)`), which already adds them. A retry
                        # that logged two evaluation errors before one unresolved
                        # placement could merge into a preserved zero-error artifact
                        # and still report `errors_count=1`, discarding the two
                        # evaluation errors entirely (Codex review, PR #859 round 32:
                        # "Add current evaluation errors during retry merges").
                        run_state["usage_proxy"] = {
                            **_merged_usage,
                            "errors_count": max(
                                _coerce_nonnegative_int(_merged_usage.get("errors_count")),
                                _coerce_nonnegative_int(_evaluated.get("errors_count"))
                                + max(1, run_state["orders_failed_count"]),
                            ),
                            "manual_recovery_required": True,
                        }
                    if unresolved_placement_halt:
                        if not merged["orders_submitted_count"]:
                            # stamp_failure_classification labels every zero-submission
                            # merge `failed_scheduled_run_startup`, which is exactly the
                            # misdiagnosis the synthesized branch above already refuses:
                            # this retry DID reach the broker placement boundary. The
                            # two branches are alternatives for the same failure, so
                            # they must not disagree about what kind of failure it was
                            # (Codex review, PR #859: "Classify unresolved retry merges
                            # as placement failures"). Only reachable at all because
                            # the unproven retry outcome is now retained rather than
                            # dropped. Scoped to a zero-submission merge specifically --
                            # unlike the evaluation-context refresh just below, this
                            # correction exists only for the misclassification a
                            # zero-submission merge produces; a merge that already has
                            # a submitted order was never mislabeled this way.
                            run_state["run_classification_outcome"] = _placement_failure_class
                            run_state["error_class"] = _placement_failure_class
                        # ...and the EVALUATION the retry completed, not the
                        # preserved attempt's. A same-slot state written by an
                        # earlier startup failure carries `counts.evaluated=0`,
                        # empty signal_rows and zero caps, and correcting only the
                        # classification left the final artifact claiming a
                        # placement failure that evaluated no symbols -- the same
                        # contradiction the synthesized branch already refuses
                        # (Codex review, PR #859: "Refresh evaluation context on
                        # unresolved retry merges"). Only when this invocation
                        # actually has an evaluation to offer; otherwise the
                        # preserved values stay, since they are then the better
                        # record. Deliberately NOT gated on orders_submitted_count
                        # (unlike the classification fix above): an existing same-
                        # slot artifact that already contains a submitted order,
                        # merged with a NEW unresolved candidate, previously kept
                        # the earlier invocation's signal_rows/evaluated count/
                        # budget verbatim and never rewrote signals.csv, leaving
                        # drift-detection and reporting consumers unable to see the
                        # signals or cap context that produced the newly recorded
                        # failure (Codex review, PR #859 round 27: "Refresh retry
                        # evaluation after prior submissions").
                        if _evaluated_decisions:
                            _merged_candidates = [
                                row
                                for row in (run_state.get("buy_candidates") or [])
                                if isinstance(row, dict)
                            ]
                            _merged_signal_rows = _build_signal_rows(
                                _evaluated_decisions, run_state.get("broker_outcomes") or {}
                            )
                            _backfill_reconciled_signal_amounts(
                                _merged_signal_rows, _merged_candidates
                            )
                            run_state["signal_rows"] = _merged_signal_rows
                            # A malformed but readable `counts` value on the preserved
                            # same-slot artifact (a string or list, from damaged or
                            # externally produced storage) is not a shape `dict(...)`
                            # can convert -- it raised, and because the failure-state
                            # write happens LATER in this same function, the exception
                            # abandoned this halt's refreshed classification, failure
                            # count, and recovery telemetry entirely, along with
                            # everything downstream (Codex review, PR #859 round 31:
                            # "Parse preserved counts before refreshing retry state").
                            # Treated the same as an absent field: a malformed value is
                            # not evidence of anything worth preserving over a fresh
                            # `evaluated` count.
                            _preserved_counts = run_state.get("counts")
                            _merged_counts = dict(_preserved_counts) if isinstance(_preserved_counts, dict) else {}
                            _merged_counts["evaluated"] = len(_evaluated_decisions)
                            run_state["counts"] = _merged_counts
                            if _evaluated_budget is not None:
                                run_state["budget"] = _evaluated_budget
                            # signals.csv is regenerated from run_state below only
                            # when the state is synthesized; a merged state keeps
                            # its companion, which now disagrees with the rows just
                            # written. Rewritten here so the two match.
                            _rewrite_merged_signals_csv = True
                    # `state_was_mutated` means ROWS changed, which is what the
                    # run_summary.json regeneration gate below is keyed on -- NOT merely
                    # that the state file was rewritten. The failure stamp above rewrites
                    # it on every raise, and setting this flag for that alone would
                    # regenerate a summary for a preserved state whose stale companion the
                    # artifact-contract check exists to catch. But an UNRESOLVED halt is
                    # never "nothing changed" even when every current outcome's order id
                    # was already present and deduplicated away (added stays False): the
                    # classification correction and evaluation/count refresh above (see
                    # "unresolved_placement_halt" a few lines up) still rewrote
                    # run_classification_outcome/error_class/orders_failed_count/
                    # usage_proxy regardless of whether any ROW was newly merged. Gating
                    # regeneration on `added` alone left a stale run_summary.json --
                    # possibly still describing an earlier SUCCESSFUL run at this slot --
                    # standing after run_state.json itself was rewritten to say a
                    # possibly-live order needs reconciliation, exactly the artifact-
                    # contract mismatch this gate exists to prevent (Codex review, PR
                    # #859 round 28: "Regenerate the summary for fully deduplicated
                    # halts"). `_status_transitioned_to_failed` covers the remaining
                    # gap: neither `added` nor `unresolved_placement_halt` fires for a
                    # same-slot retry that fails before publishing any outcome AND is
                    # not itself an unresolved-placement halt, yet the failure stamp
                    # above still just overwrote a preserved SUCCESSFUL status with
                    # "failed" (Codex review, PR #859 round 31: "Regenerate summaries
                    # after manual failure stamps").
                    state_was_mutated = added or unresolved_placement_halt or _status_transitioned_to_failed
                    _merged_run_state_text = _serialize_run_state(run_state)
                    atomic_write_text(state_path, _merged_run_state_text)
                    _written_run_state_bytes = _merged_run_state_text.encode("utf-8")
    except (TimeoutError, OSError) as _lock_exc:
        # This handler already fired because the run raised; failing to
        # acquire the sidecar lock -- whether a timeout, or a plain OSError
        # from cross_process_lock() itself when the sidecar cannot be
        # created or opened (transient filesystem error, descriptor
        # exhaustion, permissions) -- must not raise a SECOND exception out
        # of an exception-handling path (Codex review: "Contain lock I/O
        # failures in the failure writer"). Nothing below this point can
        # safely run without a trustworthy run_state.json in hand (the CSV/
        # summary writers all read fields this block would have set), so
        # the remaining companion artifacts are left untouched rather than
        # written from no state at all.
        logger.error(
            "could not write the afternoon failure artifact set at %s: %s",
            state_path,
            _lock_exc,
        )
        # `placed` (computed above, from _IN_FLIGHT_CANDIDATE_OUTCOMES) can
        # describe a REAL order this invocation's own broker calls just
        # made -- the lock holder contains no way to record it now, so
        # without this it would simply vanish: deployment accounting can
        # omit it, and a later retry has no evidence it was ever submitted
        # (Codex review: "Preserve submitted-order evidence after lock
        # timeouts"). Durably preserved in its own discoverable sidecar
        # file instead, the same posture the two related exhaustion paths
        # elsewhere in this module already take -- see
        # `_persist_undurable_evidence_sidecar`'s own docstring for why a
        # raise is not used here either (this handler runs from inside
        # exception handling for a run that already raised; a second raise
        # would still just propagate the same way, without recording this
        # evidence anywhere).
        if placed:
            # The same non-reversible account fingerprint
            # _persist_cross_account_unresolved_evidence already stamps
            # onto its own sibling sidecar: if this shared artifact
            # directory is later reused under a DIFFERENT configured
            # account, an operator reconciling this sidecar by hand has no
            # other way to tell which account's broker history the order
            # actually belongs to -- especially since lock contention
            # itself can be caused by a writer for that other account
            # (Codex review: "Bind fallback placement evidence to its
            # broker account"). Never the literal account number itself
            # (AGENTS.md).
            _account_fingerprint = (
                _account_number_for_unresolved_evidence(broker, Path(artifacts_dir).parent)
                if broker is not None
                else None
            )
            _persist_undurable_evidence_sidecar(
                out,
                "unwritten_failure_artifact_placement",
                now,
                {"broker_outcomes": placed, "account_fingerprint": _account_fingerprint},
            )
        return

    # A SYNTHESIZED state -- no prior file, or one replaced because it was
    # unreadable or not an object -- describes this failure and nothing else, so
    # every companion left in a reused directory belongs to some earlier attempt.
    # Preserving them on existence alone advertised a stale summary whose
    # classification does not match the new state, failing a contract this
    # handler could have repaired (Codex review). Same rule as the morning
    # runner, which had the identical defect.
    state_is_synthesized = not existing_is_usable
    if (
        state_is_synthesized
        or _rewrite_merged_signals_csv
        or not (out / "signals.csv").exists()
    ):
        # No explicit fieldnames: write_signals_csv derives them from the rows and
        # falls back to ["ticker"] when there are none, so pinning ("ticker",)
        # only truncated a PRESERVED state's richer signal_rows -- dropping
        # auto_buy_signal and the amounts the drift detector reads -- while
        # gaining nothing on the empty synthesized case (Copilot review).
        write_signals_csv(out, run_state.get("signal_rows") or [])
    # An unresolved-placement halt never reaches run_daily_compact's own
    # write_run_artifacts call, so buy_candidates.csv -- part of the
    # documented compact artifact set -- was never created at all on a
    # first halt, and scripts/drift_detection.detect_drift cannot use the
    # halt/deliberate-skip rows for its afternoon amount/status lookup
    # (Codex review, PR #859: "Write the candidate CSV for unresolved
    # halts"). Same staleness gating as signals.csv just above: always on a
    # fresh synthesis, when this retry merged in new rows, or when no file
    # is there yet at all -- the exact gap this fixes.
    if state_is_synthesized or added or not (out / "buy_candidates.csv").exists():
        _failure_candidates = [
            row for row in (run_state.get("buy_candidates") or []) if isinstance(row, dict)
        ]
        # An explicit, UNIONED header, not row-0-derived: a merged retry's
        # rows can come from different eras (a prior successful write's own
        # richer schema alongside this halt's _failure_candidate_row rows),
        # and _write_csv's default header-from-row-0 crashes the moment a
        # later row carries a key the first one lacks.
        _candidate_fieldnames: List[str] = []
        _seen_candidate_fields: set = set()
        for _row in _failure_candidates:
            for _field in _row:
                if _field not in _seen_candidate_fields:
                    _seen_candidate_fields.add(_field)
                    _candidate_fieldnames.append(_field)
        _write_csv(
            out / "buy_candidates.csv",
            _failure_candidates,
            fieldnames=_candidate_fieldnames or None,
        )
    expected_orders = submitted_order_rows(run_state.get("broker_outcomes") or {})
    orders_csv = out / "submitted_orders.csv"
    # order_csv_covers returns True for an empty expected set without reading
    # the file, so on a synthesized state that placed nothing a stale CSV would
    # otherwise survive untouched.
    if (
        state_is_synthesized
        or not orders_csv.exists()
        or not order_csv_covers(orders_csv, expected_orders)
    ):
        # A stale CSV from an earlier attempt must never be advertised as the
        # canonical order record for a state that knows about more orders.
        write_submitted_orders_csv(out, expected_orders)
    if (execution_records or state_is_synthesized) and not _account_fingerprint_mismatch:
        # Skipped entirely on a cross-account mismatch: `execution_records`
        # describes THIS run's own (mismatched-account) fills regardless of
        # what `run_state`/`expected_orders` say, and merging them into
        # `orders.csv` -- or backfilling usage from the merged file below --
        # would contaminate the OTHER account's durable execution log with
        # this account's own rows even though `run_state.json` itself was
        # correctly left untouched a few hundred lines above (Codex review,
        # PR #1164/#1165: "Stop after persisting cross-account evidence").
        # orders.csv (the durable fill/slippage log) is otherwise written
        # ONLY by run_daily_compact's own write_execution_csv call on the
        # success path -- never reached here, since this function exists
        # because _run_once_impl raised. Without this, any execution record
        # already appended to run_result.execution_records before the raise
        # (a recovered crash-lease fire, in particular) is lost the moment
        # the process unwinds (Codex review: "Persist recovered execution
        # rows when the batch fails"). replace_existing mirrors the
        # synthesized-state handling every other companion artifact already
        # gets here: a pre-existing orders.csv belongs to the unreadable/
        # foreign attempt being fully replaced, not this run's own history,
        # and merging with it would attribute a stale attempt's executions
        # to the freshly synthesized state (Codex review: "Drop stale
        # execution rows for synthesized failure states"). Called even with
        # NO execution_records when the state is synthesized: a stale
        # pre-existing orders.csv from that invalid prior attempt must not
        # simply survive untouched just because this invocation itself
        # recorded nothing (Codex review: "Replace stale execution CSVs even
        # when the new list is empty") -- _merge_execution_csv's own
        # replace_existing branch removes it in that case.
        _merge_execution_csv(
            out / "orders.csv",
            execution_records or [],
            replace_existing=state_is_synthesized,
        )
        # Unlike the success path (run_daily_compact), which always calls
        # this right after writing orders.csv, a PRESERVED (not synthesized)
        # run_state.json's usage_proxy was computed before this merge could
        # add or upgrade any row -- so csv_artifact_count/total_artifact_bytes
        # go stale exactly when this branch's own new/upgraded execution rows
        # are the ones that should have moved them (Codex review: "Recompute
        # usage after writing failure execution rows"). Reads back from disk,
        # so it is correct however state_path just got there (synthesized or
        # preserved-and-merged).
        _backfill_orders_csv_usage(state_path)
        # _backfill_orders_csv_usage writes its recalculated usage_proxy straight to
        # disk, but the contract-failure branch below still serializes THIS in-memory
        # run_state -- which predates that write -- back over it, undoing the
        # csv_artifact_count/total_artifact_bytes it just computed (Codex review:
        # "Preserve usage backfill when stamping contract failures"). Reload it here
        # so any later write of run_state carries the backfilled counters forward.
        try:
            _backfilled_state = json.loads(state_path.read_bytes())
        except (OSError, json.JSONDecodeError, UnicodeDecodeError):
            _backfilled_state = None
        if isinstance(_backfilled_state, dict) and isinstance(
            _backfilled_state.get("usage_proxy"), dict
        ):
            run_state["usage_proxy"] = _backfilled_state["usage_proxy"]
            # `_backfill_orders_csv_usage` is this SAME invocation's own
            # legitimate write (just made through a separate locked call,
            # not an overlapping retry), so the later contract-check
            # snapshot comparison must be updated to reflect it too, or it
            # would spuriously treat this invocation's own backfilled
            # counters as "someone else changed it" and skip annotation
            # even with no overlapping retry involved at all. Recomputed
            # from `run_state` itself -- now that its usage_proxy has just
            # been reloaded above -- rather than trusting the raw bytes
            # just read back verbatim: if an overlapping retry's write
            # raced this same reload and landed first, trusting that read
            # as "this invocation's own" would silently adopt the OTHER
            # retry's content as the expected snapshot, defeating the
            # comparison entirely. Re-serializing our own in-memory
            # understanding of the state, which only this invocation's
            # own mutations (including the backfilled usage_proxy) ever
            # touch, has no such gap.
            _written_run_state_bytes = _serialize_run_state(run_state).encode("utf-8")
    # Regenerate whenever the state changed: validate_run_artifacts compares only
    # the nested classification, so a pre-merge summary would pass while reporting
    # the previous attempt's order count and outcome (Codex review).
    if (
        state_is_synthesized
        or state_was_mutated
        or not (out / "run_summary.json").exists()
    ):
        atomic_write_text(
            out / "run_summary.json", _serialize_run_state(build_run_summary(run_state))
        )
    # Refresh latest_scheduled_run.json so a pointer-based watchdog sees today's
    # slot as fired-and-failed rather than still targeting the previous trading
    # day (Codex review). The state it points at carries
    # scheduled_evidence_denied, so every consumer that follows the pointer still
    # refuses to count it as evidence.
    #
    # Skipped entirely on a cross-account mismatch: `run_state` is the
    # OTHER account's untouched, preserved artifact here (see the
    # `run_state = merged` assignment a few hundred lines above), not this
    # run's own. Validating it and stamping artifact_contract_failure/
    # scheduled_evidence_denied into it -- or refreshing its pointer --
    # would mutate that other account's audit record with a contract
    # verdict about a companion set this run never wrote, even though the
    # "leave the primary artifact untouched" comment above claimed nothing
    # would touch it (Codex review, PR #1168: "Stop after saving
    # cross-account sidecar evidence").
    if not _account_fingerprint_mismatch:
        try:
            # This invocation entered the failure handler, so the four-file set may
            # be incomplete or carry a corrupt companion from an earlier attempt.
            # Deriving pointer validity from the state's scheduled identity alone
            # would publish it as valid anyway, so validate first and fail the state
            # closed when it does not hold (Codex review).
            #
            # Validated even with no classification_state_root: the contract failure
            # is stamped INTO the state, which needs no pointer root, and gating it
            # on one left a mismatched companion set advertised unchecked whenever
            # the caller had no root to update (Codex review).
            from scripts.scheduled_artifacts import (
                artifact_contract_failure,
                validate_run_artifacts,
            )

            # The exact bytes THIS invocation itself wrote to state_path above
            # (`_written_run_state_bytes`), never re-read from disk here: the
            # merge/synthesis block already released its lock once this point
            # is reached, so re-reading right before validate_run_artifacts()
            # (an earlier version of this fix) left a window where an
            # overlapping retry replacing run_state.json in that gap would have
            # ITS bytes silently captured as this invocation's own "snapshot"
            # instead of what this invocation actually published -- validating
            # a mixed other-state/self-companion set as failed, then later
            # comparing that other retry's still-unchanged bytes against the
            # same already-wrong snapshot and wrongly stamping it (Codex
            # review: "Bind the failure snapshot to this invocation's state",
            # extending the identical "Bind snapshots to this invocation's
            # writes" fix already applied to
            # _write_and_validate_scheduled_contract). Using the known
            # just-written bytes directly closes that window entirely: there
            # is no read to race.
            _pre_contract_check_snapshot = _written_run_state_bytes
            # Set when the CAS check below finds run_state.json no longer
            # matches this invocation's own snapshot (or could not be verified
            # at all) -- in either case, `state_path` may no longer describe
            # THIS invocation's own state, so the pointer publication further
            # down must be skipped rather than publish a pending/denied
            # pointer derived from this invocation's stale in-memory
            # `run_state` over what could be a DIFFERENT, already-successful
            # retry's own valid pointer (Codex review: "Skip pointer
            # publication after the state CAS is rejected").
            _state_cas_rejected = False
            contract = validate_run_artifacts(out, require_summary=True)
            if not contract or not order_csv_covers(orders_csv, expected_orders):
                failure = artifact_contract_failure(
                    "scheduled-run artifact contract failed",
                    detail="; ".join(contract.errors)
                    or "order CSV does not cover the state",
                )
                run_state["artifact_contract_failure"] = failure
                run_state["scheduled_evidence_denied"] = True
                rc = run_state.get("run_classification")
                if isinstance(rc, dict):
                    rc["valid_scheduled_evidence"] = False
                # Same sidecar every other run_state.json writer in this module
                # takes: the read-modify-write above (recovery merge/synthesis)
                # released the lock before validate_run_artifacts ran, so a
                # concurrent retry could have annotated run_state.json in the
                # interim. Re-read a fresh copy under the lock and apply this
                # same contract-failure stamp onto IT, rather than blindly
                # overwriting with the now-possibly-stale in-memory `run_state`
                # (Codex review: "Put every run-state writer behind the sidecar
                # lock"). A TimeoutError here is best-effort, like the other
                # annotation passes in this module: orders may already be
                # placed, so skip this one annotation and keep going rather
                # than raise a second exception out of an exception handler.
                try:
                    with cross_process_lock(state_path.with_name(f"{state_path.name}.lock")):
                        try:
                            _current_raw_bytes = state_path.read_bytes()
                        except OSError:
                            _current_raw_bytes = None
                        # ANY change since the pre-validation snapshot -- from
                        # any writer -- means `contract`/`failure` above no
                        # longer describe what is currently on disk, so this
                        # invocation must not stamp it (see the comment at the
                        # snapshot capture above).
                        if (
                            _current_raw_bytes is not None
                            and _current_raw_bytes == _pre_contract_check_snapshot
                        ):
                            try:
                                _current_state = json.loads(_current_raw_bytes)
                            except (json.JSONDecodeError, UnicodeDecodeError):
                                _current_state = None
                            if isinstance(_current_state, dict):
                                _current_state["artifact_contract_failure"] = failure
                                _current_state["scheduled_evidence_denied"] = True
                                _current_rc = _current_state.get("run_classification")
                                if isinstance(_current_rc, dict):
                                    _current_rc["valid_scheduled_evidence"] = False
                                run_state = _current_state
                            atomic_write_text(state_path, _serialize_run_state(run_state))
                        else:
                            # A mismatch means a DIFFERENT retry has since
                            # claimed `state_path` -- possibly already
                            # published its own valid, successful pointer.
                            # This invocation's in-memory `run_state`/`failure`
                            # describe evidence that no longer exists on disk,
                            # so the pointer publication below must not run
                            # against it.
                            _state_cas_rejected = True
                except (TimeoutError, OSError) as _annotate_lock_exc:
                    # Widened from TimeoutError alone to also contain a plain
                    # OSError from cross_process_lock() itself (sidecar cannot
                    # be created or opened), matching the identical
                    # "Contain non-timeout failures" reasoning already applied
                    # to the sibling annotation pass in
                    # _write_and_validate_scheduled_contract. "Could not
                    # verify" fails closed the same as a confirmed mismatch --
                    # never assumed to still be this invocation's own state.
                    _state_cas_rejected = True
                    logger.warning(
                        "could not annotate the artifact-contract failure into run_state at "
                        "%s: %s",
                        state_path,
                        _annotate_lock_exc,
                    )
            if scheduled and classification_state_root is not None and not _state_cas_rejected:
                update_latest_scheduled_run_pointer(
                    run_state, state_path, Path(classification_state_root)
                )
        except Exception:  # noqa: BLE001 - never mask the original run failure
            logger.exception(
                "failed to validate the failure artifact set at %s or refresh its pointer",
                out,
            )
    logger.error(
        "afternoon run failed; wrote the failure artifact set to %s (orders already placed: %d)",
        state_path,
        submitted,
    )


def config_broker_name() -> str:
    """Execution broker recorded on a failure artifact built without a config."""
    return "robinhood"


def _book_recovered_lease_durably(
    im_recovery: "InverseMartingaleLeaseRecovery",
    state: StrategyState,
    trading_day: date,
    deployment_history_root: Optional[str | Path],
) -> bool:
    """Durably book one reconciled inverse-Martingale lease's spend into
    ``state``, unless it is already recorded. Returns whether the order was
    already found on disk in ANY scheduled stream's artifact, for a caller
    that also needs that fact to decide whether to republish a run-artifact
    row for it.

    Shared by both the ordinary (gate-passing) booking pass and the
    date/holiday-gated early-return path in ``_run_once_impl``: a filled
    claim reconciled on a date ``_check_execution_gates()`` blocks (a
    weekend/holiday retry after a Friday crash, say) still needs its spend
    folded into the DURABLE daily/weekly totals, or the next allowed run
    computes headroom as if the money were never spent and can place orders
    beyond the configured caps -- and once this reconciliation clears the
    lease, no later run can ever rediscover it to book it retroactively
    (Codex review: "Book recovered spend before clearing gated leases").

    Idempotent against both an in-process retry (``state.own_orders_
    recorded``) and a durable one (an on-disk artifact from an earlier
    invocation that persisted ``record_buy()`` and then died before this one
    reran) -- see ``_same_day_order_recorded_in_any_stream``'s own docstring
    for why that check is scoped to every roster stream, not just this run's.

    Deliberately narrower than the ordinary booking pass's own remaining
    work: it does NOT touch ``config.deployed_last_7d_usd`` (ephemeral and
    this-run-only -- meaningless for the gated path, which returns before
    evaluating any candidate) and does NOT publish a ``candidate_outcomes``
    row (no run artifact is written on the gated path either way).
    """
    # Keyed by the INDIVIDUAL claim (order_id/claim_ref/claim_stream), not
    # just ticker+day: two distinct leases for the same ticker and claim day
    # -- e.g. a morning partial-fire claim recovered before an afternoon
    # continuation also crashes -- previously collapsed onto the identical
    # (ticker, day) key. Once the first recovery's key landed in
    # own_orders_recorded, the second recovery's own_orders_recorded check
    # short-circuited its record_buy() even though its order/ref was absent
    # from deployment history, so that batch computed daily/weekly/order-
    # count headroom without the second broker order ever counted (Codex
    # review: "Key recovery idempotency by the individual claim").
    im_recovery_key = (
        f"{im_recovery.ticker}#imart-recovery",
        im_recovery.claim_trading_day,
        im_recovery.order_id or "",
        im_recovery.claim_ref or "",
        im_recovery.claim_stream or "",
    )
    im_recovery_identifiers = {im_recovery.order_id or "", im_recovery.claim_ref or ""}
    im_already_on_disk = (
        deployment_history_root is not None
        and _same_day_order_recorded_in_any_stream(
            im_recovery_identifiers, im_recovery.claim_trading_day, deployment_history_root,
        )
    )
    if im_recovery_key not in state.own_orders_recorded and not im_already_on_disk:
        state.record_buy(
            im_recovery.ticker,
            im_recovery.claim_trading_day,
            im_recovery.recovered_amount_usd,
            order_id=im_recovery.order_id or None,
        )
        state.own_orders_recorded.add(im_recovery_key)
        # See the identical comment at the ordinary booking pass's own call
        # to this: only for a claim day the prior-allocation seeding pass
        # actually visits (today's), and only clears the weekly reserve key
        # when the claim lands on an earlier ISO week than today's.
        if im_recovery.claim_trading_day == trading_day:
            state.note_prior_allocation_baseline_is_disjoint(im_recovery.ticker, trading_day)
        if iso_week_key(im_recovery.claim_trading_day) < iso_week_key(trading_day):
            state.reserve_week_key = None
    elif im_recovery.order_id:
        # THE ATTEMPT ITSELF is already durably recorded elsewhere (e.g. a
        # legacy schema-v1 upgrade with no per-order provenance yet, or an
        # earlier run's own record_buy before this exact recovery's id was
        # known) -- record_buy() must not run again here, that would
        # double-book the notional/count. But this lease's own KNOWN order
        # id is still worth registering against that already-existing
        # attempt: leaving it anonymous lets a later, genuinely different
        # same-ticker ambiguous order mistake this attempt's own count for
        # its own already-durable charge (Codex review, PR #1168:
        # "Backfill IDs when a recovered lease is already on disk").
        state.backfill_known_order_id(
            im_recovery.ticker, im_recovery.claim_trading_day, im_recovery.order_id
        )
    return im_already_on_disk


def _final_session_credit_could_combine_with_this_runs_decline(
    ticker: str,
    decisions_by_ticker: Dict[str, "ReconciledDecision"],
    prior_same_day_allocations: Dict[str, "PriorSameDayAllocation"],
) -> bool:
    """True only when THIS ticker's own decision this run has a structural
    chance of contributing a further decline that ``evaluate_top_up_guard``
    could combine with its existing broker-minimum remainder.

    Mirrors (without duplicating the money math of) the exact gates
    ``evaluate_top_up_guard`` itself checks before it ever reaches its
    sub-dollar ``apply_cumulative_credit`` combination branch: a known prior
    allocation with a usable base and reference price, and this run's own
    decision price strictly below that reference price. When any of these
    does not hold, ``evaluate_top_up_guard`` takes one of its flush-only (or
    fail-closed manual-review) paths instead, which never combines a further
    decline with the existing remainder -- so there is nothing to gain by
    deferring the discard decision for it.
    """
    decision = decisions_by_ticker.get(ticker)
    if decision is None:
        return False
    # A structurally-combinable decision this predicate would otherwise defer
    # is never actually reached: the caller's own flush-injection loop drops
    # any decision _is_flush_safe_decision rejects (MANUAL_REVIEW/NO_DATA --
    # a provider error or Finance/Robinhood disagreement, not a genuine
    # recovered/flat price) before it ever appends to buy_candidates. Without
    # this check here, a sub-$0.50 remainder paired with an unsafe decision
    # is deferred for a combination that can never happen, stranding it
    # pending instead of being discarded now (Codex review discussion on
    # commit f2df714: "Discard unsafe sub-threshold remainders").
    if not _is_flush_safe_decision(decision):
        return False
    prior = prior_same_day_allocations.get(ticker)
    if (
        prior is None
        or prior.amount_usd <= 0
        or prior.selected_base_amount_usd is None
        or prior.selected_base_amount_usd <= 0
        or prior.reference_price is None
    ):
        return False
    afternoon_price = _afternoon_decision_price(decision)
    if afternoon_price is None or afternoon_price >= prior.reference_price:
        return False
    # evaluate_top_up_guard returns TOP_UP_NOT_LOWER_OR_NO_DELTA (0.0, never
    # touching existing_pending_credit_usd) BEFORE its combination branch
    # whenever the day's target is already fully covered by the prior
    # allocation -- ladder_incremental = desired - prior.amount_usd < 0.
    # A lower afternoon price alone does not rule this out: prior/manual
    # allocations can already exceed what today's ladder target would be.
    # Replicate that exact gate here too, or a ticker in this state gets
    # deferred for a "combination" that can never happen, leaving its
    # sub-$0.50 remainder permanently stranded pending (Codex review
    # discussion on commit bb3d494: "Check the remaining ladder delta
    # before deferring discards").
    desired, _effective_base = resolve_top_up_desired_amount_usd(
        prior,
        decision.buy_multiplier,
        decision.suggested_amount_usd,
        decision.selected_base_amount_usd,
    )
    ladder_incremental = desired - round(prior.amount_usd, 2)
    return ladder_incremental >= 0


def _discard_minimum_order_pending_with_retry(
    credit_ledger: Any,
    ticker: str,
    trading_day_iso: str,
    observed_amount_usd: float,
) -> bool:
    """Discard a final-session sub-threshold credit, retrying one stale observation.

    ``CumulativeCreditLedger.discard_minimum_order_pending`` used to refuse on
    ANY mismatch between the caller's pre-lock observation and the amount under
    its own lock -- not only when a concurrent update carried the balance over
    the order threshold. So a refusal had two very different meanings, and
    ``_select_final_session_credit_flush_tickers`` can only act on one of them:
    it routes a refused ticker into a candidate evaluation so the now-qualifying
    order can be placed, which requires the ticker to have a decision this run.
    A concurrent update that moved the balance WITHOUT carrying it over the
    threshold ($0.20 -> $0.30, say) refuses too, and for an excluded or
    un-enrolled ticker there is no decision to route it through -- so the
    still-sub-threshold balance was left pending after the day's LAST pass,
    with nothing left to resolve it (Codex review, P2: "Retry sub-threshold
    changes in the flush selector").

    Re-reading and retrying once with the refreshed observation collapses the
    two meanings back into one: this returns False only when the balance
    genuinely qualifies for an order, which is exactly what the selector
    assumes a refusal means. The ledger's own re-check under its own lock stays
    authoritative -- the retry supplies a current observation for it to agree
    with, it does not weaken the guard.

    The ledger now collapses those meanings itself -- a changed but still
    sub-threshold balance is discarded at its current value rather than refused
    (Codex review: "Retry discards when the balance remains sub-threshold") --
    so the first call already returns True in that case and the retry below
    never runs for it. This stays as the second layer: it is the caller-side
    guarantee that a False reaching the selector means "now qualifies for an
    order", independent of which refusal rule the ledger applies.

    Exactly one retry, never a loop: a further update racing the retry refuses
    again and leaves the balance pending for out-of-band reconciliation, the
    same fail-safe outcome as before.
    """
    discarded = credit_ledger.discard_minimum_order_pending(
        ticker, trading_day_iso, observed_amount_usd=observed_amount_usd
    )
    if discarded is not False:
        return discarded
    try:
        refreshed = float(
            credit_ledger.minimum_order_pending_tickers(trading_day_iso).get(ticker, 0.0) or 0.0
        )
    except Exception as exc:  # noqa: BLE001
        logger.warning(
            "cumulative credit ledger pending-balance re-read failed for %s: %s", ticker, exc
        )
        return False
    if round(refreshed, 2) == round(observed_amount_usd, 2):
        # The observation was never stale, so the refusal came from the
        # ledger's qualifying re-check: this balance now warrants an order.
        return False
    return credit_ledger.discard_minimum_order_pending(
        ticker, trading_day_iso, observed_amount_usd=refreshed
    )


def _is_flush_safe_decision(decision: "ReconciledDecision") -> bool:
    """False for a decision the final-session credit flush must never place
    an order from, even though its ticker carries a qualifying pending
    remainder.

    ``Action.MANUAL_REVIEW``/``Action.NO_DATA`` mean this ticker's OWN
    signal this run hit a provider error, a Finance/Robinhood disagreement,
    or missing data -- not a recovered/flat price. Before the final-session
    flush injection, ``buy_candidates`` was filtered to ``Action.BUY`` only,
    which is what enforced every normal data-confidence check upstream;
    appending a MANUAL_REVIEW/NO_DATA decision to the flush list bypasses
    that filter entirely and can let ``evaluate_top_up_guard`` turn an
    unreliable/error decision into a real order with no separate confidence
    gate at placement time (Codex review discussion on commit bb3d494:
    "Keep failed-confidence decisions out of flush candidates"). Its
    pending remainder stays in the ledger, unresolved, rather than being
    forced through on unreliable data -- this is the final same-day
    session, so nothing later today will revisit it either, same as any
    other ticker this final pass cannot safely evaluate.
    """
    return decision.action not in (Action.MANUAL_REVIEW, Action.NO_DATA)


def _select_final_session_credit_flush_tickers(
    pending_by_ticker: Dict[str, float],
    decisions_by_ticker: Dict[str, "ReconciledDecision"],
    prior_same_day_allocations: Dict[str, "PriorSameDayAllocation"],
    *,
    discard,
    duplicate_order_exists=lambda ticker: False,
) -> List[str]:
    """Decide, for each ticker with a broker-minimum-provenance pending
    credit, whether the 3:30 PM final session should discard it now or route
    it to a candidate evaluation that can still combine it with this
    session's own decline.

    A ticker is discarded here, immediately, unless
    :func:`_final_session_credit_could_combine_with_this_runs_decline` says
    its own decision this run has a real chance of contributing a further
    decline that ``evaluate_top_up_guard`` could combine with the existing
    remainder. Discarding a ticker that has no such chance immediately is not
    just harmless but NECESSARY: ``evaluate_top_up_guard`` is a pure
    computation with no ledger I/O (its own docstring), and
    ``_process_buy_candidate`` durably writes to the ledger only via
    ``settle()`` after a real order submission -- so a remainder routed to a
    candidate evaluation that can only ever take a flush-only or fail-closed
    path would never actually get cleared from the ledger, stranding it
    unresolved instead of correctly forgetting it for the day.

    Deferring is reserved for the one case where premature discarding is
    itself the bug: a ticker whose own qualifying decline THIS run could
    combine with its existing remainder to cross the $0.50/$1.00 thresholds
    (Codex review discussion_r3793071614: "Aggregate current credit before
    discarding the remainder" -- e.g. a pending $0.40 plus a new $0.20
    decline should aggregate to $0.60 and place a $1 order, not be discarded
    piecemeal). ``evaluate_top_up_guard``'s own final-session
    ``apply_cumulative_credit`` call correctly discards a combined total that
    still lands under $0.50 once it sees both amounts together; a remainder
    left pending in that specific sub-case is an accepted, pre-existing
    limitation (evaluate_top_up_guard performs no ledger I/O of its own), not
    a regression introduced here.

    ``duplicate_order_exists`` (ticker -> bool, defaults to always ``False``
    for callers/tests with no broker access) lets the caller check for a
    recoverable same-stream broker order before an otherwise-immediate
    discard destroys the only ledger evidence of it -- see the in-loop
    comment below.

    Returns the tickers whose remainder should be flushed through a
    candidate evaluation this run (i.e. every surviving key of
    ``pending_by_ticker`` after any immediate discards above).
    """
    survivors: List[str] = []
    for ticker, amount in list(pending_by_ticker.items()):
        if amount < 0.50 and not _final_session_credit_could_combine_with_this_runs_decline(
            ticker, decisions_by_ticker, prior_same_day_allocations
        ):
            # An earlier attempt this same stream may have already placed a
            # real broker order that combined this remainder with a fresh
            # decline (e.g. $0.30 pending + a $0.30 decline -> a $1 order),
            # then crashed before settle()/artifact persistence ran -- the
            # ledger still shows the pre-order $0.30 as pending. If this
            # retry's own decision no longer looks combinable (e.g. the price
            # recovered to a NO_ACTION decision), discarding here would erase
            # the only ledger evidence before _process_buy_candidate's own
            # same-stream duplicate lookup ever runs, permanently losing the
            # accepted order from this run's artifacts and deployment history
            # (Codex review discussion on commit 3d8df75: "Recover accepted
            # orders before discarding their credit"). Route it to a
            # candidate evaluation instead -- _process_buy_candidate's
            # existing duplicate-recovery path already reconstructs the
            # order, settles the ledger, and carries the aggregate audit
            # fields once it finds the duplicate for real.
            if duplicate_order_exists(ticker):
                if ticker in decisions_by_ticker:
                    survivors.append(ticker)
                else:
                    logger.warning(
                        "cumulative credit ledger final discard skipped for %s: "
                        "a same-stream broker order may already exist but no "
                        "decision this run can route it through recovery",
                        ticker,
                    )
                continue
            try:
                discarded = discard(ticker)
            except Exception as exc:  # noqa: BLE001
                logger.warning(
                    "cumulative credit ledger final discard failed for %s: %s",
                    ticker,
                    exc,
                )
                continue
            if discarded is False:
                # A concurrent update raised the ledger's CURRENT balance to
                # or above the discard threshold between this scan and the
                # discard call's own lock -- CumulativeCreditLedger.
                # discard_minimum_order_pending() refused to clear it rather
                # than silently losing real money. This ticker was NOT
                # deferred above because no combination looked possible from
                # the pre-lock scan's (now-stale) amount -- but the balance
                # now genuinely qualifies for the required final-session
                # order, so it must still reach a candidate evaluation this
                # run rather than being left stranded after the day's last
                # pass (Codex review discussion on commit bb3d494: "Route
                # concurrently enlarged credits into the final pass").
                # _process_buy_candidate re-reads the ledger balance fresh
                # when it runs, so it will see the up-to-date, now-qualifying
                # amount -- nothing stale is threaded through here.
                logger.warning(
                    "cumulative credit ledger final discard skipped for %s: "
                    "balance grew above the discard threshold after the scan",
                    ticker,
                )
                if ticker in decisions_by_ticker:
                    survivors.append(ticker)
                # No decision this run can route an un-enrolled/excluded
                # ticker through a candidate evaluation regardless -- same
                # reasoning as the immediate-discard branch above.
            continue
        survivors.append(ticker)
    return survivors



def _settle_inverse_martingale(
    im_pending_fires: Dict[str, Tuple[Dict[str, Any], Dict[str, Any], Any]],
    candidate_outcomes: Dict[str, Dict[str, Any]],
    stream: str,
    trading_day: date,
) -> None:
    """
    Process deferred inverse-Martingale settlement for tickers that were claimed and attempted.
    """
    # Deferred inverse-Martingale settlement: now that _process_buy_candidates_batch
    # has actually attempted every candidate (including the synthetic fires
    # claimed above), resolve each claimed ticker's ledger using the REAL
    # outcome instead of the pre-placement estimate computed at claim time.
    #
    # A claimed-but-unplaced amount is never simply left alone: this run
    # already committed to it via claim_fire()'s compare-and-swap (so a
    # concurrent process could not independently re-claim the same ticker),
    # so "do nothing" here would strand that reservation forever. Instead
    # every claimed ticker is explicitly resolved against however much was
    # ACTUALLY placed (0 for a fully blocked/failed/dry-run attempt, a
    # partial amount if a downstream cap such as the kill switch reduced it,
    # or the full claimed amount in the common case), and the unplaced
    # remainder -- if any -- is carried forward with its attempt count
    # incremented, so it is retried on a later run rather than lost, and so
    # repeated blocks/failures still converge on max_fire_attempts instead of
    # relying solely on the much longer max_cycle_days cutoff (Codex review:
    # "Count failed fire submissions toward the attempt limit").
    #
    # dry_run is deliberately NOT treated as a placement: no real broker
    # order is ever submitted in that mode (mirrors record_buy() itself,
    # which likewise never fires on the dry_run branch of
    # _process_buy_candidate), so crediting a dry-run "success" as settled
    # would defeat this mode's "deferred, not lost" contract for a repeated
    # dry-run/--demo invocation (Codex review: "Preserve accumulator
    # balances during dry runs").
    if im_pending_fires:
        im_settlement_ledger = InverseMartingaleLedger()
        for im_ticker, (im_pre_fire_state, im_fired_state, im_fired_step) in im_pending_fires.items():
            im_target_state = im_fired_state.get("settlement_target_state", {})
            im_outcome = candidate_outcomes.get(im_ticker, {})
            im_placed_amount = (
                im_outcome.get("submitted_amount_usd") if im_outcome.get("status") == "submitted" else 0.0
            ) or 0.0
            if abs(im_placed_amount - im_fired_step.fire_amount_usd) < 0.005:
                # Common case: the full claimed amount was actually placed --
                # the claim already written by claim_fire() is correct as-is,
                # EXCEPT for settlement_pending: the claim site sets that flag
                # to reserve BOTH a partial-fire remainder (status stays
                # "firing") AND a full-resolution claim (status collapses to
                # "none") against a concurrent second claim/re-arm (see the
                # guard in dca_inverse_martingale.evaluate_inverse_martingale_
                # step()), and this settlement IS that flag's release point --
                # leaving it set here would permanently freeze the ticker's
                # accumulator, since nothing else ever clears it (Codex
                # review: "Reserve partial fires until their placement
                # settles"; "Keep full-fire claims leased until settlement").
                # Stripping the flag is sufficient for both shapes: a
                # partial-fire's stripped state is a normal STATUS_FIRING
                # continuation, and a full-fire's stripped state is already
                # the complete, minimal resolved_marker() shape claim_fire()
                # wrote (status "none", last_evaluated_trading_day/stream) --
                # neither needs any further reshaping here.
                im_settlement_state = {k: v for k, v in im_target_state.items() if k != "settlement_pending"}
                im_settlement_step = im_fired_step
            else:
                # Either the placement was fully blocked/failed/dry-run
                # (im_placed_amount == 0) or a downstream cap (most likely the
                # kill-switch cap, now clamped to config.inverse_martingale_unit_usd
                # -- see the claim site) reduced it below what was claimed. Roll
                # the claim back to reflect however much was ACTUALLY placed.
                im_adjusted_remainder = round(im_fired_step.accumulated_usd_before - im_placed_amount, 2)
                if im_adjusted_remainder <= 0:
                    im_adjusted_state = resolved_marker(
                        trading_day,
                        stream,
                        fired_floor_drop_metric=im_pre_fire_state.get("lowest_drop_seen"),
                        # The floor PRICE as well as the metric, exactly like
                        # every other fire-resolution path (claim_fire's own
                        # full-fire marker, and the crash-recovery resolver).
                        # With only the metric, the same-day re-arm guard falls
                        # back to comparing it in whatever reference frame the
                        # later stream happens to have -- so once the durable
                        # rearm latch clears, a price still above the
                        # already-paid floor can read as a fresh deeper descent
                        # and re-credit tiers that were already bought (Codex
                        # review: "Preserve the absolute fire floor during
                        # overpay settlement"). Computed with the ledger's own
                        # inversion rather than a local reimplementation, from
                        # im_pre_fire_state -- the frozen cycle_reference_close/
                        # stddev_reference this fire actually resolved against,
                        # not whatever the ticker's cycle happens to look like
                        # by the time this settlement runs.
                        fired_floor_price=_drop_metric_to_price(
                            float(im_pre_fire_state.get("cycle_reference_close") or 0.0),
                            float(im_pre_fire_state.get("lowest_drop_seen") or 0.0),
                            str(im_pre_fire_state.get("basis") or BASIS_PCT),
                            im_pre_fire_state.get("stddev_reference"),
                        ),
                        rearm_reference_close=im_pre_fire_state.get("cycle_reference_close"),
                        # The split-window cursor. Seeded from
                        # cycle_start_trading_day -- the day the frozen
                        # cycle_reference_close above was actually captured on
                        # -- not today: a multi-day cycle that spans a split or
                        # dividend before this overpay settlement finally
                        # resolves would otherwise have its cursor jump straight
                        # to today, and the next live/archived corporate-action
                        # lookup excludes every row back to cycle start via
                        # `row_date <= since`, permanently missing the
                        # intervening action (Codex review: "Seed the overpay
                        # latch cursor from the cycle reference day"). Pulled
                        # back one further calendar day by rearm_cursor_seed --
                        # this is the FIRST live search under this freshly
                        # (re)armed latch, so the exclusive `since` boundary
                        # must not itself exclude an action effective ON
                        # cycle_start_trading_day (Codex review: "Include the
                        # cycle-start day in the live lookup"). Falling back to
                        # today only if a legacy/corrupted-then-repaired
                        # pre-fire state somehow lacks the field, matching
                        # dca_inverse_martingale.py's identical fallback at its
                        # own resolution sites.
                        rearm_last_seen_day=rearm_cursor_seed(
                            im_pre_fire_state.get("cycle_start_trading_day"), trading_day
                        ),
                    )
                    im_adjusted_status_after = STATUS_NONE
                else:
                    # Built from im_pre_fire_state (the state read BEFORE the
                    # claim), not im_fired_state -- a full-fire claim's
                    # im_fired_state is the minimal post-resolution marker with
                    # no per-cycle fields at all, so building a continuation FROM
                    # it would silently drop cycle_reference_close/
                    # stddev_reference/crossed_tier_thresholds, leaving a
                    # frozen-stddev cycle permanently stuck (stddev_unavailable)
                    # on its very next evaluation (Codex review: "Retain the
                    # frozen sigma in partial-fire state").
                    im_adjusted_state = dict(im_pre_fire_state)
                    im_adjusted_state["status"] = STATUS_FIRING
                    im_adjusted_state["accumulated_usd"] = im_adjusted_remainder
                    # A dry-run outcome (config.dry_run=True) never reaches a
                    # real broker at all -- im_placed_amount is unconditionally
                    # 0 for it, exactly like a genuinely blocked/failed live
                    # attempt, but it must NOT consume the same
                    # max_fire_attempts retry budget: a scheduled dry-run/
                    # --demo invocation exercising a recovered cycle would
                    # otherwise silently abandon the accumulated balance after
                    # max_fire_attempts dry runs, despite no broker order ever
                    # having been submitted (Codex review: "Do not count dry
                    # runs as fire attempts"). Preserve the PRE-fire attempt
                    # count unchanged rather than bumping/initializing it.
                    im_adjusted_state["fire_attempts"] = (
                        int(im_pre_fire_state.get("fire_attempts", 0))
                        if im_outcome.get("status") == "dry_run"
                        else (
                            1
                            if im_fired_step.status_before != STATUS_FIRING
                            else int(im_pre_fire_state.get("fire_attempts", 0)) + 1
                        )
                    )
                    im_adjusted_state["last_evaluated_trading_day"] = trading_day.isoformat()
                    # im_pre_fire_state's own last_evaluated_stream (carried
                    # forward by the dict(im_pre_fire_state) copy above) can
                    # be STALE -- stamped by whichever stream last touched
                    # this cycle BEFORE this run's own claim, not necessarily
                    # this run's own `stream`. Left unstamped, a genuine
                    # same-stream retry of THIS slot (this settlement's own
                    # rollback state, re-evaluated after a crash/restart)
                    # would find last_evaluated_stream not in (None, stream)
                    # and fail to match the STATUS_FIRING same-day retry
                    # guard in evaluate_inverse_martingale_step -- treating
                    # the retry as a genuinely new continuation, re-
                    # incrementing fire_attempts and, once no
                    # settlement_pending lease is set, submitting another
                    # real order for what is really the same logical slot
                    # (Codex review: "Stamp the settling stream on partial
                    # rollbacks").
                    im_adjusted_state["last_evaluated_stream"] = stream
                    # im_pre_fire_state's own last_evaluated_is_real (also
                    # carried forward by the dict(im_pre_fire_state) copy
                    # above) can likewise be STALE -- False, if an age-only
                    # bump (not a real per-stream evaluation) happened to be
                    # the last thing to touch this cycle before this run's
                    # own claim. Left unstamped, that stale False would make
                    # dca_inverse_martingale.py's own STATUS_FIRING
                    # same-stream retry guard (`tracker_state.get(
                    # "last_evaluated_is_real", True)`) treat THIS run's own
                    # genuine settlement as if it never really happened --
                    # bypassing the guard on a same-day retry of this exact
                    # slot and letting fire_attempts increment (or a second
                    # real order submit) for what is really the same
                    # logical continuation (Codex review: "Stamp rollback
                    # evaluations as real"). This settlement IS a genuine
                    # per-stream evaluation, so restamp it True alongside
                    # the stream identity, matching every other real
                    # evaluation site in dca_inverse_martingale.py.
                    im_adjusted_state["last_evaluated_is_real"] = True
                    im_adjusted_status_after = STATUS_FIRING
                im_settlement_state = im_adjusted_state
                im_settlement_step = replace(
                    im_fired_step,
                    fire_amount_usd=im_placed_amount,
                    accumulated_usd_after=im_adjusted_remainder,
                    status_after=im_adjusted_status_after,
                )
            # Settlement itself is a compare-and-swap against im_fired_state --
            # the EXACT state this process's own earlier claim_fire() call
            # wrote to disk -- rather than an unconditional record_step().
            # When an accumulated balance exceeds max_per_order_usd, the
            # claim above already writes an ordinary (non-leased)
            # STATUS_FIRING continuation state, which looks to any other
            # reader exactly like a normal, available-to-claim cycle -- a
            # second overlapping process evaluating this same ticker could
            # read it, decide to fire the remainder, and successfully
            # claim_fire() its own chunk before THIS process reaches
            # settlement. An unconditional overwrite here would then either
            # discard that other process's legitimately claimed remainder or
            # resurrect money this process already placed, depending on
            # write order (Codex review: "Serialize partial-fire claims
            # through settlement"). A failed CAS means exactly that
            # collision happened; skip writing rather than clobber the
            # newer state -- whichever process is currently ahead keeps
            # ownership of the ledger's bookkeeping for this cycle. This
            # narrows, but does not eliminate, the crash-recoverability gap
            # documented in docs/inverse_martingale.md's "Known limitation"
            # (this process's own placed order is still not reconciled
            # against the broker's order history if its settlement write is
            # skipped here).
            im_settlement_ledger.claim_fire(
                im_ticker,
                expected_prior_state=im_fired_state,
                new_state=im_settlement_state,
                step=im_settlement_step,
            )


def _run_once_impl(
    ctx: RunContext,
) -> List[ReconciledDecision]:
    now = ctx.now
    config = ctx.config
    state = ctx.state
    finance_data = ctx.finance_data
    robinhood_data = ctx.robinhood_data
    broker = ctx.broker
    artifacts_dir = ctx.artifacts_dir
    run_result = ctx.run_result
    notifications_sent = ctx.notifications_sent
    cost_control_notes = ctx.cost_control_notes
    prior_same_day_allocations = ctx.prior_same_day_allocations
    deployment_history_root = ctx.deployment_history_root
    scheduled = ctx.scheduled
    classification_state_root = ctx.classification_state_root
    raw_persistence_state = ctx.raw_persistence_state
    classification_overrides = ctx.classification_overrides
    correlation_id = ctx.correlation_id
    stream = ctx.stream
    earlier_week_notional_usd = ctx.earlier_week_notional_usd
    earlier_week_scan_had_failures = ctx.earlier_week_scan_had_failures
    now_et = now.astimezone(EASTERN)
    trading_day = now_et.date()
    if run_result is not None:
        run_result.trading_day = trading_day
        # Sync the resolved scheduled flag onto the result so write_run_state
        # reflects how this run actually executed, not whatever default the
        # caller's RunResult happened to be constructed with -- codex review
        # discussion_r3692009453.
        run_result.scheduled = scheduled

    errors_count = 0
    order_reviews_attempted = 0

    # The date/holiday gate must still win a race with account pinning and
    # broker-history reconciliation below: _check_execution_gates() only
    # reaches its OWN _check_account_pinning() call once the date/holiday
    # branch has already let a run through, and on a blocked date it writes
    # the graceful "blocked" run_state.json stub via _write_blocked_run_stub
    # instead of raising. Running pinning/reconciliation unconditionally
    # ahead of that gate made an unconfigured/mismatched account raise on a
    # date-gated day instead of that stub ever being written -- there is no
    # prior placement evidence to reconcile on a day this run will not trade
    # anyway (Codex review, PR #911: "Preserve date-gated blocked runs
    # before checking account pinning"). Checked here with the exact same
    # pure predicate _check_execution_gates uses, so both agree on whether
    # today is blocked.
    fractional_recovery_outcomes: Dict[str, Dict[str, Any]] = {}
    # A prior invocation's run_state.json for this artifacts_dir can be
    # truncated or non-JSON (a crash mid-write). This used to be detected
    # here and short-circuited straight to `_execution_allowed = False`,
    # skipping _check_execution_gates() -- and therefore skipping
    # _write_blocked_run_stub() -- entirely, on the theory that leaving the
    # damaged file untouched gave the reconciliation pass below a chance to
    # "fail closed" on it. In practice that reconciliation pass (below,
    # inside `if not _execution_allowed:`) reads THIS SAME file for
    # unresolved fractional-placement evidence, cannot parse it either, and
    # just logs and swallows the failure -- so the corrupt file was never
    # replaced, EVERY subsequent invocation repeated the identical failure
    # forever, and the directory never got its companion run_summary.json/
    # CSVs, permanently failing validate_run_artifacts (Codex review, PR
    # #859/#911 round 45: "Replace or quarantine unreadable state before
    # returning blocked"). _write_blocked_run_stub already implements the
    # correct policy for exactly this file (see its own "Truncated,
    # non-UTF-8, or not an object: there is no run to preserve" branch): a
    # valid existing run_state is left byte-for-byte untouched, and only a
    # genuinely unreadable/non-dict one is replaced with a fresh blocked
    # stub. Letting _check_execution_gates() run unconditionally reaches
    # that same, already-reviewed replace-vs-preserve logic instead of
    # duplicating (and under-serving) it here.
    if not _date_or_holiday_blocked(trading_day, config):
        # Verified BEFORE consulting broker history, not only inside
        # _check_execution_gates further below. The fractional ref id below
        # carries stream/date/ticker but no account identity, so a miswired
        # adapter pointed at the WRONG account could return its own order under
        # an identical ref and this reconciliation would mark the target
        # artifact submitted and book that other account's spend before the
        # later pinning check ever raised (Codex review, PR #911: "Check account
        # pinning before consulting broker history"). Calling it again inside
        # _check_execution_gates a few lines down is a harmless repeat of the
        # same pure check, not a second gate.
        _check_account_pinning(config, broker)

        # A previous invocation may have halted after a placement call whose
        # response was lost. Resolve and book that exact reference before any gate,
        # sizing, or candidate path can authorize another broker call.
        fractional_recovery_outcomes = _reconcile_prior_unproven_fractional_placements(ctx)

    _execution_allowed = _check_execution_gates(
        trading_day,
        config,
        broker,
        artifacts_dir,
        classification_state_root,
        classification_overrides=classification_overrides,
        correlation_id=correlation_id,
    )
    if not _execution_allowed:
        # A settlement_pending crash lease is a claim on real money that only
        # broker-ref reconciliation can settle, and reconciliation needs
        # neither a current price nor the rest of this run -- so it must not
        # wait behind the date/holiday gate above. Without this, a fire
        # claimed on the FINAL approved trading date (or the day before a
        # holiday) crashed into a lease no later invocation could ever reach:
        # every subsequent scheduled run returns right here, before the
        # ordinary recovery pass further down even runs, permanently
        # freezing that ticker's balance until an operator manually reopens
        # the trading window (Codex review: "Reconcile leases before the
        # date-gate return").
        #
        # The DURABLE half of booking -- state.record_buy() and its
        # idempotency bookkeeping -- runs here too, via the same
        # _book_recovered_lease_durably() helper the ordinary (gate-passing)
        # booking pass below uses. A filled claim reconciled on a
        # gate-blocked date (a Friday fire crashed after broker submission,
        # reconciled by Saturday) must still be folded into the daily/weekly
        # totals: once this pass clears settlement_pending, no LATER run can
        # ever rediscover it to book it retroactively, and the next allowed
        # run would otherwise compute headroom as if the money were never
        # spent and could place orders beyond the configured caps (Codex
        # review: "Book recovered spend before clearing gated leases").
        #
        # Only the EPHEMERAL half is skipped: config.deployed_last_7d_usd
        # (this run's own in-memory 7-day kill-switch figure) and the
        # candidate_outcomes/run-artifact row, both meaningful only for
        # candidates THIS run is about to evaluate -- and a gate-blocked run
        # evaluates none, and writes no run artifact at all. Running the
        # reconciliation itself here still keeps every account-identity/
        # live-lease/pagination safeguard (the same recovery resolver the
        # passing-gate path uses), so a claim this pass cannot yet prove is
        # simply left pending for whichever later run resolves it.
        # Runs for BOTH scheduled and manual invocations, unlike the
        # inverse-Martingale/whole-share recovery passes just below (still
        # gated on `scheduled`, unchanged by this fix -- Codex review, PR
        # #911 round 18 raised only the fractional case). An unresolved
        # fractional placement is the SAME kind of claim those two exist to
        # settle on a blocked date: real money that only broker-ref
        # reconciliation can prove, needing neither a current price nor
        # the rest of this run. This branch alone used to be wrapped in
        # `if scheduled:` too, so a MANUAL live invocation (`scheduled=
        # False`) that left an ambiguous placement on the final approved
        # trading date (or the day before a holiday) never reconciled it:
        # every subsequent manual retry returned through the date gate
        # above before this recovery pass could ever run again, leaving
        # the claim permanently unproven until a scheduled invocation
        # happened to reuse the same artifact directory -- exactly the
        # bug already fixed here for scheduled runs, and for the other two
        # recovery kinds (Codex review, PR #911 round 6: "Reconcile
        # fractional evidence on calendar-blocked days"; round 18:
        # "Reconcile manual claims on blocked dates"). The existing
        # run-origin distinction survives regardless: `_reconcile_prior_
        # unproven_fractional_placements` itself already gates whether a
        # resolved recovery is published into TODAY'S fresh candidates on
        # `persisted_stream`/run-type compatibility, independent of
        # whether the CALLER here is scheduled or manual. Isolated in its
        # own try/except, unlike the normal (gate-passing) call site: this
        # branch runs AFTER _check_execution_gates has already written the
        # blocked run_state.json stub, and that stub must survive
        # untouched even when reconciliation itself cannot yet prove the
        # placement -- a still-unresolved claim is simply left pending for
        # whichever later run resolves it, mirroring the whole-share
        # loop's own per-claim isolation a few lines down.
        try:
            # Pinned here too, not only on the gate-passing path above:
            # this call reaches the SAME reconciler, which trusts a
            # persisted placement's evidence against THIS broker's order
            # history whenever the artifact predates account
            # fingerprinting (a null persisted fingerprint skips that
            # check entirely, by design -- see the fingerprint check a
            # few hundred lines up). Without pinning here, a miswired
            # broker for another account could satisfy a legacy
            # fingerprint-less reference on a blocked date and have that
            # account's order booked into this account's StrategyState,
            # with no later gate ever catching it (Codex review, PR #911
            # round 8: "Pin the account before gated reconciliation").
            # Only reached when there IS unresolved evidence to
            # reconcile -- _reconcile_prior_unproven_fractional_
            # placements itself is the cheap short-circuit for "nothing
            # to do here" -- and isolated in the SAME try/except as the
            # reconciliation call it guards, so a pinning failure is
            # logged and swallowed exactly like a reconciliation failure
            # would be: the blocked stub _check_execution_gates already
            # wrote must survive untouched either way.
            _check_account_pinning(config, broker)
            try:
                # This is the ONE caller that persists a stale-day
                # recovery's execution row: unlike the gate-passing call
                # above (which reaches run_daily_compact's own run-
                # specific orders.csv write), this branch never reaches
                # that write at all -- the merge a few lines below,
                # driven by ctx.run_result.execution_records, is the only
                # way a blocked-day recovery reaches the execution log
                # (Codex review, PR #911 round 28: "Keep prior-day
                # executions out of the current run log").
                _reconcile_prior_unproven_fractional_placements(
                    ctx, persist_stale_day_execution=True
                )
            finally:
                # Runs whether the reconciliation above returned cleanly
                # or raised partway through a LATER reference group: the
                # loop inside it durably persists EACH group's own
                # resolution to run_state.json BEFORE ever attempting the
                # next one (see the "PERSISTED BEFORE ctx.state IS EVER
                # BOOKED" comment inside the reconciler itself), so an
                # exception raised while resolving group N still leaves
                # groups 1..N-1's resolutions already written to disk.
                # Refreshing only after a clean return left those earlier
                # groups' resolutions invisible to run_summary.json/
                # submitted_orders.csv/buy_candidates.csv -- and their own
                # execution-log rows unmerged into orders.csv -- for as
                # long as any LATER group in the same artifact stayed
                # unresolved, potentially forever, since no later run ever
                # revisits this artifact once it moves on to build its own
                # fresh one (Codex review, PR #911 round 24: "Refresh
                # companions after partial gated reconciliation").
                if artifacts_dir:
                    _refresh_blocked_run_companions(artifacts_dir)
                    # A recovery the reconciliation call just above resolved
                    # (a working order broker history now proves filled)
                    # appends its row to ctx.run_result.execution_records --
                    # but run_daily_compact's own orders.csv write is on the
                    # non-blocked success path only, never reached for a
                    # gate-blocked run: that row would otherwise vanish the
                    # moment this process exits, with nothing left to
                    # reproduce it later, since run_state.json (which the
                    # companion refresh above just re-derived from) already
                    # marks the placement settled and no later pass ever
                    # revisits it (Codex review, PR #911 round 13: "Persist
                    # gated recoveries in the execution log"). Reuses the
                    # same merge helper the afternoon failure writer and the
                    # success path both use, so a retry of this same blocked
                    # slot still dedupes against whatever an earlier pass
                    # already persisted rather than duplicating it.
                    if ctx.run_result is not None:
                        _merge_execution_csv(
                            Path(artifacts_dir) / "orders.csv",
                            ctx.run_result.execution_records,
                        )
        except Exception as fractional_gated_exc:  # noqa: BLE001 - isolated,
            # see the comment above: the blocked stub must not be
            # disturbed by a reconciliation this pass cannot complete.
            logger.warning(
                "Gated-path fractional-placement reconciliation failed: %s",
                fractional_gated_exc,
            )
        # Unlike the fractional pass just above, the inverse-Martingale and
        # whole-share recovery passes below stay gated on `scheduled` --
        # this round's Codex finding raised only the fractional case (see
        # the comment above), and widening these two as well is a separate
        # decision this fix does not make.
        if scheduled:
            for im_gated_recovery in _inverse_martingale_recover_pending_leases(
                InverseMartingaleLedger(),
                broker=broker,
                dry_run=config.dry_run,
                trading_day=trading_day,
                stream=stream,
            ).values():
                if im_gated_recovery.recovered_amount_usd <= 0 and im_gated_recovery.order_id is None:
                    continue  # a released lease: no capital moved, nothing to book
                _book_recovered_lease_durably(
                    im_gated_recovery, state, trading_day, deployment_history_root
                )
            # Whole-share claims (see docs/whole_share_accumulation.md) get
            # the SAME treatment as the inverse-Martingale leases just
            # above, for the identical reason: an ambiguous placement whose
            # own ref-id reconciliation didn't run before the broker
            # response was lost leaves an unresolved claim that only
            # exact-ref-id ledger reconciliation can settle, and that needs
            # neither a current price nor the rest of a run (Codex review:
            # "Reconcile whole-share claims before date-gated returns").
            # Restricted to the afternoon stream only, matching this
            # module's one existing whole-share evaluation restriction
            # further below -- every whole-share idempotency key/claim was
            # only ever created under stream="afternoon", so a morning/
            # midday gated invocation has nothing of its own to reconcile
            # here and would otherwise duplicate the afternoon stream's own
            # attempt at the identical claim on the same blocked day.
            if stream == "afternoon" and not config.dry_run:
                ws_ledger = WholeShareAccumulationLedger()
                # Same orphaned-ledger union the normal (gate-passing)
                # pre-pass already applies (Codex review: "Reconcile claims
                # for tickers removed from configuration") -- without it, a
                # ticker removed from config.whole_share_tickers whose next
                # invocation is beyond the final approved date returns
                # through THIS gated branch on every future run, before
                # ever reaching the discovery-aware normal pre-pass, so its
                # claim (and any real fill) would remain permanently
                # unreconciled (Codex review: "Discover orphaned ledgers
                # before the gated return").
                ws_orphaned = set(ws_ledger.discover_symbols()) - config.whole_share_tickers
                for ws_ticker in sorted(
                    (config.whole_share_tickers - config.excluded_tickers) | ws_orphaned
                ):
                    ws_idempotency_key = f"{stream}-{ws_ticker}"
                    try:
                        ws_cross_day_claims = ws_ledger.unresolved_claims_any_day(ws_ticker, ws_idempotency_key)
                    except Exception as ws_lookup_exc:  # noqa: BLE001 - best-effort;
                        # a corrupt/unreadable ledger here must not abort the
                        # gated return for every other ticker.
                        logger.warning(
                            "Whole-share gated-path unresolved-claim lookup failed for %s: %s",
                            ws_ticker,
                            ws_lookup_exc,
                        )
                        continue
                    for ws_claim_trading_day_iso, ws_claim in ws_cross_day_claims:
                        try:
                            ws_reconciled = _reconcile_unresolved_whole_share_claim(
                                ws_ledger, broker, ws_ticker, stream, ws_idempotency_key,
                                ws_claim_trading_day_iso, ws_claim, now_iso=now.isoformat(),
                            )
                        except Exception as ws_claim_exc:  # noqa: BLE001 - isolated per
                            # claim, exactly like the ordinary (gate-passing)
                            # reconciliation pass's own identical isolation.
                            logger.warning(
                                "Whole-share gated-path unresolved-claim reconciliation failed for %s "
                                "(trading_day=%s): %s",
                                ws_ticker,
                                ws_claim_trading_day_iso,
                                ws_claim_exc,
                            )
                            continue
                        if ws_reconciled is not None:
                            _book_reconciled_whole_share_order_durably(
                                state, ws_ticker, ws_claim_trading_day_iso, ws_reconciled,
                                trading_day, deployment_history_root,
                            )
        return []

    # Inject the trailing-7-day scheduled-live deployment from history so the
    # kill-switch in graded_buy_multiplier reflects real cash burn. Imported
    # lazily to avoid a circular import (dca_risk imports from this module).
    # deployment_history_root is threaded through to _process_buy_candidates_batch
    # (and from there to _process_buy_candidate) so a duplicate-preserved retry
    # can check per-ticker, at the moment it needs to, whether ITS OWN order is
    # already reflected on disk -- see _same_day_ticker_deployment_already_recorded.
    if deployment_history_root is not None:
        config = _apply_deployment_history(config, trading_day, deployment_history_root)

    # Whether the history scan just above ALREADY counted this recovery: a
    # recovered same-day group now gets a submitted buy_candidates row
    # appended to THIS artifact immediately during reconciliation (Codex
    # review, PR #911 round 4: "Publish each recovered group before
    # processing the next"), before _apply_deployment_history's scan ever
    # runs. When deployment_history_root covers ctx.artifacts_dir -- the
    # production run_dca.py default -- that scan reads this same
    # just-updated file and already folds the recovered notional into
    # config.deployed_last_7d_usd. The manual bump below assumed the
    # opposite (a failure artifact with no submitted candidate row of its
    # own, true before round 4's fix), so applying it unconditionally now
    # double-counts the same order whenever the two roots coincide,
    # inflating the kill-switch figure and risking premature caps on later
    # candidates (Codex review, PR #911 round 7: "Avoid adding recovered
    # notional already loaded from history").
    # Directory containment is not proof the scan actually counted this
    # order: _apply_deployment_history's scan (via dca_risk.is_afternoon_
    # scheduled_evidence) additionally requires a VALID scheduled
    # classification and an afternoon-or-later timestamp, so a legacy
    # afternoon failure artifact under deployment_history_root but lacking
    # either of those is skipped by the scan even though it physically sits
    # inside the covered tree. The reconciler's own account-fingerprint/
    # run-type checks are permissive of exactly that legacy shape (a
    # missing/invalid classification classifies STREAM_OTHER, not a hard
    # reject), so such an artifact's recovery can still be accepted and
    # republished -- and path containment alone then wrongly withheld the
    # ONLY bump that would have counted it, under-stating running_deployed_
    # 7d while later candidates in this same batch are sized against it
    # (Codex review, PR #911 round 9: "Verify the history scan counted the
    # recovered row"), rather than the coarser directory-level guess.
    #
    # Matched by ORDER ID, not merely ticker: _same_day_ticker_deployment_
    # already_recorded is ticker-only, so a ticker with a DIFFERENT eligible
    # submitted order already on disk (a separate broker order for the same
    # symbol) satisfied it even when THIS recovered order specifically was
    # excluded from the scan -- silently suppressing the one bump that would
    # have counted it, the same under-count the ticker-only check was meant
    # to fix (Codex review, PR #911 round 10: "Match recovered orders by ID
    # before suppressing their notional"). _same_day_order_id_already_
    # recorded is the same order-ID-aware lookup the whole-share recovery
    # loop already relies on for the identical question.
    _recovered_fractional_notional = 0.0
    if fractional_recovery_outcomes:
        for _outcome in fractional_recovery_outcomes.values():
            _outcome_ticker = _outcome.get("ticker")
            _outcome_order_id = _outcome.get("order_id")
            if (
                deployment_history_root is not None
                and isinstance(_outcome_ticker, str)
                and _outcome_ticker
                and _same_day_order_id_already_recorded(
                    _outcome_order_id, _outcome_ticker, trading_day, deployment_history_root
                )
            ):
                continue
            _recovered_fractional_notional += float(_outcome.get("submitted_amount_usd") or 0.0)
    # Gated on `scheduled`, matching every ordinary placement's own bump to
    # this same figure (e.g. the whole-share recovery loop's `if ctx.
    # scheduled: running_deployed_7d += order_notional`): deployed_last_7d_
    # usd is the SCHEDULED-live kill-switch total, and deployment-history
    # scanning already excludes manual artifacts by design. A manual
    # invocation reconciling another manual run's same-day ambiguous
    # placement still gets `fractional_recovery_outcomes` back from
    # `_run_type_compatible`'s own check -- correctly, for booking into
    # ctx.state/today's candidates -- but bumping this SCHEDULED figure
    # from it too published an inflated risk-guard total and could make a
    # later candidate in this manual run appear to cross a threshold that
    # was never actually approached (Codex review, PR #911 round 19:
    # "Exclude manual recoveries from scheduled deployment").
    #
    # `scheduled` alone is not enough, though: deployed_last_7d_usd is
    # specifically the AFTERNOON kill-switch total -- dca_risk.
    # is_afternoon_scheduled_evidence() (which _apply_deployment_history's
    # own history scan above already runs through) explicitly excludes
    # morning and midday evidence -- mirroring the inverse-Martingale
    # recovery loop's identical `im_claim_is_afternoon` gate a few hundred
    # lines below. When the shared engine runs a scheduled MORNING or
    # MIDDAY slot and reconciles that slot's own same-day ambiguous
    # placement, the preceding history scan never counted it (it is not
    # afternoon evidence), so bumping this figure here injected capital
    # the kill switch is defined to exclude, inflating the total and
    # spuriously capping later candidates in this same non-afternoon run
    # (Codex review, PR #911 round 29: "Exclude morning recoveries from
    # afternoon deployment").
    from dca_risk import STREAM_MIDDAY, STREAM_MORNING

    if _recovered_fractional_notional and scheduled and stream not in (STREAM_MORNING, STREAM_MIDDAY):
        # Applied AFTER _apply_deployment_history, not before: that call
        # replaces deployed_last_7d_usd wholesale with the disk-scanned
        # trailing-seven-day figure (dca_risk.apply_risk_guard is a full
        # dataclasses.replace, never additive), so a bump applied earlier
        # was silently discarded the moment history injection ran -- the
        # recovered order's dollars never actually reached the in-memory
        # kill-switch total a later candidate in this same batch sees
        # (Codex review, PR #911: "Apply recovered deployment after
        # loading history").
        config = replace(
            config,
            deployed_last_7d_usd=config.deployed_last_7d_usd + _recovered_fractional_notional,
        )

    decisions: List[ReconciledDecision] = []
    tradable_tickers = [
        ticker for ticker in config.tickers if ticker not in config.excluded_tickers
    ]

    # Whole-share tickers (see near_close_dca.WHOLE_SHARE_TICKERS and
    # docs/whole_share_accumulation.md) are evaluated by the SAME graded
    # ladder as the active universe -- appearing in signals.csv "along with
    # the regular buys," per the owner's explicit request -- but are a
    # distinct category from config.tickers/active_universe, so they are
    # tracked separately here rather than folded into tradable_tickers
    # above. _process_buy_candidate (below, via _process_buy_candidates_batch)
    # routes any resulting BUY decision through the whole-share accumulator
    # instead of a normal dollar-amount order.
    #
    # Restricted to the afternoon stream only (Codex review: "Restrict
    # whole-share evaluation to the afternoon stream"): _run_once_impl is the
    # SAME engine every run_dca.run_slot() slot (1030ET/1230ET/1530ET) calls
    # with stream set to "morning"/"midday"/"afternoon" respectively -- an
    # unconditional list here would let BYDDY record a separate contribution,
    # or even fire a separate order, at each of those three slots on the same
    # day, instead of the single once-daily evaluation docs/whole_share_accumulation.md
    # documents. This mirrors the accumulator's own per-(stream, ticker)
    # idempotency key, which was designed for one evaluating stream per day,
    # not three.
    #
    # SORTED, because `config.whole_share_tickers` is a `frozenset` and this
    # list decides the order tickers are evaluated, sized and PLACED in: it
    # feeds `_evaluate_all_signals`, whose `for ticker in tradable_tickers`
    # loop appends decisions in input order, and the placement loop follows
    # that order. With one whole-share ticker that was trivially stable; the
    # moment this PR added a second, `PYTHONHASHSEED` decided whether the run
    # saw `BYDDY, RVII` or `RVII, BYDDY` -- measured, it really does flip
    # between processes. So on a day when the remaining daily/order cap fits
    # only one fire, or the consecutive-failure breaker trips between them,
    # two runs on IDENTICAL inputs bought different tickers (Codex review,
    # PR #786: "Sort whole-share tickers before evaluation").
    #
    # `sorted` rather than the configured order because the configured order
    # does not survive `load_tickers`, which stores this category as a
    # frozenset. It also matches the two sibling whole-share loops that
    # already sort -- the pre-roll reconciliation pass and the gated-return
    # pass -- leaving this the last order-sensitive site that did not.
    whole_share_evaluated_tickers = (
        sorted(ticker for ticker in config.whole_share_tickers if ticker not in config.excluded_tickers)
        if stream == "afternoon"
        else []
    )

    if run_result is not None:
        # Include whole-share tickers in the coverage universe too, not just
        # tradable_tickers -- build_report()'s missing_fills loop only walks
        # active_universe, so an accepted-but-unfilled whole-share order (a
        # real, still-open submitted order -- see _process_whole_share_candidate)
        # would otherwise silently disappear from missing-fill coverage even
        # though it has a real execution_records entry (Codex review: "Include
        # unfilled whole-share orders in coverage reporting").
        run_result.active_universe = list(tradable_tickers) + list(whole_share_evaluated_tickers)

    decisions, signals_errors_count = _evaluate_all_signals(
        now, config, tradable_tickers + whole_share_evaluated_tickers, finance_data, robinhood_data
    )
    errors_count += signals_errors_count

    if run_result is not None:
        run_result.decisions = decisions

    # Reconcile whole-share cross-day (and today's own) unresolved claims as
    # early as possible -- before the redispatch-eligibility splice loop
    # below, the planned_spend/tier-selection loop, and roll_weekly_reserve,
    # not just before the last of those. Three independent reasons converge
    # on this exact position:
    #   1. The redispatch splice below re-dispatches a whole-share ticker
    #      whose NO_ACTION decision otherwise carries no order -- gated on
    #      `unresolved_claims_any_day(...)` when there is no actionable
    #      pending balance. Running reconciliation AFTER that splice let it
    #      see a claim as still-unresolved and redispatch a ticker THIS
    #      pass was about to settle for real, so the later per-candidate
    #      pass (finding the claim already resolved, settle() being
    #      idempotent) published a benign "still accumulating" outcome that
    #      OVERWROTE the reconciled fill's own "submitted" outcome below
    #      (see the _IN_FLIGHT_CANDIDATE_OUTCOMES seeding note just below).
    #   2. The planned_spend loop's own kill-switch preview
    #      (`preview_kill_switch_active = kill_switch_engaged(config)`)
    #      reads `config` directly, and a recovered fill that pushes
    #      trailing deployment over the kill-switch threshold must be
    #      visible to THAT read -- running reconciliation only after the
    #      loop let tier selection sum a candidate's UNCAPPED preview
    #      notional against the stale, pre-reconciliation config while
    #      execution (re-evaluating the kill switch against the
    #      now-updated config) actually caps it (Codex review: "Reconcile
    #      recovered spend before planning the budget tier").
    #   3. roll_weekly_reserve freezes the current week's reserve from
    #      state.week_notional(last_week) -- a claim from the PRECEDING ISO
    #      week reconciled only AFTER that freeze can never reduce it
    #      (Codex review: "Reconcile prior-week claims before rolling
    #      reserve").
    # guard_active/credit_ledger are not yet computed at this point in the
    # function, but neither field is read anywhere in the whole-share
    # reconciliation call chain (_reconcile_cross_day_whole_share_claims(
    # _for_batch)/_book_reconciled_whole_share_order) -- only the normal,
    # non-whole-share candidate path reads ctx.guard_active/ctx.credit_ledger
    # -- so False/the default empty ledger are safe placeholders here.
    pre_reserve_roll_ctx = ProcessCandidateContext(
        config=config,
        state=state,
        broker=broker,
        robinhood_data=robinhood_data,
        now=now,
        trading_day=trading_day,
        guard_active=False,
        prior_same_day_allocations=prior_same_day_allocations or {},
        scheduled=scheduled,
        run_result=run_result,
        deployment_history_root=deployment_history_root,
        stream=stream,
    )
    # A claim this pre-roll pass resolves calls _book_reconciled_whole_share_
    # order, which publishes a "submitted" outcome via
    # _publish_in_flight_outcome -- but that helper is a no-op unless
    # _IN_FLIGHT_CANDIDATE_OUTCOMES["outcomes"] is already installed, which
    # normally only happens once _process_buy_candidates_batch starts
    # (further below, and not for a claim resolved by THIS pre-roll pass
    # since settle() is idempotent and would find it already resolved).
    # Without installing a dict here first, a fill this pass is the FIRST
    # code to ever recover (never written to its original day's own run
    # artifact) is booked into ctx.state/running_deployed_7d for THIS run
    # only, but never reaches this run's own buy_candidates.csv/
    # run_state.json -- and since dca_risk.deployed_usd() (which future
    # runs' own kill-switch seeding reads) sums ONLY submitted buy_candidates
    # rows, that recovered spend would vanish from trailing deployment
    # accounting the moment this run ends, letting the kill switch
    # disengage prematurely (Codex review: "Persist fills recovered by the
    # pre-roll reconciliation pass"). _process_buy_candidates_batch's own
    # candidate_outcomes dict is later seeded from whatever is installed
    # here (see that function's own comment) so this reconciled outcome
    # survives into _build_buy_candidates. A fresh dict here (rather than
    # whatever a PRIOR run's own in-flight map happened to leave behind)
    # keeps this run's seed limited to exactly what THIS pre-roll pass
    # itself recovers.
    _IN_FLIGHT_CANDIDATE_OUTCOMES["outcomes"] = {}
    # Collects the best-effort failures this pass swallows so they reach the
    # run's error accounting. Every OTHER per-ticker net in this module feeds
    # errors_count -- and through it usage_proxy.manual_recovery_required --
    # but this pre-roll pass only logged, so a run that could not read the
    # whole-share ledger at all still reported itself healthy while leaving a
    # real claim unreconciled (Antigravity review, PR #786: "Error tracking in
    # _reconcile_cross_day_whole_share_claims_for_batch"). A raise from
    # _book_reconciled_whole_share_order is deliberately NOT in here: that one
    # still fails the run outright (see the pre-pass loop's own comment).
    pre_roll_reconciliation_errors: List[str] = []
    pre_roll_recovered_deployed_7d = _reconcile_cross_day_whole_share_claims_for_batch(
        pre_reserve_roll_ctx,
        running_deployed_7d=config.deployed_last_7d_usd,
        error_sink=pre_roll_reconciliation_errors,
    )
    if pre_roll_reconciliation_errors:
        errors_count += len(pre_roll_reconciliation_errors)
        logger.warning(
            "Whole-share pre-roll reconciliation left %d claim(s) unreconciled: %s",
            len(pre_roll_reconciliation_errors),
            "; ".join(pre_roll_reconciliation_errors),
        )
    if pre_roll_recovered_deployed_7d != config.deployed_last_7d_usd:
        config = replace(config, deployed_last_7d_usd=pre_roll_recovered_deployed_7d)

    buy_candidates = [
        decision for decision in decisions if decision.action == Action.BUY
    ]

    # A whole-share ticker whose earlier fire attempt was blocked by a
    # transient gate (ceiling/cap/spread/review/data-error -- anything that
    # calls preserve_pending) can leave pending_usd already at or above one
    # share's price. The graded ladder still runs every afternoon regardless,
    # but if TODAY's own signal happens to be NO_ACTION (e.g. the price
    # recovered), the BUY-only filter above would never re-include this
    # ticker, and the already-funded fire would sit stranded until some LATER
    # day's signal happens to be a fresh BUY again -- with no bound on how
    # long that might take. Re-check each whole-share ticker's CURRENT ledger
    # balance here and splice in its (non-BUY) decision too when the balance
    # alone is already actionable, so _process_whole_share_candidate gets a
    # chance to re-fire it today with a $0 additional contribution (Codex
    # review: "Re-dispatch preserved fires without requiring a new BUY").
    #
    # whole_share_decisions_by_ticker mirrors the inverse-Martingale fire
    # candidate's own decisions_by_ticker/decisions[:] rebuild convention
    # (see that block further below): _build_buy_candidates identifies a
    # redispatch via decision.synthetic_source == "whole_share_redispatch"
    # (see that function's own comment), a field ALWAYS present on
    # priced_decision regardless of which _process_whole_share_candidate
    # exit branch eventually fires -- but only if _build_buy_candidates is
    # actually handed THIS spliced decision object, not the ORIGINAL
    # NO_ACTION one still sitting in `decisions`. Without replacing this
    # ticker's entry in `decisions` too, _build_buy_candidates would keep
    # seeing the un-spliced decision (synthetic_source == "") and silently
    # drop every redispatch outcome again, regardless of which fields the
    # outcome dict happens to carry (Codex review: "Retain every
    # whole-share redispatch outcome").
    already_included = {d.ticker for d in buy_candidates}
    whole_share_decisions_by_ticker = {d.ticker: d for d in decisions}
    for decision in decisions:
        if decision.ticker not in config.whole_share_tickers or decision.ticker in already_included:
            continue
        if decision.ticker in config.excluded_tickers:
            continue
        # Restricted to the genuinely safe NO_ACTION case only -- NOT every
        # non-BUY action. reconcile_signals returns MANUAL_REVIEW precisely
        # when finance/Robinhood disagree or one provider errored while the
        # other said BUY, an explicit "do not auto-buy" result; NO_DATA means
        # no usable signal at all. Re-dispatching either of those would
        # bypass reconcile_signals's own safety verdict and could fire a
        # live order the reconciliation logic deliberately withheld (Codex
        # review: "Do not redispatch manual-review whole-share decisions").
        # Only a clean NO_ACTION -- both sources agreed there was no fresh
        # signal -- is safe to re-evaluate from the ledger balance alone.
        if decision.action != Action.NO_ACTION:
            continue
        # A non-BUY ReconciledDecision never goes through _target_fields
        # (reconcile_signals's fallthrough branch omits target_price/
        # decision_bar_close entirely, leaving them at their bare 0.0
        # defaults) -- unlike a BUY decision, whose target_price is already
        # populated. Re-derive a usable current price via a CROSS-SOURCE
        # agreement check, not either source directly: reconcile_signals's
        # own NO_ACTION fallthrough branch performs no price-agreement check
        # of its own (it only compares actions, not prices), so selecting one
        # source unconditionally could size and place an order against a
        # price the other source actively disagrees with, bypassing
        # max_per_order_usd (Codex review: "Reconcile prices before
        # redispatching preserved fires").
        current_share_price = _whole_share_redispatch_reconciled_price(decision)
        if current_share_price is None:
            continue
        # target_price_source/target_quote_time are informational metadata
        # only (not used for pricing, which came from the reconciled check
        # above) -- finance preferred, matching _target_fields's own
        # preference order, purely for consistency with a normal BUY
        # decision's provenance fields.
        signal = decision.finance_signal or decision.robinhood_signal
        if signal is None:
            continue
        # Splice in a COPY carrying the derived target_price/decision_bar_close
        # -- _process_whole_share_candidate reads those fields directly, and
        # the original NO_ACTION decision object must not be mutated in
        # place. synthetic_source marks it as synthesized here, mirroring the
        # inverse-Martingale fire candidate's identical convention --
        # _build_buy_candidates recognizes a redispatch by THIS field (see
        # that function's own comment), and this ticker's entry in
        # `decisions` is replaced with this SAME object below (mirroring
        # inverse-Martingale's own decisions_by_ticker/decisions[:] rebuild)
        # so _build_buy_candidates actually sees it.
        priced_decision = replace(
            decision,
            target_price=current_share_price,
            target_price_source=f"{signal.source.value}:signal_quote",
            target_quote_time=signal.quote_time,
            decision_bar_close=current_share_price,
            synthetic_source="whole_share_redispatch",
        )
        try:
            # apply_contribution (the SAME pure decision function the real
            # placement/tier-planning paths use) is the authoritative source
            # of truth for whether pending_usd alone -- rounded to the cent
            # exactly like record_contribution rounds it -- already covers a
            # share. A raw float comparison here could disagree with it at a
            # fractional-cent quote (e.g. $10.00 pending vs. a $10.004 quote
            # compares as insufficient, while apply_contribution's own
            # cent-rounding treats the quote as $10.00 and fires) (Codex
            # review: "Compare redispatch thresholds using cent-rounded
            # prices").
            whole_share_ledger = WholeShareAccumulationLedger()
            pending_usd = whole_share_ledger.pending_usd(decision.ticker)
            is_actionable = apply_contribution(pending_usd, 0.0, current_share_price).shares_to_buy > 0
            if not is_actionable:
                # A ticker with an UNRESOLVED claim (an ambiguous placement
                # whose reconciliation lookup also failed) commonly leaves
                # $0 pending -- the full notional stays deducted, awaiting
                # reconciliation, not sitting in pending_usd for this
                # threshold check to see. Cross-day reconciliation only
                # runs INSIDE _process_whole_share_candidate (see that
                # function's own top-of-function check), which only ever
                # runs for a ticker THIS eligibility gate actually
                # dispatches -- without also checking for an unresolved
                # claim here, a ticker stuck in that ambiguous state, with
                # no fresh BUY signal on a later afternoon, would never be
                # dispatched again, and its reconciliation code would never
                # get a chance to run (Codex review: "Dispatch unresolved
                # claims even without pending credit").
                whole_share_idempotency_key = f"{stream}-{decision.ticker}"
                is_actionable = bool(
                    whole_share_ledger.unresolved_claims_any_day(decision.ticker, whole_share_idempotency_key)
                )
        except Exception:  # noqa: BLE001 - a corrupt/unreadable/locked ledger
            # here must not silently drop this ticker from the run without a
            # trace: dispatching it anyway lets _process_whole_share_candidate's
            # own record_contribution call hit the SAME failure and classify
            # it properly (errors_count_inc, MISSING_FILL_DATA_ERROR) instead
            # of this eligibility check swallowing it as a quiet no-op (Codex
            # review: "Surface ledger failures during preserved-fire
            # redispatch").
            logger.exception(
                "whole-share ledger read failed while checking re-dispatch eligibility for %s", decision.ticker
            )
            buy_candidates.append(priced_decision)
            whole_share_decisions_by_ticker[decision.ticker] = priced_decision
            continue
        if is_actionable:
            buy_candidates.append(priced_decision)
            whole_share_decisions_by_ticker[decision.ticker] = priced_decision

    # Reflect every redispatched ticker's priced_decision (carrying
    # synthetic_source="whole_share_redispatch") back into `decisions` --
    # _build_buy_candidates iterates THIS list, and run_result.decisions was
    # assigned by reference to it earlier in this function, so this rebuild
    # in place keeps both correctly pointing at the spliced decision instead
    # of the original, un-spliced NO_ACTION one (see the dict's own comment
    # above for why this matters).
    decisions[:] = list(whole_share_decisions_by_ticker.values())

    # Higher multiplier -> larger drop -> ticker alphabetical (see allocation_sort_key).
    buy_candidates.sort(key=allocation_sort_key)

    # The top-up guard (and its same-day-order-check bypass) is only for the
    # scheduled afternoon run: a manual run must still be blocked by its own
    # same-day-order/max-buys checks even if a caller happens to also pass
    # prior_same_day_allocations (e.g. an auto-loaded state root shared across
    # call sites), or a manual run could unintentionally double-buy. Computed
    # here, before tier selection below, so the tier can be selected from the
    # same top-up-adjusted amounts the batch will actually spend.
    guard_active = scheduled and prior_same_day_allocations is not None

    # Enumerate pending sub-dollar credits independently of the BUY-only
    # buy_candidates list built above. A ticker that earned a pending credit
    # earlier today but whose OWN final decision is not BUY (e.g. its price
    # recovered to or above the previous close, so no ladder tier matches at
    # all) would otherwise never reach _process_buy_candidate/
    # evaluate_top_up_guard's existing "flush ANY positive pending balance"
    # branch, permanently stranding that balance since this is always the
    # final same-day session (Codex review: "Flush credits even when the
    # final signal is not BUY"). Reusing the SAME decision object already
    # computed by _evaluate_all_signals above (not synthesizing a BUY one)
    # keeps evaluate_top_up_guard's own price/prior comparison authoritative.
    credit_ledger = CumulativeCreditLedger()
    # Read regardless of stream: also feeds planned_spend's tier-selection
    # estimate below for every scheduled stream, not just the afternoon
    # final pass.
    try:
        pending_by_ticker = credit_ledger.minimum_order_pending_tickers(
            trading_day.isoformat()
        )
    except Exception as exc:  # noqa: BLE001
        pending_by_ticker = {}
        logger.warning(
            "cumulative credit ledger pending-ticker scan failed: %s", exc
        )
    # Everything below this point in the block is the FINAL-SESSION-only
    # aggregate minimum top-up policy (config/scheduled_tasks.json's
    # minimum_order_aggregate_topup_1530): it discards sub-$0.50 remainders
    # outright and evaluates every qualifying one against evaluate_top_up_
    # guard's final_session=True rounding, both meant to happen exactly
    # once, at 3:30 PM. guard_active alone does NOT mean "this is the 15:30
    # run" -- it is shared by every scheduled stream with prior-allocation
    # context (market-open, morning, midday, intraday, afternoon all use the
    # ordinary top-up guard). run_dca.run_slot() routes 1030ET
    # (stream="morning") and 1230ET (stream="midday") through this SAME
    # _run_once_impl with guard_active true, so without a stream check this
    # final-session-only block was firing hours early -- discarding or
    # force-flushing a 9:35 remainder at 10:30 instead of letting it
    # accumulate through 3:30 as designed (Codex review discussion on commit
    # 8720cec: "Restrict the final credit flush to the afternoon stream").
    if guard_active and stream == "afternoon":
        if pending_by_ticker:
            already_included = {d.ticker for d in buy_candidates}
            decisions_by_ticker = {d.ticker: d for d in decisions}
            flush_tickers = _select_final_session_credit_flush_tickers(
                pending_by_ticker,
                decisions_by_ticker,
                prior_same_day_allocations or {},
                discard=(
                    (lambda ticker: True)
                    if config.dry_run
                    # A dry run must never mutate the live-root credit
                    # ledger -- CumulativeCreditLedger() always resolves the
                    # SAME default root regardless of config.dry_run, and a
                    # --demo/local invocation sharing that root with real
                    # scheduled runs (the common case: only --artifacts-dir
                    # is typically overridden, not $DCA_CRON_TRACKING_ROOT)
                    # would otherwise permanently delete a live pending
                    # credit a real run is still relying on. Simulate the
                    # discard decision (`True`, matching the real method's
                    # success return) without touching the ledger; the
                    # settle() call inside _process_buy_candidate is already
                    # gated the same way via its own dry-run early return
                    # (Codex review discussion on commit e385a54: "Keep dry
                    # runs from discarding the live credit ledger").
                    # Retries one stale observation so a False return here
                    # means only "this balance now qualifies for an order",
                    # which is the single meaning the selector can act on --
                    # see _discard_minimum_order_pending_with_retry.
                    else lambda ticker: _discard_minimum_order_pending_with_retry(
                        credit_ledger,
                        ticker,
                        trading_day.isoformat(),
                        pending_by_ticker.get(ticker, 0.0),
                    )
                ),
                # A dry run never places a real broker order, so there is
                # nothing to recover and no live broker call to make here --
                # same reasoning as the discard callback above. A real check
                # failure is treated conservatively as "a duplicate might
                # exist" (returns True) rather than silently discarding
                # possibly-real ledger evidence of an accepted order.
                duplicate_order_exists=(
                    (lambda ticker: False)
                    if config.dry_run
                    else lambda ticker: _same_stream_duplicate_check_or_assume_exists(
                        broker, ticker, trading_day, stream
                    )
                ),
            )
            for ticker in flush_tickers:
                if ticker in already_included:
                    continue
                flush_decision = decisions_by_ticker.get(ticker)
                if flush_decision is None:
                    continue
                # _is_flush_safe_decision is NOT re-checked here: a ticker
                # can reach flush_tickers via _select_final_session_credit_
                # flush_tickers's duplicate-recovery path specifically
                # BECAUSE its decision this run is unsafe (MANUAL_REVIEW/
                # NO_DATA) -- filtering it out here would drop it before
                # _process_buy_candidate's duplicate check ever runs,
                # permanently losing a real accepted order (Codex review
                # discussion on commit be6b992: "Recover duplicates before
                # filtering unsafe flush signals"). _process_buy_candidate
                # itself now enforces the equivalent policy AFTER its
                # duplicate check: it only ever lets an unsafe decision
                # through when a confirmed duplicate is recovered, never to
                # authorize placing a genuinely new order.
                buy_candidates.append(flush_decision)
            buy_candidates.sort(key=allocation_sort_key)

    # Opt-in inverse-Martingale deferred-accumulation sizing mode (off by
    # default; see dca_inverse_martingale.py and config/inverse_martingale.json).
    # Tracks what the normal ladder would have bought at each dip tier without
    # buying, then fires the accumulated total as ONE order once price
    # recovers by the configured offset. Gated on `scheduled` so an ad hoc,
    # manual, or --demo invocation never advances or fires a real multi-day
    # accumulator cycle. Placed here, BEFORE the planned_spend loop below, so
    # a fire this run is correctly reflected in tier selection -- exactly
    # like the credit-ledger flush above.
    #
    # Crash-lease reconciliation pass. Runs FIRST -- before the enrollment
    # cleanup below and before the per-ticker evaluation loop's own
    # enrollment/tradability/market-data gates -- because a `settlement_pending`
    # lease is a claim on real money that only broker-ref reconciliation can
    # settle, and reconciliation needs neither a current price nor an active
    # enrollment. Reached only from inside the evaluation loop (its original
    # home), a crashed lease became permanently unrecoverable the moment the
    # operator disabled inverse-Martingale for that ticker, or the moment its
    # market data went missing: the cleanup helper below and the age-only
    # helper both deliberately refuse to touch a pending lease, and the
    # evaluation loop never reaches an unenrolled or price-less ticker at all
    # (Codex review: "Reconcile leases before enrollment and market-data
    # gates"). Placed before the cleanup pass specifically so a lease RELEASED
    # here can then be cleaned up in the same run rather than waiting a session.
    #
    # Gated on `scheduled` like everything else in this feature (an ad hoc or
    # --demo invocation must never resolve a real accumulator claim), but NOT
    # on `config.inverse_martingale` being non-empty and NOT on `stream` --
    # a lease outlives both the enrollment mapping that created it and the
    # narrowed morning universe.
    im_lease_recoveries: Dict[str, InverseMartingaleLeaseRecovery] = {}
    #: Whether each recovery's own order was ALREADY recorded in an on-disk
    #: artifact, keyed exactly like ``im_lease_recoveries``. Computed once
    #: during the booking pass below and consulted again by the artifact
    #: publication loop near the end of this function, which must not republish
    #: an order the crashed worker already audited.
    im_recovery_already_on_disk: Dict[str, bool] = {}
    if scheduled:
        im_lease_ledger = InverseMartingaleLedger()
        im_lease_recoveries = _inverse_martingale_recover_pending_leases(
            im_lease_ledger,
            broker=broker,
            dry_run=config.dry_run,
            trading_day=trading_day,
            stream=stream,
        )
        for im_recovery_lookup_key, im_recovery in im_lease_recoveries.items():
            if im_recovery.recovered_amount_usd <= 0 and im_recovery.order_id is None:
                # A RELEASED lease: the resolver proved no order was ever
                # submitted under this claim's ref, so no capital moved and no
                # order slot was consumed. Nothing to book.
                #
                # Discriminated on order_id, not on the amount alone. A matched
                # TERMINAL ZERO-FILL recovery also carries $0 -- but a real
                # order reached the broker and came back cancelled/rejected,
                # and config/budgets.json counts exactly that as a buy ATTEMPT
                # against max_orders_per_day. Conflating the two skipped
                # record_buy entirely, leaving the roster-wide
                # day_order_count() unincremented so within_caps() granted the
                # rest of this batch an extra order beyond the shared daily
                # circuit breaker, and left no artifact row preserving the
                # attempt (Codex review: "Count recovered zero-fill orders
                # toward the daily cap").
                continue
            # The claimed order reached the broker but the process died before
            # its state transaction and artifacts were durably committed, so
            # NOTHING in this restarted run knows that capital was spent.
            # Reconciling only the inverse-Martingale ledger would leave the
            # daily, weekly and trailing-7-day headroom computed as if the
            # money were still available, letting later candidates in this very
            # batch place orders beyond the configured caps, and would omit the
            # recovered purchase from the run artifacts entirely (Codex review:
            # "Book recovered broker orders into the strategy budget").
            # Booked against the CLAIM day, not today: record_buy keys the
            # daily/weekly buckets by the day passed in, and a lease recovered
            # the morning after its crash spent yesterday's budget, not today's.
            #
            # Idempotency rests on a DURABLE signal, not only on the run-scoped
            # own_orders_recorded set. StrategyState itself survives across
            # invocations (state_transaction), and own_orders_recorded
            # deliberately does not -- so a prior run that placed the order,
            # recorded the buy, persisted its state and wrote its artifact, then
            # died before deferred settlement, leaves the lease pending AND the
            # spend already booked. Re-booking it here would double that
            # ticker's day/week notional and attempt count and could block valid
            # later buys (Codex review: "Avoid rebooking recovery spend already
            # persisted in state"). The per-ticker artifact check is that
            # durable signal, and it is the same one the deployment addition
            # below already uses.
            #
            # It is not a total guarantee: a crash between the state write and
            # the artifact write leaves no on-disk record, and re-booking is
            # possible in that narrower window -- the same two-phase gap
            # documented in docs/inverse_martingale.md's "Remaining
            # limitations".
            # Deliberately NOT the bare (ticker, trading_day) shape the rest of
            # own_orders_recorded uses. _seed_prior_allocations() reads that set
            # as "this stream already placed a real order for this ticker
            # today, so its aggregate is already accounted for" and skips the
            # ticker's ENTIRE prior-allocation aggregate. A recovered order is
            # the one case where that inference is wrong: it is absent from the
            # artifact scan the aggregate is built from (it died before its
            # artifacts were written -- the very condition the booking below is
            # gated on), so the aggregate describes some OTHER order, and
            # suppressing it dropped that order's dollars and its attempt from
            # StrategyState entirely, letting unrelated candidates run past the
            # daily, weekly and shared order-count caps (Codex review:
            # "Reconcile separate prior allocations after booking a recovery").
            # A distinct namespace keeps this loop's own in-process retry
            # idempotency without ever matching that gate.
            # ANY scheduled stream's artifact, not just the afternoon's. A
            # morning or midday worker that persisted record_buy() AND its
            # artifact before dying leaves a MORNING artifact, which an
            # afternoon-scoped predicate would reject outright -- so booking
            # read "not on disk" and recorded the same dollars and attempt a
            # second time (Codex review: "Check every roster stream before
            # rebooking a recovery"). _book_recovered_lease_durably's own
            # afternoon-agnostic check belongs to the kill-switch total
            # below, not to the question of whether this order has already
            # been booked at all.
            im_already_on_disk = _book_recovered_lease_durably(
                im_recovery, state, trading_day, deployment_history_root
            )
            im_recovery_already_on_disk[im_recovery_lookup_key] = im_already_on_disk
            im_recovery_identifiers = {im_recovery.order_id or "", im_recovery.claim_ref or ""}
            # Same per-ticker deployment-history check the same-stream
            # duplicate-preserved retry path uses: _apply_deployment_history
            # already summed every order recorded in an on-disk artifact into
            # config.deployed_last_7d_usd, so adding a recovered order that IS
            # on disk would double-count it against the kill-switch threshold.
            # A crashed claim's order is precisely the case where nothing on
            # disk has ever counted this capital.
            #
            # Bounded by the SAME trailing window the injected figure covers.
            # _load_deployment_history_states deliberately sums only the
            # KILL_SWITCH_WINDOW_DAYS days ending on trading_day, so a claim day
            # older than that window is no longer part of the configured
            # seven-day exposure at all. Adding it anyway -- reachable when
            # reconciliation is delayed by a long history outage or an
            # unverifiable account -- would inflate the figure with capital the
            # kill switch is not supposed to be counting, spuriously engaging it
            # and capping later candidates in this run (Codex review: "Exclude
            # stale recoveries from the seven-day deployment total").
            #
            # Skipped outright for a terminal zero-fill recovery: it consumed
            # an order slot (booked above) but moved no capital, and the
            # kill-switch figure counts dollars deployed, not attempts.
            #
            # And scoped to a claim made by the AFTERNOON stream. Deployment is
            # accounted per stream and never conflated: dca_risk's kill-switch
            # figure counts only scheduled-afternoon capital, and
            # is_afternoon_scheduled_evidence() explicitly rejects morning and
            # midday runs. A lease outlives the run that claimed it, so the
            # afternoon slot routinely recovers a MORNING claim -- adding those
            # dollars here injected capital the kill switch is defined to
            # exclude, inflating the figure and spuriously capping later
            # candidates (Codex review: "Preserve the claiming stream when
            # booking recovered spend"). A legacy lease carries no stream at
            # all; its provenance is unknown, and the conservative reading of
            # unknown provenance is to leave the afternoon figure alone rather
            # than assume this run's own stream produced it. Note the ordinary
            # budget booking above is deliberately NOT stream-scoped -- the
            # daily and weekly caps are shared across the whole roster.
            #
            # The already-on-disk test here is the AFTERNOON-scoped one, not
            # the all-stream predicate used for booking idempotency above: this
            # guards against double-counting within _apply_deployment_history's
            # own afternoon-only sum, so it has to ask the same question that
            # sum asks.
            # Mirrors is_afternoon_scheduled_evidence's own rule, which defines
            # the afternoon stream NEGATIVELY -- everything scheduled that is
            # not morning and not midday -- rather than by matching a literal
            # "afternoon". Comparing against this run's own stream would be
            # wrong: what matters is where the money came from, not who is
            # reconciling it.
            from dca_risk import STREAM_MIDDAY, STREAM_MORNING

            im_claim_is_afternoon = im_recovery.claim_stream is not None and im_recovery.claim_stream not in (
                STREAM_MORNING,
                STREAM_MIDDAY,
            )
            im_deployment_already_counted = (
                deployment_history_root is not None
                and _same_day_order_deployment_already_recorded(
                    im_recovery_identifiers,
                    im_recovery.claim_trading_day,
                    deployment_history_root,
                )
            )
            if (
                im_recovery.recovered_amount_usd > 0
                and im_claim_is_afternoon
                and deployment_history_root is not None
                and _within_kill_switch_window(im_recovery.claim_trading_day, trading_day)
                and not im_deployment_already_counted
            ):
                config = replace(
                    config,
                    deployed_last_7d_usd=config.deployed_last_7d_usd
                    + im_recovery.recovered_amount_usd,
                )

    # Cleanup pass for tickers whose accumulator cycle is no longer backed by
    # an active enrollment -- runs regardless of whether config.inverse_
    # martingale is non-empty, unlike the tracking/firing block below. If
    # scoped to that block's own `if ... and config.inverse_martingale:`
    # guard, disabling enrollment for EVERY ticker at once (the mapping
    # empties out entirely, or the feature is made inactive) would skip past
    # this cleanup completely -- leaving every previously-active cycle
    # frozen with no path back to reset, the same bug the per-ticker
    # disabled-enrollment reset below was meant to close, just at the
    # whole-mapping granularity instead of the per-ticker one (Codex review:
    # "Run enrollment cleanup when the mapping becomes empty"). Scoped to
    # the ON-DISK ledger tree, not `tradable_tickers`, so it also covers a
    # ticker that left the active universe entirely, not just one still-
    # tradable but disabled. Gated cheaply on the ledger root directory
    # actually existing -- for the overwhelming majority of runs (the
    # feature has never been used at all), stream_root(
    # "inverse_martingale_dca") was never created, so this costs one
    # directory-existence check and nothing more.
    # Skipped entirely for the "morning" stream: run_dca.run_slot("1030ET")
    # temporarily narrows config.tickers to the 9:45 pre-flight-admitted
    # subset (`slot_config = replace(config, tickers=slot_tickers, ...)`,
    # run_dca.py's own morning-only preflight gate), so `tradable_tickers`
    # below is a SLOT-FILTERED evaluation subset during this stream, not the
    # canonical configured universe -- unlike "midday"/"afternoon", which
    # always see the full config.tickers. Without this guard, a ticker
    # merely gated out of THIS ONE morning slot (a transient reason -- a
    # wide spread, missing data -- not a genuine removal from config/
    # tickers.json) would look identical, from this cleanup pass's own
    # tradable-set check, to a ticker genuinely dropped from the universe or
    # excluded, and its real accumulated balance would be discarded even
    # though the ticker remains globally active and simply returns in the
    # midday/afternoon slots the same day (Codex review: "Preserve cycles
    # excluded only from the current slot"). Deferring this cleanup to
    # "midday"/"afternoon" instead -- both of which always see the true
    # canonical universe -- costs a genuinely-removed ticker's own cleanup
    # at most a few hours' delay later the same day, not a false discard of
    # real state.
    if scheduled and stream != "morning":
        im_cleanup_ledger = InverseMartingaleLedger()
        if im_cleanup_ledger.root.is_dir():
            # A ticker still enrolled in config.inverse_martingale is only
            # SAFE to leave alone here if it also stays reachable by the
            # tracking/firing loop below, which iterates tradable_tickers
            # (config.tickers minus config.excluded_tickers), not every
            # config.inverse_martingale key. A ticker removed from
            # config.tickers entirely, or added to excluded_tickers, while
            # its inverse-Martingale entry remains enabled/enrolled passes
            # `_inverse_martingale_config(...)` truthy here and would
            # otherwise be skipped as "still enrolled" -- but it can never
            # be evaluated again (not in tradable_tickers), so its balance
            # and age freeze indefinitely, bypassing max_cycle_days
            # entirely, and can resume as a stale obligation from a
            # completely different market regime if the ticker is later
            # restored to the active universe (Codex review: "Reset cycles
            # for tickers outside the tradable universe"). Reset exactly
            # like a disabled-enrollment cycle -- the same "no longer
            # reachable, no longer trustworthy" contract, just a different
            # removal path.
            im_tradable_set = frozenset(tradable_tickers)
            for im_ticker_dir in sorted(im_cleanup_ledger.root.iterdir()):
                if not im_ticker_dir.is_dir():
                    continue
                im_cleanup_ticker = im_ticker_dir.name
                if _inverse_martingale_config(im_cleanup_ticker, config) and im_cleanup_ticker in im_tradable_set:
                    continue  # still enrolled AND tradable -- nothing to clean up
                _inverse_martingale_reset_if_disabled_mid_cycle(
                    im_cleanup_ledger, im_cleanup_ticker, trading_day, stream
                )

    # im_pending_fires carries this run's fired-but-not-yet-settled
    # accumulator steps forward to the deferred-settlement block below (after
    # _process_buy_candidates_batch runs) -- see that block's own comment for
    # why settlement cannot happen here.
    im_pending_fires: Dict[str, Tuple[Dict[str, Any], Dict[str, Any], InverseMartingaleStep]] = {}
    # Extra same-run finance queries the per-ticker signal scan below does not
    # already account for: each armed durable latch's live corporate-action
    # lookup is a genuine additional connector call, but build_usage_proxy's
    # default (one finance call per scanned ticker) has no way to see it.
    # Counted here and threaded into _finalize_and_write_artifacts below so
    # the usage proxy does not under-report connector activity on a run with
    # one or more armed latches (Codex review: "Count live corporate-action
    # finance queries").
    im_finance_calls_attempted = 0
    if scheduled and config.inverse_martingale:
        already_included = {d.ticker for d in buy_candidates}
        decisions_by_ticker = {d.ticker: d for d in decisions}
        im_ledger = InverseMartingaleLedger()
        for im_ticker in tradable_tickers:
            im_cfg = _inverse_martingale_config(im_ticker, config)
            if not im_cfg:
                # Already handled by the cleanup pass above, which runs
                # regardless of whether config.inverse_martingale is empty
                # -- nothing further to do for this ticker here.
                continue
            # `already_included` reflects EVERY candidate buy_candidates
            # already carries this run -- a genuine normal-ladder BUY, or a
            # non-BUY decision the credit-ledger flush block just above
            # appended so a same-day cumulative-credit balance can flush
            # (see that block's own comment: it deliberately reuses the
            # ticker's real, non-BUY final decision). _process_buy_
            # candidates_batch's outcome tracking is keyed by ticker, so
            # only one candidate per ticker can flow through a single run
            # -- but that only means a SECOND candidate cannot be injected
            # for this ticker, not that tracking must stop. An earlier
            # version of this code skipped this ticker's evaluation
            # ENTIRELY whenever already_included matched, which not only
            # blocked injecting a fire candidate (correct) but also
            # silently dropped tier tracking for the rest of the day --
            # if this is the FINAL scheduled slot and the FIRST time price
            # crosses a tier, that crossing is never persisted at all, and
            # is gone for good once tomorrow starts from a fresh
            # previous_close reference (Codex review: "Track tiers despite
            # a pending-credit flush candidate"). Mirrors the identical fix
            # already applied for a PRIOR same-day allocation (guard_active)
            # just below: tracking always runs; only fire-injection defers.
            im_batch_occupied = im_ticker in already_included
            im_signal = decisions_by_ticker.get(im_ticker)
            if im_signal is None:
                _inverse_martingale_advance_age_for_missing_data(im_ledger, im_ticker, trading_day)
                continue
            # Enrollment forces this ticker's normal buy_multiplier to 0.0
            # (see graded_buy_multiplier), so decision.action is never BUY
            # here and reconcile_signals' own finance/Robinhood-disagreement
            # handling never runs for it. Apply the same cross-source safety
            # bar directly to the two raw signals instead of trusting
            # whichever source happens to report a price first.
            im_reconciled_price = _inverse_martingale_reconciled_price(im_signal)
            if im_reconciled_price is None:
                _inverse_martingale_advance_age_for_missing_data(im_ledger, im_ticker, trading_day)
                continue
            im_decision_price, im_previous_close = im_reconciled_price
            im_stddev_reference = None
            if im_cfg["basis"] == "stddev":
                im_stddev_reference = stddev_reference_for_ticker(
                    im_ticker,
                    as_of=trading_day,
                    window_days=int(im_cfg.get("stddev_window_days", 20)),
                )
            try:
                im_tracker_state = im_ledger.read(im_ticker)
            except CorruptedLedgerStateError as exc:
                # A truncated/malformed tracker.json (or an unsupported
                # ledger version) must NOT be silently treated as "no cycle
                # yet" -- evaluating from a fabricated {} would start a
                # fresh cycle and this ticker's own compare-and-swap write
                # below would then overwrite the damaged file, permanently
                # discarding whatever dollar balance it held with no way to
                # recover it (Codex review: "Refuse unreadable accumulator
                # state instead of resetting it"). Skip ONLY this ticker
                # this run -- leaving the file untouched for manual
                # recovery -- rather than crashing the whole scheduled run
                # over one ticker's corrupted state.
                logger.error("inverse-Martingale ledger unreadable for %s: %s", im_ticker, exc)
                continue
            if im_tracker_state.get("settlement_pending"):
                # The crash-lease reconciliation pass above already had its
                # chance at this ticker and deliberately preserved the lease
                # (still the claiming trading day, an unreachable broker, or a
                # live lease seen from a dry-run invocation). Evaluating a
                # leased cycle is exactly what that reservation exists to
                # prevent, so skip the ticker entirely this run.
                continue
            # Confirmed corporate-action evidence for the durable rearm latch,
            # supplied the same way stddev_reference is: read from the archive
            # here so evaluate_inverse_martingale_step stays a pure function of
            # its inputs. Only meaningful while a latch is actually armed, and
            # only over the window since it was last evaluated -- re-reading the
            # whole history every run would re-apply a split already applied.
            # None (no latch, no window, or an archive that cannot confirm)
            # rebases nothing, which is the fail-closed direction.
            im_split_factor = None
            im_split_cursor_day = None
            im_last_seen_day = im_tracker_state.get("rearm_last_seen_day")
            if im_tracker_state.get("rearm_reference_close") is not None and isinstance(im_last_seen_day, str):
                try:
                    im_split_since = date.fromisoformat(im_last_seen_day)
                except ValueError:
                    im_split_since = None
                if im_split_since is not None:
                    # Prefer the finance provider's same-run daily query.  The
                    # managed CSV archive is maintained by an explicitly
                    # unregistered job, so it is not a live evidence source and
                    # can miss every action after its last manual refresh.  Keep
                    # the archive fallback only for legacy/test providers that
                    # do not expose the new capability; FinanceDataProvider,
                    # used by unattended wiring, always exposes it and fails
                    # closed when its response lacks split metadata.
                    #
                    # The method's mere presence does not prove it can ever
                    # succeed: FinanceDataProvider always defines it regardless
                    # of what its own bars_fn actually returns, so a real,
                    # OHLC-only bars_fn (no split/dividend fields) would fail
                    # closed on every call yet still route through this
                    # stricter branch's archive-freshness requirement below,
                    # instead of the always-available legacy fallback --
                    # potentially holding the latch forever (Codex review:
                    # "Preserve the documented FinanceDataProvider contract").
                    # supports_corporate_actions is the explicit opt-out for
                    # exactly that provider shape; default True preserves
                    # today's documented behavior for providers that were
                    # never told otherwise.
                    live_action_lookup = getattr(finance_data, "get_corporate_action_factor", None)
                    if callable(live_action_lookup) and getattr(
                        finance_data, "supports_corporate_actions", True
                    ):
                        # im_split_since >= trading_day (a later same-day
                        # stream re-evaluating a latch already confirmed
                        # through today by an earlier stream this same
                        # trading day) is the documented already-covered
                        # no-op get_corporate_action_factor itself returns
                        # without ever calling its injected bars_fn -- count
                        # only a genuine external-request attempt, not that
                        # short-circuit, so usage_proxy.finance_calls_attempted
                        # isn't overstated for every such latch (Codex
                        # review: "Count only actual corporate-action
                        # connector attempts").
                        try:
                            im_split_lookup = _validated_live_corporate_action_result(
                                live_action_lookup(im_ticker, im_split_since, trading_day),
                                trading_day,
                            )
                        except (OSError, RuntimeError, TypeError, ValueError, OverflowError):
                            # A custom provider passed directly to
                            # run_daily_compact (not routed through run_dca.py's
                            # frozen persist-before-compute wrapper, which never
                            # reaches this except its own get_corporate_action_
                            # factor implementation's identical internal catch)
                            # can raise a transient connector exception instead
                            # of returning None. Left uncaught, that exception
                            # would escape this per-ticker loop entirely and
                            # abort the whole scheduled batch over one ticker's
                            # evidence lookup, instead of holding only that
                            # ticker's latch the same way every other
                            # "cannot confirm" outcome here already does (Codex
                            # review: "Contain failures from custom action
                            # providers").
                            im_split_lookup = None
                        # Checked AFTER the call, not before: a frozen/replay
                        # provider (run_dca.py's persisted-corporate-action
                        # wrapper) can answer a same-artifacts-directory retry
                        # entirely from an already-saved corporate_action_
                        # SYMBOL.json without ever invoking the live finance
                        # callable. Counting that as a connector attempt just
                        # because im_split_since < trading_day overstates
                        # connector usage on every replay of saved evidence
                        # (Codex review: "Count cached action evidence as zero
                        # connector calls"); a provider with no opinion on
                        # this (the ordinary live path, or any other test/
                        # legacy provider) defaults to "not a cache hit", so
                        # it still counts exactly as before.
                        if im_split_since < trading_day and not getattr(
                            live_action_lookup, "served_from_cache", False
                        ):
                            im_finance_calls_attempted += 1
                        if im_split_lookup is None:
                            # The live query answered "cannot confirm" (e.g. the
                            # current session's daily row is not yet published),
                            # not "no action occurred" -- distinct from the
                            # legacy-provider branch above, this ticker's archive
                            # may still independently hold the same evidence (the
                            # two sources refresh on unrelated schedules), so try
                            # it before giving up entirely. Still None afterward
                            # means neither source can confirm, which stays the
                            # documented fail-closed "rebase nothing" direction
                            # below (Codex review: "Hold the latch when live
                            # action evidence is unavailable").
                            im_split_lookup = archived_split_factor(
                                im_ticker, since=im_split_since, as_of=trading_day
                            )
                            # The archive tolerates up to seven days of
                            # staleness, so a non-None result here does not
                            # by itself confirm today's action window -- only
                            # a cursor that lands exactly on trading_day does
                            # (Codex review: "Require fallback evidence
                            # through the evaluation day"). Anything short of
                            # that is still "cannot confirm today", not "no
                            # action today", so fall through to the same
                            # fail-closed hold below rather than rebasing off
                            # a stale reference.
                            if (
                                im_split_lookup is not None
                                and im_split_lookup[1] != trading_day
                            ):
                                im_split_lookup = None
                    else:
                        im_split_lookup = archived_split_factor(
                            im_ticker, since=im_split_since, as_of=trading_day
                        )
                    if im_split_lookup is None:
                        # Recovery can only be evaluated after the complete
                        # corporate-action window has been established.  A
                        # missing live row and an unavailable/stale archive do
                        # not prove that the stale reference is on today's
                        # price scale; letting evaluation continue could clear
                        # the latch merely because a reverse split lifted the
                        # quote above that reference.  Preserve the ledger
                        # byte-for-byte and retry when either source can cover
                        # the window.
                        logger.warning(
                            "inverse-Martingale corporate-action evidence unavailable for %s; holding rearm latch",
                            im_ticker,
                        )
                        continue
                    im_split_factor, im_split_cursor_day = im_split_lookup
            im_new_state, im_step = evaluate_inverse_martingale_step(
                im_tracker_state,
                decision_price=im_decision_price,
                previous_close=im_previous_close,
                trading_day=trading_day,
                tier_config=im_cfg["tiers"],
                unit_usd=config.inverse_martingale_unit_usd,
                recovery_offset=im_cfg["recovery_offset"],
                max_cycle_days=config.inverse_martingale_max_cycle_days,
                max_fire_attempts=config.inverse_martingale_max_fire_attempts,
                basis=im_cfg["basis"],
                stddev_reference=im_stddev_reference,
                split_factor=im_split_factor,
                split_cursor_day=im_split_cursor_day,
                per_order_cap_usd=config.max_per_order_usd,
                stream=stream,
            )
            im_guarded = (
                guard_active
                and bool(prior_same_day_allocations and prior_same_day_allocations.get(im_ticker) is not None)
            )
            if im_step.fired and im_step.fire_amount_usd > 0 and (im_guarded or im_batch_occupied):
                # This ticker cannot safely carry a fire candidate this run,
                # for one of two independent reasons:
                #   - im_guarded: a prior same-day allocation exists (bought
                #     earlier today by a DIFFERENT stream/entry point) --
                #     _process_buy_candidate would treat it as ticker_guarded
                #     and run the top-up guard's ladder-multiplier-based
                #     delta math against a flat, non-ladder dollar amount,
                #     which that guard was never designed to interpret.
                #   - im_batch_occupied: buy_candidates already carries a
                #     candidate for this ticker THIS run (a normal-ladder
                #     BUY, or a non-BUY credit-ledger flush) --
                #     _process_buy_candidates_batch's outcome tracking is
                #     keyed by ticker, so a second candidate for the same
                #     ticker in the same run would corrupt outcome tracking
                #     for all but the last one.
                # Do NOT claim/persist im_new_state's fire-branch accounting
                # (a reduced accumulated_usd, a settlement_pending lease, or
                # a resolved_marker that collapses the cycle straight to
                # "none") -- the SAME recovery must be re-evaluated fresh,
                # from the unchanged pre-fire balance/status, on a later
                # unblocked run rather than being silently claimed and then
                # never placed.
                #
                # The cycle's AGE must still advance, though. A bare
                # `continue` here (this branch's prior behavior) leaves
                # trading_days_active and last_evaluated_trading_day frozen
                # at whatever they were before this evaluation -- so a
                # ticker that happens to recover into a blocked slot every
                # single session never ages at all, no matter how many real
                # trading sessions pass, and max_cycle_days can never
                # abandon it (Codex review: "Advance cycle age when
                # deferring a guarded recovery"). This mirrors
                # _inverse_martingale_advance_age_for_missing_data's
                # philosophy -- bump only the age fields, touch nothing else
                # -- but starts from im_tracker_state (already read above,
                # no need to re-read the ledger) rather than im_new_state,
                # so none of the fire branch's accounting can leak through:
                # im_new_state's own trading_days_active is absent entirely
                # when the fire fully resolves the cycle (resolved_marker
                # carries no per-cycle fields at all), so it can't be reused
                # here regardless.
                im_prior_trading_days_active = int(im_tracker_state.get("trading_days_active", 0))
                if im_tracker_state.get("last_evaluated_trading_day") != trading_day.isoformat():
                    im_prior_trading_days_active += 1
                im_aged_state = dict(im_tracker_state)
                im_aged_state["trading_days_active"] = im_prior_trading_days_active
                im_aged_state["last_evaluated_trading_day"] = trading_day.isoformat()
                # This is an age-only bump, not a real evaluation by
                # `stream` -- last_evaluated_stream is deliberately left
                # untouched (still whatever a real evaluation last set it
                # to), and last_evaluated_is_real is stamped False so a
                # later same-day evaluation from the stream that ends up
                # matching that stale, carried-forward name isn't misread
                # as a retry of ITS OWN prior (nonexistent) evaluation
                # today. Mirrors _inverse_martingale_advance_age_for_
                # missing_data's identical fix -- see that helper's own
                # docstring and dca_inverse_martingale.py's STATUS_FIRING
                # same-day guard for the full rationale (Codex review:
                # "Mark deferred-fire age updates as non-real").
                im_aged_state["last_evaluated_is_real"] = False
                im_ledger.compare_and_swap_transition(
                    im_ticker,
                    expected_prior_state=im_tracker_state,
                    new_state=im_aged_state,
                    step=InverseMartingaleStep(
                        status_before=im_step.status_before,
                        status_after=im_step.status_before,
                        accumulated_usd_before=im_step.accumulated_usd_before,
                        accumulated_usd_after=im_step.accumulated_usd_before,
                        newly_crossed_tiers=(),
                        fired=False,
                        fire_amount_usd=0.0,
                        reason=(
                            "fire_deferred_same_day_guard" if im_guarded else "fire_deferred_batch_occupied"
                        ),
                    ),
                )
                continue
            if im_step.fired and im_step.fire_amount_usd > 0:
                # Atomically CLAIM this fire (compare-and-swap on the
                # pre-fire state) before doing anything else with it. Two
                # overlapping scheduled-stream processes (a slow/retried
                # earlier slot still running when a later one starts) could
                # otherwise both read the SAME pre-fire tracker state here,
                # both independently decide to fire, and both reach broker
                # placement for the same descent -- neither the ledger's
                # per-write lock alone nor the same-stream duplicate check
                # would catch it, since these candidates are deliberately
                # never ticker_guarded (Codex review: "Reserve each fire
                # atomically before broker placement"). A lost claim means
                # another process already claimed this ticker this run;
                # skip it entirely -- it is that OTHER process's candidate to
                # carry to placement, not lost.
                im_ref_id = (
                    f"{_graded_dca_ref_id_prefix(stream, 'imart')}-"
                    f"{trading_day.isoformat()}-{im_ticker}"
                )
                # Persist a recoverable lease, not the already-debited target
                # state.  A crash before broker submission therefore leaves the
                # entire accumulated balance present ON THE TRACKER ITSELF,
                # while the target and exact broker ref provide enough
                # information for a later invocation to distinguish a submitted
                # order from an abandoned reservation.
                #
                # The pre-fire state is the PRIMARY on-disk state here, not a
                # nested side field, and deliberately so: any reader that does
                # not understand this lease -- the age-only and cleanup helpers,
                # drift detection, an operator inspecting tracker.json -- still
                # sees the real balance. Claiming with the debited target state
                # and stashing the balance in a nested key would make the money
                # read as already spent to every one of them, and would lose it
                # outright if the lease can never be reconciled (an
                # AlpacaBroker-driven roster, or a nested field dropped by a
                # restore). The cost is that the leased status is routinely
                # "dipping"; _validate_tracker_payload accommodates that by
                # requiring a lease to carry its recovery metadata rather than
                # by inferring legitimacy from status alone.
                im_claim_state = dict(im_tracker_state)
                im_claim_state.update(
                    settlement_pending=True,
                    settlement_ref_id=im_ref_id,
                    settlement_trading_day=trading_day.isoformat(),
                    settlement_claimed_usd=im_step.fire_amount_usd,
                    settlement_target_state=im_new_state,
                    # Whether THIS invocation could reach a real broker at all.
                    # A later recovery run reads it to decide whether an absent
                    # order proves anything: a dry-run invocation has no order
                    # history, so it must never release a lease a LIVE run
                    # claimed (Codex review: "Reconcile live leases even when
                    # the recovery run is dry-run").
                    settlement_live=not config.dry_run,
                    # Which roster stream is making this claim. Deployment is
                    # accounted PER STREAM and never conflated (dca_risk.py's
                    # own "Stream hygiene" contract): only scheduled-afternoon
                    # runs are the kill-switch trading stream, and
                    # is_afternoon_scheduled_evidence() explicitly rejects
                    # morning and midday capital. A lease outlives the run that
                    # created it and is routinely recovered by a LATER stream,
                    # which has no other way to know where the money came from
                    # -- so without this the afternoon slot booked a morning
                    # claim's dollars into the afternoon-only trailing-7-day
                    # figure and published its row inside an afternoon artifact,
                    # making every future deployed_by_day() scan count morning
                    # capital as afternoon deployment and spuriously engage the
                    # kill switch (Codex review: "Preserve the claiming stream
                    # when booking recovered spend"). Absent on a legacy lease,
                    # which recovery treats as "provenance unknown".
                    settlement_stream=stream,
                    # Which ACCOUNT this claim is about to submit into, as a
                    # keyed, non-reversible fingerprint. Broker history is
                    # queried per account, so a recovery run pointed at a
                    # different account would search somewhere the order could
                    # never be and read that absence as proof nothing was
                    # submitted -- releasing a balance whose order sits in the
                    # original account (Codex review: "Verify the claiming
                    # broker account before releasing a lease"). Recorded only
                    # for a LIVE claim: a dry-run claim submits nothing, so
                    # there is no account for it to be found in and pinning one
                    # would only freeze the lease if the value later changed.
                    # A live claim ALWAYS records the field, falling back to the
                    # explicit "unknown" sentinel when the identity cannot be
                    # computed -- persisting None there would look exactly like
                    # a legacy lease and be exempted from account matching, so a
                    # later run on a different account could release it on that
                    # account's empty history.
                    settlement_account=(
                        None
                        if config.dry_run
                        else (
                            _broker_account_fingerprint(broker, im_ledger.root.parent)
                            or _LEASE_ACCOUNT_UNKNOWN
                        )
                    ),
                )
                if not im_ledger.claim_fire(
                    im_ticker,
                    expected_prior_state=im_tracker_state,
                    new_state=im_claim_state,
                    step=im_step,
                ):
                    continue
                # Full settlement (confirming, adjusting, or rolling back the
                # claim) is DEFERRED until the real placement outcome is
                # known -- see the block below, after
                # _process_buy_candidates_batch runs. The claim above already
                # reserved the ticker (preventing a concurrent duplicate
                # claim); it does not yet know whether THIS run's own
                # placement will actually succeed.
                # im_tracker_state (the PRE-claim, pre-fire persisted state)
                # is carried forward alongside im_new_state so the deferred
                # settlement can rebuild a correct continuation/rollback
                # state even when im_new_state is the minimal post-full-fire
                # marker (see dca_inverse_martingale.resolved_marker) -- that
                # marker deliberately carries no per-cycle fields
                # (cycle_reference_close, stddev_reference,
                # crossed_tier_thresholds), so building a partial-fire
                # continuation FROM it would silently drop the frozen sigma
                # reference a stddev-basis cycle needs on its next
                # evaluation (Codex review: "Retain the frozen sigma in
                # partial-fire state").
                im_pending_fires[im_ticker] = (im_tracker_state, im_claim_state, im_step)
                # Hoisted OUT of the replace(...) call below, where a later
                # type-safety pass had placed it between keyword arguments --
                # a statement cannot appear inside a call's argument list, and
                # the module failed to import at all. _inverse_martingale_
                # reconciled_price() above already required both sources
                # present, error-free and in agreement, so finance_signal is
                # guaranteed non-None here; raising explicitly (rather than
                # asserting, which -O strips) keeps that guarantee enforced
                # in every build.
                finance_signal = im_signal.finance_signal
                if finance_signal is None:
                    raise RuntimeError("inverse_martingale_fire requires a finance signal")
                fire_decision = replace(
                    im_signal,
                    action=Action.BUY,
                    reason="inverse_martingale_fire",
                    buy_multiplier=0.0,
                    # Enrollment forces every source signal for this ticker
                    # to a non-BUY action (buy_multiplier=0.0), so
                    # reconcile_signals() never took the Action.BUY branch
                    # that would have populated target_price/target_price_
                    # source/target_quote_time/decision_bar_close via
                    # _target_fields() -- im_signal's own copies of these
                    # fields are still ReconciledDecision's bare defaults
                    # (target_price=0.0, target_price_source="", etc.).
                    # Left unset, every filled inverse-Martingale order is
                    # logged against a $0 target: build_execution_record()'s
                    # `if target_price:` guard skips slippage_pct entirely,
                    # and downstream execution-quality classification reads
                    # the same zero target, corrupting the execution-quality
                    # artifacts for every synthetic fire (Codex review:
                    # "Populate execution targets on synthetic fire
                    # decisions"). im_signal.finance_signal is guaranteed
                    # present and verified here -- _inverse_martingale_
                    # reconciled_price() above already required both
                    # sources present, error-free, and in agreement before
                    # this branch could ever be reached -- so it's safe to
                    # source the target fields from it directly, matching
                    # reconcile_signals()'s own finance-preferred convention.
                    **_target_fields(finance_signal),
                    # evaluate_inverse_martingale_step() itself already floors
                    # fire_amount_usd to the broker minimum (Codex review:
                    # "Keep sub-dollar fires in the accumulator" -- the floor
                    # used to live only here, understating what the ledger
                    # actually claimed/settled against relative to what was
                    # really submitted). This max() is now pure defense in
                    # depth against that invariant, not the primary floor.
                    suggested_amount_usd=max(1.0, im_step.fire_amount_usd),
                    # The kill-switch cap in _process_buy_candidate clamps
                    # order_amount to THIS field when the risk guard is
                    # engaged -- setting it to the full fire amount would make
                    # that cap a complete no-op for these synthetic
                    # candidates. Use the accumulator's own per-unit base
                    # instead (also floored at $1 for the same broker-minimum
                    # reason above), so an engaged kill switch still caps a
                    # fire down to the base amount, exactly as it does for a
                    # normal ladder buy (Codex review: "Preserve the
                    # kill-switch cap for synthetic fires").
                    selected_base_amount_usd=max(1.0, config.inverse_martingale_unit_usd),
                    synthetic_source="inverse_martingale",
                )
                buy_candidates.append(fire_decision)
                already_included.add(im_ticker)
                # Replace this ticker's entry in decisions_by_ticker (and,
                # after the loop, in `decisions` itself -- the SAME list
                # object run_result.decisions already references) with the
                # synthetic fire decision. Without this, _build_buy_candidates
                # and the signals.csv auto_buy_signal reconciliation both
                # read the ORIGINAL pre-fire decision (non-BUY, enrollment's
                # forced buy_multiplier=0.0) for this ticker even though
                # candidate_outcomes now shows a real submitted order for
                # it -- misclassifying a genuine inverse-Martingale fire as
                # a pending-credit flush, with the wrong reason/multiplier,
                # and leaving both source signal rows' auto_buy_signal at
                # False (Codex review: "Preserve the synthetic fire decision
                # in run artifacts").
                decisions_by_ticker[im_ticker] = fire_decision
            else:
                # Not a fire this run (tier crossed, awaiting recovery, or a
                # cycle abandoned by max_cycle_days/max_fire_attempts). Write
                # via the SAME compare-and-swap the fire branch above uses,
                # not an unconditional record_step() -- two overlapping
                # processes evaluating the same ticker from the same
                # snapshot but different prices could otherwise have one
                # successfully claim_fire() a real order while the other,
                # slightly slower to reach this else branch, unconditionally
                # overwrites that claim with its own (now-stale) non-fire
                # state. The fire would still be submitted, but its later
                # settlement CAS would then fail against this overwritten
                # state, stranding the already-spent balance in the ledger
                # to be fired again later (Codex review: "Compare-and-swap
                # every accumulator transition"). A lost CAS here means
                # another process already advanced this ticker past the
                # state this evaluation started from; skip writing rather
                # than clobber it -- the ticker is re-evaluated fresh from
                # whatever that other process left on a later run.
                im_ledger.compare_and_swap_transition(
                    im_ticker,
                    expected_prior_state=im_tracker_state,
                    new_state=im_new_state,
                    step=im_step,
                )
        buy_candidates.sort(key=allocation_sort_key)
        # decisions_by_ticker preserves the original per-ticker key order
        # from decisions (dict reassignment does not move an existing key),
        # so this rebuild in place keeps `decisions` -- and, since
        # run_result.decisions was assigned by reference to this SAME list
        # object earlier in this function, run_result.decisions too --
        # correctly reflecting any tickers this block replaced with a
        # synthetic fire decision.
        decisions[:] = list(decisions_by_ticker.values())

    # ⚡ Bolt Optimization: Use a single pass loop instead of multiple sum() generators
    # to eliminate O(N) object overhead when iterating DataFrames/lists.
    #
    # planned_spend feeds tier selection (config/budgets.json budget_tiers),
    # which sets the day's daily/weekly cap ceiling -- so it must reflect what
    # the batch will actually try to spend, not each candidate's full
    # first-allocation desired amount. A repeat same-day buy is capped by the
    # same-day top-up guard to max(0, desired - prior), often to $0; summing
    # the pre-guard desired amounts instead can select a materially higher
    # tier (e.g. Elevated $240 instead of Normal $180) from spend that the
    # guard was always going to shrink, authorizing real daily cap headroom
    # the actionable plan never needed (Codex review: "Select the tier after
    # applying top-up deltas"). evaluate_top_up_guard is a pure computation
    # (no broker/state I/O); redoing it here to estimate each candidate's
    # incremental amount is safe -- _process_buy_candidate below makes the
    # real, authoritative per-candidate decision once the broker's own
    # same-day exposure and duplicate checks are available. This estimate
    # only feeds tier selection, never a placed order.
    planned_spend = 0.0
    high_multiplier_signals = 0
    for d in buy_candidates:
        if d.ticker in config.whole_share_tickers:
            # A whole-share candidate's own suggested_amount_usd is just
            # TODAY's contribution, not what this run will actually try to
            # spend: below the share threshold it spends $0 (accumulates
            # instead), and once the accumulated total crosses a share's
            # price, execution attempts the full share-multiple
            # order_notional_usd -- which can be many times today's single
            # contribution. Preview the SAME read-only accumulator math the
            # dry-run branch uses (WholeShareAccumulationLedger.pending_usd
            # + apply_contribution) so tier selection reflects what will
            # actually be attempted rather than the day's raw contribution
            # (Codex review: "Preview accumulated notional before selecting
            # the budget tier"). Purely a read, makes no ledger writes.
            #
            # For a genuine, fresh Action.BUY decision with both sources
            # present (a synthetic redispatch decision stays NO_ACTION, so
            # this never re-triggers for one -- its target_price is already
            # the reconciled price the redispatch loop above computed),
            # reconcile the execution price the SAME way
            # _process_whole_share_candidate now does before sizing: without
            # this, a preview using the unreconciled winning-signal quote
            # could disagree with what execution actually attempts whenever
            # the two sources' quotes are close but not identical (e.g.
            # Finance $9.90 vs. Robinhood $10.09) -- understating planned
            # spend near a budget-tier threshold and selecting a cap below
            # what the run will really need (Codex review: "Reconcile the
            # tier-planning whole-share price"). A disagreement (or either
            # source unusable) reconciles to None here exactly like
            # execution's own block -- treated as a $0 preview contribution,
            # matching what execution would actually do.
            if (
                d.action == Action.BUY
                and d.finance_signal is not None
                and d.robinhood_signal is not None
            ):
                current_share_price = _whole_share_redispatch_reconciled_price(d) or 0.0
            else:
                current_share_price = d.target_price or d.decision_bar_close
            if current_share_price > 0:
                # Preview the SAME kill-switch-capped contribution
                # _process_whole_share_candidate actually applies (see that
                # function's own kill-switch cap) -- previewing the full,
                # uncapped suggested_amount_usd while execution caps it to
                # selected_base_amount_usd overstates planned spend and can
                # select a needlessly high tier (Codex review: "Preview the
                # kill-switch-capped contribution"). Uses config's own
                # pre-batch deployed_last_7d_usd, matching this loop's
                # existing planning-estimate precedent (evaluate_top_up_guard
                # above is likewise an approximation, not the authoritative
                # per-candidate decision _process_buy_candidate(s) make later).
                preview_contribution_usd = d.suggested_amount_usd
                preview_kill_switch_active = kill_switch_engaged(config)
                if preview_kill_switch_active:
                    preview_contribution_usd = min(preview_contribution_usd, d.selected_base_amount_usd)
                try:
                    whole_share_ledger = WholeShareAccumulationLedger()
                    whole_share_idempotency_key = f"{stream}-{d.ticker}"
                    whole_share_recorded_at = now.isoformat()
                    # A same-day retry (e.g. a scheduler re-invocation) that
                    # already called record_contribution() for THIS slot is
                    # idempotent per (trading_day, idempotency_key) -- but
                    # what the real call returns for an already-recorded slot
                    # depends on ITS state, not just "already recorded":
                    # resolved (settled/preserved) or still within its claim
                    # window both return zero shares regardless of the
                    # CURRENT pending balance (recomputing via
                    # apply_contribution(pending, 0, price) instead would
                    # preview a phantom order if a LATER preserve_pending()
                    # restored a balance now big enough to cover a share on
                    # its own -- Codex review: "Mirror cached ledger outcomes
                    # in tier previews"). But an UNRESOLVED, STALE entry is
                    # actionable: a real call right now would RECLAIM it and
                    # return its cached POSITIVE decision, so treating this
                    # as a flat $0 would understate what this retry will
                    # actually attempt (Codex review: "Account for actionable
                    # stale claims in tier planning"). cached_fire_decision
                    # returns the exact decision a real call would produce
                    # for any of these already-recorded cases; None means the
                    # slot was never recorded, so the normal preview applies.
                    cached_decision = whole_share_ledger.cached_fire_decision(
                        d.ticker,
                        trading_day.isoformat(),
                        whole_share_idempotency_key,
                        whole_share_recorded_at,
                        current_share_price,
                        preview_contribution_usd,
                    )
                    if cached_decision is not None:
                        preview = cached_decision
                    else:
                        pending_before = whole_share_ledger.pending_usd(d.ticker)
                        preview = apply_contribution(pending_before, preview_contribution_usd, current_share_price)
                    # Clamp to what execution could actually spend: _whole_share_risk_gates'
                    # max_per_order_usd ceiling (execution never places more than that in
                    # one run, however large the accumulated balance) -- without this, a
                    # large preserved/accumulated balance could preview a notional far
                    # above what the whole-share path will ever actually submit, pushing
                    # tier selection (and the daily/weekly cap it sets for UNRELATED
                    # orders) higher than the real plan justifies (Codex review: "Clamp
                    # whole-share previews to executable notional"). Uses
                    # preview.current_share_price_usd -- apply_contribution's OWN
                    # cent-rounded price -- not the raw current_share_price, so this
                    # ceiling clamp matches the SAME rounded price execution actually
                    # clamps with (Codex review: "Use the ledger-rounded price in tier
                    # planning"); at a fractional-cent price the two can disagree on
                    # how many shares fit under the ceiling and pick the wrong tier.
                    #
                    # When the kill switch is engaged, execution's
                    # _whole_share_risk_gates call additionally clamps against
                    # decision.selected_base_amount_usd (0.0 for a redispatched
                    # NO_ACTION decision, since only a fresh BUY sets it) via
                    # ceiling_override_usd (Codex review: "Apply the kill switch
                    # to the executable whole-share fire") -- this preview must
                    # use the SAME effective ceiling, or it can preview up to the
                    # full max_per_order_usd while execution actually clamps or
                    # blocks at $0-$2, overstating planned spend enough to select
                    # a needlessly high budget tier near a threshold and
                    # authorize unrelated orders the real, capped whole-share
                    # spend never justifies (Codex review: "Apply the
                    # kill-switch ceiling in tier planning").
                    # THE SAME function execution uses, not a parallel copy of
                    # its arithmetic: this preview exists to predict exactly
                    # what execution will spend, and every time the two were
                    # computed separately they drifted (the kill-switch clamp,
                    # then the single-share allowance -- see
                    # _whole_share_executable_share_count's own docstring).
                    max_shares_by_ceiling, _preview_ceiling_usd, _ = (
                        _whole_share_executable_share_count(
                            config,
                            preview.current_share_price_usd,
                            ceiling_override_usd=(
                                d.selected_base_amount_usd if preview_kill_switch_active else None
                            ),
                        )
                    )
                    preview_notional = min(
                        preview.order_notional_usd,
                        max_shares_by_ceiling * preview.current_share_price_usd,
                    )
                    planned_spend += round(preview_notional, 2)
                except Exception as exc:  # noqa: BLE001 - a corrupt/unreadable/locked
                    # BYDDY ledger must not abort tier planning for every OTHER,
                    # independent active-ticker candidate in this batch;
                    # _process_whole_share_candidate has its own identical
                    # ledger-error handling (blocks with MISSING_FILL_DATA_ERROR) for
                    # the real, authoritative decision, so treating this PREVIEW as a
                    # $0 planned-spend contribution here is consistent with what
                    # execution will actually do (Codex review: "Isolate ledger
                    # preview failures to the whole-share ticker").
                    logger.warning(
                        "whole-share tier-planning preview failed for %s: %s", d.ticker, exc
                    )
            if d.ladder_multiplier >= config.high_multiplier_threshold:
                high_multiplier_signals += 1
            continue
        if guard_active:
            prior = prior_same_day_allocations.get(d.ticker) if prior_same_day_allocations is not None else None
            # Carry each candidate's enumerated pending balance (including a
            # flush-only candidate appended above solely because it has a
            # pending credit, whose own suggested_amount_usd/action never
            # reflects that balance) into the estimate so a recovered pending
            # credit that would round up to a real $1 order at execution time
            # is not silently estimated at $0 for tier selection (Codex
            # review: "Include pending flushes in planned spend"). Restricted
            # to the afternoon stream, matching the same restriction on
            # _process_buy_candidate's own read below and the flush-injection
            # block above: pending_by_ticker is populated for every scheduled
            # stream (it feeds this same estimate), but folding it into a
            # 10:30/12:30 tier estimate would apply final-session sizing to a
            # remainder that has not reached its final session yet (Codex
            # review discussion on commit f46f29c: "Restrict per-candidate
            # credit resolution to the afternoon").
            existing_pending_credit_usd = (
                pending_by_ticker.get(d.ticker, 0.0) if stream == "afternoon" else 0.0
            )
            planned_spend += evaluate_top_up_guard(
                d, prior, config, existing_pending_credit_usd=existing_pending_credit_usd
            ).incremental_order_amount
        else:
            planned_spend += d.suggested_amount_usd
        # ladder_multiplier, not buy_multiplier -- see the identical
        # comment on the other high_multiplier_threshold count above.
        if d.ladder_multiplier >= config.high_multiplier_threshold:
            high_multiplier_signals += 1

    state.select_daily_budget(planned_spend, high_multiplier_signals, config)
    # Roll the reserve forward now, before any budget query or day finalization,
    # so a quiet week (no BUY candidates) still carries prior unused Normal-cap
    # capacity into the stress tier's ceiling.
    state.roll_weekly_reserve(trading_day, config)

    # Everything above this line is evaluation the run COMPLETED. Published now
    # so a later failure -- an unresolved-placement halt above all, which by
    # definition happens at the broker boundary and not before it -- writes an
    # artifact carrying the real signal rows, candidate count and budget caps
    # rather than a stub asserting nothing was evaluated.
    _publish_in_flight_evaluation(
        decisions=decisions,
        config=config,
        state=state,
        trading_day=trading_day,
        planned_spend=planned_spend,
        high_multiplier_signals=high_multiplier_signals,
        errors_count=errors_count,
    )

    # Snapshotted BEFORE _seed_prior_allocations folds TODAY's own same-day
    # cross-stream context into the same weekly bucket -- reconcile_earlier_
    # week_cross_stream_notional's first-reconciliation-this-week baseline
    # must reflect only what predates today's own seeding, or it mistakes
    # today's spend for already-accounted earlier-week spend and silently
    # drops the real earlier-week delta (Codex review: "Exclude today's
    # allocations from the prior-week baseline").
    pre_same_day_seed_week_notional = state.week_notional(trading_day)
    _seed_prior_allocations(
        state,
        trading_day,
        guard_active,
        prior_same_day_allocations,
        one_order_per_ticker_per_day=config.one_order_per_ticker_per_day,
    )
    if guard_active:
        # Earlier-weekday cross-stream spend (Codex review: "Include
        # prior-week sibling spend in the afternoon ledger") -- computed by
        # the caller (run_dca._compute_earlier_week_cross_stream_notional)
        # since it needs config_dir/artifacts_dir to resolve cross-stream
        # roots, which this function does not receive. Reconciled into the
        # shared weekly bucket ONLY (decoupled from any specific ticker's
        # same-day top-up reference), adding only what isn't already
        # reflected in this persistent state's own history (Codex review:
        # "Reconcile earlier-week spend instead of adding it" -- a bare
        # bump_week_notional_only call here re-added the same earlier-week
        # total on every invocation this week, double-counting spend this
        # state's own earlier record_buy() calls already persisted).
        if earlier_week_scan_had_failures:
            state.force_week_notional_to_worst_case_ceiling(trading_day)
        else:
            state.reconcile_earlier_week_cross_stream_notional(
                trading_day,
                earlier_week_notional_usd,
                pre_same_day_seed_week_notional=pre_same_day_seed_week_notional,
            )

    # Publish a candidate outcome for every crash lease reconciled to a REAL
    # broker order placed TODAY. Its capital is already booked into the budget
    # counters above, but without an outcome row the recovered purchase is
    # missing from buy_candidates.csv, orders_placed_count and the run audit
    # entirely -- the run would report having placed nothing while a real order
    # exists (Codex review: "Book recovered broker orders into the strategy
    # budget").
    #
    # Computed and published into the batch's OWN seed dict, before
    # _process_buy_candidates_batch runs, rather than merged in afterward. A
    # later candidate in the batch can raise before returning, and the earlier
    # afterward-merge point would then never be reached at all -- silently
    # dropping an already-reconciled, already-lease-cleared recovery from the
    # failure artifact, with no way for a later retry to reconstruct it from a
    # stale one (Codex review: "Publish recovered outcomes before processing
    # new candidates"). Stored under a synthetic key (below), so seeding this
    # cannot collide with any outcome the batch itself produces for the same
    # ticker.
    #
    # Scoped to a claim day equal to THIS trading day. A run_state artifact
    # carries one top-level trading day and its candidate rows carry no claim
    # day of their own, so load_prior_same_day_allocations reads every submitted
    # row in it as an allocation made TODAY. Emitting a prior-day recovery here
    # would therefore charge yesterday's order against today's per-ticker and
    # per-day caps in every later slot, and present it to the top-up guard as
    # today's same-ticker allocation -- suppressing a legitimate buy (Codex
    # review: "Keep prior-day recoveries out of today's submission context").
    # A prior-day recovery is not unaudited: claim_fire() has already written a
    # durable step event for it in the accumulator ledger's own audit log, with
    # the reconciled dollar amount and the claim day it belongs to, which is the
    # record that correctly carries the older date.
    recovered_fire_outcomes: Dict[str, Dict[str, Any]] = {}
    # Seeded with whatever the startup reconciliation pass already resolved
    # for TODAY (an earlier trading day's reconciliation is booked into
    # ctx.state/its own artifact only, never surfaced here -- see that
    # function's own docstring). Without this the fresh run_state.json this
    # invocation is about to build has no idea the ticker was ever bought
    # (Codex review, PR #911: "Publish recovered submissions into the fresh
    # run artifacts").
    recovered_fire_outcomes.update(fractional_recovery_outcomes)
    for im_recovery_lookup_key, im_recovery in im_lease_recoveries.items():
        # Gated on order_id, NOT on the notional. A matched TERMINAL ZERO-FILL
        # recovery carries $0 but a real order DID reach the broker, and
        # config/budgets.json counts a cancelled or rejected buy as an attempt
        # against the roster-wide max_orders_per_day. The in-memory
        # record_buy(..., 0.0) above only protects THIS invocation: every later
        # roster slot reconstructs that shared attempt count from artifact rows,
        # so filtering the row out here let a genuine broker attempt vanish from
        # the record and granted a later slot an extra order (Codex review:
        # "Persist recovered zero-fill attempts in artifacts"). Only a RELEASED
        # lease -- no order, no attempt -- has nothing to audit.
        if im_recovery.order_id is None:
            continue
        if im_recovery.claim_trading_day != trading_day:
            logger.info(
                "inverse-Martingale lease for %s reconciled $%.2f from %s; booked to that day's "
                "budget and recorded in the accumulator audit log, not today's candidates",
                im_recovery.ticker,
                im_recovery.recovered_amount_usd,
                im_recovery.claim_trading_day.isoformat(),
            )
            continue
        # Scoped to a claim made by THIS stream, for the same reason the claim
        # DAY is scoped just above: a run_state artifact carries one stream and
        # its candidate rows carry no stream of their own, so every row inside
        # it is read as this stream's deployment. Publishing a morning claim's
        # recovery into an afternoon artifact therefore makes every future
        # deployed_by_day() scan count morning capital as afternoon deployment
        # -- exactly the conflation dca_risk's "Stream hygiene" contract and
        # is_afternoon_scheduled_evidence() exist to prevent -- inflating the
        # kill-switch total permanently, since the artifact is durable (Codex
        # review: "Preserve the claiming stream when booking recovered spend").
        # A legacy lease carrying no stream is treated the same way: unknown
        # provenance must not be silently attributed to this stream.
        #
        # The cost is that a cross-stream recovery's ATTEMPT is not in this
        # run's artifact, which is the accounting the sibling zero-fill fix
        # above exists to preserve. It is the lesser error: an attempt missing
        # from one artifact is recoverable from the accumulator ledger's own
        # durable audit log (claim_fire() wrote a step event carrying the
        # amount, the claim day and the stream), whereas capital misfiled into
        # the wrong risk stream corrupts the kill switch for seven days with no
        # way for a later reader to tell it apart from real afternoon
        # deployment. Recorded in docs/inverse_martingale.md's "Remaining
        # limitations".
        if im_recovery.claim_stream != stream:
            logger.info(
                "inverse-Martingale lease for %s was claimed by the %s stream and reconciled by %s; "
                "booked to the shared budget and recorded in the accumulator audit log, "
                "not published into this stream's artifact",
                im_recovery.ticker,
                im_recovery.claim_stream or "unknown",
                stream,
            )
            continue
        # `im_recovery_already_on_disk` (checked further below, and consulted
        # here too) answers "is this order recorded on disk ANYWHERE" --
        # true for a genuine same-slot retry (an earlier failed attempt at
        # THIS exact artifacts_dir), but also true when the on-disk copy is
        # a SIBLING stream's or an earlier day's own artifact entirely.
        # Appending an execution record below is a same-file UPGRADE in the
        # first case, but a cross-file DUPLICATE in the second -- a second
        # orders.csv, in a different directory, would then claim the same
        # fill, inflating filled-order/slippage reporting wherever both get
        # aggregated (Codex review: "Skip current-run logging for
        # recoveries already on disk"). Narrowed to THIS directory
        # specifically, not "any disk record", before deciding to log.
        im_recovery_on_disk_here = im_recovery_already_on_disk.get(
            im_recovery_lookup_key
        ) and _order_recorded_in_this_artifacts_dir(
            {im_recovery.order_id or "", im_recovery.claim_ref or ""}, artifacts_dir
        )
        if run_result is not None and (
            not im_recovery_already_on_disk.get(im_recovery_lookup_key) or im_recovery_on_disk_here
        ):
            # Built and appended for EVERY same-day, same-stream recovery
            # with a real order_id -- including one already-on-disk IN THIS
            # SAME DIRECTORY for BOOKING purposes (checked further below).
            # An earlier crashed attempt could only log this order as
            # "submitted" before dying;
            # _merge_execution_csv's order-id match upgrades that existing
            # row to "filled" once broker history confirms it here, rather
            # than leaving it permanently wrong (Codex review: "Upgrade
            # persisted submissions when recovery confirms a fill"). Placed
            # here -- after the day/stream checks, before the on-disk one --
            # so it never fires for a cross-day/cross-stream recovery, whose
            # order belongs to a DIFFERENT artifacts_dir's own orders.csv;
            # appending it to THIS run's execution_records would misattribute
            # it to this run's file instead.
            #
            # run_daily_compact()/write_execution_csv write orders.csv solely
            # from run_result.execution_records, never from buy_candidates.csv
            # -- so without a row here a recovered fire is visible in
            # buy_candidates.csv/submitted_orders.csv but silently absent from
            # the durable fill/slippage log, undercounting execution reporting
            # for a real order the broker actually filled (Codex review:
            # "Record recovered fills in the execution log"). Built directly
            # via build_execution_record rather than _log_execution: there is
            # no ReconciledDecision for this recovery (the ticker may have
            # been un-enrolled or dropped from config.tickers since the
            # crash), so target_price/decision_bar_close are left at 0.0 --
            # exactly like the synthesized buy_candidates.csv row above --
            # and build_execution_record's own `if target_price:` guard skips
            # slippage_pct for a zero target instead of dividing by it.
            # Wrapped in try/except: this lookup runs AFTER
            # _inverse_martingale_recover_pending_lease() has already
            # claim_fire()'d the lease durably clear. If get_order_fill()
            # itself raised here (e.g. a transient broker-adapter outage)
            # unguarded, the exception would propagate out of this whole
            # publish loop before the recovered outcome/execution record
            # below is appended -- losing the recovered fill with no lease
            # left to retry it from (Codex review: "Isolate the optional
            # fill lookup from recovery settlement"). Falling back to the
            # fill data already retained on im_recovery keeps this lookup
            # purely optional, exactly as its result is already treated
            # below.
            im_recovery_get_fill = getattr(broker, "get_order_fill", None)
            try:
                im_recovery_fill = (
                    im_recovery_get_fill(im_recovery.order_id)
                    if callable(im_recovery_get_fill)
                    else None
                )
            except Exception:
                im_recovery_fill = None
            if not isinstance(im_recovery_fill, OrderFill):
                im_recovery_fill = None
            # Gated on recovered_amount_usd > 0, the authoritative answer
            # _recovered_broker_notional already computed for this exact
            # order: a $0 recovery (a confirmed terminal zero-fill) must
            # never carry ANY fill price/quantity, regardless of what a
            # separate get_order_fill() lookup reports. That second,
            # independent call can itself synthesize a fake fill for a
            # cancelled order from its plain (REQUESTED, not executed)
            # quantity field -- belt-and-suspenders here in case that bug
            # class recurs there too (Codex review: "Do not turn confirmed
            # zero-fill orders into fills").
            if im_recovery.recovered_amount_usd > 0:
                # Price/quantity prefer im_recovery's OWN retained values --
                # read from the same broker history lookup that already
                # established this as a TERMINAL fill -- over a fresh
                # get_order_fill() call. That second, independent call can
                # be eventually consistent: it can return a real OrderFill
                # (not None) that still reflects an earlier PARTIAL fill,
                # not yet caught up to the terminal quantity the history
                # lookup already confirmed. Falling back to it only when the
                # retained value is None -- rather than preferring it
                # outright -- previously let that stale partial win, and
                # _merge_execution_csv() can never upgrade an existing row
                # when both attempts report the same smaller quantity
                # (Codex review: "Prefer the terminal recovery quantity over
                # the follow-up lookup"). get_order_fill is still consulted
                # for the two timestamp fields, which the retained history
                # values never carry.
                # The get_order_fill() fallback only fires when the history
                # lookup retained SOME granular breakdown (fill_price and
                # fill_quantity are always set together -- see the
                # _price/_qty pairing in
                # _inverse_martingale_recover_pending_lease). When BOTH are
                # None, this recovery was valued only through
                # executed_notional (a supported terminal row with no
                # separate price/quantity at all) -- there is no terminal
                # granular result for the follow-up lookup to "fill in", so
                # accepting its value here would silently substitute a
                # possibly-stale/partial fill for the authoritative
                # notional_usd force_filled already carries: filled = (both
                # fields present) becomes True, and build_report() then uses
                # avg_fill_price * quantity_filled instead of falling back to
                # notional_usd, underreporting the recovery (Codex review:
                # "Preserve terminal notional over a stale fill lookup").
                im_recovery_had_granular_history = (
                    im_recovery.fill_price is not None or im_recovery.fill_quantity is not None
                )
                im_recovery_avg_fill_price = im_recovery.fill_price
                if (
                    im_recovery_avg_fill_price is None
                    and im_recovery_had_granular_history
                    and im_recovery_fill
                ):
                    im_recovery_avg_fill_price = im_recovery_fill.avg_fill_price
                im_recovery_quantity_filled = im_recovery.fill_quantity
                if (
                    im_recovery_quantity_filled is None
                    and im_recovery_had_granular_history
                    and im_recovery_fill
                ):
                    im_recovery_quantity_filled = im_recovery_fill.quantity_filled
            else:
                im_recovery_avg_fill_price = None
                im_recovery_quantity_filled = None
            # im_recovery itself (the terminal history result) carries no
            # timestamps of its own -- only the optional get_order_fill()
            # lookup does. That lookup can be eventually consistent and
            # still return an EARLIER PARTIAL fill even though its price/
            # quantity were already correctly rejected above in favor of the
            # terminal values. Copying its timestamps unconditionally then
            # stamped the partial transaction's submit/fill time onto the
            # terminal execution record, corrupting
            # build_execution_record()'s latency_seconds for a fill it never
            # actually timed (Codex review: "Reject stale partial
            # timestamps during terminal recovery"). Accepted only when the
            # lookup's own quantity agrees with whichever quantity this
            # record is actually reporting -- including the notional-only
            # case (im_recovery_quantity_filled is None), where nothing
            # granular was used at all, so a lookup quantity of 0/None is
            # the only "agreement" possible -- NOT "accept anything", which
            # the prior `is None` branch here mistakenly did: a notional-only
            # recovery has no quantity of its own to compare against, but an
            # eventually-consistent follow-up lookup can still return a real
            # POSITIVE-quantity partial fill for the same order. Requiring
            # the lookup's own quantity to be equally absent (Codex review:
            # "Reject partial timestamps for notional-only recoveries")
            # closes that gap instead of accepting it unconditionally.
            im_recovery_order_submitted_at = None
            im_recovery_order_filled_at = None
            if im_recovery_fill is not None and (
                (im_recovery_quantity_filled is None and not im_recovery_fill.quantity_filled)
                or im_recovery_fill.quantity_filled == im_recovery_quantity_filled
            ):
                im_recovery_order_submitted_at = im_recovery_fill.order_submitted_at
                im_recovery_order_filled_at = im_recovery_fill.order_filled_at
            run_result.execution_records.append(
                build_execution_record(
                    ticker=im_recovery.ticker,
                    target_price=0.0,
                    target_price_source="",
                    decision_bar_close=0.0,
                    notional_usd=im_recovery.recovered_amount_usd,
                    action_reason="recovered_inverse_martingale_lease",
                    order_id=im_recovery.order_id,
                    order_submitted_at=im_recovery_order_submitted_at,
                    order_filled_at=im_recovery_order_filled_at,
                    avg_fill_price=im_recovery_avg_fill_price,
                    quantity_filled=im_recovery_quantity_filled,
                    # A confirmed positive recovered notional IS a fill, even
                    # when neither get_order_fill() nor the retained history
                    # values could supply a price/quantity breakdown (e.g. a
                    # terminal row valued only through executed_notional --
                    # see _recovered_broker_notional's own docstring). Without
                    # this, such a recovery was recorded "submitted" despite
                    # being broker-confirmed, undercounting
                    # filled_order_count/total_filled_notional (Codex review:
                    # "Mark executed-notional recoveries as filled").
                    force_filled=im_recovery.recovered_amount_usd > 0,
                )
            )
        # Already audited by the crashed worker itself. `im_already_on_disk`
        # keeps this order out of StrategyState and the runtime seven-day
        # total, but publishing the row anyway put a SECOND artifact carrying
        # the same broker order on disk, and dca_risk.deployed_by_day sums
        # deployed_usd(state) per artifact with no order-level deduplication --
        # so the next invocation counted that one order twice against the
        # kill-switch threshold and could suppress valid later purchases
        # (Codex review: "Avoid republishing recovery spend already on disk").
        # The original artifact is the authoritative record; this run adds
        # nothing further to it -- except the execution-record upgrade just
        # above, which is about correcting THIS order's own row, not about
        # attributing new capital to it.
        #
        # UNLESS the "original artifact" IS this run's own artifacts_dir
        # (im_recovery_on_disk_here): run_once() is about to overwrite THIS
        # directory's own run_state.json with a fresh one, so skipping the
        # rebooking here does not avoid a double count -- it silently drops
        # the recovery from the new state entirely, even though its
        # execution-record upgrade just above already made it into the new
        # orders.csv. dca_risk.deployed_usd() derives deployed capital from
        # buy_candidates/candidate_outcomes, not from orders.csv, so the real
        # fill goes uncounted against the kill-switch threshold from the
        # moment the state is overwritten (Codex review: "Republish
        # recoveries before overwriting their owning state").
        if im_recovery_already_on_disk.get(im_recovery_lookup_key) and not im_recovery_on_disk_here:
            logger.info(
                "inverse-Martingale lease for %s reconciled an order already recorded on disk; "
                "not republishing it in this run's candidates",
                im_recovery.ticker,
            )
            continue
        # Stored under a SYNTHETIC key, not the plain ticker. candidate_outcomes
        # is keyed by ticker and holds one entry each, so keying a recovery by
        # its ticker made the two events collide: a run where the ticker also
        # produced an ordinary candidate (reachable once enrollment is disabled
        # after the crash) silently dropped one of them, and the artifact then
        # under-reported real capital to every later same-day and
        # deployment-history reader (Codex review: "Preserve recovery rows
        # alongside current ticker outcomes"). A recovery is a distinct event
        # from anything this run placed, so it gets its own entry.
        #
        # Safe against every consumer: the ticker-keyed lookups
        # (`candidate_outcomes.get(decision.ticker)`, and deferred settlement's
        # own `.get(im_ticker)`) can never resolve this key, while the
        # `.values()` sweeps that matter -- orders_placed_count in particular --
        # still see it. "#" cannot appear in a real symbol.
        recovered_fire_outcomes[f"{im_recovery.ticker}#imart-recovery"] = {
            "status": "submitted",
            "order_id": im_recovery.order_id,
            "skip_reason": None,
            "reviewed_order": None,
            "submitted_amount_usd": im_recovery.recovered_amount_usd,
            # Read by _build_buy_candidates to synthesize an auditable row. The
            # ticker travels IN the outcome because the dict key is synthetic.
            "recovered_inverse_martingale_lease": True,
            "ticker": im_recovery.ticker,
        }

    process_ctx = ProcessCandidateContext(
        config=config,
        state=state,
        broker=broker,
        robinhood_data=robinhood_data,
        now=now,
        trading_day=trading_day,
        guard_active=guard_active,
        prior_same_day_allocations=prior_same_day_allocations or {},
        scheduled=scheduled,
        run_result=run_result,
        deployment_history_root=deployment_history_root,
        stream=stream,
        credit_ledger=credit_ledger,
    )
    candidate_outcomes, top_up_outcomes, running_deployed_7d, err_inc, rev_inc = (
        _process_buy_candidates_batch(
            buy_candidates=buy_candidates,
            ctx=process_ctx,
            initial_candidate_outcomes=recovered_fire_outcomes,
        )
    )
    errors_count += err_inc
    order_reviews_attempted += rev_inc

    _settle_inverse_martingale(
        im_pending_fires=im_pending_fires,
        candidate_outcomes=candidate_outcomes,
        stream=stream,
        trading_day=trading_day,
    )

    # Reflect any in-batch kill-switch engagement in the config used to build
    # this run's artifacts, so the risk_guard audit block (and
    # kill_switch_engaged) shows the guard actually having engaged during the
    # run when later candidates were capped, instead of only the pre-run
    # trailing-7-day figure.
    config = replace(config, deployed_last_7d_usd=running_deployed_7d)

    manual_review = [d for d in decisions if d.action == Action.MANUAL_REVIEW]
    if manual_review:
        logger.info(
            "Manual review tickers: %s", ", ".join(d.ticker for d in manual_review)
        )

    tier = state.current_tier()
    state.finalize_daily_budget(trading_day, config)
    logger.info(
        "Budget summary [%s]: spent $%.2f (daily cap $%.2f); weekly spent $%.2f / $%.2f; "
        "rollover reserve now $%.2f.",
        tier.name,
        state.day_notional(trading_day),
        tier.daily_cap_usd,
        state.week_notional(trading_day),
        state.effective_weekly_cap(),
        state.weekly_rollover_reserve_usd,
    )

    _finalize_and_write_artifacts(
        now=now,
        config=config,
        state=state,
        decisions=decisions,
        candidate_outcomes=candidate_outcomes,
        order_reviews_attempted=order_reviews_attempted,
        errors_count=errors_count,
        notifications_sent=notifications_sent,
        cost_control_notes=cost_control_notes,
        top_up_outcomes=top_up_outcomes if guard_active else None,
        scheduled=scheduled,
        artifacts_dir=artifacts_dir,
        classification_state_root=classification_state_root,
        raw_persistence_state=raw_persistence_state,
        classification_overrides=classification_overrides,
        correlation_id=correlation_id,
        broker=broker,
        extra_finance_calls_attempted=im_finance_calls_attempted,
        run_result=run_result,
    )

    return decisions


def run_and_report(
    now: datetime,
    config: StrategyConfig,
    state: StrategyState,
    finance_data: MarketDataProvider,
    robinhood_data: MarketDataProvider,
    broker: BrokerAdapter,
    *,
    output_dir: str,
    state_path: str,
    run_label: str = "manual",
    scheduled: bool = False,
    deployment_history_root: Optional[str | Path] = None,
) -> Dict[str, object]:
    """Execute one DCA run and emit the full slippage/coverage narrative + state file.

    This is the heavier path intended for manual and Friday/monthly reviews: it
    renders the narrative markdown report in addition to the CSV log. For the daily
    live path use ``run_daily_compact`` instead, which writes structured JSON/CSV and
    a compact summary only. This path is fully non-interactive: it never prompts for
    confirmation, so scheduled/background execution is unaffected. Returns the
    artifact paths and summary metrics.

    ``deployment_history_root`` feeds the trailing-7-day kill-switch (see
    ``dca_risk.apply_risk_guard``), same as ``run_daily_compact``/``run_pipeline``;
    defaults to ``output_dir``'s parent when not given, so a manual/full-report run
    during a period where scheduled-live deployment exceeded the threshold is
    capped the same as the compact daily path instead of silently using the
    full 2x-5x ladder.
    """
    if deployment_history_root is None:
        deployment_history_root = Path(output_dir).parent
    run_result = RunResult(
        trading_day=now.astimezone(EASTERN).date(),
        decisions=[],
        run_label=run_label,
        scheduled=scheduled,
    )
    ctx = RunContext(
        now=now,
        config=config,
        state=state,
        finance_data=finance_data,
        robinhood_data=robinhood_data,
        broker=broker,
        run_result=run_result,
        deployment_history_root=deployment_history_root,
        scheduled=scheduled,
    )
    run_once(ctx)
    report = generate_slippage_report(
        run_result, output_dir=output_dir, now=now
    )
    written_state = write_run_state(
        state_path,
        run_result=run_result,
        report=report,
        config=config,
        state=state,
    )
    return {
        "run_label": run_label,
        "scheduled": scheduled,
        "slippage_report_path": report.report_path,
        "orders_csv_path": report.csv_path,
        "state_path": written_state,
        "summary_metrics": report.metrics,
    }


@dataclass(frozen=True)
class CompactRunOptions:
    """Grouped configuration for :func:`run_daily_compact`.

    Bundles the daily compact run's tunables -- output location, run
    labeling/scheduling flags, cross-run state carried between same-day
    passes, and identifiers threaded through to the underlying
    :func:`run_once` call -- into a single immutable options object instead
    of a long keyword-argument list.

    Attributes:
        artifacts_dir: Directory the run's structured JSON/CSV artifacts are
            written to.
        run_label: Label recorded on the run result and artifacts (e.g.
            ``"daily"``, ``"morning"``).
        scheduled: Whether this run was triggered by the scheduler (as
            opposed to a manual invocation).
        notifications_sent: Count of notifications already sent for this
            trading day, if any, used to keep the usage-proxy counter
            accurate across passes.
        prior_same_day_allocations: Per-ticker allocations from an earlier
            same-day pass, used to top up rather than double-allocate.
        deployment_history_root: Root directory for deployment-history
            lookups; defaults to the parent of ``artifacts_dir`` when unset.
        classification_state_root: Root directory for persisted signal
            classification state.
        raw_persistence_state: Raw persistence state carried in from a
            prior pass/process, if the caller is resuming one.
        classification_overrides: Manual overrides applied on top of the
            computed signal classification.
        correlation_id: Identifier used to correlate this run's artifacts
            and logs with related runs/processes.
        stream: Which scheduled stream this run belongs to (e.g.
            ``"morning"``, ``"afternoon"``).
        earlier_week_notional_usd: Pre-summed EARLIER-weekday cross-stream
            spend (a completed prior day in the current ISO week), bumped
            onto the shared weekly cap bucket only -- see
            ``StrategyState.bump_week_notional_only``. Computed by the
            caller (``run_dca._compute_earlier_week_cross_stream_notional``),
            since resolving cross-stream roots needs ``config_dir``, which
            this options object does not carry.
        earlier_week_scan_had_failures: True when the earlier-weekday scan
            above could not verify every artifact it found; forces the
            weekly bucket to the worst-case tier ceiling instead of trusting
            an unproven, possibly-too-low total (see
            ``StrategyState.force_week_notional_to_worst_case_ceiling``).
    """

    artifacts_dir: str | Path
    run_label: str = "daily"
    scheduled: bool = True
    notifications_sent: Optional[int] = None
    prior_same_day_allocations: Optional[Dict[str, PriorSameDayAllocation]] = None
    deployment_history_root: Optional[str | Path] = None
    classification_state_root: Optional[str | Path] = None
    raw_persistence_state: Optional[Dict[str, object]] = None
    classification_overrides: Optional[Dict[str, Any]] = None
    correlation_id: Optional[str] = None
    stream: str = "afternoon"
    earlier_week_notional_usd: float = 0.0
    earlier_week_scan_had_failures: bool = False


def _validated_live_corporate_action_result(result: Any, as_of: date) -> Optional[Tuple[float, date]]:
    """Return only complete, well-formed corporate-action evidence.

    Custom providers can be passed directly to :func:`run_daily_compact`, so
    validation cannot be left solely to the persisted-provider wrapper in
    ``run_dca``.  Invalid evidence must fail closed before either the factor or
    cursor reaches the durable inverse-Martingale ledger.
    """
    if result is None:
        return None
    if not isinstance(result, (tuple, list)) or len(result) != 2:
        return None
    factor, cursor = result
    try:
        factor = float(factor)
    except (TypeError, ValueError, OverflowError):
        return None
    if isinstance(cursor, str):
        try:
            cursor = date.fromisoformat(cursor)
        except ValueError:
            return None
    if not isinstance(cursor, date) or cursor != as_of:
        return None
    if not math.isfinite(factor) or factor <= 0:
        return None
    return factor, cursor


def run_daily_compact(
    now: datetime,
    config: StrategyConfig,
    state: StrategyState,
    finance_data: MarketDataProvider,
    robinhood_data: MarketDataProvider,
    broker: BrokerAdapter,
    options: Optional[CompactRunOptions] = None,
    **legacy_options: Any,
) -> Dict[str, Any]:
    """Run one DCA scan and write only compact, structured daily artifacts.

    This is the token/credit-lean daily live path. It deliberately does NOT:
        - render the long narrative slippage/coverage markdown report,
        - build the weekly performance matrix,
        - run any historical backtest,
        - generate the full Notion dashboard.

    Those heavier rollups belong to Friday/monthly reviews (see ``run_and_report``
    and ``dca_weekly_dashboard``). Daily output is:
        - ``run_state.json``    structured run state incl. the usage-proxy block,
        - ``signals.csv``       per-(ticker, source) signal rows,
        - ``buy_candidates.csv``per-candidate rows,
        - ``orders.csv``        durable per-order execution/slippage log.

    The compact Notion "Latest Run" sync is produced downstream from
    ``latest_run_summary.json`` (see ``dca_reporting``/``dca_notion_sync``); this
    function only writes local artifacts and does not contact Notion directly.
    It may interact with the passed-in broker adapter (dry-run by default).

    Prefer passing ``options`` (a :class:`CompactRunOptions`). The former
    keyword-only parameters (``artifacts_dir``, ``run_label``, ``scheduled``,
    etc. -- documented in ``README_REPORTING.md``) are still accepted via
    ``**legacy_options`` and used to build a ``CompactRunOptions`` for
    backwards compatibility; do not pass both ``options`` and legacy keyword
    arguments in the same call.
    """
    if options is None:
        options = CompactRunOptions(**legacy_options)
    elif legacy_options:
        raise TypeError(
            "run_daily_compact() got legacy keyword arguments "
            f"{sorted(legacy_options)} in addition to 'options'; pass either "
            "'options' or the legacy keyword arguments, not both"
        )
    trading_day = now.astimezone(EASTERN).date()
    # Read BEFORE run_once() can overwrite it, to answer "does any pre-
    # existing orders.csv in this directory belong to the SAME scheduled slot
    # as this invocation, or was artifacts_dir reused for an unrelated
    # trading day OR a DIFFERENT scheduled slot on the same day?"
    # run_state.json's own trading_day plus run_classification.stream is the
    # only durable proof of that identity; without checking BOTH, the
    # success-path orders.csv merge below would keep a totally unrelated
    # run's execution rows and misattribute their fills/usage counts to
    # today's run (Codex review: "Merge executions only when retrying the
    # same run"; "Match the prior artifact's slot before merging
    # executions" -- two different scheduled slots sharing a trading_day but
    # writing to the same directory, e.g. a stale morning artifact reused by
    # a later midday run, must not be treated as a retry of each other just
    # because the date matches).
    _prior_state_path = Path(options.artifacts_dir) / "run_state.json"
    _prior_trading_day: Optional[str] = None
    _prior_stream: Optional[str] = None
    _prior_scheduled_for_et: Optional[str] = None
    # build_run_artifacts stamps a manual run's run_classification with
    # run_origin="manual" and neither `stream` nor `scheduled_for_et` set,
    # so a manual prior attempt's identity is None/None on both -- which,
    # left uncompared, spuriously equals THIS invocation's afternoon/15:30
    # DEFAULTS whenever options.scheduled is False (a manual run) too,
    # since _current_stream/_current_scheduled_for_et below have no way to
    # reflect "manual" on their own. Tracked separately so a manual run
    # invoked into a directory holding a same-day 15:30 SCHEDULED artifact
    # is never treated as a retry of it, and vice versa (Codex review:
    # "Separate manual runs from scheduled retries").
    _prior_state_payload: Optional[Dict[str, Any]] = None
    _prior_run_origin: Optional[str] = None
    # A run_state.json left by a DIFFERENT configured broker account (not
    # just a different day/stream/slot) is not this account's own prior
    # attempt to retry, even when every other identity field happens to
    # match -- the shared artifacts directory convention this module uses
    # throughout is per-directory, not per-account. Tracked separately, the
    # same non-reversible fingerprint _persist_cross_account_unresolved_
    # evidence/_reconcile_prior_unproven_fractional_placements already
    # compare, so `_orders_csv_same_run` below can require it too (Codex
    # review: "Include the broker account in directory ownership").
    _prior_account_fingerprint: Optional[str] = None
    # Default True (the safe "nothing to reject" reading): only overwritten
    # below when a prior state actually parses and reports otherwise. See
    # the comment where this is set for why it exists.
    _prior_state_was_dry_run = True
    # Tracked separately from `_prior_state_payload is None`: that also goes
    # None when the path EXISTS but a transient OSError/JSONDecodeError
    # prevented reading it -- a state that is not absent, only temporarily
    # unreadable. Collapsing the two let the blocked-date branch below treat
    # a foreign existing-but-unreadable state as "genuinely nothing there,
    # ownership verified" the same as a real empty directory: if the read
    # failure was transient and _write_blocked_run_stub() went on to
    # preserve that foreign state untouched, this invocation would still
    # stamp `directory_ownership_verified=True` on it (Codex review:
    # "Distinguish unreadable prior state from an absent state").
    _prior_state_path_truly_absent = not _prior_state_path.exists()
    if not _prior_state_path_truly_absent:
        try:
            _prior_state_payload = json.loads(_prior_state_path.read_bytes())
        except (OSError, json.JSONDecodeError, UnicodeDecodeError):
            _prior_state_payload = None
        if isinstance(_prior_state_payload, dict):
            _candidate_prior_day = _prior_state_payload.get("trading_day")
            if isinstance(_candidate_prior_day, str):
                _prior_trading_day = _candidate_prior_day
            _prior_classification = _prior_state_payload.get("run_classification")
            if isinstance(_prior_classification, dict):
                _candidate_prior_stream = _prior_classification.get("stream")
                if isinstance(_candidate_prior_stream, str):
                    _prior_stream = _candidate_prior_stream
                _candidate_prior_slot = _prior_classification.get("scheduled_for_et")
                if isinstance(_candidate_prior_slot, str):
                    _prior_scheduled_for_et = _candidate_prior_slot
                _candidate_prior_origin = _prior_classification.get("run_origin")
                if isinstance(_candidate_prior_origin, str):
                    _prior_run_origin = _candidate_prior_origin
            _candidate_prior_account = _prior_state_payload.get("account_number")
            if isinstance(_candidate_prior_account, str) and _candidate_prior_account.strip():
                _prior_account_fingerprint = _candidate_prior_account
            # build_run_artifacts() stamps "account_number" from the RAW,
            # non-sentinel _broker_account_fingerprint() call, which
            # collapses "no identity to fingerprint" (fine, dry-run/
            # simulated) and "a LIVE account's identity exists but the
            # keyed HMAC was temporarily unreadable" into the SAME `null`
            # -- the sentinel distinction _account_number_for_unresolved_
            # evidence exists to preserve is lost at the moment this field
            # is written, not just read. A null `account_number` therefore
            # cannot, on its own, tell "nothing to compare" apart from "a
            # live account's binding that could not be verified". Read
            # `"dry_run"` (stamped alongside "account_number" by the same
            # writer) as the distinguishing signal instead: a prior run
            # explicitly recording `dry_run: false` alongside a null
            # account_number is presumed to be the unavailable-binding case
            # and must NOT be treated as "no constraint recorded" below, or
            # a same-slot directory previously used by account A could be
            # retried under a DIFFERENT account B and have A's evidence
            # reinjected into B's state merely because fingerprinting
            # happened to be down when A's run wrote its artifact (Codex
            # review: "Reject prior states with unavailable account
            # bindings"). `is not False`, not a bare truthiness check: a
            # field that is simply ABSENT (a hand-built or legacy artifact
            # that predates this field) carries no positive evidence the
            # prior run was live, so it is read leniently, the same as a
            # genuinely dry-run prior state -- only an EXPLICIT `false`
            # counts as evidence to reject on.
            _prior_state_was_dry_run = _prior_state_payload.get("dry_run") is not False
    # Compared against the STREAM THE PERSISTED CLASSIFICATION WILL ACTUALLY
    # CARRY, not options.stream directly: build_scheduled_classification (via
    # build_run_artifacts, further below) stamps run_classification.stream
    # from classification_overrides["stream"], defaulting to "afternoon" when
    # that key is absent -- options.stream is a SEPARATE field this function
    # otherwise only threads through for other purposes. A caller of this
    # public CompactRunOptions API that sets options.stream="midday" without
    # ALSO putting "stream": "midday" in classification_overrides (this
    # repo's own real call site, run_dca._slot_classification_overrides,
    # always keeps them in sync) would otherwise compare a persisted
    # "afternoon" default against "midday" and never recognize its own
    # genuine retry, deleting an already-recovered execution row on every
    # successful retry (Codex review: "Compare retries against the persisted
    # classification stream").
    # SCHEDULED only: build_manual_classification stamps run_origin="manual"
    # and sets NEITHER "stream" NOR "scheduled_for_et", so a manual failure
    # artifact's own persisted slot identity is (None, None) -- exactly what
    # _prior_stream/_prior_scheduled_for_et read back for one, since there is
    # no classification dict key to find. Defaulting to "afternoon"/"15:30"
    # here regardless of options.scheduled compared that (None, None) prior
    # identity against the scheduled defaults and never recognized a manual
    # run's own prior manual failure as the same slot, deleting its recovered
    # candidate and execution rows on every successful manual retry --
    # exactly the gap _write_afternoon_failure_artifacts's OWN identical
    # computation (a few thousand lines up) was already fixed for (Codex
    # review, PR #859 round 27: "Align manual failure identity with
    # successful retries"), which this function's own docstring cites as the
    # precedent to mirror.
    _current_stream = (
        (options.classification_overrides or {}).get("stream", "afternoon")
        if options.scheduled
        else None
    )
    # A shared stream is not enough on its own: the intraday stream in
    # particular covers three distinct fire times (11:30/13:30/14:30 ET,
    # each its own run_id shape -- see scripts/run_classification.py's
    # INTRADAY_SLOT_IDENTITIES) under one stream name, distinguished only by
    # scheduled_for_et/run_id. Comparing day+stream alone would treat a
    # later slot reusing the same directory as a retry of an EARLIER slot
    # and merge its execution rows in (Codex review: "Include the scheduled
    # slot when identifying retries"). Defaults mirror
    # build_scheduled_classification's own default (SCHEDULED_FOR_ET =
    # "15:30"), so two afternoon runs with no override still compare equal.
    _current_scheduled_for_et = (
        (options.classification_overrides or {}).get("scheduled_for_et", "15:30")
        if options.scheduled
        else None
    )
    _current_run_origin = "manual" if not options.scheduled else "scheduled"
    # Computed once, up front -- this run's own account fingerprint never
    # changes across the rest of this function, and the unified ownership
    # check further below reuses it too (Codex review: "Include the broker
    # account in directory ownership"). _account_number_for_unresolved_
    # evidence, not a bare _broker_account_fingerprint call: the two both
    # return None for "the broker genuinely has no account identity"
    # (dry-run/simulated -- fine, nothing to bind), but the latter ALSO
    # returns None when the broker DOES have an identity and the local HMAC
    # key merely could not be read right now -- collapsing "nothing to
    # verify" and "verification temporarily unavailable" into the same
    # value would let a same-slot directory previously used by account A be
    # retried under account B, both reading back as an unbound `None`,
    # while fingerprint generation happens to be down (Codex review:
    # "Reject unbound account ownership"). The distinguishing sentinel
    # value below is never treated as a match against anything.
    _current_account_fingerprint = (
        _account_number_for_unresolved_evidence(broker, Path(options.artifacts_dir).parent)
        if broker is not None
        else None
    )
    # A prior artifact recording NO fingerprint at all (legacy, or a broker-
    # less dry run) has nothing to compare -- not the same thing as a
    # RECORDED fingerprint this run cannot verify against. Only a prior
    # artifact that DOES carry one, and this run's own fingerprint either
    # cannot be computed/verified (None, or the explicit "unavailable"
    # sentinel) or disagrees, fails the account check -- "cannot verify" is
    # treated as "not the same run", never as "assume it is". A null prior
    # fingerprint is trusted as "nothing to compare" ONLY when the prior run
    # was itself dry_run: a non-dry-run (live) prior run recording null is
    # presumed to be the unavailable-HMAC-key case (see
    # _prior_state_was_dry_run above), which must fail this check the same
    # way an unavailable CURRENT fingerprint already does, rather than being
    # silently accepted as an unbound match against any account.
    _prior_account_matches = (
        _current_account_fingerprint != _ACCOUNT_FINGERPRINT_UNAVAILABLE_SENTINEL
        and (
            (_prior_account_fingerprint is None and _prior_state_was_dry_run)
            or (
                _current_account_fingerprint is not None
                and _current_account_fingerprint == _prior_account_fingerprint
            )
        )
    )
    # A dry-run peer's null account_number reads as "nothing to compare"
    # above (the same leniency a genuine dry-run/legacy state always got),
    # but that leniency alone is not enough: a LIVE invocation (this run,
    # config.dry_run=False, a real fingerprint) overlapping a DRY-RUN
    # peer for the identical day/stream/slot would otherwise still be
    # accepted as the same run purely on identity+account, and the dry
    # peer could then be treated as the surviving state to reinject THIS
    # invocation's own real placements into -- while its own top-level
    # "dry_run" field stays true, so a loader that excludes dry-run
    # artifacts from allocation/exposure accounting would never see the
    # real order at all (Codex review: "Keep dry-run artifacts outside
    # live ownership matches"). Only rejects when the prior state's own
    # "dry_run" field is actually PRESENT and disagrees -- absent (a
    # legacy/hand-built artifact) carries no positive evidence either
    # way, so it stays lenient the same way `_prior_state_was_dry_run`'s
    # own "is not False" default already does.
    _prior_dry_run_field = (
        _prior_state_payload.get("dry_run") if isinstance(_prior_state_payload, dict) else None
    )
    _prior_execution_mode_matches = _prior_dry_run_field is None or _prior_dry_run_field == config.dry_run
    _orders_csv_same_run = (
        _prior_trading_day == trading_day.isoformat()
        and _prior_stream == _current_stream
        and _prior_scheduled_for_et == _current_scheduled_for_et
        and (_prior_run_origin or "scheduled") == _current_run_origin
        and _prior_account_matches
        and _prior_execution_mode_matches
    )
    # run_once() below is about to unconditionally overwrite run_state.json
    # with THIS invocation's own fresh state -- and once it does,
    # `_orders_csv_same_run` being False (specifically because the account
    # didn't match, with every other identity field agreeing) means the
    # reinjection block further down never revisits `_prior_state_payload`
    # again; it only reads it when `_orders_csv_same_run` is True. Whatever
    # submitted/recovered evidence the OTHER account's prior state carried
    # would otherwise simply vanish the instant run_once() publishes,
    # rather than merely being correctly excluded from THIS account's own
    # state (Codex review: "Preserve prior-account evidence before
    # publishing the new run"). Preserved here, before that overwrite,
    # through the same cross-account sidecar `_write_afternoon_failure_
    # artifacts`'s own `_cross_account_mismatch` branch already uses.
    # Triggers on EITHER an account mismatch OR an execution-mode mismatch
    # -- not `not _prior_account_matches` alone. A same-account retry that
    # switches mode (e.g. a live slot with real submitted candidates
    # re-run as config.dry_run=True) has `_prior_account_matches=True`
    # but `_prior_execution_mode_matches=False`, so `_orders_csv_same_run`
    # above is already False for it -- but the narrower account-only guard
    # here skipped this exact case, letting run_once()'s overwrite drop
    # the real order from artifact-derived deployment accounting with no
    # preservation at all (Codex review: "Preserve live evidence on a
    # dry-run mode switch").
    if (
        _prior_state_payload is not None
        and not (_prior_account_matches and _prior_execution_mode_matches)
        and _prior_trading_day == trading_day.isoformat()
        and _prior_stream == _current_stream
        and _prior_scheduled_for_et == _current_scheduled_for_et
        and (_prior_run_origin or "scheduled") == _current_run_origin
    ):
        _prior_account_broker_outcomes = _prior_state_payload.get("broker_outcomes")
        _prior_account_evidence = {
            key: outcome
            for key, outcome in (
                _prior_account_broker_outcomes.items()
                if isinstance(_prior_account_broker_outcomes, dict)
                else ()
            )
            if isinstance(outcome, dict)
        }
        # broker_outcomes alone only ever carries account A's recovery/
        # reconciliation rows -- an ORDINARY successful order A's own
        # run_once() placed lives in buy_candidates instead, the same
        # collection dca_risk.deployed_usd() sums for rolling exposure.
        # Without this, a normal submitted order (no recovery involved at
        # all) left this mapping empty, so no sidecar was ever written for
        # it, and the overwrite just below removed A's placement from
        # artifact-derived exposure accounting with no trace left behind
        # anywhere (Codex review: "Preserve ordinary prior-account
        # placements before overwrite"). Converted into the same
        # outcome shape the reinjection loop already uses for a folded
        # concurrent placement (see _my_own_outcomes further below):
        # submitted_amount_usd populated from planned_amount_usd (the
        # field name buy_candidates rows actually carry it under), keyed
        # by ticker with a defensive order_id/index suffix on collision.
        _prior_account_buy_candidates = _prior_state_payload.get("buy_candidates")
        if isinstance(_prior_account_buy_candidates, list):
            # DEPLOYED_CANDIDATE_STATUSES (submitted/filled/pending/
            # unconfirmed), not a bare ("submitted", "filled") tuple:
            # dca_risk.deployed_usd() treats all four as committed exposure,
            # so a still-outstanding pending/unconfirmed order from account
            # A excluded here was silently dropped from BOTH preservation
            # sidecars the instant run_once() replaced this foreign state --
            # a still-live order vanishing from every artifact-derived
            # deployment/cap accounting with no trace anywhere (Codex
            # review: "Preserve pending placements before replacing foreign
            # state").
            from dca_risk import DEPLOYED_CANDIDATE_STATUSES

            for _prior_account_row_index, _prior_account_row in enumerate(_prior_account_buy_candidates):
                if (
                    not isinstance(_prior_account_row, dict)
                    or _prior_account_row.get("status") not in DEPLOYED_CANDIDATE_STATUSES
                ):
                    continue
                _prior_account_row_ticker = _prior_account_row.get("ticker")
                if not isinstance(_prior_account_row_ticker, str) or not _prior_account_row_ticker:
                    continue
                _prior_account_evidence_key = (
                    _prior_account_row_ticker
                    if _prior_account_row_ticker not in _prior_account_evidence
                    else (
                        f"{_prior_account_row_ticker}:"
                        f"{_prior_account_row.get('order_id') or _prior_account_row_index}"
                    )
                )
                _prior_account_row_as_outcome = dict(_prior_account_row)
                _prior_account_row_as_outcome.setdefault(
                    "submitted_amount_usd", _prior_account_row.get("planned_amount_usd")
                )
                _prior_account_evidence[_prior_account_evidence_key] = _prior_account_row_as_outcome
        if _prior_account_evidence:
            if (
                isinstance(_prior_account_fingerprint, str)
                and _prior_account_fingerprint
                and _current_account_fingerprint is not None
                and _current_account_fingerprint != _ACCOUNT_FINGERPRINT_UNAVAILABLE_SENTINEL
                # EQUAL fingerprints means this trigger was a same-account
                # execution-mode mismatch (see _prior_execution_mode_matches
                # above), not a genuine cross-account conflict. The
                # cross-account sidecar's own reconciliation reader treats
                # ANY entry whose account_number equals the CURRENT
                # account's own fingerprint as unresolved evidence
                # belonging to it, raising UnresolvedPlacementError and
                # blocking every future placement for that account until
                # manual cleanup -- exactly the self-inflicted lockout the
                # comment below already warns against for a reversed
                # argument order, which equal fingerprints reproduce no
                # matter which order they are passed in. Routed to the
                # generic sidecar instead, which the reconciliation reader
                # never scans.
                and _prior_account_fingerprint != _current_account_fingerprint
            ):
                _persist_cross_account_unresolved_evidence(
                    options.artifacts_dir,
                    now,
                    # This evidence belongs to the PRIOR account (A) --
                    # not this run's own (B) -- so A's fingerprint is the
                    # "current_account_fingerprint" (whose evidence this
                    # is) and B's is the "existing_account_fingerprint"
                    # (the account the artifact will now belong to).
                    # Reversed, the sidecar entry would record this run's
                    # OWN account as the evidence owner, and
                    # _reconcile_prior_unproven_fractional_placements's
                    # own sidecar check (which blocks NEW placements
                    # whenever unresolved evidence recorded for ITS
                    # account is outstanding) would then refuse this same
                    # account's every future placement over evidence that
                    # was never actually its own.
                    _prior_account_fingerprint,
                    _current_account_fingerprint,
                    _prior_account_evidence,
                )
            else:
                # Either side's fingerprint could not be pinned down (this
                # run's own is unverifiable, or the prior state's own
                # recorded value was malformed) -- the cross-account
                # sidecar needs two real fingerprint strings, so this falls
                # back to the generic undurable-evidence sidecar instead of
                # silently dropping the evidence. The sidecar's own
                # "account_fingerprint" field should identify whose
                # evidence this is -- the PRIOR account's, since
                # `_prior_account_evidence` is A's own broker_outcomes --
                # so it prefers the known `_prior_account_fingerprint` over
                # this invocation's own (possibly unavailable/sentinel)
                # fingerprint whenever the prior one is itself a usable
                # string (Codex review: "Retain the prior account
                # fingerprint on fallback evidence"). Only falls back to
                # this run's own value when the prior one is what's
                # missing/malformed.
                _persist_undurable_evidence_sidecar(
                    Path(options.artifacts_dir),
                    "unreinjected_recovered_placement",
                    now,
                    {
                        "broker_outcomes": _prior_account_evidence,
                        "account_fingerprint": (
                            _prior_account_fingerprint
                            if isinstance(_prior_account_fingerprint, str) and _prior_account_fingerprint
                            else _current_account_fingerprint
                        ),
                    },
                )
    run_result = RunResult(
        trading_day=trading_day,
        decisions=[],
        run_label=options.run_label,
        scheduled=options.scheduled,
    )
    ctx = RunContext(
        now=now,
        config=config,
        state=state,
        finance_data=finance_data,
        robinhood_data=robinhood_data,
        broker=broker,
        artifacts_dir=options.artifacts_dir,
        run_result=run_result,
        notifications_sent=options.notifications_sent,
        prior_same_day_allocations=options.prior_same_day_allocations,
        deployment_history_root=options.deployment_history_root,
        scheduled=options.scheduled,
        classification_state_root=options.classification_state_root,
        raw_persistence_state=options.raw_persistence_state,
        classification_overrides=options.classification_overrides,
        correlation_id=options.correlation_id,
        stream=options.stream,
        earlier_week_notional_usd=options.earlier_week_notional_usd,
        earlier_week_scan_had_failures=options.earlier_week_scan_had_failures,
    )
    run_once(ctx)

    out = Path(options.artifacts_dir)
    out.mkdir(parents=True, exist_ok=True)
    # THIS invocation's own run_state.json bytes, exactly as
    # _finalize_and_write_artifacts's write_run_artifacts() call wrote them
    # under ITS OWN lock -- read back off the SAME RunResult object ctx.run_result
    # pointed at, never re-read from disk here. A prior version of this
    # snapshot re-read run_state.json from disk, unlocked, at this exact
    # point: a concurrent peer publishing into the SAME shared directory in
    # the gap between _finalize_and_write_artifacts's own lock release and
    # this read could win that race, so "this invocation's own bytes" was
    # sometimes actually the PEER's bytes -- which made the concurrent-writer
    # comparison below report "no concurrent writer" for a run that had one,
    # skipping the fold of this invocation's real placements into
    # buy_candidates and risking replacing the peer's orders.csv outright
    # (Codex review: "Capture this invocation's state at publication time").
    # Binding the snapshot to the exact bytes written under
    # write_run_artifacts's own lock, rather than any later re-read of the
    # shared path, closes that gap entirely: `run_result` is the object THIS
    # invocation's own ctx.run_result points at and _finalize_and_write_artifacts
    # stashed the bytes on, so it can only ever reflect this invocation's own
    # publish, never a peer's.
    _this_invocations_own_state_bytes: Optional[bytes] = run_result.published_run_state_bytes
    result: Dict[str, object] = {
        "run_label": options.run_label,
        "scheduled": options.scheduled,
        "compact": True,
        "blocked": _date_or_holiday_blocked(trading_day, config),
        "artifacts_dir": str(out),
        "run_state_path": str(out / "run_state.json"),
    }
    if result["blocked"]:
        # Date or holiday gate tripped inside run_once. The blocked stub still
        # writes the complete root-level set (run_state.json, run_summary.json, and
        # header-only signals.csv / submitted_orders.csv), so advertise the signals
        # path and the summary.
        # A malformed pre-existing state is intentionally left untouched by
        # the blocked-path preservation guard. In that case no stub companions
        # exist, so advertise only files that this invocation can prove exist.
        for _result_key, _artifact_name in (
            ("run_summary_path", "run_summary.json"),
            ("signals_path", "signals.csv"),
            ("submitted_orders_path", "submitted_orders.csv"),
        ):
            _artifact_path = out / _artifact_name
            if _artifact_path.exists():
                result[_result_key] = str(_artifact_path)
        # buy_candidates.csv / orders.csv are ordinarily NOT written on a
        # blocked date -- the run evaluated no candidate and logged no
        # execution -- but gated fractional-placement reconciliation
        # (inside run_once, above) can accept an order on a calendar-
        # blocked date and, via _refresh_blocked_run_companions and the
        # execution-csv merge that follows it, write exactly those two
        # files even though this run itself evaluated nothing fresh. The
        # old unconditional omission assumed the files could not exist and
        # left callers that key off the returned artifact map skipping the
        # recovered execution and candidate audit even when both were
        # actually written to disk (Codex review, PR #911 round 28: "Return
        # paths for artifacts created by blocked recovery").
        #
        # Existence alone is not proof THIS invocation produced them,
        # though: a blocked directory reused from an OLDER, already-
        # completed run can carry a stale buy_candidates.csv/orders.csv of
        # its own with nothing left to recover this pass -- advertising
        # those as this invocation's own recovery output let a caller
        # process old trades as though they were fresh blocked-day
        # recovery (Codex review, PR #911 round 30: "Return blocked
        # artifact paths only when recovery produced them"). Gated instead
        # on run_state.json's own "reconciled_on_retry" marker --
        # _reconcile_prior_unproven_fractional_placements stamps this on
        # every broker_outcomes row it durably resolves, this pass or any
        # earlier one, so its presence is exactly "gated reconciliation
        # actually ran and mutated this artifact" -- the only condition
        # under which _refresh_blocked_run_companions/the execution-csv
        # merge could have produced these two files at all.
        #
        # A durable "reconciled_on_retry" marker persists FOREVER once
        # set -- it never gets cleared -- so checking only "does the
        # CURRENT on-disk state have any such row" answered yes for a
        # SECOND blocked invocation with nothing left to reconcile too:
        # _write_blocked_run_stub() preserves the existing state, the
        # marker from the FIRST invocation's genuine recovery is still
        # sitting there, and this check read it as proof THIS pass
        # produced fresh output, recreating the exact stale-artifact
        # behavior this fix was meant to close (Codex review, PR #911
        # round 33: "Scope blocked-recovery detection to this
        # invocation"). `_prior_state_payload` -- the SAME snapshot read
        # BEFORE `run_once()` could mutate anything, a few hundred lines
        # up in this function -- is the "before" side of the comparison:
        # a row's marker is new evidence only when it was NOT already set
        # on that prior snapshot.
        _prior_reconciled_on_retry_keys: set = set()
        if isinstance(_prior_state_payload, dict):
            _prior_outcomes_snapshot = _prior_state_payload.get("broker_outcomes")
            if isinstance(_prior_outcomes_snapshot, dict):
                _prior_reconciled_on_retry_keys = {
                    _key
                    for _key, _row in _prior_outcomes_snapshot.items()
                    if isinstance(_row, dict) and _row.get("reconciled_on_retry")
                }
        _blocked_recovery_occurred = False
        # Initialized before the guarded read, not only on the success
        # path: the ownership check just below (`_blocked_state_is_own`)
        # reads `_blocked_run_state` unconditionally, and a transient
        # OSError/JSONDecodeError/UnicodeDecodeError here previously left
        # it unbound, raising UnboundLocalError and crashing a calendar-
        # blocked invocation precisely when the resulting artifact could
        # not be read (Codex review: "Initialize the blocked-state
        # snapshot before reading").
        _blocked_run_state: Optional[Dict[str, Any]] = None
        try:
            _blocked_run_state = json.loads(
                (out / "run_state.json").read_text(encoding="utf-8")
            )
            _blocked_outcomes = (
                _blocked_run_state.get("broker_outcomes")
                if isinstance(_blocked_run_state, dict)
                else None
            )
            if isinstance(_blocked_outcomes, dict):
                _blocked_recovery_occurred = any(
                    isinstance(_row, dict)
                    and _row.get("reconciled_on_retry")
                    and _key not in _prior_reconciled_on_retry_keys
                    for _key, _row in _blocked_outcomes.items()
                )
        except (OSError, UnicodeDecodeError, json.JSONDecodeError):
            _blocked_recovery_occurred = False
        # Ownership re-verified from `_blocked_run_state` -- read AFTER
        # run_once() (and, inside it, _write_blocked_run_stub()) already ran
        # -- rather than trusted from `_prior_state_path_truly_absent`/
        # `_orders_csv_same_run`, both computed from the snapshot taken
        # BEFORE run_once() could touch anything. When the initial check
        # found no prior state at all, a DIFFERENT overlapping invocation
        # (a different slot, or a different account) can still publish its
        # own run_state.json in the gap before _write_blocked_run_stub()
        # runs; that helper's own contract is "never clobber existing
        # state", so it preserves the peer's state untouched -- but the
        # stale "was absent" snapshot alone would still report ownership as
        # verified for what is now actually a foreign file (Codex review:
        # "Verify blocked-run ownership after writing the stub"). Mirrors
        # `_fresh_state_is_own`'s identity+account check further below,
        # applied here against the freshest read instead of a pre-run one.
        _blocked_state_is_own = False
        if isinstance(_blocked_run_state, dict):
            _blocked_classification = _blocked_run_state.get("run_classification")
            _blocked_stream = (
                _blocked_classification.get("stream")
                if isinstance(_blocked_classification, dict) else None
            )
            _blocked_scheduled_for_et = (
                _blocked_classification.get("scheduled_for_et")
                if isinstance(_blocked_classification, dict) else None
            )
            _blocked_run_origin = (
                _blocked_classification.get("run_origin")
                if isinstance(_blocked_classification, dict) else None
            )
            _blocked_account_fingerprint = _blocked_run_state.get("account_number")
            _blocked_state_was_dry_run = _blocked_run_state.get("dry_run") is not False
            _blocked_account_matches = (
                _current_account_fingerprint != _ACCOUNT_FINGERPRINT_UNAVAILABLE_SENTINEL
                and (
                    (_blocked_account_fingerprint is None and _blocked_state_was_dry_run)
                    or (
                        isinstance(_blocked_account_fingerprint, str)
                        and _blocked_account_fingerprint.strip()
                        and _current_account_fingerprint is not None
                        and _current_account_fingerprint == _blocked_account_fingerprint
                    )
                )
            )
            # Same execution-mode parity as `_prior_execution_mode_matches`/
            # `_fresh_execution_mode_matches` -- the calendar gate can
            # preserve a same-slot DRY-RUN artifact (via
            # _write_blocked_run_stub()'s own "never clobber" contract)
            # while THIS invocation is live; without this, its null
            # account_number/dry_run:true state passed the account check
            # above purely on the null-fingerprint leniency, and the caller
            # would go on to perform raw-manifest/preflight rewrites
            # against that dry-run peer (Codex review: "Require
            # execution-mode parity for blocked ownership"). `is None`,
            # not the defaulted `_blocked_state_was_dry_run` above (which
            # exists only for the account-null-leniency check and defaults
            # True when absent): a field that is simply absent carries no
            # positive evidence either way, so it stays lenient the same
            # way `_prior_execution_mode_matches` does.
            _blocked_dry_run_field = _blocked_run_state.get("dry_run")
            _blocked_execution_mode_matches = (
                _blocked_dry_run_field is None or _blocked_dry_run_field == config.dry_run
            )
            _blocked_state_is_own = (
                _blocked_run_state.get("trading_day") == trading_day.isoformat()
                and _blocked_stream == _current_stream
                and _blocked_scheduled_for_et == _current_scheduled_for_et
                and (_blocked_run_origin or "scheduled") == _current_run_origin
                and _blocked_account_matches
                and _blocked_execution_mode_matches
            )
        if _blocked_recovery_occurred:
            _blocked_buy_candidates_csv = out / "buy_candidates.csv"
            if _blocked_buy_candidates_csv.exists():
                result["buy_candidates_path"] = str(_blocked_buy_candidates_csv)
            _blocked_orders_csv = out / "orders.csv"
            if _blocked_orders_csv.exists():
                result["orders_csv_path"] = str(_blocked_orders_csv)
        # This branch returns before the unified ownership-verification
        # critical section further down ever runs, so that section's own
        # `result["directory_ownership_verified"]` stamp never happens
        # here -- and _write_blocked_run_stub's own contract is "nothing
        # already on disk is clobbered", i.e. a reused directory's existing
        # run_state.json is preserved completely UNVERIFIED, with no
        # identity or account check at all. Verified only when there was
        # genuinely nothing there before this call (the stub's own fresh
        # write, unambiguously this invocation's) or the preserved state
        # provably shares this invocation's own identity AND account
        # (`_orders_csv_same_run`, computed above before run_once() could
        # touch anything) -- otherwise the caller must not trust
        # `run_state_path` as this invocation's own output any more than
        # the foreign-directory case further down already refuses to
        # (Codex review: "Set ownership status before returning blocked
        # results").
        result["directory_ownership_verified"] = _blocked_state_is_own
        return result

    # A crash-lease recovery from an EARLIER, failed attempt at this same
    # slot has its own execution row preserved into orders.csv below (via
    # _orders_csv_same_run), but run_once() just wrote a FRESH run_state.json
    # from THIS invocation's own candidates alone -- if the recovery's lease
    # was already durably cleared by that earlier attempt, THIS run's
    # recovery-publish loop never re-evaluates it (there is nothing pending
    # left to recover), so the recovered candidate never makes it into the
    # new state's buy_candidates. dca_risk.deployed_usd() sums exactly
    # buy_candidates rows with status=="submitted", so the recovered spend
    # silently drops out of the kill-switch's deployed-capital total from
    # this point on (Codex review: "Preserve recovered candidates through
    # successful retries"). Re-injected here from the prior state's own
    # broker_outcomes -- the full outcome dict a failure artifact retains,
    # keyed by the same synthetic "<ticker>#imart-recovery" key the
    # recovery-publish loop itself uses -- via the SAME _failure_candidate_row
    # builder the failure writer uses, so the row shape matches exactly.
    #
    # `reconciled_fractional_placement` is the SAME shape of gap for a
    # DIFFERENT recovery kind: a same-slot run that succeeded by reconciling
    # an ambiguous fractional placement (see
    # _reconcile_ambiguous_fractional_placement/_reconcile_prior_unproven_
    # fractional_placements) marks its outcome this way, not
    # recovered_inverse_martingale_lease -- and a LATER retry of that same
    # slot overwrote run_state.json from its own fresh candidates alone,
    # silently dropping the earlier reconciled submission the exact same
    # way an un-reinjected imart recovery would (Codex review, PR #911
    # round 32: "Preserve fractional recoveries across later retries").
    # Both markers already travel together everywhere else this module
    # tracks recovery rows (see _RECOVERY_ROW_REASONS).
    # Set when the reinjection loop's own freshest-state identity recheck
    # (below) finds that a DIFFERENT, overlapping invocation has since
    # claimed this shared directory -- a different trading day, scheduled
    # slot, or manual run now owns run_state.json here, even though
    # `_orders_csv_same_run` (computed from the snapshot taken BEFORE
    # run_once() ran) still says "same run". That flag alone used to keep
    # gating the orders.csv merge/backfill below it for the rest of this
    # function, so those downstream writes still treated the now-foreign
    # directory as this invocation's own: merging this invocation's
    # execution records into the foreign owner's orders.csv and backfilling
    # usage into ITS run_state.json, corrupting an unrelated run's artifacts
    # (Codex review: "Stop downstream writes when the run identity
    # changes"). This flag lets the downstream section skip entirely once
    # that is known, rather than trusting the stale pre-run_once() check.
    _prior_recovered_outcomes: Dict[str, Any] = {}
    if _orders_csv_same_run and _prior_state_payload is not None:
        _prior_broker_outcomes = _prior_state_payload.get("broker_outcomes")
        # A same-slot prior run_state.json that parsed as an object can still
        # carry a malformed (non-mapping) broker_outcomes field -- e.g. a
        # partially corrupted list. An unconditional .items() there raised
        # AFTER run_once() had already completed and potentially placed live
        # orders, aborting this whole reinjection block -- including the
        # orders.csv merge and usage backfill that follow it -- even though
        # the freshly written state itself may be entirely valid (Codex
        # review: "Ignore malformed prior broker outcomes during retry").
        _prior_recovered_outcomes = {
            key: outcome
            for key, outcome in (
                _prior_broker_outcomes.items()
                if isinstance(_prior_broker_outcomes, dict)
                else ()
            )
            if isinstance(outcome, dict)
            and (
                outcome.get("recovered_inverse_martingale_lease")
                or outcome.get("reconciled_fractional_placement")
            )
        }

    orders_csv = out / "orders.csv"
    _directory_claimed_by_foreign_run = False
    _reinjection_attempts_remaining = 3
    # Verifying THIS invocation still owns this shared directory, reinjecting
    # any queued recovery, merging this invocation's own executions into
    # orders.csv, and backfilling usage counters now all run as ONE critical
    # section under a SINGLE lock acquisition, always -- regardless of
    # whether _orders_csv_same_run was ever true, or whether there happened
    # to be a recovery queued to reinject. An earlier version of this fix
    # used one `with cross_process_lock(...)` block for the ownership check
    # and a separate, later one for the orders.csv merge/backfill; that left
    # a real gap between them where a DIFFERENT overlapping invocation could
    # still claim the directory, an opportunistic "no prior state at all"
    # case where the check never ran, and a failed ownership check that used
    # to just log a warning and fall through to the writes anyway (Codex
    # review: "Require verified ownership before merging executions").
    # Holding one lock across the whole thing, and treating "could not
    # verify" the SAME as "verified foreign" (sidecar and skip, never merge
    # on an unproven identity), closes all three.
    while True:
        try:
            with cross_process_lock(
                (out / "run_state.json").with_name("run_state.json.lock")
            ):
                try:
                    _fresh_state_raw_bytes: Optional[bytes] = (out / "run_state.json").read_bytes()
                    _fresh_state = json.loads(_fresh_state_raw_bytes)
                except (OSError, json.JSONDecodeError, UnicodeDecodeError):
                    _fresh_state_raw_bytes = None
                    _fresh_state = None
                _fresh_state_is_own = False
                _fresh_stream: Optional[str] = None
                if isinstance(_fresh_state, dict):
                    # `_orders_csv_same_run` only proved identity against
                    # `_prior_state_payload`, read BEFORE run_once() ran (or,
                    # when there was no prior state at all, proved nothing
                    # either way); this retry loop's own lock acquisition can
                    # be delayed behind a contending holder, leaving a window
                    # where an entirely different overlapping invocation (a
                    # different trading day, scheduled slot, or a manual run)
                    # publishes into this SAME shared directory first.
                    # Compared against THIS invocation's own identity
                    # (`_current_stream`/`_current_scheduled_for_et`/
                    # `_current_run_origin`, computed unconditionally above
                    # this whole block -- independent of whether a prior
                    # state ever existed) and re-read from the freshest
                    # on-disk state, not the pre-run_once() snapshot (Codex
                    # review: "Recheck run identity before reinjecting
                    # recoveries").
                    _fresh_classification = _fresh_state.get("run_classification")
                    _fresh_stream = (
                        _fresh_classification.get("stream")
                        if isinstance(_fresh_classification, dict) else None
                    )
                    _fresh_scheduled_for_et = (
                        _fresh_classification.get("scheduled_for_et")
                        if isinstance(_fresh_classification, dict) else None
                    )
                    _fresh_run_origin = (
                        _fresh_classification.get("run_origin")
                        if isinstance(_fresh_classification, dict) else None
                    )
                    # Same day/stream/slot/origin match is not enough on its
                    # own: a directory reused for the identical scheduled
                    # slot under a DIFFERENT configured broker account would
                    # otherwise still read as "this invocation's own",
                    # reinjecting/merging THAT account's executions into
                    # this account's artifact set and misattributing
                    # exposure between accounts (Codex review: "Include the
                    # broker account in directory ownership"). A fresh state
                    # with NO fingerprint recorded (legacy/broker-less dry
                    # run) has nothing to compare, same posture as the
                    # prior-run check above; one that DOES carry a
                    # fingerprint this run cannot compute or that disagrees
                    # fails closed -- "cannot verify" is never treated as
                    # "assume it's mine". Same non-dry-run-null-means-
                    # unbound reasoning as `_prior_state_was_dry_run` above:
                    # build_run_artifacts() stamps "account_number" from the
                    # raw, non-sentinel fingerprint call, so a null value on
                    # a NON-dry-run fresh state means "a live account's
                    # binding could not be verified when this was written",
                    # not "nothing to compare" -- trusting it as a match
                    # would accept ANY current account against a directory a
                    # different, unverifiable account actually claimed
                    # (Codex review: "Reject prior states with unavailable
                    # account bindings").
                    _fresh_account_fingerprint = _fresh_state.get("account_number")
                    # `is not False`, not a bare truthiness check -- same
                    # reasoning as `_prior_state_was_dry_run` above: a
                    # missing field carries no positive evidence this was a
                    # live run, so it is read leniently; only an explicit
                    # `false` counts as evidence to reject on.
                    _fresh_state_was_dry_run = _fresh_state.get("dry_run") is not False
                    _fresh_account_matches = (
                        _current_account_fingerprint != _ACCOUNT_FINGERPRINT_UNAVAILABLE_SENTINEL
                        and (
                            (_fresh_account_fingerprint is None and _fresh_state_was_dry_run)
                            or (
                                isinstance(_fresh_account_fingerprint, str)
                                and _fresh_account_fingerprint.strip()
                                and _current_account_fingerprint is not None
                                and _current_account_fingerprint == _fresh_account_fingerprint
                            )
                        )
                    )
                    # Same execution-mode parity as `_prior_execution_mode_
                    # matches` above -- a dry-run peer's null account must
                    # not be accepted as a match for a LIVE invocation
                    # purely because every other identity field agrees
                    # (Codex review: "Keep dry-run artifacts outside live
                    # ownership matches").
                    _fresh_dry_run_field = _fresh_state.get("dry_run")
                    _fresh_execution_mode_matches = (
                        _fresh_dry_run_field is None or _fresh_dry_run_field == config.dry_run
                    )
                    _fresh_state_is_own = (
                        _fresh_state.get("trading_day") == trading_day.isoformat()
                        and _fresh_stream == _current_stream
                        and _fresh_scheduled_for_et == _current_scheduled_for_et
                        and (_fresh_run_origin or "scheduled") == _current_run_origin
                        and _fresh_account_matches
                        and _fresh_execution_mode_matches
                    )
                if not _fresh_state_is_own:
                    # This directory does not (or no longer) belongs to this
                    # invocation. Nothing past this point -- reinjection, the
                    # orders.csv merge, or the usage backfill -- may touch it
                    # as if it were still this invocation's own (Codex
                    # review: "Stop downstream writes when the run identity
                    # changes" / "Require verified ownership before merging
                    # executions"). Any recovery this invocation still had
                    # queued, and any order it itself placed via run_once()
                    # above, are not simply dropped -- there is genuinely no
                    # directory left to publish them into, so both go to the
                    # same durable, lock-free sidecar mechanism the
                    # lock-exhaustion branch below also uses.
                    _directory_claimed_by_foreign_run = True
                    logger.error(
                        "not publishing this run's recoveries/executions into %s: "
                        "the directory was claimed by a different run "
                        "(trading_day=%s stream=%s) since this invocation started",
                        out / "run_state.json",
                        _fresh_state.get("trading_day") if isinstance(_fresh_state, dict) else None,
                        _fresh_stream,
                    )
                    if _prior_recovered_outcomes:
                        _foreign_directory_account_fingerprint = (
                            _account_number_for_unresolved_evidence(broker, Path(out).parent)
                            if broker is not None
                            else None
                        )
                        _persist_undurable_evidence_sidecar(
                            out,
                            "unreinjected_recovered_placement",
                            datetime.now(timezone.utc),
                            {
                                "broker_outcomes": _prior_recovered_outcomes,
                                "account_fingerprint": _foreign_directory_account_fingerprint,
                            },
                        )
                    _persist_foreign_directory_execution_sidecar(
                        out, datetime.now(timezone.utc), run_result.execution_records, broker
                    )
                    break

                # Ownership verified. True only when the run_state.json just
                # read differs from the exact bytes THIS invocation's OWN
                # run_once() call wrote (captured right after that call
                # returned) -- proof some OTHER, concurrent invocation
                # sharing this identity published its own state since, not
                # a stale leftover. Computed here, before the reinjection
                # block below, so that block can also fold THIS invocation's
                # own placements into the SURVIVING peer's state -- not just
                # decide the orders.csv merge/replace question further down
                # (Codex review: "Recompute replacement intent after
                # acquiring the lock" / "Merge concurrent placements into
                # the surviving run state").
                _concurrent_writer_confirmed = (
                    _this_invocations_own_state_bytes is not None
                    and _fresh_state_raw_bytes is not None
                    and _fresh_state_raw_bytes != _this_invocations_own_state_bytes
                )
                # When a concurrent peer's state is what's surviving, THIS
                # invocation's own buy_candidates/broker_outcomes -- real
                # orders run_once() above already placed -- would otherwise
                # never enter the state dca_risk.deployed_usd() actually
                # reads (it sums run_state.json's buy_candidates, not
                # orders.csv): only orders.csv gets this invocation's rows,
                # via the merge further below. Extracted from THIS
                # invocation's own just-written state (captured right after
                # run_once() returned, before any peer could have touched
                # it) and reinjected the same way a queued recovery already
                # is, below (Codex review: "Merge concurrent placements into
                # the surviving run state").
                # `broker_outcomes` is NOT where an ordinary successful
                # placement lives -- that field is only ever populated by
                # recovery/reconciliation paths (crash-lease recovery,
                # fractional-placement reconciliation). A normal run's own
                # submitted candidates live in `buy_candidates` alone, so
                # this reads THAT instead and converts each qualifying row
                # into the same outcome shape `_failure_candidate_row`
                # (used by the existing reinjection loop below) already
                # expects, keyed by ticker (or ticker:order_id on a
                # same-ticker collision, mirroring
                # `_write_afternoon_failure_artifacts`'s own convention).
                _my_own_state_for_merge: Optional[Dict[str, Any]] = None
                if _concurrent_writer_confirmed and _this_invocations_own_state_bytes is not None:
                    try:
                        _my_own_state_for_merge = json.loads(_this_invocations_own_state_bytes)
                    except (json.JSONDecodeError, UnicodeDecodeError):
                        _my_own_state_for_merge = None
                _my_own_outcomes: Dict[str, Any] = {}
                if isinstance(_my_own_state_for_merge, dict):
                    for _row in _my_own_state_for_merge.get("buy_candidates") or []:
                        if not isinstance(_row, dict) or _row.get("status") not in ("submitted", "filled"):
                            continue
                        _row_ticker = _row.get("ticker")
                        if not isinstance(_row_ticker, str) or not _row_ticker:
                            continue
                        _outcome_dict_key = (
                            _row_ticker
                            if _row_ticker not in _my_own_outcomes
                            else f"{_row_ticker}:{_row.get('order_id')}"
                        )
                        _row_as_outcome = dict(_row)
                        # `_failure_candidate_row` (the shared builder the
                        # loop below uses) reads the submitted amount as
                        # `submitted_amount_usd` -- the field name a
                        # broker_outcomes/recovery entry carries it under --
                        # not `planned_amount_usd`, which is what an
                        # ordinary buy_candidates row (this one) actually
                        # has. Without this, the rebuilt row would silently
                        # zero out this invocation's own planned amount.
                        _row_as_outcome.setdefault("submitted_amount_usd", _row.get("planned_amount_usd"))
                        # Marked so a LATER retry of this same slot -- whose own
                        # run_once() overwrites run_state.json again -- still finds
                        # this concurrent placement in _prior_recovered_outcomes
                        # (below) and carries it forward. Without this marker the
                        # row survives only ONE retry: the very next one
                        # recomputes _prior_recovered_outcomes from THIS state's
                        # own broker_outcomes and filters on exactly the two
                        # markers checked there, dropping this otherwise-unmarked
                        # row and permanently excluding a real placement from
                        # run_state.json's buy_candidates -- the same collection
                        # dca_risk.deployed_usd() sums (Codex review: "Carry
                        # merged concurrent placements through later retries").
                        # Reusing reconciled_fractional_placement rather than
                        # adding a third marker: both flags already travel
                        # together everywhere else this module tracks recovery
                        # rows (see _RECOVERY_ROW_REASONS), and this row is the
                        # same shape of gap -- a no-decision row this run's own
                        # fresh candidate-building never produces -- that marker
                        # already exists to close.
                        _row_as_outcome.setdefault("reconciled_fractional_placement", True)
                        _my_own_outcomes[_outcome_dict_key] = _row_as_outcome
                # Distinct keys from _prior_recovered_outcomes in practice
                # (that dict's keys carry a "#imart-recovery"/"#fractional-
                # recovery" suffix run_once()'s own candidate-building never
                # produces), but suffixed defensively on any collision
                # rather than trusting that to always hold.
                _outcomes_to_reinject: Dict[str, Any] = dict(_prior_recovered_outcomes)
                for _my_key, _my_outcome in _my_own_outcomes.items():
                    _dedup_key = _my_key
                    if _dedup_key in _outcomes_to_reinject:
                        # A single fixed ":concurrent" suffix is not
                        # collision-free once folded concurrent placements
                        # persist across retries (see
                        # reconciled_fractional_placement above): a
                        # same-ticker key can already occupy BOTH `_my_key`
                        # and `f"{_my_key}:concurrent"` after multiple
                        # overlapping retries, and reusing that one fallback
                        # would silently overwrite -- not merely rename --
                        # the second persisted outcome (Codex review:
                        # "Allocate a collision-free key for every
                        # concurrent outcome"). Prefer the order_id, which
                        # is unique per broker submission, and only fall
                        # back to a numeric counter when it too collides or
                        # is unusable.
                        _my_order_id = _my_outcome.get("order_id")
                        _dedup_key = (
                            f"{_my_key}:concurrent:{_my_order_id}"
                            if _is_usable_reconciled_order_id(_my_order_id)
                            else f"{_my_key}:concurrent"
                        )
                        _dedup_suffix = 2
                        while _dedup_key in _outcomes_to_reinject:
                            _dedup_key = f"{_my_key}:concurrent:{_dedup_suffix}"
                            _dedup_suffix += 1
                    _outcomes_to_reinject[_dedup_key] = _my_outcome

                # Reinject any queued recovery or this invocation's own
                # concurrent placements, still under this SAME lock, before
                # merging this invocation's own executions and backfilling
                # usage below.
                if _outcomes_to_reinject:
                    # A non-list "buy_candidates" (the same shape of
                    # corruption/legacy-format risk as "broker_outcomes"
                    # and "counts" above -- a same-identity concurrent
                    # writer can leave a truthy non-iterable value, e.g. a
                    # partially corrupted state containing a bare number)
                    # made `for row in (... or [])` raise TypeError:
                    # 'int' object is not iterable -- AFTER run_once() may
                    # already have placed live orders, while the enclosing
                    # retry catches only TimeoutError/OSError, so neither
                    # the orders merge nor the fallback sidecar ran (Codex
                    # review: "Normalize fresh candidates before
                    # reinjection"). Normalized the same way
                    # "broker_outcomes"/"counts" already are.
                    _fresh_buy_candidates_raw = _fresh_state.get("buy_candidates")
                    _fresh_candidates = [
                        row
                        for row in (
                            _fresh_buy_candidates_raw if isinstance(_fresh_buy_candidates_raw, list) else []
                        )
                        if isinstance(row, dict)
                    ]
                    # Filtered through the same usability check as
                    # the prior-recovery order_id below (Codex
                    # review: "Fail closed on malformed recovered
                    # order IDs") -- a malformed row already present
                    # in the fresh state's own buy_candidates (a
                    # truthy non-scalar order_id) would otherwise
                    # raise TypeError: unhashable type building this
                    # set literal itself, before the loop below is
                    # ever reached.
                    #
                    # Seeded from EVERY id a fresh candidate represents
                    # (via `_represented_order_ids_for_count`, which also
                    # reads `whole_share_order_ids`), not just its own
                    # scalar `order_id`: a fresh whole-share aggregate can
                    # represent A and B via `whole_share_order_ids` while
                    # exposing only B as its scalar id, and seeding from
                    # the scalar alone left A absent from this dedup set --
                    # a prior recovery row for A was then reinjected as
                    # ANOTHER submission, duplicating its candidate/outcome
                    # and inflating regenerated submission counts (Codex
                    # review, PR #1169: "Seed deduplication from every
                    # represented order ID").
                    _fresh_order_ids: set = set()
                    for row in _fresh_candidates:
                        _fresh_order_ids |= _represented_order_ids_for_count(row)
                    # Persisted into THIS run's own broker_outcomes too, not just
                    # buy_candidates: a SUBSEQUENT successful retry of the same
                    # slot re-derives _prior_recovered_outcomes from THIS state's
                    # own broker_outcomes (read as _prior_state_payload on that
                    # later call) -- if this block only ever updated
                    # buy_candidates, that later retry would find nothing to
                    # reinject and silently drop the recovered candidate all
                    # over again the moment a second retry happens (Codex
                    # review: "Persist reinjected recoveries for the next
                    # retry").
                    # A non-mapping "broker_outcomes" (a same-identity
                    # concurrent writer leaving a corrupted/legacy shape,
                    # e.g. a list) made a bare `dict(...)` call raise
                    # ValueError/TypeError here -- AFTER run_once() may
                    # already have placed live orders, while the enclosing
                    # retry loop's own except clause only catches
                    # TimeoutError/OSError, so this escaped uncaught,
                    # skipping both the orders merge and the fallback
                    # sidecar and leaving those orders out of deployment
                    # accounting entirely (Codex review: "Reject malformed
                    # fresh broker outcomes without raising"). Normalized
                    # the same way the prior-state extraction already
                    # guards its own read of this same field.
                    _fresh_broker_outcomes_raw = _fresh_state.get("broker_outcomes")
                    _fresh_broker_outcomes = (
                        dict(_fresh_broker_outcomes_raw)
                        if isinstance(_fresh_broker_outcomes_raw, dict)
                        else {}
                    )
                    _added_recovered = False
                    for _key, _outcome in _outcomes_to_reinject.items():
                        _order_id = _outcome.get("order_id")
                        # `_is_usable_reconciled_order_id` (not a bare
                        # truthiness/membership check) guards the set
                        # operations below: a malformed prior
                        # recovery row can carry a truthy NON-scalar
                        # order_id (a JSON list or object), which
                        # `in _fresh_order_ids` -- a set -- raised
                        # TypeError: unhashable type on, escaping
                        # this whole reinjection block entirely
                        # after run_once() had already replaced the
                        # prior run_state.json, with no chance to
                        # reach the durable sidecar fallback below
                        # (Codex review: "Fail closed on malformed
                        # recovered order IDs"). An unusable id is
                        # treated as "does not match" rather than
                        # raising -- the row still gets reinjected,
                        # so the recovery evidence itself is not
                        # lost merely because the id it carries
                        # happens to be malformed.
                        _order_id_usable = _is_usable_reconciled_order_id(_order_id)
                        # Sanitized to `None`, not left as whatever malformed
                        # value the prior artifact carried: a truthy but
                        # unusable id (a JSON list/object, or a scalar
                        # sentinel like `True`/`-1`/`NaN`) reinjected verbatim
                        # would itself become the NEXT retry's own "prior
                        # recovered outcome", where the identical membership
                        # test raises the same way this pass just avoided --
                        # and since Python considers `True == 1`, an unfixed
                        # boolean sentinel could also falsely collide with a
                        # later run's genuine numeric `order_id=1` (Codex
                        # review, PR #1168: "Reject scalar sentinels while
                        # reinjecting recovery outcomes"). The row itself is
                        # still reinjected below -- only the unusable id is
                        # cleared -- so the recovery evidence is not lost,
                        # merely untrackable by id the way a genuinely
                        # id-less outcome already is.
                        if not _order_id_usable:
                            _outcome = {**_outcome, "order_id": None}
                            _order_id = None
                        # Compared via `_normalized_order_id`, matching how
                        # `_fresh_order_ids` above is now built from
                        # `_represented_order_ids_for_count`: a raw
                        # `_order_id` -- possibly a different SUPPORTED
                        # numeric encoding of an id already represented in
                        # `_fresh_order_ids` (`123` vs `"123.0"`) -- must
                        # normalize the same way to actually match.
                        elif _order_id is not None and _normalized_order_id(_order_id) in _fresh_order_ids:
                            continue
                        # The surviving peer's OWN prior candidate row for this
                        # exact ticker -- still "not_submitted" from before this
                        # reinjection -- is resolved (dropped) before the new
                        # row is appended, not left standing beside it. Without
                        # this, a peer that had already contract-stamped a
                        # positive not_submitted candidate for this ticker kept
                        # that stale unplaced row in buy_candidates even after
                        # this invocation's own successful retry reinjected the
                        # real submitted order for the SAME ticker: the
                        # scheduled contract evaluates every positive candidate
                        # independently, so the old row alone kept the merged
                        # state compute-only/partial and its
                        # artifact_contract_failure/status="blocked" markers
                        # never got revalidated, rejecting the only canonical
                        # state even though it now also contains the real order
                        # (Codex review: "Resolve the peer candidate when
                        # folding its successful retry").
                        _reinject_ticker = _outcome.get("ticker", _key)
                        if isinstance(_reinject_ticker, str) and _reinject_ticker:
                            _fresh_candidates[:] = [
                                _row
                                for _row in _fresh_candidates
                                if not (
                                    isinstance(_row, dict)
                                    and _row.get("ticker") == _reinject_ticker
                                    and _row.get("status") == "not_submitted"
                                )
                            ]
                        _fresh_candidates.append(_failure_candidate_row(_key, _outcome))
                        # The synthetic "<ticker>#imart-recovery" key is not
                        # guaranteed free in _fresh_broker_outcomes: THIS run's
                        # own recovery-publish loop can independently recover a
                        # DIFFERENT pending order for the same ticker under that
                        # identical key. Overwriting it with the OLDER prior
                        # outcome would silently drop the current run's own
                        # recovery from submitted_orders.csv (regenerated from
                        # broker_outcomes just below) even though both rows
                        # remain in buy_candidates (Codex review: "Keep distinct
                        # recovery outcomes when reinjecting retries"). Falls
                        # back to an order-id-suffixed key on collision, mirroring
                        # _write_afternoon_failure_artifacts's own
                        # same-ticker-second-order handling.
                        _outcome_key = _key
                        if _outcome_key in _fresh_broker_outcomes:
                            _outcome_key = f"{_key}:{_order_id}"
                        _fresh_broker_outcomes[_outcome_key] = _outcome
                        if _order_id_usable:
                            _fresh_order_ids.add(_order_id)
                        _added_recovered = True
                    if _added_recovered:
                        _fresh_state["buy_candidates"] = _fresh_candidates
                        _fresh_state["broker_outcomes"] = _fresh_broker_outcomes
                        # A truthy but non-scalar order_id (the
                        # same malformed shape guarded against
                        # above) would otherwise raise TypeError:
                        # unhashable type building this set too --
                        # falls back to the ticker-keyed identity
                        # the same way a missing order_id already
                        # does (Codex review: "Fail closed on
                        # malformed recovered order IDs").
                        _fresh_state["orders_submitted_count"] = len(
                            {
                                row.get("order_id")
                                if _is_usable_reconciled_order_id(row.get("order_id"))
                                else f"ticker:{row.get('ticker')}"
                                for row in _fresh_candidates
                                if row.get("status") in ("submitted", "filled")
                            }
                        )
                        # counts.buy_candidates and the usage-proxy's
                        # buy_candidates_written/orders_placed_count all derive
                        # from the SAME buy_candidates/broker_outcomes
                        # collections that just grew -- leaving them at their
                        # pre-reinjection values understated the regenerated
                        # run_summary.json's own copy of these counts too
                        # (Codex review: "Refresh all derived counts after
                        # reinjection").
                        # Derived from _fresh_candidates -- the complete,
                        # de-duplicated buy_candidates set this whole block
                        # just finished building (ordinary placements this
                        # invocation's own run_once() already made, PLUS
                        # every reinjected row appended above) -- rather
                        # than from _fresh_broker_outcomes alone. An
                        # ORDINARY submitted candidate is never recorded in
                        # broker_outcomes (only recovery/reconciliation rows
                        # are); deriving these two counts purely from
                        # _fresh_broker_outcomes silently excluded a
                        # same-slot retry's own genuinely new, non-recovery
                        # order the moment ANY reinjection also happened in
                        # the same run, undercounting both `counts.submitted`
                        # and `usage_proxy.orders_placed_count` (Codex
                        # review: "Preserve fresh placements when
                        # reclassifying reinjected state").
                        #
                        # Aggregate-awareness (_submitted_orders_in_row --
                        # the same helper the normal artifact path already
                        # uses, so a whole-share aggregate outcome
                        # (merged_submission_count > 1) or a
                        # settlement-adjustment row (representing zero NEW
                        # submissions) is not flattened to exactly one order)
                        # is preserved by looking up each row's matching
                        # broker_outcomes entry via its order_id when one
                        # exists -- reinjected rows always have one, ordinary
                        # rows fall back to counting themselves as a single
                        # order, which is _submitted_orders_in_row's own
                        # default for a dict with no merge history (Codex
                        # review: "Preserve aggregate submission counts
                        # during reinjection").
                        # Keeps the ORIGINAL mapping key alongside each
                        # outcome, not just the outcome dict alone: a
                        # recovery outcome can legitimately omit its own
                        # "ticker" field and rely on this key for the
                        # symbol instead (e.g. a "<ticker>#imart-recovery"
                        # key) -- the exact fallback _failure_candidate_row()
                        # already uses when building the buy_candidates row
                        # itself. Losing the key here would leave nothing
                        # to fall back to when reproducing that same lookup
                        # below.
                        _fresh_broker_outcomes_by_order_id = {
                            _oc.get("order_id"): (_oc_key, _oc)
                            for _oc_key, _oc in _fresh_broker_outcomes.items()
                            if isinstance(_oc, dict) and _is_usable_reconciled_order_id(_oc.get("order_id"))
                        }
                        # ONE combined outcome-shaped mapping, keyed uniquely per
                        # row, built from the complete _fresh_candidates set --
                        # reused below for every consumer that used to read
                        # _fresh_broker_outcomes alone (order counts,
                        # _apply_no_order_classification, submitted_orders.csv).
                        # A reinjected row's matching broker_outcomes entry is
                        # preferred (it carries the recovery markers and
                        # aggregate-submission metadata _apply_no_order_
                        # classification/_submitted_orders_in_row need); an
                        # ordinary row -- never present in broker_outcomes --
                        # falls back to itself, normalized so
                        # "submitted_amount_usd" (the field every one of these
                        # consumers reads the amount under) is populated from
                        # its native "planned_amount_usd" rather than left
                        # absent (Codex review: "Reclassify reinjected runs
                        # from every submitted candidate" -- building
                        # classification and the canonical order CSV from
                        # _fresh_broker_outcomes alone excluded this same-run's
                        # own ordinary submitted candidates the moment ANY
                        # reinjection also happened, the same gap the nested
                        # counts above were already fixed for).
                        # Keyed purely by row INDEX, never by order_id: two
                        # rows could otherwise coincidentally share an
                        # order_id (a malformed/duplicate one), silently
                        # collapsing this mapping to fewer entries than
                        # _fresh_candidates has and reproducing the exact
                        # undercount this fix exists to close.
                        _fresh_outcomes_for_classification: Dict[str, Any] = {}
                        for _fresh_row_index, _fresh_row in enumerate(_fresh_candidates):
                            _fresh_row_order_id = _fresh_row.get("order_id")
                            _fresh_matching_entry = (
                                _fresh_broker_outcomes_by_order_id.get(_fresh_row_order_id)
                                if _is_usable_reconciled_order_id(_fresh_row_order_id)
                                else None
                            )
                            if _fresh_matching_entry is not None:
                                # A reinjected recovery outcome can
                                # legitimately omit its own "ticker" and
                                # rely on its broker_outcomes MAPPING KEY
                                # for the symbol instead (e.g. a
                                # "<ticker>#imart-recovery" key) -- a shape
                                # both _failure_candidate_row() and
                                # submitted_order_rows() explicitly support
                                # via `outcome.get("ticker") or key`.
                                # Keying THIS mapping by row index instead
                                # of the original outcome key (needed to
                                # stay collision-free -- see above) would
                                # drop that fallback if the candidate ROW's
                                # own "ticker" were trusted instead: a row
                                # rebuilt by _failure_candidate_row() from
                                # such a ticker-less outcome carries the
                                # RAW mapping key there too (that builder's
                                # own `outcome.get("ticker", ticker)`
                                # fallback, where `ticker` is the key it
                                # was called with) -- not the clean symbol
                                # -- so copying the row's "ticker" back
                                # would merely round-trip the same
                                # synthetic key string. Reproducing
                                # `outcome.get("ticker") or key` directly
                                # against the ORIGINAL broker_outcomes key
                                # is the only way to recover the real
                                # symbol (Codex review: "Retain ticker keys
                                # when rebuilding submitted orders").
                                _fresh_matching_key, _fresh_matching_outcome = _fresh_matching_entry
                                _fresh_matching_outcome_with_ticker = dict(_fresh_matching_outcome)
                                # `.get("ticker", key)`, not `.setdefault`:
                                # matches _failure_candidate_row()'s own
                                # `outcome.get("ticker", ticker)` fallback
                                # exactly -- substitutes only when the
                                # "ticker" key is absent, same as that
                                # builder does.
                                _fresh_matching_outcome_with_ticker["ticker"] = _fresh_matching_outcome.get(
                                    "ticker", _fresh_matching_key
                                )
                                _fresh_outcomes_for_classification[f"idx:{_fresh_row_index}"] = (
                                    _fresh_matching_outcome_with_ticker
                                )
                            else:
                                _fresh_normalized_row = dict(_fresh_row)
                                _fresh_normalized_row.setdefault(
                                    "submitted_amount_usd", _fresh_row.get("planned_amount_usd")
                                )
                                _fresh_outcomes_for_classification[f"idx:{_fresh_row_index}"] = (
                                    _fresh_normalized_row
                                )
                        # Grouped via `_grouped_submission_rows_by_represented_
                        # order` BEFORE summing, not summed independently per
                        # row: two fresh/reinjected aggregates representing
                        # {A, B} and {B, C} (each with merged_submission_count
                        # 2) overlap on "B", so summing their counts
                        # independently reported 4 submissions for the 3
                        # physical orders {A, B, C} their union actually
                        # represents, inflating `counts.submitted` and the
                        # usage-proxy's own order count (Codex review, PR
                        # #1169: "Apply overlap grouping before summing
                        # submission counts").
                        _fresh_qualifying_outcomes = [
                            _outcome
                            for _row, _outcome in zip(
                                _fresh_candidates, _fresh_outcomes_for_classification.values(), strict=True
                            )
                            if _row.get("status") in ("submitted", "filled")
                        ]
                        _fresh_aggregate_submitted_count = sum(
                            _submitted_orders_in_row(_grouped_row)
                            for _grouped_row in _grouped_submission_rows_by_represented_order(
                                _fresh_qualifying_outcomes, ticker_prefix="ticker:"
                            )
                        )
                        # A non-mapping "counts" (the same shape of
                        # corruption/legacy-format risk as
                        # "broker_outcomes" above) made `**(... or {})`
                        # raise TypeError -- "argument after ** must be a
                        # mapping" -- for the identical reason: a truthy
                        # non-dict value is not falsy, so `or {}` never
                        # substitutes the safe default (Codex review:
                        # "Normalize malformed counts before
                        # reinjection"). Normalized the same way
                        # "broker_outcomes" already is above.
                        _fresh_counts_raw = _fresh_state.get("counts")
                        _fresh_state["counts"] = {
                            **(_fresh_counts_raw if isinstance(_fresh_counts_raw, dict) else {}),
                            "submitted": _fresh_aggregate_submitted_count,
                            "buy_candidates": len(_fresh_candidates),
                        }
                        # "filled", not just ("submitted", "dry_run"): a
                        # reinjected recovery outcome can already carry a
                        # proven fill. counts.submitted just above (via
                        # _fresh_aggregate_submitted_count) already counts
                        # "filled" rows; excluding them here left
                        # usage_proxy.orders_placed_count undercounting the
                        # SAME reinjected placements dca_cost_tracker.py's
                        # order-execution usage tier reads, disagreeing with
                        # the canonical state's own submitted count (Codex
                        # review: "Include filled recoveries in placed-order
                        # usage").
                        # Grouped before summing here too, for the identical
                        # overlap-counting reason as `counts.submitted` above
                        # -- this filter (order_id present; status includes
                        # "dry_run") is its own distinct set of rows, not a
                        # subset of `_fresh_qualifying_outcomes`, so it needs
                        # its own grouping pass rather than reusing that sum.
                        _fresh_placed_outcomes = [
                            _outcome
                            for _row, _outcome in zip(
                                _fresh_candidates, _fresh_outcomes_for_classification.values(), strict=True
                            )
                            if _row.get("order_id") and _row.get("status") in {"submitted", "filled", "dry_run"}
                        ]
                        _fresh_orders_placed_count = sum(
                            _submitted_orders_in_row(_grouped_row)
                            for _grouped_row in _grouped_submission_rows_by_represented_order(
                                _fresh_placed_outcomes, ticker_prefix="ticker:"
                            )
                        )
                        _fresh_usage = _fresh_state.get("usage_proxy")
                        if isinstance(_fresh_usage, dict):
                            _fresh_usage["buy_candidates_written"] = len(_fresh_candidates)
                            _fresh_usage["orders_placed_count"] = _fresh_orders_placed_count
                        # `_added_recovered` only means a prior outcome was
                        # reinjected -- it does NOT mean that outcome was a
                        # submitted order. A reconciled REJECTION
                        # (`reconciled_fractional_placement=true`,
                        # `status="failed"`) is included in
                        # `_prior_recovered_outcomes` too (see the comment
                        # above this loop), so unconditionally stamping
                        # `order_submit_status` here reported a run that
                        # placed nothing as "submitted" while
                        # `orders_submitted_count`/`usage_proxy.orders_placed_
                        # count` both stayed zero, and
                        # `_apply_no_order_classification` below never clears
                        # an already-concrete `order_submit_status`, only a
                        # stale NO-order classification. Gate this on the
                        # SAME `orders_submitted_count` just computed above
                        # from the merged buy_candidates, so the status only
                        # flips to "submitted" when a reinjected outcome
                        # actually was one (Codex review, PR #911 round 36:
                        # "Do not mark reinjected rejections as submitted").
                        if _fresh_state["orders_submitted_count"] > 0:
                            _fresh_state["order_submit_status"] = ORDER_SUBMIT_STATUS_SUBMITTED
                        # run_once() already stamped a no-order classification
                        # (run_classification_outcome="completed_no_orders",
                        # a completion_reason, etc.) onto _fresh_state BEFORE this
                        # block could learn the retry actually submitted the
                        # recovered order. _apply_no_order_classification only
                        # ever ADDS/overwrites these fields for a batch that is
                        # STILL empty when it runs; it never clears a stale
                        # no-order marker once orders_submitted_count turns
                        # positive, so a run can end up simultaneously reported as
                        # submitted (order_submit_status just above) and
                        # completed-with-no-orders (Codex review: "Recompute
                        # classification after reinjecting submissions"). Cleared
                        # first so the recompute below starts clean -- the
                        # function re-derives every one of these from the merged
                        # outcomes, including re-setting is_trading_failure/
                        # error_class if a genuine failure is still present among
                        # them.
                        for _stale_key in (
                            "run_classification_outcome",
                            "completion_reason",
                            "is_trading_failure",
                            "error_class",
                            "orders_failed_count",
                        ):
                            _fresh_state.pop(_stale_key, None)
                        _apply_no_order_classification(
                            _fresh_state, _fresh_outcomes_for_classification, scheduled=options.scheduled
                        )
                        atomic_write_text(out / "run_state.json", _serialize_run_state(_fresh_state))
                        # run_once() already generated buy_candidates.csv,
                        # submitted_orders.csv, and run_summary.json from the
                        # PRE-reinjection state -- rewriting only run_state.json
                        # above left those three companions contradicting it: a
                        # risk reader of run_state.json counts the recovered
                        # order, while a CSV/report reader of the untouched
                        # companions does not see it at all (Codex review:
                        # "Rebuild companion artifacts after reinjecting
                        # recoveries"). Regenerated from the SAME updated state
                        # so the whole artifact set agrees.
                        try:  # pragma: no cover - import shim for flat sys.path
                            from scripts.scheduled_artifacts import (
                                build_run_summary,
                                submitted_order_rows,
                                write_submitted_orders_csv,
                            )
                        except ModuleNotFoundError as _import_exc:  # pragma: no cover
                            # Only a failure to resolve the "scripts"
                            # package itself means package-style import
                            # doesn't apply and the flat, run-from-
                            # scripts/ style is needed instead. A
                            # ModuleNotFoundError for anything else (a
                            # real missing dependency inside
                            # scheduled_artifacts.py's OWN imports)
                            # must not be silently reinterpreted as
                            # "package layout doesn't resolve" and
                            # retried through a duplicate module
                            # instance under a different import path
                            # (Codex review: "Narrow the reinjection
                            # import fallback"; AGENTS.md: "Do not
                            # wrap imports in broad try/except
                            # blocks").
                            if _import_exc.name not in (
                                "scripts", "scripts.scheduled_artifacts",
                            ):
                                raise
                            from scheduled_artifacts import (  # type: ignore
                                build_run_summary,
                                submitted_order_rows,
                                write_submitted_orders_csv,
                            )
                        # A plain _write_csv(rows) derives its header from row[0]
                        # alone -- fine when every row comes from the same
                        # builder, but _fresh_candidates mixes run_once()'s own
                        # _build_buy_candidates rows with a _failure_candidate_row
                        # shape that does not necessarily carry identical keys.
                        # csv.DictWriter's default extrasaction="raise" would
                        # crash on the first field-set mismatch (the same class
                        # of bug _merge_execution_csv's own extrasaction="ignore"
                        # already guards against for orders.csv), so build the
                        # union of every row's keys and ignore the rest.
                        _candidate_fieldnames: List[str] = []
                        _seen_candidate_fields: set[str] = set()
                        for _row in _fresh_candidates:
                            for _field in _row.keys():
                                if _field not in _seen_candidate_fields:
                                    _seen_candidate_fields.add(_field)
                                    _candidate_fieldnames.append(_field)
                        with atomic_open_w(out / "buy_candidates.csv", newline="") as _handle:
                            _writer = csv.DictWriter(
                                _handle, fieldnames=_candidate_fieldnames or ["ticker"], extrasaction="ignore"
                            )
                            _writer.writeheader()
                            _writer.writerows(_fresh_candidates)
                        write_submitted_orders_csv(
                            out, submitted_order_rows(_fresh_outcomes_for_classification)
                        )
                        atomic_write_text(
                            out / "run_summary.json",
                            _serialize_run_state(build_run_summary(_fresh_state)),
                        )

                # Merges with (rather than overwrites) any existing orders.csv
                # when EITHER of two signals proves the pre-existing state
                # belongs to the SAME scheduled slot -- a genuine retry, so a
                # crash-lease recovery's execution row an EARLIER, failed
                # attempt at this slot already persisted via
                # _write_afternoon_failure_artifacts survives (that
                # recovery's lease is already cleared, so nothing will ever
                # re-produce the row again once it's gone -- Codex review:
                # "Preserve recovered fills through successful retries").
                # `_orders_csv_same_run` alone (computed before run_once()
                # could touch run_state.json) missed one case: two FIRST
                # invocations of the identical slot racing each other both
                # start with no prior state at all (`_orders_csv_same_run`
                # False for both), so whichever reaches this point second
                # still saw `replace_existing=True` and deleted the first
                # one's already-published, equally legitimate execution rows
                # -- despite `_fresh_state_is_own` above having just proven
                # the current on-disk state (written by that OTHER,
                # concurrent invocation) genuinely shares this identity
                # (Codex review: "Recompute replacement intent after
                # acquiring the lock"). `_concurrent_writer_confirmed`
                # (computed above, before the reinjection block, which also
                # uses it to fold this invocation's own placements into the
                # surviving peer's run_state.json) closes that gap: True
                # only when the run_state.json just read differs from the
                # exact bytes THIS invocation's OWN run_once() call wrote --
                # proof some OTHER writer touched this same-identity
                # directory since, so its orders.csv (if any) is that
                # writer's legitimate row, not a stale leftover. Otherwise
                # -- no prior state and no confirmed concurrent writer, or
                # artifacts_dir reused for an unrelated trading day --
                # replace rather than merge, so an unrelated run's stale
                # rows are never kept and misattributed to this one (Codex
                # review: "Merge executions only when retrying the same
                # run"). always_write keeps write_execution_csv's prior
                # unconditional-create contract: this call still always
                # produces a (possibly header-only) orders.csv, unlike the
                # failure writer's own no-op-when-empty default. Still
                # inside the SAME lock ownership was just verified under:
                # releasing it here and reacquiring for a separate write
                # would reopen exactly the TOCTOU gap this unified critical
                # section exists to close (Codex review: "Require verified
                # ownership before merging executions").
                _merge_execution_csv(
                    orders_csv,
                    run_result.execution_records,
                    replace_existing=not (_orders_csv_same_run or _concurrent_writer_confirmed),
                    always_write=True,
                )
                # The lock-acquiring wrapper would try to reacquire this SAME
                # run_state.json.lock and simply time out against the one
                # already held here -- flock is per-open-file-description,
                # not reentrant within a process -- so this calls the
                # already-locked variant directly (Codex review: "Require
                # verified ownership before merging executions").
                _backfill_orders_csv_usage_locked(out / "run_state.json")
                result.update(
                    signals_path=str(out / "signals.csv"),
                    buy_candidates_path=str(out / "buy_candidates.csv"),
                    orders_csv_path=str(orders_csv),
                )
            break
        except (TimeoutError, OSError) as _reinjection_lock_exc:
            # Widened from TimeoutError alone to also contain a
            # plain OSError from cross_process_lock() itself (the
            # sidecar cannot be created or opened -- transient
            # filesystem error, descriptor exhaustion,
            # permissions), matching the identical fix already
            # applied to the other lock-guarded passes in this
            # module (Codex review: "Preserve recoveries when lock
            # setup raises OSError"). run_once() has already
            # replaced the prior state by this point, so either
            # exception must still route through the same
            # durable-sidecar fallback below rather than escaping.
            _reinjection_attempts_remaining -= 1
            if _reinjection_attempts_remaining <= 0:
                logger.error(
                    "could not verify run_state.json ownership / reinject "
                    "recovered candidates %s at %s after repeated lock "
                    "failures (%s); failing closed -- orders.csv/usage "
                    "backfill skipped, evidence sidecar'd for manual "
                    "reconciliation",
                    sorted(_prior_recovered_outcomes),
                    out / "run_state.json",
                    _reinjection_lock_exc,
                )
                # Durably preserved in its own file rather than lost
                # outright: run_once() already replaced run_state.json
                # with fresh state that never saw this recovery, so
                # there is no further chance to reinject it THIS run
                # (Codex review: "Fail finalization when recovery
                # reinjection is exhausted") -- see
                # `_persist_undurable_evidence_sidecar`'s own
                # docstring for why this is a discoverable sidecar
                # rather than a raise (which would misreport a run
                # that may have already placed real orders as a hard
                # failure) or a further-extended retry. Repeated lock
                # contention/failure means ownership could not be
                # PROVEN either, so this invocation's own new
                # placements are preserved the same way a confirmed
                # foreign claim already is -- unable to verify is
                # treated as unable to trust, never as "proceed
                # anyway" (Codex review: "Require verified ownership
                # before merging executions").
                _directory_claimed_by_foreign_run = True
                if _prior_recovered_outcomes:
                    # See the matching comment in
                    # _write_afternoon_failure_artifacts: the same
                    # non-reversible account fingerprint
                    # _persist_cross_account_unresolved_evidence
                    # already stamps, so a shared artifact directory
                    # later reused under a different configured
                    # account can still be reconciled by hand (Codex
                    # review: "Bind fallback placement evidence to its
                    # broker account").
                    _reinjection_account_fingerprint = (
                        _account_number_for_unresolved_evidence(broker, Path(out).parent)
                        if broker is not None
                        else None
                    )
                    _persist_undurable_evidence_sidecar(
                        out,
                        "unreinjected_recovered_placement",
                        datetime.now(timezone.utc),
                        {
                            "broker_outcomes": _prior_recovered_outcomes,
                            "account_fingerprint": _reinjection_account_fingerprint,
                        },
                    )
                _persist_foreign_directory_execution_sidecar(
                    out, datetime.now(timezone.utc), run_result.execution_records, broker
                )
                break
            continue

    # Propagated to the caller (run_dca._run_pipeline_impl), not just used
    # internally: a `False` here means run_state_path currently holds a
    # DIFFERENT invocation's (or account's) state, never this one's own --
    # `blocked=False` alone does not say that, so a caller that only checks
    # `blocked` before doing its own post-processing (refreshing the raw-
    # input manifest, persisting preflight_gate, merging raw placement
    # responses) would keep treating that foreign path as its own output
    # and corrupt it the same way this function's own unified critical
    # section exists to prevent (Codex review: "Propagate foreign ownership
    # to the outer pipeline").
    result["directory_ownership_verified"] = not _directory_claimed_by_foreign_run
    return result


if __name__ == "__main__":
    raise SystemExit(
        "near_close_dca is the strategy library, not a runnable entry point. "
        "Run the orchestrator instead: `python run_dca.py --demo` for a local dry-run, "
        "or drive a live/scheduled run via run_dca.run_pipeline() with providers/broker "
        "built from dca_live_adapters (wire Robinhood MCP callables). Live placement stays "
        "gated behind StrategyConfig.dry_run and the adapter's enable_live_orders flag."
    )
